TEST_CASE("almetal: drawable presentation converts GL rows and covers its underlay", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);

        auto library = ALMetalShaderLibrary::loadBuiltin(*device, &error);
        INFO(error);
        REQUIRE(library);
        REQUIRE(library->hasFunction("almetal_present_gl_rows_fragment"));

        ALMetalRenderPipelineDescriptor pipeline_descriptor;
        pipeline_descriptor.library = library.get();
        pipeline_descriptor.vertex_function = "almetal_resample_vertex";
        pipeline_descriptor.fragment_function =
            "almetal_present_gl_rows_fragment";
        pipeline_descriptor.colors[0].format =
            ALMetalPixelFormat::bgra8_unorm;
        pipeline_descriptor.label =
            "Alchemy retained GL-row presentation regression pipeline";
        auto pipeline = ALMetalRenderPipeline::create(
            *device, pipeline_descriptor, &error);
        INFO(error);
        REQUIRE(pipeline);

        ALMetalSamplerDescriptor sampler_descriptor;
        sampler_descriptor.min_filter = ALMetalSamplerFilter::nearest;
        sampler_descriptor.mag_filter = ALMetalSamplerFilter::nearest;
        sampler_descriptor.mip_filter = ALMetalSamplerMipFilter::none;
        sampler_descriptor.address_s =
            ALMetalSamplerAddressMode::clamp_to_edge;
        sampler_descriptor.address_t =
            ALMetalSamplerAddressMode::clamp_to_edge;
        sampler_descriptor.address_r =
            ALMetalSamplerAddressMode::clamp_to_edge;
        sampler_descriptor.label =
            "Alchemy retained GL-row presentation regression sampler";
        auto sampler = ALMetalSamplerState::create(
            *device, sampler_descriptor, &error);
        INFO(error);
        REQUIRE(sampler);

        ALMetalTextureDescriptor source_descriptor;
        source_descriptor.format = ALMetalPixelFormat::bgra8_unorm;
        source_descriptor.width = 2;
        source_descriptor.height = 2;
        source_descriptor.storage = ALMetalStorageMode::private_gpu;
        source_descriptor.usage = ALMetalTextureUsage::shader_read;
        source_descriptor.label =
            "Alchemy retained GL-row presentation regression source";
        auto source = ALMetalTexture::create(
            *device, source_descriptor, &error);
        INFO(error);
        REQUIRE(source);

        ALMetalRenderTargetDescriptor target_descriptor;
        target_descriptor.width = 2;
        target_descriptor.height = 2;
        target_descriptor.color_attachment_count = 1;
        target_descriptor.colors[0].format =
            ALMetalPixelFormat::bgra8_unorm;
        target_descriptor.colors[0].shader_read = true;
        target_descriptor.colors[0].label =
            "Alchemy retained GL-row presentation regression color";
        target_descriptor.label =
            "Alchemy retained GL-row presentation regression target";
        auto target = ALMetalRenderTarget::create(
            *device, target_descriptor, &error);
        INFO(error);
        REQUIRE(target);

        // Raw row zero is the GL lower row. Distinct pixels in both axes
        // prove that the drawable conversion reverses Y without mirroring X.
        // Deliberately non-opaque source alpha proves the published drawable
        // cannot reveal a frozen GL loading/world frame beneath it.
        constexpr std::array<std::uint8_t, 16> source_pixels{{
            11, 12, 13, 0, 21, 22, 23, 64,
            31, 32, 33, 128, 41, 42, 43, 192,
        }};
        constexpr std::array<std::uint8_t, 16> expected_pixels{{
            31, 32, 33, 255, 41, 42, 43, 255,
            11, 12, 13, 255, 21, 22, 23, 255,
        }};
        auto command = device->makeCommandBuffer(
            "Alchemy retained GL-row presentation regression", &error);
        INFO(error);
        REQUIRE(command);
        REQUIRE(source->upload(
            *command, 0, 0, {}, source_pixels.data(), 8, &error));

        ALMetalRenderPassConfig pass_config;
        auto pass = target->makeRenderPass(pass_config, &error);
        INFO(error);
        REQUIRE(pass);
        auto encoder = ALMetalRenderEncoder::begin(
            *command, *pass,
            "Alchemy retained GL-row presentation regression encoder",
            &error);
        INFO(error);
        REQUIRE(encoder);
        const ALMetalViewport viewport{0.0, 0.0, 2.0, 2.0, 0.0, 1.0};
        const ALMetalScissorRect scissor{0, 0, 2, 2};
        REQUIRE(encoder->setPipeline(*pipeline, &error));
        REQUIRE(encoder->setFragmentTexture(0, source.get(), &error));
        REQUIRE(encoder->setFragmentSampler(0, sampler.get(), &error));
        REQUIRE(encoder->setViewport(viewport, &error));
        REQUIRE(encoder->setScissor(scissor, &error));
        REQUIRE(encoder->setCullMode(ALMetalCullMode::none, &error));
        REQUIRE(encoder->draw(
            ALMetalPrimitiveType::triangle, 0, 3, 1, &error));
        REQUIRE(encoder->end(&error));
        REQUIRE(command->commitAndWait(&error));
        INFO(error);

        std::array<std::uint8_t, 16> presented{};
        REQUIRE(target->colorTexture(0)->readback(
            *device, 0, 0, {}, presented.data(), 8, &error));
        INFO(error);
        CHECK(presented == expected_pixels);
    }
}

TEST_CASE("almetal: a blit command copies shared storage and reports completion", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        ALMetalDevice::setCommandTimingEnabled(false);
        CHECK_FALSE(ALMetalDevice::commandTimingEnabled());
        REQUIRE(device->waitUntilIdle(&error));
        INFO(error);
        const ALMetalCommandTiming timing_before =
            ALMetalDevice::commandTiming();

        constexpr std::size_t size = 4096;
        std::array<std::uint8_t, size> expected{};
        for (std::size_t i = 0; i < expected.size(); ++i)
        {
            expected[i] = static_cast<std::uint8_t>((i * 131u + 17u) & 0xffu);
        }

        id<MTLBuffer> source = [nativeDevice(*device)
            newBufferWithBytes:expected.data()
                      length:expected.size()
                     options:MTLResourceStorageModeShared];
        id<MTLBuffer> destination = [nativeDevice(*device)
            newBufferWithLength:expected.size()
                         options:MTLResourceStorageModeShared];
        REQUIRE(source);
        REQUIRE(destination);
        std::memset(destination.contents, 0, size);

        auto command = device->makeCommandBuffer("Alchemy Metal blit test", &error);
        INFO(error);
        REQUIRE(command);
        id<MTLBlitCommandEncoder> encoder = [nativeCommand(*command) blitCommandEncoder];
        REQUIRE(encoder);
        [encoder copyFromBuffer:source
                   sourceOffset:0
                       toBuffer:destination
              destinationOffset:0
                           size:size];
        [encoder endEncoding];

        const std::uint64_t commits_before =
            ALMetalDevice::committedCommandBufferCount();
        ALMetalDevice::setCommandTimingEnabled(true);
        CHECK(ALMetalDevice::commandTimingEnabled());
        const bool committed = command->commitAndWait(&error);
        ALMetalDevice::setCommandTimingEnabled(false);
        CHECK_FALSE(ALMetalDevice::commandTimingEnabled());
        CHECK(committed);
        INFO(error);
        CHECK(ALMetalDevice::committedCommandBufferCount() ==
              commits_before + 1);
        REQUIRE(device->waitUntilIdle(&error));
        INFO(error);
        const ALMetalCommandTiming timing_after =
            ALMetalDevice::commandTiming();
        CHECK(timing_after.submitted == timing_before.submitted + 1);
        CHECK(timing_after.completed == timing_before.completed + 1);
        CHECK(timing_after.timed == timing_before.timed + 1);
        CHECK(timing_after.gpu_time_nanoseconds >
              timing_before.gpu_time_nanoseconds);
        CHECK(command->status() == ALMetalCommandStatus::completed);
        CHECK(std::memcmp(destination.contents, expected.data(), size) == 0);
    }
}

TEST_CASE("almetal: a render pass clears a texture and CPU readback observes it", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);

        MTLTextureDescriptor* description = [MTLTextureDescriptor
            texture2DDescriptorWithPixelFormat:MTLPixelFormatBGRA8Unorm
                                      width:8
                                     height:8
                                  mipmapped:NO];
        description.storageMode = MTLStorageModeShared;
        description.usage = MTLTextureUsageRenderTarget;
        id<MTLTexture> texture = [nativeDevice(*device) newTextureWithDescriptor:description];
        REQUIRE(texture);

        auto command = device->makeCommandBuffer("Alchemy Metal clear/readback test", &error);
        INFO(error);
        REQUIRE(command);
        MTLRenderPassDescriptor* pass = [MTLRenderPassDescriptor renderPassDescriptor];
        pass.colorAttachments[0].texture = texture;
        pass.colorAttachments[0].loadAction = MTLLoadActionClear;
        pass.colorAttachments[0].storeAction = MTLStoreActionStore;
        pass.colorAttachments[0].clearColor = MTLClearColorMake(0.25, 0.5, 0.75, 1.0);
        id<MTLRenderCommandEncoder> encoder = [nativeCommand(*command) renderCommandEncoderWithDescriptor:pass];
        REQUIRE(encoder);
        [encoder endEncoding];
        CHECK(command->commitAndWait(&error));
        INFO(error);

        std::array<std::uint8_t, 8 * 8 * 4> pixels{};
        [texture getBytes:pixels.data()
              bytesPerRow:8 * 4
               fromRegion:MTLRegionMake2D(0, 0, 8, 8)
              mipmapLevel:0];
        // BGRA storage for the requested (R,G,B,A) clear, with one LSB of
        // tolerance for the implementation's UNORM rounding mode.
        CHECK(std::abs(static_cast<int>(pixels[0]) - 191) <= 1);
        CHECK(std::abs(static_cast<int>(pixels[1]) - 128) <= 1);
        CHECK(std::abs(static_cast<int>(pixels[2]) - 64) <= 1);
        CHECK(pixels[3] == 255);
    }
}

TEST_CASE("almetal: typed shared and private buffers preserve staged ranges", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);

        ALMetalBufferDescriptor shared_descriptor;
        shared_descriptor.length = 256;
        shared_descriptor.storage = ALMetalStorageMode::shared;
        shared_descriptor.label = "Alchemy shared buffer test";
        auto shared = ALMetalBuffer::create(*device, shared_descriptor, &error);
        INFO(error);
        REQUIRE(shared);
        REQUIRE(shared->mappedBytes());

        std::array<std::uint8_t, 31> small_source{};
        for (std::size_t i = 0; i < small_source.size(); ++i)
        {
            small_source[i] = static_cast<std::uint8_t>(i * 7u + 3u);
        }
        REQUIRE(shared->write(17, small_source.data(), small_source.size(), &error));
        std::array<std::uint8_t, 31> small_result{};
        REQUIRE(shared->read(17, small_result.data(), small_result.size(), &error));
        CHECK(small_result == small_source);

        ALMetalBufferDescriptor private_descriptor;
        private_descriptor.length = 8192;
        private_descriptor.storage = ALMetalStorageMode::private_gpu;
        private_descriptor.label = "Alchemy private buffer test";
        auto private_buffer = ALMetalBuffer::create(*device, private_descriptor, &error);
        INFO(error);
        REQUIRE(private_buffer);
        CHECK(private_buffer->mappedBytes() == nullptr);

        std::array<std::uint8_t, 1024> source{};
        for (std::size_t i = 0; i < source.size(); ++i)
        {
            source[i] = static_cast<std::uint8_t>((i * 29u + 11u) & 0xffu);
        }
        auto upload = device->makeCommandBuffer("Alchemy private buffer upload", &error);
        INFO(error);
        REQUIRE(upload);
        REQUIRE(private_buffer->upload(*upload, 257, source.data(), source.size(), &error));
        REQUIRE(upload->commitAndWait(&error));
        INFO(error);

        std::array<std::uint8_t, 1024> result{};
        REQUIRE(private_buffer->readback(*device, 257, result.data(), result.size(), &error));
        INFO(error);
        CHECK(result == source);
        CHECK_FALSE(private_buffer->readback(*device, 8000, result.data(), result.size(), &error));
    }
}

TEST_CASE("almetal: private texture transfer handles unaligned CPU row pitches", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);

        constexpr std::uint32_t width = 17;
        constexpr std::uint32_t height = 9;
        constexpr std::size_t source_pitch = width * 4 + 12;
        constexpr std::size_t result_pitch = width * 4 + 20;
        std::vector<std::uint8_t> source(source_pitch * height, 0xcd);
        for (std::uint32_t y = 0; y < height; ++y)
        {
            for (std::uint32_t x = 0; x < width; ++x)
            {
                std::uint8_t* pixel = source.data() + y * source_pitch + x * 4;
                pixel[0] = static_cast<std::uint8_t>(x * 9u);
                pixel[1] = static_cast<std::uint8_t>(y * 17u);
                pixel[2] = static_cast<std::uint8_t>(x + y * 3u);
                pixel[3] = 255;
            }
        }

        ALMetalTextureDescriptor descriptor;
        descriptor.format = ALMetalPixelFormat::rgba8_unorm;
        descriptor.width = width;
        descriptor.height = height;
        descriptor.storage = ALMetalStorageMode::private_gpu;
        descriptor.usage = ALMetalTextureUsage::shader_read | ALMetalTextureUsage::shader_write;
        descriptor.label = "Alchemy odd-pitch private texture";
        auto texture = ALMetalTexture::create(*device, descriptor, &error);
        INFO(error);
        REQUIRE(texture);

        auto command = device->makeCommandBuffer("Alchemy private texture upload", &error);
        INFO(error);
        REQUIRE(command);
        REQUIRE(texture->upload(*command, 0, 0, {}, source.data(), source_pitch, &error));
        REQUIRE(command->commitAndWait(&error));
        INFO(error);

        std::vector<std::uint8_t> result(result_pitch * height, 0xee);
        REQUIRE(texture->readback(*device, 0, 0, {}, result.data(), result_pitch, &error));
        INFO(error);
        for (std::uint32_t y = 0; y < height; ++y)
        {
            CHECK(std::memcmp(result.data() + y * result_pitch,
                              source.data() + y * source_pitch,
                              width * 4) == 0);
            CHECK(result[y * result_pitch + width * 4] == 0xee);
        }

        // Final world/UI presentation is BGRA8, while the snapshot encoder's
        // LLImageRaw contract is RGB. Exercise a cropped, padded readback so
        // the production path cannot accidentally retain BGRA channel order
        // or assume a tightly packed destination.
        descriptor.format = ALMetalPixelFormat::bgra8_unorm;
        descriptor.label = "Alchemy odd-pitch BGRA snapshot texture";
        auto bgra_texture = ALMetalTexture::create(
            *device, descriptor, &error);
        INFO(error);
        REQUIRE(bgra_texture);
        auto bgra_upload = device->makeCommandBuffer(
            "Alchemy BGRA snapshot upload", &error);
        INFO(error);
        REQUIRE(bgra_upload);
        REQUIRE(bgra_texture->upload(
            *bgra_upload, 0, 0, {}, source.data(), source_pitch, &error));
        REQUIRE(bgra_upload->commitAndWait(&error));
        INFO(error);

        constexpr ALMetalRegion2D crop{3, 2, 7, 4};
        constexpr std::size_t rgb_pitch = crop.width * 3 + 5;
        std::vector<std::uint8_t> rgb(rgb_pitch * crop.height, 0xa5);
        REQUIRE(bgra_texture->readbackRGB8(
            *device, 0, 0, crop, rgb.data(), rgb_pitch, &error));
        INFO(error);
        for (std::uint32_t y = 0; y < crop.height; ++y)
        {
            for (std::uint32_t x = 0; x < crop.width; ++x)
            {
                const std::uint8_t* expected = source.data() +
                    (crop.y + y) * source_pitch + (crop.x + x) * 4;
                const std::uint8_t* actual = rgb.data() +
                    y * rgb_pitch + x * 3;
                CHECK(actual[0] == expected[2]);
                CHECK(actual[1] == expected[1]);
                CHECK(actual[2] == expected[0]);
            }
            CHECK(rgb[y * rgb_pitch + crop.width * 3] == 0xa5);
        }

        // A high-resolution snapshot places independently rendered subfields
        // into one LLImageRaw by passing each tile's destination pointer while
        // retaining the aggregate row pitch. Reproduce a 2x2 assembly here:
        // every read must stay inside its tile and preserve the padding at the
        // end of every aggregate row.
        constexpr std::uint32_t tile_width = 6;
        constexpr std::uint32_t tile_height = 4;
        constexpr std::uint32_t assembled_width = tile_width * 2;
        constexpr std::uint32_t assembled_height = tile_height * 2;
        constexpr std::size_t assembled_pitch = assembled_width * 3 + 5;
        std::vector<std::uint8_t> assembled(
            assembled_pitch * assembled_height, 0x5a);
        const std::array<ALMetalRegion2D, 4> tiles{
            ALMetalRegion2D{0, 0, tile_width, tile_height},
            ALMetalRegion2D{width - tile_width, 0,
                            tile_width, tile_height},
            ALMetalRegion2D{0, height - tile_height,
                            tile_width, tile_height},
            ALMetalRegion2D{width - tile_width,
                            height - tile_height,
                            tile_width, tile_height},
        };
        for (std::size_t tile = 0; tile < tiles.size(); ++tile)
        {
            const std::uint32_t destination_x =
                static_cast<std::uint32_t>(tile % 2) * tile_width;
            const std::uint32_t destination_y =
                static_cast<std::uint32_t>(tile / 2) * tile_height;
            REQUIRE(bgra_texture->readbackRGB8(
                *device, 0, 0, tiles[tile],
                assembled.data() + destination_y * assembled_pitch +
                    destination_x * 3,
                assembled_pitch, &error));
            INFO(error);
        }
        for (std::uint32_t y = 0; y < assembled_height; ++y)
        {
            const std::size_t tile_row = y / tile_height;
            const std::uint32_t source_y = tile_row == 0
                ? y : height - tile_height + (y % tile_height);
            for (std::uint32_t x = 0; x < assembled_width; ++x)
            {
                const std::size_t tile_column = x / tile_width;
                const std::uint32_t source_x = tile_column == 0
                    ? x : width - tile_width + (x % tile_width);
                const std::uint8_t* expected = source.data() +
                    source_y * source_pitch + source_x * 4;
                const std::uint8_t* actual = assembled.data() +
                    y * assembled_pitch + x * 3;
                CHECK(actual[0] == expected[2]);
                CHECK(actual[1] == expected[1]);
                CHECK(actual[2] == expected[0]);
            }
            CHECK(assembled[y * assembled_pitch + assembled_width * 3] ==
                  0x5a);
        }

        error.clear();
        CHECK_FALSE(bgra_texture->readbackRGB8(
            *device, 0, 0, crop, rgb.data(), crop.width * 3 - 1,
            &error));
        CHECK(error == "Metal RGB readback row pitch is too small");
    }
}

TEST_CASE("almetal: unorm volume-array upload preserves precision and expands RGB",
          "[almetal][texture]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);

        constexpr std::uint32_t edge = 2;
        std::array<std::uint8_t, edge * edge * edge * 3> rgb8{};
        for (std::size_t index = 0; index < rgb8.size(); ++index)
        {
            rgb8[index] = static_cast<std::uint8_t>(index * 7u + 3u);
        }
        auto rgba8 = alMetalCreateUnormVolumeArray(
            *device, edge, 3, 1, rgb8.data(), "Alchemy RGB8 volume test",
            &error);
        INFO(error);
        REQUIRE(rgba8);
        CHECK(rgba8->descriptor().type ==
              ALMetalTextureType::texture_2d_array);
        CHECK(rgba8->descriptor().format == ALMetalPixelFormat::rgba8_unorm);
        CHECK(rgba8->descriptor().width == edge);
        CHECK(rgba8->descriptor().height == edge);
        CHECK(rgba8->descriptor().array_length == edge);
        std::array<std::uint8_t, edge * edge * 4> slice8{};
        for (std::uint32_t slice = 0; slice < edge; ++slice)
        {
            REQUIRE(rgba8->readback(*device, 0, slice, {}, slice8.data(),
                                    edge * 4, &error));
            INFO(error);
            for (std::size_t texel = 0; texel < edge * edge; ++texel)
            {
                const std::size_t source =
                    (static_cast<std::size_t>(slice) * edge * edge + texel) *
                    3;
                const std::size_t destination = texel * 4;
                CHECK(slice8[destination] == rgb8[source]);
                CHECK(slice8[destination + 1] == rgb8[source + 1]);
                CHECK(slice8[destination + 2] == rgb8[source + 2]);
                CHECK(slice8[destination + 3] == 0xffu);
            }
        }

        std::array<std::uint16_t, edge * edge * edge * 4> rgba16_source{};
        for (std::size_t index = 0; index < rgba16_source.size(); ++index)
        {
            rgba16_source[index] = static_cast<std::uint16_t>(
                index * 1999u + 17u);
        }
        auto rgba16 = alMetalCreateUnormVolumeArray(
            *device, edge, 4, 2, rgba16_source.data(),
            "Alchemy RGBA16 volume test", &error);
        INFO(error);
        REQUIRE(rgba16);
        CHECK(rgba16->descriptor().format ==
              ALMetalPixelFormat::rgba16_unorm);
        std::array<std::uint16_t, edge * edge * 4> slice16{};
        for (std::uint32_t slice = 0; slice < edge; ++slice)
        {
            REQUIRE(rgba16->readback(
                *device, 0, slice, {}, slice16.data(),
                edge * 4 * sizeof(std::uint16_t), &error));
            INFO(error);
            const auto first = rgba16_source.begin() +
                static_cast<std::ptrdiff_t>(slice * edge * edge * 4);
            CHECK(std::equal(slice16.begin(), slice16.end(), first));
        }

        CHECK_FALSE(alMetalCreateUnormVolumeArray(
            *device, 0, 4, 1, rgb8.data(), "invalid", &error));
        CHECK_FALSE(alMetalCreateUnormVolumeArray(
            *device, edge, 2, 1, rgb8.data(), "invalid", &error));
        CHECK_FALSE(alMetalCreateUnormVolumeArray(
            *device, edge, 4, 4, rgb8.data(), "invalid", &error));
        CHECK_FALSE(alMetalCreateUnormVolumeArray(
            *device, edge, 4, 1, nullptr, "invalid", &error));
    }
}

TEST_CASE("almetal: unorm 2D upload preserves tone-curve precision",
          "[almetal][texture]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);

        // Production ALToneCurveSet::LUT_SIZE without coupling almetal to
        // newview's curve model.
        constexpr std::uint32_t width = 512;
        std::array<std::uint16_t, width * 4> source{};
        for (std::size_t index = 0; index < source.size(); ++index)
        {
            source[index] = static_cast<std::uint16_t>(
                index * 2341u + 29u);
        }
        auto texture = alMetalCreateUnormTexture2D(
            *device, width, 1, 4, 2, source.data(),
            "Alchemy RGBA16 tone-curve test", &error);
        INFO(error);
        REQUIRE(texture);
        CHECK(texture->descriptor().type == ALMetalTextureType::texture_2d);
        CHECK(texture->descriptor().format ==
              ALMetalPixelFormat::rgba16_unorm);
        CHECK(texture->descriptor().width == width);
        CHECK(texture->descriptor().height == 1);
        CHECK(texture->descriptor().array_length == 1);
        CHECK(texture->descriptor().storage ==
              ALMetalStorageMode::private_gpu);
        CHECK(texture->descriptor().usage ==
              ALMetalTextureUsage::shader_read);

        std::array<std::uint16_t, width * 4> readback{};
        REQUIRE(texture->readback(
            *device, 0, 0, {}, readback.data(),
            width * 4 * sizeof(std::uint16_t),
            &error));
        INFO(error);
        CHECK(readback == source);

        CHECK_FALSE(alMetalCreateUnormTexture2D(
            *device, 0, 1, 4, 2, source.data(), "invalid", &error));
        CHECK_FALSE(alMetalCreateUnormTexture2D(
            *device, width, 0, 4, 2, source.data(), "invalid", &error));
        CHECK_FALSE(alMetalCreateUnormTexture2D(
            *device, width, 1, 2, 2, source.data(), "invalid", &error));
        CHECK_FALSE(alMetalCreateUnormTexture2D(
            *device, width, 1, 4, 4, source.data(), "invalid", &error));
        CHECK_FALSE(alMetalCreateUnormTexture2D(
            *device, width, 1, 4, 2, nullptr, "invalid", &error));
        CHECK_FALSE(alMetalCreateUnormTexture2D(
            *device, std::numeric_limits<std::uint32_t>::max(),
            std::numeric_limits<std::uint32_t>::max(), 4, 2,
            source.data(), "invalid", &error));
    }
}

TEST_CASE("almetal: texture readback ring stays bounded and preserves FIFO order", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);

        ALMetalTextureDescriptor descriptor;
        descriptor.format = ALMetalPixelFormat::rgba8_unorm;
        descriptor.width = 3;
        descriptor.height = 2;
        descriptor.storage = ALMetalStorageMode::private_gpu;
        descriptor.usage = ALMetalTextureUsage::shader_read;
        descriptor.label = "Alchemy ordered readback-ring texture";
        auto texture = ALMetalTexture::create(*device, descriptor, &error);
        INFO(error);
        REQUIRE(texture);

        std::array<std::uint8_t, 3 * 2 * 4> pattern_a{};
        std::array<std::uint8_t, 3 * 2 * 4> pattern_b{};
        std::array<std::uint8_t, 3 * 2 * 4> pattern_c{};
        for (std::size_t index = 0; index < pattern_a.size(); ++index)
        {
            pattern_a[index] = static_cast<std::uint8_t>(10u + index);
            pattern_b[index] = static_cast<std::uint8_t>(70u + index);
            pattern_c[index] = static_cast<std::uint8_t>(130u + index);
        }

        const auto queue_upload = [&](const auto& pixels, const std::string& label)
        {
            auto command = device->makeCommandBuffer(label, &error);
            return command &&
                   texture->upload(
                       *command, 0, 0, {}, pixels.data(), 3 * 4, &error) &&
                   command->commit(&error);
        };
        const ALMetalRegion2D region{1, 0, 2, 2};
        const auto check_region = [](const auto& pixels,
                                     const std::array<std::uint8_t, 24>& result)
        {
            CHECK(std::memcmp(result.data(), pixels.data() + 4, 8) == 0);
            CHECK(std::memcmp(result.data() + 12, pixels.data() + 16, 8) == 0);
            for (std::size_t padding = 8; padding < 12; ++padding)
            {
                CHECK(result[padding] == 0xee);
                CHECK(result[12 + padding] == 0xee);
            }
        };

        ALMetalTextureReadbackRing ring;
        CHECK_FALSE(ring.isAllocated());
        CHECK(ring.pending() == 0);
        CHECK_FALSE(ring.request(*texture, 0, 0, region, &error));
        CHECK_FALSE(error.empty());

        error.clear();
        REQUIRE(ring.allocate(*device, 2, "Alchemy ordered readback ring", &error));
        INFO(error);
        CHECK(ring.isAllocated());

        REQUIRE(queue_upload(pattern_a, "Alchemy readback-ring upload A"));
        REQUIRE(ring.request(*texture, 0, 0, region, &error));
        REQUIRE(queue_upload(pattern_b, "Alchemy readback-ring upload B"));
        REQUIRE(ring.request(*texture, 0, 0, region, &error));
        CHECK(ring.pending() == 2);

        error.clear();
        CHECK_FALSE(ring.request(*texture, 0, 0, region, &error));
        CHECK(error.empty());
        CHECK(ring.pending() == 2);

        std::array<std::uint8_t, 24> result{};
        error.clear();
        CHECK_FALSE(ring.collect(result.data(), 7, true, &error));
        CHECK_FALSE(error.empty());
        CHECK(ring.pending() == 2);

        result.fill(0xee);
        error.clear();
        REQUIRE(ring.collect(result.data(), 12, true, &error));
        INFO(error);
        check_region(pattern_a, result);
        CHECK(ring.pending() == 1);

        REQUIRE(queue_upload(pattern_c, "Alchemy readback-ring upload C"));
        REQUIRE(ring.request(*texture, 0, 0, region, &error));
        CHECK(ring.pending() == 2);

        result.fill(0xee);
        REQUIRE(ring.collect(result.data(), 12, true, &error));
        INFO(error);
        check_region(pattern_b, result);
        CHECK(ring.pending() == 1);

        result.fill(0xee);
        REQUIRE(ring.collect(result.data(), 12, true, &error));
        INFO(error);
        check_region(pattern_c, result);
        CHECK(ring.pending() == 0);

        error.clear();
        CHECK_FALSE(ring.collect(result.data(), 12, false, &error));
        CHECK(error.empty());
        ring.release();
        CHECK_FALSE(ring.isAllocated());
    }
}

TEST_CASE("almetal: texture swizzles and generated mipmaps survive private upload", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);

        ALMetalTextureDescriptor descriptor;
        descriptor.format = ALMetalPixelFormat::r8_unorm;
        descriptor.width = 4;
        descriptor.height = 4;
        descriptor.mipmap_level_count = 3;
        descriptor.storage = ALMetalStorageMode::private_gpu;
        descriptor.swizzle = {
            ALMetalTextureSwizzle::zero,
            ALMetalTextureSwizzle::zero,
            ALMetalTextureSwizzle::zero,
            ALMetalTextureSwizzle::red,
        };
        descriptor.label = "Alchemy alpha swizzle texture";
        auto texture = ALMetalTexture::create(*device, descriptor, &error);
        INFO(error);
        REQUIRE(texture);
        CHECK(texture->blockWidth() == 1);
        CHECK(texture->blockHeight() == 1);
        CHECK(texture->bytesPerBlock() == 1);
        CHECK_FALSE(texture->isCompressed());

        auto library = ALMetalShaderLibrary::loadBuiltin(*device, &error);
        INFO(error);
        REQUIRE(library);
        ALMetalComputePipelineDescriptor pipeline_descriptor;
        pipeline_descriptor.library = library.get();
        pipeline_descriptor.function = "almetal_test_sample_texture";
        pipeline_descriptor.label = "Alchemy texture swizzle pipeline";
        auto pipeline = ALMetalComputePipeline::create(*device, pipeline_descriptor, &error);
        INFO(error);
        REQUIRE(pipeline);

        ALMetalBufferDescriptor result_descriptor;
        result_descriptor.length = sizeof(float) * 4;
        result_descriptor.storage = ALMetalStorageMode::shared;
        result_descriptor.label = "Alchemy texture sample result";
        auto result = ALMetalBuffer::create(*device, result_descriptor, &error);
        INFO(error);
        REQUIRE(result);

        const std::array<std::uint8_t, 16> source = {
            64, 64, 64, 64,
            64, 64, 64, 64,
            64, 64, 64, 64,
            64, 64, 64, 64,
        };
        auto command = device->makeCommandBuffer("Alchemy swizzle and mip test", &error);
        INFO(error);
        REQUIRE(command);
        REQUIRE(texture->upload(*command, 0, 0, {}, source.data(), 4, &error));
        REQUIRE(texture->generateMipmaps(*command, &error));

        auto encoder = ALMetalComputeEncoder::begin(*command, "Alchemy texture sample", &error);
        INFO(error);
        REQUIRE(encoder);
        REQUIRE(encoder->setPipeline(*pipeline, &error));
        REQUIRE(encoder->setTexture(0, texture.get(), &error));
        REQUIRE(encoder->setBuffer(0, *result, 0, &error));
        REQUIRE(encoder->dispatch(1, 1, 1, 1, 1, 1, &error));
        REQUIRE(encoder->end(&error));
        REQUIRE(command->commitAndWait(&error));
        INFO(error);

        std::array<float, 4> sample{};
        REQUIRE(result->read(0, sample.data(), sizeof(sample), &error));
        CHECK(sample[0] == 0.0f);
        CHECK(sample[1] == 0.0f);
        CHECK(sample[2] == 0.0f);
        CHECK(std::abs(sample[3] - (64.0f / 255.0f)) < 0.001f);

        std::uint8_t final_mip = 0;
        REQUIRE(texture->readback(*device, 2, 0, {}, &final_mip, 1, &error));
        INFO(error);
        CHECK(final_mip == 64);
    }
}

TEST_CASE("almetal: a cube-array texture addresses every cube face and samples one array element", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);

        ALMetalTextureDescriptor descriptor;
        descriptor.type = ALMetalTextureType::texture_cube_array;
        descriptor.format = ALMetalPixelFormat::rgba8_unorm;
        descriptor.width = 1;
        descriptor.height = 1;
        descriptor.array_length = 2;
        descriptor.storage = ALMetalStorageMode::private_gpu;
        descriptor.usage = ALMetalTextureUsage::shader_read;
        descriptor.label = "Alchemy cube-array resource test";
        auto texture = ALMetalTexture::create(*device, descriptor, &error);
        INFO(error);
        REQUIRE(texture);

        auto upload = device->makeCommandBuffer(
            "Alchemy cube-array resource upload", &error);
        INFO(error);
        REQUIRE(upload);
        for (std::uint32_t slice = 0; slice < 12; ++slice)
        {
            const std::array<std::uint8_t, 4> pixel{{
                static_cast<std::uint8_t>(slice * 17u),
                static_cast<std::uint8_t>(255u - slice * 13u),
                static_cast<std::uint8_t>(slice * 7u),
                255,
            }};
            REQUIRE(texture->upload(
                *upload, 0, slice, {}, pixel.data(), 4, &error));
        }
        REQUIRE(upload->commitAndWait(&error));
        INFO(error);

        std::array<std::uint8_t, 4> face{};
        REQUIRE(texture->readback(
            *device, 0, 10, {}, face.data(), 4, &error));
        INFO(error);
        CHECK(face[0] == 170);
        CHECK(face[1] == 125);
        CHECK(face[2] == 70);
        CHECK(face[3] == 255);

        auto library = ALMetalShaderLibrary::loadBuiltin(*device, &error);
        INFO(error);
        REQUIRE(library);
        ALMetalComputePipelineDescriptor pipeline_descriptor;
        pipeline_descriptor.library = library.get();
        pipeline_descriptor.function = "almetal_test_sample_cube_array";
        pipeline_descriptor.label = "Alchemy cube-array sample pipeline";
        auto pipeline = ALMetalComputePipeline::create(
            *device, pipeline_descriptor, &error);
        INFO(error);
        REQUIRE(pipeline);

        ALMetalBufferDescriptor result_descriptor;
        result_descriptor.length = sizeof(float) * 4;
        result_descriptor.storage = ALMetalStorageMode::shared;
        result_descriptor.label = "Alchemy cube-array sample result";
        auto result = ALMetalBuffer::create(
            *device, result_descriptor, &error);
        INFO(error);
        REQUIRE(result);

        auto sample = device->makeCommandBuffer(
            "Alchemy cube-array resource sample", &error);
        INFO(error);
        REQUIRE(sample);
        auto encoder = ALMetalComputeEncoder::begin(
            *sample, "Alchemy cube-array sample encoder", &error);
        INFO(error);
        REQUIRE(encoder);
        REQUIRE(encoder->setPipeline(*pipeline, &error));
        REQUIRE(encoder->setTexture(0, texture.get(), &error));
        REQUIRE(encoder->setBuffer(0, *result, 0, &error));
        REQUIRE(encoder->dispatch(1, 1, 1, 1, 1, 1, &error));
        REQUIRE(encoder->end(&error));
        REQUIRE(sample->commitAndWait(&error));
        INFO(error);

        std::array<float, 4> sampled{};
        REQUIRE(result->read(
            0, sampled.data(), sizeof(sampled), &error));
        CHECK(std::abs(sampled[0] - 170.0f / 255.0f) < 0.001f);
        CHECK(std::abs(sampled[1] - 125.0f / 255.0f) < 0.001f);
        CHECK(std::abs(sampled[2] - 70.0f / 255.0f) < 0.001f);
        CHECK(sampled[3] == 1.0f);

        auto invalid_upload = device->makeCommandBuffer(
            "Alchemy invalid cube-array upload", &error);
        INFO(error);
        REQUIRE(invalid_upload);
        CHECK_FALSE(texture->upload(
            *invalid_upload, 0, 12, {}, face.data(), 4, &error));
        CHECK(error == "Metal texture slice is out of range");

        ALMetalTextureDescriptor invalid_descriptor = descriptor;
        invalid_descriptor.type = ALMetalTextureType::texture_cube;
        CHECK_FALSE(ALMetalTexture::create(
            *device, invalid_descriptor, &error));
        CHECK(error ==
              "Only an array Metal texture accepts array_length greater than one");
    }
}

TEST_CASE("almetal: a typed texture blit copies one mip into a new mip chain", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);

        ALMetalTextureDescriptor source_descriptor;
        source_descriptor.format = ALMetalPixelFormat::r8_unorm;
        source_descriptor.width = 4;
        source_descriptor.height = 4;
        source_descriptor.mipmap_level_count = 3;
        source_descriptor.storage = ALMetalStorageMode::private_gpu;
        source_descriptor.usage = ALMetalTextureUsage::shader_read;
        source_descriptor.label = "Alchemy texture-copy source";
        auto source = ALMetalTexture::create(*device, source_descriptor, &error);
        INFO(error);
        REQUIRE(source);

        ALMetalTextureDescriptor destination_descriptor = source_descriptor;
        destination_descriptor.width = 2;
        destination_descriptor.height = 2;
        destination_descriptor.mipmap_level_count = 2;
        destination_descriptor.label = "Alchemy texture-copy destination";
        auto destination = ALMetalTexture::create(*device, destination_descriptor, &error);
        INFO(error);
        REQUIRE(destination);

        const std::array<std::uint8_t, 4> expected = {11, 22, 33, 44};
        auto command = device->makeCommandBuffer("Alchemy typed texture-copy test", &error);
        INFO(error);
        REQUIRE(command);
        REQUIRE(source->upload(*command, 1, 0, {}, expected.data(), 2, &error));
        ALMetalTextureCopy copy;
        copy.source_mip_level = 1;
        REQUIRE(destination->copyFrom(*command, *source, copy, &error));
        REQUIRE(destination->generateMipmaps(*command, &error));
        REQUIRE(command->commitAndWait(&error));
        INFO(error);

        std::array<std::uint8_t, 4> result{};
        REQUIRE(destination->readback(*device, 0, 0, {}, result.data(), 2, &error));
        INFO(error);
        CHECK(result == expected);

        ALMetalTextureDescriptor mismatched_descriptor = destination_descriptor;
        mismatched_descriptor.format = ALMetalPixelFormat::rg8_unorm;
        auto mismatched = ALMetalTexture::create(*device, mismatched_descriptor, &error);
        INFO(error);
        REQUIRE(mismatched);
        auto rejected = device->makeCommandBuffer("Alchemy rejected texture-copy test", &error);
        REQUIRE(rejected);
        CHECK_FALSE(mismatched->copyFrom(*rejected, *source, {}, &error));
        CHECK(error == "Metal texture copy requires matching pixel formats");
    }
}

TEST_CASE("almetal: bilinear texture resampling stays entirely on the GPU", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);

        ALMetalTextureDescriptor source_descriptor;
        source_descriptor.format = ALMetalPixelFormat::r8_unorm;
        source_descriptor.width = 4;
        source_descriptor.height = 4;
        source_descriptor.storage = ALMetalStorageMode::private_gpu;
        source_descriptor.usage = ALMetalTextureUsage::shader_read;
        source_descriptor.label = "Alchemy texture-resample source";
        auto source = ALMetalTexture::create(*device, source_descriptor, &error);
        INFO(error);
        REQUIRE(source);

        ALMetalTextureDescriptor destination_descriptor = source_descriptor;
        destination_descriptor.width = 2;
        destination_descriptor.height = 2;
        destination_descriptor.usage = ALMetalTextureUsage::shader_read |
                                       ALMetalTextureUsage::render_target;
        destination_descriptor.label = "Alchemy texture-resample destination";
        auto destination = ALMetalTexture::create(*device, destination_descriptor, &error);
        INFO(error);
        REQUIRE(destination);
        // Each output pixel samples the center of one constant 2x2 quadrant,
        // so the exact expected bytes are independent of UNORM rounding.
        const std::array<std::uint8_t, 16> source_pixels = {
             16,  16,  64,  64,
             16,  16,  64,  64,
            128, 128, 240, 240,
            128, 128, 240, 240,
        };
        const std::array<std::uint8_t, 4> expected = {16, 64, 128, 240};

        auto resampler = ALMetalTextureResampler::create(*device, &error);
        INFO(error);
        REQUIRE(resampler);
        auto command = device->makeCommandBuffer(
            "Alchemy bilinear texture-resample test", &error);
        INFO(error);
        REQUIRE(command);
        REQUIRE(source->upload(
            *command, 0, 0, {}, source_pixels.data(), 4, &error));
        REQUIRE(resampler->encode(*command, *source, *destination, &error));
        CHECK_FALSE(resampler->encode(
            *command, *source, *destination, true, &error));
        CHECK(error == "Metal texture row flip requires matching dimensions");
        REQUIRE(command->commitAndWait(&error));
        INFO(error);

        std::array<std::uint8_t, 4> result{};
        REQUIRE(destination->readback(
            *device, 0, 0, {}, result.data(), 2, &error));
        INFO(error);
        CHECK(result == expected);
        CHECK(ALMetalTextureResampler::supports(
            ALMetalPixelFormat::rgba8_unorm_srgb));

        ALMetalTextureDescriptor srgb_source_descriptor;
        srgb_source_descriptor.format = ALMetalPixelFormat::rgba8_unorm_srgb;
        srgb_source_descriptor.width = 4;
        srgb_source_descriptor.height = 4;
        srgb_source_descriptor.storage = ALMetalStorageMode::private_gpu;
        srgb_source_descriptor.usage = ALMetalTextureUsage::shader_read;
        srgb_source_descriptor.label = "Alchemy raw-sRGB resample source";
        auto srgb_source = ALMetalTexture::create(
            *device, srgb_source_descriptor, &error);
        INFO(error);
        REQUIRE(srgb_source);

        ALMetalTextureDescriptor srgb_destination_descriptor = srgb_source_descriptor;
        srgb_destination_descriptor.width = 2;
        srgb_destination_descriptor.height = 2;
        srgb_destination_descriptor.usage = ALMetalTextureUsage::shader_read |
                                            ALMetalTextureUsage::render_target;
        srgb_destination_descriptor.label = "Alchemy raw-sRGB resample destination";
        auto srgb_destination = ALMetalTexture::create(
            *device, srgb_destination_descriptor, &error);
        INFO(error);
        REQUIRE(srgb_destination);

        std::array<std::uint8_t, 4 * 4 * 4> srgb_pixels{};
        for (std::size_t y = 0; y < 4; ++y)
        {
            for (std::size_t x = 0; x < 4; ++x)
            {
                const std::uint8_t value = (x & 1u) ? 255 : 0;
                const std::size_t offset = (y * 4 + x) * 4;
                srgb_pixels[offset + 0] = value;
                srgb_pixels[offset + 1] = value;
                srgb_pixels[offset + 2] = value;
                srgb_pixels[offset + 3] = 255;
            }
        }
        auto srgb_command = device->makeCommandBuffer(
            "Alchemy encoded-sRGB texture-resample test", &error);
        INFO(error);
        REQUIRE(srgb_command);
        REQUIRE(srgb_source->upload(
            *srgb_command, 0, 0, {}, srgb_pixels.data(), 4 * 4, &error));
        REQUIRE(resampler->encode(
            *srgb_command, *srgb_source, *srgb_destination, &error));
        REQUIRE(srgb_command->commitAndWait(&error));
        INFO(error);

        std::array<std::uint8_t, 2 * 2 * 4> srgb_result{};
        REQUIRE(srgb_destination->readback(
            *device, 0, 0, {}, srgb_result.data(), 2 * 4, &error));
        INFO(error);
        for (std::size_t pixel = 0; pixel < 4; ++pixel)
        {
            CHECK(std::abs(static_cast<int>(srgb_result[pixel * 4 + 0]) - 128) <= 1);
            CHECK(std::abs(static_cast<int>(srgb_result[pixel * 4 + 1]) - 128) <= 1);
            CHECK(std::abs(static_cast<int>(srgb_result[pixel * 4 + 2]) - 128) <= 1);
            CHECK(srgb_result[pixel * 4 + 3] == 255);
        }
    }
}

TEST_CASE("almetal: IOSurface media ingress is imported without a CPU staging copy", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);

        constexpr std::uint32_t width = 3;
        constexpr std::uint32_t height = 2;
        constexpr std::uint32_t bgra_fourcc = 0x42475241u;
        const std::size_t aligned_row_bytes = IOSurfaceAlignProperty(
            kIOSurfaceBytesPerRow, width * 4);
        NSDictionary* properties = @{
            (__bridge NSString*)kIOSurfaceWidth: @(width),
            (__bridge NSString*)kIOSurfaceHeight: @(height),
            (__bridge NSString*)kIOSurfaceBytesPerElement: @4,
            (__bridge NSString*)kIOSurfaceBytesPerRow: @(aligned_row_bytes),
            (__bridge NSString*)kIOSurfacePixelFormat: @(bgra_fourcc),
        };
        IOSurfaceRef surface = IOSurfaceCreate(
            (__bridge CFDictionaryRef)properties);
        REQUIRE(surface != nullptr);
        struct SurfaceRelease
        {
            IOSurfaceRef value = nullptr;
            ~SurfaceRelease()
            {
                if (value)
                {
                    CFRelease(value);
                }
            }
        } release{surface};

        REQUIRE(IOSurfaceLock(surface, 0, nullptr) == kIOReturnSuccess);
        auto* bytes = static_cast<std::uint8_t*>(IOSurfaceGetBaseAddress(surface));
        REQUIRE(bytes != nullptr);
        const std::size_t row_bytes = IOSurfaceGetBytesPerRow(surface);
        const std::array<std::uint8_t, width * 4> top = {
            1, 2, 3, 255, 4, 5, 6, 255, 7, 8, 9, 255,
        };
        const std::array<std::uint8_t, width * 4> bottom = {
            11, 12, 13, 255, 14, 15, 16, 255, 17, 18, 19, 255,
        };
        std::memcpy(bytes, top.data(), top.size());
        std::memcpy(bytes + row_bytes, bottom.data(), bottom.size());
        REQUIRE(IOSurfaceUnlock(surface, 0, nullptr) == kIOReturnSuccess);

        ALMetalTextureDescriptor imported_descriptor;
        imported_descriptor.format = ALMetalPixelFormat::bgra8_unorm;
        imported_descriptor.width = width;
        imported_descriptor.height = height;
        imported_descriptor.storage = ALMetalStorageMode::shared;
        imported_descriptor.usage = ALMetalTextureUsage::shader_read;
        imported_descriptor.label = "Alchemy IOSurface media import test";
        auto imported = ALMetalTexture::createFromIOSurface(
            *device, surface, 0, imported_descriptor, &error);
        INFO(error);
        REQUIRE(imported);

        ALMetalTextureDescriptor output_descriptor = imported_descriptor;
        output_descriptor.storage = ALMetalStorageMode::private_gpu;
        output_descriptor.usage = ALMetalTextureUsage::shader_read |
                                  ALMetalTextureUsage::render_target;
        output_descriptor.label = "Alchemy flipped IOSurface media output test";
        auto output = ALMetalTexture::create(
            *device, output_descriptor, &error);
        INFO(error);
        REQUIRE(output);
        auto resampler = ALMetalTextureResampler::create(*device, &error);
        INFO(error);
        REQUIRE(resampler);
        auto command = device->makeCommandBuffer(
            "Alchemy IOSurface media ingress test", &error);
        INFO(error);
        REQUIRE(command);
        REQUIRE(resampler->encode(
            *command, *imported, *output, true, &error));
        REQUIRE(command->commitAndWait(&error));
        INFO(error);

        std::array<std::uint8_t, width * height * 4> result{};
        REQUIRE(output->readback(
            *device, 0, 0, {}, result.data(), width * 4, &error));
        INFO(error);
        CHECK(std::equal(bottom.begin(), bottom.end(), result.begin()));
        CHECK(std::equal(top.begin(), top.end(), result.begin() + bottom.size()));

        ALMetalTextureDescriptor wrong_size = imported_descriptor;
        wrong_size.width = width + 1;
        CHECK_FALSE(ALMetalTexture::createFromIOSurface(
            *device, surface, 0, wrong_size, &error));
        CHECK(error ==
              "IOSurface dimensions do not match the Metal texture descriptor");
    }
}

TEST_CASE("almetal: legacy brightness and darkness bump maps are generated natively", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        auto generator = ALMetalNormalMapGenerator::create(*device, &error);
        INFO(error);
        REQUIRE(generator);

        ALMetalTextureDescriptor source_descriptor;
        source_descriptor.format = ALMetalPixelFormat::rgba8_unorm;
        source_descriptor.width = 4;
        source_descriptor.height = 4;
        source_descriptor.storage = ALMetalStorageMode::private_gpu;
        source_descriptor.usage = ALMetalTextureUsage::shader_read;
        source_descriptor.label = "Alchemy legacy bump source";
        auto source = ALMetalTexture::create(
            *device, source_descriptor, &error);
        INFO(error);
        REQUIRE(source);

        ALMetalTextureDescriptor destination_descriptor = source_descriptor;
        destination_descriptor.mipmap_level_count = 3;
        destination_descriptor.usage = ALMetalTextureUsage::shader_read |
                                       ALMetalTextureUsage::render_target;
        destination_descriptor.label = "Alchemy brightness bump result";
        auto brightness = ALMetalTexture::create(
            *device, destination_descriptor, &error);
        INFO(error);
        REQUIRE(brightness);
        destination_descriptor.label = "Alchemy darkness bump result";
        auto darkness = ALMetalTexture::create(
            *device, destination_descriptor, &error);
        INFO(error);
        REQUIRE(darkness);

        std::array<std::uint8_t, 4 * 4 * 4> source_pixels{};
        for (std::size_t pixel = 0; pixel < 16; ++pixel)
        {
            source_pixels[pixel * 4 + 0] = 64;
            source_pixels[pixel * 4 + 1] = 64;
            source_pixels[pixel * 4 + 2] = 64;
            source_pixels[pixel * 4 + 3] = 255;
        }
        auto command = device->makeCommandBuffer(
            "Alchemy native legacy bump-map test", &error);
        INFO(error);
        REQUIRE(command);
        REQUIRE(source->upload(
            *command, 0, 0, {}, source_pixels.data(), 4 * 4, &error));
        REQUIRE(generator->encode(
            *command, *source, *brightness, 2.f, false, &error));
        REQUIRE(brightness->generateMipmaps(*command, &error));
        REQUIRE(generator->encode(
            *command, *source, *darkness, 2.f, true, &error));
        REQUIRE(darkness->generateMipmaps(*command, &error));
        REQUIRE(command->commitAndWait(&error));
        INFO(error);

        std::array<std::uint8_t, 4 * 4 * 4> bright_pixels{};
        std::array<std::uint8_t, 4 * 4 * 4> dark_pixels{};
        REQUIRE(brightness->readback(
            *device, 0, 0, {}, bright_pixels.data(), 4 * 4, &error));
        REQUIRE(darkness->readback(
            *device, 0, 0, {}, dark_pixels.data(), 4 * 4, &error));
        INFO(error);
        for (std::size_t pixel = 0; pixel < 16; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            CHECK(std::abs(static_cast<int>(bright_pixels[offset + 0]) - 128) <= 1);
            CHECK(std::abs(static_cast<int>(bright_pixels[offset + 1]) - 128) <= 1);
            CHECK(bright_pixels[offset + 2] == 255);
            CHECK(std::abs(static_cast<int>(bright_pixels[offset + 3]) - 64) <= 1);
            CHECK(std::abs(static_cast<int>(dark_pixels[offset + 0]) - 128) <= 1);
            CHECK(std::abs(static_cast<int>(dark_pixels[offset + 1]) - 128) <= 1);
            CHECK(dark_pixels[offset + 2] == 255);
            CHECK(std::abs(static_cast<int>(dark_pixels[offset + 3]) - 191) <= 1);
        }
    }
}

TEST_CASE("almetal: terrain paint bake consumes indexed viewer buffers and generates mips", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        auto renderer = ALMetalTerrainPaintRenderer::create(*device, &error);
        INFO(error);
        REQUIRE(renderer);

        constexpr std::size_t position_offset = 0;
        constexpr std::size_t texcoord_offset = sizeof(float) * 4 * 4;
        std::array<std::uint8_t, texcoord_offset + sizeof(float) * 2 * 4> vertex_bytes{};
        const float positions[4][4] = {
            {-1.f, -1.f, 0.f, 1.f},
            { 1.f, -1.f, 0.f, 1.f},
            {-1.f,  1.f, 0.f, 1.f},
            { 1.f,  1.f, 0.f, 1.f},
        };
        const float texcoords[4][2] = {
            {0.5f, 0.5f}, {0.5f, 0.5f},
            {0.5f, 0.5f}, {0.5f, 0.5f},
        };
        std::memcpy(vertex_bytes.data() + position_offset, positions, sizeof(positions));
        std::memcpy(vertex_bytes.data() + texcoord_offset, texcoords, sizeof(texcoords));

        ALMetalBufferDescriptor vertex_descriptor;
        vertex_descriptor.length = vertex_bytes.size();
        vertex_descriptor.storage = ALMetalStorageMode::shared;
        vertex_descriptor.label = "Alchemy terrain paint vertex test";
        auto vertices = ALMetalBuffer::create(*device, vertex_descriptor, &error);
        INFO(error);
        REQUIRE(vertices);
        REQUIRE(vertices->write(0, vertex_bytes.data(), vertex_bytes.size(), &error));

        const std::array<std::uint32_t, 6> index_values = {0, 1, 2, 1, 3, 2};
        ALMetalBufferDescriptor index_descriptor;
        index_descriptor.length = sizeof(index_values);
        index_descriptor.storage = ALMetalStorageMode::shared;
        index_descriptor.label = "Alchemy terrain paint index test";
        auto indices = ALMetalBuffer::create(*device, index_descriptor, &error);
        INFO(error);
        REQUIRE(indices);
        REQUIRE(indices->write(0, index_values.data(), sizeof(index_values), &error));

        ALMetalTextureDescriptor alpha_descriptor;
        alpha_descriptor.format = ALMetalPixelFormat::rgba8_unorm;
        alpha_descriptor.width = 1;
        alpha_descriptor.height = 1;
        alpha_descriptor.storage = ALMetalStorageMode::private_gpu;
        alpha_descriptor.usage = ALMetalTextureUsage::shader_read;
        alpha_descriptor.label = "Alchemy terrain alpha-ramp test";
        auto alpha_ramp = ALMetalTexture::create(*device, alpha_descriptor, &error);
        INFO(error);
        REQUIRE(alpha_ramp);
        const std::array<std::uint8_t, 4> alpha_pixel = {0, 0, 0, 128};
        auto upload = device->makeCommandBuffer("Alchemy terrain alpha upload", &error);
        INFO(error);
        REQUIRE(upload);
        REQUIRE(alpha_ramp->upload(*upload, 0, 0, {}, alpha_pixel.data(), 4, &error));
        REQUIRE(upload->commit(&error));

        ALMetalTextureDescriptor template_descriptor;
        template_descriptor.format = ALMetalPixelFormat::rgba8_unorm;
        template_descriptor.width = 8;
        template_descriptor.height = 8;
        template_descriptor.mipmap_level_count = 4;
        template_descriptor.storage = ALMetalStorageMode::private_gpu;
        template_descriptor.usage = ALMetalTextureUsage::shader_read;
        template_descriptor.label = "Alchemy terrain paint destination template";
        auto destination_template = ALMetalTexture::create(
            *device, template_descriptor, &error);
        INFO(error);
        REQUIRE(destination_template);

        ALMetalTerrainPaintBatch batch;
        batch.vertices = vertices.get();
        batch.position_offset = position_offset;
        batch.texcoord_offset = texcoord_offset;
        batch.indices = indices.get();
        batch.index_type = ALMetalIndexType::uint32;
        batch.index_count = index_values.size();
        batch.alpha_ramp = alpha_ramp.get();
        batch.destination_template = destination_template.get();
        batch.precision = 255.f;
        for (int i = 0; i < 4; ++i)
        {
            batch.modelview_projection[i * 4 + i] = 1.f;
        }

        auto result = renderer->render(batch, &error);
        INFO(error);
        REQUIRE(result);
        CHECK(alMetalHasUsage(result->descriptor().usage,
                              ALMetalTextureUsage::shader_read));
        CHECK(alMetalHasUsage(result->descriptor().usage,
                              ALMetalTextureUsage::render_target));
        CHECK(result->descriptor().mipmap_level_count == 4);

        std::array<std::uint8_t, 8 * 8 * 4> level_zero{};
        REQUIRE(result->readback(
            *device, 0, 0, {}, level_zero.data(), 8 * 4, &error));
        INFO(error);
        for (std::size_t pixel = 0; pixel < 8 * 8; ++pixel)
        {
            CHECK(level_zero[pixel * 4 + 0] == 64);
            CHECK(level_zero[pixel * 4 + 1] == 64);
            CHECK(level_zero[pixel * 4 + 2] == 63);
            CHECK(level_zero[pixel * 4 + 3] == 255);
        }

        std::array<std::uint8_t, 4> final_mip{};
        REQUIRE(result->readback(
            *device, 3, 0, {}, final_mip.data(), 4, &error));
        INFO(error);
        CHECK(final_mip == std::array<std::uint8_t, 4>{64, 64, 63, 255});

        // A Metal render target numbers row zero from the top, while the GL
        // framebuffer copy numbers it from the bottom. Vary the composition
        // coordinate vertically and verify the renderer stores GL's lower
        // row first so the two mirrors remain byte-for-byte interchangeable.
        const float vertical_texcoords[4][2] = {
            {1.25f, 0.5f}, {1.25f, 0.5f},
            {1.75f, 0.5f}, {1.75f, 0.5f},
        };
        REQUIRE(vertices->write(
            texcoord_offset, vertical_texcoords, sizeof(vertical_texcoords), &error));
        ALMetalTextureDescriptor gradient_descriptor = alpha_descriptor;
        gradient_descriptor.width = 2;
        gradient_descriptor.label = "Alchemy terrain alpha orientation test";
        auto gradient = ALMetalTexture::create(*device, gradient_descriptor, &error);
        INFO(error);
        REQUIRE(gradient);
        const std::array<std::uint8_t, 8> gradient_pixels = {
            0, 0, 0, 0,
            0, 0, 0, 255,
        };
        auto gradient_upload = device->makeCommandBuffer(
            "Alchemy terrain alpha orientation upload", &error);
        INFO(error);
        REQUIRE(gradient_upload);
        REQUIRE(gradient->upload(
            *gradient_upload, 0, 0, {}, gradient_pixels.data(), 8, &error));
        REQUIRE(gradient_upload->commit(&error));

        batch.alpha_ramp = gradient.get();
        auto oriented = renderer->render(batch, &error);
        INFO(error);
        REQUIRE(oriented);
        std::array<std::uint8_t, 8 * 8 * 4> oriented_pixels{};
        REQUIRE(oriented->readback(
            *device, 0, 0, {}, oriented_pixels.data(), 8 * 4, &error));
        INFO(error);
        const std::size_t lower_gl_row = 4 * 4;
        CHECK(oriented_pixels[lower_gl_row + 0] == 0);
        CHECK(oriented_pixels[lower_gl_row + 1] == 0);
        CHECK(oriented_pixels[lower_gl_row + 2] == 255);
        CHECK(oriented_pixels[lower_gl_row + 3] == 255);
        const std::size_t upper_gl_row = (7 * 8 + 4) * 4;
        CHECK(oriented_pixels[upper_gl_row + 0] == 0);
        CHECK(oriented_pixels[upper_gl_row + 1] == 0);
        CHECK(oriented_pixels[upper_gl_row + 2] == 0);
        CHECK(oriented_pixels[upper_gl_row + 3] == 255);
    }
}

TEST_CASE("almetal: direct spot-shadow slices retain strict raw raster depth", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        auto renderer = ALMetalWorldGBufferRenderer::create(*device, &error);
        INFO(error);
        REQUIRE(renderer);

        const std::array<std::array<float, 4>, 3> positions{{
            {{-0.75f, -0.75f, 0.f, 1.f}},
            {{ 0.75f, -0.75f, 0.f, 1.f}},
            {{ 0.f,    0.75f, 0.f, 1.f}},
        }};
        const std::array<std::array<float, 4>, 3> weights{{
            {{0.5f, 0.f, 0.f, 0.f}},
            {{0.5f, 0.f, 0.f, 0.f}},
            {{0.5f, 0.f, 0.f, 0.f}},
        }};
        const std::array<std::array<float, 2>, 3> texcoords{{
            {{0.125f, 0.5f}},
            {{0.125f, 0.5f}},
            {{0.125f, 0.5f}},
        }};
        const std::array<std::array<std::uint8_t, 4>, 3> white_colors{{
            {{255, 255, 255, 255}},
            {{255, 255, 255, 255}},
            {{255, 255, 255, 255}},
        }};
        constexpr std::size_t weight_offset = sizeof(positions);
        constexpr std::size_t texcoord_offset =
            weight_offset + sizeof(weights);
        constexpr std::size_t color_offset =
            texcoord_offset + sizeof(texcoords);
        std::array<std::uint8_t,
                   sizeof(positions) + sizeof(weights) +
                       sizeof(texcoords) + sizeof(white_colors)>
            vertex_bytes{};
        std::memcpy(vertex_bytes.data(), positions.data(), sizeof(positions));
        std::memcpy(vertex_bytes.data() + weight_offset,
                    weights.data(), sizeof(weights));
        std::memcpy(vertex_bytes.data() + texcoord_offset,
                    texcoords.data(), sizeof(texcoords));
        std::memcpy(vertex_bytes.data() + color_offset,
                    white_colors.data(), sizeof(white_colors));
        const std::array<std::uint16_t, 3> index_values{{0, 1, 2}};

        ALMetalBufferDescriptor descriptor;
        descriptor.length = vertex_bytes.size();
        descriptor.storage = ALMetalStorageMode::shared;
        descriptor.label = "Alchemy direct spot-shadow test vertices";
        auto vertices = ALMetalBuffer::create(*device, descriptor, &error);
        INFO(error);
        REQUIRE(vertices);
        REQUIRE(vertices->write(
            0, vertex_bytes.data(), vertex_bytes.size(), &error));
        descriptor.length = sizeof(index_values);
        descriptor.label = "Alchemy direct spot-shadow test indices";
        auto indices = ALMetalBuffer::create(*device, descriptor, &error);
        INFO(error);
        REQUIRE(indices);
        REQUIRE(indices->write(
            0, index_values.data(), sizeof(index_values), &error));

        ALMetalWorldSpotShadowBatch batch;
        batch.vertices = vertices.get();
        batch.vertex_count = positions.size();
        batch.indices = indices.get();
        batch.index_count = index_values.size();
        for (std::size_t axis = 0; axis < 4; ++axis)
        {
            batch.modelview_projection[axis * 4 + axis] = 1.f;
        }
        ALMetalWorldSpotShadowScene scene;
        scene.batches = &batch;
        scene.batch_count = 1;
        scene.width = 32;
        scene.height = 32;

        auto forward = renderer->renderSpotShadow(scene, &error);
        INFO(error);
        REQUIRE(forward);
        REQUIRE(forward->descriptor().colors[0].format ==
                ALMetalPixelFormat::r32_float);
        std::array<float, 32 * 32> forward_depth{};
        REQUIRE(forward->colorTexture(0)->readback(
            *device, 0, 0, {}, forward_depth.data(), 32 * sizeof(float),
            &error));
        INFO(error);
        CHECK(std::abs(forward_depth[16 * 32 + 16] - 0.5f) < 0.0001f);
        CHECK(std::abs(forward_depth[1 * 32 + 1] - 1.f) < 0.0001f);

        batch.modelview_projection[14] = -2.f;
        auto clipped = renderer->renderSpotShadow(scene, &error);
        INFO(error);
        REQUIRE(clipped);
        std::array<float, 32 * 32> clipped_depth{};
        REQUIRE(clipped->colorTexture(0)->readback(
            *device, 0, 0, {}, clipped_depth.data(), 32 * sizeof(float),
            &error));
        INFO(error);
        CHECK(std::abs(clipped_depth[16 * 32 + 16] - 1.f) < 0.0001f);

        scene.depth_clamp = true;
        auto clamped = renderer->renderSpotShadow(scene, &error);
        INFO(error);
        REQUIRE(clamped);
        std::array<float, 32 * 32> clamped_depth{};
        REQUIRE(clamped->colorTexture(0)->readback(
            *device, 0, 0, {}, clamped_depth.data(), 32 * sizeof(float),
            &error));
        INFO(error);
        CHECK(std::abs(clamped_depth[16 * 32 + 16]) < 0.0001f);

        batch.modelview_projection[14] = 0.f;
        auto clamped_mid = renderer->renderSpotShadow(scene, &error);
        INFO(error);
        REQUIRE(clamped_mid);
        std::array<float, 32 * 32> clamped_mid_depth{};
        REQUIRE(clamped_mid->colorTexture(0)->readback(
            *device, 0, 0, {}, clamped_mid_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK(std::abs(
            clamped_mid_depth[16 * 32 + 16] - 0.5f) < 0.0001f);
        scene.depth_clamp = false;

        const std::array<float, 16> skin_palette{{
            0.25f, 0.f, 0.f, 0.f,
            1.f, 0.f, 0.f, 0.25f,
            0.f, 1.f, 0.f, 0.f,
            0.f, 0.f, 1.f, 0.f,
        }};
        batch.weight_offset = weight_offset;
        batch.skin_palette = skin_palette.data();
        batch.skin_palette_float_count = skin_palette.size();
        batch.skin_joint_count = 1;
        auto rigged = renderer->renderSpotShadow(scene, &error);
        INFO(error);
        REQUIRE(rigged);
        std::array<float, 32 * 32> rigged_depth{};
        REQUIRE(rigged->colorTexture(0)->readback(
            *device, 0, 0, {}, rigged_depth.data(), 32 * sizeof(float),
            &error));
        INFO(error);
        CHECK(std::abs(rigged_depth[16 * 32 + 24] - 0.5f) < 0.0001f);
        CHECK(std::abs(rigged_depth[16 * 32 + 8] - 1.f) < 0.0001f);

        batch.skin_palette = nullptr;
        batch.skin_palette_float_count = 0;
        batch.skin_joint_count = 0;
        batch.weight_offset = 0;
        scene.reverse_z = true;
        batch.modelview_projection[14] = 0.5f;
        auto reverse = renderer->renderSpotShadow(scene, &error);
        INFO(error);
        REQUIRE(reverse);
        std::array<float, 32 * 32> reverse_depth{};
        REQUIRE(reverse->colorTexture(0)->readback(
            *device, 0, 0, {}, reverse_depth.data(), 32 * sizeof(float),
            &error));
        INFO(error);
        CHECK(std::abs(reverse_depth[16 * 32 + 16] - 0.5f) < 0.0001f);
        CHECK(std::abs(reverse_depth[1 * 32 + 1]) < 0.0001f);

        scene.depth_clamp = true;
        batch.modelview_projection[14] = 2.f;
        auto reverse_clamped = renderer->renderSpotShadow(scene, &error);
        INFO(error);
        REQUIRE(reverse_clamped);
        std::array<float, 32 * 32> reverse_clamped_depth{};
        REQUIRE(reverse_clamped->colorTexture(0)->readback(
            *device, 0, 0, {}, reverse_clamped_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK(std::abs(
            reverse_clamped_depth[16 * 32 + 16] - 1.f) < 0.0001f);

        batch.modelview_projection[14] = 0.5f;
        auto reverse_clamped_mid = renderer->renderSpotShadow(
            scene, &error);
        INFO(error);
        REQUIRE(reverse_clamped_mid);
        std::array<float, 32 * 32> reverse_clamped_mid_depth{};
        REQUIRE(reverse_clamped_mid->colorTexture(0)->readback(
            *device, 0, 0, {}, reverse_clamped_mid_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK(std::abs(
            reverse_clamped_mid_depth[16 * 32 + 16] - 0.5f) <
            0.0001f);
        scene.depth_clamp = false;

        const std::array<std::array<float, 4>, 4>
            terrain_control_points{{
                {{-0.75f, -0.75f, 0.f, 1.f}},
                {{ 0.75f, -0.75f, 0.f, 1.f}},
                {{ 0.75f,  0.75f, 0.f, 1.f}},
                {{-0.75f,  0.75f, 0.f, 1.f}},
            }};
        descriptor.length = sizeof(terrain_control_points);
        descriptor.label =
            "Alchemy direct terrain spot-shadow control points";
        auto terrain_vertices = ALMetalBuffer::create(
            *device, descriptor, &error);
        INFO(error);
        REQUIRE(terrain_vertices);
        REQUIRE(terrain_vertices->write(
            0, terrain_control_points.data(),
            sizeof(terrain_control_points), &error));

        ALMetalTextureDescriptor terrain_height_descriptor;
        terrain_height_descriptor.format = ALMetalPixelFormat::r32_float;
        terrain_height_descriptor.width = 8;
        terrain_height_descriptor.height = 8;
        terrain_height_descriptor.storage = ALMetalStorageMode::private_gpu;
        terrain_height_descriptor.usage = ALMetalTextureUsage::shader_read;
        terrain_height_descriptor.label =
            "Alchemy direct terrain spot-shadow height map";
        auto terrain_height = ALMetalTexture::create(
            *device, terrain_height_descriptor, &error);
        INFO(error);
        REQUIRE(terrain_height);
        const std::array<float, 8 * 8> flat_terrain{};
        auto terrain_upload = device->makeCommandBuffer(
            "Alchemy direct terrain spot-shadow upload", &error);
        INFO(error);
        REQUIRE(terrain_upload);
        REQUIRE(terrain_height->upload(
            *terrain_upload, 0, 0, {}, flat_terrain.data(),
            8 * sizeof(float), &error));
        REQUIRE(terrain_upload->commitAndWait(&error));
        INFO(error);

        ALMetalWorldSpotShadowBatch terrain_batch;
        terrain_batch.terrain = true;
        terrain_batch.vertices = terrain_vertices.get();
        terrain_batch.vertex_count = terrain_control_points.size();
        terrain_batch.terrain_height_texture = terrain_height.get();
        terrain_batch.terrain_grid_scale = 1.f;
        std::fill_n(terrain_batch.terrain_tessellation_factors, 6,
                    std::uint16_t{0x4400});
        for (std::size_t axis = 0; axis < 4; ++axis)
        {
            terrain_batch.modelview_projection[axis * 4 + axis] = 1.f;
        }
        scene.batches = &terrain_batch;
        scene.reverse_z = false;
        auto terrain_shadow = renderer->renderSpotShadow(scene, &error);
        INFO(error);
        REQUIRE(terrain_shadow);
        std::array<float, 32 * 32> terrain_depth{};
        REQUIRE(terrain_shadow->colorTexture(0)->readback(
            *device, 0, 0, {}, terrain_depth.data(), 32 * sizeof(float),
            &error));
        INFO(error);
        CHECK(std::abs(terrain_depth[16 * 32 + 16] - 0.5f) < 0.0001f);

        terrain_batch.terrain_smoothing = true;
        terrain_batch.terrain_tessellation_pinned = true;
        std::fill_n(terrain_batch.terrain_tessellation_factors, 6,
                    std::uint16_t{0x4c00});
        auto pinned_terrain_shadow = renderer->renderSpotShadow(scene, &error);
        INFO(error);
        REQUIRE(pinned_terrain_shadow);
        scene.reverse_z = true;
        terrain_batch.modelview_projection[14] = 0.5f;
        auto reverse_terrain_shadow = renderer->renderSpotShadow(scene, &error);
        INFO(error);
        REQUIRE(reverse_terrain_shadow);
        std::array<float, 32 * 32> reverse_terrain_depth{};
        REQUIRE(reverse_terrain_shadow->colorTexture(0)->readback(
            *device, 0, 0, {}, reverse_terrain_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK(std::abs(reverse_terrain_depth[16 * 32 + 16] - 0.5f) <
              0.0001f);
        CHECK(std::abs(reverse_terrain_depth[1 * 32 + 1]) < 0.0001f);
        scene.reverse_z = false;
        terrain_batch.modelview_projection[14] = 0.f;
        terrain_batch.terrain_tessellation_factors[0] = 0;
        error.clear();
        CHECK_FALSE(renderer->renderSpotShadow(scene, &error));
        CHECK(error == "Metal spot-shadow terrain batch is invalid");

        scene.batches = &batch;

        ALMetalTextureDescriptor coverage_descriptor;
        coverage_descriptor.format = ALMetalPixelFormat::rgba8_unorm;
        coverage_descriptor.width = 1;
        coverage_descriptor.height = 1;
        coverage_descriptor.storage = ALMetalStorageMode::private_gpu;
        coverage_descriptor.usage = ALMetalTextureUsage::shader_read;
        coverage_descriptor.label =
            "Alchemy spot-shadow quantized coverage texture";
        auto below_cutoff = ALMetalTexture::create(
            *device, coverage_descriptor, &error);
        auto above_cutoff = ALMetalTexture::create(
            *device, coverage_descriptor, &error);
        auto opaque_coverage = ALMetalTexture::create(
            *device, coverage_descriptor, &error);
        auto avatar_below_cutoff = ALMetalTexture::create(
            *device, coverage_descriptor, &error);
        auto avatar_at_cutoff = ALMetalTexture::create(
            *device, coverage_descriptor, &error);
        INFO(error);
        REQUIRE(below_cutoff);
        REQUIRE(above_cutoff);
        REQUIRE(opaque_coverage);
        REQUIRE(avatar_below_cutoff);
        REQUIRE(avatar_at_cutoff);
        const std::array<std::uint8_t, 4> below_pixel{{255, 255, 255, 127}};
        const std::array<std::uint8_t, 4> above_pixel{{255, 255, 255, 128}};
        const std::array<std::uint8_t, 4> opaque_pixel{{255, 255, 255, 255}};
        const std::array<std::uint8_t, 4> avatar_below_pixel{{
            255, 255, 255, 50}};
        const std::array<std::uint8_t, 4> avatar_at_pixel{{
            255, 255, 255, 51}};

        ALMetalTextureDescriptor transform_descriptor = coverage_descriptor;
        transform_descriptor.width = 4;
        transform_descriptor.label =
            "Alchemy spot-shadow PBR transform coverage texture";
        auto transform_coverage = ALMetalTexture::create(
            *device, transform_descriptor, &error);
        INFO(error);
        REQUIRE(transform_coverage);
        const std::array<std::uint8_t, 16> transform_pixels{{
            255, 255, 255, 255, 255, 255, 255, 255,
            255, 255, 255,   0, 255, 255, 255,   0,
        }};
        auto coverage_upload = device->makeCommandBuffer(
            "Alchemy spot-shadow coverage upload", &error);
        INFO(error);
        REQUIRE(coverage_upload);
        REQUIRE(below_cutoff->upload(
            *coverage_upload, 0, 0, {}, below_pixel.data(), 4, &error));
        REQUIRE(above_cutoff->upload(
            *coverage_upload, 0, 0, {}, above_pixel.data(), 4, &error));
        REQUIRE(opaque_coverage->upload(
            *coverage_upload, 0, 0, {}, opaque_pixel.data(), 4, &error));
        REQUIRE(avatar_below_cutoff->upload(
            *coverage_upload, 0, 0, {}, avatar_below_pixel.data(), 4,
            &error));
        REQUIRE(avatar_at_cutoff->upload(
            *coverage_upload, 0, 0, {}, avatar_at_pixel.data(), 4,
            &error));
        REQUIRE(transform_coverage->upload(
            *coverage_upload, 0, 0, {}, transform_pixels.data(), 16,
            &error));
        REQUIRE(coverage_upload->commitAndWait(&error));
        INFO(error);

        const std::array<std::array<float, 4>, 3> avatar_normals{{
            {{0.f, 0.f, 1.f, 0.f}},
            {{0.f, 0.f, 1.f, 0.f}},
            {{0.f, 0.f, 1.f, 0.f}},
        }};
        const std::array<std::array<float, 4>, 3> avatar_clothing{};
        const std::array<float, 3> avatar_weights{{0.f, 0.f, 0.f}};
        constexpr std::size_t avatar_texcoord_offset = sizeof(positions);
        constexpr std::size_t avatar_weight_offset = 72;
        constexpr std::size_t avatar_normal_offset = 96;
        constexpr std::size_t avatar_cloth_offset =
            avatar_normal_offset + sizeof(avatar_normals);
        std::array<std::uint8_t,
                   avatar_cloth_offset + sizeof(avatar_clothing)>
            avatar_vertex_bytes{};
        std::memcpy(avatar_vertex_bytes.data(), positions.data(),
                    sizeof(positions));
        std::memcpy(
            avatar_vertex_bytes.data() + avatar_texcoord_offset,
            texcoords.data(), sizeof(texcoords));
        std::memcpy(avatar_vertex_bytes.data() + avatar_weight_offset,
                    avatar_weights.data(), sizeof(avatar_weights));
        std::memcpy(avatar_vertex_bytes.data() + avatar_normal_offset,
                    avatar_normals.data(), sizeof(avatar_normals));
        std::memcpy(avatar_vertex_bytes.data() + avatar_cloth_offset,
                    avatar_clothing.data(), sizeof(avatar_clothing));
        descriptor.length = avatar_vertex_bytes.size();
        descriptor.label = "Alchemy avatar spot-shadow test vertices";
        auto avatar_vertices = ALMetalBuffer::create(
            *device, descriptor, &error);
        INFO(error);
        REQUIRE(avatar_vertices);
        REQUIRE(avatar_vertices->write(
            0, avatar_vertex_bytes.data(), avatar_vertex_bytes.size(),
            &error));

        std::array<std::array<float, 4>, 45> avatar_palette{};
        for (std::size_t joint = 0; joint < 15; ++joint)
        {
            avatar_palette[joint][0] = 1.f;
            avatar_palette[15 + joint][1] = 1.f;
            avatar_palette[30 + joint][2] = 1.f;
        }
        ALMetalWorldSpotShadowBatch avatar_batch;
        avatar_batch.avatar = true;
        avatar_batch.vertices = avatar_vertices.get();
        avatar_batch.vertex_count = positions.size();
        avatar_batch.indices = indices.get();
        avatar_batch.index_count = index_values.size();
        avatar_batch.texcoord_offset = avatar_texcoord_offset;
        for (std::size_t axis = 0; axis < 4; ++axis)
        {
            avatar_batch.modelview_projection[axis * 4 + axis] = 1.f;
        }
        scene.batches = &avatar_batch;
        scene.reverse_z = false;
        auto rigid_avatar = renderer->renderSpotShadow(scene, &error);
        INFO(error);
        REQUIRE(rigid_avatar);

        avatar_batch.skin_palette = &avatar_palette[0][0];
        avatar_batch.skin_palette_float_count = 45 * 4;
        avatar_batch.skin_joint_count = 15;
        avatar_batch.weight_offset = avatar_weight_offset;
        auto skinned_avatar = renderer->renderSpotShadow(scene, &error);
        INFO(error);
        REQUIRE(skinned_avatar);
        std::array<float, 32 * 32> skinned_avatar_depth{};
        REQUIRE(skinned_avatar->colorTexture(0)->readback(
            *device, 0, 0, {}, skinned_avatar_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK(std::abs(skinned_avatar_depth[16 * 32 + 16] - 0.5f) <
              0.0001f);

        avatar_batch.avatar_cloth = true;
        avatar_batch.normal_offset = avatar_normal_offset;
        avatar_batch.cloth_offset = avatar_cloth_offset;
        auto cloth_avatar = renderer->renderSpotShadow(scene, &error);
        INFO(error);
        REQUIRE(cloth_avatar);
        avatar_batch.avatar_cloth = false;

        avatar_batch.coverage =
            ALMetalWorldSpotShadowCoverage::avatar_mask;
        avatar_batch.texture_count = 1;
        avatar_batch.alpha_cutoffs[0] = 0.2f;
        avatar_batch.textures[0] = avatar_below_cutoff.get();
        auto rejected_avatar_mask = renderer->renderSpotShadow(scene, &error);
        INFO(error);
        REQUIRE(rejected_avatar_mask);
        std::array<float, 32 * 32> rejected_avatar_mask_depth{};
        REQUIRE(rejected_avatar_mask->colorTexture(0)->readback(
            *device, 0, 0, {}, rejected_avatar_mask_depth.data(),
            32 * sizeof(float), &error));
        CHECK(std::abs(rejected_avatar_mask_depth[16 * 32 + 16] - 1.f) <
              0.0001f);

        avatar_batch.textures[0] = avatar_at_cutoff.get();
        auto accepted_avatar_mask = renderer->renderSpotShadow(scene, &error);
        INFO(error);
        REQUIRE(accepted_avatar_mask);
        std::array<float, 32 * 32> accepted_avatar_mask_depth{};
        REQUIRE(accepted_avatar_mask->colorTexture(0)->readback(
            *device, 0, 0, {}, accepted_avatar_mask_depth.data(),
            32 * sizeof(float), &error));
        CHECK(std::abs(accepted_avatar_mask_depth[16 * 32 + 16] - 0.5f) <
              0.0001f);

        avatar_batch.coverage =
            ALMetalWorldSpotShadowCoverage::avatar_blend;
        avatar_batch.textures[0] = opaque_coverage.get();
        avatar_batch.avatar_draw_alpha = 0.5f;
        auto blended_avatar = renderer->renderSpotShadow(scene, &error);
        INFO(error);
        REQUIRE(blended_avatar);
        std::array<float, 32 * 32> blended_avatar_depth{};
        REQUIRE(blended_avatar->colorTexture(0)->readback(
            *device, 0, 0, {}, blended_avatar_depth.data(),
            32 * sizeof(float), &error));
        CHECK(std::abs(blended_avatar_depth[16 * 32 + 16] - 0.5f) <
              0.0001f);
        CHECK(std::abs(blended_avatar_depth[16 * 32 + 17] - 1.f) <
              0.0001f);

        avatar_batch.skin_palette_float_count = 45 * 4 - 1;
        error.clear();
        CHECK_FALSE(renderer->renderSpotShadow(scene, &error));
        CHECK(error.find("Metal spot-shadow skinning data is invalid") == 0);
        CHECK(error.find("palette=179/180") != std::string::npos);
        CHECK(error.find("palette-size-valid=0") != std::string::npos);

        scene.reverse_z = false;
        scene.batches = &batch;
        batch.modelview_projection[14] = 0.f;
        batch.texcoord_offset = texcoord_offset;
        batch.color_offset = color_offset;
        batch.texture_count = 1;
        batch.alpha_cutoffs[0] = 0.5f;
        batch.coverage = ALMetalWorldSpotShadowCoverage::texture_mask;
        batch.textures[0] = below_cutoff.get();
        auto rejected_mask = renderer->renderSpotShadow(scene, &error);
        INFO(error);
        REQUIRE(rejected_mask);
        std::array<float, 32 * 32> rejected_mask_depth{};
        REQUIRE(rejected_mask->colorTexture(0)->readback(
            *device, 0, 0, {}, rejected_mask_depth.data(),
            32 * sizeof(float), &error));
        CHECK(std::abs(rejected_mask_depth[16 * 32 + 16] - 1.f) <
              0.0001f);

        batch.textures[0] = above_cutoff.get();
        auto accepted_mask = renderer->renderSpotShadow(scene, &error);
        INFO(error);
        REQUIRE(accepted_mask);
        std::array<float, 32 * 32> accepted_mask_depth{};
        REQUIRE(accepted_mask->colorTexture(0)->readback(
            *device, 0, 0, {}, accepted_mask_depth.data(),
            32 * sizeof(float), &error));
        CHECK(std::abs(accepted_mask_depth[16 * 32 + 16] - 0.5f) <
              0.0001f);

        const std::array<std::array<std::uint8_t, 4>, 3>
            transparent_vertex_colors{{
                {{255, 255, 255, 0}},
                {{255, 255, 255, 0}},
                {{255, 255, 255, 0}},
            }};
        REQUIRE(vertices->write(
            color_offset, transparent_vertex_colors.data(),
            sizeof(transparent_vertex_colors), &error));
        batch.coverage = ALMetalWorldSpotShadowCoverage::legacy_mask;
        auto tinted_mask = renderer->renderSpotShadow(scene, &error);
        INFO(error);
        REQUIRE(tinted_mask);
        std::array<float, 32 * 32> tinted_mask_depth{};
        REQUIRE(tinted_mask->colorTexture(0)->readback(
            *device, 0, 0, {}, tinted_mask_depth.data(),
            32 * sizeof(float), &error));
        CHECK(std::abs(tinted_mask_depth[16 * 32 + 16] - 1.f) < 0.0001f);

        batch.coverage =
            ALMetalWorldSpotShadowCoverage::legacy_fullbright_mask;
        auto fullbright_mask = renderer->renderSpotShadow(scene, &error);
        INFO(error);
        REQUIRE(fullbright_mask);
        std::array<float, 32 * 32> fullbright_mask_depth{};
        REQUIRE(fullbright_mask->colorTexture(0)->readback(
            *device, 0, 0, {}, fullbright_mask_depth.data(),
            32 * sizeof(float), &error));
        CHECK(std::abs(fullbright_mask_depth[16 * 32 + 16] - 0.5f) <
              0.0001f);

        REQUIRE(vertices->write(
            color_offset, white_colors.data(), sizeof(white_colors),
            &error));
        batch.coverage = ALMetalWorldSpotShadowCoverage::pbr_mask;
        batch.textures[0] = transform_coverage.get();
        batch.pbr_base_color_transforms[0][0][0] = 1.f;
        batch.pbr_base_color_transforms[0][0][1] = 1.f;
        auto unshifted_pbr = renderer->renderSpotShadow(scene, &error);
        INFO(error);
        REQUIRE(unshifted_pbr);
        std::array<float, 32 * 32> unshifted_pbr_depth{};
        REQUIRE(unshifted_pbr->colorTexture(0)->readback(
            *device, 0, 0, {}, unshifted_pbr_depth.data(),
            32 * sizeof(float), &error));
        CHECK(std::abs(unshifted_pbr_depth[16 * 32 + 16] - 0.5f) <
              0.0001f);

        batch.pbr_base_color_transforms[0][1][0] = 0.5f;
        auto shifted_pbr = renderer->renderSpotShadow(scene, &error);
        INFO(error);
        REQUIRE(shifted_pbr);
        std::array<float, 32 * 32> shifted_pbr_depth{};
        REQUIRE(shifted_pbr->colorTexture(0)->readback(
            *device, 0, 0, {}, shifted_pbr_depth.data(),
            32 * sizeof(float), &error));
        CHECK(std::abs(shifted_pbr_depth[16 * 32 + 16] - 1.f) <
              0.0001f);
        batch.pbr_base_color_transforms[0][1][0] = 0.f;

        const std::array<std::array<std::uint8_t, 4>, 3>
            half_alpha_colors{{
                {{255, 255, 255, 128}},
                {{255, 255, 255, 128}},
                {{255, 255, 255, 128}},
            }};
        REQUIRE(vertices->write(
            color_offset, half_alpha_colors.data(),
            sizeof(half_alpha_colors), &error));
        batch.coverage = ALMetalWorldSpotShadowCoverage::legacy_blend;
        batch.textures[0] = opaque_coverage.get();
        batch.alpha_cutoffs[0] = 0.598f;
        auto stippled = renderer->renderSpotShadow(scene, &error);
        INFO(error);
        REQUIRE(stippled);
        std::array<float, 32 * 32> stippled_depth{};
        REQUIRE(stippled->colorTexture(0)->readback(
            *device, 0, 0, {}, stippled_depth.data(),
            32 * sizeof(float), &error));
        CHECK(std::abs(stippled_depth[16 * 32 + 16] - 0.5f) < 0.0001f);
        CHECK(std::abs(stippled_depth[16 * 32 + 17] - 1.f) < 0.0001f);

        REQUIRE(vertices->write(
            color_offset, white_colors.data(), sizeof(white_colors),
            &error));
        batch.coverage = ALMetalWorldSpotShadowCoverage::texture_mask;
        batch.alpha_cutoffs[0] = 0.5f;
        batch.weight_offset = weight_offset;
        batch.skin_palette = skin_palette.data();
        batch.skin_palette_float_count = skin_palette.size();
        batch.skin_joint_count = 1;
        auto covered_rigged = renderer->renderSpotShadow(scene, &error);
        INFO(error);
        REQUIRE(covered_rigged);
        std::array<float, 32 * 32> covered_rigged_depth{};
        REQUIRE(covered_rigged->colorTexture(0)->readback(
            *device, 0, 0, {}, covered_rigged_depth.data(),
            32 * sizeof(float), &error));
        CHECK(std::abs(covered_rigged_depth[16 * 32 + 24] - 0.5f) <
              0.0001f);
        CHECK(std::abs(covered_rigged_depth[16 * 32 + 8] - 1.f) <
              0.0001f);

        batch.skin_palette = nullptr;
        batch.skin_palette_float_count = 0;
        batch.skin_joint_count = 0;
        batch.weight_offset = 0;
        batch.textures[0] = nullptr;
        error.clear();
        CHECK_FALSE(renderer->renderSpotShadow(scene, &error));
        CHECK(error == "Metal spot-shadow coverage texture is invalid");

        batch.coverage = ALMetalWorldSpotShadowCoverage::opaque;
        batch.texture_count = 0;
        batch.index_count = 4;
        error.clear();
        CHECK_FALSE(renderer->renderSpotShadow(scene, &error));
        CHECK(error == "Metal spot-shadow batch geometry is invalid");
    }
}

TEST_CASE("almetal: world simple pass writes the native four-attachment G-buffer", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        auto renderer = ALMetalWorldGBufferRenderer::create(*device, &error);
        INFO(error);
        REQUIRE(renderer);

        const std::array<std::array<float, 4>, 3> positions{{
            {{-0.8f, -0.8f, 0.25f, 1.f}},
            {{ 0.8f, -0.8f, 0.25f, 1.f}},
            {{ 0.0f,  0.8f, 0.25f, 1.f}},
        }};
        const std::array<std::array<float, 4>, 3> normals{{
            {{0.f, 0.f, 1.f, 0.f}},
            {{0.f, 0.f, 1.f, 0.f}},
            {{0.f, 0.f, 1.f, 0.f}},
        }};
        const std::array<std::array<float, 2>, 3> texcoords{{
            {{0.f, 0.f}}, {{0.f, 0.f}}, {{0.f, 0.f}},
        }};
        const std::array<std::array<std::uint8_t, 4>, 3> colors{{
            {{128, 255, 255, 128}},
            {{128, 255, 255, 128}},
            {{128, 255, 255, 128}},
        }};
        const std::array<std::array<float, 4>, 3> tangents{{
            {{1.f, 0.f, 0.f, 1.f}},
            {{1.f, 0.f, 0.f, 1.f}},
            {{1.f, 0.f, 0.f, 1.f}},
        }};
        const std::array<std::array<float, 4>, 3> weights{{
            {{0.5f, 0.f, 0.f, 0.f}},
            {{0.5f, 0.f, 0.f, 0.f}},
            {{0.5f, 0.f, 0.f, 0.f}},
        }};
        const std::array<std::array<float, 2>, 3> emboss_texcoords{{
            {{0.5f, 0.f}}, {{0.5f, 0.f}}, {{0.5f, 0.f}},
        }};
        const std::array<std::array<std::uint8_t, 4>, 3> emissive{{
            {{0, 0, 0, 128}},
            {{0, 0, 0, 128}},
            {{0, 0, 0, 128}},
        }};
        const std::array<float, 3> avatar_weights{{0.f, 0.f, 0.f}};
        const std::array<std::array<float, 4>, 3> avatar_clothing{{
            {{0.25f, 0.f, 0.f, 1.f}},
            {{0.25f, 0.f, 0.f, 1.f}},
            {{0.25f, 0.f, 0.f, 1.f}},
        }};
        constexpr std::size_t normal_offset = sizeof(positions);
        constexpr std::size_t texcoord_offset =
            normal_offset + sizeof(normals);
        constexpr std::size_t color_offset =
            texcoord_offset + sizeof(texcoords);
        constexpr std::size_t tangent_offset =
            (color_offset + sizeof(colors) + 15) & ~std::size_t{15};
        constexpr std::size_t weight_offset =
            tangent_offset + sizeof(tangents);
        constexpr std::size_t emboss_texcoord_offset =
            weight_offset + sizeof(weights);
        constexpr std::size_t emissive_offset =
            emboss_texcoord_offset + sizeof(emboss_texcoords);
        constexpr std::size_t vertex_storage_size =
            (emissive_offset + sizeof(emissive) + 15) & ~std::size_t{15};
        constexpr std::size_t avatar_weight_offset =
            texcoord_offset + sizeof(texcoords);
        constexpr std::size_t avatar_cloth_offset =
            (avatar_weight_offset + sizeof(avatar_weights) + 15) &
            ~std::size_t{15};
        std::array<std::uint8_t, vertex_storage_size> vertex_bytes{};
        std::memcpy(vertex_bytes.data(), positions.data(), sizeof(positions));
        std::memcpy(vertex_bytes.data() + normal_offset,
                    normals.data(), sizeof(normals));
        std::memcpy(vertex_bytes.data() + texcoord_offset,
                    texcoords.data(), sizeof(texcoords));
        std::memcpy(vertex_bytes.data() + color_offset,
                    colors.data(), sizeof(colors));
        std::memcpy(vertex_bytes.data() + tangent_offset,
                    tangents.data(), sizeof(tangents));
        std::memcpy(vertex_bytes.data() + weight_offset,
                    weights.data(), sizeof(weights));
        std::memcpy(vertex_bytes.data() + emboss_texcoord_offset,
                    emboss_texcoords.data(), sizeof(emboss_texcoords));
        std::memcpy(vertex_bytes.data() + emissive_offset,
                    emissive.data(), sizeof(emissive));
        std::array<std::uint8_t,
                   avatar_cloth_offset + sizeof(avatar_clothing)>
            avatar_vertex_bytes{};
        std::memcpy(avatar_vertex_bytes.data(),
                    positions.data(), sizeof(positions));
        std::memcpy(avatar_vertex_bytes.data() + normal_offset,
                    normals.data(), sizeof(normals));
        std::memcpy(avatar_vertex_bytes.data() + texcoord_offset,
                    texcoords.data(), sizeof(texcoords));
        std::memcpy(avatar_vertex_bytes.data() + avatar_weight_offset,
                    avatar_weights.data(), sizeof(avatar_weights));
        std::memcpy(avatar_vertex_bytes.data() + avatar_cloth_offset,
                    avatar_clothing.data(), sizeof(avatar_clothing));

        ALMetalBufferDescriptor vertex_descriptor;
        vertex_descriptor.length = vertex_bytes.size();
        vertex_descriptor.storage = ALMetalStorageMode::shared;
        vertex_descriptor.label = "Alchemy world simple test vertices";
        auto vertices = ALMetalBuffer::create(
            *device, vertex_descriptor, &error);
        INFO(error);
        REQUIRE(vertices);
        REQUIRE(vertices->write(
            0, vertex_bytes.data(), vertex_bytes.size(), &error));
        ALMetalBufferDescriptor avatar_vertex_descriptor = vertex_descriptor;
        avatar_vertex_descriptor.length = avatar_vertex_bytes.size();
        avatar_vertex_descriptor.label =
            "Alchemy world avatar test vertices";
        auto avatar_vertices = ALMetalBuffer::create(
            *device, avatar_vertex_descriptor, &error);
        INFO(error);
        REQUIRE(avatar_vertices);
        REQUIRE(avatar_vertices->write(
            0, avatar_vertex_bytes.data(), avatar_vertex_bytes.size(),
            &error));

        const std::array<std::uint16_t, 3> index_values{{0, 1, 2}};
        ALMetalBufferDescriptor index_descriptor;
        index_descriptor.length = sizeof(index_values);
        index_descriptor.storage = ALMetalStorageMode::shared;
        index_descriptor.label = "Alchemy world simple test indices";
        auto indices = ALMetalBuffer::create(
            *device, index_descriptor, &error);
        INFO(error);
        REQUIRE(indices);
        REQUIRE(indices->write(
            0, index_values.data(), sizeof(index_values), &error));
        const std::array<std::uint16_t, 3> reversed_index_values{{0, 2, 1}};
        ALMetalBufferDescriptor reversed_index_descriptor = index_descriptor;
        reversed_index_descriptor.label =
            "Alchemy reversed world particle glow indices";
        auto reversed_indices = ALMetalBuffer::create(
            *device, reversed_index_descriptor, &error);
        INFO(error);
        REQUIRE(reversed_indices);
        REQUIRE(reversed_indices->write(
            0, reversed_index_values.data(),
            sizeof(reversed_index_values), &error));

        ALMetalTextureDescriptor diffuse_descriptor;
        diffuse_descriptor.format = ALMetalPixelFormat::rgba8_unorm_srgb;
        diffuse_descriptor.width = 1;
        diffuse_descriptor.height = 1;
        diffuse_descriptor.storage = ALMetalStorageMode::private_gpu;
        diffuse_descriptor.usage = ALMetalTextureUsage::shader_read;
        diffuse_descriptor.label = "Alchemy world simple sRGB diffuse";
        auto diffuse = ALMetalTexture::create(
            *device, diffuse_descriptor, &error);
        INFO(error);
        REQUIRE(diffuse);
        const std::array<std::uint8_t, 4> diffuse_pixel{{128, 64, 32, 255}};
        diffuse_descriptor.label =
            "Alchemy world simple indexed sRGB diffuse";
        auto indexed_diffuse = ALMetalTexture::create(
            *device, diffuse_descriptor, &error);
        INFO(error);
        REQUIRE(indexed_diffuse);
        const std::array<std::uint8_t, 4> indexed_diffuse_pixel{{
            0, 255, 0, 255,
        }};
        diffuse_descriptor.label =
            "Alchemy world highlight white sRGB texture";
        auto highlight_texture = ALMetalTexture::create(
            *device, diffuse_descriptor, &error);
        INFO(error);
        REQUIRE(highlight_texture);
        const std::array<std::uint8_t, 4> highlight_pixel{{
            255, 255, 255, 255,
        }};
        diffuse_descriptor.label =
            "Alchemy world tree half-alpha sRGB diffuse";
        auto tree_diffuse = ALMetalTexture::create(
            *device, diffuse_descriptor, &error);
        INFO(error);
        REQUIRE(tree_diffuse);
        const std::array<std::uint8_t, 4> tree_diffuse_pixel{{
            128, 64, 32, 128,
        }};
        diffuse_descriptor.label =
            "Alchemy world custom-blend zero-alpha sRGB diffuse";
        auto zero_alpha_diffuse = ALMetalTexture::create(
            *device, diffuse_descriptor, &error);
        INFO(error);
        REQUIRE(zero_alpha_diffuse);
        const std::array<std::uint8_t, 4> zero_alpha_diffuse_pixel{{
            128, 64, 32, 0,
        }};
        ALMetalTextureDescriptor normal_descriptor = diffuse_descriptor;
        normal_descriptor.format = ALMetalPixelFormat::rgba8_unorm;
        normal_descriptor.label = "Alchemy world bump tangent normal";
        auto bump_normal = ALMetalTexture::create(
            *device, normal_descriptor, &error);
        INFO(error);
        REQUIRE(bump_normal);
        const std::array<std::uint8_t, 4> bump_normal_pixel{{
            255, 128, 128, 128,
        }};
        ALMetalTextureDescriptor srgb_bump_normal_descriptor =
            normal_descriptor;
        srgb_bump_normal_descriptor.format =
            ALMetalPixelFormat::rgba8_unorm_srgb;
        srgb_bump_normal_descriptor.label =
            "Alchemy world sRGB-backed tangent normal";
        auto srgb_bump_normal = ALMetalTexture::create(
            *device, srgb_bump_normal_descriptor, &error);
        INFO(error);
        REQUIRE(srgb_bump_normal);
        srgb_bump_normal_descriptor.label =
            "Alchemy world sRGB-backed flat tangent normal";
        auto srgb_flat_normal = ALMetalTexture::create(
            *device, srgb_bump_normal_descriptor, &error);
        INFO(error);
        REQUIRE(srgb_flat_normal);
        normal_descriptor.label = "Alchemy world flat tangent normal";
        auto flat_normal = ALMetalTexture::create(
            *device, normal_descriptor, &error);
        INFO(error);
        REQUIRE(flat_normal);
        const std::array<std::uint8_t, 4> flat_normal_pixel{{
            128, 128, 255, 255,
        }};
        normal_descriptor.width = 2;
        normal_descriptor.label = "Alchemy world two-tap emboss bump";
        auto emboss_bump = ALMetalTexture::create(
            *device, normal_descriptor, &error);
        INFO(error);
        REQUIRE(emboss_bump);
        const std::array<std::uint8_t, 8> emboss_bump_pixels{{
            0, 0, 0, 128,
            0, 0, 0, 192,
        }};
        normal_descriptor.width = 1;
        ALMetalTextureDescriptor material_specular_descriptor =
            diffuse_descriptor;
        material_specular_descriptor.label =
            "Alchemy world material white sRGB specular";
        auto material_specular_texture = ALMetalTexture::create(
            *device, material_specular_descriptor, &error);
        INFO(error);
        REQUIRE(material_specular_texture);
        const std::array<std::uint8_t, 4> material_specular_pixel{{
            255, 255, 255, 128,
        }};
        ALMetalTextureDescriptor pbr_orm_descriptor = normal_descriptor;
        pbr_orm_descriptor.label = "Alchemy world PBR ORM";
        auto pbr_orm_texture = ALMetalTexture::create(
            *device, pbr_orm_descriptor, &error);
        INFO(error);
        REQUIRE(pbr_orm_texture);
        ALMetalTextureDescriptor srgb_pbr_orm_descriptor =
            pbr_orm_descriptor;
        srgb_pbr_orm_descriptor.format =
            ALMetalPixelFormat::rgba8_unorm_srgb;
        srgb_pbr_orm_descriptor.label =
            "Alchemy world sRGB-backed PBR ORM";
        auto srgb_pbr_orm_texture = ALMetalTexture::create(
            *device, srgb_pbr_orm_descriptor, &error);
        INFO(error);
        REQUIRE(srgb_pbr_orm_texture);
        const std::array<std::uint8_t, 4> pbr_orm_pixel{{
            128, 128, 64, 255,
        }};
        ALMetalTextureDescriptor pbr_base_descriptor = diffuse_descriptor;
        pbr_base_descriptor.width = 2;
        pbr_base_descriptor.label =
            "Alchemy world PBR transformed sRGB base color";
        auto pbr_base_texture = ALMetalTexture::create(
            *device, pbr_base_descriptor, &error);
        INFO(error);
        REQUIRE(pbr_base_texture);
        const std::array<std::uint8_t, 8> pbr_base_pixels{{
            255, 0, 0, 255,
            0, 255, 0, 128,
        }};
        auto upload = device->makeCommandBuffer(
            "Alchemy world simple diffuse upload", &error);
        INFO(error);
        REQUIRE(upload);
        REQUIRE(diffuse->upload(
            *upload, 0, 0, {}, diffuse_pixel.data(), 4, &error));
        REQUIRE(indexed_diffuse->upload(
            *upload, 0, 0, {}, indexed_diffuse_pixel.data(), 4, &error));
        REQUIRE(highlight_texture->upload(
            *upload, 0, 0, {}, highlight_pixel.data(), 4, &error));
        REQUIRE(tree_diffuse->upload(
            *upload, 0, 0, {}, tree_diffuse_pixel.data(), 4, &error));
        REQUIRE(zero_alpha_diffuse->upload(
            *upload, 0, 0, {}, zero_alpha_diffuse_pixel.data(), 4,
            &error));
        REQUIRE(bump_normal->upload(
            *upload, 0, 0, {}, bump_normal_pixel.data(), 4, &error));
        REQUIRE(srgb_bump_normal->upload(
            *upload, 0, 0, {}, bump_normal_pixel.data(), 4, &error));
        REQUIRE(srgb_flat_normal->upload(
            *upload, 0, 0, {}, flat_normal_pixel.data(), 4, &error));
        REQUIRE(flat_normal->upload(
            *upload, 0, 0, {}, flat_normal_pixel.data(), 4, &error));
        REQUIRE(emboss_bump->upload(
            *upload, 0, 0, {}, emboss_bump_pixels.data(), 8, &error));
        REQUIRE(material_specular_texture->upload(
            *upload, 0, 0, {}, material_specular_pixel.data(), 4, &error));
        REQUIRE(pbr_orm_texture->upload(
            *upload, 0, 0, {}, pbr_orm_pixel.data(), 4, &error));
        REQUIRE(srgb_pbr_orm_texture->upload(
            *upload, 0, 0, {}, pbr_orm_pixel.data(), 4, &error));
        REQUIRE(pbr_base_texture->upload(
            *upload, 0, 0, {}, pbr_base_pixels.data(), 8, &error));
        REQUIRE(upload->commitAndWait(&error));
        INFO(error);

        ALMetalWorldSimpleBatch batch;
        batch.vertices = vertices.get();
        batch.position_offset = 0;
        batch.normal_offset = normal_offset;
        batch.texcoord_offset = texcoord_offset;
        batch.color_offset = color_offset;
        batch.vertex_count = positions.size();
        batch.indices = indices.get();
        batch.index_count = index_values.size();
        batch.diffuse_textures[0] = diffuse.get();
        batch.texture_count = 1;
        for (std::size_t index = 0; index < 4; ++index)
        {
            batch.modelview_projection[index * 4 + index] = 1.f;
            batch.modelview[index * 4 + index] = 1.f;
        }
        for (std::size_t index = 0; index < 3; ++index)
        {
            batch.normal_matrix[index][index] = 1.f;
        }

        ALMetalWorldGBufferScene scene;
        scene.batches = &batch;
        scene.batch_count = 1;
        scene.width = 32;
        scene.height = 32;
        scene.normal_hdr = true;
        scene.hdr = true;

        batch.color_offset = vertex_bytes.size();
        CHECK_FALSE(renderer->render(scene, &error));
        CHECK(error ==
              "Metal world simple geometry range exceeds its buffers");
        batch.color_offset = color_offset;
        error.clear();

        auto result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(result);
        CHECK(result->descriptor().color_attachment_count == 4);
        CHECK(result->descriptor().colors[0].format ==
              ALMetalPixelFormat::rgba8_unorm_srgb);
        CHECK(result->descriptor().colors[1].format ==
              ALMetalPixelFormat::rgba8_unorm);
        CHECK(result->descriptor().colors[2].format ==
              ALMetalPixelFormat::rgba16_unorm);
        CHECK(result->descriptor().colors[3].format ==
              ALMetalPixelFormat::rg11b10_float);
        REQUIRE(result->depthStencilTexture());

        std::array<std::uint8_t, 32 * 32 * 4> albedo{};
        REQUIRE(result->colorTexture(0)->readback(
            *device, 0, 0, {}, albedo.data(), 32 * 4, &error));
        INFO(error);
        std::array<std::uint8_t, 32 * 32 * 4> specular{};
        REQUIRE(result->colorTexture(1)->readback(
            *device, 0, 0, {}, specular.data(), 32 * 4, &error));
        INFO(error);
        std::array<std::uint16_t, 32 * 32 * 4> normal{};
        REQUIRE(result->colorTexture(2)->readback(
            *device, 0, 0, {}, normal.data(), 32 * 8, &error));
        INFO(error);

        const std::size_t center = (16 * 32 + 16) * 4;
        // Both diffuse and tint are decoded with the exact sRGB transfer;
        // attachment zero then performs the hardware sRGB encode on store.
        CHECK(std::abs(static_cast<int>(albedo[center + 0]) - 61) <= 1);
        CHECK(std::abs(static_cast<int>(albedo[center + 1]) - 64) <= 1);
        CHECK(std::abs(static_cast<int>(albedo[center + 2]) - 32) <= 1);
        CHECK(albedo[center + 3] == 0);
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(std::abs(static_cast<int>(specular[center + channel]) -
                           128) <= 1);
        }
        CHECK(std::abs(static_cast<int>(normal[center + 0]) - 32768) <= 1);
        CHECK(std::abs(static_cast<int>(normal[center + 1]) - 32768) <= 1);
        CHECK(std::abs(static_cast<int>(normal[center + 2]) - 32896) <= 1);
        CHECK(std::abs(static_cast<int>(normal[center + 3]) - 22282) <= 2);

        // A hero mirror keeps only the eye-space half-space accepted by the
        // GLSL MIRROR_CLIP variant. Metal clip distances must reject the
        // negative side before any G-buffer fragment is written, while the
        // ordinary positive side retains the same material result.
        scene.mirror_clip = true;
        scene.mirror_clip_plane[0] = 1.f;
        scene.mirror_clip_plane[1] = 0.f;
        scene.mirror_clip_plane[2] = 0.f;
        scene.mirror_clip_plane[3] = 0.f;
        auto mirror_clipped = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(mirror_clipped);
        std::array<std::uint8_t, 32 * 32 * 4> clipped_albedo{};
        REQUIRE(mirror_clipped->colorTexture(0)->readback(
            *device, 0, 0, {}, clipped_albedo.data(), 32 * 4, &error));
        INFO(error);
        const std::size_t clipped_side = (10 * 32 + 10) * 4;
        const std::size_t retained_side = (10 * 32 + 22) * 4;
        CHECK(clipped_albedo[clipped_side + 0] == 255);
        CHECK(clipped_albedo[clipped_side + 1] == 0);
        CHECK(clipped_albedo[clipped_side + 2] == 255);
        CHECK(std::abs(
            static_cast<int>(clipped_albedo[retained_side + 0]) - 61) <= 1);
        CHECK(std::abs(
            static_cast<int>(clipped_albedo[retained_side + 1]) - 64) <= 1);
        CHECK(std::abs(
            static_cast<int>(clipped_albedo[retained_side + 2]) - 32) <= 1);
        scene.mirror_clip = false;

        std::array<float, 32 * 32> forward_depth{};
        REQUIRE(result->depthStencilTexture()->readback(
            *device, 0, 0, {}, forward_depth.data(), 32 * sizeof(float),
            &error));
        INFO(error);
        CHECK(std::abs(forward_depth[16 * 32 + 16] - 0.625f) < 0.0001f);

        // Wireframe is a rasterizer mode, not a display-space edge effect.
        // Preserve GL's raw 0.5 clear in the sRGB albedo attachment, retain
        // only the triangle boundary, and leave its interior at far depth.
        scene.wireframe = true;
        scene.clear_color[0] = 0.5f;
        scene.clear_color[1] = 0.5f;
        scene.clear_color[2] = 0.5f;
        scene.clear_color[3] = 1.f;
        auto wireframe_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(wireframe_result);
        std::array<std::uint8_t, 32 * 32 * 4> wireframe_albedo{};
        std::array<float, 32 * 32> wireframe_depth{};
        REQUIRE(wireframe_result->colorTexture(0)->readback(
            *device, 0, 0, {}, wireframe_albedo.data(), 32 * 4, &error));
        REQUIRE(wireframe_result->depthStencilTexture()->readback(
            *device, 0, 0, {}, wireframe_depth.data(), 32 * sizeof(float),
            &error));
        INFO(error);
        CHECK(wireframe_albedo[center + 0] == 128u);
        CHECK(wireframe_albedo[center + 1] == 128u);
        CHECK(wireframe_albedo[center + 2] == 128u);
        CHECK(wireframe_albedo[center + 3] == 255u);
        CHECK(std::abs(wireframe_depth[16 * 32 + 16] - 1.f) < 0.0001f);
        const auto covered_depth = [](float depth)
        {
            return std::abs(depth - 1.f) >= 0.0001f;
        };
        const std::size_t filled_coverage = std::count_if(
            forward_depth.begin(), forward_depth.end(), covered_depth);
        const std::size_t wireframe_coverage = std::count_if(
            wireframe_depth.begin(), wireframe_depth.end(), covered_depth);
        CHECK(wireframe_coverage > 0);
        CHECK(wireframe_coverage < filled_coverage);
        scene.wireframe = false;
        scene.clear_color[0] = 1.f;
        scene.clear_color[1] = 0.f;
        scene.clear_color[2] = 1.f;
        scene.clear_color[3] = 1.f;

        // The production main-world path may retain several dependent
        // encoders in one command buffer. Standalone rendering above keeps
        // its immediate commit behavior; the explicit batch publishes only
        // when its owner commits and rejects accidental nesting.
        error.clear();
        REQUIRE(renderer->beginCommandBatch(
            "Alchemy world command-batch regression", &error));
        CHECK(renderer->commandBatchActive());
        error.clear();
        CHECK_FALSE(renderer->beginCommandBatch(
            "Alchemy nested command-batch regression", &error));
        CHECK(error == "Metal world command batch is already active");
        error.clear();
        auto batched_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(batched_result);
        CHECK(renderer->commandBatchActive());
        REQUIRE(renderer->commitCommandBatch(&error));
        INFO(error);
        CHECK_FALSE(renderer->commandBatchActive());
        std::array<float, 32 * 32> batched_depth{};
        REQUIRE(batched_result->depthStencilTexture()->readback(
            *device, 0, 0, {}, batched_depth.data(), 32 * sizeof(float),
            &error));
        CHECK(std::abs(batched_depth[16 * 32 + 16] - 0.625f) < 0.0001f);
        error.clear();
        REQUIRE(renderer->beginCommandBatch(
            "Alchemy cancelled command-batch regression", &error));
        renderer->cancelCommandBatch();
        CHECK_FALSE(renderer->commandBatchActive());

        // Forward GL clip depth is remapped from [-w,+w]. A reverse-Z world
        // projection already emits Metal's [0,+w] convention and must not be
        // remapped a second time.
        scene.reverse_z = true;
        auto reverse_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(reverse_result);
        std::array<float, 32 * 32> reverse_depth{};
        REQUIRE(reverse_result->depthStencilTexture()->readback(
            *device, 0, 0, {}, reverse_depth.data(), 32 * sizeof(float),
            &error));
        INFO(error);
        CHECK(std::abs(reverse_depth[16 * 32 + 16] - 0.25f) < 0.0001f);

        // The impostor bake turns every opaque depth-covered texel into full
        // albedo coverage before forward alpha accumulates over it. Stamp it
        // on the GPU with strict far-plane depth tests: equal clear depth
        // remains transparent in both forward and reverse Z.
        scene.stamp_opaque_coverage = true;
        scene.reverse_z = false;
        std::fill(std::begin(scene.clear_color),
                  std::end(scene.clear_color), 0.f);
        auto coverage_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(coverage_result);
        std::array<std::uint8_t, 32 * 32 * 4> coverage_albedo{};
        REQUIRE(coverage_result->colorTexture(0)->readback(
            *device, 0, 0, {}, coverage_albedo.data(), 32 * 4, &error));
        INFO(error);
        CHECK(coverage_albedo[center + 0] == albedo[center + 0]);
        CHECK(coverage_albedo[center + 1] == albedo[center + 1]);
        CHECK(coverage_albedo[center + 2] == albedo[center + 2]);
        CHECK(coverage_albedo[center + 3] == 255);
        CHECK(coverage_albedo[3] == 0);

        scene.reverse_z = true;
        auto reverse_coverage_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(reverse_coverage_result);
        coverage_albedo.fill(0);
        REQUIRE(reverse_coverage_result->colorTexture(0)->readback(
            *device, 0, 0, {}, coverage_albedo.data(), 32 * 4, &error));
        INFO(error);
        CHECK(coverage_albedo[center + 3] == 255);
        CHECK(coverage_albedo[3] == 0);

        scene.stamp_opaque_coverage = false;
        scene.clear_color[0] = 1.f;
        scene.clear_color[1] = 0.f;
        scene.clear_color[2] = 1.f;
        scene.clear_color[3] = 1.f;

        // TYPE_TEXTURE_INDEX aliases the fourth 32-bit word of the packed
        // position stream. Verify the Metal vertex function reads that exact
        // per-vertex word with the position's 16-byte stride and selects the
        // corresponding entry from the viewer's 32-texture ladder.
        constexpr std::int32_t indexed_texture = 1;
        for (std::size_t vertex = 0; vertex < positions.size(); ++vertex)
        {
            std::memcpy(vertex_bytes.data() + vertex * sizeof(positions[0]) +
                            sizeof(float) * 3,
                        &indexed_texture, sizeof(indexed_texture));
        }
        REQUIRE(vertices->write(
            0, vertex_bytes.data(), vertex_bytes.size(), &error));
        batch.diffuse_textures[1] = indexed_diffuse.get();
        batch.texture_count = 2;
        scene.reverse_z = false;
        auto indexed_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(indexed_result);
        std::array<std::uint8_t, 32 * 32 * 4> indexed_albedo{};
        REQUIRE(indexed_result->colorTexture(0)->readback(
            *device, 0, 0, {}, indexed_albedo.data(), 32 * 4, &error));
        INFO(error);
        CHECK(indexed_albedo[center + 0] == 0);
        CHECK(indexed_albedo[center + 1] == 255);
        CHECK(indexed_albedo[center + 2] == 0);
        CHECK(indexed_albedo[center + 3] == 0);

        // The legacy bump owner consumes the mirrored tangent stream and its
        // generated linear normal map. This +X tangent-space normal must turn
        // the encoded view normal away from the geometric +Z value while
        // retaining the vertex-alpha specular/gloss contract.
        batch.tangent_offset =
            (vertex_bytes.size() + 15) & ~std::size_t{15};
        batch.normal_texture = bump_normal.get();
        CHECK_FALSE(renderer->render(scene, &error));
        CHECK(error ==
              "Metal world simple geometry range exceeds its buffers");
        batch.tangent_offset = tangent_offset;
        error.clear();
        auto bump_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(bump_result);
        std::array<std::uint8_t, 32 * 32 * 4> bump_specular{};
        std::array<std::uint16_t, 32 * 32 * 4> bump_normal_output{};
        REQUIRE(bump_result->colorTexture(1)->readback(
            *device, 0, 0, {}, bump_specular.data(), 32 * 4, &error));
        REQUIRE(bump_result->colorTexture(2)->readback(
            *device, 0, 0, {}, bump_normal_output.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(bump_normal_output[center + 0] > 65000);
        CHECK(std::abs(static_cast<int>(bump_normal_output[center + 1]) -
                       32768) < 512);
        CHECK(std::abs(static_cast<int>(bump_normal_output[center + 2]) -
                       32896) <= 2);
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(std::abs(static_cast<int>(bump_specular[center + channel]) -
                           128) <= 1);
        }

        // Every legacy bump variant is data: bindBumpMap uses raw AnisoWrap
        // for generated brightness/darkness maps and fetched standard bump
        // assets alike. Hold the normal bytes constant and require a shared
        // sRGB-backed asset to produce the same G-buffer normal.
        batch.normal_texture = srgb_bump_normal.get();
        auto srgb_bump_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(srgb_bump_result);
        std::array<std::uint16_t, 32 * 32 * 4> srgb_bump_normal_output{};
        REQUIRE(srgb_bump_result->colorTexture(2)->readback(
            *device, 0, 0, {}, srgb_bump_normal_output.data(), 32 * 8,
            &error));
        INFO(error);
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(srgb_bump_normal_output[center + channel] ==
                  bump_normal_output[center + channel]);
        }
        batch.normal_texture = bump_normal.get();

        batch.alpha_mask = true;
        batch.alpha_cutoff = 0.5f;
        auto masked_bump_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(masked_bump_result);
        std::array<std::uint16_t, 32 * 32 * 4> masked_bump_normal{};
        REQUIRE(masked_bump_result->colorTexture(2)->readback(
            *device, 0, 0, {}, masked_bump_normal.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(masked_bump_normal[center + 0] > 65000);

        batch.normal_texture = nullptr;
        batch.tangent_offset = 0;

        // The alpha-mask owner uses combined texture/vertex coverage with the
        // legacy half-byte bias, but clears specular/environment while
        // retaining the same encoded albedo and atmospheric normal flag.
        batch.alpha_mask = true;
        batch.alpha_cutoff = 0.5f;
        auto masked_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(masked_result);
        std::array<std::uint8_t, 32 * 32 * 4> masked_albedo{};
        std::array<std::uint8_t, 32 * 32 * 4> masked_specular{};
        std::array<std::uint16_t, 32 * 32 * 4> masked_normal{};
        REQUIRE(masked_result->colorTexture(0)->readback(
            *device, 0, 0, {}, masked_albedo.data(), 32 * 4, &error));
        REQUIRE(masked_result->colorTexture(1)->readback(
            *device, 0, 0, {}, masked_specular.data(), 32 * 4, &error));
        REQUIRE(masked_result->colorTexture(2)->readback(
            *device, 0, 0, {}, masked_normal.data(), 32 * 8, &error));
        INFO(error);
        CHECK(masked_albedo[center + 0] == 0);
        CHECK(masked_albedo[center + 1] == 255);
        CHECK(masked_albedo[center + 2] == 0);
        CHECK(masked_specular[center + 0] == 0);
        CHECK(masked_specular[center + 1] == 0);
        CHECK(masked_specular[center + 2] == 0);
        CHECK(masked_specular[center + 3] == 0);
        CHECK(std::abs(static_cast<int>(masked_normal[center + 0]) -
                       32768) <= 1);
        CHECK(std::abs(static_cast<int>(masked_normal[center + 1]) -
                       32768) <= 1);
        CHECK(masked_normal[center + 2] == 0);
        CHECK(std::abs(static_cast<int>(masked_normal[center + 3]) -
                       22282) <= 2);

        // Tree cutouts share the alpha-mask pipeline but intentionally ignore
        // the streamed vertex tint and compare alpha without the generic
        // diffuse-mask half-byte bias. A cutoff just above 128/255 therefore
        // discards here, then passes when the generic bias is restored.
        batch.diffuse_textures[1] = tree_diffuse.get();
        batch.use_vertex_color = false;
        batch.alpha_cutoff_bias = false;
        batch.alpha_cutoff = 0.503f;
        auto tree_discarded_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(tree_discarded_result);
        std::array<std::uint8_t, 32 * 32 * 4> tree_discarded_albedo{};
        REQUIRE(tree_discarded_result->colorTexture(0)->readback(
            *device, 0, 0, {}, tree_discarded_albedo.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(tree_discarded_albedo[center + 0] == 255);
        CHECK(tree_discarded_albedo[center + 1] == 0);
        CHECK(tree_discarded_albedo[center + 2] == 255);

        batch.alpha_cutoff_bias = true;
        auto tree_biased_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(tree_biased_result);
        std::array<std::uint8_t, 32 * 32 * 4> tree_biased_albedo{};
        REQUIRE(tree_biased_result->colorTexture(0)->readback(
            *device, 0, 0, {}, tree_biased_albedo.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(tree_biased_albedo[center + 0]) -
                       128) <= 1);
        CHECK(std::abs(static_cast<int>(tree_biased_albedo[center + 1]) -
                       64) <= 1);
        CHECK(std::abs(static_cast<int>(tree_biased_albedo[center + 2]) -
                       32) <= 1);

        // The dedicated tree producer does not use the generic draw-info
        // capture, but treeF still clips its cutout in eye space. Reject the
        // former zero-initialized model-view payload, then prove the exact
        // tree contract clips the negative half and preserves the positive
        // half just like the GLSL mirrorClip(vary_position) call.
        batch.alpha_cutoff_bias = false;
        batch.alpha_cutoff = 0.5f;
        batch.diffuse_textures[1] = indexed_diffuse.get();
        scene.mirror_clip = true;
        scene.mirror_clip_plane[0] = 1.f;
        scene.mirror_clip_plane[1] = 0.f;
        scene.mirror_clip_plane[2] = 0.f;
        scene.mirror_clip_plane[3] = 0.f;
        batch.modelview[15] = 0.f;
        CHECK_FALSE(renderer->render(scene, &error));
        CHECK(error == "Metal world simple batch is invalid");
        batch.modelview[15] = 1.f;
        error.clear();
        auto tree_mirror_clipped = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(tree_mirror_clipped);
        std::array<std::uint8_t, 32 * 32 * 4> tree_clipped_albedo{};
        REQUIRE(tree_mirror_clipped->colorTexture(0)->readback(
            *device, 0, 0, {}, tree_clipped_albedo.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(tree_clipped_albedo[clipped_side + 0] == 255);
        CHECK(tree_clipped_albedo[clipped_side + 1] == 0);
        CHECK(tree_clipped_albedo[clipped_side + 2] == 255);
        CHECK(tree_clipped_albedo[retained_side + 0] == 0);
        CHECK(tree_clipped_albedo[retained_side + 1] == 255);
        CHECK(tree_clipped_albedo[retained_side + 2] == 0);
        scene.mirror_clip = false;

        batch.diffuse_textures[1] = indexed_diffuse.get();
        batch.use_vertex_color = true;
        batch.alpha_cutoff = 0.6f;
        auto discarded_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(discarded_result);
        std::array<std::uint8_t, 32 * 32 * 4> discarded_albedo{};
        REQUIRE(discarded_result->colorTexture(0)->readback(
            *device, 0, 0, {}, discarded_albedo.data(), 32 * 4, &error));
        INFO(error);
        CHECK(discarded_albedo[center + 0] == 255);
        CHECK(discarded_albedo[center + 1] == 0);
        CHECK(discarded_albedo[center + 2] == 255);
        CHECK(discarded_albedo[center + 3] == 255);

        // Plain legacy materials add authored specular/gloss, environment,
        // fullbright and three diffuse-alpha modes to the same geometry path.
        // The position.w slot index selects the second material exactly as the
        // indexed GL program does.
        batch.alpha_mask = false;
        batch.alpha_cutoff = 0.f;
        batch.diffuse_textures[1] = indexed_diffuse.get();
        batch.material_slot_count = 2;
        batch.material_alpha_mode = 1;
        batch.material_slots[1].specular_color[0] = 0.25f;
        batch.material_slots[1].specular_color[1] = 0.5f;
        batch.material_slots[1].specular_color[2] = 0.75f;
        batch.material_slots[1].specular_color[3] = 0.25f;
        batch.material_slots[1].env_intensity = 0.375f;
        batch.material_slots[1].alpha_cutoff = 0.5f;
        batch.material_slots[1].fullbright = 0.25f;
        CHECK_FALSE(renderer->render(scene, &error));
        CHECK(error == "Metal world simple batch is invalid");

        batch.material_alpha_mode = 0;
        error.clear();
        auto material_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(material_result);
        std::array<std::uint8_t, 32 * 32 * 4> material_albedo{};
        std::array<std::uint8_t, 32 * 32 * 4> material_specular{};
        std::array<std::uint16_t, 32 * 32 * 4> material_normal{};
        REQUIRE(material_result->colorTexture(0)->readback(
            *device, 0, 0, {}, material_albedo.data(), 32 * 4, &error));
        REQUIRE(material_result->colorTexture(1)->readback(
            *device, 0, 0, {}, material_specular.data(), 32 * 4, &error));
        REQUIRE(material_result->colorTexture(2)->readback(
            *device, 0, 0, {}, material_normal.data(), 32 * 8, &error));
        INFO(error);
        CHECK(material_albedo[center + 0] == 0);
        CHECK(material_albedo[center + 1] == 255);
        CHECK(material_albedo[center + 2] == 0);
        CHECK(std::abs(static_cast<int>(material_albedo[center + 3]) -
                       64) <= 1);
        CHECK(std::abs(static_cast<int>(material_specular[center + 0]) -
                       64) <= 1);
        CHECK(std::abs(static_cast<int>(material_specular[center + 1]) -
                       128) <= 1);
        CHECK(std::abs(static_cast<int>(material_specular[center + 2]) -
                       191) <= 1);
        CHECK(std::abs(static_cast<int>(material_specular[center + 3]) -
                       64) <= 1);
        CHECK(std::abs(static_cast<int>(material_normal[center + 0]) -
                       32768) <= 1);
        CHECK(std::abs(static_cast<int>(material_normal[center + 1]) -
                       32768) <= 1);
        CHECK(std::abs(static_cast<int>(material_normal[center + 2]) -
                       24576) <= 2);
        CHECK(std::abs(static_cast<int>(material_normal[center + 3]) -
                       22282) <= 2);

        // The three remaining legacy material families share the same slot
        // constants but independently opt into the tangent/UV1 normal map and
        // UV2 sRGB specular map. Exercise normal-only, specular-only and both
        // before the rigged variant below reuses the combined contract.
        batch.tangent_offset = tangent_offset;
        batch.texcoord1_offset = texcoord_offset;
        batch.texcoord2_offset = texcoord_offset;
        batch.material_slots[0].normal_texture = bump_normal.get();
        batch.material_slots[1].normal_texture = bump_normal.get();
        auto material_normal_map_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(material_normal_map_result);
        std::array<std::uint8_t, 32 * 32 * 4>
            material_normal_map_specular{};
        std::array<std::uint16_t, 32 * 32 * 4>
            material_normal_map_normal{};
        REQUIRE(material_normal_map_result->colorTexture(1)->readback(
            *device, 0, 0, {}, material_normal_map_specular.data(),
            32 * 4, &error));
        REQUIRE(material_normal_map_result->colorTexture(2)->readback(
            *device, 0, 0, {}, material_normal_map_normal.data(),
            32 * 8, &error));
        INFO(error);
        CHECK(material_normal_map_normal[center + 0] > 65000);
        CHECK(std::abs(static_cast<int>(
                           material_normal_map_specular[center + 3]) -
                       32) <= 1);
        CHECK(std::abs(static_cast<int>(
                           material_normal_map_normal[center + 2]) -
                       24576) <= 2);

        // Legacy normals are data, so GL binds them with raw AnisoWrap even
        // when the fetched asset's shared backing is sRGB. The opaque
        // material owner must produce the same G-buffer normal from the same
        // raw bytes in either storage declaration.
        batch.material_slots[0].normal_texture = srgb_bump_normal.get();
        batch.material_slots[1].normal_texture = srgb_bump_normal.get();
        auto srgb_material_normal_map_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(srgb_material_normal_map_result);
        std::array<std::uint16_t, 32 * 32 * 4>
            srgb_material_normal_map_normal{};
        REQUIRE(srgb_material_normal_map_result->colorTexture(2)->readback(
            *device, 0, 0, {}, srgb_material_normal_map_normal.data(),
            32 * 8, &error));
        INFO(error);
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(srgb_material_normal_map_normal[center + channel] ==
                  material_normal_map_normal[center + channel]);
        }

        batch.material_slots[0].normal_texture = nullptr;
        batch.material_slots[1].normal_texture = nullptr;
        batch.material_slots[0].specular_texture =
            material_specular_texture.get();
        batch.material_slots[1].specular_texture =
            material_specular_texture.get();
        auto material_specular_map_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(material_specular_map_result);
        std::array<std::uint8_t, 32 * 32 * 4>
            material_specular_map_specular{};
        std::array<std::uint16_t, 32 * 32 * 4>
            material_specular_map_normal{};
        REQUIRE(material_specular_map_result->colorTexture(1)->readback(
            *device, 0, 0, {}, material_specular_map_specular.data(),
            32 * 4, &error));
        REQUIRE(material_specular_map_result->colorTexture(2)->readback(
            *device, 0, 0, {}, material_specular_map_normal.data(),
            32 * 8, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(
                           material_specular_map_specular[center + 0]) -
                       64) <= 1);
        CHECK(std::abs(static_cast<int>(
                           material_specular_map_specular[center + 1]) -
                       128) <= 1);
        CHECK(std::abs(static_cast<int>(
                           material_specular_map_specular[center + 2]) -
                       191) <= 1);
        CHECK(std::abs(static_cast<int>(
                           material_specular_map_specular[center + 3]) -
                       64) <= 1);
        CHECK(std::abs(static_cast<int>(
                           material_specular_map_normal[center + 0]) -
                       32768) <= 1);
        CHECK(std::abs(static_cast<int>(
                           material_specular_map_normal[center + 2]) -
                       12336) <= 3);

        batch.material_slots[0].normal_texture = bump_normal.get();
        batch.material_slots[1].normal_texture = bump_normal.get();
        batch.texcoord2_offset = vertex_bytes.size();
        CHECK_FALSE(renderer->render(scene, &error));
        CHECK(error ==
              "Metal world simple geometry range exceeds its buffers");
        batch.texcoord2_offset = texcoord_offset;
        error.clear();
        auto material_normal_specular_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(material_normal_specular_result);
        std::array<std::uint8_t, 32 * 32 * 4>
            material_normal_specular_specular{};
        std::array<std::uint16_t, 32 * 32 * 4>
            material_normal_specular_normal{};
        REQUIRE(material_normal_specular_result->colorTexture(1)->readback(
            *device, 0, 0, {}, material_normal_specular_specular.data(),
            32 * 4, &error));
        REQUIRE(material_normal_specular_result->colorTexture(2)->readback(
            *device, 0, 0, {}, material_normal_specular_normal.data(),
            32 * 8, &error));
        INFO(error);
        CHECK(material_normal_specular_normal[center + 0] > 65000);
        CHECK(std::abs(static_cast<int>(
                           material_normal_specular_specular[center + 3]) -
                       32) <= 1);
        CHECK(std::abs(static_cast<int>(
                           material_normal_specular_normal[center + 2]) -
                       12336) <= 3);

        batch.material_alpha_mode = 2;
        batch.material_slots[1].alpha_cutoff = 1.01f;
        auto material_masked_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(material_masked_result);
        std::array<std::uint8_t, 32 * 32 * 4> material_masked_albedo{};
        REQUIRE(material_masked_result->colorTexture(0)->readback(
            *device, 0, 0, {}, material_masked_albedo.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(material_masked_albedo[center + 0] == 255);
        CHECK(material_masked_albedo[center + 1] == 0);
        CHECK(material_masked_albedo[center + 2] == 255);

        batch.material_alpha_mode = 3;
        batch.diffuse_textures[1] = tree_diffuse.get();
        auto material_emissive_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(material_emissive_result);
        std::array<std::uint8_t, 32 * 32 * 4> material_emissive_albedo{};
        REQUIRE(material_emissive_result->colorTexture(0)->readback(
            *device, 0, 0, {}, material_emissive_albedo.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(material_emissive_albedo[center + 0]) -
                       61) <= 1);
        CHECK(std::abs(static_cast<int>(material_emissive_albedo[center + 1]) -
                       64) <= 1);
        CHECK(std::abs(static_cast<int>(material_emissive_albedo[center + 2]) -
                       32) <= 1);
        CHECK(std::abs(static_cast<int>(material_emissive_albedo[center + 3]) -
                       128) <= 1);

        batch.material_slot_count = 0;
        batch.material_alpha_mode = 0;
        batch.diffuse_textures[1] = indexed_diffuse.get();

        // Reproduce the world owner's rebased object skinning. Joint-local
        // and origin translations each contribute +0.25 clip X, so the
        // indexed green triangle moves by exactly half the target width.
        const std::array<float, 16> skin_palette{{
            0.25f, 0.f, 0.f, 0.f,
            1.f, 0.f, 0.f, 0.25f,
            0.f, 1.f, 0.f, 0.f,
            0.f, 0.f, 1.f, 0.f,
        }};
        batch.alpha_mask = false;
        batch.alpha_cutoff = 0.f;
        batch.weight_offset = weight_offset;
        batch.skin_palette = skin_palette.data();
        batch.skin_palette_float_count = skin_palette.size() - 1;
        batch.skin_joint_count = 1;
        CHECK_FALSE(renderer->render(scene, &error));
        CHECK(error == "Metal world simple skinning data is invalid");
        batch.skin_palette_float_count = skin_palette.size();
        for (std::size_t column = 0; column < 3; ++column)
        {
            batch.rigged_normal_matrix[column][column] = 1.f;
        }
        error.clear();
        auto skinned_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(skinned_result);
        std::array<std::uint8_t, 32 * 32 * 4> skinned_albedo{};
        REQUIRE(skinned_result->colorTexture(0)->readback(
            *device, 0, 0, {}, skinned_albedo.data(), 32 * 4, &error));
        INFO(error);
        const std::size_t translated_center = (16 * 32 + 24) * 4;
        CHECK(skinned_albedo[translated_center + 0] == 0);
        CHECK(skinned_albedo[translated_center + 1] == 255);
        CHECK(skinned_albedo[translated_center + 2] == 0);
        CHECK(skinned_albedo[translated_center + 3] == 0);

        batch.tangent_offset = tangent_offset;
        batch.normal_texture = bump_normal.get();
        auto skinned_bump_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(skinned_bump_result);
        std::array<std::uint16_t, 32 * 32 * 4> skinned_bump_normal{};
        REQUIRE(skinned_bump_result->colorTexture(2)->readback(
            *device, 0, 0, {}, skinned_bump_normal.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(skinned_bump_normal[translated_center + 0] > 65000);

        batch.alpha_mask = true;
        batch.alpha_cutoff = 0.5f;
        auto skinned_bump_mask_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(skinned_bump_mask_result);
        std::array<std::uint16_t, 32 * 32 * 4> skinned_bump_mask_normal{};
        REQUIRE(skinned_bump_mask_result->colorTexture(2)->readback(
            *device, 0, 0, {}, skinned_bump_mask_normal.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(skinned_bump_mask_normal[translated_center + 0] > 65000);

        batch.normal_texture = nullptr;
        batch.tangent_offset = 0;
        auto skinned_mask_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(skinned_mask_result);
        std::array<std::uint8_t, 32 * 32 * 4> skinned_mask_albedo{};
        std::array<std::uint8_t, 32 * 32 * 4> skinned_mask_specular{};
        REQUIRE(skinned_mask_result->colorTexture(0)->readback(
            *device, 0, 0, {}, skinned_mask_albedo.data(), 32 * 4, &error));
        REQUIRE(skinned_mask_result->colorTexture(1)->readback(
            *device, 0, 0, {}, skinned_mask_specular.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(skinned_mask_albedo[translated_center + 0] == 0);
        CHECK(skinned_mask_albedo[translated_center + 1] == 255);
        CHECK(skinned_mask_albedo[translated_center + 2] == 0);
        CHECK(skinned_mask_specular[translated_center + 0] == 0);
        CHECK(skinned_mask_specular[translated_center + 1] == 0);
        CHECK(skinned_mask_specular[translated_center + 2] == 0);
        CHECK(skinned_mask_specular[translated_center + 3] == 0);

        // The same material fragment contract consumes the rebased rigged
        // vertex output; no separate approximation or CPU skinning path is
        // allowed for the rigged material owner.
        batch.alpha_mask = false;
        batch.tangent_offset = tangent_offset;
        batch.material_slot_count = 2;
        batch.material_alpha_mode = 0;
        batch.material_slots[1].fullbright = 0.25f;
        auto skinned_material_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(skinned_material_result);
        std::array<std::uint8_t, 32 * 32 * 4> skinned_material_albedo{};
        std::array<std::uint8_t, 32 * 32 * 4> skinned_material_specular{};
        std::array<std::uint16_t, 32 * 32 * 4> skinned_material_normal{};
        REQUIRE(skinned_material_result->colorTexture(0)->readback(
            *device, 0, 0, {}, skinned_material_albedo.data(), 32 * 4,
            &error));
        REQUIRE(skinned_material_result->colorTexture(1)->readback(
            *device, 0, 0, {}, skinned_material_specular.data(), 32 * 4,
            &error));
        REQUIRE(skinned_material_result->colorTexture(2)->readback(
            *device, 0, 0, {}, skinned_material_normal.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(skinned_material_albedo[translated_center + 0] == 0);
        CHECK(skinned_material_albedo[translated_center + 1] == 255);
        CHECK(skinned_material_albedo[translated_center + 2] == 0);
        CHECK(std::abs(static_cast<int>(
                           skinned_material_albedo[translated_center + 3]) -
                       64) <= 1);
        CHECK(std::abs(static_cast<int>(
                           skinned_material_specular[translated_center + 3]) -
                       32) <= 1);
        CHECK(skinned_material_normal[translated_center + 0] > 65000);
        CHECK(std::abs(static_cast<int>(
                           skinned_material_normal[translated_center + 2]) -
                       12336) <= 3);

        // The glTF PBR owner uses four independently transformed maps and
        // packs filtered ORM plus the geometric normal into the same target.
        // Exercise the indexed static path first, including a KHR base-color
        // offset that selects the green texel from a red/green texture.
        batch.material_slot_count = 0;
        batch.material_alpha_mode = 0;
        batch.pbr_slot_count = 2;
        batch.alpha_mask = false;
        batch.double_sided = true;
        batch.tangent_offset = tangent_offset;
        batch.diffuse_textures[0] = pbr_base_texture.get();
        batch.diffuse_textures[1] = pbr_base_texture.get();
        for (std::size_t slot = 0; slot < batch.pbr_slot_count; ++slot)
        {
            ALMetalWorldPBRSlot& pbr = batch.pbr_slots[slot];
            pbr.normal_texture = bump_normal.get();
            pbr.orm_texture = pbr_orm_texture.get();
            pbr.emissive_texture = diffuse.get();
            pbr.texture_transform[0][4] = 0.75f;
            pbr.emissive_color[0] = 0.5f;
            pbr.emissive_color[1] = 1.f;
            pbr.roughness_factor = 0.5f;
            pbr.metallic_factor = 0.5f;
            pbr.alpha_cutoff = -1.f;
        }
        batch.skin_palette = nullptr;
        batch.skin_palette_float_count = 0;
        batch.skin_joint_count = 0;
        batch.weight_offset = 0;

        // Blend the glTF FOR_IMPOSTOR contract into the retained opaque bake:
        // flat linear base colour, true coverage, attachment-zero only. Static
        // alpha keeps depth read-only; rigged alpha writes it so later layers
        // self-occlude, matching LLDrawPoolAlpha::forwardRender.
        ALMetalWorldSimpleBatch alpha_batch = batch;
        alpha_batch.texture_count = 1;
        alpha_batch.pbr_slot_count = 1;
        alpha_batch.modelview_projection[12] = 0.8f;
        ALMetalWorldGBufferScene alpha_scene = scene;
        alpha_scene.batches = &alpha_batch;
        alpha_scene.batch_count = 1;
        alpha_scene.hdr = true;
        alpha_scene.normal_hdr = true;
        alpha_scene.reverse_z = false;
        alpha_batch.pbr_slots[0].alpha_cutoff = 0.5f;
        CHECK_FALSE(renderer->compositeImpostorPostDeferred(
            *coverage_result, alpha_scene, &error));
        CHECK(error == "Metal world PBR alpha material is invalid");
        alpha_batch.pbr_slots[0].alpha_cutoff = -1.f;
        error.clear();
        REQUIRE(renderer->compositeImpostorPostDeferred(
            *coverage_result, alpha_scene, &error));
        INFO(error);
        std::array<std::uint8_t, 32 * 32 * 4> alpha_albedo{};
        std::array<std::uint8_t, 32 * 32 * 4> alpha_orm{};
        std::array<float, 32 * 32> alpha_depth{};
        REQUIRE(coverage_result->colorTexture(0)->readback(
            *device, 0, 0, {}, alpha_albedo.data(), 32 * 4, &error));
        REQUIRE(coverage_result->colorTexture(1)->readback(
            *device, 0, 0, {}, alpha_orm.data(), 32 * 4, &error));
        REQUIRE(coverage_result->depthStencilTexture()->readback(
            *device, 0, 0, {}, alpha_depth.data(), 32 * sizeof(float),
            &error));
        INFO(error);
        const std::size_t alpha_right = (16 * 32 + 24) * 4;
        CHECK(alpha_albedo[alpha_right + 0] == 0);
        CHECK(std::abs(static_cast<int>(alpha_albedo[alpha_right + 1]) -
                       137) <= 2);
        CHECK(alpha_albedo[alpha_right + 2] == 0);
        CHECK(std::abs(static_cast<int>(alpha_albedo[alpha_right + 3]) -
                       64) <= 1);
        CHECK(alpha_albedo[center + 0] == coverage_albedo[center + 0]);
        CHECK(alpha_albedo[center + 1] == coverage_albedo[center + 1]);
        CHECK(alpha_albedo[center + 2] == coverage_albedo[center + 2]);
        CHECK(alpha_albedo[center + 3] == 255);
        CHECK(alpha_orm[alpha_right + 0] == 0);
        CHECK(alpha_orm[alpha_right + 1] == 0);
        CHECK(alpha_orm[alpha_right + 2] == 0);
        CHECK(alpha_orm[alpha_right + 3] == 0);
        CHECK(std::abs(alpha_depth[16 * 32 + 24] - 1.f) < 0.0001f);

        REQUIRE(renderer->compositeImpostorPostDeferred(
            *coverage_result, alpha_scene, &error));
        INFO(error);
        REQUIRE(coverage_result->colorTexture(0)->readback(
            *device, 0, 0, {}, alpha_albedo.data(), 32 * 4, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(alpha_albedo[alpha_right + 1]) -
                       177) <= 2);
        CHECK(std::abs(static_cast<int>(alpha_albedo[alpha_right + 3]) -
                       112) <= 1);

        const std::array<float, 16> alpha_skin_palette{{
            0.f, 0.f, 0.f, 0.f,
            1.f, 0.f, 0.f, 0.f,
            0.f, 1.f, 0.f, 0.f,
            0.f, 0.f, 1.f, 0.f,
        }};
        alpha_batch.modelview_projection[12] = -0.8f;
        alpha_batch.weight_offset = weight_offset;
        alpha_batch.skin_palette = alpha_skin_palette.data();
        alpha_batch.skin_palette_float_count = alpha_skin_palette.size();
        alpha_batch.skin_joint_count = 1;
        for (std::size_t column = 0; column < 3; ++column)
        {
            alpha_batch.rigged_normal_matrix[column][column] = 1.f;
        }
        REQUIRE(renderer->compositeImpostorPostDeferred(
            *coverage_result, alpha_scene, &error));
        INFO(error);
        REQUIRE(coverage_result->depthStencilTexture()->readback(
            *device, 0, 0, {}, alpha_depth.data(), 32 * sizeof(float),
            &error));
        INFO(error);
        CHECK(std::abs(alpha_depth[16 * 32 + 8] - 0.625f) < 0.0001f);

        alpha_scene.reverse_z = true;
        REQUIRE(renderer->compositeImpostorPostDeferred(
            *reverse_coverage_result, alpha_scene, &error));
        INFO(error);
        REQUIRE(reverse_coverage_result->depthStencilTexture()->readback(
            *device, 0, 0, {}, alpha_depth.data(), 32 * sizeof(float),
            &error));
        INFO(error);
        CHECK(std::abs(alpha_depth[16 * 32 + 8] - 0.25f) < 0.0001f);

        // The legacy simple and fullbright impostor programs converge on the
        // same flat diffuse-times-tint contract. Exercise that pipeline with
        // static read-only depth and the object-skinned depth-writing variant.
        ALMetalWorldSimpleBatch flat_alpha_batch = alpha_batch;
        flat_alpha_batch.pbr_slot_count = 0;
        flat_alpha_batch.double_sided = false;
        flat_alpha_batch.tangent_offset = 0;
        flat_alpha_batch.diffuse_textures[0] = indexed_diffuse.get();
        flat_alpha_batch.skin_palette = nullptr;
        flat_alpha_batch.skin_palette_float_count = 0;
        flat_alpha_batch.skin_joint_count = 0;
        flat_alpha_batch.weight_offset = 0;
        flat_alpha_batch.modelview_projection[12] = 0.8f;
        flat_alpha_batch.modelview_projection[13] = 0.8f;
        alpha_scene.batches = &flat_alpha_batch;
        alpha_scene.reverse_z = false;
        flat_alpha_batch.diffuse_textures[0] = nullptr;
        CHECK_FALSE(renderer->compositeImpostorPostDeferred(
            *coverage_result, alpha_scene, &error));
        CHECK(error ==
              "Metal world impostor post-deferred texture is invalid");
        flat_alpha_batch.diffuse_textures[0] = indexed_diffuse.get();
        error.clear();
        REQUIRE(renderer->compositeImpostorPostDeferred(
            *coverage_result, alpha_scene, &error));
        INFO(error);
        REQUIRE(coverage_result->colorTexture(0)->readback(
            *device, 0, 0, {}, alpha_albedo.data(), 32 * 4, &error));
        REQUIRE(coverage_result->colorTexture(1)->readback(
            *device, 0, 0, {}, alpha_orm.data(), 32 * 4, &error));
        REQUIRE(coverage_result->depthStencilTexture()->readback(
            *device, 0, 0, {}, alpha_depth.data(), 32 * sizeof(float),
            &error));
        INFO(error);
        const std::size_t alpha_top = (24 * 32 + 24) * 4;
        CHECK(alpha_albedo[alpha_top + 0] == 0);
        CHECK(std::abs(static_cast<int>(alpha_albedo[alpha_top + 1]) -
                       188) <= 2);
        CHECK(alpha_albedo[alpha_top + 2] == 0);
        CHECK(std::abs(static_cast<int>(alpha_albedo[alpha_top + 3]) -
                       128) <= 1);
        CHECK(alpha_orm[alpha_top + 0] == 0);
        CHECK(alpha_orm[alpha_top + 1] == 0);
        CHECK(alpha_orm[alpha_top + 2] == 0);
        CHECK(alpha_orm[alpha_top + 3] == 0);
        CHECK(std::abs(alpha_depth[24 * 32 + 24] - 1.f) < 0.0001f);

        flat_alpha_batch.modelview_projection[13] = -0.8f;
        flat_alpha_batch.weight_offset = weight_offset;
        flat_alpha_batch.skin_palette = alpha_skin_palette.data();
        flat_alpha_batch.skin_palette_float_count =
            alpha_skin_palette.size();
        flat_alpha_batch.skin_joint_count = 1;
        REQUIRE(renderer->compositeImpostorPostDeferred(
            *coverage_result, alpha_scene, &error));
        INFO(error);
        REQUIRE(coverage_result->depthStencilTexture()->readback(
            *device, 0, 0, {}, alpha_depth.data(), 32 * sizeof(float),
            &error));
        INFO(error);
        CHECK(std::abs(alpha_depth[8 * 32 + 28] - 0.625f) < 0.0001f);

        // Fullbright and fullbright-mask run earlier in post-deferred than
        // blended alpha. They write depth, then the bake seeds full coverage
        // from that depth before partial coverage begins. Exercise the masked
        // static owner and that phase-boundary stamp together.
        ALMetalWorldSimpleBatch fullbright_batch = flat_alpha_batch;
        fullbright_batch.impostor_fullbright = true;
        fullbright_batch.alpha_mask = true;
        fullbright_batch.alpha_cutoff = 1.1f;
        fullbright_batch.skin_palette = nullptr;
        fullbright_batch.skin_palette_float_count = 0;
        fullbright_batch.skin_joint_count = 0;
        fullbright_batch.weight_offset = 0;
        fullbright_batch.modelview_projection[12] = -0.8f;
        fullbright_batch.modelview_projection[13] = 0.8f;
        alpha_scene.batches = &fullbright_batch;
        alpha_scene.stamp_opaque_coverage = true;
        CHECK_FALSE(renderer->compositeImpostorPostDeferred(
            *coverage_result, alpha_scene, &error));
        CHECK(error ==
              "Metal world impostor post-deferred batch is invalid");
        fullbright_batch.alpha_cutoff = 0.5f;
        error.clear();
        REQUIRE(renderer->compositeImpostorPostDeferred(
            *coverage_result, alpha_scene, &error));
        INFO(error);
        REQUIRE(coverage_result->colorTexture(0)->readback(
            *device, 0, 0, {}, alpha_albedo.data(), 32 * 4, &error));
        REQUIRE(coverage_result->colorTexture(1)->readback(
            *device, 0, 0, {}, alpha_orm.data(), 32 * 4, &error));
        REQUIRE(coverage_result->depthStencilTexture()->readback(
            *device, 0, 0, {}, alpha_depth.data(), 32 * sizeof(float),
            &error));
        INFO(error);
        const std::size_t fullbright_top = (24 * 32 + 8) * 4;
        CHECK(alpha_albedo[fullbright_top + 0] == 0);
        CHECK(alpha_albedo[fullbright_top + 1] == 255);
        CHECK(alpha_albedo[fullbright_top + 2] == 0);
        CHECK(alpha_albedo[fullbright_top + 3] == 255);
        CHECK(alpha_orm[fullbright_top + 0] == 0);
        CHECK(alpha_orm[fullbright_top + 1] == 0);
        CHECK(alpha_orm[fullbright_top + 2] == 0);
        CHECK(alpha_orm[fullbright_top + 3] == 0);
        CHECK(std::abs(alpha_depth[24 * 32 + 8] - 0.625f) < 0.0001f);

        // Fullbright volume batches legally omit normals: neither the GL
        // fullbright vertex shader nor its fragment consumes them. Keep the
        // native static and skinned contracts honest by pointing the unused
        // normal offset beyond the buffer and requiring both variants to
        // encode under Metal API validation.
        ALMetalWorldSimpleBatch normal_free_fullbright = fullbright_batch;
        normal_free_fullbright.normal_offset = vertex_bytes.size() + 16;
        alpha_scene.batches = &normal_free_fullbright;
        REQUIRE(renderer->compositeImpostorPostDeferred(
            *coverage_result, alpha_scene, &error));
        INFO(error);
        normal_free_fullbright.weight_offset = weight_offset;
        normal_free_fullbright.skin_palette = alpha_skin_palette.data();
        normal_free_fullbright.skin_palette_float_count =
            alpha_skin_palette.size();
        normal_free_fullbright.skin_joint_count = 1;
        REQUIRE(renderer->compositeImpostorPostDeferred(
            *coverage_result, alpha_scene, &error));
        INFO(error);
        normal_free_fullbright.weight_offset = 0;
        normal_free_fullbright.skin_palette = nullptr;
        normal_free_fullbright.skin_palette_float_count = 0;
        normal_free_fullbright.skin_joint_count = 0;
        alpha_scene.batches = &fullbright_batch;

        // The main-world owner starts from independently produced lighting
        // color and G-buffer depth. It copies both on-GPU, then replays this
        // opaque-forward batch into a single final-color attachment without
        // disturbing pixels outside the geometry.
        ALMetalRenderTargetDescriptor final_light_descriptor;
        final_light_descriptor.width = 32;
        final_light_descriptor.height = 32;
        final_light_descriptor.colors[0].format =
            ALMetalPixelFormat::rgba16_float;
        final_light_descriptor.label =
            "Alchemy opaque post-deferred test lighting";
        auto final_light = ALMetalRenderTarget::create(
            *device, final_light_descriptor, &error);
        INFO(error);
        REQUIRE(final_light);
        ALMetalRenderPassConfig final_light_clear;
        final_light_clear.colors[0].load = ALMetalLoadAction::clear;
        final_light_clear.colors[0].store = ALMetalStoreAction::store;
        final_light_clear.colors[0].clear = {0.25, 0.125, 0.0625, 0.5};
        auto final_light_pass = final_light->makeRenderPass(
            final_light_clear, &error);
        auto final_light_command = device->makeCommandBuffer(
            "Alchemy opaque post-deferred test lighting clear", &error);
        auto final_light_encoder = final_light_pass && final_light_command
            ? ALMetalRenderEncoder::begin(
                  *final_light_command, *final_light_pass,
                  "Alchemy opaque post-deferred test clear encoder",
                  &error)
            : nullptr;
        INFO(error);
        REQUIRE(final_light_encoder);
        REQUIRE(final_light_encoder->end(&error));
        REQUIRE(final_light_command->commitAndWait(&error));

        ALMetalWorldOpaquePostDeferredScene opaque_forward_scene;
        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.composed_lighting = final_light.get();
        opaque_forward_scene.batches = &normal_free_fullbright;
        opaque_forward_scene.batch_count = 1;
        opaque_forward_scene.width = 32;
        opaque_forward_scene.height = 32;
        opaque_forward_scene.hdr = true;

        // A world with no forward/post-deferred draws is still a complete
        // transaction: retain composed opaque lighting and G-buffer depth so
        // the display chain does not stall on an empty optional slice.
        opaque_forward_scene.batches = nullptr;
        opaque_forward_scene.batch_count = 0;
        auto opaque_only = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(opaque_only);
        std::array<std::uint16_t, 32 * 32 * 4> opaque_only_pixels{};
        std::array<float, 32 * 32> opaque_only_depth{};
        REQUIRE(opaque_only->colorTexture(0)->readback(
            *device, 0, 0, {}, opaque_only_pixels.data(), 32 * 8,
            &error));
        REQUIRE(opaque_only->depthStencilTexture()->readback(
            *device, 0, 0, {}, opaque_only_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK(opaque_only_pixels[0] == 0x3400);
        CHECK(opaque_only_pixels[1] == 0x3000);
        CHECK(opaque_only_pixels[2] == 0x2c00);
        CHECK(opaque_only_pixels[3] == 0x3800);
        CHECK(std::abs(opaque_only_depth[24 * 32 + 8] - 0.625f) <
              0.0001f);
        CHECK(std::abs(opaque_only_depth[0] - 1.f) < 0.0001f);

        // A cutout clears final color only where retained depth is still at
        // the far plane, then stamps opaque depth to full coverage before any
        // alpha batches accumulate. The composed lighting source starts with
        // half alpha everywhere, making both halves of the contract visible.
        opaque_forward_scene.seed_cutout_coverage = true;
        auto cutout_seed = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(cutout_seed);
        std::array<std::uint16_t, 32 * 32 * 4> cutout_seed_pixels{};
        REQUIRE(cutout_seed->colorTexture(0)->readback(
            *device, 0, 0, {}, cutout_seed_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(cutout_seed_pixels[0] == 0u);
        CHECK(cutout_seed_pixels[1] == 0u);
        CHECK(cutout_seed_pixels[2] == 0u);
        CHECK(cutout_seed_pixels[3] == 0u);
        const std::size_t covered_cutout_pixel =
            (24u * 32u + 8u) * 4u;
        CHECK(cutout_seed_pixels[covered_cutout_pixel + 0] == 0x3400);
        CHECK(cutout_seed_pixels[covered_cutout_pixel + 1] == 0x3000);
        CHECK(cutout_seed_pixels[covered_cutout_pixel + 2] == 0x2c00);
        CHECK(cutout_seed_pixels[covered_cutout_pixel + 3] == 0x3c00);
        opaque_forward_scene.gbuffer = reverse_coverage_result.get();
        opaque_forward_scene.reverse_z = true;
        auto reverse_cutout_seed = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_cutout_seed);
        cutout_seed_pixels.fill(0xffffu);
        REQUIRE(reverse_cutout_seed->colorTexture(0)->readback(
            *device, 0, 0, {}, cutout_seed_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(cutout_seed_pixels[0] == 0u);
        CHECK(cutout_seed_pixels[3] == 0u);
        CHECK(cutout_seed_pixels[center + 3] == 0x3c00);
        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.reverse_z = false;
        opaque_forward_scene.seed_cutout_coverage = false;

        // Production may join this expensive opaque/post-deferred owner to
        // its dependent post chain. Standalone rendering above still
        // commits immediately; an explicit batch must publish the same
        // color/depth and dependent display result in exactly one submission
        // and only when committed.
        ALMetalWorldDisplayPostScene standalone_opaque_display_scene;
        standalone_opaque_display_scene.source = opaque_only.get();
        standalone_opaque_display_scene.hdr = true;
        standalone_opaque_display_scene.tonemap_mix = 0.f;
        auto standalone_opaque_display = renderer->renderDisplayPost(
            standalone_opaque_display_scene, &error);
        INFO(error);
        REQUIRE(standalone_opaque_display);
        std::array<std::uint32_t, 32 * 32>
            standalone_opaque_display_pixels{};
        REQUIRE(standalone_opaque_display->colorTexture(0)->readback(
            *device, 0, 0, {}, standalone_opaque_display_pixels.data(),
            32 * sizeof(std::uint32_t), &error));
        const std::uint64_t opaque_submissions_before_batch =
            ALMetalDevice::committedCommandBufferCount();
        REQUIRE(renderer->beginCommandBatch(
            "Alchemy opaque/post command-batch regression", &error));
        auto batched_opaque_only = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(batched_opaque_only);
        ALMetalWorldDisplayPostScene batched_opaque_display_scene;
        batched_opaque_display_scene.source = batched_opaque_only.get();
        batched_opaque_display_scene.hdr = true;
        batched_opaque_display_scene.tonemap_mix = 0.f;
        auto batched_opaque_display = renderer->renderDisplayPost(
            batched_opaque_display_scene, &error);
        INFO(error);
        REQUIRE(batched_opaque_display);
        CHECK(renderer->commandBatchActive());
        REQUIRE(renderer->commitCommandBatch(&error));
        INFO(error);
        CHECK(ALMetalDevice::committedCommandBufferCount() ==
              opaque_submissions_before_batch + 1);
        std::array<std::uint16_t, 32 * 32 * 4>
            batched_opaque_only_pixels{};
        std::array<float, 32 * 32> batched_opaque_only_depth{};
        std::array<std::uint32_t, 32 * 32>
            batched_opaque_display_pixels{};
        REQUIRE(batched_opaque_only->colorTexture(0)->readback(
            *device, 0, 0, {}, batched_opaque_only_pixels.data(), 32 * 8,
            &error));
        REQUIRE(batched_opaque_only->depthStencilTexture()->readback(
            *device, 0, 0, {}, batched_opaque_only_depth.data(),
            32 * sizeof(float), &error));
        REQUIRE(batched_opaque_display->colorTexture(0)->readback(
            *device, 0, 0, {}, batched_opaque_display_pixels.data(),
            32 * sizeof(std::uint32_t), &error));
        INFO(error);
        CHECK(batched_opaque_only_pixels == opaque_only_pixels);
        CHECK(batched_opaque_only_depth == opaque_only_depth);
        CHECK(batched_opaque_display_pixels ==
              standalone_opaque_display_pixels);

        opaque_forward_scene.batches = &normal_free_fullbright;
        opaque_forward_scene.batch_count = 1;
        normal_free_fullbright.diffuse_textures[0] = nullptr;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world opaque post-deferred texture is invalid");
        normal_free_fullbright.diffuse_textures[0] = indexed_diffuse.get();
        error.clear();
        auto opaque_forward = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(opaque_forward);
        CHECK(opaque_forward->descriptor().color_attachment_count == 1);
        CHECK(opaque_forward->descriptor().colors[0].format ==
              ALMetalPixelFormat::rgba16_float);
        CHECK(opaque_forward->descriptor().depth_stencil_format ==
              ALMetalPixelFormat::depth32_float_stencil8);
        CHECK_FALSE(opaque_forward->descriptor().depth_stencil_shader_read);
        std::array<std::uint16_t, 32 * 32 * 4> opaque_forward_pixels{};
        std::array<float, 32 * 32> opaque_forward_depth{};
        REQUIRE(opaque_forward->colorTexture(0)->readback(
            *device, 0, 0, {}, opaque_forward_pixels.data(), 32 * 8,
            &error));
        REQUIRE(opaque_forward->depthStencilTexture()->readback(
            *device, 0, 0, {}, opaque_forward_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK(opaque_forward_pixels[0] == 0x3400);
        CHECK(opaque_forward_pixels[1] == 0x3000);
        CHECK(opaque_forward_pixels[2] == 0x2c00);
        CHECK(opaque_forward_pixels[3] == 0x3800);
        CHECK(opaque_forward_pixels[fullbright_top + 0] == 0);
        CHECK(opaque_forward_pixels[fullbright_top + 1] == 0x3c00);
        CHECK(opaque_forward_pixels[fullbright_top + 2] == 0);
        CHECK(opaque_forward_pixels[fullbright_top + 3] >= 0x3800);
        CHECK(opaque_forward_pixels[fullbright_top + 3] <= 0x3808);
        CHECK(std::abs(
                  opaque_forward_depth[24 * 32 + 8] - 0.625f) < 0.0001f);
        CHECK(std::abs(opaque_forward_depth[0] - 1.f) < 0.0001f);

        // Ordinary POOL_FULLBRIGHT is opaque even though the streamed vertex
        // alpha holds shininess (0.5 in this fixture). GL keeps blending
        // disabled and writes RGB only, so Metal must replace the background
        // with the full green texel while preserving the lighting target's
        // destination alpha. Source-alpha blending would leave a half-strength
        // poster and raise destination alpha from 0.5 to 0.75.
        normal_free_fullbright.alpha_mask = false;
        normal_free_fullbright.alpha_cutoff = 0.f;
        auto opaque_unmasked_fullbright =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(opaque_unmasked_fullbright);
        std::array<std::uint16_t, 32 * 32 * 4>
            opaque_unmasked_fullbright_pixels{};
        REQUIRE(opaque_unmasked_fullbright->colorTexture(0)->readback(
            *device, 0, 0, {},
            opaque_unmasked_fullbright_pixels.data(), 32 * 8, &error));
        INFO(error);
        CHECK(opaque_unmasked_fullbright_pixels[fullbright_top + 0] == 0);
        CHECK(opaque_unmasked_fullbright_pixels[fullbright_top + 1] ==
              0x3c00);
        CHECK(opaque_unmasked_fullbright_pixels[fullbright_top + 2] == 0);
        CHECK(opaque_unmasked_fullbright_pixels[fullbright_top + 3] ==
              0x3800);
        normal_free_fullbright.alpha_mask = true;
        normal_free_fullbright.alpha_cutoff = 0.5f;

        float opaque_scene_pixel[4]{};
        REQUIRE(renderer->readSceneColorPixel(
            *opaque_forward, 0, 0, opaque_scene_pixel, &error));
        INFO(error);
        CHECK(opaque_scene_pixel[0] == 0.25f);
        CHECK(opaque_scene_pixel[1] == 0.125f);
        CHECK(opaque_scene_pixel[2] == 0.0625f);
        CHECK(opaque_scene_pixel[3] == 0.5f);

        // Post-deferred draw-pool triangles inherit line fill while the
        // copied lighting plane remains filled. This proves the mode is
        // applied at the geometry owner and not to the whole composite.
        opaque_forward_scene.wireframe = true;
        auto wireframe_forward = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(wireframe_forward);
        std::array<std::uint16_t, 32 * 32 * 4>
            wireframe_forward_pixels{};
        REQUIRE(wireframe_forward->colorTexture(0)->readback(
            *device, 0, 0, {}, wireframe_forward_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(wireframe_forward_pixels[center + 0] == 0x3400);
        CHECK(wireframe_forward_pixels[center + 1] == 0x3000);
        CHECK(wireframe_forward_pixels[center + 2] == 0x2c00);
        const std::size_t wireframe_green_pixels = std::count_if(
            wireframe_forward_pixels.begin(),
            wireframe_forward_pixels.end(),
            [](std::uint16_t value)
            {
                return value == 0x3c00;
            });
        CHECK(wireframe_green_pixels > 0);
        opaque_forward_scene.wireframe = false;

        // Legacy edit-face/touch highlights sit after all post-deferred
        // geometry but before exposure, tonemapping and other display post.
        // Reuse the retained face buffers, sample an sRGB white marker, and
        // prove GL's uniform-color multiplication, alpha blend and read-only
        // forward/reverse depth conventions at that exact boundary.
        ALMetalWorldHighlightBatch highlight;
        highlight.vertices = vertices.get();
        highlight.position_offset = 0;
        highlight.texcoord_offset = texcoord_offset;
        highlight.vertex_count = positions.size();
        highlight.indices = indices.get();
        highlight.index_count = index_values.size();
        highlight.texture = highlight_texture.get();
        highlight.color[0] = 1.f;
        highlight.color[3] = 0.5f;
        for (std::size_t axis = 0; axis < 4; ++axis)
        {
            highlight.modelview_projection[axis * 4 + axis] = 1.f;
        }
        opaque_forward_scene.highlight_batches = &highlight;
        opaque_forward_scene.highlight_batch_count = 1;
        highlight.texture = nullptr;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world highlight batch is invalid");
        highlight.texture = highlight_texture.get();
        error.clear();
        auto highlighted = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(highlighted);
        std::array<std::uint16_t, 32 * 32 * 4> highlighted_pixels{};
        std::array<float, 32 * 32> highlighted_depth{};
        REQUIRE(highlighted->colorTexture(0)->readback(
            *device, 0, 0, {}, highlighted_pixels.data(), 32 * 8,
            &error));
        REQUIRE(highlighted->depthStencilTexture()->readback(
            *device, 0, 0, {}, highlighted_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK(highlighted_pixels[center + 0] == 0x3900);
        CHECK(highlighted_pixels[center + 1] == 0x2c00);
        CHECK(highlighted_pixels[center + 2] == 0x2800);
        CHECK(highlighted_pixels[center + 3] == 0x3800);
        CHECK(std::abs(highlighted_depth[16 * 32 + 16] - 0.625f) <
              0.0001f);

        // GL restores fill before the edit-face highlight owner. A filled
        // center under wireframe proves that the preceding line state does
        // not leak into this later diagnostic geometry.
        opaque_forward_scene.wireframe = true;
        auto wireframe_highlighted = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(wireframe_highlighted);
        std::array<std::uint16_t, 32 * 32 * 4>
            wireframe_highlighted_pixels{};
        REQUIRE(wireframe_highlighted->colorTexture(0)->readback(
            *device, 0, 0, {}, wireframe_highlighted_pixels.data(),
            32 * 8, &error));
        CHECK(wireframe_highlighted_pixels[center + 0] == 0x3900);
        CHECK(wireframe_highlighted_pixels[center + 1] == 0x2c00);
        CHECK(wireframe_highlighted_pixels[center + 2] == 0x2800);
        opaque_forward_scene.wireframe = false;

        // Highlight Transparent uses the same sampled-uniform-color shader,
        // but GL has already restored an RGB-only color mask. Prove that the
        // diagnostic overlay leaves the retained glow/coverage alpha alone,
        // then move the same triangle through the object-skin palette so the
        // rigged pipeline cannot pass by accidentally using static vertices.
        ALMetalWorldHighlightBatch debug_highlight = highlight;
        debug_highlight.color[0] = 1.f;
        debug_highlight.color[1] = 0.f;
        debug_highlight.color[2] = 0.f;
        debug_highlight.color[3] = 1.f;
        debug_highlight.write_alpha = false;
        opaque_forward_scene.highlight_batches = &debug_highlight;
        auto debug_highlighted = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(debug_highlighted);
        std::array<std::uint16_t, 32 * 32 * 4>
            debug_highlighted_pixels{};
        REQUIRE(debug_highlighted->colorTexture(0)->readback(
            *device, 0, 0, {}, debug_highlighted_pixels.data(), 32 * 8,
            &error));
        const std::size_t debug_static = (16 * 32 + 12) * 4;
        const std::size_t debug_shifted = (16 * 32 + 25) * 4;
        CHECK(debug_highlighted_pixels[debug_static + 0] == 0x3c00);
        CHECK(debug_highlighted_pixels[debug_static + 1] == 0u);
        CHECK(debug_highlighted_pixels[debug_static + 2] == 0u);
        CHECK(debug_highlighted_pixels[debug_static + 3] ==
              opaque_forward_pixels[debug_static + 3]);

        std::array<float, 16> debug_skin_palette = alpha_skin_palette;
        debug_skin_palette[7] = 0.5f;
        debug_highlight.weight_offset = weight_offset;
        debug_highlight.skin_palette = debug_skin_palette.data();
        debug_highlight.skin_palette_float_count =
            debug_skin_palette.size();
        debug_highlight.skin_joint_count = 1;
        auto rigged_debug_highlighted =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(rigged_debug_highlighted);
        debug_highlighted_pixels.fill(0xffffu);
        REQUIRE(rigged_debug_highlighted->colorTexture(0)->readback(
            *device, 0, 0, {}, debug_highlighted_pixels.data(), 32 * 8,
            &error));
        CHECK(debug_highlighted_pixels[debug_static + 0] ==
              opaque_forward_pixels[debug_static + 0]);
        CHECK(debug_highlighted_pixels[debug_shifted + 0] == 0x3c00);
        CHECK(debug_highlighted_pixels[debug_shifted + 1] == 0u);
        CHECK(debug_highlighted_pixels[debug_shifted + 2] == 0u);
        CHECK(debug_highlighted_pixels[debug_shifted + 3] ==
              opaque_forward_pixels[debug_shifted + 3]);

        debug_highlight.skin_palette_float_count = 4;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world highlight batch is invalid");
        error.clear();

        opaque_forward_scene.gbuffer = reverse_coverage_result.get();
        opaque_forward_scene.reverse_z = true;
        opaque_forward_scene.highlight_batches = &highlight;
        auto reverse_highlighted = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_highlighted);
        REQUIRE(reverse_highlighted->depthStencilTexture()->readback(
            *device, 0, 0, {}, highlighted_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK(std::abs(highlighted_depth[16 * 32 + 16] - 0.25f) <
              0.0001f);
        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.reverse_z = false;
        opaque_forward_scene.highlight_batches = nullptr;
        opaque_forward_scene.highlight_batch_count = 0;

        // "Show Updates to Objects" emits eight-pixel gUIProgram points at
        // the end of renderDebug. Reproduce the streamed position/color,
        // RGB-only mask and GL_ALWAYS depth write at the same pre-post
        // boundary. Half-pixel centers make an exact 8x8 footprint for each
        // asymmetric marker.
        std::array<ALMetalWorldDebugBlip, 2> debug_blips{};
        debug_blips[0].position[0] = -0.46875f;
        debug_blips[0].position[1] = 0.03125f;
        debug_blips[0].color[0] = 1.f;
        debug_blips[0].color[1] = 0.f;
        debug_blips[0].color[2] = 0.f;
        debug_blips[1].position[0] = 0.53125f;
        debug_blips[1].position[1] = 0.03125f;
        debug_blips[1].color[0] = 0.f;
        debug_blips[1].color[1] = 1.f;
        debug_blips[1].color[2] = 0.f;
        opaque_forward_scene.debug_blips = debug_blips.data();
        opaque_forward_scene.debug_blip_count = debug_blips.size();
        for (std::size_t axis = 0; axis < 4; ++axis)
        {
            opaque_forward_scene.debug_blip_modelview_projection[
                axis * 4 + axis] = 1.f;
        }

        opaque_forward_scene.debug_blips = nullptr;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world object-update blip storage is invalid");
        opaque_forward_scene.debug_blips = debug_blips.data();
        debug_blips[0].color[0] =
            std::numeric_limits<float>::quiet_NaN();
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world object-update blip data is non-finite");
        debug_blips[0].color[0] = 1.f;
        error.clear();

        auto native_debug_blips = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(native_debug_blips);
        std::array<std::uint16_t, 32 * 32 * 4> debug_blip_pixels{};
        std::array<float, 32 * 32> debug_blip_depth{};
        REQUIRE(native_debug_blips->colorTexture(0)->readback(
            *device, 0, 0, {}, debug_blip_pixels.data(), 32 * 8,
            &error));
        REQUIRE(native_debug_blips->depthStencilTexture()->readback(
            *device, 0, 0, {}, debug_blip_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        const std::size_t red_blip = (16 * 32 + 8) * 4;
        const std::size_t green_blip = (16 * 32 + 24) * 4;
        CHECK(debug_blip_pixels[red_blip + 0] == 0x3c00);
        CHECK(debug_blip_pixels[red_blip + 1] == 0u);
        CHECK(debug_blip_pixels[red_blip + 2] == 0u);
        CHECK(debug_blip_pixels[red_blip + 3] ==
              opaque_forward_pixels[red_blip + 3]);
        CHECK(debug_blip_pixels[green_blip + 0] == 0u);
        CHECK(debug_blip_pixels[green_blip + 1] == 0x3c00);
        CHECK(debug_blip_pixels[green_blip + 2] == 0u);
        CHECK(debug_blip_pixels[green_blip + 3] ==
              opaque_forward_pixels[green_blip + 3]);
        std::size_t red_blip_pixels = 0;
        std::size_t green_blip_pixels = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            red_blip_pixels +=
                std::abs(debug_blip_depth[pixel] - 0.5f) < 0.0001f &&
                std::abs(opaque_forward_depth[pixel] - 0.5f) >= 0.0001f &&
                debug_blip_pixels[offset + 0] == 0x3c00 &&
                debug_blip_pixels[offset + 1] == 0u &&
                debug_blip_pixels[offset + 2] == 0u;
            green_blip_pixels +=
                std::abs(debug_blip_depth[pixel] - 0.5f) < 0.0001f &&
                std::abs(opaque_forward_depth[pixel] - 0.5f) >= 0.0001f &&
                debug_blip_pixels[offset + 0] == 0u &&
                debug_blip_pixels[offset + 1] == 0x3c00 &&
                debug_blip_pixels[offset + 2] == 0u;
        }
        CHECK(red_blip_pixels == 64);
        CHECK(green_blip_pixels == 64);
        CHECK(std::abs(debug_blip_depth[16 * 32 + 8] - 0.5f) <
              0.0001f);
        CHECK(std::abs(debug_blip_depth[16 * 32 + 24] - 0.5f) <
              0.0001f);
        CHECK(debug_blip_pixels[0] == opaque_forward_pixels[0]);
        CHECK(std::abs(debug_blip_depth[0] - opaque_forward_depth[0]) <
              0.0001f);
        opaque_forward_scene.debug_blips = nullptr;
        opaque_forward_scene.debug_blip_count = 0;

        // Develop > Points emits an opaque white one-pixel point for each
        // valid face centre. Region and spatial-bridge traversals can carry
        // distinct transforms; depth is disabled, so even a point behind a
        // covered surface draws without changing retained scene depth.
        std::array<ALMetalWorldDebugPointVertex, 2> debug_points{};
        for (ALMetalWorldDebugPointVertex& point : debug_points)
        {
            point.position[0] = -0.71875f;
            point.position[1] = -0.71875f;
            point.position[2] = 0.9f;
        }
        std::array<ALMetalWorldDebugPointBatch, 2> debug_point_batches{};
        for (std::size_t batch = 0;
             batch < debug_point_batches.size(); ++batch)
        {
            debug_point_batches[batch].first_vertex =
                static_cast<std::uint32_t>(batch);
            debug_point_batches[batch].vertex_count = 1;
            debug_point_batches[batch].order = batch;
            for (std::size_t axis = 0; axis < 4; ++axis)
            {
                debug_point_batches[batch].modelview_projection[
                    axis * 4 + axis] = 1.f;
            }
        }
        // Translate the second batch in X. Both retained vertices are equal,
        // so the two separated pixels prove per-batch transform ownership.
        debug_point_batches[1].modelview_projection[12] = 1.f;
        opaque_forward_scene.debug_points = debug_points.data();
        opaque_forward_scene.debug_point_count = debug_points.size();
        opaque_forward_scene.debug_point_batches =
            debug_point_batches.data();
        opaque_forward_scene.debug_point_batch_count =
            debug_point_batches.size();

        opaque_forward_scene.debug_points = nullptr;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world drawable-centre point storage is invalid");
        opaque_forward_scene.debug_points = debug_points.data();
        opaque_forward_scene.debug_point_batches = nullptr;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world drawable-centre point storage is invalid");
        opaque_forward_scene.debug_point_batches =
            debug_point_batches.data();
        debug_point_batches[1].first_vertex = 0;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world drawable-centre point batch is invalid");
        debug_point_batches[1].first_vertex = 1;
        debug_point_batches[1].order = 0;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world drawable-centre point batch is invalid");
        debug_point_batches[1].order = 1;
        debug_point_batches[1].modelview_projection[0] =
            std::numeric_limits<float>::quiet_NaN();
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world drawable-centre point batch is invalid");
        debug_point_batches[1].modelview_projection[0] = 1.f;
        debug_points[0].position[0] =
            std::numeric_limits<float>::quiet_NaN();
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world drawable-centre point data is non-finite");
        debug_points[0].position[0] = -0.71875f;
        error.clear();

        auto native_debug_points = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(native_debug_points);
        std::array<std::uint16_t, 32 * 32 * 4> debug_point_pixels{};
        std::array<float, 32 * 32> debug_point_depth{};
        REQUIRE(native_debug_points->colorTexture(0)->readback(
            *device, 0, 0, {}, debug_point_pixels.data(), 32 * 8,
            &error));
        REQUIRE(native_debug_points->depthStencilTexture()->readback(
            *device, 0, 0, {}, debug_point_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        std::size_t debug_point_changed = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            const bool changed =
                debug_point_pixels[offset + 0] !=
                    opaque_forward_pixels[offset + 0] ||
                debug_point_pixels[offset + 1] !=
                    opaque_forward_pixels[offset + 1] ||
                debug_point_pixels[offset + 2] !=
                    opaque_forward_pixels[offset + 2];
            debug_point_changed += changed;
            if (changed)
            {
                CHECK(debug_point_pixels[offset + 0] == 0x3c00);
                CHECK(debug_point_pixels[offset + 1] == 0x3c00);
                CHECK(debug_point_pixels[offset + 2] == 0x3c00);
                CHECK(debug_point_pixels[offset + 3] ==
                      opaque_forward_pixels[offset + 3]);
            }
        }
        CHECK(debug_point_changed == 2);
        CHECK(debug_point_pixels[(4 * 32 + 4) * 4] == 0x3c00);
        CHECK(debug_point_pixels[(4 * 32 + 20) * 4] == 0x3c00);
        CHECK(debug_point_depth == opaque_forward_depth);

        opaque_forward_scene.debug_points = nullptr;
        opaque_forward_scene.debug_point_count = 0;
        opaque_forward_scene.debug_point_batches = nullptr;
        opaque_forward_scene.debug_point_batch_count = 0;
        auto no_debug_points = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(no_debug_points);
        debug_point_pixels.fill(0xffffu);
        debug_point_depth.fill(-1.f);
        REQUIRE(no_debug_points->colorTexture(0)->readback(
            *device, 0, 0, {}, debug_point_pixels.data(), 32 * 8,
            &error));
        REQUIRE(no_debug_points->depthStencilTexture()->readback(
            *device, 0, 0, {}, debug_point_depth.data(),
            32 * sizeof(float), &error));
        CHECK(debug_point_pixels == opaque_forward_pixels);
        CHECK(debug_point_depth == opaque_forward_depth);

        // Develop > Composition is a fixed 261x261 current-region grid.
        // Only its live heights are uploaded; the Metal vertex stage derives
        // the original x/y loop order plus the 0..255 blue interior and
        // 256..260 red border. It inherits read/write world depth.
        std::vector<float> composition_debug_heights(
            AL_METAL_COMPOSITION_DEBUG_POINT_COUNT, 0.f);
        opaque_forward_scene.composition_debug_heights =
            composition_debug_heights.data();
        opaque_forward_scene.composition_debug_height_count =
            composition_debug_heights.size();
        constexpr float composition_grid_span = 1.4375f;
        constexpr float composition_grid_origin = -0.71875f;
        opaque_forward_scene.composition_debug_modelview_projection[0] =
            composition_grid_span /
            static_cast<float>(AL_METAL_COMPOSITION_DEBUG_EDGE - 1);
        opaque_forward_scene.composition_debug_modelview_projection[5] =
            composition_grid_span /
            static_cast<float>(AL_METAL_COMPOSITION_DEBUG_EDGE - 1);
        opaque_forward_scene.composition_debug_modelview_projection[10] =
            1.f;
        opaque_forward_scene.composition_debug_modelview_projection[12] =
            composition_grid_origin;
        opaque_forward_scene.composition_debug_modelview_projection[13] =
            composition_grid_origin;
        opaque_forward_scene.composition_debug_modelview_projection[15] =
            1.f;

        opaque_forward_scene.composition_debug_heights = nullptr;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world composition-debug storage is invalid");
        opaque_forward_scene.composition_debug_heights =
            composition_debug_heights.data();
        opaque_forward_scene.composition_debug_height_count = 1;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world composition-debug storage is invalid");
        opaque_forward_scene.composition_debug_height_count =
            composition_debug_heights.size();
        opaque_forward_scene.composition_debug_modelview_projection[0] =
            std::numeric_limits<float>::quiet_NaN();
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world composition-debug storage is invalid");
        opaque_forward_scene.composition_debug_modelview_projection[0] =
            composition_grid_span /
            static_cast<float>(AL_METAL_COMPOSITION_DEBUG_EDGE - 1);
        composition_debug_heights[0] =
            std::numeric_limits<float>::quiet_NaN();
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world composition-debug height is non-finite");
        composition_debug_heights[0] = 0.f;
        error.clear();

        auto native_composition_debug =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(native_composition_debug);
        std::array<std::uint16_t, 32 * 32 * 4>
            composition_debug_pixels{};
        std::array<float, 32 * 32> composition_debug_depth{};
        REQUIRE(native_composition_debug->colorTexture(0)->readback(
            *device, 0, 0, {}, composition_debug_pixels.data(),
            32 * 8, &error));
        REQUIRE(native_composition_debug->depthStencilTexture()->readback(
            *device, 0, 0, {}, composition_debug_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        const std::size_t composition_blue = (16 * 32 + 16) * 4;
        const std::size_t composition_red = (27 * 32 + 27) * 4;
        CHECK(composition_debug_pixels[composition_blue + 0] == 0u);
        CHECK(composition_debug_pixels[composition_blue + 1] == 0u);
        CHECK(composition_debug_pixels[composition_blue + 2] == 0x3c00);
        CHECK(composition_debug_pixels[composition_blue + 3] ==
              opaque_forward_pixels[composition_blue + 3]);
        CHECK(composition_debug_pixels[composition_red + 0] == 0x3c00);
        CHECK(composition_debug_pixels[composition_red + 1] == 0u);
        CHECK(composition_debug_pixels[composition_red + 2] == 0u);
        CHECK(composition_debug_pixels[composition_red + 3] ==
              opaque_forward_pixels[composition_red + 3]);
        CHECK(std::abs(
            composition_debug_depth[16 * 32 + 16] - 0.5f) < 0.0001f);

        std::fill(
            composition_debug_heights.begin(),
            composition_debug_heights.end(), 0.75f);
        auto hidden_composition_debug =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(hidden_composition_debug);
        composition_debug_pixels.fill(0xffffu);
        composition_debug_depth.fill(-1.f);
        REQUIRE(hidden_composition_debug->colorTexture(0)->readback(
            *device, 0, 0, {}, composition_debug_pixels.data(),
            32 * 8, &error));
        REQUIRE(hidden_composition_debug->depthStencilTexture()->readback(
            *device, 0, 0, {}, composition_debug_depth.data(),
            32 * sizeof(float), &error));
        CHECK(composition_debug_pixels[composition_blue + 0] ==
              opaque_forward_pixels[composition_blue + 0]);
        CHECK(composition_debug_pixels[composition_blue + 1] ==
              opaque_forward_pixels[composition_blue + 1]);
        CHECK(composition_debug_pixels[composition_blue + 2] ==
              opaque_forward_pixels[composition_blue + 2]);
        CHECK(std::abs(
            composition_debug_depth[16 * 32 + 16] -
            opaque_forward_depth[16 * 32 + 16]) < 0.0001f);

        opaque_forward_scene.gbuffer = reverse_coverage_result.get();
        opaque_forward_scene.reverse_z = true;
        std::fill(
            composition_debug_heights.begin(),
            composition_debug_heights.end(), 0.9f);
        auto reverse_composition_debug =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_composition_debug);
        composition_debug_pixels.fill(0xffffu);
        composition_debug_depth.fill(-1.f);
        REQUIRE(reverse_composition_debug->colorTexture(0)->readback(
            *device, 0, 0, {}, composition_debug_pixels.data(),
            32 * 8, &error));
        REQUIRE(reverse_composition_debug->depthStencilTexture()->readback(
            *device, 0, 0, {}, composition_debug_depth.data(),
            32 * sizeof(float), &error));
        CHECK(composition_debug_pixels[composition_blue + 0] == 0u);
        CHECK(composition_debug_pixels[composition_blue + 1] == 0u);
        CHECK(composition_debug_pixels[composition_blue + 2] == 0x3c00);
        CHECK(std::abs(
            composition_debug_depth[16 * 32 + 16] - 0.9f) < 0.0001f);

        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.reverse_z = false;
        opaque_forward_scene.composition_debug_heights = nullptr;
        opaque_forward_scene.composition_debug_height_count = 0;
        auto no_composition_debug = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(no_composition_debug);
        composition_debug_pixels.fill(0xffffu);
        composition_debug_depth.fill(-1.f);
        REQUIRE(no_composition_debug->colorTexture(0)->readback(
            *device, 0, 0, {}, composition_debug_pixels.data(),
            32 * 8, &error));
        REQUIRE(no_composition_debug->depthStencilTexture()->readback(
            *device, 0, 0, {}, composition_debug_depth.data(),
            32 * sizeof(float), &error));
        CHECK(composition_debug_pixels == opaque_forward_pixels);
        CHECK(composition_debug_depth == opaque_forward_depth);

        // Develop > Agent Target emits four 0.2 m self-avatar crosshairs as
        // translucent RGB-only lines. The enclosing spatial-debug owner has
        // alpha blending enabled and inherits the display's read/write
        // GL_LEQUAL depth state (GEQUAL under reverse-Z), while scene alpha
        // remains untouched.
        std::array<ALMetalWorldAgentTargetVertex, 24>
            agent_target_lines{};
        std::size_t agent_target_offset = 0;
        const auto append_agent_target =
            [&](float x, float y, float z,
                const std::array<float, 4>& color)
            {
                constexpr float size = 0.1875f;
                const float positions[6][3] = {
                    {x - size, y, z}, {x + size, y, z},
                    {x, y - size, z}, {x, y + size, z},
                    {x, y, z - size}, {x, y, z + size},
                };
                for (const auto& position : positions)
                {
                    ALMetalWorldAgentTargetVertex& vertex =
                        agent_target_lines[agent_target_offset++];
                    std::memcpy(
                        vertex.position, position, sizeof(position));
                    std::memcpy(
                        vertex.color, color.data(),
                        sizeof(vertex.color));
                }
            };
        const std::array<std::array<float, 4>, 4>
            agent_target_source_colors{{
                {{1.f, 0.f, 0.f, 0.8f}},
                {{0.f, 1.f, 0.f, 0.8f}},
                {{1.f, 1.f, 1.f, 0.8f}},
                {{0.f, 0.f, 1.f, 0.8f}},
            }};
        append_agent_target(
            -0.71875f, -0.71875f, 0.f,
            agent_target_source_colors[0]);
        append_agent_target(
            -0.21875f, -0.71875f, 0.f,
            agent_target_source_colors[1]);
        append_agent_target(
            0.28125f, -0.71875f, 0.f,
            agent_target_source_colors[2]);
        append_agent_target(
            0.71875f, -0.71875f, 0.f,
            agent_target_source_colors[3]);
        REQUIRE(agent_target_offset == agent_target_lines.size());
        opaque_forward_scene.agent_target_lines =
            agent_target_lines.data();
        opaque_forward_scene.agent_target_line_vertex_count =
            agent_target_lines.size();
        for (std::size_t axis = 0; axis < 4; ++axis)
        {
            opaque_forward_scene.agent_target_modelview_projection[
                axis * 4 + axis] = 1.f;
        }

        opaque_forward_scene.agent_target_lines = nullptr;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world agent-target storage is invalid");
        opaque_forward_scene.agent_target_lines =
            agent_target_lines.data();
        opaque_forward_scene.agent_target_line_vertex_count = 6;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world agent-target storage is invalid");
        opaque_forward_scene.agent_target_line_vertex_count =
            agent_target_lines.size();
        agent_target_lines[0].position[0] =
            std::numeric_limits<float>::quiet_NaN();
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world agent-target data is non-finite");
        agent_target_lines[0].position[0] = -0.90625f;
        error.clear();

        auto native_agent_target = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(native_agent_target);
        std::array<std::uint16_t, 32 * 32 * 4> agent_target_pixels{};
        std::array<float, 32 * 32> agent_target_depth{};
        REQUIRE(native_agent_target->colorTexture(0)->readback(
            *device, 0, 0, {}, agent_target_pixels.data(), 32 * 8,
            &error));
        REQUIRE(native_agent_target->depthStencilTexture()->readback(
            *device, 0, 0, {}, agent_target_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        std::array<std::size_t, 4> agent_target_color_pixels{};
        const std::array<int, 4> agent_target_centers{{4, 12, 20, 27}};
        const auto agent_half_to_float = [](std::uint16_t bits)
        {
            __fp16 value;
            std::memcpy(&value, &bits, sizeof(value));
            return static_cast<float>(value);
        };
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            const bool changed =
                agent_target_pixels[offset + 0] !=
                    opaque_forward_pixels[offset + 0] ||
                agent_target_pixels[offset + 1] !=
                    opaque_forward_pixels[offset + 1] ||
                agent_target_pixels[offset + 2] !=
                    opaque_forward_pixels[offset + 2];
            if (changed)
            {
                const int x = static_cast<int>(pixel % 32);
                const int y = static_cast<int>(pixel / 32);
                std::size_t owner = agent_target_centers.size();
                for (std::size_t crosshair = 0;
                     crosshair < agent_target_centers.size(); ++crosshair)
                {
                    if (std::abs(x - agent_target_centers[crosshair]) <= 3 &&
                        std::abs(y - 4) <= 3)
                    {
                        owner = crosshair;
                        break;
                    }
                }
                REQUIRE(owner < agent_target_centers.size());
                CHECK(agent_target_pixels[offset + 3] ==
                      opaque_forward_pixels[offset + 3]);
                CHECK(agent_target_depth[pixel] <=
                      opaque_forward_depth[pixel]);
                // The X/Y/Z line pairs deliberately meet at the center, so
                // that one pixel can receive the same alpha blend more than
                // once. Every arm pixel receives exactly one blend.
                if (x != agent_target_centers[owner] || y != 4)
                {
                    CHECK(std::abs(agent_target_depth[pixel] - 0.5f) <
                          0.0001f);
                    for (std::size_t channel = 0; channel < 3; ++channel)
                    {
                        const float destination = agent_half_to_float(
                            opaque_forward_pixels[offset + channel]);
                        const float expected =
                            agent_target_source_colors[owner][channel] *
                                0.8f +
                            destination * 0.2f;
                        CHECK(std::abs(
                            agent_half_to_float(
                                agent_target_pixels[offset + channel]) -
                            expected) < 0.001f);
                    }
                }
                ++agent_target_color_pixels[owner];
            }
        }
        for (std::size_t color = 0;
             color < agent_target_color_pixels.size(); ++color)
        {
            CAPTURE(color, agent_target_color_pixels[color]);
            CHECK(agent_target_color_pixels[color] >= 8);
        }
        CHECK(agent_target_depth != opaque_forward_depth);

        // The spatial traversal can encounter drawable-centre Points before
        // and after the self avatar. Preserve that order rather than grouping
        // the two debug families. A point after the red crosshair overwrites
        // its centre white; the same point before it is alpha-blended red.
        debug_points[0].position[0] = -0.71875f;
        debug_points[0].position[1] = -0.71875f;
        debug_points[0].position[2] = 0.9f;
        debug_point_batches[0].first_vertex = 0;
        debug_point_batches[0].vertex_count = 1;
        debug_point_batches[0].order = 1;
        opaque_forward_scene.debug_points = debug_points.data();
        opaque_forward_scene.debug_point_count = 1;
        opaque_forward_scene.debug_point_batches =
            debug_point_batches.data();
        opaque_forward_scene.debug_point_batch_count = 1;
        opaque_forward_scene.agent_target_order = 0;
        auto point_after_agent = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(point_after_agent);
        std::array<std::uint16_t, 32 * 32 * 4>
            point_after_agent_pixels{};
        REQUIRE(point_after_agent->colorTexture(0)->readback(
            *device, 0, 0, {}, point_after_agent_pixels.data(),
            32 * 8, &error));
        const std::size_t ordered_debug_pixel = (4 * 32 + 4) * 4;
        CHECK(point_after_agent_pixels[ordered_debug_pixel + 0] == 0x3c00);
        CHECK(point_after_agent_pixels[ordered_debug_pixel + 1] == 0x3c00);
        CHECK(point_after_agent_pixels[ordered_debug_pixel + 2] == 0x3c00);
        CHECK(point_after_agent_pixels[ordered_debug_pixel + 3] ==
              opaque_forward_pixels[ordered_debug_pixel + 3]);

        debug_point_batches[0].order = 0;
        opaque_forward_scene.agent_target_order = 1;
        auto point_before_agent = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(point_before_agent);
        std::array<std::uint16_t, 32 * 32 * 4>
            point_before_agent_pixels{};
        REQUIRE(point_before_agent->colorTexture(0)->readback(
            *device, 0, 0, {}, point_before_agent_pixels.data(),
            32 * 8, &error));
        CHECK(point_before_agent_pixels[ordered_debug_pixel + 0] == 0x3c00);
        CHECK(point_before_agent_pixels[ordered_debug_pixel + 1] < 0x3c00);
        CHECK(point_before_agent_pixels[ordered_debug_pixel + 2] < 0x3c00);
        CHECK(point_before_agent_pixels[ordered_debug_pixel + 3] ==
              opaque_forward_pixels[ordered_debug_pixel + 3]);

        opaque_forward_scene.agent_target_order = 0;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world drawable-centre point batch is invalid");
        opaque_forward_scene.agent_target_order = 0;
        opaque_forward_scene.debug_points = nullptr;
        opaque_forward_scene.debug_point_count = 0;
        opaque_forward_scene.debug_point_batches = nullptr;
        opaque_forward_scene.debug_point_batch_count = 0;

        // Place all four crosshairs inside the known covered centre. At GL
        // depth 0 (Metal 0.5) they pass and write; at GL depth 0.75 (Metal
        // 0.875) they are behind the retained 0.625 surface and every line is
        // rejected. This distinguishes inherited read/write depth from an
        // always-on-top diagnostic composite.
        auto agent_target_depth_lines = agent_target_lines;
        const float depth_crosshair_positions[6][2] = {
            {-0.1875f, 0.f}, {0.1875f, 0.f},
            {0.f, -0.1875f}, {0.f, 0.1875f},
            {0.f, 0.f}, {0.f, 0.f},
        };
        for (std::size_t crosshair = 0; crosshair < 4; ++crosshair)
        {
            for (std::size_t vertex = 0; vertex < 6; ++vertex)
            {
                ALMetalWorldAgentTargetVertex& target =
                    agent_target_depth_lines[crosshair * 6 + vertex];
                target.position[0] =
                    depth_crosshair_positions[vertex][0];
                target.position[1] =
                    depth_crosshair_positions[vertex][1];
                target.position[2] = 0.f;
            }
        }
        opaque_forward_scene.agent_target_lines =
            agent_target_depth_lines.data();
        auto near_agent_target = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(near_agent_target);
        std::array<std::uint16_t, 32 * 32 * 4>
            near_agent_target_pixels{};
        std::array<float, 32 * 32> near_agent_target_depth{};
        REQUIRE(near_agent_target->colorTexture(0)->readback(
            *device, 0, 0, {}, near_agent_target_pixels.data(),
            32 * 8, &error));
        REQUIRE(near_agent_target->depthStencilTexture()->readback(
            *device, 0, 0, {}, near_agent_target_depth.data(),
            32 * sizeof(float), &error));
        std::size_t near_agent_target_changed = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            const bool changed =
                near_agent_target_pixels[offset + 0] !=
                    opaque_forward_pixels[offset + 0] ||
                near_agent_target_pixels[offset + 1] !=
                    opaque_forward_pixels[offset + 1] ||
                near_agent_target_pixels[offset + 2] !=
                    opaque_forward_pixels[offset + 2];
            near_agent_target_changed += changed;
            if (changed)
            {
                CHECK(near_agent_target_pixels[offset + 3] ==
                      opaque_forward_pixels[offset + 3]);
                CHECK(std::abs(near_agent_target_depth[pixel] - 0.5f) <
                      0.0001f);
            }
        }
        CHECK(near_agent_target_changed > 0);
        for (ALMetalWorldAgentTargetVertex& vertex :
             agent_target_depth_lines)
        {
            vertex.position[2] = 0.75f;
        }
        auto hidden_agent_target = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(hidden_agent_target);
        std::array<std::uint16_t, 32 * 32 * 4>
            hidden_agent_target_pixels{};
        std::array<float, 32 * 32> hidden_agent_target_depth{};
        REQUIRE(hidden_agent_target->colorTexture(0)->readback(
            *device, 0, 0, {}, hidden_agent_target_pixels.data(),
            32 * 8, &error));
        REQUIRE(hidden_agent_target->depthStencilTexture()->readback(
            *device, 0, 0, {}, hidden_agent_target_depth.data(),
            32 * sizeof(float), &error));
        CHECK(hidden_agent_target_pixels == opaque_forward_pixels);
        CHECK(hidden_agent_target_depth == opaque_forward_depth);

        opaque_forward_scene.gbuffer = reverse_coverage_result.get();
        opaque_forward_scene.reverse_z = true;
        opaque_forward_scene.agent_target_lines = nullptr;
        opaque_forward_scene.agent_target_line_vertex_count = 0;
        auto reverse_agent_target_baseline =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_agent_target_baseline);
        std::array<std::uint16_t, 32 * 32 * 4>
            reverse_agent_target_baseline_pixels{};
        std::array<float, 32 * 32>
            reverse_agent_target_baseline_depth{};
        REQUIRE(reverse_agent_target_baseline->colorTexture(0)->readback(
            *device, 0, 0, {},
            reverse_agent_target_baseline_pixels.data(), 32 * 8,
            &error));
        REQUIRE(
            reverse_agent_target_baseline->depthStencilTexture()->readback(
                *device, 0, 0, {},
                reverse_agent_target_baseline_depth.data(),
                32 * sizeof(float), &error));
        debug_points[0].position[0] = 0.03125f;
        debug_points[0].position[1] = 0.03125f;
        debug_points[0].position[2] = 0.9f;
        debug_point_batches[0].first_vertex = 0;
        debug_point_batches[0].vertex_count = 1;
        debug_point_batches[0].order = 0;
        opaque_forward_scene.debug_points = debug_points.data();
        opaque_forward_scene.debug_point_count = 1;
        opaque_forward_scene.debug_point_batches =
            debug_point_batches.data();
        opaque_forward_scene.debug_point_batch_count = 1;
        auto reverse_debug_point = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_debug_point);
        std::array<std::uint16_t, 32 * 32 * 4>
            reverse_debug_point_pixels{};
        std::array<float, 32 * 32> reverse_debug_point_depth{};
        REQUIRE(reverse_debug_point->colorTexture(0)->readback(
            *device, 0, 0, {}, reverse_debug_point_pixels.data(),
            32 * 8, &error));
        REQUIRE(reverse_debug_point->depthStencilTexture()->readback(
            *device, 0, 0, {}, reverse_debug_point_depth.data(),
            32 * sizeof(float), &error));
        std::size_t reverse_debug_point_changed = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            const bool changed =
                reverse_debug_point_pixels[offset + 0] !=
                    reverse_agent_target_baseline_pixels[offset + 0] ||
                reverse_debug_point_pixels[offset + 1] !=
                    reverse_agent_target_baseline_pixels[offset + 1] ||
                reverse_debug_point_pixels[offset + 2] !=
                    reverse_agent_target_baseline_pixels[offset + 2];
            reverse_debug_point_changed += changed;
            if (changed)
            {
                CHECK(reverse_debug_point_pixels[offset + 0] == 0x3c00);
                CHECK(reverse_debug_point_pixels[offset + 1] == 0x3c00);
                CHECK(reverse_debug_point_pixels[offset + 2] == 0x3c00);
                CHECK(reverse_debug_point_pixels[offset + 3] ==
                      reverse_agent_target_baseline_pixels[offset + 3]);
            }
        }
        CHECK(reverse_debug_point_changed == 1);
        CHECK(reverse_debug_point_depth ==
              reverse_agent_target_baseline_depth);
        opaque_forward_scene.debug_points = nullptr;
        opaque_forward_scene.debug_point_count = 0;
        opaque_forward_scene.debug_point_batches = nullptr;
        opaque_forward_scene.debug_point_batch_count = 0;
        for (ALMetalWorldAgentTargetVertex& vertex : agent_target_lines)
        {
            vertex.position[2] = 0.9f;
        }
        opaque_forward_scene.agent_target_lines =
            agent_target_lines.data();
        opaque_forward_scene.agent_target_line_vertex_count =
            agent_target_lines.size();
        auto reverse_agent_target = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_agent_target);
        std::array<std::uint16_t, 32 * 32 * 4>
            reverse_agent_target_pixels{};
        std::array<float, 32 * 32> reverse_agent_target_depth{};
        REQUIRE(reverse_agent_target->colorTexture(0)->readback(
            *device, 0, 0, {}, reverse_agent_target_pixels.data(),
            32 * 8, &error));
        REQUIRE(reverse_agent_target->depthStencilTexture()->readback(
            *device, 0, 0, {}, reverse_agent_target_depth.data(),
            32 * sizeof(float), &error));
        std::size_t reverse_agent_target_changed = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            const bool changed =
                reverse_agent_target_pixels[offset + 0] !=
                    reverse_agent_target_baseline_pixels[offset + 0] ||
                reverse_agent_target_pixels[offset + 1] !=
                    reverse_agent_target_baseline_pixels[offset + 1] ||
                reverse_agent_target_pixels[offset + 2] !=
                    reverse_agent_target_baseline_pixels[offset + 2];
            reverse_agent_target_changed += changed;
            if (changed)
            {
                CHECK(reverse_agent_target_pixels[offset + 3] ==
                      reverse_agent_target_baseline_pixels[offset + 3]);
                CHECK(std::abs(reverse_agent_target_depth[pixel] - 0.9f) <
                      0.0001f);
            }
        }
        CHECK(reverse_agent_target_changed >= 32);
        CHECK(reverse_agent_target_depth !=
              reverse_agent_target_baseline_depth);

        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.reverse_z = false;
        opaque_forward_scene.agent_target_lines = nullptr;
        opaque_forward_scene.agent_target_line_vertex_count = 0;
        auto no_agent_target = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(no_agent_target);
        agent_target_pixels.fill(0xffffu);
        agent_target_depth.fill(-1.f);
        REQUIRE(no_agent_target->colorTexture(0)->readback(
            *device, 0, 0, {}, agent_target_pixels.data(), 32 * 8,
            &error));
        REQUIRE(no_agent_target->depthStencilTexture()->readback(
            *device, 0, 0, {}, agent_target_depth.data(),
            32 * sizeof(float), &error));
        CHECK(agent_target_pixels == opaque_forward_pixels);
        CHECK(agent_target_depth == opaque_forward_depth);

        // Develop > Collision Skeleton emits two line/sphere pairs per
        // avatar collision volume. The colored shell and white centre dot
        // preserve their live transforms and traversal order. Visible pieces
        // use writable ambient depth; hidden pieces use the complementary
        // read-only comparison, including under reverse-Z.
        std::array<ALMetalWorldAvatarVolumeBatch, 2>
            avatar_volume_batches{};
        const auto set_avatar_volume_transform = [](
            float* matrix, float scale, float depth)
        {
            std::fill(matrix, matrix + 16, 0.f);
            matrix[0] = scale;
            matrix[5] = scale;
            matrix[10] = scale;
            matrix[14] = depth;
            matrix[15] = 1.f;
        };
        for (ALMetalWorldAvatarVolumeBatch& batch :
             avatar_volume_batches)
        {
            for (std::size_t axis = 0; axis < 4; ++axis)
            {
                batch.line_modelview_projection[axis * 4 + axis] = 1.f;
            }
            batch.end[0] = 0.5f;
            batch.end[3] = 1.f;
        }
        set_avatar_volume_transform(
            avatar_volume_batches[0].sphere_modelview_projection,
            0.125f, 0.f);
        avatar_volume_batches[0].visible_color[0] = 0.5f;
        avatar_volume_batches[0].visible_color[1] = 0.5f;
        avatar_volume_batches[0].visible_color[2] = 1.f;
        avatar_volume_batches[0].visible_color[3] = 1.f;
        avatar_volume_batches[0].occluded_color[0] = 0.f;
        avatar_volume_batches[0].occluded_color[1] = 0.f;
        avatar_volume_batches[0].occluded_color[2] = 1.f;
        avatar_volume_batches[0].occluded_color[3] = 1.f;
        avatar_volume_batches[0].sphere_scale = 1.f;
        avatar_volume_batches[0].order = 0;
        set_avatar_volume_transform(
            avatar_volume_batches[1].sphere_modelview_projection,
            0.01f, 0.f);
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            avatar_volume_batches[1].visible_color[channel] = 1.f;
            avatar_volume_batches[1].occluded_color[channel] = 1.f;
        }
        avatar_volume_batches[1].sphere_scale = 0.05f;
        avatar_volume_batches[1].order = 1;
        opaque_forward_scene.avatar_volume_batches =
            avatar_volume_batches.data();
        opaque_forward_scene.avatar_volume_batch_count =
            avatar_volume_batches.size();

        opaque_forward_scene.avatar_volume_batches = nullptr;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world avatar-volume batch storage is invalid");
        opaque_forward_scene.avatar_volume_batches =
            avatar_volume_batches.data();
        opaque_forward_scene.avatar_volume_batch_count = 1;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world avatar-volume batch storage is invalid");
        opaque_forward_scene.avatar_volume_batch_count =
            avatar_volume_batches.size();
        avatar_volume_batches[0].line_modelview_projection[0] =
            std::numeric_limits<float>::quiet_NaN();
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world avatar-volume batch is invalid");
        avatar_volume_batches[0].line_modelview_projection[0] = 1.f;
        avatar_volume_batches[1].sphere_scale = 0.5f;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world avatar-volume batch is invalid");
        avatar_volume_batches[1].sphere_scale = 0.05f;
        avatar_volume_batches[0].visible_color[0] = 1.f;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world avatar-volume batch is invalid");
        avatar_volume_batches[0].visible_color[0] = 0.5f;
        avatar_volume_batches[1].end[0] = 0.25f;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world avatar-volume batch is invalid");
        avatar_volume_batches[1].end[0] = 0.5f;
        opaque_forward_scene.agent_target_lines = agent_target_lines.data();
        opaque_forward_scene.agent_target_line_vertex_count =
            agent_target_lines.size();
        opaque_forward_scene.agent_target_order = 0;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world avatar-volume batch is invalid");
        opaque_forward_scene.agent_target_lines = nullptr;
        opaque_forward_scene.agent_target_line_vertex_count = 0;
        error.clear();

        // Collision volumes occur before Agent Target for the same avatar,
        // but a previous drawable can contribute an earlier target owner.
        // Prove the shared order stream instead of merely validating unique
        // sequence numbers: the translucent crosshairs produce different
        // pixels on opposite sides of the opaque collision-volume replay.
        for (ALMetalWorldAgentTargetVertex& vertex :
             agent_target_depth_lines)
        {
            vertex.position[2] = 0.f;
        }
        opaque_forward_scene.agent_target_lines =
            agent_target_depth_lines.data();
        opaque_forward_scene.agent_target_line_vertex_count =
            agent_target_depth_lines.size();
        opaque_forward_scene.agent_target_order = 2;
        auto agent_after_avatar_volume =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(agent_after_avatar_volume);
        std::array<std::uint16_t, 32 * 32 * 4>
            agent_after_avatar_volume_pixels{};
        REQUIRE(agent_after_avatar_volume->colorTexture(0)->readback(
            *device, 0, 0, {},
            agent_after_avatar_volume_pixels.data(), 32 * 8,
            &error));

        opaque_forward_scene.agent_target_order = 0;
        avatar_volume_batches[0].order = 1;
        avatar_volume_batches[1].order = 2;
        auto agent_before_avatar_volume =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(agent_before_avatar_volume);
        std::array<std::uint16_t, 32 * 32 * 4>
            agent_before_avatar_volume_pixels{};
        REQUIRE(agent_before_avatar_volume->colorTexture(0)->readback(
            *device, 0, 0, {},
            agent_before_avatar_volume_pixels.data(), 32 * 8,
            &error));
        CHECK(agent_after_avatar_volume_pixels !=
              agent_before_avatar_volume_pixels);
        opaque_forward_scene.agent_target_lines = nullptr;
        opaque_forward_scene.agent_target_line_vertex_count = 0;
        avatar_volume_batches[0].order = 0;
        avatar_volume_batches[1].order = 1;

        auto visible_avatar_volume = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(visible_avatar_volume);
        std::array<std::uint16_t, 32 * 32 * 4>
            visible_avatar_volume_pixels{};
        std::array<float, 32 * 32> visible_avatar_volume_depth{};
        REQUIRE(visible_avatar_volume->colorTexture(0)->readback(
            *device, 0, 0, {}, visible_avatar_volume_pixels.data(),
            32 * 8, &error));
        REQUIRE(visible_avatar_volume->depthStencilTexture()->readback(
            *device, 0, 0, {}, visible_avatar_volume_depth.data(),
            32 * sizeof(float), &error));
        std::size_t visible_avatar_volume_changed = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            const bool changed =
                visible_avatar_volume_pixels[offset + 0] !=
                    opaque_forward_pixels[offset + 0] ||
                visible_avatar_volume_pixels[offset + 1] !=
                    opaque_forward_pixels[offset + 1] ||
                visible_avatar_volume_pixels[offset + 2] !=
                    opaque_forward_pixels[offset + 2];
            visible_avatar_volume_changed += changed;
            if (changed)
            {
                CHECK(visible_avatar_volume_pixels[offset + 3] ==
                      opaque_forward_pixels[offset + 3]);
                CHECK(visible_avatar_volume_depth[pixel] <=
                      opaque_forward_depth[pixel]);
            }
        }
        CHECK(visible_avatar_volume_changed >= 8);
        CHECK(visible_avatar_volume_depth != opaque_forward_depth);

        for (ALMetalWorldAvatarVolumeBatch& batch :
             avatar_volume_batches)
        {
            batch.line_modelview_projection[14] = 0.75f;
            batch.sphere_modelview_projection[14] = 0.75f;
        }
        auto occluded_avatar_volume = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(occluded_avatar_volume);
        std::array<std::uint16_t, 32 * 32 * 4>
            occluded_avatar_volume_pixels{};
        std::array<float, 32 * 32> occluded_avatar_volume_depth{};
        REQUIRE(occluded_avatar_volume->colorTexture(0)->readback(
            *device, 0, 0, {}, occluded_avatar_volume_pixels.data(),
            32 * 8, &error));
        REQUIRE(occluded_avatar_volume->depthStencilTexture()->readback(
            *device, 0, 0, {}, occluded_avatar_volume_depth.data(),
            32 * sizeof(float), &error));
        std::size_t occluded_avatar_volume_changed = 0;
        std::size_t occluded_avatar_volume_readonly = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            const bool changed =
                occluded_avatar_volume_pixels[offset + 0] !=
                    opaque_forward_pixels[offset + 0] ||
                occluded_avatar_volume_pixels[offset + 1] !=
                    opaque_forward_pixels[offset + 1] ||
                occluded_avatar_volume_pixels[offset + 2] !=
                    opaque_forward_pixels[offset + 2];
            occluded_avatar_volume_changed += changed;
            if (changed)
            {
                CHECK(occluded_avatar_volume_pixels[offset + 3] ==
                      opaque_forward_pixels[offset + 3]);
                if (opaque_forward_depth[pixel] < 1.f)
                {
                    CHECK(occluded_avatar_volume_depth[pixel] ==
                          opaque_forward_depth[pixel]);
                    ++occluded_avatar_volume_readonly;
                }
            }
        }
        CHECK(occluded_avatar_volume_changed >= 8);
        CHECK(occluded_avatar_volume_readonly >= 8);

        opaque_forward_scene.gbuffer = reverse_coverage_result.get();
        opaque_forward_scene.reverse_z = true;
        for (ALMetalWorldAvatarVolumeBatch& batch :
             avatar_volume_batches)
        {
            batch.line_modelview_projection[14] = 0.9f;
            batch.sphere_modelview_projection[14] = 0.9f;
        }
        auto reverse_visible_avatar_volume =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_visible_avatar_volume);
        std::array<std::uint16_t, 32 * 32 * 4>
            reverse_visible_avatar_volume_pixels{};
        std::array<float, 32 * 32>
            reverse_visible_avatar_volume_depth{};
        REQUIRE(reverse_visible_avatar_volume->colorTexture(0)->readback(
            *device, 0, 0, {},
            reverse_visible_avatar_volume_pixels.data(), 32 * 8,
            &error));
        REQUIRE(
            reverse_visible_avatar_volume->depthStencilTexture()->readback(
                *device, 0, 0, {},
                reverse_visible_avatar_volume_depth.data(),
                32 * sizeof(float), &error));
        std::size_t reverse_visible_avatar_volume_changed = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            const bool changed =
                reverse_visible_avatar_volume_pixels[offset + 0] !=
                    reverse_agent_target_baseline_pixels[offset + 0] ||
                reverse_visible_avatar_volume_pixels[offset + 1] !=
                    reverse_agent_target_baseline_pixels[offset + 1] ||
                reverse_visible_avatar_volume_pixels[offset + 2] !=
                    reverse_agent_target_baseline_pixels[offset + 2];
            reverse_visible_avatar_volume_changed += changed;
            if (changed)
            {
                CHECK(reverse_visible_avatar_volume_pixels[offset + 3] ==
                      reverse_agent_target_baseline_pixels[offset + 3]);
                CHECK(reverse_visible_avatar_volume_depth[pixel] >=
                      reverse_agent_target_baseline_depth[pixel]);
            }
        }
        CHECK(reverse_visible_avatar_volume_changed >= 8);
        CHECK(reverse_visible_avatar_volume_depth !=
              reverse_agent_target_baseline_depth);

        for (ALMetalWorldAvatarVolumeBatch& batch :
             avatar_volume_batches)
        {
            batch.line_modelview_projection[14] = 0.1f;
            batch.sphere_modelview_projection[14] = 0.1f;
        }
        auto reverse_occluded_avatar_volume =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_occluded_avatar_volume);
        std::array<std::uint16_t, 32 * 32 * 4>
            reverse_occluded_avatar_volume_pixels{};
        std::array<float, 32 * 32>
            reverse_occluded_avatar_volume_depth{};
        REQUIRE(reverse_occluded_avatar_volume->colorTexture(0)->readback(
            *device, 0, 0, {},
            reverse_occluded_avatar_volume_pixels.data(), 32 * 8,
            &error));
        REQUIRE(
            reverse_occluded_avatar_volume->depthStencilTexture()->readback(
                *device, 0, 0, {},
                reverse_occluded_avatar_volume_depth.data(),
                32 * sizeof(float), &error));
        std::size_t reverse_occluded_avatar_volume_changed = 0;
        std::size_t reverse_occluded_avatar_volume_readonly = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            const bool changed =
                reverse_occluded_avatar_volume_pixels[offset + 0] !=
                    reverse_agent_target_baseline_pixels[offset + 0] ||
                reverse_occluded_avatar_volume_pixels[offset + 1] !=
                    reverse_agent_target_baseline_pixels[offset + 1] ||
                reverse_occluded_avatar_volume_pixels[offset + 2] !=
                    reverse_agent_target_baseline_pixels[offset + 2];
            reverse_occluded_avatar_volume_changed += changed;
            if (changed && reverse_agent_target_baseline_depth[pixel] > 0.f)
            {
                CHECK(reverse_occluded_avatar_volume_depth[pixel] ==
                      reverse_agent_target_baseline_depth[pixel]);
                ++reverse_occluded_avatar_volume_readonly;
            }
        }
        CHECK(reverse_occluded_avatar_volume_changed >= 8);
        CHECK(reverse_occluded_avatar_volume_readonly >= 8);

        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.reverse_z = false;
        opaque_forward_scene.avatar_volume_batches = nullptr;
        opaque_forward_scene.avatar_volume_batch_count = 0;

        // Develop > Joints emits one visible/occluded line-and-sphere pair
        // per skeleton joint, followed by yellow joint-space and cyan
        // attachment-face rigged bounds. All records share the global debug
        // order while retaining the source's writable visible depth and
        // complementary read-only hidden pass.
        std::array<ALMetalWorldAvatarJointBatch, 3>
            avatar_joint_batches{};
        ALMetalWorldAvatarJointBatch& avatar_joint_segment =
            avatar_joint_batches[0];
        avatar_joint_segment.kind =
            ALMetalWorldAvatarJointKind::segment;
        for (std::size_t axis = 0; axis < 4; ++axis)
        {
            avatar_joint_segment
                .line_modelview_projection[axis * 4 + axis] = 1.f;
        }
        set_avatar_volume_transform(
            avatar_joint_segment.sphere_modelview_projection,
            0.125f, 0.f);
        avatar_joint_segment.end[0] = 0.5f;
        avatar_joint_segment.visible_color[0] = 0.5f;
        avatar_joint_segment.visible_color[1] = 0.5f;
        avatar_joint_segment.visible_color[2] = 0.5f;
        avatar_joint_segment.visible_color[3] = 1.f;
        avatar_joint_segment.occluded_color[0] = 0.f;
        avatar_joint_segment.occluded_color[1] = 1.f;
        avatar_joint_segment.occluded_color[2] = 1.f;
        avatar_joint_segment.occluded_color[3] = 1.f;
        avatar_joint_segment.sphere_scale = 0.001f;
        avatar_joint_segment.order = 0;

        const auto configure_avatar_joint_bounds = [](
            ALMetalWorldAvatarJointBatch& batch,
            ALMetalWorldAvatarJointKind kind, std::uint64_t order)
        {
            batch.kind = kind;
            for (std::size_t axis = 0; axis < 4; ++axis)
            {
                batch.line_modelview_projection[axis * 4 + axis] = 1.f;
            }
            batch.center[3] = 1.f;
            batch.half_extent[0] = 0.35f;
            batch.half_extent[1] = 0.25f;
            batch.half_extent[2] = 0.1f;
            const bool attachment = kind ==
                ALMetalWorldAvatarJointKind::attachment_bounds;
            batch.visible_color[0] = attachment ? 0.f : 1.f;
            batch.visible_color[1] = 1.f;
            batch.visible_color[2] = attachment ? 1.f : 0.f;
            batch.visible_color[3] = 1.f;
            batch.order = order;
        };
        configure_avatar_joint_bounds(
            avatar_joint_batches[1],
            ALMetalWorldAvatarJointKind::joint_bounds, 1);
        configure_avatar_joint_bounds(
            avatar_joint_batches[2],
            ALMetalWorldAvatarJointKind::attachment_bounds, 2);
        avatar_joint_batches[2].center[1] = 0.4f;
        opaque_forward_scene.avatar_joint_batches =
            avatar_joint_batches.data();
        opaque_forward_scene.avatar_joint_batch_count =
            avatar_joint_batches.size();

        opaque_forward_scene.avatar_joint_batches = nullptr;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world avatar-joint batch storage is invalid");
        opaque_forward_scene.avatar_joint_batches =
            avatar_joint_batches.data();
        avatar_joint_segment.line_modelview_projection[0] =
            std::numeric_limits<float>::quiet_NaN();
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world avatar-joint batch is invalid");
        avatar_joint_segment.line_modelview_projection[0] = 1.f;
        avatar_joint_segment.sphere_scale = 0.01f;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world avatar-joint batch is invalid");
        avatar_joint_segment.sphere_scale = 0.001f;
        avatar_joint_segment.occluded_color[2] = 0.25f;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world avatar-joint batch is invalid");
        avatar_joint_segment.occluded_color[2] = 1.f;
        avatar_joint_batches[1].center[3] = 0.f;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world avatar-joint batch is invalid");
        avatar_joint_batches[1].center[3] = 1.f;
        avatar_joint_batches[2].kind =
            static_cast<ALMetalWorldAvatarJointKind>(99);
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world avatar-joint batch is invalid");
        avatar_joint_batches[2].kind =
            ALMetalWorldAvatarJointKind::attachment_bounds;
        opaque_forward_scene.agent_target_lines =
            agent_target_lines.data();
        opaque_forward_scene.agent_target_line_vertex_count =
            agent_target_lines.size();
        opaque_forward_scene.agent_target_order = 0;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world avatar-joint batch is invalid");
        opaque_forward_scene.agent_target_lines = nullptr;
        opaque_forward_scene.agent_target_line_vertex_count = 0;
        error.clear();

        opaque_forward_scene.agent_target_lines =
            agent_target_depth_lines.data();
        opaque_forward_scene.agent_target_line_vertex_count =
            agent_target_depth_lines.size();
        opaque_forward_scene.agent_target_order = 3;
        auto agent_after_avatar_joints =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(agent_after_avatar_joints);
        std::array<std::uint16_t, 32 * 32 * 4>
            agent_after_avatar_joint_pixels{};
        REQUIRE(agent_after_avatar_joints->colorTexture(0)->readback(
            *device, 0, 0, {},
            agent_after_avatar_joint_pixels.data(), 32 * 8,
            &error));

        opaque_forward_scene.agent_target_order = 0;
        for (std::size_t index = 0;
             index < avatar_joint_batches.size(); ++index)
        {
            avatar_joint_batches[index].order = index + 1;
        }
        auto agent_before_avatar_joints =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(agent_before_avatar_joints);
        std::array<std::uint16_t, 32 * 32 * 4>
            agent_before_avatar_joint_pixels{};
        REQUIRE(agent_before_avatar_joints->colorTexture(0)->readback(
            *device, 0, 0, {},
            agent_before_avatar_joint_pixels.data(), 32 * 8,
            &error));
        CHECK(agent_after_avatar_joint_pixels !=
              agent_before_avatar_joint_pixels);
        opaque_forward_scene.agent_target_lines = nullptr;
        opaque_forward_scene.agent_target_line_vertex_count = 0;
        for (std::size_t index = 0;
             index < avatar_joint_batches.size(); ++index)
        {
            avatar_joint_batches[index].order = index;
        }

        auto visible_avatar_joints = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(visible_avatar_joints);
        std::array<std::uint16_t, 32 * 32 * 4>
            visible_avatar_joint_pixels{};
        std::array<float, 32 * 32> visible_avatar_joint_depth{};
        REQUIRE(visible_avatar_joints->colorTexture(0)->readback(
            *device, 0, 0, {}, visible_avatar_joint_pixels.data(),
            32 * 8, &error));
        REQUIRE(visible_avatar_joints->depthStencilTexture()->readback(
            *device, 0, 0, {}, visible_avatar_joint_depth.data(),
            32 * sizeof(float), &error));
        std::size_t visible_avatar_joint_changed = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            const bool changed =
                visible_avatar_joint_pixels[offset + 0] !=
                    opaque_forward_pixels[offset + 0] ||
                visible_avatar_joint_pixels[offset + 1] !=
                    opaque_forward_pixels[offset + 1] ||
                visible_avatar_joint_pixels[offset + 2] !=
                    opaque_forward_pixels[offset + 2];
            visible_avatar_joint_changed += changed;
            if (changed)
            {
                CHECK(visible_avatar_joint_pixels[offset + 3] ==
                      opaque_forward_pixels[offset + 3]);
                CHECK(visible_avatar_joint_depth[pixel] <=
                      opaque_forward_depth[pixel]);
            }
        }
        CHECK(visible_avatar_joint_changed >= 16);
        CHECK(visible_avatar_joint_depth != opaque_forward_depth);

        // The generated rigged-bound path must raster independently of the
        // shared skeleton segment primitive.
        opaque_forward_scene.avatar_joint_batches =
            avatar_joint_batches.data() + 1;
        opaque_forward_scene.avatar_joint_batch_count = 2;
        auto avatar_joint_bounds = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(avatar_joint_bounds);
        std::array<std::uint16_t, 32 * 32 * 4>
            avatar_joint_bound_pixels{};
        REQUIRE(avatar_joint_bounds->colorTexture(0)->readback(
            *device, 0, 0, {}, avatar_joint_bound_pixels.data(),
            32 * 8, &error));
        CHECK(avatar_joint_bound_pixels != opaque_forward_pixels);
        opaque_forward_scene.avatar_joint_batches =
            avatar_joint_batches.data();
        opaque_forward_scene.avatar_joint_batch_count =
            avatar_joint_batches.size();

        for (ALMetalWorldAvatarJointBatch& batch : avatar_joint_batches)
        {
            batch.line_modelview_projection[14] = 0.75f;
        }
        avatar_joint_segment.sphere_modelview_projection[14] = 0.75f;
        auto occluded_avatar_joints = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(occluded_avatar_joints);
        std::array<std::uint16_t, 32 * 32 * 4>
            occluded_avatar_joint_pixels{};
        std::array<float, 32 * 32> occluded_avatar_joint_depth{};
        REQUIRE(occluded_avatar_joints->colorTexture(0)->readback(
            *device, 0, 0, {}, occluded_avatar_joint_pixels.data(),
            32 * 8, &error));
        REQUIRE(occluded_avatar_joints->depthStencilTexture()->readback(
            *device, 0, 0, {}, occluded_avatar_joint_depth.data(),
            32 * sizeof(float), &error));
        std::size_t occluded_avatar_joint_changed = 0;
        std::size_t occluded_avatar_joint_readonly = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            const bool changed =
                occluded_avatar_joint_pixels[offset + 0] !=
                    opaque_forward_pixels[offset + 0] ||
                occluded_avatar_joint_pixels[offset + 1] !=
                    opaque_forward_pixels[offset + 1] ||
                occluded_avatar_joint_pixels[offset + 2] !=
                    opaque_forward_pixels[offset + 2];
            occluded_avatar_joint_changed += changed;
            if (changed && opaque_forward_depth[pixel] < 1.f)
            {
                CHECK(occluded_avatar_joint_depth[pixel] ==
                      opaque_forward_depth[pixel]);
                ++occluded_avatar_joint_readonly;
            }
        }
        CHECK(occluded_avatar_joint_changed >= 4);
        CHECK(occluded_avatar_joint_readonly >= 4);

        opaque_forward_scene.gbuffer = reverse_coverage_result.get();
        opaque_forward_scene.reverse_z = true;
        for (ALMetalWorldAvatarJointBatch& batch : avatar_joint_batches)
        {
            batch.line_modelview_projection[14] = 0.9f;
        }
        avatar_joint_segment.sphere_modelview_projection[14] = 0.9f;
        auto reverse_visible_avatar_joints =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_visible_avatar_joints);
        std::array<std::uint16_t, 32 * 32 * 4>
            reverse_visible_avatar_joint_pixels{};
        std::array<float, 32 * 32>
            reverse_visible_avatar_joint_depth{};
        REQUIRE(reverse_visible_avatar_joints->colorTexture(0)->readback(
            *device, 0, 0, {},
            reverse_visible_avatar_joint_pixels.data(), 32 * 8,
            &error));
        REQUIRE(
            reverse_visible_avatar_joints->depthStencilTexture()->readback(
                *device, 0, 0, {},
                reverse_visible_avatar_joint_depth.data(),
                32 * sizeof(float), &error));
        std::size_t reverse_visible_avatar_joint_changed = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            const bool changed =
                reverse_visible_avatar_joint_pixels[offset + 0] !=
                    reverse_agent_target_baseline_pixels[offset + 0] ||
                reverse_visible_avatar_joint_pixels[offset + 1] !=
                    reverse_agent_target_baseline_pixels[offset + 1] ||
                reverse_visible_avatar_joint_pixels[offset + 2] !=
                    reverse_agent_target_baseline_pixels[offset + 2];
            reverse_visible_avatar_joint_changed += changed;
            if (changed)
            {
                CHECK(reverse_visible_avatar_joint_pixels[offset + 3] ==
                      reverse_agent_target_baseline_pixels[offset + 3]);
                CHECK(reverse_visible_avatar_joint_depth[pixel] >=
                      reverse_agent_target_baseline_depth[pixel]);
            }
        }
        CHECK(reverse_visible_avatar_joint_changed >= 16);
        CHECK(reverse_visible_avatar_joint_depth !=
              reverse_agent_target_baseline_depth);

        for (ALMetalWorldAvatarJointBatch& batch : avatar_joint_batches)
        {
            batch.line_modelview_projection[14] = 0.1f;
        }
        avatar_joint_segment.sphere_modelview_projection[14] = 0.1f;
        auto reverse_occluded_avatar_joints =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_occluded_avatar_joints);
        std::array<std::uint16_t, 32 * 32 * 4>
            reverse_occluded_avatar_joint_pixels{};
        std::array<float, 32 * 32>
            reverse_occluded_avatar_joint_depth{};
        REQUIRE(reverse_occluded_avatar_joints->colorTexture(0)->readback(
            *device, 0, 0, {},
            reverse_occluded_avatar_joint_pixels.data(), 32 * 8,
            &error));
        REQUIRE(
            reverse_occluded_avatar_joints->depthStencilTexture()->readback(
                *device, 0, 0, {},
                reverse_occluded_avatar_joint_depth.data(),
                32 * sizeof(float), &error));
        std::size_t reverse_occluded_avatar_joint_changed = 0;
        std::size_t reverse_occluded_avatar_joint_readonly = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            const bool changed =
                reverse_occluded_avatar_joint_pixels[offset + 0] !=
                    reverse_agent_target_baseline_pixels[offset + 0] ||
                reverse_occluded_avatar_joint_pixels[offset + 1] !=
                    reverse_agent_target_baseline_pixels[offset + 1] ||
                reverse_occluded_avatar_joint_pixels[offset + 2] !=
                    reverse_agent_target_baseline_pixels[offset + 2];
            reverse_occluded_avatar_joint_changed += changed;
            if (changed &&
                reverse_agent_target_baseline_depth[pixel] > 0.f)
            {
                CHECK(reverse_occluded_avatar_joint_depth[pixel] ==
                      reverse_agent_target_baseline_depth[pixel]);
                ++reverse_occluded_avatar_joint_readonly;
            }
        }
        CHECK(reverse_occluded_avatar_joint_changed >= 4);
        CHECK(reverse_occluded_avatar_joint_readonly >= 4);

        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.reverse_z = false;
        opaque_forward_scene.avatar_joint_batches = nullptr;
        opaque_forward_scene.avatar_joint_batch_count = 0;

        // Develop > Bounding Boxes emits generated 12-edge outlines under the
        // ambient writable world depth state. Region and bridge transforms
        // are already folded into the retained MVP. Active drawables retain
        // their live one-to-five-pixel pulse through screen-space expansion.
        ALMetalWorldBoundingBoxBatch bounding_box_batch;
        for (std::size_t axis = 0; axis < 4; ++axis)
        {
            bounding_box_batch.modelview_projection[axis * 4 + axis] = 1.f;
        }
        bounding_box_batch.center[3] = 1.f;
        bounding_box_batch.half_extent[0] = 0.4f;
        bounding_box_batch.half_extent[1] = 0.3f;
        bounding_box_batch.half_extent[2] = 0.1f;
        bounding_box_batch.color[0] = 0.f;
        bounding_box_batch.color[1] = 0.f;
        bounding_box_batch.color[2] = 1.f;
        bounding_box_batch.color[3] = 1.f;
        bounding_box_batch.line_width = 1.f;
        bounding_box_batch.order = 0;
        opaque_forward_scene.bounding_box_batches = &bounding_box_batch;
        opaque_forward_scene.bounding_box_batch_count = 1;

        opaque_forward_scene.bounding_box_batches = nullptr;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world bounding-box batch storage is invalid");
        opaque_forward_scene.bounding_box_batches = &bounding_box_batch;
        bounding_box_batch.modelview_projection[0] =
            std::numeric_limits<float>::quiet_NaN();
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world bounding-box batch is invalid");
        bounding_box_batch.modelview_projection[0] = 1.f;
        bounding_box_batch.half_extent[0] = -0.1f;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world bounding-box batch is invalid");
        bounding_box_batch.half_extent[0] = 0.4f;
        bounding_box_batch.color[2] = 0.25f;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world bounding-box batch is invalid");
        bounding_box_batch.color[2] = 1.f;
        bounding_box_batch.line_width = 6.f;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world bounding-box batch is invalid");
        bounding_box_batch.line_width = 1.f;
        opaque_forward_scene.agent_target_lines = agent_target_lines.data();
        opaque_forward_scene.agent_target_line_vertex_count =
            agent_target_lines.size();
        opaque_forward_scene.agent_target_order = 0;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world bounding-box batch is invalid");
        opaque_forward_scene.agent_target_lines = nullptr;
        opaque_forward_scene.agent_target_line_vertex_count = 0;
        error.clear();

        auto thin_bounding_box = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(thin_bounding_box);
        std::array<std::uint16_t, 32 * 32 * 4>
            thin_bounding_box_pixels{};
        std::array<float, 32 * 32> thin_bounding_box_depth{};
        REQUIRE(thin_bounding_box->colorTexture(0)->readback(
            *device, 0, 0, {}, thin_bounding_box_pixels.data(),
            32 * 8, &error));
        REQUIRE(thin_bounding_box->depthStencilTexture()->readback(
            *device, 0, 0, {}, thin_bounding_box_depth.data(),
            32 * sizeof(float), &error));
        std::size_t thin_bounding_box_changed = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            const bool changed =
                thin_bounding_box_pixels[offset + 0] !=
                    opaque_forward_pixels[offset + 0] ||
                thin_bounding_box_pixels[offset + 1] !=
                    opaque_forward_pixels[offset + 1] ||
                thin_bounding_box_pixels[offset + 2] !=
                    opaque_forward_pixels[offset + 2];
            thin_bounding_box_changed += changed;
            if (changed)
            {
                CHECK(thin_bounding_box_pixels[offset + 3] ==
                      opaque_forward_pixels[offset + 3]);
                CHECK(thin_bounding_box_depth[pixel] <=
                      opaque_forward_depth[pixel]);
            }
        }
        CHECK(thin_bounding_box_changed >= 16);
        CHECK(thin_bounding_box_depth != opaque_forward_depth);

        bounding_box_batch.line_width = 5.f;
        auto wide_bounding_box = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(wide_bounding_box);
        std::array<std::uint16_t, 32 * 32 * 4>
            wide_bounding_box_pixels{};
        REQUIRE(wide_bounding_box->colorTexture(0)->readback(
            *device, 0, 0, {}, wide_bounding_box_pixels.data(),
            32 * 8, &error));
        std::size_t wide_bounding_box_changed = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            wide_bounding_box_changed +=
                wide_bounding_box_pixels[offset + 0] !=
                    opaque_forward_pixels[offset + 0] ||
                wide_bounding_box_pixels[offset + 1] !=
                    opaque_forward_pixels[offset + 1] ||
                wide_bounding_box_pixels[offset + 2] !=
                    opaque_forward_pixels[offset + 2];
            CHECK(wide_bounding_box_pixels[offset + 3] ==
                  opaque_forward_pixels[offset + 3]);
        }
        CHECK(wide_bounding_box_changed > thin_bounding_box_changed);

        opaque_forward_scene.gbuffer = reverse_coverage_result.get();
        opaque_forward_scene.reverse_z = true;
        bounding_box_batch.modelview_projection[14] = 0.9f;
        auto reverse_bounding_box = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_bounding_box);
        std::array<std::uint16_t, 32 * 32 * 4>
            reverse_bounding_box_pixels{};
        std::array<float, 32 * 32> reverse_bounding_box_depth{};
        REQUIRE(reverse_bounding_box->colorTexture(0)->readback(
            *device, 0, 0, {}, reverse_bounding_box_pixels.data(),
            32 * 8, &error));
        REQUIRE(reverse_bounding_box->depthStencilTexture()->readback(
            *device, 0, 0, {}, reverse_bounding_box_depth.data(),
            32 * sizeof(float), &error));
        std::size_t reverse_bounding_box_changed = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            const bool changed =
                reverse_bounding_box_pixels[offset + 0] !=
                    reverse_agent_target_baseline_pixels[offset + 0] ||
                reverse_bounding_box_pixels[offset + 1] !=
                    reverse_agent_target_baseline_pixels[offset + 1] ||
                reverse_bounding_box_pixels[offset + 2] !=
                    reverse_agent_target_baseline_pixels[offset + 2];
            reverse_bounding_box_changed += changed;
            if (changed)
            {
                CHECK(reverse_bounding_box_pixels[offset + 3] ==
                      reverse_agent_target_baseline_pixels[offset + 3]);
                CHECK(reverse_bounding_box_depth[pixel] >=
                      reverse_agent_target_baseline_depth[pixel]);
            }
        }
        CHECK(reverse_bounding_box_changed >= 32);
        CHECK(reverse_bounding_box_depth !=
              reverse_agent_target_baseline_depth);

        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.reverse_z = false;
        bounding_box_batch.modelview_projection[14] = 0.f;
        bounding_box_batch.line_width = 5.f;
        bounding_box_batch.center[0] = 0.03125f;
        bounding_box_batch.center[1] = 0.03125f;
        bounding_box_batch.half_extent[0] = 0.1875f;
        bounding_box_batch.half_extent[1] = 0.f;
        bounding_box_batch.color[0] = 1.f;
        bounding_box_batch.color[2] = 0.f;
        bounding_box_batch.order = 0;
        debug_points[0].position[0] = 0.03125f;
        debug_points[0].position[1] = 0.03125f;
        debug_points[0].position[2] = 0.9f;
        debug_point_batches[0].first_vertex = 0;
        debug_point_batches[0].vertex_count = 1;
        debug_point_batches[0].order = 1;
        opaque_forward_scene.debug_points = debug_points.data();
        opaque_forward_scene.debug_point_count = 1;
        opaque_forward_scene.debug_point_batches =
            debug_point_batches.data();
        opaque_forward_scene.debug_point_batch_count = 1;
        auto point_after_bounding_box =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(point_after_bounding_box);
        std::array<std::uint16_t, 32 * 32 * 4>
            point_after_bounding_box_pixels{};
        REQUIRE(point_after_bounding_box->colorTexture(0)->readback(
            *device, 0, 0, {},
            point_after_bounding_box_pixels.data(), 32 * 8, &error));

        debug_point_batches[0].order = 0;
        bounding_box_batch.order = 1;
        auto bounding_box_after_point =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(bounding_box_after_point);
        std::array<std::uint16_t, 32 * 32 * 4>
            bounding_box_after_point_pixels{};
        REQUIRE(bounding_box_after_point->colorTexture(0)->readback(
            *device, 0, 0, {},
            bounding_box_after_point_pixels.data(), 32 * 8, &error));
        CHECK(point_after_bounding_box_pixels !=
              bounding_box_after_point_pixels);

        opaque_forward_scene.debug_points = nullptr;
        opaque_forward_scene.debug_point_count = 0;
        opaque_forward_scene.debug_point_batches = nullptr;
        opaque_forward_scene.debug_point_batch_count = 0;
        opaque_forward_scene.bounding_box_batches = nullptr;
        opaque_forward_scene.bounding_box_batch_count = 0;
        auto no_bounding_box = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(no_bounding_box);
        std::array<std::uint16_t, 32 * 32 * 4>
            no_bounding_box_pixels{};
        REQUIRE(no_bounding_box->colorTexture(0)->readback(
            *device, 0, 0, {}, no_bounding_box_pixels.data(),
            32 * 8, &error));
        CHECK(no_bounding_box_pixels == opaque_forward_pixels);

        // Develop > Raycast retains every volume-octree branch intersected by
        // the live cursor ray. Branch outlines keep their ordinary writable
        // depth, immediate triangles become explicit edge pairs for the
        // hidden one-pixel and visible three-pixel read-only passes, and the
        // selected-hit boxes plus later particle crosshair remain ordered.
        std::array<ALMetalWorldRaycastVertex, 12> raycast_vertices{};
        const float raycast_triangle[6][3] = {
            {-0.5f, -0.4f, 0.f}, {0.5f, -0.4f, 0.f},
            {0.5f, -0.4f, 0.f}, {0.f, 0.5f, 0.f},
            {0.f, 0.5f, 0.f}, {-0.5f, -0.4f, 0.f},
        };
        for (std::size_t copy = 0; copy < 2; ++copy)
        {
            for (std::size_t vertex = 0; vertex < 6; ++vertex)
            {
                std::memcpy(
                    raycast_vertices[copy * 6 + vertex].position,
                    raycast_triangle[vertex], sizeof(float) * 3);
                raycast_vertices[copy * 6 + vertex].position[3] = 1.f;
            }
        }
        const auto set_raycast_identity = [](float (&matrix)[16])
        {
            std::fill(std::begin(matrix), std::end(matrix), 0.f);
            for (std::size_t axis = 0; axis < 4; ++axis)
            {
                matrix[axis * 4 + axis] = 1.f;
            }
        };
        ALMetalWorldRaycastBatch raycast_batch;
        raycast_batch.kind = ALMetalWorldRaycastKind::branch_outline;
        set_raycast_identity(raycast_batch.modelview_projection);
        raycast_batch.center[3] = 1.f;
        raycast_batch.half_extent[0] = 0.4f;
        raycast_batch.half_extent[1] = 0.3f;
        raycast_batch.half_extent[2] = 0.1f;
        raycast_batch.color[0] = 1.f;
        raycast_batch.color[1] = 0.2f;
        raycast_batch.color[2] = 0.f;
        raycast_batch.color[3] = 1.f;
        raycast_batch.line_width = 1.f;
        raycast_batch.order = 0;
        opaque_forward_scene.raycast_batches = &raycast_batch;
        opaque_forward_scene.raycast_batch_count = 1;

        opaque_forward_scene.raycast_batches = nullptr;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world raycast storage is invalid");
        opaque_forward_scene.raycast_batches = &raycast_batch;
        raycast_batch.modelview_projection[0] =
            std::numeric_limits<float>::quiet_NaN();
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world raycast batch is invalid");
        raycast_batch.modelview_projection[0] = 1.f;
        raycast_batch.half_extent[0] = -0.1f;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world raycast batch is invalid");
        raycast_batch.half_extent[0] = 0.4f;
        raycast_batch.color[1] = 0.25f;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world raycast batch is invalid");
        raycast_batch.color[1] = 0.2f;
        raycast_batch.kind =
            static_cast<ALMetalWorldRaycastKind>(99);
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world raycast batch is invalid");
        raycast_batch.kind = ALMetalWorldRaycastKind::branch_outline;
        opaque_forward_scene.agent_target_lines =
            agent_target_lines.data();
        opaque_forward_scene.agent_target_line_vertex_count =
            agent_target_lines.size();
        opaque_forward_scene.agent_target_order = 0;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world raycast batch is invalid");
        opaque_forward_scene.agent_target_lines = nullptr;
        opaque_forward_scene.agent_target_line_vertex_count = 0;

        raycast_batch.kind =
            ALMetalWorldRaycastKind::hidden_triangles;
        raycast_batch.first_vertex = 0;
        raycast_batch.vertex_count = 6;
        raycast_batch.color[0] = 0.f;
        raycast_batch.color[1] = 0.5f;
        raycast_batch.color[2] = 0.5f;
        raycast_batch.color[3] = 0.25f;
        raycast_batch.center[0] = 0.f;
        raycast_batch.center[1] = 0.f;
        raycast_batch.center[2] = 0.f;
        raycast_batch.half_extent[0] = 0.f;
        raycast_batch.half_extent[1] = 0.f;
        raycast_batch.half_extent[2] = 0.f;
        opaque_forward_scene.raycast_vertex_count = 6;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world raycast storage is invalid");
        opaque_forward_scene.raycast_vertices = raycast_vertices.data();
        raycast_vertices[0].position[3] = 0.f;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world raycast vertex is invalid");
        raycast_vertices[0].position[3] = 1.f;

        ALMetalWorldRaycastParticle raycast_particle;
        set_raycast_identity(raycast_particle.modelview_projection);
        raycast_particle.center[3] = 1.f;
        raycast_particle.half_extent[0] = 0.1f;
        raycast_particle.half_extent[1] = 0.1f;
        raycast_particle.half_extent[2] = 0.1f;
        opaque_forward_scene.raycast_particle = &raycast_particle;
        raycast_particle.half_extent[0] = 0.2f;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world raycast particle is invalid");
        raycast_particle.half_extent[0] = 0.1f;
        opaque_forward_scene.raycast_particle = nullptr;

        set_raycast_identity(raycast_batch.modelview_projection);
        raycast_batch.modelview_projection[14] = 0.75f;
        error.clear();
        auto hidden_raycast = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(hidden_raycast);
        std::array<std::uint16_t, 32 * 32 * 4>
            hidden_raycast_pixels{};
        std::array<float, 32 * 32> hidden_raycast_depth{};
        REQUIRE(hidden_raycast->colorTexture(0)->readback(
            *device, 0, 0, {}, hidden_raycast_pixels.data(),
            32 * 8, &error));
        REQUIRE(hidden_raycast->depthStencilTexture()->readback(
            *device, 0, 0, {}, hidden_raycast_depth.data(),
            32 * sizeof(float), &error));
        std::size_t hidden_raycast_changed = 0;
        std::size_t hidden_raycast_readonly = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            const bool changed =
                hidden_raycast_pixels[offset + 0] !=
                    opaque_forward_pixels[offset + 0] ||
                hidden_raycast_pixels[offset + 1] !=
                    opaque_forward_pixels[offset + 1] ||
                hidden_raycast_pixels[offset + 2] !=
                    opaque_forward_pixels[offset + 2];
            hidden_raycast_changed += changed;
            if (changed && opaque_forward_depth[pixel] < 1.f)
            {
                CHECK(hidden_raycast_depth[pixel] ==
                      opaque_forward_depth[pixel]);
                ++hidden_raycast_readonly;
            }
        }
        CHECK(hidden_raycast_changed >= 4);
        CHECK(hidden_raycast_readonly >= 4);

        raycast_batch.kind =
            ALMetalWorldRaycastKind::visible_triangles;
        raycast_batch.color[1] = 1.f;
        raycast_batch.color[2] = 1.f;
        raycast_batch.color[3] = 0.5f;
        raycast_batch.line_width = 3.f;
        raycast_batch.modelview_projection[14] = 0.f;
        auto visible_raycast = renderer->renderOpaquePostDeferred(
