        INFO(error);
        REQUIRE(point_after_raycast);
        std::array<std::uint16_t, 32 * 32 * 4>
            point_after_raycast_pixels{};
        REQUIRE(point_after_raycast->colorTexture(0)->readback(
            *device, 0, 0, {}, point_after_raycast_pixels.data(),
