            occlusion_bounds.modelview_projection[axis * 4 + axis] = 1.f;
        }
        opaque_forward_scene.occlusion_batches = &occlusion_bounds;
        occlusion_bounds.half_extent[0] = -0.1f;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world occlusion batch is invalid");
        occlusion_bounds.half_extent[0] = 0.4f;
        std::array<ALMetalWorldOcclusionBatch, 2>
            occlusion_order_batches{{occlusion_xray, occlusion_bounds}};
        occlusion_order_batches[0].order = 1;
        occlusion_order_batches[1].order = 0;
        opaque_forward_scene.occlusion_batches =
            occlusion_order_batches.data();
        opaque_forward_scene.occlusion_batch_count =
            occlusion_order_batches.size();
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world occlusion batch is invalid");
        opaque_forward_scene.occlusion_batches = &occlusion_bounds;
        opaque_forward_scene.occlusion_batch_count = 1;
        error.clear();
        auto selected_occlusion_bounds =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(selected_occlusion_bounds);
        std::array<std::uint16_t, 32 * 32 * 4>
            selected_occlusion_bounds_pixels{};
        std::array<float, 32 * 32> selected_occlusion_bounds_depth{};
        REQUIRE(selected_occlusion_bounds->colorTexture(0)->readback(
            *device, 0, 0, {},
            selected_occlusion_bounds_pixels.data(), 32 * 8, &error));
        REQUIRE(selected_occlusion_bounds->depthStencilTexture()->readback(
            *device, 0, 0, {}, selected_occlusion_bounds_depth.data(),
            32 * sizeof(float), &error));
        std::size_t selected_occlusion_bounds_changed = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            const bool changed =
                selected_occlusion_bounds_pixels[offset + 0] !=
                    opaque_forward_pixels[offset + 0] ||
                selected_occlusion_bounds_pixels[offset + 1] !=
                    opaque_forward_pixels[offset + 1] ||
                selected_occlusion_bounds_pixels[offset + 2] !=
                    opaque_forward_pixels[offset + 2];
            selected_occlusion_bounds_changed += changed;
            if (changed)
            {
                CHECK(selected_occlusion_bounds_pixels[offset + 3] ==
                      opaque_forward_pixels[offset + 3]);
                CHECK(selected_occlusion_bounds_depth[pixel] ==
                      opaque_forward_depth[pixel]);
            }
        }
        CHECK(selected_occlusion_bounds_changed >= 32);
        CHECK(selected_occlusion_bounds_depth == opaque_forward_depth);

        debug_points[0].position[0] = 0.f;
        debug_points[0].position[1] = 0.f;
        debug_points[0].position[2] = 0.f;
        debug_point_batches[0].first_vertex = 0;
        debug_point_batches[0].vertex_count = 1;
        occlusion_bounds.order = 0;
        debug_point_batches[0].order = 0;
        opaque_forward_scene.debug_points = debug_points.data();
        opaque_forward_scene.debug_point_count = 1;
        opaque_forward_scene.debug_point_batches =
            debug_point_batches.data();
        opaque_forward_scene.debug_point_batch_count = 1;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world render-debug ordering is invalid");

        debug_point_batches[0].order = 1;
        auto point_after_occlusion = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(point_after_occlusion);
        std::array<std::uint16_t, 32 * 32 * 4>
            point_after_occlusion_pixels{};
        REQUIRE(point_after_occlusion->colorTexture(0)->readback(
            *device, 0, 0, {}, point_after_occlusion_pixels.data(),
            32 * 8, &error));
        debug_point_batches[0].order = 0;
        occlusion_bounds.order = 1;
        auto occlusion_after_point = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(occlusion_after_point);
        std::array<std::uint16_t, 32 * 32 * 4>
            occlusion_after_point_pixels{};
        REQUIRE(occlusion_after_point->colorTexture(0)->readback(
            *device, 0, 0, {}, occlusion_after_point_pixels.data(),
            32 * 8, &error));
        CHECK(point_after_occlusion_pixels !=
              occlusion_after_point_pixels);

        opaque_forward_scene.debug_points = nullptr;
        opaque_forward_scene.debug_point_count = 0;
        opaque_forward_scene.debug_point_batches = nullptr;
        opaque_forward_scene.debug_point_batch_count = 0;
        opaque_forward_scene.occlusion_batches = nullptr;
        opaque_forward_scene.occlusion_batch_count = 0;
        auto no_occlusion = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(no_occlusion);
        std::array<std::uint16_t, 32 * 32 * 4> no_occlusion_pixels{};
        REQUIRE(no_occlusion->colorTexture(0)->readback(
            *device, 0, 0, {}, no_occlusion_pixels.data(),
            32 * 8, &error));
        CHECK(no_occlusion_pixels == opaque_forward_pixels);

        // Develop > Octree preserves one complete post-order source owner:
        // an additive, no-depth rebuild flash (wide bounds and static/rigged
        // face wireframes) followed by the ordinary depth-writing cyan group
        // outline. Destination alpha remains owned by the composed scene.
        ALMetalWorldOctreeBatch octree_batch;
        octree_batch.kind = ALMetalWorldOctreeKind::flash_bounds;
        octree_batch.center[3] = 1.f;
        octree_batch.half_extent[0] = 0.4f;
        octree_batch.half_extent[1] = 0.3f;
        octree_batch.half_extent[2] = 0.1f;
        octree_batch.color[0] = 1.f;
        octree_batch.color[3] = 0.5f;
        octree_batch.line_width = 5.f;
        for (std::size_t axis = 0; axis < 4; ++axis)
        {
            octree_batch.modelview_projection[axis * 4 + axis] = 1.f;
        }
        opaque_forward_scene.octree_batches = &octree_batch;
        opaque_forward_scene.octree_batch_count = 1;

        opaque_forward_scene.octree_batches = nullptr;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world octree batch storage is invalid");
        opaque_forward_scene.octree_batches = &octree_batch;
        octree_batch.half_extent[0] = -0.1f;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world octree batch is invalid");
        octree_batch.half_extent[0] = 0.4f;
        octree_batch.kind = static_cast<ALMetalWorldOctreeKind>(99);
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world octree batch is invalid");
        octree_batch.kind = ALMetalWorldOctreeKind::flash_bounds;
        opaque_forward_scene.agent_target_lines =
            agent_target_lines.data();
        opaque_forward_scene.agent_target_line_vertex_count =
            agent_target_lines.size();
        opaque_forward_scene.agent_target_order = 0;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world octree batch is invalid");
        opaque_forward_scene.agent_target_lines = nullptr;
        opaque_forward_scene.agent_target_line_vertex_count = 0;

        error.clear();
        auto octree_flash_bounds = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(octree_flash_bounds);
        std::array<std::uint16_t, 32 * 32 * 4>
            octree_flash_bounds_pixels{};
        std::array<float, 32 * 32> octree_flash_bounds_depth{};
        REQUIRE(octree_flash_bounds->colorTexture(0)->readback(
            *device, 0, 0, {}, octree_flash_bounds_pixels.data(),
            32 * 8, &error));
        REQUIRE(octree_flash_bounds->depthStencilTexture()->readback(
            *device, 0, 0, {}, octree_flash_bounds_depth.data(),
            32 * sizeof(float), &error));
        std::size_t octree_flash_bounds_changed = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            const bool changed =
                octree_flash_bounds_pixels[offset + 0] !=
                    opaque_forward_pixels[offset + 0] ||
                octree_flash_bounds_pixels[offset + 1] !=
                    opaque_forward_pixels[offset + 1] ||
                octree_flash_bounds_pixels[offset + 2] !=
                    opaque_forward_pixels[offset + 2];
            octree_flash_bounds_changed += changed;
            if (changed)
            {
                CHECK(octree_flash_bounds_pixels[offset + 3] ==
                      opaque_forward_pixels[offset + 3]);
            }
        }
        CHECK(octree_flash_bounds_changed >= 32);
        CHECK(octree_flash_bounds_depth == opaque_forward_depth);

        octree_batch.kind = ALMetalWorldOctreeKind::flash_geometry;
        octree_batch.vertices = vertices.get();
        octree_batch.vertex_count = positions.size();
        octree_batch.indices = indices.get();
        octree_batch.index_count = index_values.size();
        octree_batch.center[0] = 0.f;
        octree_batch.center[1] = 0.f;
        octree_batch.center[2] = 0.f;
        octree_batch.half_extent[0] = 0.f;
        octree_batch.half_extent[1] = 0.f;
        octree_batch.half_extent[2] = 0.f;
        octree_batch.color[0] = 0.f;
        octree_batch.color[1] = 1.f;
        octree_batch.color[2] = 0.f;
        octree_batch.line_width = 1.f;
        octree_batch.vertices = nullptr;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world octree batch is invalid");
        octree_batch.vertices = vertices.get();
        octree_batch.index_count = 2;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world octree batch is invalid");
        octree_batch.index_count = index_values.size();
        octree_batch.index_type = static_cast<ALMetalIndexType>(99);
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world octree batch is invalid");
        octree_batch.index_type = ALMetalIndexType::uint16;
        octree_batch.position_offset = sizeof(float);
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world octree batch is invalid");
        octree_batch.position_offset = 0;
        octree_batch.modelview_projection[0] =
            std::numeric_limits<float>::quiet_NaN();
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world octree batch is invalid");
        octree_batch.modelview_projection[0] = 1.f;

        error.clear();
        auto octree_static_flash = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(octree_static_flash);
        std::array<std::uint16_t, 32 * 32 * 4>
            octree_static_flash_pixels{};
        std::array<float, 32 * 32> octree_static_flash_depth{};
        REQUIRE(octree_static_flash->colorTexture(0)->readback(
            *device, 0, 0, {}, octree_static_flash_pixels.data(),
            32 * 8, &error));
        REQUIRE(octree_static_flash->depthStencilTexture()->readback(
            *device, 0, 0, {}, octree_static_flash_depth.data(),
            32 * sizeof(float), &error));
        std::size_t octree_static_flash_changed = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            const bool changed =
                octree_static_flash_pixels[offset + 0] !=
                    opaque_forward_pixels[offset + 0] ||
                octree_static_flash_pixels[offset + 1] !=
                    opaque_forward_pixels[offset + 1] ||
                octree_static_flash_pixels[offset + 2] !=
                    opaque_forward_pixels[offset + 2];
            octree_static_flash_changed += changed;
            if (changed)
            {
                CHECK(octree_static_flash_pixels[offset + 3] ==
                      opaque_forward_pixels[offset + 3]);
            }
        }
        CHECK(octree_static_flash_changed >= 4);
        CHECK(octree_static_flash_depth == opaque_forward_depth);

        opaque_forward_scene.gbuffer = reverse_coverage_result.get();
        opaque_forward_scene.reverse_z = true;
        error.clear();
        auto reverse_octree_static_flash =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_octree_static_flash);
        std::array<std::uint16_t, 32 * 32 * 4>
            reverse_octree_static_flash_pixels{};
        std::array<float, 32 * 32> reverse_octree_static_flash_depth{};
        REQUIRE(reverse_octree_static_flash->colorTexture(0)->readback(
            *device, 0, 0, {},
            reverse_octree_static_flash_pixels.data(), 32 * 8, &error));
        REQUIRE(
            reverse_octree_static_flash->depthStencilTexture()->readback(
                *device, 0, 0, {},
                reverse_octree_static_flash_depth.data(),
                32 * sizeof(float), &error));
        CHECK(reverse_octree_static_flash_pixels !=
              reverse_agent_target_baseline_pixels);
        CHECK(reverse_octree_static_flash_depth ==
              reverse_agent_target_baseline_depth);
        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.reverse_z = false;

        // All four source movement/update colours are accepted, and the
        // rigged variant consumes the same rebased object-skin palette.
        const std::array<std::array<float, 3>, 4> octree_colors{{
            {{0.f, 1.f, 1.f}}, {{0.f, 1.f, 0.f}},
            {{1.f, 1.f, 0.f}}, {{1.f, 0.f, 0.f}},
        }};
        for (const auto& color : octree_colors)
        {
            std::copy(color.begin(), color.end(), octree_batch.color);
            error.clear();
            REQUIRE(renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error));
        }
        octree_batch.weight_offset = weight_offset;
        octree_batch.skin_palette = skin_palette.data();
        octree_batch.skin_palette_float_count = skin_palette.size() - 1;
        octree_batch.skin_joint_count = 1;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world octree batch is invalid");
        octree_batch.skin_palette_float_count = skin_palette.size();
        error.clear();
        auto octree_rigged_flash = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(octree_rigged_flash);
        std::array<std::uint16_t, 32 * 32 * 4>
            octree_rigged_flash_pixels{};
        REQUIRE(octree_rigged_flash->colorTexture(0)->readback(
            *device, 0, 0, {}, octree_rigged_flash_pixels.data(),
            32 * 8, &error));
        CHECK(octree_rigged_flash_pixels != octree_static_flash_pixels);

        octree_batch.vertices = nullptr;
        octree_batch.vertex_count = 0;
        octree_batch.indices = nullptr;
        octree_batch.index_count = 0;
        octree_batch.weight_offset = 0;
        octree_batch.skin_palette = nullptr;
        octree_batch.skin_palette_float_count = 0;
        octree_batch.skin_joint_count = 0;
        octree_batch.kind = ALMetalWorldOctreeKind::group_outline;
        octree_batch.half_extent[0] = 0.4f;
        octree_batch.half_extent[1] = 0.3f;
        octree_batch.half_extent[2] = 0.1f;
        octree_batch.color[0] = 0.f;
        octree_batch.color[1] = 1.f;
        octree_batch.color[2] = 1.f;
        octree_batch.color[3] = 1.f;
        octree_batch.line_width = 1.f;
        error.clear();
        auto octree_group_outline = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(octree_group_outline);
        std::array<std::uint16_t, 32 * 32 * 4>
            octree_group_outline_pixels{};
        std::array<float, 32 * 32> octree_group_outline_depth{};
        REQUIRE(octree_group_outline->colorTexture(0)->readback(
            *device, 0, 0, {}, octree_group_outline_pixels.data(),
            32 * 8, &error));
        REQUIRE(octree_group_outline->depthStencilTexture()->readback(
            *device, 0, 0, {}, octree_group_outline_depth.data(),
            32 * sizeof(float), &error));
        CHECK(octree_group_outline_pixels != opaque_forward_pixels);
        CHECK(octree_group_outline_depth != opaque_forward_depth);

        opaque_forward_scene.gbuffer = reverse_coverage_result.get();
        opaque_forward_scene.reverse_z = true;
        octree_batch.modelview_projection[14] = 0.9f;
        auto reverse_octree_group_outline =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_octree_group_outline);
        std::array<float, 32 * 32> reverse_octree_group_depth{};
        REQUIRE(reverse_octree_group_outline->depthStencilTexture()->readback(
            *device, 0, 0, {}, reverse_octree_group_depth.data(),
            32 * sizeof(float), &error));
        CHECK(reverse_octree_group_depth !=
              reverse_agent_target_baseline_depth);

        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.reverse_z = false;
        octree_batch.modelview_projection[14] = 0.f;
        ALMetalWorldOctreeBatch flash_order_batch = octree_batch;
        flash_order_batch.kind = ALMetalWorldOctreeKind::flash_bounds;
        flash_order_batch.color[0] = 1.f;
        flash_order_batch.color[1] = 0.f;
        flash_order_batch.color[2] = 0.f;
        flash_order_batch.color[3] = 0.5f;
        flash_order_batch.line_width = 5.f;
        std::array<ALMetalWorldOctreeBatch, 2> octree_order_batches{{
            flash_order_batch, octree_batch,
        }};
        octree_order_batches[0].order = 1;
        octree_order_batches[1].order = 0;
        opaque_forward_scene.octree_batches =
            octree_order_batches.data();
        opaque_forward_scene.octree_batch_count =
            octree_order_batches.size();
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world octree batch is invalid");

        opaque_forward_scene.octree_batches = &flash_order_batch;
        opaque_forward_scene.octree_batch_count = 1;
        debug_points[0].position[0] = 0.f;
        debug_points[0].position[1] = 0.f;
        debug_points[0].position[2] = 0.f;
        debug_point_batches[0].first_vertex = 0;
        debug_point_batches[0].vertex_count = 1;
        flash_order_batch.order = 0;
        debug_point_batches[0].order = 0;
        opaque_forward_scene.debug_points = debug_points.data();
        opaque_forward_scene.debug_point_count = 1;
        opaque_forward_scene.debug_point_batches =
            debug_point_batches.data();
        opaque_forward_scene.debug_point_batch_count = 1;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world render-debug ordering is invalid");

        // The merged order is behavioral, not metadata-only: the opaque
        // magenta selected bounds erase an earlier additive red flash, while
        // a later flash adds red over those same edge pixels.
        opaque_forward_scene.debug_points = nullptr;
        opaque_forward_scene.debug_point_count = 0;
        opaque_forward_scene.debug_point_batches = nullptr;
        opaque_forward_scene.debug_point_batch_count = 0;
        occlusion_bounds.order = 1;
        flash_order_batch.order = 0;
        opaque_forward_scene.occlusion_batches = &occlusion_bounds;
        opaque_forward_scene.occlusion_batch_count = 1;
        auto occlusion_after_octree = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(occlusion_after_octree);
        std::array<std::uint16_t, 32 * 32 * 4>
            occlusion_after_octree_pixels{};
        REQUIRE(occlusion_after_octree->colorTexture(0)->readback(
            *device, 0, 0, {}, occlusion_after_octree_pixels.data(),
            32 * 8, &error));
        occlusion_bounds.order = 0;
        flash_order_batch.order = 1;
        auto octree_after_occlusion = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(octree_after_occlusion);
        std::array<std::uint16_t, 32 * 32 * 4>
            octree_after_occlusion_pixels{};
        REQUIRE(octree_after_occlusion->colorTexture(0)->readback(
            *device, 0, 0, {}, octree_after_occlusion_pixels.data(),
            32 * 8, &error));
        CHECK(occlusion_after_octree_pixels !=
              octree_after_occlusion_pixels);

        opaque_forward_scene.occlusion_batches = nullptr;
        opaque_forward_scene.occlusion_batch_count = 0;
        opaque_forward_scene.octree_batches = nullptr;
        opaque_forward_scene.octree_batch_count = 0;
        auto no_octree = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(no_octree);
        std::array<std::uint16_t, 32 * 32 * 4> no_octree_pixels{};
        REQUIRE(no_octree->colorTexture(0)->readback(
            *device, 0, 0, {}, no_octree_pixels.data(), 32 * 8,
            &error));
        CHECK(no_octree_pixels == opaque_forward_pixels);

        // Develop > Physics Shapes is one late three-pass transaction. The
        // first triangle pass writes depth only, the second blends RGB at the
        // same depth, and the final three-pixel edge pass is biased behind
        // that fill. Generated vertices are owned by the scene so temporary
        // decomposition and LLVolume storage cannot escape into encoding.
        std::array<ALMetalWorldPhysicsShapeVertex, 9>
            physics_shape_vertices{};
        const std::array<std::array<float, 3>, 3>
            physics_triangle{{
                {{-0.55f, -0.55f, -0.5f}},
                {{ 0.55f, -0.55f, -0.5f}},
                {{ 0.f,    0.55f, -0.5f}},
            }};
        for (std::size_t index = 0; index < 3; ++index)
        {
            std::copy(
                physics_triangle[index].begin(),
                physics_triangle[index].end(),
                physics_shape_vertices[index].position);
            physics_shape_vertices[index].position[3] = 1.f;
        }
        const std::array<std::size_t, 6> physics_edges{{
            0, 1, 1, 2, 2, 0,
        }};
        for (std::size_t index = 0; index < physics_edges.size();
             ++index)
        {
            physics_shape_vertices[index + 3] =
                physics_shape_vertices[physics_edges[index]];
        }
        std::array<ALMetalWorldPhysicsShapeBatch, 4>
            physics_shape_batches{};
        for (std::size_t index = 0;
             index < physics_shape_batches.size(); ++index)
        {
            auto& batch = physics_shape_batches[index];
            for (std::size_t axis = 0; axis < 4; ++axis)
            {
                batch.modelview_projection[axis * 4 + axis] = 1.f;
            }
            batch.color[1] = index >= 2 ? 0.5f : 1.f;
            batch.color[3] = index >= 2 ? 0.25f : 0.5f;
            batch.cull_back = true;
            batch.order = index;
        }
        physics_shape_batches[0].pass =
            ALMetalWorldPhysicsShapePass::depth_fill;
        physics_shape_batches[0].first_vertex = 0;
        physics_shape_batches[0].vertex_count = 3;
        physics_shape_batches[1].pass =
            ALMetalWorldPhysicsShapePass::color_fill;
        physics_shape_batches[1].first_vertex = 0;
        physics_shape_batches[1].vertex_count = 3;
        physics_shape_batches[2].pass =
            ALMetalWorldPhysicsShapePass::color_wire;
        physics_shape_batches[2].first_vertex = 0;
        physics_shape_batches[2].vertex_count = 3;
        physics_shape_batches[2].triangle_wire = true;
        physics_shape_batches[2].polygon_offset = true;
        physics_shape_batches[3].pass =
            ALMetalWorldPhysicsShapePass::color_wire;
        physics_shape_batches[3].first_vertex = 3;
        physics_shape_batches[3].vertex_count = 6;
        physics_shape_batches[3].wide_lines = true;

        opaque_forward_scene.physics_shape_vertices = nullptr;
        opaque_forward_scene.physics_shape_vertex_count =
            physics_shape_vertices.size();
        opaque_forward_scene.physics_shape_batches =
            physics_shape_batches.data();
        opaque_forward_scene.physics_shape_batch_count = 1;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world Physics Shapes storage is invalid");
        opaque_forward_scene.physics_shape_vertices =
            physics_shape_vertices.data();
        physics_shape_vertices[0].position[0] =
            std::numeric_limits<float>::quiet_NaN();
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world Physics Shapes vertex is invalid");
        physics_shape_vertices[0].position[0] = -0.55f;
        physics_shape_batches[0].vertex_count = 10;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world Physics Shapes batch is invalid");
        physics_shape_batches[0].vertex_count = 3;
        physics_shape_batches[0].pass =
            static_cast<ALMetalWorldPhysicsShapePass>(99);
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world Physics Shapes batch is invalid");
        physics_shape_batches[0].pass =
            ALMetalWorldPhysicsShapePass::depth_fill;
        physics_shape_batches[0].polygon_offset = true;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world Physics Shapes batch is invalid");
        physics_shape_batches[0].polygon_offset = false;
        opaque_forward_scene.agent_target_lines =
            agent_target_lines.data();
        opaque_forward_scene.agent_target_line_vertex_count =
            agent_target_lines.size();
        opaque_forward_scene.agent_target_order = 0;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world Physics Shapes batch is invalid");
        opaque_forward_scene.agent_target_lines = nullptr;
        opaque_forward_scene.agent_target_line_vertex_count = 0;

        error.clear();
        auto physics_depth_only = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(physics_depth_only);
        std::array<std::uint16_t, 32 * 32 * 4>
            physics_depth_only_pixels{};
        std::array<float, 32 * 32> physics_depth_only_depth{};
        REQUIRE(physics_depth_only->colorTexture(0)->readback(
            *device, 0, 0, {}, physics_depth_only_pixels.data(),
            32 * 8, &error));
        REQUIRE(physics_depth_only->depthStencilTexture()->readback(
            *device, 0, 0, {}, physics_depth_only_depth.data(),
            32 * sizeof(float), &error));
        CHECK(physics_depth_only_pixels == opaque_forward_pixels);
        CHECK(physics_depth_only_depth != opaque_forward_depth);

        opaque_forward_scene.physics_shape_batch_count =
            physics_shape_batches.size();
        error.clear();
        auto physics_three_pass = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(physics_three_pass);
        std::array<std::uint16_t, 32 * 32 * 4>
            physics_three_pass_pixels{};
        std::array<float, 32 * 32> physics_three_pass_depth{};
        REQUIRE(physics_three_pass->colorTexture(0)->readback(
            *device, 0, 0, {}, physics_three_pass_pixels.data(),
            32 * 8, &error));
        REQUIRE(physics_three_pass->depthStencilTexture()->readback(
            *device, 0, 0, {}, physics_three_pass_depth.data(),
            32 * sizeof(float), &error));
        std::size_t physics_shape_changed = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            const bool changed =
                physics_three_pass_pixels[offset + 0] !=
                    opaque_forward_pixels[offset + 0] ||
                physics_three_pass_pixels[offset + 1] !=
                    opaque_forward_pixels[offset + 1] ||
                physics_three_pass_pixels[offset + 2] !=
                    opaque_forward_pixels[offset + 2];
            physics_shape_changed += changed;
            if (changed)
            {
                CHECK(physics_three_pass_pixels[offset + 3] ==
                      opaque_forward_pixels[offset + 3]);
            }
        }
        CHECK(physics_shape_changed >= 64);
        CHECK(physics_three_pass_depth == physics_depth_only_depth);

        std::swap(physics_shape_batches[0],
                  physics_shape_batches[1]);
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world Physics Shapes batch is invalid");
        std::swap(physics_shape_batches[0],
                  physics_shape_batches[1]);
        physics_shape_batches[0].order = 0;
        physics_shape_batches[1].order = 1;
        physics_shape_batches[2].order = 2;
        physics_shape_batches[3].order = 3;

        debug_points[0].position[0] = 0.f;
        debug_points[0].position[1] = 0.f;
        debug_points[0].position[2] = 0.f;
        debug_point_batches[0].first_vertex = 0;
        debug_point_batches[0].vertex_count = 1;
        debug_point_batches[0].order = 3;
        opaque_forward_scene.debug_points = debug_points.data();
        opaque_forward_scene.debug_point_count = 1;
        opaque_forward_scene.debug_point_batches =
            debug_point_batches.data();
        opaque_forward_scene.debug_point_batch_count = 1;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world render-debug ordering is invalid");
        opaque_forward_scene.debug_points = nullptr;
        opaque_forward_scene.debug_point_count = 0;
        opaque_forward_scene.debug_point_batches = nullptr;
        opaque_forward_scene.debug_point_batch_count = 0;

        opaque_forward_scene.gbuffer = reverse_coverage_result.get();
        opaque_forward_scene.reverse_z = true;
        for (auto& vertex : physics_shape_vertices)
        {
            vertex.position[2] = 0.9f;
        }
        error.clear();
        auto reverse_physics_shapes =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_physics_shapes);
        std::array<std::uint16_t, 32 * 32 * 4>
            reverse_physics_shape_pixels{};
        std::array<float, 32 * 32> reverse_physics_shape_depth{};
        REQUIRE(reverse_physics_shapes->colorTexture(0)->readback(
            *device, 0, 0, {}, reverse_physics_shape_pixels.data(),
            32 * 8, &error));
        REQUIRE(reverse_physics_shapes->depthStencilTexture()->readback(
            *device, 0, 0, {}, reverse_physics_shape_depth.data(),
            32 * sizeof(float), &error));
        CHECK(reverse_physics_shape_pixels !=
              reverse_agent_target_baseline_pixels);
        CHECK(reverse_physics_shape_depth !=
              reverse_agent_target_baseline_depth);

        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.reverse_z = false;
        opaque_forward_scene.physics_shape_vertices = nullptr;
        opaque_forward_scene.physics_shape_vertex_count = 0;
        opaque_forward_scene.physics_shape_batches = nullptr;
        opaque_forward_scene.physics_shape_batch_count = 0;
        error.clear();
        auto no_physics_shapes = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(no_physics_shapes);
        std::array<std::uint16_t, 32 * 32 * 4>
            no_physics_shape_pixels{};
        REQUIRE(no_physics_shapes->colorTexture(0)->readback(
            *device, 0, 0, {}, no_physics_shape_pixels.data(),
            32 * 8, &error));
        CHECK(no_physics_shape_pixels == opaque_forward_pixels);

        // Develop > Normals has two retained owners. Volume faces arrive as
        // exact CPU-expanded yellow/cyan line pairs, while other drawables
        // retain indexed geometry and expand normal/tangent lines in the
        // vertex shader. Both inherit RGB-only standard-alpha blend and
        // read-only world depth.
        std::array<ALMetalWorldNormalVertex, 4>
            explicit_normal_vertices{};
        const std::array<std::array<float, 3>, 4>
            explicit_normal_positions{{
                {{-0.65f, -0.45f, -0.5f}},
                {{ 0.65f, -0.45f, -0.5f}},
                {{ 0.f,   -0.65f, -0.5f}},
                {{ 0.f,    0.65f, -0.5f}},
            }};
        for (std::size_t index = 0;
             index < explicit_normal_vertices.size(); ++index)
        {
            std::copy(explicit_normal_positions[index].begin(),
                      explicit_normal_positions[index].end(),
                      explicit_normal_vertices[index].position);
            explicit_normal_vertices[index].position[3] = 1.f;
        }
        std::array<ALMetalWorldNormalBatch, 2>
            explicit_normal_batches{};
        for (std::size_t index = 0;
             index < explicit_normal_batches.size(); ++index)
        {
            auto& batch = explicit_normal_batches[index];
            batch.kind = ALMetalWorldNormalKind::explicit_lines;
            batch.first_vertex = static_cast<std::uint32_t>(index * 2);
            batch.line_vertex_count = 2;
            batch.order = index;
            for (std::size_t axis = 0; axis < 4; ++axis)
            {
                batch.modelview_projection[axis * 4 + axis] = 1.f;
            }
            batch.color[1] = 1.f;
            batch.color[3] = 1.f;
        }
        explicit_normal_batches[0].color[0] = 1.f;
        explicit_normal_batches[1].color[2] = 1.f;

        opaque_forward_scene.normal_vertices = nullptr;
        opaque_forward_scene.normal_vertex_count =
            explicit_normal_vertices.size();
        opaque_forward_scene.normal_batches =
            explicit_normal_batches.data();
        opaque_forward_scene.normal_batch_count =
            explicit_normal_batches.size();
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world Normals storage is invalid");
        opaque_forward_scene.normal_vertices =
            explicit_normal_vertices.data();
        explicit_normal_vertices[0].position[0] =
            std::numeric_limits<float>::quiet_NaN();
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world Normals vertex is invalid");
        explicit_normal_vertices[0].position[0] = -0.65f;
        explicit_normal_batches[0].line_vertex_count = 3;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world Normals batch is invalid");
        explicit_normal_batches[0].line_vertex_count = 2;
        explicit_normal_batches[0].color[0] = 0.5f;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world Normals batch is invalid");
        explicit_normal_batches[0].color[0] = 1.f;
        explicit_normal_batches[1].order = 0;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world Normals batch is invalid");
        explicit_normal_batches[1].order = 1;
        opaque_forward_scene.normal_batch_count = 1;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world Normals storage is invalid");
        opaque_forward_scene.normal_batch_count =
            explicit_normal_batches.size();

        error.clear();
        auto explicit_normals = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(explicit_normals);
        std::array<std::uint16_t, 32 * 32 * 4>
            explicit_normal_pixels{};
        std::array<float, 32 * 32> explicit_normal_depth{};
        REQUIRE(explicit_normals->colorTexture(0)->readback(
            *device, 0, 0, {}, explicit_normal_pixels.data(),
            32 * 8, &error));
        REQUIRE(explicit_normals->depthStencilTexture()->readback(
            *device, 0, 0, {}, explicit_normal_depth.data(),
            32 * sizeof(float), &error));
        std::size_t explicit_normal_changed = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            const bool changed =
                explicit_normal_pixels[offset + 0] !=
                    opaque_forward_pixels[offset + 0] ||
                explicit_normal_pixels[offset + 1] !=
                    opaque_forward_pixels[offset + 1] ||
                explicit_normal_pixels[offset + 2] !=
                    opaque_forward_pixels[offset + 2];
            explicit_normal_changed += changed;
            if (changed)
            {
                CHECK(explicit_normal_pixels[offset + 3] ==
                      opaque_forward_pixels[offset + 3]);
            }
        }
        CHECK(explicit_normal_changed >= 32);
        CHECK(explicit_normal_depth == opaque_forward_depth);

        auto normal_debug_positions = positions;
        for (auto& position : normal_debug_positions)
        {
            position[2] = -0.5f;
        }
        const std::array<std::array<float, 4>, 3>
            normal_debug_normals{{
                {{0.f, 1.f, 0.f, 0.f}},
                {{0.f, 1.f, 0.f, 0.f}},
                {{0.f, 1.f, 0.f, 0.f}},
            }};
        auto normal_debug_vertex_bytes = vertex_bytes;
        std::memcpy(normal_debug_vertex_bytes.data(),
                    normal_debug_positions.data(),
                    sizeof(normal_debug_positions));
        std::memcpy(normal_debug_vertex_bytes.data() + normal_offset,
                    normal_debug_normals.data(),
                    sizeof(normal_debug_normals));
        ALMetalBufferDescriptor normal_vertex_descriptor =
            vertex_descriptor;
        normal_vertex_descriptor.label =
            "Alchemy indexed normal-debug test vertices";
        auto normal_debug_vertices = ALMetalBuffer::create(
            *device, normal_vertex_descriptor, &error);
        INFO(error);
        REQUIRE(normal_debug_vertices);
        REQUIRE(normal_debug_vertices->write(
            0, normal_debug_vertex_bytes.data(),
            normal_debug_vertex_bytes.size(), &error));
        const std::array<std::uint32_t, 3>
            normal_index32_values{{0, 1, 2}};
        ALMetalBufferDescriptor normal_index32_descriptor;
        normal_index32_descriptor.length = sizeof(normal_index32_values);
        normal_index32_descriptor.storage = ALMetalStorageMode::shared;
        normal_index32_descriptor.label =
            "Alchemy uint32 normal-debug test indices";
        auto normal_indices32 = ALMetalBuffer::create(
            *device, normal_index32_descriptor, &error);
        INFO(error);
        REQUIRE(normal_indices32);
        REQUIRE(normal_indices32->write(
            0, normal_index32_values.data(),
            sizeof(normal_index32_values), &error));

        ALMetalWorldNormalBatch indexed_normal_batch;
        indexed_normal_batch.kind =
            ALMetalWorldNormalKind::indexed_geometry;
        indexed_normal_batch.vertices = normal_debug_vertices.get();
        indexed_normal_batch.position_offset = 0;
        indexed_normal_batch.normal_offset = normal_offset;
        indexed_normal_batch.vertex_count = positions.size();
        indexed_normal_batch.indices = indices.get();
        indexed_normal_batch.index_type = ALMetalIndexType::uint16;
        indexed_normal_batch.index_count = index_values.size();
        indexed_normal_batch.draw_length = 0.35f;
        for (std::size_t axis = 0; axis < 4; ++axis)
        {
            indexed_normal_batch.modelview_projection[
                axis * 4 + axis] = 1.f;
            indexed_normal_batch.modelview[axis * 4 + axis] = 1.f;
            indexed_normal_batch.projection[axis * 4 + axis] = 1.f;
        }
        opaque_forward_scene.normal_vertices = nullptr;
        opaque_forward_scene.normal_vertex_count = 0;
        opaque_forward_scene.normal_batches = &indexed_normal_batch;
        opaque_forward_scene.normal_batch_count = 1;

        indexed_normal_batch.vertices = nullptr;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world Normals batch is invalid");
        indexed_normal_batch.vertices = normal_debug_vertices.get();
        indexed_normal_batch.normal_offset =
            normal_debug_vertex_bytes.size();
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world Normals batch is invalid");
        indexed_normal_batch.normal_offset = normal_offset;
        indexed_normal_batch.index_type =
            static_cast<ALMetalIndexType>(99);
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world Normals batch is invalid");
        indexed_normal_batch.index_type = ALMetalIndexType::uint16;
        indexed_normal_batch.with_tangents = true;
        indexed_normal_batch.tangent_offset =
            normal_debug_vertex_bytes.size();
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world Normals batch is invalid");
        indexed_normal_batch.with_tangents = false;
        indexed_normal_batch.tangent_offset = 0;
        indexed_normal_batch.draw_length =
            std::numeric_limits<float>::quiet_NaN();
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world Normals batch is invalid");
        indexed_normal_batch.draw_length = 0.35f;

        error.clear();
        auto indexed_normals = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(indexed_normals);
        std::array<std::uint16_t, 32 * 32 * 4>
            indexed_normal_pixels{};
        std::array<float, 32 * 32> indexed_normal_depth{};
        REQUIRE(indexed_normals->colorTexture(0)->readback(
            *device, 0, 0, {}, indexed_normal_pixels.data(),
            32 * 8, &error));
        REQUIRE(indexed_normals->depthStencilTexture()->readback(
            *device, 0, 0, {}, indexed_normal_depth.data(),
            32 * sizeof(float), &error));
        std::size_t indexed_normal_changed = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            const bool changed =
                indexed_normal_pixels[offset + 0] !=
                    opaque_forward_pixels[offset + 0] ||
                indexed_normal_pixels[offset + 1] !=
                    opaque_forward_pixels[offset + 1] ||
                indexed_normal_pixels[offset + 2] !=
                    opaque_forward_pixels[offset + 2];
            indexed_normal_changed += changed;
            if (changed)
            {
                CHECK(indexed_normal_pixels[offset + 3] ==
                      opaque_forward_pixels[offset + 3]);
            }
        }
        CHECK(indexed_normal_changed >= 12);
        CHECK(indexed_normal_depth == opaque_forward_depth);

        indexed_normal_batch.with_tangents = true;
        indexed_normal_batch.tangent_offset = tangent_offset;
        error.clear();
        auto indexed_tangents = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(indexed_tangents);
        std::array<std::uint16_t, 32 * 32 * 4>
            indexed_tangent_pixels{};
        REQUIRE(indexed_tangents->colorTexture(0)->readback(
            *device, 0, 0, {}, indexed_tangent_pixels.data(),
            32 * 8, &error));
        CHECK(indexed_tangent_pixels != indexed_normal_pixels);

        indexed_normal_batch.indices = normal_indices32.get();
        indexed_normal_batch.index_type = ALMetalIndexType::uint32;
        error.clear();
        auto indexed_normals_u32 = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(indexed_normals_u32);
        std::array<std::uint16_t, 32 * 32 * 4>
            indexed_normal_u32_pixels{};
        REQUIRE(indexed_normals_u32->colorTexture(0)->readback(
            *device, 0, 0, {}, indexed_normal_u32_pixels.data(),
            32 * 8, &error));
        CHECK(indexed_normal_u32_pixels == indexed_tangent_pixels);

        debug_points[0].position[0] = 0.f;
        debug_points[0].position[1] = 0.f;
        debug_points[0].position[2] = 0.f;
        debug_point_batches[0].first_vertex = 0;
        debug_point_batches[0].vertex_count = 1;
        debug_point_batches[0].order = indexed_normal_batch.order;
        opaque_forward_scene.debug_points = debug_points.data();
        opaque_forward_scene.debug_point_count = 1;
        opaque_forward_scene.debug_point_batches =
            debug_point_batches.data();
        opaque_forward_scene.debug_point_batch_count = 1;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world render-debug ordering is invalid");
        opaque_forward_scene.debug_points = nullptr;
        opaque_forward_scene.debug_point_count = 0;
        opaque_forward_scene.debug_point_batches = nullptr;
        opaque_forward_scene.debug_point_batch_count = 0;

        for (auto& position : normal_debug_positions)
        {
            position[2] = 0.9f;
        }
        REQUIRE(normal_debug_vertices->write(
            0, normal_debug_positions.data(),
            sizeof(normal_debug_positions), &error));
        opaque_forward_scene.gbuffer = reverse_coverage_result.get();
        opaque_forward_scene.reverse_z = true;
        error.clear();
        auto reverse_indexed_normals =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_indexed_normals);
        std::array<std::uint16_t, 32 * 32 * 4>
            reverse_indexed_normal_pixels{};
        std::array<float, 32 * 32> reverse_indexed_normal_depth{};
        REQUIRE(reverse_indexed_normals->colorTexture(0)->readback(
            *device, 0, 0, {}, reverse_indexed_normal_pixels.data(),
            32 * 8, &error));
        REQUIRE(reverse_indexed_normals->depthStencilTexture()->readback(
            *device, 0, 0, {}, reverse_indexed_normal_depth.data(),
            32 * sizeof(float), &error));
        CHECK(reverse_indexed_normal_pixels !=
              reverse_agent_target_baseline_pixels);
        CHECK(reverse_indexed_normal_depth ==
              reverse_agent_target_baseline_depth);

        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.reverse_z = false;
        opaque_forward_scene.normal_batches = nullptr;
        opaque_forward_scene.normal_batch_count = 0;
        error.clear();
        auto no_normals = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(no_normals);
        std::array<std::uint16_t, 32 * 32 * 4> no_normal_pixels{};
        REQUIRE(no_normals->colorTexture(0)->readback(
            *device, 0, 0, {}, no_normal_pixels.data(),
            32 * 8, &error));
        CHECK(no_normal_pixels == opaque_forward_pixels);

        // Develop > Texel Density's three source modes bind a checkerboard
        // and calculate its texture matrix, but the production gDebugProgram
        // has no texture or UV input. The reachable visual draw is therefore
        // the current uniform color over each indexed face, with ordinary
        // RGB-only blending and writable world depth.
        ALMetalWorldTexelDensityBatch texel_density_batch;
        texel_density_batch.vertices = normal_debug_vertices.get();
        texel_density_batch.vertex_count = positions.size();
        texel_density_batch.indices = indices.get();
        texel_density_batch.index_type = ALMetalIndexType::uint16;
        texel_density_batch.index_count = index_values.size();
        texel_density_batch.color[0] = 0.25f;
        texel_density_batch.color[1] = 0.75f;
        texel_density_batch.color[2] = 0.5f;
        texel_density_batch.color[3] = 0.5f;
        for (std::size_t axis = 0; axis < 4; ++axis)
        {
            texel_density_batch.modelview_projection[
                axis * 4 + axis] = 1.f;
        }
        // The shared test positions currently sit at GL z=0.9. Move them to
        // z=-0.5 for the forward-depth proof so they cover the retained
        // G-buffer triangle and visibly replace its depth.
        texel_density_batch.modelview_projection[14] = -1.4f;
        opaque_forward_scene.texel_density_batches =
            &texel_density_batch;
        opaque_forward_scene.texel_density_batch_count = 1;

        opaque_forward_scene.texel_density_batches = nullptr;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world texel-density batch storage is invalid");
        opaque_forward_scene.texel_density_batches =
            &texel_density_batch;
        texel_density_batch.vertices = nullptr;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world texel-density batch is invalid");
        texel_density_batch.vertices = normal_debug_vertices.get();
        texel_density_batch.position_offset = sizeof(float);
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world texel-density batch is invalid");
        texel_density_batch.position_offset = 0;
        texel_density_batch.index_type =
            static_cast<ALMetalIndexType>(99);
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world texel-density batch is invalid");
        texel_density_batch.index_type = ALMetalIndexType::uint16;
        texel_density_batch.color[0] =
            std::numeric_limits<float>::quiet_NaN();
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world texel-density batch is invalid");
        texel_density_batch.color[0] = 0.25f;
        std::array<ALMetalWorldTexelDensityBatch, 2>
            texel_density_order_batches{{
                texel_density_batch, texel_density_batch,
            }};
        texel_density_order_batches[0].order = 1;
        texel_density_order_batches[1].order = 0;
        opaque_forward_scene.texel_density_batches =
            texel_density_order_batches.data();
        opaque_forward_scene.texel_density_batch_count =
            texel_density_order_batches.size();
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world texel-density batch is invalid");
        opaque_forward_scene.texel_density_batches =
            &texel_density_batch;
        opaque_forward_scene.texel_density_batch_count = 1;

        error.clear();
        auto texel_density = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(texel_density);
        std::array<std::uint16_t, 32 * 32 * 4>
            texel_density_pixels{};
        std::array<float, 32 * 32> texel_density_depth{};
        REQUIRE(texel_density->colorTexture(0)->readback(
            *device, 0, 0, {}, texel_density_pixels.data(),
            32 * 8, &error));
        REQUIRE(texel_density->depthStencilTexture()->readback(
            *device, 0, 0, {}, texel_density_depth.data(),
            32 * sizeof(float), &error));
        std::size_t texel_density_changed = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            const bool changed =
                texel_density_pixels[offset + 0] !=
                    opaque_forward_pixels[offset + 0] ||
                texel_density_pixels[offset + 1] !=
                    opaque_forward_pixels[offset + 1] ||
                texel_density_pixels[offset + 2] !=
                    opaque_forward_pixels[offset + 2];
            texel_density_changed += changed;
            if (changed)
            {
                CHECK(texel_density_pixels[offset + 3] ==
                      opaque_forward_pixels[offset + 3]);
            }
        }
        CHECK(texel_density_changed >= 128);
        CHECK(texel_density_depth != opaque_forward_depth);

        texel_density_batch.indices = normal_indices32.get();
        texel_density_batch.index_type = ALMetalIndexType::uint32;
        error.clear();
        auto texel_density_u32 = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(texel_density_u32);
        std::array<std::uint16_t, 32 * 32 * 4>
            texel_density_u32_pixels{};
        REQUIRE(texel_density_u32->colorTexture(0)->readback(
            *device, 0, 0, {}, texel_density_u32_pixels.data(),
            32 * 8, &error));
        CHECK(texel_density_u32_pixels == texel_density_pixels);

        debug_points[0].position[0] = 0.f;
        debug_points[0].position[1] = 0.f;
        debug_points[0].position[2] = 0.f;
        debug_point_batches[0].first_vertex = 0;
        debug_point_batches[0].vertex_count = 1;
        debug_point_batches[0].order = texel_density_batch.order;
        opaque_forward_scene.debug_points = debug_points.data();
        opaque_forward_scene.debug_point_count = 1;
        opaque_forward_scene.debug_point_batches =
            debug_point_batches.data();
        opaque_forward_scene.debug_point_batch_count = 1;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world render-debug ordering is invalid");
        opaque_forward_scene.debug_points = nullptr;
        opaque_forward_scene.debug_point_count = 0;
        opaque_forward_scene.debug_point_batches = nullptr;
        opaque_forward_scene.debug_point_batch_count = 0;

        texel_density_batch.modelview_projection[14] = 0.f;
        opaque_forward_scene.gbuffer = reverse_coverage_result.get();
        opaque_forward_scene.reverse_z = true;
        error.clear();
        auto reverse_texel_density =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_texel_density);
        std::array<std::uint16_t, 32 * 32 * 4>
            reverse_texel_density_pixels{};
        std::array<float, 32 * 32> reverse_texel_density_depth{};
        REQUIRE(reverse_texel_density->colorTexture(0)->readback(
            *device, 0, 0, {}, reverse_texel_density_pixels.data(),
            32 * 8, &error));
        REQUIRE(reverse_texel_density->depthStencilTexture()->readback(
            *device, 0, 0, {}, reverse_texel_density_depth.data(),
            32 * sizeof(float), &error));
        CHECK(reverse_texel_density_pixels !=
              reverse_agent_target_baseline_pixels);
        CHECK(reverse_texel_density_depth !=
              reverse_agent_target_baseline_depth);

        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.reverse_z = false;
        opaque_forward_scene.texel_density_batches = nullptr;
        opaque_forward_scene.texel_density_batch_count = 0;
        error.clear();
        auto no_texel_density = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(no_texel_density);
        std::array<std::uint16_t, 32 * 32 * 4>
            no_texel_density_pixels{};
        REQUIRE(no_texel_density->colorTexture(0)->readback(
            *device, 0, 0, {}, no_texel_density_pixels.data(),
            32 * 8, &error));
        CHECK(no_texel_density_pixels == opaque_forward_pixels);

        // Develop > Texture Anim selects visible draw-info triangles whose
        // texture matrix is non-null, but gDebugProgram consumes positions
        // only and emits one fixed translucent-yellow uniform. The enclosing
        // spatial-debug owner disables culling and inherits RGB-only alpha
        // blend plus read/write world depth.
        ALMetalWorldTextureAnimBatch texture_anim_batch;
        texture_anim_batch.vertices = vertices.get();
        texture_anim_batch.vertex_count = positions.size();
        texture_anim_batch.indices = indices.get();
        texture_anim_batch.index_count = index_values.size();
        for (std::size_t axis = 0; axis < 4; ++axis)
        {
            texture_anim_batch.modelview_projection[
                axis * 4 + axis] = 1.f;
        }
        opaque_forward_scene.texture_anim_batches =
            &texture_anim_batch;
        opaque_forward_scene.texture_anim_batch_count = 1;

        opaque_forward_scene.texture_anim_batches = nullptr;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world texture-animation batch storage is invalid");
        opaque_forward_scene.texture_anim_batches =
            &texture_anim_batch;
        texture_anim_batch.vertices = nullptr;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world texture-animation batch is invalid");
        texture_anim_batch.vertices = vertices.get();
        texture_anim_batch.index_count = 2;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world texture-animation batch is invalid");
        texture_anim_batch.index_count = index_values.size();
        texture_anim_batch.modelview_projection[0] =
            std::numeric_limits<float>::quiet_NaN();
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world texture-animation batch is invalid");
        texture_anim_batch.modelview_projection[0] = 1.f;
        error.clear();

        auto native_texture_anim = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(native_texture_anim);
        std::array<std::uint16_t, 32 * 32 * 4>
            texture_anim_pixels{};
        std::array<float, 32 * 32> texture_anim_depth{};
        REQUIRE(native_texture_anim->colorTexture(0)->readback(
            *device, 0, 0, {}, texture_anim_pixels.data(), 32 * 8,
            &error));
        REQUIRE(native_texture_anim->depthStencilTexture()->readback(
            *device, 0, 0, {}, texture_anim_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        const float texture_anim_destination[3] = {
            agent_half_to_float(opaque_forward_pixels[center + 0]),
            agent_half_to_float(opaque_forward_pixels[center + 1]),
            agent_half_to_float(opaque_forward_pixels[center + 2]),
        };
        const float texture_anim_expected[3] = {
            0.5f + texture_anim_destination[0] * 0.5f,
            0.5f + texture_anim_destination[1] * 0.5f,
            texture_anim_destination[2] * 0.5f,
        };
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            CHECK(std::abs(
                agent_half_to_float(
                    texture_anim_pixels[center + channel]) -
                texture_anim_expected[channel]) < 0.001f);
        }
        CHECK(texture_anim_pixels[center + 3] ==
              opaque_forward_pixels[center + 3]);
        CHECK(std::abs(
            texture_anim_depth[16 * 32 + 16] - 0.625f) < 0.0001f);

        // Source culling is disabled for this entire debug traversal.
        texture_anim_batch.indices = reversed_indices.get();
        auto reverse_winding_texture_anim =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_winding_texture_anim);
        texture_anim_pixels.fill(0xffffu);
        REQUIRE(
            reverse_winding_texture_anim->colorTexture(0)->readback(
                *device, 0, 0, {}, texture_anim_pixels.data(),
                32 * 8, &error));
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            CHECK(std::abs(
                agent_half_to_float(
                    texture_anim_pixels[center + channel]) -
                texture_anim_expected[channel]) < 0.001f);
        }
        texture_anim_batch.indices = indices.get();

        texture_anim_batch.modelview_projection[14] = 0.5f;
        auto hidden_texture_anim = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(hidden_texture_anim);
        texture_anim_pixels.fill(0xffffu);
        texture_anim_depth.fill(-1.f);
        REQUIRE(hidden_texture_anim->colorTexture(0)->readback(
            *device, 0, 0, {}, texture_anim_pixels.data(), 32 * 8,
            &error));
        REQUIRE(hidden_texture_anim->depthStencilTexture()->readback(
            *device, 0, 0, {}, texture_anim_depth.data(),
            32 * sizeof(float), &error));
        CHECK(texture_anim_pixels[center + 0] ==
              opaque_forward_pixels[center + 0]);
        CHECK(texture_anim_pixels[center + 1] ==
              opaque_forward_pixels[center + 1]);
        CHECK(texture_anim_pixels[center + 2] ==
              opaque_forward_pixels[center + 2]);
        CHECK(texture_anim_depth == opaque_forward_depth);

        opaque_forward_scene.gbuffer = reverse_coverage_result.get();
        opaque_forward_scene.reverse_z = true;
        texture_anim_batch.modelview_projection[14] = 0.65f;
        auto reverse_texture_anim = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_texture_anim);
        texture_anim_pixels.fill(0xffffu);
        texture_anim_depth.fill(-1.f);
        REQUIRE(reverse_texture_anim->colorTexture(0)->readback(
            *device, 0, 0, {}, texture_anim_pixels.data(), 32 * 8,
            &error));
        REQUIRE(reverse_texture_anim->depthStencilTexture()->readback(
            *device, 0, 0, {}, texture_anim_depth.data(),
            32 * sizeof(float), &error));
        CHECK(texture_anim_pixels[center + 0] !=
              reverse_agent_target_baseline_pixels[center + 0]);
        CHECK(texture_anim_pixels[center + 3] ==
              reverse_agent_target_baseline_pixels[center + 3]);
        CHECK(std::abs(
            texture_anim_depth[16 * 32 + 16] - 0.9f) < 0.0001f);

        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.reverse_z = false;
        texture_anim_batch.modelview_projection[14] = 0.f;
        debug_points[0].position[0] = 0.03125f;
        debug_points[0].position[1] = 0.03125f;
        debug_points[0].position[2] = 0.9f;
        debug_point_batches[0].first_vertex = 0;
        debug_point_batches[0].vertex_count = 1;
        debug_point_batches[0].order = 1;
        texture_anim_batch.order = 0;
        opaque_forward_scene.debug_points = debug_points.data();
        opaque_forward_scene.debug_point_count = 1;
        opaque_forward_scene.debug_point_batches =
            debug_point_batches.data();
        opaque_forward_scene.debug_point_batch_count = 1;
        auto point_after_texture_anim =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(point_after_texture_anim);
        texture_anim_pixels.fill(0xffffu);
        REQUIRE(point_after_texture_anim->colorTexture(0)->readback(
            *device, 0, 0, {}, texture_anim_pixels.data(), 32 * 8,
            &error));
        CHECK(texture_anim_pixels[center + 0] == 0x3c00);
        CHECK(texture_anim_pixels[center + 1] == 0x3c00);
        CHECK(texture_anim_pixels[center + 2] == 0x3c00);

        debug_point_batches[0].order = 0;
        texture_anim_batch.order = 1;
        auto texture_anim_after_point =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(texture_anim_after_point);
        texture_anim_pixels.fill(0xffffu);
        REQUIRE(texture_anim_after_point->colorTexture(0)->readback(
            *device, 0, 0, {}, texture_anim_pixels.data(), 32 * 8,
            &error));
        CHECK(texture_anim_pixels[center + 0] == 0x3c00);
        CHECK(texture_anim_pixels[center + 1] == 0x3c00);
        CHECK(std::abs(
            agent_half_to_float(texture_anim_pixels[center + 2]) -
            0.5f) < 0.001f);
        CHECK(texture_anim_pixels[center + 3] ==
              opaque_forward_pixels[center + 3]);

        texture_anim_batch.order = 0;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world render-debug ordering is invalid");
        error.clear();
        opaque_forward_scene.debug_points = nullptr;
        opaque_forward_scene.debug_point_count = 0;
        opaque_forward_scene.debug_point_batches = nullptr;
        opaque_forward_scene.debug_point_batch_count = 0;
        opaque_forward_scene.texture_anim_batches = nullptr;
        opaque_forward_scene.texture_anim_batch_count = 0;
        auto no_texture_anim = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(no_texture_anim);
        texture_anim_pixels.fill(0xffffu);
        texture_anim_depth.fill(-1.f);
        REQUIRE(no_texture_anim->colorTexture(0)->readback(
            *device, 0, 0, {}, texture_anim_pixels.data(), 32 * 8,
            &error));
        REQUIRE(no_texture_anim->depthStencilTexture()->readback(
            *device, 0, 0, {}, texture_anim_depth.data(),
            32 * sizeof(float), &error));
        CHECK(texture_anim_pixels == opaque_forward_pixels);
        CHECK(texture_anim_depth == opaque_forward_depth);

        // Develop > Update Type replays every face with one of five fixed
        // half-alpha colors while keeping the same position-only debug shader
        // and inherited no-cull/read-write-depth state as Texture Anim.
        ALMetalWorldUpdateTypeBatch update_type_batch;
        update_type_batch.vertices = vertices.get();
        update_type_batch.vertex_count = positions.size();
        update_type_batch.indices = indices.get();
        update_type_batch.index_count = index_values.size();
        for (std::size_t axis = 0; axis < 4; ++axis)
        {
            update_type_batch.modelview_projection[
                axis * 4 + axis] = 1.f;
        }
        const std::array<std::array<float, 4>, 5> update_type_colors{{
            {{0.f, 1.f, 0.f, 0.5f}},
            {{0.f, 1.f, 1.f, 0.5f}},
            {{1.f, 0.f, 0.f, 0.5f}},
            {{1.f, 1.f, 0.f, 0.5f}},
            {{0.f, 0.f, 1.f, 0.5f}},
        }};
        std::memcpy(update_type_batch.color,
                    update_type_colors[0].data(),
                    sizeof(update_type_batch.color));
        opaque_forward_scene.update_type_batches = &update_type_batch;
        opaque_forward_scene.update_type_batch_count = 1;

        opaque_forward_scene.update_type_batches = nullptr;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world update-type batch storage is invalid");
        opaque_forward_scene.update_type_batches = &update_type_batch;
        update_type_batch.vertices = nullptr;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world update-type batch is invalid");
        update_type_batch.vertices = vertices.get();
        update_type_batch.index_count = 2;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world update-type batch is invalid");
        update_type_batch.index_count = index_values.size();
        update_type_batch.color[3] = 1.f;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world update-type batch is invalid");
        std::memcpy(update_type_batch.color,
                    update_type_colors[0].data(),
                    sizeof(update_type_batch.color));
        update_type_batch.modelview_projection[0] =
            std::numeric_limits<float>::quiet_NaN();
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world update-type batch is invalid");
        update_type_batch.modelview_projection[0] = 1.f;
        error.clear();

        std::array<std::uint16_t, 32 * 32 * 4>
            update_type_pixels{};
        std::array<float, 32 * 32> update_type_depth{};
        for (const auto& color : update_type_colors)
        {
            std::memcpy(update_type_batch.color, color.data(),
                        sizeof(update_type_batch.color));
            auto update_type_result = renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
            INFO(error);
            REQUIRE(update_type_result);
            update_type_pixels.fill(0xffffu);
            update_type_depth.fill(-1.f);
            REQUIRE(update_type_result->colorTexture(0)->readback(
                *device, 0, 0, {}, update_type_pixels.data(),
                32 * 8, &error));
            REQUIRE(update_type_result->depthStencilTexture()->readback(
                *device, 0, 0, {}, update_type_depth.data(),
                32 * sizeof(float), &error));
            for (std::size_t channel = 0; channel < 3; ++channel)
            {
                const float expected =
                    color[channel] * 0.5f +
                    texture_anim_destination[channel] * 0.5f;
                CHECK(std::abs(agent_half_to_float(
                    update_type_pixels[center + channel]) -
                    expected) < 0.001f);
            }
            CHECK(update_type_pixels[center + 3] ==
                  opaque_forward_pixels[center + 3]);
            CHECK(std::abs(
                update_type_depth[16 * 32 + 16] - 0.625f) <
                0.0001f);
        }

        update_type_batch.indices = reversed_indices.get();
        auto reverse_winding_update_type =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_winding_update_type);
        update_type_pixels.fill(0xffffu);
        REQUIRE(reverse_winding_update_type->colorTexture(0)->readback(
            *device, 0, 0, {}, update_type_pixels.data(),
            32 * 8, &error));
        CHECK(update_type_pixels[center + 2] !=
              opaque_forward_pixels[center + 2]);
        update_type_batch.indices = indices.get();

        update_type_batch.modelview_projection[14] = 0.5f;
        auto hidden_update_type = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(hidden_update_type);
        update_type_pixels.fill(0xffffu);
        update_type_depth.fill(-1.f);
        REQUIRE(hidden_update_type->colorTexture(0)->readback(
            *device, 0, 0, {}, update_type_pixels.data(), 32 * 8,
            &error));
        REQUIRE(hidden_update_type->depthStencilTexture()->readback(
            *device, 0, 0, {}, update_type_depth.data(),
            32 * sizeof(float), &error));
        CHECK(update_type_pixels == opaque_forward_pixels);
        CHECK(update_type_depth == opaque_forward_depth);

        opaque_forward_scene.gbuffer = reverse_coverage_result.get();
        opaque_forward_scene.reverse_z = true;
        update_type_batch.modelview_projection[14] = 0.65f;
        auto reverse_update_type = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_update_type);
        update_type_pixels.fill(0xffffu);
        update_type_depth.fill(-1.f);
        REQUIRE(reverse_update_type->colorTexture(0)->readback(
            *device, 0, 0, {}, update_type_pixels.data(), 32 * 8,
            &error));
        REQUIRE(reverse_update_type->depthStencilTexture()->readback(
            *device, 0, 0, {}, update_type_depth.data(),
            32 * sizeof(float), &error));
        CHECK(update_type_pixels[center + 2] !=
              reverse_agent_target_baseline_pixels[center + 2]);
        CHECK(update_type_pixels[center + 3] ==
              reverse_agent_target_baseline_pixels[center + 3]);
        CHECK(std::abs(
            update_type_depth[16 * 32 + 16] - 0.9f) < 0.0001f);

        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.reverse_z = false;
        update_type_batch.modelview_projection[14] = 0.f;
        std::memcpy(update_type_batch.color,
                    update_type_colors[4].data(),
                    sizeof(update_type_batch.color));
        opaque_forward_scene.texture_anim_batches =
            &texture_anim_batch;
        opaque_forward_scene.texture_anim_batch_count = 1;
        update_type_batch.order = 0;
        texture_anim_batch.order = 1;
        auto texture_after_update_type =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(texture_after_update_type);
        std::array<std::uint16_t, 32 * 32 * 4>
            texture_after_update_pixels{};
        REQUIRE(texture_after_update_type->colorTexture(0)->readback(
            *device, 0, 0, {}, texture_after_update_pixels.data(),
            32 * 8, &error));

        update_type_batch.order = 1;
        texture_anim_batch.order = 0;
        auto update_type_after_texture =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(update_type_after_texture);
        std::array<std::uint16_t, 32 * 32 * 4>
            update_after_texture_pixels{};
        REQUIRE(update_type_after_texture->colorTexture(0)->readback(
            *device, 0, 0, {}, update_after_texture_pixels.data(),
            32 * 8, &error));
        CHECK(texture_after_update_pixels[center + 0] !=
              update_after_texture_pixels[center + 0]);
        CHECK(texture_after_update_pixels[center + 2] !=
              update_after_texture_pixels[center + 2]);
        CHECK(texture_after_update_pixels[center + 3] ==
              opaque_forward_pixels[center + 3]);
        CHECK(update_after_texture_pixels[center + 3] ==
              opaque_forward_pixels[center + 3]);

        update_type_batch.order = 0;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world render-debug ordering is invalid");
        error.clear();
        opaque_forward_scene.texture_anim_batches = nullptr;
        opaque_forward_scene.texture_anim_batch_count = 0;
        opaque_forward_scene.update_type_batches = nullptr;
        opaque_forward_scene.update_type_batch_count = 0;
        auto no_update_type = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(no_update_type);
        update_type_pixels.fill(0xffffu);
        update_type_depth.fill(-1.f);
        REQUIRE(no_update_type->colorTexture(0)->readback(
            *device, 0, 0, {}, update_type_pixels.data(), 32 * 8,
            &error));
        REQUIRE(no_update_type->depthStencilTexture()->readback(
            *device, 0, 0, {}, update_type_depth.data(),
            32 * sizeof(float), &error));
        CHECK(update_type_pixels == opaque_forward_pixels);
        CHECK(update_type_depth == opaque_forward_depth);

        // Develop > Batch Size uses one stable hash colour per LLDrawInfo,
        // applies semantic polygon offset (-1 factor, +1 unit), and switches
        // to gDebugProgram's object-skinned variant for avatar draw infos.
        // It otherwise inherits the same RGB-only alpha blend, no-cull and
        // read/write depth state as the adjacent debug overlays.
        ALMetalWorldBatchSizeBatch batch_size_batch;
        batch_size_batch.vertices = vertices.get();
        batch_size_batch.vertex_count = positions.size();
        batch_size_batch.indices = indices.get();
        batch_size_batch.index_count = index_values.size();
        for (std::size_t axis = 0; axis < 4; ++axis)
        {
            batch_size_batch.modelview_projection[
                axis * 4 + axis] = 1.f;
        }
        const std::array<float, 4> batch_size_color{{
            64.f / 255.f, 128.f / 255.f, 1.f, 200.f / 255.f,
        }};
        std::memcpy(batch_size_batch.color,
                    batch_size_color.data(),
                    sizeof(batch_size_batch.color));
        opaque_forward_scene.batch_size_batches = &batch_size_batch;
        opaque_forward_scene.batch_size_batch_count = 1;

        opaque_forward_scene.batch_size_batches = nullptr;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world batch-size batch storage is invalid");
        opaque_forward_scene.batch_size_batches = &batch_size_batch;
        batch_size_batch.color[3] = 1.f;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world batch-size batch is invalid");
        std::memcpy(batch_size_batch.color,
                    batch_size_color.data(),
                    sizeof(batch_size_batch.color));
        error.clear();

        auto native_batch_size = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(native_batch_size);
        std::array<std::uint16_t, 32 * 32 * 4>
            batch_size_pixels{};
        std::array<float, 32 * 32> batch_size_depth{};
        REQUIRE(native_batch_size->colorTexture(0)->readback(
            *device, 0, 0, {}, batch_size_pixels.data(), 32 * 8,
            &error));
        REQUIRE(native_batch_size->depthStencilTexture()->readback(
            *device, 0, 0, {}, batch_size_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            const float alpha = batch_size_color[3];
            const float expected = batch_size_color[channel] * alpha +
                texture_anim_destination[channel] * (1.f - alpha);
            CHECK(std::abs(agent_half_to_float(
                batch_size_pixels[center + channel]) - expected) <
                0.001f);
        }
        CHECK(batch_size_pixels[center + 3] ==
              opaque_forward_pixels[center + 3]);
        CHECK(batch_size_depth[16 * 32 + 16] < 0.625f);

        batch_size_batch.indices = reversed_indices.get();
        auto reverse_winding_batch_size =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_winding_batch_size);
        batch_size_pixels.fill(0xffffu);
        REQUIRE(reverse_winding_batch_size->colorTexture(0)->readback(
            *device, 0, 0, {}, batch_size_pixels.data(), 32 * 8,
            &error));
        CHECK(batch_size_pixels[center + 0] !=
              opaque_forward_pixels[center + 0]);
        batch_size_batch.indices = indices.get();

        opaque_forward_scene.gbuffer = reverse_coverage_result.get();
        opaque_forward_scene.reverse_z = true;
        auto reverse_batch_size = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_batch_size);
        batch_size_depth.fill(-1.f);
        REQUIRE(reverse_batch_size->depthStencilTexture()->readback(
            *device, 0, 0, {}, batch_size_depth.data(),
            32 * sizeof(float), &error));
        CHECK(batch_size_depth[16 * 32 + 16] > 0.25f);

        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.reverse_z = false;
        batch_size_batch.weight_offset = weight_offset;
        batch_size_batch.skin_palette = skin_palette.data();
        batch_size_batch.skin_palette_float_count =
            skin_palette.size() - 1;
        batch_size_batch.skin_joint_count = 1;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world batch-size batch is invalid");
        batch_size_batch.skin_palette_float_count = skin_palette.size();
        error.clear();
        auto rigged_batch_size = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(rigged_batch_size);
        batch_size_pixels.fill(0xffffu);
        REQUIRE(rigged_batch_size->colorTexture(0)->readback(
            *device, 0, 0, {}, batch_size_pixels.data(), 32 * 8,
            &error));
        std::size_t rigged_batch_size_first_x = 32;
        std::size_t rigged_batch_size_last_x = 0;
        for (std::size_t x = 0; x < 32; ++x)
        {
            const std::size_t pixel = (16 * 32 + x) * 4;
            const bool changed =
                batch_size_pixels[pixel + 0] !=
                    opaque_forward_pixels[pixel + 0] ||
                batch_size_pixels[pixel + 1] !=
                    opaque_forward_pixels[pixel + 1] ||
                batch_size_pixels[pixel + 2] !=
                    opaque_forward_pixels[pixel + 2];
            if (changed)
            {
                rigged_batch_size_first_x = std::min(
                    rigged_batch_size_first_x, x);
                rigged_batch_size_last_x = std::max(
                    rigged_batch_size_last_x, x);
            }
        }
        CHECK(rigged_batch_size_first_x >= 11);
        CHECK(rigged_batch_size_last_x >= 28);

        batch_size_batch.skin_palette = nullptr;
        batch_size_batch.skin_palette_float_count = 0;
        batch_size_batch.skin_joint_count = 0;
        batch_size_batch.weight_offset = 0;
        std::memcpy(update_type_batch.color,
                    update_type_colors[4].data(),
                    sizeof(update_type_batch.color));
        opaque_forward_scene.update_type_batches = &update_type_batch;
        opaque_forward_scene.update_type_batch_count = 1;
        batch_size_batch.order = 0;
        update_type_batch.order = 1;
        auto update_after_batch_size =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(update_after_batch_size);
        std::array<std::uint16_t, 32 * 32 * 4>
            update_after_batch_size_pixels{};
        REQUIRE(update_after_batch_size->colorTexture(0)->readback(
            *device, 0, 0, {},
            update_after_batch_size_pixels.data(), 32 * 8, &error));

        batch_size_batch.order = 1;
        update_type_batch.order = 0;
        auto batch_size_after_update =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(batch_size_after_update);
        std::array<std::uint16_t, 32 * 32 * 4>
            batch_size_after_update_pixels{};
        REQUIRE(batch_size_after_update->colorTexture(0)->readback(
            *device, 0, 0, {},
            batch_size_after_update_pixels.data(), 32 * 8, &error));
        CHECK(update_after_batch_size_pixels[center + 0] !=
              batch_size_after_update_pixels[center + 0]);
        CHECK(update_after_batch_size_pixels[center + 2] !=
              batch_size_after_update_pixels[center + 2]);

        batch_size_batch.order = 0;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world render-debug ordering is invalid");
        error.clear();
        opaque_forward_scene.update_type_batches = nullptr;
        opaque_forward_scene.update_type_batch_count = 0;
        opaque_forward_scene.batch_size_batches = nullptr;
        opaque_forward_scene.batch_size_batch_count = 0;
        auto no_batch_size = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(no_batch_size);
        batch_size_pixels.fill(0xffffu);
        batch_size_depth.fill(-1.f);
        REQUIRE(no_batch_size->colorTexture(0)->readback(
            *device, 0, 0, {}, batch_size_pixels.data(), 32 * 8,
            &error));
        REQUIRE(no_batch_size->depthStencilTexture()->readback(
            *device, 0, 0, {}, batch_size_depth.data(),
            32 * sizeof(float), &error));
        CHECK(batch_size_pixels == opaque_forward_pixels);
        CHECK(batch_size_depth == opaque_forward_depth);

        // Develop > Lights is one ordered source transaction per light:
        // translucent-cyan indexed faces, an always-pass depth-writing white
        // spatial box, then a yellow radius box under ambient read/write
        // LEQUAL depth. Generated box vertices must not hide an accidental
        // triangle-only implementation.
        std::array<ALMetalWorldLightDebugBatch, 3>
            light_debug_batches{};
        ALMetalWorldLightDebugBatch& light_faces =
            light_debug_batches[0];
        light_faces.kind = ALMetalWorldLightDebugKind::triangles;
        light_faces.vertices = vertices.get();
        light_faces.vertex_count = positions.size();
        light_faces.indices = indices.get();
        light_faces.index_count = index_values.size();
        light_faces.color[0] = 0.f;
        light_faces.color[1] = 1.f;
        light_faces.color[2] = 1.f;
        light_faces.color[3] = 0.5f;

        ALMetalWorldLightDebugBatch& light_spatial_bounds =
            light_debug_batches[1];
        light_spatial_bounds.kind =
            ALMetalWorldLightDebugKind::spatial_bounds;
        light_spatial_bounds.center[0] = -0.25f;
        light_spatial_bounds.center[1] = 0.f;
        light_spatial_bounds.center[2] = 0.8f;
        light_spatial_bounds.half_extent[0] = 0.06f;
        light_spatial_bounds.half_extent[1] = 0.1f;
        light_spatial_bounds.half_extent[2] = 0.05f;
        light_spatial_bounds.color[0] = 1.f;
        light_spatial_bounds.color[1] = 1.f;
        light_spatial_bounds.color[2] = 1.f;
        light_spatial_bounds.color[3] = 1.f;

        ALMetalWorldLightDebugBatch& light_radius_bounds =
            light_debug_batches[2];
        light_radius_bounds.kind =
            ALMetalWorldLightDebugKind::radius_bounds;
        light_radius_bounds.center[0] = 0.25f;
        light_radius_bounds.center[1] = 0.f;
        light_radius_bounds.center[2] = 0.8f;
        light_radius_bounds.half_extent[0] = 0.06f;
        light_radius_bounds.half_extent[1] = 0.1f;
        light_radius_bounds.half_extent[2] = 0.05f;
        light_radius_bounds.color[0] = 1.f;
        light_radius_bounds.color[1] = 1.f;
        light_radius_bounds.color[2] = 0.f;
        light_radius_bounds.color[3] = 1.f;

        for (std::size_t batch = 0;
             batch < light_debug_batches.size(); ++batch)
        {
            light_debug_batches[batch].order = batch;
            for (std::size_t axis = 0; axis < 4; ++axis)
            {
                light_debug_batches[batch].modelview_projection[
                    axis * 4 + axis] = 1.f;
            }
        }
        opaque_forward_scene.light_debug_batches =
            light_debug_batches.data();
        opaque_forward_scene.light_debug_batch_count =
            light_debug_batches.size();

        opaque_forward_scene.light_debug_batches = nullptr;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world light-debug batch storage is invalid");
        opaque_forward_scene.light_debug_batches =
            light_debug_batches.data();
        light_faces.color[3] = 1.f;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world light-debug batch is invalid");
        light_faces.color[3] = 0.5f;
        light_spatial_bounds.center[0] =
            std::numeric_limits<float>::quiet_NaN();
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world light-debug batch is invalid");
        light_spatial_bounds.center[0] = -0.25f;
        error.clear();

        auto native_light_debug = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(native_light_debug);
        std::array<std::uint16_t, 32 * 32 * 4>
            light_debug_pixels{};
        std::array<float, 32 * 32> light_debug_depth{};
        REQUIRE(native_light_debug->colorTexture(0)->readback(
            *device, 0, 0, {}, light_debug_pixels.data(), 32 * 8,
            &error));
        REQUIRE(native_light_debug->depthStencilTexture()->readback(
            *device, 0, 0, {}, light_debug_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        const float light_face_source[3] = {0.f, 1.f, 1.f};
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            const float expected = light_face_source[channel] * 0.5f +
                texture_anim_destination[channel] * 0.5f;
            CHECK(std::abs(agent_half_to_float(
                light_debug_pixels[center + channel]) - expected) <
                0.001f);
        }
        CHECK(light_debug_pixels[center + 3] ==
              opaque_forward_pixels[center + 3]);
        CHECK(std::abs(light_debug_depth[16 * 32 + 16] - 0.625f) <
              0.0001f);

        std::size_t white_light_pixels = 0;
        std::size_t yellow_light_pixels = 0;
        std::size_t white_depth_writes = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            const bool white =
                light_debug_pixels[offset + 0] == 0x3c00 &&
                light_debug_pixels[offset + 1] == 0x3c00 &&
                light_debug_pixels[offset + 2] == 0x3c00;
            const bool yellow =
                light_debug_pixels[offset + 0] == 0x3c00 &&
                light_debug_pixels[offset + 1] == 0x3c00 &&
                light_debug_pixels[offset + 2] == 0u;
            white_light_pixels += white;
            yellow_light_pixels += yellow;
            white_depth_writes += white &&
                light_debug_depth[pixel] > 0.8f;
            if (white || yellow)
            {
                CHECK(light_debug_pixels[offset + 3] ==
                      opaque_forward_pixels[offset + 3]);
            }
        }
        CHECK(white_light_pixels > 0);
        CHECK(white_depth_writes > 0);
        CHECK(yellow_light_pixels == 0);

        // Move the radius outline in front of retained geometry. Its yellow
        // pixels and depth writes distinguish ordinary LEQUAL from the
        // preceding always-pass white outline.
        light_radius_bounds.center[2] = -0.2f;
        auto visible_light_radius = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(visible_light_radius);
        light_debug_pixels.fill(0xffffu);
        light_debug_depth.fill(-1.f);
        REQUIRE(visible_light_radius->colorTexture(0)->readback(
            *device, 0, 0, {}, light_debug_pixels.data(), 32 * 8,
            &error));
        REQUIRE(visible_light_radius->depthStencilTexture()->readback(
            *device, 0, 0, {}, light_debug_depth.data(),
            32 * sizeof(float), &error));
        yellow_light_pixels = 0;
        std::size_t yellow_depth_writes = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            const bool yellow =
                light_debug_pixels[offset + 0] == 0x3c00 &&
                light_debug_pixels[offset + 1] == 0x3c00 &&
                light_debug_pixels[offset + 2] == 0u;
            yellow_light_pixels += yellow;
            yellow_depth_writes += yellow &&
                light_debug_depth[pixel] < 0.5f;
        }
        CHECK(yellow_light_pixels > 0);
        CHECK(yellow_depth_writes > 0);

        light_faces.indices = reversed_indices.get();
        auto reverse_winding_light = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_winding_light);
        light_debug_pixels.fill(0xffffu);
        REQUIRE(reverse_winding_light->colorTexture(0)->readback(
            *device, 0, 0, {}, light_debug_pixels.data(), 32 * 8,
            &error));
        CHECK(light_debug_pixels[center + 1] !=
              opaque_forward_pixels[center + 1]);
        light_faces.indices = indices.get();

        opaque_forward_scene.gbuffer = reverse_coverage_result.get();
        opaque_forward_scene.reverse_z = true;
        light_radius_bounds.center[2] = 0.75f;
        auto reverse_light_debug = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_light_debug);
        light_debug_pixels.fill(0xffffu);
        light_debug_depth.fill(-1.f);
        REQUIRE(reverse_light_debug->colorTexture(0)->readback(
            *device, 0, 0, {}, light_debug_pixels.data(), 32 * 8,
            &error));
        REQUIRE(reverse_light_debug->depthStencilTexture()->readback(
            *device, 0, 0, {}, light_debug_depth.data(),
            32 * sizeof(float), &error));
        yellow_light_pixels = 0;
        yellow_depth_writes = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            const bool yellow =
                light_debug_pixels[offset + 0] == 0x3c00 &&
                light_debug_pixels[offset + 1] == 0x3c00 &&
                light_debug_pixels[offset + 2] == 0u;
            yellow_light_pixels += yellow;
            yellow_depth_writes += yellow &&
                light_debug_depth[pixel] > 0.6f;
        }
        CHECK(yellow_light_pixels > 0);
        CHECK(yellow_depth_writes > 0);
        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.reverse_z = false;

        // Light faces participate in the same traversal order as Update
        // Type. Exercise both directions and reject one colliding order.
        light_radius_bounds.center[2] = -0.2f;
        std::memcpy(update_type_batch.color,
                    update_type_colors[4].data(),
                    sizeof(update_type_batch.color));
        opaque_forward_scene.update_type_batches = &update_type_batch;
        opaque_forward_scene.update_type_batch_count = 1;
        light_debug_batches[0].order = 0;
        light_debug_batches[1].order = 1;
        light_debug_batches[2].order = 2;
        update_type_batch.order = 3;
        auto update_after_light = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(update_after_light);
        std::array<std::uint16_t, 32 * 32 * 4>
            update_after_light_pixels{};
        REQUIRE(update_after_light->colorTexture(0)->readback(
            *device, 0, 0, {}, update_after_light_pixels.data(),
            32 * 8, &error));

        update_type_batch.order = 0;
        light_debug_batches[0].order = 1;
        light_debug_batches[1].order = 2;
        light_debug_batches[2].order = 3;
        auto light_after_update = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(light_after_update);
        std::array<std::uint16_t, 32 * 32 * 4>
            light_after_update_pixels{};
        REQUIRE(light_after_update->colorTexture(0)->readback(
            *device, 0, 0, {}, light_after_update_pixels.data(),
            32 * 8, &error));
        CHECK(update_after_light_pixels[center + 1] !=
              light_after_update_pixels[center + 1]);

        update_type_batch.order = 2;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world render-debug ordering is invalid");
        error.clear();
        opaque_forward_scene.update_type_batches = nullptr;
        opaque_forward_scene.update_type_batch_count = 0;
        opaque_forward_scene.light_debug_batches = nullptr;
        opaque_forward_scene.light_debug_batch_count = 0;
        auto no_light_debug = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(no_light_debug);
        light_debug_pixels.fill(0xffffu);
        light_debug_depth.fill(-1.f);
        REQUIRE(no_light_debug->colorTexture(0)->readback(
            *device, 0, 0, {}, light_debug_pixels.data(), 32 * 8,
            &error));
        REQUIRE(no_light_debug->depthStencilTexture()->readback(
            *device, 0, 0, {}, light_debug_depth.data(),
            32 * sizeof(float), &error));
        CHECK(light_debug_pixels == opaque_forward_pixels);
        CHECK(light_debug_depth == opaque_forward_depth);

        // Develop > Reflection Probes draws one-pixel neighbor links for
        // relevant probes: orange unless both endpoints own viewer objects,
        // yellow when both do. The ordered stream inherits read/write depth.
        std::array<ALMetalWorldReflectionProbeLinkVertex, 4>
            reflection_probe_links{};
        const float reflection_probe_link_positions[4][3] = {
            {-0.84375f, 0.84375f, 0.f},
            {-0.34375f, 0.84375f, 0.f},
            {0.34375f, 0.84375f, 0.f},
            {0.84375f, 0.84375f, 0.f},
        };
        for (std::size_t vertex = 0;
             vertex < reflection_probe_links.size(); ++vertex)
        {
            std::memcpy(
                reflection_probe_links[vertex].position,
                reflection_probe_link_positions[vertex],
                sizeof(reflection_probe_link_positions[vertex]));
            reflection_probe_links[vertex].color[0] = 1.f;
            reflection_probe_links[vertex].color[1] =
                vertex < 2 ? 0.5f : 1.f;
            reflection_probe_links[vertex].color[2] = 0.f;
        }
        opaque_forward_scene.reflection_probe_links =
            reflection_probe_links.data();
        opaque_forward_scene.reflection_probe_link_vertex_count =
            reflection_probe_links.size();
        for (std::size_t axis = 0; axis < 4; ++axis)
        {
            opaque_forward_scene
                .reflection_probe_link_modelview_projection[
                    axis * 4 + axis] = 1.f;
        }

        opaque_forward_scene.reflection_probe_links = nullptr;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world reflection-probe link storage is invalid");
        opaque_forward_scene.reflection_probe_links =
            reflection_probe_links.data();
        opaque_forward_scene.reflection_probe_link_vertex_count = 3;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world reflection-probe link storage is invalid");
        opaque_forward_scene.reflection_probe_link_vertex_count =
            reflection_probe_links.size();
        reflection_probe_links[0].color[1] = 0.25f;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world reflection-probe link data is invalid");
        reflection_probe_links[0].color[1] = 0.5f;
        reflection_probe_links[0].position[0] =
            std::numeric_limits<float>::quiet_NaN();
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world reflection-probe link data is invalid");
        reflection_probe_links[0].position[0] = -0.84375f;
        error.clear();

        auto native_reflection_probe_links =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(native_reflection_probe_links);
        std::array<std::uint16_t, 32 * 32 * 4>
            reflection_probe_link_pixels{};
        std::array<float, 32 * 32> reflection_probe_link_depth{};
        REQUIRE(native_reflection_probe_links->colorTexture(0)->readback(
            *device, 0, 0, {}, reflection_probe_link_pixels.data(),
            32 * 8, &error));
        REQUIRE(native_reflection_probe_links->depthStencilTexture()->readback(
            *device, 0, 0, {}, reflection_probe_link_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        std::size_t orange_link_pixels = 0;
        std::size_t yellow_link_pixels = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            const bool orange =
                reflection_probe_link_pixels[offset + 0] == 0x3c00 &&
                reflection_probe_link_pixels[offset + 1] == 0x3800 &&
                reflection_probe_link_pixels[offset + 2] == 0u;
            const bool yellow =
                reflection_probe_link_pixels[offset + 0] == 0x3c00 &&
                reflection_probe_link_pixels[offset + 1] == 0x3c00 &&
                reflection_probe_link_pixels[offset + 2] == 0u;
            orange_link_pixels += orange;
            yellow_link_pixels += yellow;
            if (orange || yellow)
            {
                CHECK(reflection_probe_link_pixels[offset + 3] ==
                      opaque_forward_pixels[offset + 3]);
                CHECK(std::abs(
                    reflection_probe_link_depth[pixel] - 0.5f) < 0.0001f);
            }
        }
        CHECK(orange_link_pixels >= 8);
        CHECK(yellow_link_pixels >= 8);

        for (ALMetalWorldReflectionProbeLinkVertex& vertex :
             reflection_probe_links)
        {
            vertex.position[0] *= 0.2f;
            vertex.position[1] = 0.f;
            vertex.position[2] = 0.75f;
        }
        auto hidden_reflection_probe_links =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(hidden_reflection_probe_links);
        reflection_probe_link_pixels.fill(0xffffu);
        reflection_probe_link_depth.fill(-1.f);
        REQUIRE(hidden_reflection_probe_links->colorTexture(0)->readback(
            *device, 0, 0, {}, reflection_probe_link_pixels.data(),
            32 * 8, &error));
        REQUIRE(hidden_reflection_probe_links->depthStencilTexture()->readback(
            *device, 0, 0, {}, reflection_probe_link_depth.data(),
            32 * sizeof(float), &error));
        const std::size_t covered_center = (16 * 32 + 16) * 4;
        CHECK(reflection_probe_link_pixels[covered_center + 0] ==
              opaque_forward_pixels[covered_center + 0]);
        CHECK(reflection_probe_link_pixels[covered_center + 1] ==
              opaque_forward_pixels[covered_center + 1]);
        CHECK(reflection_probe_link_pixels[covered_center + 2] ==
              opaque_forward_pixels[covered_center + 2]);
        CHECK(std::abs(
            reflection_probe_link_depth[16 * 32 + 16] -
            opaque_forward_depth[16 * 32 + 16]) < 0.0001f);

        opaque_forward_scene.gbuffer = reverse_coverage_result.get();
        opaque_forward_scene.reverse_z = true;
        for (ALMetalWorldReflectionProbeLinkVertex& vertex :
             reflection_probe_links)
        {
            vertex.position[2] = 0.9f;
        }
        auto reverse_reflection_probe_links =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_reflection_probe_links);
        reflection_probe_link_pixels.fill(0xffffu);
        reflection_probe_link_depth.fill(-1.f);
        REQUIRE(
            reverse_reflection_probe_links->colorTexture(0)->readback(
                *device, 0, 0, {}, reflection_probe_link_pixels.data(),
                32 * 8, &error));
        REQUIRE(
            reverse_reflection_probe_links->depthStencilTexture()->readback(
                *device, 0, 0, {}, reflection_probe_link_depth.data(),
                32 * sizeof(float), &error));
        std::size_t reverse_reflection_probe_link_changed = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            const bool changed =
                reflection_probe_link_pixels[offset + 0] !=
                    reverse_agent_target_baseline_pixels[offset + 0] ||
                reflection_probe_link_pixels[offset + 1] !=
                    reverse_agent_target_baseline_pixels[offset + 1] ||
                reflection_probe_link_pixels[offset + 2] !=
                    reverse_agent_target_baseline_pixels[offset + 2];
            reverse_reflection_probe_link_changed += changed;
            if (changed)
            {
                CHECK(reflection_probe_link_pixels[offset + 3] ==
                      reverse_agent_target_baseline_pixels[offset + 3]);
                CHECK(std::abs(
                    reflection_probe_link_depth[pixel] - 0.9f) < 0.0001f);
            }
        }
        CHECK(reverse_reflection_probe_link_changed >= 4);
        CHECK(reflection_probe_link_depth !=
              reverse_agent_target_baseline_depth);

        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.reverse_z = false;
        opaque_forward_scene.reflection_probe_links = nullptr;
        opaque_forward_scene.reflection_probe_link_vertex_count = 0;
        auto no_reflection_probe_links =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(no_reflection_probe_links);
        reflection_probe_link_pixels.fill(0xffffu);
        reflection_probe_link_depth.fill(-1.f);
        REQUIRE(no_reflection_probe_links->colorTexture(0)->readback(
            *device, 0, 0, {}, reflection_probe_link_pixels.data(),
            32 * 8, &error));
        REQUIRE(no_reflection_probe_links->depthStencilTexture()->readback(
            *device, 0, 0, {}, reflection_probe_link_depth.data(),
            32 * sizeof(float), &error));
        CHECK(reflection_probe_link_pixels == opaque_forward_pixels);
        CHECK(reflection_probe_link_depth == opaque_forward_depth);

        // Develop > Shadow Frusta is a read-only-depth, alpha-blended owner
        // between probe debug display and Wind Vectors. The exact source
        // topology is four optional eight-pixel point clouds, eight mandatory
        // line batches, then three volume strips for each non-empty cascade.
        std::vector<ALMetalWorldShadowFrustumVertex>
            shadow_frustum_vertices;
        std::vector<ALMetalWorldShadowFrustumBatch>
            shadow_frustum_batches;
        const float shadow_colors[4][3] = {
            {1.f, 0.f, 0.f},
            {0.f, 1.f, 0.f},
            {0.f, 0.f, 1.f},
            {1.f, 0.f, 1.f},
        };
        const auto append_shadow_vertex = [&](
            float x, float y, float z, std::size_t cascade, float alpha)
        {
            ALMetalWorldShadowFrustumVertex vertex;
            vertex.position[0] = x;
            vertex.position[1] = y;
            vertex.position[2] = z;
            vertex.color[0] = shadow_colors[cascade][0];
            vertex.color[1] = shadow_colors[cascade][1];
            vertex.color[2] = shadow_colors[cascade][2];
            vertex.color[3] = alpha;
            shadow_frustum_vertices.push_back(vertex);
        };
        const auto begin_shadow_batch = [&]()
        {
            ALMetalWorldShadowFrustumBatch batch;
            batch.first_vertex = static_cast<std::uint32_t>(
                shadow_frustum_vertices.size());
            return batch;
        };
        const auto end_shadow_batch = [&](
            ALMetalWorldShadowFrustumBatch batch)
        {
            batch.vertex_count = static_cast<std::uint32_t>(
                shadow_frustum_vertices.size() - batch.first_vertex);
            shadow_frustum_batches.push_back(batch);
        };

        auto point_batch = begin_shadow_batch();
        point_batch.cascade = 0;
        point_batch.kind =
            ALMetalWorldShadowFrustumKind::cascade_points;
        append_shadow_vertex(-0.75f, 0.75f, 0.f, 0, 1.f);
        end_shadow_batch(point_batch);
        for (std::size_t cascade = 0; cascade < 4; ++cascade)
        {
            const float y = 0.65f - static_cast<float>(cascade) * 0.35f;
            auto extent_batch = begin_shadow_batch();
            extent_batch.cascade = static_cast<std::uint32_t>(cascade);
            extent_batch.kind =
                ALMetalWorldShadowFrustumKind::cascade_extent;
            for (std::size_t line = 0; line < 12; ++line)
            {
                append_shadow_vertex(0.2f, y, 0.f, cascade, 1.f);
                append_shadow_vertex(0.8f, y, 0.f, cascade, 1.f);
            }
            end_shadow_batch(extent_batch);

            auto outline_batch = begin_shadow_batch();
            outline_batch.cascade = static_cast<std::uint32_t>(cascade);
            outline_batch.kind =
                ALMetalWorldShadowFrustumKind::cascade_outline;
            for (std::size_t line = 0; line < 12; ++line)
            {
                append_shadow_vertex(0.2f, y + 0.03f, 0.f,
                                     cascade, 1.f);
                append_shadow_vertex(0.8f, y + 0.03f, 0.f,
                                     cascade, 1.f);
            }
            end_shadow_batch(outline_batch);
        }

        const float volume_positions[10][2] = {
            {-0.8f, -0.8f}, {-0.8f, -0.2f},
            {-0.2f, -0.8f}, {-0.2f, -0.2f},
            {-0.8f, -0.8f}, {-0.8f, -0.2f},
            {-0.2f, -0.8f}, {-0.2f, -0.2f},
            {-0.8f, -0.8f}, {-0.8f, -0.2f},
        };
        auto volume_sides = begin_shadow_batch();
        volume_sides.cascade = 0;
        volume_sides.kind = ALMetalWorldShadowFrustumKind::volume_sides;
        for (const auto& position : volume_positions)
        {
            append_shadow_vertex(
                position[0], position[1], -0.5f, 0, 0.1f);
        }
        end_shadow_batch(volume_sides);
        const float face_positions[4][2] = {
            {-0.8f, -0.8f}, {-0.8f, -0.2f},
            {-0.2f, -0.8f}, {-0.2f, -0.2f},
        };
        auto volume_near = begin_shadow_batch();
        volume_near.cascade = 0;
        volume_near.kind = ALMetalWorldShadowFrustumKind::volume_near;
        for (const auto& position : face_positions)
        {
            append_shadow_vertex(
                position[0], position[1], -0.5f, 0, 0.1f);
        }
        end_shadow_batch(volume_near);
        auto volume_far = begin_shadow_batch();
        volume_far.cascade = 0;
        volume_far.kind = ALMetalWorldShadowFrustumKind::volume_far;
        for (const auto& position : face_positions)
        {
            append_shadow_vertex(
                position[0], position[1], -0.5f, 0, 0.1f);
        }
        end_shadow_batch(volume_far);

        opaque_forward_scene.shadow_frustum_vertices =
            shadow_frustum_vertices.data();
        opaque_forward_scene.shadow_frustum_vertex_count =
            shadow_frustum_vertices.size();
        opaque_forward_scene.shadow_frustum_batches =
            shadow_frustum_batches.data();
        opaque_forward_scene.shadow_frustum_batch_count =
            shadow_frustum_batches.size();
        for (std::size_t axis = 0; axis < 4; ++axis)
        {
            opaque_forward_scene.shadow_frustum_modelview_projection[
                axis * 4 + axis] = 1.f;
        }

        opaque_forward_scene.shadow_frustum_vertices = nullptr;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world shadow-frustum storage is invalid");
        opaque_forward_scene.shadow_frustum_vertices =
            shadow_frustum_vertices.data();
        shadow_frustum_vertices[0].position[0] =
            std::numeric_limits<float>::quiet_NaN();
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world shadow-frustum data is invalid");
        shadow_frustum_vertices[0].position[0] = -0.75f;
        ++shadow_frustum_batches[1].first_vertex;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world shadow-frustum topology is invalid");
        --shadow_frustum_batches[1].first_vertex;
        shadow_frustum_vertices[0].color[3] = 0.1f;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world shadow-frustum topology is invalid");
        shadow_frustum_vertices[0].color[3] = 1.f;
        error.clear();

        auto native_shadow_frusta = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(native_shadow_frusta);
        std::array<std::uint16_t, 32 * 32 * 4> shadow_frustum_pixels{};
        std::array<float, 32 * 32> shadow_frustum_depth{};
        REQUIRE(native_shadow_frusta->colorTexture(0)->readback(
            *device, 0, 0, {}, shadow_frustum_pixels.data(),
            32 * 8, &error));
        REQUIRE(native_shadow_frusta->depthStencilTexture()->readback(
            *device, 0, 0, {}, shadow_frustum_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK(shadow_frustum_depth == opaque_forward_depth);
        std::size_t red_pixels = 0;
        std::size_t green_pixels = 0;
        std::size_t blue_pixels = 0;
        std::size_t magenta_pixels = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            const bool red =
                shadow_frustum_pixels[offset + 0] == 0x3c00 &&
                shadow_frustum_pixels[offset + 1] == 0u &&
                shadow_frustum_pixels[offset + 2] == 0u;
            const bool green =
                shadow_frustum_pixels[offset + 0] == 0u &&
                shadow_frustum_pixels[offset + 1] == 0x3c00 &&
                shadow_frustum_pixels[offset + 2] == 0u;
            const bool blue =
                shadow_frustum_pixels[offset + 0] == 0u &&
                shadow_frustum_pixels[offset + 1] == 0u &&
                shadow_frustum_pixels[offset + 2] == 0x3c00;
            const bool magenta =
                shadow_frustum_pixels[offset + 0] == 0x3c00 &&
                shadow_frustum_pixels[offset + 1] == 0u &&
                shadow_frustum_pixels[offset + 2] == 0x3c00;
            red_pixels += red;
            green_pixels += green;
            blue_pixels += blue;
            magenta_pixels += magenta;
            if (red || green || blue || magenta)
            {
                CHECK(shadow_frustum_pixels[offset + 3] ==
                      opaque_forward_pixels[offset + 3]);
            }
        }
        CHECK(red_pixels >= 32);
        CHECK(green_pixels >= 8);
        CHECK(blue_pixels >= 8);
        CHECK(magenta_pixels >= 8);
        const std::size_t volume_pixel = (8 * 32 + 8) * 4;
        CHECK(shadow_frustum_pixels[volume_pixel + 0] >
              opaque_forward_pixels[volume_pixel + 0]);
        CHECK(shadow_frustum_pixels[volume_pixel + 3] ==
              opaque_forward_pixels[volume_pixel + 3]);

        opaque_forward_scene.gbuffer = reverse_coverage_result.get();
        opaque_forward_scene.reverse_z = true;
        for (ALMetalWorldShadowFrustumVertex& vertex :
             shadow_frustum_vertices)
        {
            vertex.position[2] = 0.9f;
        }
        auto reverse_shadow_frusta = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_shadow_frusta);
        shadow_frustum_pixels.fill(0xffffu);
        shadow_frustum_depth.fill(-1.f);
        REQUIRE(reverse_shadow_frusta->colorTexture(0)->readback(
            *device, 0, 0, {}, shadow_frustum_pixels.data(),
            32 * 8, &error));
        REQUIRE(reverse_shadow_frusta->depthStencilTexture()->readback(
            *device, 0, 0, {}, shadow_frustum_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK(shadow_frustum_depth ==
              reverse_agent_target_baseline_depth);
        std::size_t reverse_shadow_frustum_changed = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            reverse_shadow_frustum_changed +=
                shadow_frustum_pixels[offset + 0] !=
                    reverse_agent_target_baseline_pixels[offset + 0] ||
                shadow_frustum_pixels[offset + 1] !=
                    reverse_agent_target_baseline_pixels[offset + 1] ||
                shadow_frustum_pixels[offset + 2] !=
                    reverse_agent_target_baseline_pixels[offset + 2];
            CHECK(shadow_frustum_pixels[offset + 3] ==
                  reverse_agent_target_baseline_pixels[offset + 3]);
        }
        CHECK(reverse_shadow_frustum_changed >= 32);

        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.reverse_z = false;
        opaque_forward_scene.shadow_frustum_vertices = nullptr;
        opaque_forward_scene.shadow_frustum_vertex_count = 0;
        opaque_forward_scene.shadow_frustum_batches = nullptr;
        opaque_forward_scene.shadow_frustum_batch_count = 0;
        auto no_shadow_frusta = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(no_shadow_frusta);
        shadow_frustum_pixels.fill(0xffffu);
        shadow_frustum_depth.fill(-1.f);
        REQUIRE(no_shadow_frusta->colorTexture(0)->readback(
            *device, 0, 0, {}, shadow_frustum_pixels.data(),
            32 * 8, &error));
        REQUIRE(no_shadow_frusta->depthStencilTexture()->readback(
            *device, 0, 0, {}, shadow_frustum_depth.data(),
            32 * sizeof(float), &error));
        CHECK(shadow_frustum_pixels == opaque_forward_pixels);
        CHECK(shadow_frustum_depth == opaque_forward_depth);

        // Develop > Wind Vectors follows the probe-volume display and emits
        // one-pixel green lattice points plus red line segments. It inherits
        // the ambient GL_LEQUAL read/write depth state (GEQUAL under
        // reverse-Z), disabled blending and an RGB-only color mask.
        std::array<ALMetalWorldWindVectorVertex, 2> wind_points{};
        std::array<ALMetalWorldWindVectorVertex, 4> wind_lines{};
        wind_points[0].position[0] = 0.84375f;
        wind_points[0].position[1] = 0.84375f;
        wind_points[0].color[0] = 0.f;
        wind_points[0].color[1] = 1.f;
        wind_points[0].color[2] = 0.f;
        wind_points[1].position[0] = 0.03125f;
        wind_points[1].position[1] = 0.03125f;
        wind_points[1].position[2] = 0.75f;
        wind_points[1].color[0] = 0.f;
        wind_points[1].color[1] = 1.f;
        wind_points[1].color[2] = 0.f;
        wind_lines[0].position[0] = -0.84375f;
        wind_lines[0].position[1] = 0.84375f;
        wind_lines[1].position[0] = -0.34375f;
        wind_lines[1].position[1] = 0.84375f;
        wind_lines[2].position[0] = -0.21875f;
        wind_lines[2].position[1] = 0.03125f;
        wind_lines[2].position[2] = 0.75f;
        wind_lines[3].position[0] = 0.21875f;
        wind_lines[3].position[1] = 0.03125f;
        wind_lines[3].position[2] = 0.75f;
        for (ALMetalWorldWindVectorVertex& vertex : wind_lines)
        {
            vertex.color[0] = 1.f;
            vertex.color[1] = 0.f;
            vertex.color[2] = 0.f;
        }
        opaque_forward_scene.wind_vector_points = wind_points.data();
        opaque_forward_scene.wind_vector_point_count = wind_points.size();
        opaque_forward_scene.wind_vector_lines = wind_lines.data();
        opaque_forward_scene.wind_vector_line_vertex_count =
            wind_lines.size();
        for (std::size_t axis = 0; axis < 4; ++axis)
        {
            opaque_forward_scene.wind_vector_modelview_projection[
                axis * 4 + axis] = 1.f;
        }

        opaque_forward_scene.wind_vector_points = nullptr;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world wind-vector storage is invalid");
        opaque_forward_scene.wind_vector_points = wind_points.data();
        opaque_forward_scene.wind_vector_line_vertex_count = 3;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world wind-vector storage is invalid");
        opaque_forward_scene.wind_vector_line_vertex_count =
            wind_lines.size();
        wind_lines[0].position[0] =
            std::numeric_limits<float>::quiet_NaN();
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world wind-vector data is non-finite");
        wind_lines[0].position[0] = -0.84375f;
        error.clear();

        auto native_wind_vectors = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(native_wind_vectors);
        std::array<std::uint16_t, 32 * 32 * 4> wind_pixels{};
        std::array<float, 32 * 32> wind_depth{};
        REQUIRE(native_wind_vectors->colorTexture(0)->readback(
            *device, 0, 0, {}, wind_pixels.data(), 32 * 8, &error));
        REQUIRE(native_wind_vectors->depthStencilTexture()->readback(
            *device, 0, 0, {}, wind_depth.data(), 32 * sizeof(float),
            &error));
        INFO(error);
        std::size_t wind_green_pixels = 0;
        std::size_t wind_red_pixels = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            const bool changed =
                wind_pixels[offset + 0] !=
                    opaque_forward_pixels[offset + 0] ||
                wind_pixels[offset + 1] !=
                    opaque_forward_pixels[offset + 1] ||
                wind_pixels[offset + 2] !=
                    opaque_forward_pixels[offset + 2];
            wind_green_pixels += changed &&
                wind_pixels[offset + 0] == 0u &&
                wind_pixels[offset + 1] == 0x3c00 &&
                wind_pixels[offset + 2] == 0u;
            wind_red_pixels += changed &&
                wind_pixels[offset + 0] == 0x3c00 &&
                wind_pixels[offset + 1] == 0u &&
                wind_pixels[offset + 2] == 0u;
            if (changed)
            {
                CHECK(wind_pixels[offset + 3] ==
                      opaque_forward_pixels[offset + 3]);
                CHECK(std::abs(wind_depth[pixel] - 0.5f) < 0.0001f);
            }
        }
        CHECK(wind_green_pixels == 1);
        CHECK(wind_red_pixels >= 7);
        CHECK(wind_pixels[center + 0] == opaque_forward_pixels[center + 0]);
        CHECK(wind_pixels[center + 1] == opaque_forward_pixels[center + 1]);
        CHECK(wind_pixels[center + 2] == opaque_forward_pixels[center + 2]);
        CHECK(std::abs(wind_depth[16 * 32 + 16] -
                       opaque_forward_depth[16 * 32 + 16]) < 0.0001f);

        // Shadow Frusta precedes Wind Vectors in renderDebug. Collide the
        // one-pixel green wind point with the eight-pixel red cascade-point
        // footprint: green must win only at that pixel while retained red
        // remains around it. Depth-reject the later shadow batches so the
        // ordering assertion isolates these two owners.
        for (ALMetalWorldShadowFrustumVertex& vertex :
             shadow_frustum_vertices)
        {
            vertex.position[2] = 1.f;
        }
        shadow_frustum_vertices[0].position[0] = 0.84375f;
        shadow_frustum_vertices[0].position[1] = 0.84375f;
        shadow_frustum_vertices[0].position[2] = 0.f;
        for (std::size_t vertex = 1;
             vertex < shadow_frustum_vertices.size(); ++vertex)
        {
            shadow_frustum_vertices[vertex].position[0] = 2.f;
            shadow_frustum_vertices[vertex].position[1] = 2.f;
        }
        opaque_forward_scene.shadow_frustum_vertices =
            shadow_frustum_vertices.data();
        opaque_forward_scene.shadow_frustum_vertex_count =
            shadow_frustum_vertices.size();
        opaque_forward_scene.shadow_frustum_batches =
            shadow_frustum_batches.data();
        opaque_forward_scene.shadow_frustum_batch_count =
            shadow_frustum_batches.size();
        auto shadow_then_wind = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(shadow_then_wind);
        wind_pixels.fill(0xffffu);
        REQUIRE(shadow_then_wind->colorTexture(0)->readback(
            *device, 0, 0, {}, wind_pixels.data(), 32 * 8, &error));
        INFO(error);
        std::size_t shadow_wind_green_pixels = 0;
        std::size_t shadow_wind_red_pixels = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            const bool changed =
                wind_pixels[offset + 0] !=
                    opaque_forward_pixels[offset + 0] ||
                wind_pixels[offset + 1] !=
                    opaque_forward_pixels[offset + 1] ||
                wind_pixels[offset + 2] !=
                    opaque_forward_pixels[offset + 2];
            const bool green = changed &&
                wind_pixels[offset + 0] == 0u &&
                wind_pixels[offset + 1] == 0x3c00 &&
                wind_pixels[offset + 2] == 0u;
            const bool red = changed &&
                wind_pixels[offset + 0] == 0x3c00 &&
                wind_pixels[offset + 1] == 0u &&
                wind_pixels[offset + 2] == 0u;
            shadow_wind_green_pixels += green;
            shadow_wind_red_pixels += red;
            if (green || red)
            {
                CHECK(wind_pixels[offset + 3] ==
                      opaque_forward_pixels[offset + 3]);
            }
        }
        CHECK(shadow_wind_green_pixels == 1);
        CHECK(shadow_wind_red_pixels >= 7);
        opaque_forward_scene.shadow_frustum_vertices = nullptr;
        opaque_forward_scene.shadow_frustum_vertex_count = 0;
        opaque_forward_scene.shadow_frustum_batches = nullptr;
        opaque_forward_scene.shadow_frustum_batch_count = 0;

        opaque_forward_scene.gbuffer = reverse_coverage_result.get();
        opaque_forward_scene.reverse_z = true;
        opaque_forward_scene.wind_vector_points = nullptr;
        opaque_forward_scene.wind_vector_point_count = 0;
        opaque_forward_scene.wind_vector_lines = nullptr;
        opaque_forward_scene.wind_vector_line_vertex_count = 0;
        auto reverse_wind_baseline = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_wind_baseline);
        std::array<std::uint16_t, 32 * 32 * 4>
            reverse_wind_baseline_pixels{};
        std::array<float, 32 * 32> reverse_wind_baseline_depth{};
        REQUIRE(reverse_wind_baseline->colorTexture(0)->readback(
            *device, 0, 0, {}, reverse_wind_baseline_pixels.data(),
            32 * 8, &error));
        REQUIRE(reverse_wind_baseline->depthStencilTexture()->readback(
            *device, 0, 0, {}, reverse_wind_baseline_depth.data(),
            32 * sizeof(float), &error));
        for (ALMetalWorldWindVectorVertex& point : wind_points)
        {
            point.position[2] = 0.5f;
        }
        wind_points[1].position[2] = 0.1f;
        for (ALMetalWorldWindVectorVertex& vertex : wind_lines)
        {
            vertex.position[2] = 0.5f;
        }
        wind_lines[2].position[2] = 0.1f;
        wind_lines[3].position[2] = 0.1f;
        opaque_forward_scene.wind_vector_points = wind_points.data();
        opaque_forward_scene.wind_vector_point_count = wind_points.size();
        opaque_forward_scene.wind_vector_lines = wind_lines.data();
        opaque_forward_scene.wind_vector_line_vertex_count =
            wind_lines.size();
        auto reverse_wind_vectors = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_wind_vectors);
        std::array<std::uint16_t, 32 * 32 * 4> reverse_wind_pixels{};
        std::array<float, 32 * 32> reverse_wind_depth{};
        REQUIRE(reverse_wind_vectors->colorTexture(0)->readback(
            *device, 0, 0, {}, reverse_wind_pixels.data(), 32 * 8,
            &error));
        REQUIRE(reverse_wind_vectors->depthStencilTexture()->readback(
            *device, 0, 0, {}, reverse_wind_depth.data(),
            32 * sizeof(float), &error));
        std::size_t reverse_wind_green_pixels = 0;
        std::size_t reverse_wind_red_pixels = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t offset = pixel * 4;
            const bool changed =
                reverse_wind_pixels[offset + 0] !=
                    reverse_wind_baseline_pixels[offset + 0] ||
                reverse_wind_pixels[offset + 1] !=
                    reverse_wind_baseline_pixels[offset + 1] ||
                reverse_wind_pixels[offset + 2] !=
                    reverse_wind_baseline_pixels[offset + 2];
            reverse_wind_green_pixels += changed &&
                reverse_wind_pixels[offset + 0] == 0u &&
                reverse_wind_pixels[offset + 1] == 0x3c00 &&
                reverse_wind_pixels[offset + 2] == 0u;
            reverse_wind_red_pixels += changed &&
                reverse_wind_pixels[offset + 0] == 0x3c00 &&
                reverse_wind_pixels[offset + 1] == 0u &&
                reverse_wind_pixels[offset + 2] == 0u;
            if (changed)
            {
                CHECK(reverse_wind_pixels[offset + 3] ==
                      reverse_wind_baseline_pixels[offset + 3]);
                CHECK(std::abs(reverse_wind_depth[pixel] - 0.5f) <
                      0.0001f);
            }
        }
        CHECK(reverse_wind_green_pixels == 1);
        CHECK(reverse_wind_red_pixels >= 7);
        CHECK(reverse_wind_pixels[center + 0] ==
              reverse_wind_baseline_pixels[center + 0]);
        CHECK(reverse_wind_pixels[center + 1] ==
              reverse_wind_baseline_pixels[center + 1]);
        CHECK(reverse_wind_pixels[center + 2] ==
              reverse_wind_baseline_pixels[center + 2]);
        CHECK(std::abs(reverse_wind_depth[16 * 32 + 16] -
                       reverse_wind_baseline_depth[16 * 32 + 16]) <
              0.0001f);

        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.reverse_z = false;
        opaque_forward_scene.wind_vector_points = nullptr;
        opaque_forward_scene.wind_vector_point_count = 0;
        opaque_forward_scene.wind_vector_lines = nullptr;
        opaque_forward_scene.wind_vector_line_vertex_count = 0;
        auto no_wind_vectors = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(no_wind_vectors);
        wind_pixels.fill(0xffffu);
        wind_depth.fill(-1.f);
        REQUIRE(no_wind_vectors->colorTexture(0)->readback(
            *device, 0, 0, {}, wind_pixels.data(), 32 * 8, &error));
        REQUIRE(no_wind_vectors->depthStencilTexture()->readback(
            *device, 0, 0, {}, wind_depth.data(), 32 * sizeof(float),
            &error));
        CHECK(wind_pixels == opaque_forward_pixels);
        CHECK(wind_depth == opaque_forward_depth);

        // The reflection-probe volume developer display is an independent
        // full-screen owner inside renderDebug. It reconstructs eye-space
        // scene depth, shows manual sphere/box intersections in yellow when
        // visible and distance-faded blue when hidden, then leaves scene
        // coverage and depth untouched. Identity projection makes the same
        // covered texel reconstruct to z=0.25 in both depth conventions.
        auto probe_volume_constants =
            std::make_unique<ALMetalWorldReflectionProbeConstants>();
        probe_volume_constants->config[0] = 2.f;
        probe_volume_constants->ref_index[1][3] = 1;
        probe_volume_constants->ref_sphere[1][3] = 0.5f;
        opaque_forward_scene.reflection_probe_volume_constants =
            probe_volume_constants.get();
        for (std::size_t axis = 0; axis < 4; ++axis)
        {
            opaque_forward_scene.reflection_probe_volume_inverse_projection[
                axis * 4 + axis] = 1.f;
        }

        probe_volume_constants->config[0] = 257.f;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world reflection-probe volume overlay is invalid");
        probe_volume_constants->config[0] = 2.f;
        opaque_forward_scene.reflection_probe_volume_inverse_projection[0] =
            std::numeric_limits<float>::quiet_NaN();
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world reflection-probe volume overlay is invalid");
        opaque_forward_scene.reflection_probe_volume_inverse_projection[0] =
            1.f;
        error.clear();

        auto sphere_probe_volume = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(sphere_probe_volume);
        std::array<std::uint16_t, 32 * 32 * 4> sphere_probe_pixels{};
        std::array<float, 32 * 32> sphere_probe_depth{};
        REQUIRE(sphere_probe_volume->colorTexture(0)->readback(
            *device, 0, 0, {}, sphere_probe_pixels.data(), 32 * 8,
            &error));
        REQUIRE(sphere_probe_volume->depthStencilTexture()->readback(
            *device, 0, 0, {}, sphere_probe_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK(sphere_probe_pixels[0] == opaque_forward_pixels[0]);
        CHECK(sphere_probe_pixels[1] > opaque_forward_pixels[1]);
        CHECK(sphere_probe_pixels[2] < opaque_forward_pixels[2]);
        CHECK(sphere_probe_pixels[3] == opaque_forward_pixels[3]);
        CHECK(sphere_probe_pixels[center + 0] <
              opaque_forward_pixels[center + 0]);
        CHECK(sphere_probe_pixels[center + 1] <
              opaque_forward_pixels[center + 1]);
        CHECK(sphere_probe_pixels[center + 2] >
              opaque_forward_pixels[center + 2]);
        CHECK(sphere_probe_pixels[center + 3] ==
              opaque_forward_pixels[center + 3]);
        CHECK(sphere_probe_depth == opaque_forward_depth);

        opaque_forward_scene.gbuffer = reverse_coverage_result.get();
        opaque_forward_scene.reverse_z = true;
        auto reverse_sphere_probe_volume =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_sphere_probe_volume);
        std::array<std::uint16_t, 32 * 32 * 4>
            reverse_sphere_probe_pixels{};
        REQUIRE(reverse_sphere_probe_volume->colorTexture(0)->readback(
            *device, 0, 0, {}, reverse_sphere_probe_pixels.data(),
            32 * 8, &error));
        INFO(error);
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(reverse_sphere_probe_pixels[channel] ==
                  sphere_probe_pixels[channel]);
            CHECK(reverse_sphere_probe_pixels[center + channel] ==
                  sphere_probe_pixels[center + channel]);
        }
        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.reverse_z = false;

        probe_volume_constants->ref_index[1][3] = -1;
        probe_volume_constants->ref_sphere[1][3] = 0.f;
        for (std::size_t axis = 0; axis < 4; ++axis)
        {
            probe_volume_constants->ref_box[1][axis * 4 + axis] = 1.f;
        }
        auto box_probe_volume = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(box_probe_volume);
        std::array<std::uint16_t, 32 * 32 * 4> box_probe_pixels{};
        REQUIRE(box_probe_volume->colorTexture(0)->readback(
            *device, 0, 0, {}, box_probe_pixels.data(), 32 * 8, &error));
        INFO(error);
        CHECK(box_probe_pixels[1] > opaque_forward_pixels[1]);
        CHECK(box_probe_pixels[2] < opaque_forward_pixels[2]);
        CHECK(box_probe_pixels[center + 0] <
              opaque_forward_pixels[center + 0]);
        CHECK(box_probe_pixels[center + 2] >
              opaque_forward_pixels[center + 2]);
        CHECK(box_probe_pixels[center + 3] ==
              opaque_forward_pixels[center + 3]);
        CHECK(box_probe_pixels[center + 2] !=
              sphere_probe_pixels[center + 2]);

        probe_volume_constants->ref_index[1][3] = 0;
        auto automatic_probe_volume = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(automatic_probe_volume);
        std::array<std::uint16_t, 32 * 32 * 4> automatic_probe_pixels{};
        REQUIRE(automatic_probe_volume->colorTexture(0)->readback(
            *device, 0, 0, {}, automatic_probe_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(automatic_probe_pixels == opaque_forward_pixels);
        opaque_forward_scene.reflection_probe_volume_constants = nullptr;

        // The Develop far-plane overlay depth-tests nearer orange columns
        // against farther cyan columns in a private target, then RGB-only
        // composites over the world. Use one overlapping pair and one exposed
        // far column so depth order, coverage, destination alpha and retained
        // scene depth are independently visible.
        std::array<ALMetalWorldFarPlaneOverlayColumn, 3> overlay_columns{};
        for (ALMetalWorldFarPlaneOverlayColumn& column : overlay_columns)
        {
            column.half_extent[0] = 0.2f;
            column.half_extent[1] = 0.2f;
            column.half_extent[2] = 0.05f;
        }
        overlay_columns[0].center[0] = -0.5f;
        overlay_columns[0].center[2] = -0.5f;
        overlay_columns[0].color[0] = 1.f;
        overlay_columns[0].color[1] = 0.5f;
        overlay_columns[0].color[2] = 0.f;
        overlay_columns[1].center[0] = -0.5f;
        overlay_columns[1].center[2] = 0.5f;
        overlay_columns[1].color[0] = 0.f;
        overlay_columns[1].color[1] = 0.8f;
        overlay_columns[1].color[2] = 1.f;
        overlay_columns[2] = overlay_columns[1];
        overlay_columns[2].center[0] = 0.5f;
        opaque_forward_scene.far_plane_overlay_columns =
            overlay_columns.data();
        opaque_forward_scene.far_plane_overlay_column_count =
            overlay_columns.size();
        opaque_forward_scene.far_plane_overlay_near_count = 1;
        for (std::size_t axis = 0; axis < 4; ++axis)
        {
            opaque_forward_scene.far_plane_overlay_modelview_projection[
                axis * 4 + axis] = 1.f;
        }

        opaque_forward_scene.far_plane_overlay_columns = nullptr;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world far-plane overlay storage is invalid");
        opaque_forward_scene.far_plane_overlay_columns =
            overlay_columns.data();
        opaque_forward_scene.far_plane_overlay_near_count = 0;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world far-plane overlay storage is invalid");
        opaque_forward_scene.far_plane_overlay_near_count = 1;
        overlay_columns[0].color[0] =
            std::numeric_limits<float>::quiet_NaN();
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world far-plane overlay data is invalid");
        overlay_columns[0].color[0] = 1.f;
        error.clear();

        auto native_far_plane_overlay = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(native_far_plane_overlay);
        std::array<std::uint16_t, 32 * 32 * 4> overlay_pixels{};
        std::array<float, 32 * 32> overlay_depth{};
        REQUIRE(native_far_plane_overlay->colorTexture(0)->readback(
            *device, 0, 0, {}, overlay_pixels.data(), 32 * 8, &error));
        REQUIRE(native_far_plane_overlay->depthStencilTexture()->readback(
            *device, 0, 0, {}, overlay_depth.data(), 32 * sizeof(float),
            &error));
        INFO(error);
        const std::size_t near_overlay = (16 * 32 + 8) * 4;
        const std::size_t far_overlay = (16 * 32 + 24) * 4;
        CHECK(overlay_pixels[near_overlay + 0] == 0x3c00);
        CHECK(overlay_pixels[near_overlay + 1] == 0x3804);
        CHECK(overlay_pixels[near_overlay + 2] == 0u);
        CHECK(overlay_pixels[near_overlay + 3] ==
              opaque_forward_pixels[near_overlay + 3]);
        CHECK(overlay_pixels[far_overlay + 0] == 0u);
        CHECK(overlay_pixels[far_overlay + 1] == 0x3a66);
        CHECK(overlay_pixels[far_overlay + 2] == 0x3c00);
        CHECK(overlay_pixels[far_overlay + 3] ==
              opaque_forward_pixels[far_overlay + 3]);
        CHECK(std::abs(overlay_depth[16 * 32 + 8] -
                       opaque_forward_depth[16 * 32 + 8]) < 0.0001f);
        CHECK(std::abs(overlay_depth[16 * 32 + 24] -
                       opaque_forward_depth[16 * 32 + 24]) < 0.0001f);
        CHECK(overlay_pixels[0] == opaque_forward_pixels[0]);

        opaque_forward_scene.gbuffer = reverse_coverage_result.get();
        opaque_forward_scene.reverse_z = true;
        overlay_columns[0].center[2] = 0.5f;
        overlay_columns[1].center[2] = -0.5f;
        overlay_columns[2].center[2] = -0.5f;
        auto reverse_far_plane_overlay = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_far_plane_overlay);
        overlay_pixels.fill(0xffffu);
        REQUIRE(reverse_far_plane_overlay->colorTexture(0)->readback(
            *device, 0, 0, {}, overlay_pixels.data(), 32 * 8, &error));
        INFO(error);
        CHECK(overlay_pixels[near_overlay + 0] == 0x3c00);
        CHECK(overlay_pixels[near_overlay + 1] == 0x3804);
        CHECK(overlay_pixels[near_overlay + 2] == 0u);
        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.reverse_z = false;
        overlay_columns[0].center[2] = -0.5f;
        overlay_columns[1].center[2] = 0.5f;
        overlay_columns[2].center[2] = 0.5f;

        ALMetalRenderTargetDescriptor overlay_ldr_descriptor;
        overlay_ldr_descriptor.width = 32;
        overlay_ldr_descriptor.height = 32;
        overlay_ldr_descriptor.colors[0].format =
            ALMetalPixelFormat::rgba8_unorm;
        overlay_ldr_descriptor.label =
            "Alchemy far-plane overlay LDR test lighting";
        auto overlay_ldr_lighting = ALMetalRenderTarget::create(
            *device, overlay_ldr_descriptor, &error);
        REQUIRE(overlay_ldr_lighting);
        ALMetalRenderPassConfig overlay_ldr_clear;
        overlay_ldr_clear.colors[0].load = ALMetalLoadAction::clear;
        overlay_ldr_clear.colors[0].store = ALMetalStoreAction::store;
        overlay_ldr_clear.colors[0].clear = {0.25, 0.125, 0.0625, 0.5};
        auto overlay_ldr_pass = overlay_ldr_lighting->makeRenderPass(
            overlay_ldr_clear, &error);
        auto overlay_ldr_command = device->makeCommandBuffer(
            "Alchemy far-plane overlay LDR test clear", &error);
        auto overlay_ldr_encoder = overlay_ldr_pass && overlay_ldr_command
            ? ALMetalRenderEncoder::begin(
                  *overlay_ldr_command, *overlay_ldr_pass,
                  "Alchemy far-plane overlay LDR clear encoder", &error)
            : nullptr;
        REQUIRE(overlay_ldr_encoder);
        REQUIRE(overlay_ldr_encoder->end(&error));
        REQUIRE(overlay_ldr_command->commitAndWait(&error));
        opaque_forward_scene.composed_lighting = overlay_ldr_lighting.get();
        opaque_forward_scene.hdr = false;
        opaque_forward_scene.batches = nullptr;
        opaque_forward_scene.batch_count = 0;
        auto ldr_far_plane_overlay = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(ldr_far_plane_overlay);
        std::array<std::uint8_t, 32 * 32 * 4> overlay_ldr_pixels{};
        REQUIRE(ldr_far_plane_overlay->colorTexture(0)->readback(
            *device, 0, 0, {}, overlay_ldr_pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(overlay_ldr_pixels[near_overlay + 0] == 255u);
        CHECK(overlay_ldr_pixels[near_overlay + 1] == 128u);
        CHECK(overlay_ldr_pixels[near_overlay + 2] == 0u);
        CHECK(overlay_ldr_pixels[near_overlay + 3] == 128u);
        CHECK(overlay_ldr_pixels[far_overlay + 0] == 0u);
        CHECK(overlay_ldr_pixels[far_overlay + 1] == 204u);
        CHECK(overlay_ldr_pixels[far_overlay + 2] == 255u);
        CHECK(overlay_ldr_pixels[far_overlay + 3] == 128u);
        opaque_forward_scene.far_plane_overlay_columns = nullptr;
        opaque_forward_scene.far_plane_overlay_column_count = 0;
        opaque_forward_scene.far_plane_overlay_near_count = 0;
        probe_volume_constants->ref_index[1][3] = 1;
        probe_volume_constants->ref_sphere[1][3] = 0.5f;
        opaque_forward_scene.reflection_probe_volume_constants =
            probe_volume_constants.get();
        auto ldr_probe_volume = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(ldr_probe_volume);
        std::array<std::uint8_t, 32 * 32 * 4> ldr_probe_pixels{};
        REQUIRE(ldr_probe_volume->colorTexture(0)->readback(
            *device, 0, 0, {}, ldr_probe_pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(ldr_probe_pixels[0] == 64u);
        CHECK(ldr_probe_pixels[1] > 32u);
        CHECK(ldr_probe_pixels[2] < 16u);
        CHECK(ldr_probe_pixels[3] == 128u);
        CHECK(ldr_probe_pixels[center + 0] < 64u);
        CHECK(ldr_probe_pixels[center + 2] > 16u);
        CHECK(ldr_probe_pixels[center + 3] == 128u);
        opaque_forward_scene.reflection_probe_volume_constants = nullptr;
        opaque_forward_scene.composed_lighting = final_light.get();
        opaque_forward_scene.hdr = true;
        opaque_forward_scene.batches = &normal_free_fullbright;
        opaque_forward_scene.batch_count = 1;

        // Final-color publication is opt-in because only the continuously
        // advancing main-world path needs to sample combined depth. Prove
        // that the ordinary retained target stays private, then publish the
        // exact HDR color/depth pair with the historical GL row convention.
        std::unique_ptr<ALMetalRenderTarget> ssr_history;
        error.clear();
        CHECK_FALSE(renderer->updateScreenSpaceReflectionHistory(
            *opaque_forward, ssr_history, &error));
        CHECK(error == "Metal world SSR-history source is incompatible");
        opaque_forward_scene.publish_screen_space_reflection_history = true;
        error.clear();
        auto opaque_forward_history_source =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(opaque_forward_history_source);
        CHECK(opaque_forward_history_source->descriptor()
                  .depth_stencil_shader_read);
        REQUIRE(renderer->updateScreenSpaceReflectionHistory(
            *opaque_forward_history_source, ssr_history, &error));
        INFO(error);
        REQUIRE(ssr_history);
        CHECK(ssr_history->descriptor().color_attachment_count == 2);
        CHECK(ssr_history->descriptor().colors[0].format ==
              ALMetalPixelFormat::rg11b10_float);
        CHECK(ssr_history->descriptor().colors[1].format ==
              ALMetalPixelFormat::r32_float);
        std::array<std::uint32_t, 32 * 32> ssr_history_color{};
        std::array<float, 32 * 32> ssr_history_depth{};
        REQUIRE(ssr_history->colorTexture(0)->readback(
            *device, 0, 0, {}, ssr_history_color.data(), 32 * 4,
            &error));
        REQUIRE(ssr_history->colorTexture(1)->readback(
            *device, 0, 0, {}, ssr_history_depth.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(ssr_history_color[7 * 32 + 8] != 0);
        CHECK(std::abs(ssr_history_depth[7 * 32 + 8] - 0.625f) <
              0.0001f);
        CHECK(std::abs(ssr_history_depth[31 * 32] - 1.f) < 0.0001f);
        ALMetalRenderTarget* retained_ssr_history = ssr_history.get();
        REQUIRE(renderer->updateScreenSpaceReflectionHistory(
            *opaque_forward_history_source, ssr_history, &error));
        INFO(error);
        CHECK(ssr_history.get() == retained_ssr_history);
        opaque_forward_scene.publish_screen_space_reflection_history = false;

        // Water exclusion runs before opaque-forward geometry, tests the
        // retained scene depth without writing it, and marks only stencil
        // bit zero. Feed an all-zero water-height cell under a camera and
        // triangle that are both above the surface, then prove the mark by
        // drawing red only where that bit survived the transaction.
        ALMetalTextureDescriptor water_cell_descriptor;
        water_cell_descriptor.format = ALMetalPixelFormat::rg32_float;
        water_cell_descriptor.width = 1;
        water_cell_descriptor.height = 1;
        water_cell_descriptor.storage = ALMetalStorageMode::private_gpu;
        water_cell_descriptor.usage = ALMetalTextureUsage::shader_read;
        water_cell_descriptor.label =
            "Alchemy water-exclusion test height field";
        auto water_cell_map = ALMetalTexture::create(
            *device, water_cell_descriptor, &error);
        INFO(error);
        REQUIRE(water_cell_map);
        const std::array<float, 2> water_cell{{0.f, 1.f}};
        auto water_upload = device->makeCommandBuffer(
            "Alchemy water-exclusion test height upload", &error);
        REQUIRE(water_upload);
        REQUIRE(water_cell_map->upload(
            *water_upload, 0, 0, {}, water_cell.data(),
            sizeof(water_cell), &error));
        REQUIRE(water_upload->commitAndWait(&error));

        const std::array<float, 16> identity{{
            1.f, 0.f, 0.f, 0.f,
            0.f, 1.f, 0.f, 0.f,
            0.f, 0.f, 1.f, 0.f,
            0.f, 0.f, 0.f, 1.f,
        }};
        ALMetalWorldSimpleBatch water_exclusion_batch;
        water_exclusion_batch.vertices = vertices.get();
        water_exclusion_batch.vertex_count = positions.size();
        water_exclusion_batch.indices = indices.get();
        water_exclusion_batch.index_count = index_values.size();
        water_exclusion_batch.water_exclusion = true;
        std::memcpy(water_exclusion_batch.modelview_projection,
                    identity.data(), sizeof(identity));
        std::memcpy(water_exclusion_batch.modelview,
                    identity.data(), sizeof(identity));
        std::array<ALMetalWorldSimpleBatch, 2> final_batches{{
            water_exclusion_batch,
            fullbright_batch,
        }};
        ALMetalWorldWaterExclusionSurface water_surface;
        water_surface.cell_map = water_cell_map.get();
        std::memcpy(water_surface.eye_to_agent,
                    identity.data(), sizeof(identity));
        water_surface.cell_square[0] = -1.f;
        water_surface.cell_square[1] = -1.f;
        water_surface.cell_square[2] = 2.f;
        water_surface.cell_square[3] = 1.f;
        water_surface.camera_default_height[2] = 1.f;
        water_surface.camera_default_height[3] = 0.f;
        opaque_forward_scene.batches = final_batches.data();
        opaque_forward_scene.batch_count = final_batches.size();
        opaque_forward_scene.water_exclusion_surface = nullptr;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world water-exclusion surface is invalid");
        opaque_forward_scene.water_exclusion_surface = &water_surface;
        error.clear();
        auto water_excluded = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(water_excluded);

        auto stencil_library = ALMetalShaderLibrary::loadBuiltin(
            *device, &error);
        INFO(error);
        REQUIRE(stencil_library);
        ALMetalRenderPipelineDescriptor stencil_pipeline_descriptor;
        stencil_pipeline_descriptor.library = stencil_library.get();
        stencil_pipeline_descriptor.vertex_function =
            "almetal_test_vertex";
        stencil_pipeline_descriptor.fragment_function =
            "almetal_test_fragment";
        stencil_pipeline_descriptor.colors[0].format =
            ALMetalPixelFormat::rgba16_float;
        stencil_pipeline_descriptor.depth_stencil_format =
            ALMetalPixelFormat::depth32_float_stencil8;
        stencil_pipeline_descriptor.label =
            "Alchemy water-exclusion stencil proof pipeline";
        auto stencil_pipeline = ALMetalRenderPipeline::create(
            *device, stencil_pipeline_descriptor, &error);
        INFO(error);
        REQUIRE(stencil_pipeline);
        ALMetalDepthStencilDescriptor stencil_test_descriptor;
        stencil_test_descriptor.depth_compare =
            ALMetalCompareFunction::always;
        stencil_test_descriptor.depth_write_enabled = false;
        stencil_test_descriptor.stencil_enabled = true;
        stencil_test_descriptor.front_stencil.compare =
            ALMetalCompareFunction::equal;
        stencil_test_descriptor.front_stencil.read_mask = 1u;
        stencil_test_descriptor.front_stencil.write_mask = 0u;
        stencil_test_descriptor.back_stencil =
            stencil_test_descriptor.front_stencil;
        stencil_test_descriptor.label =
            "Alchemy water-exclusion stencil proof state";
        auto stencil_test_state = ALMetalDepthStencilState::create(
            *device, stencil_test_descriptor, &error);
        INFO(error);
        REQUIRE(stencil_test_state);
        struct StencilProofVertex
        {
            float position[2];
            float color[4];
        };
        const std::array<StencilProofVertex, 3> stencil_vertices{{
            {{-0.8f, -0.8f}, {1.f, 0.f, 0.f, 1.f}},
            {{ 0.8f, -0.8f}, {1.f, 0.f, 0.f, 1.f}},
            {{ 0.0f,  0.8f}, {1.f, 0.f, 0.f, 1.f}},
        }};
        ALMetalBufferDescriptor stencil_vertex_descriptor;
        stencil_vertex_descriptor.length = sizeof(stencil_vertices);
        stencil_vertex_descriptor.storage = ALMetalStorageMode::shared;
        stencil_vertex_descriptor.label =
            "Alchemy water-exclusion stencil proof vertices";
        auto stencil_vertex_buffer = ALMetalBuffer::create(
            *device, stencil_vertex_descriptor, &error);
        INFO(error);
        REQUIRE(stencil_vertex_buffer);
        REQUIRE(stencil_vertex_buffer->write(
            0, stencil_vertices.data(), sizeof(stencil_vertices), &error));
        ALMetalRenderPassConfig stencil_proof_config;
        stencil_proof_config.colors[0].load = ALMetalLoadAction::load;
        stencil_proof_config.colors[0].store = ALMetalStoreAction::store;
        stencil_proof_config.depth_load = ALMetalLoadAction::load;
        stencil_proof_config.depth_store = ALMetalStoreAction::store;
        stencil_proof_config.stencil_load = ALMetalLoadAction::load;
        stencil_proof_config.stencil_store = ALMetalStoreAction::store;
        auto stencil_proof_pass = water_excluded->makeRenderPass(
            stencil_proof_config, &error);
        auto stencil_proof_command = device->makeCommandBuffer(
            "Alchemy water-exclusion stencil proof", &error);
        auto stencil_proof_encoder =
            stencil_proof_pass && stencil_proof_command
            ? ALMetalRenderEncoder::begin(
                  *stencil_proof_command, *stencil_proof_pass,
                  "Alchemy water-exclusion stencil proof encoder",
                  &error)
            : nullptr;
        INFO(error);
        REQUIRE(stencil_proof_encoder);
        REQUIRE(stencil_proof_encoder->setPipeline(
            *stencil_pipeline, &error));
        REQUIRE(stencil_proof_encoder->setDepthStencilState(
            stencil_test_state.get(), &error));
        REQUIRE(stencil_proof_encoder->setStencilReferenceValue(
            1u, &error));
        REQUIRE(stencil_proof_encoder->setVertexBuffer(
            0, *stencil_vertex_buffer, 0, &error));
        REQUIRE(stencil_proof_encoder->setViewport(
            {0.0, 0.0, 32.0, 32.0, 0.0, 1.0}, &error));
        REQUIRE(stencil_proof_encoder->setScissor(
            {0, 0, 32, 32}, &error));
        REQUIRE(stencil_proof_encoder->setCullMode(
            ALMetalCullMode::none, &error));
        REQUIRE(stencil_proof_encoder->draw(
            ALMetalPrimitiveType::triangle, 0, 3, 1, &error));
        REQUIRE(stencil_proof_encoder->end(&error));
        REQUIRE(stencil_proof_command->commitAndWait(&error));
        INFO(error);
        std::array<std::uint16_t, 32 * 32 * 4> stencil_pixels{};
        REQUIRE(water_excluded->colorTexture(0)->readback(
            *device, 0, 0, {}, stencil_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        const std::size_t stencil_center = (16 * 32 + 16) * 4;
        CHECK(stencil_pixels[stencil_center + 0] == 0x3c00);
        CHECK(stencil_pixels[stencil_center + 1] == 0);
        CHECK(stencil_pixels[stencil_center + 2] == 0);
        CHECK(stencil_pixels[stencil_center + 3] == 0x3c00);
        CHECK(stencil_pixels[0] == 0x3400);
        CHECK(stencil_pixels[1] == 0x3000);
        CHECK(stencil_pixels[2] == 0x2c00);
        CHECK(stencil_pixels[3] == 0x3800);

        // Water haze is an ordered procedural marker rather than a mesh
        // batch. Above water it reuses the live field, reads the retained
        // scene depth, and keeps pixels marked by water exclusion untouched.
        // Underwater it uses the same fog equation over a full-screen
        // triangle without depending on a field texture or stencil.
        ALMetalWorldWaterHaze water_haze;
        water_haze.cell_map = water_cell_map.get();
        std::memcpy(water_haze.modelview_projection,
                    identity.data(), sizeof(identity));
        std::memcpy(water_haze.inverse_projection,
                    identity.data(), sizeof(identity));
        water_haze.cell_square[0] = -1.f;
        water_haze.cell_square[1] = -1.f;
        water_haze.cell_square[2] = 2.f;
        water_haze.cell_square[3] = 1.f;
        water_haze.rings[0] = 1.f;
        water_haze.rings[1] = 1.f;
        water_haze.rings[2] = 4.f;
        water_haze.rings[3] = 0.f;
        water_haze.water_plane[2] = -1.f;
        water_haze.fog_color[0] = 0.5f;
        water_haze.fog_color[1] = 0.25f;
        water_haze.fog_color[2] = 0.125f;
        water_haze.fog_color[3] = 1.f;
        water_haze.fog[0] = 1.f;
        water_haze.fog[1] = 1.f;
        water_haze.draws[0] = {0u, 4u, 1u, true};
        water_haze.draws[1] = {1u, 9u, 12u, false};
        water_haze.draws[2] = {2u, 9u, 4u, false};
        water_haze.draw_count = 3;
        water_haze.above_water = true;
        ALMetalWorldSimpleBatch water_haze_marker;
        water_haze_marker.water_haze = true;
        std::array<ALMetalWorldSimpleBatch, 2> water_haze_batches{{
            water_exclusion_batch,
            water_haze_marker,
        }};
        opaque_forward_scene.batches = water_haze_batches.data();
        opaque_forward_scene.batch_count = water_haze_batches.size();
        opaque_forward_scene.water_exclusion_surface = &water_surface;
        opaque_forward_scene.water_haze = nullptr;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world water-haze inputs are invalid");
        opaque_forward_scene.water_haze = &water_haze;
        std::array<ALMetalWorldSimpleBatch, 2> misordered_haze{{
            water_haze_marker,
            fullbright_batch,
        }};
        opaque_forward_scene.batches = misordered_haze.data();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world water-haze ordering is invalid");
        opaque_forward_scene.batches = water_haze_batches.data();
        error.clear();
        auto above_water_haze = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(above_water_haze);
        std::array<std::uint16_t, 32 * 32 * 4> water_haze_pixels{};
        std::array<float, 32 * 32> water_haze_depth{};
        REQUIRE(above_water_haze->colorTexture(0)->readback(
            *device, 0, 0, {}, water_haze_pixels.data(), 32 * 8,
            &error));
        REQUIRE(above_water_haze->depthStencilTexture()->readback(
            *device, 0, 0, {}, water_haze_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK(water_haze_pixels[stencil_center + 0] == 0x3400);
        CHECK(water_haze_pixels[stencil_center + 1] == 0x3000);
        CHECK(water_haze_pixels[stencil_center + 2] == 0x2c00);
        CHECK(water_haze_pixels[stencil_center + 3] == 0x3800);
        CHECK(water_haze_pixels[0] != 0x3400);
        CHECK(water_haze_pixels[3] < 0x3800);
        CHECK(std::abs(
                  water_haze_depth[stencil_center / 4] - 0.625f) <
              0.0001f);
        CHECK(std::abs(water_haze_depth[0] - 1.f) < 0.0001f);

        water_haze.above_water = false;
        water_haze.cell_map = nullptr;
        water_haze.draw_count = 0;
        opaque_forward_scene.batches = &water_haze_marker;
        opaque_forward_scene.batch_count = 1;
        opaque_forward_scene.water_exclusion_surface = nullptr;
        auto underwater_haze = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(underwater_haze);
        REQUIRE(underwater_haze->colorTexture(0)->readback(
            *device, 0, 0, {}, water_haze_pixels.data(), 32 * 8,
            &error));
        REQUIRE(underwater_haze->depthStencilTexture()->readback(
            *device, 0, 0, {}, water_haze_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK(water_haze_pixels[stencil_center + 0] != 0x3400);
        CHECK(water_haze_pixels[stencil_center + 3] < 0x3800);
        CHECK(std::abs(
                  water_haze_depth[stencil_center / 4] - 0.625f) <
              0.0001f);

        const std::array<float, 2> reverse_water_cell{{0.5f, 1.f}};
        auto reverse_water_upload = device->makeCommandBuffer(
            "Alchemy reverse water-haze height upload", &error);
        REQUIRE(reverse_water_upload);
        REQUIRE(water_cell_map->upload(
            *reverse_water_upload, 0, 0, {}, reverse_water_cell.data(),
            sizeof(reverse_water_cell), &error));
        REQUIRE(reverse_water_upload->commitAndWait(&error));
        water_haze.above_water = true;
        water_haze.cell_map = water_cell_map.get();
        water_haze.draw_count = 3;
        opaque_forward_scene.gbuffer = reverse_coverage_result.get();
        opaque_forward_scene.reverse_z = true;
        auto reverse_water_haze = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_water_haze);
        REQUIRE(reverse_water_haze->colorTexture(0)->readback(
            *device, 0, 0, {}, water_haze_pixels.data(), 32 * 8,
            &error));
        REQUIRE(reverse_water_haze->depthStencilTexture()->readback(
            *device, 0, 0, {}, water_haze_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK(water_haze_pixels[stencil_center + 0] != 0x3400);
        CHECK(water_haze_pixels[stencil_center + 3] < 0x3800);
        CHECK(std::abs(
                  water_haze_depth[stencil_center / 4] - 0.25f) <
              0.0001f);

        // Pre-water alpha follows water haze in the final-color owner. The
        // first native family is the exact fogged fullbright program: source
        // over RGB, destination alpha multiplied by uncovered coverage, and
        // writable depth for both static and rigged geometry.
        ALMetalWorldAlphaEnvironment alpha_environment;
        alpha_environment.water_plane[2] = 1.f;
        alpha_environment.water_plane[3] = -1.f;
        alpha_environment.eye_to_sky[0][0] = 1.f;
        alpha_environment.eye_to_sky[1][1] = 1.f;
        alpha_environment.eye_to_sky[2][2] = 1.f;
        alpha_environment.glow_max_y[0] = 1.f;
        alpha_environment.glow_max_y[2] = -1.f;
        alpha_environment.glow_max_y[3] = 1.f;
        alpha_environment.light_direction[2] = 1.f;
        alpha_environment.atmospheric[1] = 1.f;
        alpha_environment.atmospheric[2] = 1.f;
        alpha_environment.atmospheric[3] = 1.f;
        alpha_environment.water_fog[0] = 1.f;
        alpha_environment.water_fog[2] = -1.f;

        ALMetalWorldSimpleBatch pre_water_alpha = fullbright_batch;
        pre_water_alpha.impostor_fullbright = false;
        pre_water_alpha.alpha_mask = false;
        pre_water_alpha.alpha_cutoff = 0.f;
        pre_water_alpha.pre_water_alpha = true;
        pre_water_alpha.pre_water_fullbright = true;
        std::fill(std::begin(pre_water_alpha.modelview),
                  std::end(pre_water_alpha.modelview), 0.f);
        pre_water_alpha.modelview[14] = 0.25f;
        pre_water_alpha.modelview[15] = 1.f;
        std::fill(std::begin(pre_water_alpha.modelview_projection),
                  std::end(pre_water_alpha.modelview_projection), 0.f);
        for (std::size_t diagonal = 0; diagonal < 4; ++diagonal)
        {
            pre_water_alpha.modelview_projection[
                diagonal * 4 + diagonal] = 1.f;
        }
        pre_water_alpha.modelview_projection[12] = -0.8f;
        pre_water_alpha.modelview_projection[14] = -0.25f;
        pre_water_alpha.skin_palette = nullptr;
        pre_water_alpha.skin_palette_float_count = 0;
        pre_water_alpha.skin_joint_count = 0;
        pre_water_alpha.weight_offset = 0;

        ALMetalWorldSimpleBatch pre_water_alpha_rigged =
            pre_water_alpha;
        pre_water_alpha_rigged.modelview_projection[12] = 0.8f;
        pre_water_alpha_rigged.weight_offset = weight_offset;
        pre_water_alpha_rigged.skin_palette =
            alpha_skin_palette.data();
        pre_water_alpha_rigged.skin_palette_float_count =
            alpha_skin_palette.size();
        pre_water_alpha_rigged.skin_joint_count = 1;
        for (std::size_t diagonal = 0; diagonal < 3; ++diagonal)
        {
            pre_water_alpha_rigged.rigged_normal_matrix
                [diagonal][diagonal] = 1.f;
        }
        std::array<ALMetalWorldSimpleBatch, 2> pre_water_batches{{
            pre_water_alpha,
            pre_water_alpha_rigged,
        }};
        opaque_forward_scene.batches = pre_water_batches.data();
        opaque_forward_scene.batch_count = pre_water_batches.size();
        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.reverse_z = false;
        opaque_forward_scene.water_exclusion_surface = nullptr;
        opaque_forward_scene.water_haze = nullptr;
        opaque_forward_scene.alpha_environment = nullptr;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world pre-water alpha environment is invalid");
        opaque_forward_scene.alpha_environment = &alpha_environment;
        error.clear();
        auto pre_water_result = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(pre_water_result);
        std::array<std::uint16_t, 32 * 32 * 4> pre_water_pixels{};
        std::array<float, 32 * 32> pre_water_depth{};
        REQUIRE(pre_water_result->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        REQUIRE(pre_water_result->depthStencilTexture()->readback(
            *device, 0, 0, {}, pre_water_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        const std::size_t pre_water_left = (16 * 32 + 6) * 4;
        const std::size_t pre_water_right = (16 * 32 + 26) * 4;
        for (const std::size_t pixel : {pre_water_left,
                                        pre_water_right})
        {
            CHECK(pre_water_pixels[pixel + 0] >= 0x2ff0);
            CHECK(pre_water_pixels[pixel + 0] <= 0x3000);
            CHECK(pre_water_pixels[pixel + 1] >= 0x3880);
            CHECK(pre_water_pixels[pixel + 1] <= 0x3890);
            CHECK(pre_water_pixels[pixel + 2] >= 0x27f0);
            CHECK(pre_water_pixels[pixel + 2] <= 0x2800);
            CHECK(pre_water_pixels[pixel + 3] >= 0x33f0);
            CHECK(pre_water_pixels[pixel + 3] <= 0x3400);
            CHECK(std::abs(pre_water_depth[pixel / 4] - 0.5f) <
                  0.0001f);
        }

        const auto half_to_float = [](std::uint16_t value)
        {
            const float magnitude = ((value >> 10) & 0x1fu) == 0
                ? std::ldexp(static_cast<float>(value & 0x3ffu), -24)
                : std::ldexp(
                      static_cast<float>((value & 0x3ffu) + 0x400u),
                      static_cast<int>((value >> 10) & 0x1fu) - 25);
            return (value & 0x8000u) != 0 ? -magnitude : magnitude;
        };
        const float coverage = 128.f / 255.f;
        const float uncovered = 1.f - coverage;

        // A constant eye-space position makes the reference water-fog line
        // integral independent of raster position. Compare the actual half
        // output against the GLSL equation, then do the same for atmospheric
        // extinction and additive haze below.
        alpha_environment.water_fog_color[0] = 0.2f;
        alpha_environment.water_fog_color[1] = 0.4f;
        alpha_environment.water_fog_color[2] = 0.6f;
        alpha_environment.water_fog[1] = 2.f;
        auto fogged_pre_water = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(fogged_pre_water);
        REQUIRE(fogged_pre_water->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        constexpr float fog_base = 0.98f;
        const float fog_t1 = -2.f * std::pow(fog_base, 1.f);
        const float fog_t2 = 2.f - 1.f;
        const float fog_t3 = std::pow(fog_base, fog_t2 * 0.25f) - 1.f;
        const float fog_light = std::pow(
            std::min(fog_t1 / fog_t2 * fog_t3, 1.f), 1.f / 1.7f);
        const float fog_transmission = std::pow(fog_base, 0.5f);
        const std::array<float, 4> expected_water_fog{{
            (0.2f * fog_light) * coverage + 0.25f * uncovered,
            (fog_transmission + 0.4f * fog_light) * coverage +
                0.125f * uncovered,
            (0.6f * fog_light) * coverage + 0.0625f * uncovered,
            0.5f * uncovered,
        }};
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(std::abs(
                half_to_float(pre_water_pixels[pre_water_left + channel]) -
                expected_water_fog[channel]) < 0.002f);
        }

        const auto srgb_to_linear = [](float value)
        {
            return value <= 0.04045f
                ? value / 12.92f
                : std::pow((value + 0.055f) / 1.055f, 2.4f);
        };
        alpha_environment.water_plane[3] = 1.f;
        alpha_environment.water_fog[1] = 0.f;
        alpha_environment.water_fog[2] = 1.f;
        alpha_environment.atmospheric[0] = 1.f;
        alpha_environment.haze_extinction[0] = 2.f;
        alpha_environment.haze_extinction[1] = 2.f;
        alpha_environment.haze_extinction[2] = 2.f;
        alpha_environment.haze_additive[0] = 0.1f;
        alpha_environment.haze_additive[1] = 0.2f;
        alpha_environment.haze_additive[2] = 0.3f;
        auto atmospheric_pre_water = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(atmospheric_pre_water);
        REQUIRE(atmospheric_pre_water->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        const float attenuation = std::exp(-2.f * 0.25f);
        const std::array<float, 3> haze_additive{{0.1f, 0.2f, 0.3f}};
        std::array<float, 4> expected_atmosphere{{
            0.f, attenuation, 0.f, 0.5f * uncovered,
        }};
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            const float additive = srgb_to_linear(
                haze_additive[channel] * (1.f - attenuation) * 2.f);
            expected_atmosphere[channel] =
                (expected_atmosphere[channel] + additive) * coverage +
                std::array<float, 3>{{0.25f, 0.125f, 0.0625f}}[channel] *
                    uncovered;
        }
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(std::abs(
                half_to_float(pre_water_pixels[pre_water_left + channel]) -
                expected_atmosphere[channel]) < 0.002f);
        }

        // Flip the clip side: the same geometry must leave both color and
        // depth at their copied inputs.
        alpha_environment.water_fog[2] = -1.f;
        auto clipped_pre_water = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(clipped_pre_water);
        REQUIRE(clipped_pre_water->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        REQUIRE(clipped_pre_water->depthStencilTexture()->readback(
            *device, 0, 0, {}, pre_water_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK(pre_water_pixels[pre_water_left + 0] == 0x3400);
        CHECK(pre_water_pixels[pre_water_left + 1] == 0x3000);
        CHECK(pre_water_pixels[pre_water_left + 2] == 0x2c00);
        CHECK(pre_water_pixels[pre_water_left + 3] == 0x3800);
        CHECK(std::abs(pre_water_depth[pre_water_left / 4] - 0.625f) <
              0.0001f);
        alpha_environment.water_plane[3] = -1.f;
        alpha_environment.water_fog[2] = -1.f;
        alpha_environment.atmospheric[0] = 0.f;
        alpha_environment.haze_extinction[0] = 0.f;
        alpha_environment.haze_extinction[1] = 0.f;
        alpha_environment.haze_extinction[2] = 0.f;
        alpha_environment.haze_additive[0] = 0.f;
        alpha_environment.haze_additive[1] = 0.f;
        alpha_environment.haze_additive[2] = 0.f;

        std::array<ALMetalWorldSimpleBatch, 2> ordered_haze_alpha{{
            water_haze_marker,
            pre_water_alpha,
        }};
        opaque_forward_scene.batches = ordered_haze_alpha.data();
        opaque_forward_scene.batch_count = ordered_haze_alpha.size();
        opaque_forward_scene.water_haze = &water_haze;
        auto ordered_haze_alpha_result =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(ordered_haze_alpha_result);
        REQUIRE(ordered_haze_alpha_result->depthStencilTexture()->readback(
            *device, 0, 0, {}, pre_water_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK(std::abs(pre_water_depth[pre_water_left / 4] - 0.5f) <
              0.0001f);

        // Alpha cannot precede the water-haze marker. The valid production
        // order is haze followed by one or more alpha batches.
        std::array<ALMetalWorldSimpleBatch, 2> alpha_before_haze{{
            pre_water_alpha,
            water_haze_marker,
        }};
        opaque_forward_scene.batches = alpha_before_haze.data();
        opaque_forward_scene.batch_count = alpha_before_haze.size();
        opaque_forward_scene.water_haze = &water_haze;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world water-haze ordering is invalid");

        opaque_forward_scene.batches = pre_water_batches.data();
        opaque_forward_scene.batch_count = pre_water_batches.size();
        opaque_forward_scene.water_haze = nullptr;
        opaque_forward_scene.gbuffer = reverse_coverage_result.get();
        opaque_forward_scene.reverse_z = true;
        pre_water_batches[0].modelview_projection[14] = 0.25f;
        pre_water_batches[1].modelview_projection[14] = 0.25f;
        error.clear();
        auto reverse_pre_water = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_pre_water);
        REQUIRE(reverse_pre_water->depthStencilTexture()->readback(
            *device, 0, 0, {}, pre_water_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK(std::abs(pre_water_depth[pre_water_left / 4] - 0.5f) <
              0.0001f);
        CHECK(std::abs(pre_water_depth[pre_water_right / 4] - 0.5f) <
              0.0001f);

        opaque_forward_scene.batches = &fullbright_batch;
        opaque_forward_scene.batch_count = 1;
        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.reverse_z = false;
        opaque_forward_scene.water_exclusion_surface = nullptr;
        opaque_forward_scene.water_haze = nullptr;
        opaque_forward_scene.alpha_environment = nullptr;

        // The two glow owners share alpha-only output but not blending:
        // opaque PBR glow replaces destination alpha, then legacy glow adds
        // its diffuse-alpha-times-emissive coverage. Replay both static and
        // rigged variants at retained equal depth and prove RGB/depth survive.
        ALMetalWorldSimpleBatch pbr_glow_batch;
        pbr_glow_batch.vertices = vertices.get();
        pbr_glow_batch.position_offset = 0;
        pbr_glow_batch.texcoord_offset = texcoord_offset;
        pbr_glow_batch.emissive_offset = emissive_offset;
        pbr_glow_batch.vertex_count = positions.size();
        pbr_glow_batch.indices = indices.get();
        pbr_glow_batch.index_count = index_values.size();
        pbr_glow_batch.diffuse_textures[0] = indexed_diffuse.get();
        pbr_glow_batch.texture_count = 1;
        pbr_glow_batch.pbr_slots[0].emissive_texture =
            indexed_diffuse.get();
        pbr_glow_batch.pbr_slots[0].emissive_color[1] = 0.5f;
        pbr_glow_batch.pbr_slots[0].base_color_factor[3] = 1.f;
        pbr_glow_batch.pbr_slots[0].alpha_cutoff = -1.f;
        pbr_glow_batch.pbr_slot_count = 1;
        pbr_glow_batch.pbr_glow = true;
        std::memcpy(pbr_glow_batch.modelview_projection,
                    identity.data(), sizeof(identity));

        ALMetalWorldSimpleBatch pbr_glow_rigged = pbr_glow_batch;
        pbr_glow_rigged.weight_offset = weight_offset;
        pbr_glow_rigged.skin_palette = alpha_skin_palette.data();
        pbr_glow_rigged.skin_palette_float_count =
            alpha_skin_palette.size();
        pbr_glow_rigged.skin_joint_count = 1;
        std::array<ALMetalWorldSimpleBatch, 2> pbr_glow_batches{{
            pbr_glow_batch,
            pbr_glow_rigged,
        }};
        opaque_forward_scene.batches = pbr_glow_batches.data();
        opaque_forward_scene.batch_count = pbr_glow_batches.size();

        pbr_glow_batches[0].emissive_offset = vertex_bytes.size();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error.find(
                  "Metal world opaque post-deferred batch is invalid") == 0);
        pbr_glow_batches[0].emissive_offset = emissive_offset;
        pbr_glow_batches[0].pbr_slots[0].emissive_texture = nullptr;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world PBR glow slot is invalid");
        pbr_glow_batches[0].pbr_slots[0].emissive_texture =
            indexed_diffuse.get();
        error.clear();
        auto pbr_glow_result = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(pbr_glow_result);
        std::array<std::uint16_t, 32 * 32 * 4> glow_pixels{};
        std::array<float, 32 * 32> glow_depth{};
        REQUIRE(pbr_glow_result->colorTexture(0)->readback(
            *device, 0, 0, {}, glow_pixels.data(), 32 * 8, &error));
        REQUIRE(pbr_glow_result->depthStencilTexture()->readback(
            *device, 0, 0, {}, glow_depth.data(), 32 * sizeof(float),
            &error));
        INFO(error);
        CHECK(glow_pixels[center + 0] == 0x3400);
        CHECK(glow_pixels[center + 1] == 0x3000);
        CHECK(glow_pixels[center + 2] == 0x2c00);
        CHECK(glow_pixels[center + 3] >= 0x3400);
        CHECK(glow_pixels[center + 3] <= 0x3410);
        CHECK(std::abs(glow_depth[center / 4] - 0.625f) < 0.0001f);

        ALMetalWorldSimpleBatch legacy_glow_batch = pbr_glow_batch;
        legacy_glow_batch.diffuse_textures[0] = tree_diffuse.get();
        legacy_glow_batch.pbr_slot_count = 0;
        legacy_glow_batch.pbr_glow = false;
        legacy_glow_batch.legacy_glow = true;
        ALMetalWorldSimpleBatch legacy_glow_rigged = legacy_glow_batch;
        legacy_glow_rigged.weight_offset = weight_offset;
        legacy_glow_rigged.skin_palette = alpha_skin_palette.data();
        legacy_glow_rigged.skin_palette_float_count =
            alpha_skin_palette.size();
        legacy_glow_rigged.skin_joint_count = 1;
        std::array<ALMetalWorldSimpleBatch, 4> glow_batches{{
            pbr_glow_batch,
            pbr_glow_rigged,
            legacy_glow_batch,
            legacy_glow_rigged,
        }};
        opaque_forward_scene.batches = glow_batches.data();
        opaque_forward_scene.batch_count = glow_batches.size();
        auto glow_result = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(glow_result);
        REQUIRE(glow_result->colorTexture(0)->readback(
            *device, 0, 0, {}, glow_pixels.data(), 32 * 8, &error));
        REQUIRE(glow_result->depthStencilTexture()->readback(
            *device, 0, 0, {}, glow_depth.data(), 32 * sizeof(float),
            &error));
        INFO(error);
        CHECK(glow_pixels[center + 0] == 0x3400);
        CHECK(glow_pixels[center + 1] == 0x3000);
        CHECK(glow_pixels[center + 2] == 0x2c00);
        CHECK(glow_pixels[center + 3] > 0x3a00);
        CHECK(glow_pixels[center + 3] < 0x3a20);
        CHECK(std::abs(glow_depth[center / 4] - 0.625f) < 0.0001f);
        CHECK(glow_pixels[0] == 0x3400);
        CHECK(glow_pixels[1] == 0x3000);
        CHECK(glow_pixels[2] == 0x2c00);
        CHECK(glow_pixels[3] == 0x3800);

        opaque_forward_scene.batches = &fullbright_batch;
        opaque_forward_scene.batch_count = 1;

        // Fullbright shiny is opaque in the impostor bake, but its RGB is
        // the exact legacy reflection-probe result: decoded diffuse times
        // linear tint mixed with the selected live cubemap at vertex-alpha
        // intensity. Use two single-texel cubes with distinct colours to
        // prove that refIndex selects the requested array element rather
        // than silently sampling cube zero.
        ALMetalTextureDescriptor probe_descriptor;
        probe_descriptor.type = ALMetalTextureType::texture_cube_array;
        probe_descriptor.format = ALMetalPixelFormat::rgba8_unorm;
        probe_descriptor.width = 1;
        probe_descriptor.height = 1;
        probe_descriptor.array_length = 2;
        probe_descriptor.storage = ALMetalStorageMode::private_gpu;
        probe_descriptor.usage = ALMetalTextureUsage::shader_read;
        probe_descriptor.label =
            "Alchemy world shiny reflection-probe array";
        auto probe_texture = ALMetalTexture::create(
            *device, probe_descriptor, &error);
        INFO(error);
        REQUIRE(probe_texture);
        auto probe_upload = device->makeCommandBuffer(
            "Alchemy world shiny reflection-probe upload", &error);
        INFO(error);
        REQUIRE(probe_upload);
        for (std::uint32_t slice = 0; slice < 12; ++slice)
        {
            const std::array<std::uint8_t, 4> pixel = slice < 6
                ? std::array<std::uint8_t, 4>{{255, 0, 0, 255}}
                : std::array<std::uint8_t, 4>{{0, 0, 255, 255}};
            REQUIRE(probe_texture->upload(
                *probe_upload, 0, slice, {}, pixel.data(), 4, &error));
        }
        REQUIRE(probe_upload->commitAndWait(&error));
        INFO(error);

        ALMetalWorldReflectionProbes reflection_probes;
        reflection_probes.radiance_texture = probe_texture.get();
        reflection_probes.constants.ref_sphere[0][3] = 100.f;
        reflection_probes.constants.ref_params[0][1] = 1.f;
        reflection_probes.constants.ref_params[0][2] = 1.f;
        reflection_probes.constants.ref_index[0][0] = 0;
        reflection_probes.constants.ref_index[0][1] = -1;
        reflection_probes.constants.ref_sphere[1][3] = 100.f;
        reflection_probes.constants.ref_params[1][1] = 1.f;
        reflection_probes.constants.ref_params[1][2] = 1.f;
        reflection_probes.constants.ref_params[1][3] = -100.f;
        reflection_probes.constants.ref_index[1][0] = 1;
        reflection_probes.constants.ref_index[1][1] = -1;
        reflection_probes.constants.ref_index[1][3] = 1;
        reflection_probes.constants.config[0] = 2.f;
        reflection_probes.constants.env_matrix[0][0] = 1.f;
        reflection_probes.constants.env_matrix[1][1] = 1.f;
        reflection_probes.constants.env_matrix[2][2] = 1.f;

        ALMetalTextureDescriptor irradiance_descriptor;
        irradiance_descriptor.format = ALMetalPixelFormat::rgba32_uint;
        irradiance_descriptor.width = 4;
        irradiance_descriptor.height = 2;
        irradiance_descriptor.storage = ALMetalStorageMode::private_gpu;
        irradiance_descriptor.usage = ALMetalTextureUsage::shader_read;
        irradiance_descriptor.label =
            "Alchemy world simple-alpha irradiance test";
        auto irradiance_texture = ALMetalTexture::create(
            *device, irradiance_descriptor, &error);
        INFO(error);
        REQUIRE(irradiance_texture);
        std::array<std::uint32_t, 4 * 2 * 4> zero_irradiance{};
        auto irradiance_upload = device->makeCommandBuffer(
            "Alchemy world simple-alpha irradiance upload", &error);
        REQUIRE(irradiance_upload);
        REQUIRE(irradiance_texture->upload(
            *irradiance_upload, 0, 0, {}, zero_irradiance.data(),
            4 * 4 * sizeof(std::uint32_t), &error));
        REQUIRE(irradiance_upload->commitAndWait(&error));
        INFO(error);
        reflection_probes.irradiance_texture = irradiance_texture.get();

        // The lit/simple pre-water family adds the exact forward ambient,
        // directional and punctual model on top of the fullbright coverage,
        // fog and depth contract. A zero-ambiance SH pack leaves the live
        // Environment ambient unchanged, so this fixture isolates the
        // modern directional term while exercising both static and rigged
        // pipelines.
        ALMetalWorldLegacyAlphaLighting simple_alpha_lighting;
        simple_alpha_lighting.sun_direction[2] = 1.f;
        simple_alpha_lighting.parameters[0] = 128.f;
        simple_alpha_lighting.parameters[1] = 0.004f;
        simple_alpha_lighting.parameters[2] = 1.f;
        alpha_environment.atmos_sunlit_linear[0] = 1.f;
        alpha_environment.atmos_sunlit_linear[1] = 0.5f;
        alpha_environment.atmos_sunlit_linear[2] = 0.25f;
        alpha_environment.atmos_sunlit[3] = 1.f;
        alpha_environment.atmos_sunlit_linear[3] = 1.f;
        alpha_environment.atmos_amblit[0] = 0.f;
        alpha_environment.atmos_amblit[1] = 0.f;
        alpha_environment.atmos_amblit[2] = 0.f;
        alpha_environment.water_fog[1] = 0.f;

        ALMetalWorldSimpleBatch simple_pre_water = pre_water_alpha;
        simple_pre_water.pre_water_fullbright = false;
        simple_pre_water.pre_water_simple = true;
        simple_pre_water.pre_water_shadows = false;
        ALMetalWorldSimpleBatch simple_pre_water_rigged =
            pre_water_alpha_rigged;
        simple_pre_water_rigged.pre_water_fullbright = false;
        simple_pre_water_rigged.pre_water_simple = true;
        simple_pre_water_rigged.pre_water_shadows = false;
        std::array<ALMetalWorldSimpleBatch, 2> simple_pre_water_batches{{
            simple_pre_water,
            simple_pre_water_rigged,
        }};
        opaque_forward_scene.batches = simple_pre_water_batches.data();
        opaque_forward_scene.batch_count = simple_pre_water_batches.size();
        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.reverse_z = false;
        opaque_forward_scene.water_exclusion_surface = nullptr;
        opaque_forward_scene.water_haze = nullptr;
        opaque_forward_scene.alpha_environment = &alpha_environment;
        opaque_forward_scene.reflection_probes = &reflection_probes;
        opaque_forward_scene.alpha_lighting = nullptr;
        opaque_forward_scene.alpha_directional_shadows = nullptr;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world pre-water alpha lighting is invalid");
        opaque_forward_scene.alpha_lighting = &simple_alpha_lighting;
        reflection_probes.irradiance_texture = nullptr;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world forward environment is invalid");
        reflection_probes.irradiance_texture = irradiance_texture.get();
        error.clear();
        auto simple_pre_water_result = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(simple_pre_water_result);
        REQUIRE(simple_pre_water_result->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        REQUIRE(simple_pre_water_result->depthStencilTexture()->readback(
            *device, 0, 0, {}, pre_water_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        for (const std::size_t pixel : {pre_water_left,
                                        pre_water_right})
        {
            CHECK(std::abs(
                half_to_float(pre_water_pixels[pixel + 0]) - 0.125f) <
                0.002f);
            CHECK(std::abs(
                half_to_float(pre_water_pixels[pixel + 1]) - 0.3125f) <
                0.002f);
            CHECK(std::abs(
                half_to_float(pre_water_pixels[pixel + 2]) - 0.03125f) <
                0.002f);
            CHECK(std::abs(
                half_to_float(pre_water_pixels[pixel + 3]) - 0.25f) <
                0.002f);
            CHECK(std::abs(pre_water_depth[pixel / 4] - 0.5f) <
                  0.0001f);
        }

        simple_alpha_lighting.parameters[3] = 1.f;
        alpha_environment.atmos_sunlit[0] = 0.f;
        alpha_environment.atmos_sunlit[1] = 1.f;
        alpha_environment.atmos_sunlit[2] = 0.f;
        auto classic_simple_result = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(classic_simple_result);
        REQUIRE(classic_simple_result->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        const float classic_source_green =
            srgb_to_linear(0.7f * 1.35f) * 1.1f;
        CHECK(std::abs(
            half_to_float(pre_water_pixels[pre_water_left + 1]) -
            (classic_source_green * coverage + 0.125f * uncovered)) <
            0.002f);

        simple_alpha_lighting.parameters[3] = 0.f;
        alpha_environment.atmos_sunlit_linear[0] = 0.f;
        alpha_environment.atmos_sunlit_linear[1] = 0.f;
        alpha_environment.atmos_sunlit_linear[2] = 0.f;
        ALMetalWorldLegacyAlphaLight& local_light =
            simple_alpha_lighting.local_lights[0];
        local_light.position[2] = 10.f;
        local_light.diffuse[1] = 0.5f;
        local_light.parameters[0] = 100.f;
        local_light.parameters[2] = 1.f;
        auto local_simple_result = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(local_simple_result);
        REQUIRE(local_simple_result->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(half_to_float(pre_water_pixels[pre_water_left + 1]) >
              0.0625f);
        local_light = {};
        alpha_environment.atmos_sunlit_linear[0] = 1.f;
        alpha_environment.atmos_sunlit_linear[1] = 0.5f;
        alpha_environment.atmos_sunlit_linear[2] = 0.25f;

        ALMetalTextureDescriptor hero_descriptor;
        hero_descriptor.type = ALMetalTextureType::texture_cube;
        hero_descriptor.format = ALMetalPixelFormat::rgba8_unorm;
        hero_descriptor.width = 1;
        hero_descriptor.height = 1;
        hero_descriptor.storage = ALMetalStorageMode::private_gpu;
        hero_descriptor.usage = ALMetalTextureUsage::shader_read;
        hero_descriptor.label =
            "Alchemy world hero-probe test cube";
        auto hero_texture = ALMetalTexture::create(
            *device, hero_descriptor, &error);
        INFO(error);
        REQUIRE(hero_texture);
        auto hero_upload = device->makeCommandBuffer(
            "Alchemy world hero-probe black upload", &error);
        INFO(error);
        REQUIRE(hero_upload);
        const std::array<std::uint8_t, 4> black_hero{{0, 0, 0, 255}};
        for (std::uint32_t face = 0; face < 6; ++face)
        {
            REQUIRE(hero_texture->upload(
                *hero_upload, 0, face, {}, black_hero.data(), 4,
                &error));
        }
        REQUIRE(hero_upload->commitAndWait(&error));
        INFO(error);

        ALMetalWorldHeroProbe hero_probe;
        hero_probe.radiance_texture = hero_texture.get();
        hero_probe.constants.clip_plane[3] = 1.f;
        hero_probe.constants.config[1] = 1;

        ALMetalTextureDescriptor ssr_color_descriptor;
        ssr_color_descriptor.format = ALMetalPixelFormat::rgba8_unorm;
        ssr_color_descriptor.width = 1;
        ssr_color_descriptor.height = 2;
        ssr_color_descriptor.storage = ALMetalStorageMode::private_gpu;
        ssr_color_descriptor.usage = ALMetalTextureUsage::shader_read;
        ssr_color_descriptor.label =
            "Alchemy world SSR scene-color test";
        auto ssr_color = ALMetalTexture::create(
            *device, ssr_color_descriptor, &error);
        INFO(error);
        REQUIRE(ssr_color);
        ALMetalTextureDescriptor ssr_depth_descriptor =
            ssr_color_descriptor;
        ssr_depth_descriptor.format = ALMetalPixelFormat::r32_float;
        ssr_depth_descriptor.label =
            "Alchemy world SSR scene-depth test";
        auto ssr_depth = ALMetalTexture::create(
            *device, ssr_depth_descriptor, &error);
        INFO(error);
        REQUIRE(ssr_depth);
        ALMetalTextureDescriptor ssr_normal_descriptor =
            ssr_color_descriptor;
        ssr_normal_descriptor.height = 1;
        ssr_normal_descriptor.label =
            "Alchemy world SSR reverse-facing normal test";
        auto ssr_normal = ALMetalTexture::create(
            *device, ssr_normal_descriptor, &error);
        INFO(error);
        REQUIRE(ssr_normal);
        auto ssr_upload = device->makeCommandBuffer(
            "Alchemy world SSR scene-history upload", &error);
        INFO(error);
        REQUIRE(ssr_upload);
        // Native SSR history retains the ported lower-row-first coordinate
        // contract. Keep the upper row black so a second Y flip in the Metal
        // sampler makes the lower-half assertion below fail visibly.
        const std::array<std::uint8_t, 8> red_lower_ssr{{
            255, 0, 0, 255,
              0, 0, 0, 255,
        }};
        const std::array<std::uint8_t, 4> reverse_normal{{128, 128, 0, 255}};
        const std::array<float, 2> ssr_depth_values{{0.5f, 0.5f}};
        REQUIRE(ssr_color->upload(
            *ssr_upload, 0, 0, {}, red_lower_ssr.data(), 4, &error));
        REQUIRE(ssr_depth->upload(
            *ssr_upload, 0, 0, {}, ssr_depth_values.data(),
            sizeof(float), &error));
        REQUIRE(ssr_normal->upload(
            *ssr_upload, 0, 0, {}, reverse_normal.data(), 4, &error));
        REQUIRE(ssr_upload->commitAndWait(&error));
        INFO(error);

        ALMetalWorldScreenSpaceReflections screen_space_reflections;
        screen_space_reflections.scene_color = ssr_color.get();
        screen_space_reflections.scene_depth = ssr_depth.get();
        for (std::size_t index = 0; index < 4; ++index)
        {
            screen_space_reflections.constants.projection[index * 4 + index] = 1.f;
            screen_space_reflections.constants.inverse_projection[index * 4 + index] = 1.f;
            screen_space_reflections.constants.inverse_modelview_delta[index * 4 + index] = 1.f;
        }
        screen_space_reflections.constants.inverse_projection[14] = -1.5f;
        screen_space_reflections.constants.screen[0] = 32.f;
        screen_space_reflections.constants.screen[1] = 32.f;
        screen_space_reflections.constants.screen[2] = 32.f;
        screen_space_reflections.constants.trace[0] = 4.f;
        screen_space_reflections.constants.trace[1] = 0.1f;
        screen_space_reflections.constants.trace[2] = 0.2f;
        screen_space_reflections.constants.trace[3] = 0.001f;
        screen_space_reflections.constants.sampling[0] = 1.f;
        screen_space_reflections.constants.sampling[1] = 1.6f;
        screen_space_reflections.constants.config[1] = 1;

        // Legacy BLEND materials keep their authored diffuse alpha unless a
        // sun, reflection-probe or punctual highlight raises it. Build a
        // clean retained target so every assertion below observes the Metal
        // fragment directly rather than a preceding alpha layer.
        ALMetalWorldSimpleBatch legacy_seed_batch = flat_alpha_batch;
        legacy_seed_batch.skin_palette = nullptr;
        legacy_seed_batch.skin_palette_float_count = 0;
        legacy_seed_batch.skin_joint_count = 0;
        legacy_seed_batch.weight_offset = 0;
        std::fill(std::begin(legacy_seed_batch.modelview_projection),
                  std::end(legacy_seed_batch.modelview_projection), 0.f);
        for (std::size_t index = 0; index < 4; ++index)
        {
            legacy_seed_batch.modelview_projection[index * 4 + index] = 1.f;
        }
        legacy_seed_batch.modelview_projection[12] = 3.f;
        ALMetalWorldGBufferScene legacy_seed_scene = scene;
        legacy_seed_scene.batches = &legacy_seed_batch;
        legacy_seed_scene.batch_count = 1;
        legacy_seed_scene.reverse_z = false;
        legacy_seed_scene.stamp_opaque_coverage = false;
        legacy_seed_scene.reflection_probes = nullptr;
        legacy_seed_scene.legacy_alpha_lighting = nullptr;
        std::fill(std::begin(legacy_seed_scene.clear_color),
                  std::end(legacy_seed_scene.clear_color), 0.f);
        auto make_legacy_target = [&]()
        {
            error.clear();
            return renderer->render(legacy_seed_scene, &error);
        };
        auto read_legacy_alpha = [&](ALMetalRenderTarget& target)
        {
            std::array<std::uint8_t, 32 * 32 * 4> pixels{};
            REQUIRE(target.colorTexture(0)->readback(
                *device, 0, 0, {}, pixels.data(), 32 * 4, &error));
            INFO(error);
            return pixels[center + 3];
        };
        auto read_legacy_alpha_at = [&](ALMetalRenderTarget& target,
                                        std::size_t x, std::size_t y)
        {
            std::array<std::uint8_t, 32 * 32 * 4> pixels{};
            REQUIRE(target.colorTexture(0)->readback(
                *device, 0, 0, {}, pixels.data(), 32 * 4, &error));
            INFO(error);
            return pixels[(y * 32 + x) * 4 + 3];
        };
        auto read_legacy_depth = [&](ALMetalRenderTarget& target)
        {
            std::array<float, 32 * 32> pixels{};
            REQUIRE(target.depthStencilTexture()->readback(
                *device, 0, 0, {}, pixels.data(), 32 * sizeof(float),
                &error));
            INFO(error);
            return pixels[center / 4];
        };

        ALMetalWorldSimpleBatch legacy_alpha_batch = flat_alpha_batch;
        legacy_alpha_batch.diffuse_textures[0] = tree_diffuse.get();
        legacy_alpha_batch.texture_count = 1;
        legacy_alpha_batch.material_slot_count = 1;
        legacy_alpha_batch.material_alpha_mode = 1;
        legacy_alpha_batch.tangent_offset = tangent_offset;
        legacy_alpha_batch.texcoord1_offset = texcoord_offset;
        legacy_alpha_batch.texcoord2_offset = texcoord_offset;
        legacy_alpha_batch.pbr_slot_count = 0;
        legacy_alpha_batch.skin_palette = nullptr;
        legacy_alpha_batch.skin_palette_float_count = 0;
        legacy_alpha_batch.skin_joint_count = 0;
        legacy_alpha_batch.weight_offset = 0;
        std::fill(std::begin(legacy_alpha_batch.modelview_projection),
                  std::end(legacy_alpha_batch.modelview_projection), 0.f);
        std::fill(std::begin(legacy_alpha_batch.modelview),
                  std::end(legacy_alpha_batch.modelview), 0.f);
        for (std::size_t index = 0; index < 4; ++index)
        {
            legacy_alpha_batch.modelview_projection[index * 4 + index] = 1.f;
            legacy_alpha_batch.modelview[index * 4 + index] = 1.f;
        }
        legacy_alpha_batch.modelview[14] = -2.f;
        legacy_alpha_batch.material_slots[0].specular_color[0] = 1.f;
        legacy_alpha_batch.material_slots[0].specular_color[1] = 1.f;
        legacy_alpha_batch.material_slots[0].specular_color[2] = 1.f;
        legacy_alpha_batch.material_slots[0].specular_color[3] = 1.f;
        legacy_alpha_batch.material_slots[0].normal_texture = nullptr;
        legacy_alpha_batch.material_slots[0].specular_texture = nullptr;
        legacy_alpha_batch.material_slots[0].env_intensity = 1.f;
        legacy_alpha_batch.material_slots[0].fullbright = 0.f;

        ALMetalWorldLegacyAlphaLighting legacy_lighting;
        legacy_lighting.sun_direction[2] = 1.f;
        legacy_lighting.sun_color[0] = 1.f;
        legacy_lighting.parameters[0] = 128.f;
        legacy_lighting.parameters[1] = 0.004f;
        legacy_lighting.parameters[2] = 1.f;

        ALMetalWorldGBufferScene legacy_alpha_scene = legacy_seed_scene;
        legacy_alpha_scene.batches = &legacy_alpha_batch;
        legacy_alpha_scene.reflection_probes = &reflection_probes;
        legacy_alpha_scene.legacy_alpha_lighting = nullptr;
        auto legacy_target = make_legacy_target();
        INFO(error);
        REQUIRE(legacy_target);
        CHECK_FALSE(renderer->compositeImpostorPostDeferred(
            *legacy_target, legacy_alpha_scene, &error));
        CHECK(error == "Metal world legacy alpha lighting is invalid");
        error.clear();
        legacy_alpha_scene.legacy_alpha_lighting = &legacy_lighting;
        legacy_alpha_scene.reflection_probes = nullptr;
        CHECK_FALSE(renderer->compositeImpostorPostDeferred(
            *legacy_target, legacy_alpha_scene, &error));
        CHECK(error ==
              "Metal world legacy alpha reflection probes are invalid");
        error.clear();
        legacy_alpha_scene.reflection_probes = &reflection_probes;

        std::array<std::uint8_t, 32 * 32 * 4> legacy_orm_before{};
        std::array<std::uint16_t, 32 * 32 * 4> legacy_normal_before{};
        std::array<std::uint32_t, 32 * 32> legacy_emissive_before{};
        REQUIRE(legacy_target->colorTexture(1)->readback(
            *device, 0, 0, {}, legacy_orm_before.data(), 32 * 4,
            &error));
        REQUIRE(legacy_target->colorTexture(2)->readback(
            *device, 0, 0, {}, legacy_normal_before.data(), 32 * 8,
            &error));
        REQUIRE(legacy_target->colorTexture(3)->readback(
            *device, 0, 0, {}, legacy_emissive_before.data(), 32 * 4,
            &error));
        REQUIRE(renderer->compositeImpostorPostDeferred(
            *legacy_target, legacy_alpha_scene, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(read_legacy_alpha(*legacy_target)) -
                       128) <= 1);
        CHECK(std::abs(read_legacy_depth(*legacy_target) - 1.f) < 0.0001f);
        std::array<std::uint8_t, 32 * 32 * 4> legacy_orm_after{};
        std::array<std::uint16_t, 32 * 32 * 4> legacy_normal_after{};
        std::array<std::uint32_t, 32 * 32> legacy_emissive_after{};
        REQUIRE(legacy_target->colorTexture(1)->readback(
            *device, 0, 0, {}, legacy_orm_after.data(), 32 * 4,
            &error));
        REQUIRE(legacy_target->colorTexture(2)->readback(
            *device, 0, 0, {}, legacy_normal_after.data(), 32 * 8,
            &error));
        REQUIRE(legacy_target->colorTexture(3)->readback(
            *device, 0, 0, {}, legacy_emissive_after.data(), 32 * 4,
            &error));
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(legacy_orm_after[center + channel] ==
                  legacy_orm_before[center + channel]);
            CHECK(legacy_normal_after[center + channel] ==
                  legacy_normal_before[center + channel]);
        }
        CHECK(legacy_emissive_after[center / 4] ==
              legacy_emissive_before[center / 4]);

        // A full-weight box hero replaces the ordinary bright probe with a
        // black sharp cube, returning coverage to authored diffuse alpha.
        // The sphere branch reaches the same result at its centre, while a
        // rejected mirror clip plane leaves the ordinary probe untouched.
        legacy_lighting.sun_color[0] = 0.f;
        ALMetalWorldHeroProbe invalid_hero;
        invalid_hero.constants.config[1] = 1;
        legacy_alpha_scene.hero_probe = &invalid_hero;
        auto invalid_hero_target = make_legacy_target();
        INFO(error);
        REQUIRE(invalid_hero_target);
        CHECK_FALSE(renderer->compositeImpostorPostDeferred(
            *invalid_hero_target, legacy_alpha_scene, &error));
        CHECK(error == "Metal world impostor hero probe is invalid");
        error.clear();
        legacy_alpha_scene.hero_probe = &hero_probe;
        auto hero_box_target = make_legacy_target();
        INFO(error);
        REQUIRE(hero_box_target);
        REQUIRE(renderer->compositeImpostorPostDeferred(
            *hero_box_target, legacy_alpha_scene, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(
                           read_legacy_alpha(*hero_box_target)) - 64) <= 1);

        hero_probe.constants.config[0] = 1;
        hero_probe.constants.hero_sphere[2] = -2.f;
        hero_probe.constants.hero_sphere[3] = 100.f;
        auto hero_sphere_target = make_legacy_target();
        INFO(error);
        REQUIRE(hero_sphere_target);
        REQUIRE(renderer->compositeImpostorPostDeferred(
            *hero_sphere_target, legacy_alpha_scene, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(
                           read_legacy_alpha(*hero_sphere_target)) - 64) <= 1);

        hero_probe.constants.clip_plane[3] = -1.f;
        auto hero_clipped_target = make_legacy_target();
        INFO(error);
        REQUIRE(hero_clipped_target);
        REQUIRE(renderer->compositeImpostorPostDeferred(
            *hero_clipped_target, legacy_alpha_scene, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(
                           read_legacy_alpha(*hero_clipped_target)) - 128) <= 1);
        hero_probe.constants.config[0] = 0;
        hero_probe.constants.clip_plane[3] = 1.f;
        legacy_alpha_scene.hero_probe = nullptr;
        legacy_lighting.sun_color[0] = 1.f;

        // The transparent legacy finish blends a successful screen-space
        // hit into both radiance taps before the hero override. Disable the
        // ordinary cube contribution, flip the test normal toward the view,
        // and require the red history hit to raise quarter coverage to one
        // half. A partial pack must fail closed before encoding.
        ALMetalWorldScreenSpaceReflections invalid_ssr;
        invalid_ssr.constants.config[1] = 1;
        legacy_alpha_scene.screen_space_reflections = &invalid_ssr;
        auto invalid_ssr_target = make_legacy_target();
        INFO(error);
        REQUIRE(invalid_ssr_target);
        CHECK_FALSE(renderer->compositeImpostorPostDeferred(
            *invalid_ssr_target, legacy_alpha_scene, &error));
        CHECK(error ==
              "Metal world impostor screen-space reflections are invalid");
        error.clear();

        const float saved_default_radiance_scale =
            reflection_probes.constants.ref_params[0][1];
        const float saved_radiance_scale =
            reflection_probes.constants.ref_params[1][1];
        reflection_probes.constants.ref_params[0][1] = 0.f;
        reflection_probes.constants.ref_params[1][1] = 0.f;
        legacy_alpha_batch.material_slots[0].normal_texture =
            ssr_normal.get();
        legacy_alpha_scene.screen_space_reflections = nullptr;
        auto no_ssr_target = make_legacy_target();
        INFO(error);
        REQUIRE(no_ssr_target);
        REQUIRE(renderer->compositeImpostorPostDeferred(
            *no_ssr_target, legacy_alpha_scene, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(
                           read_legacy_alpha(*no_ssr_target)) - 64) <= 1);

        legacy_alpha_scene.screen_space_reflections =
            &screen_space_reflections;
        auto ssr_target = make_legacy_target();
        INFO(error);
        REQUIRE(ssr_target);
        REQUIRE(renderer->compositeImpostorPostDeferred(
            *ssr_target, legacy_alpha_scene, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(
                           read_legacy_alpha_at(*ssr_target, 16, 8)) -
                       128) <= 2);

        // Transparent legacy SSR has no opaque roughness cutoff: GLSL
        // traces one mirror ray at full gloss and applies the authored
        // glossiness only to the final hit weight. A quarter-gloss hit is
        // therefore still strong enough to saturate this environment glare.
        legacy_alpha_batch.material_slots[0].specular_color[3] = 0.25f;
        auto low_gloss_ssr_target = make_legacy_target();
        INFO(error);
        REQUIRE(low_gloss_ssr_target);
        REQUIRE(renderer->compositeImpostorPostDeferred(
            *low_gloss_ssr_target, legacy_alpha_scene, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(read_legacy_alpha_at(
                           *low_gloss_ssr_target, 16, 8)) -
                       128) <= 2);
        legacy_alpha_batch.material_slots[0].specular_color[3] = 1.f;
        legacy_alpha_scene.screen_space_reflections = nullptr;
        legacy_alpha_batch.material_slots[0].normal_texture = nullptr;
        reflection_probes.constants.ref_params[0][1] =
            saved_default_radiance_scale;
        reflection_probes.constants.ref_params[1][1] =
            saved_radiance_scale;

        // With the probe term disabled, an aligned red sun saturates glare
        // and raises half-diffuse/half-vertex coverage from one quarter to
        // one half. Tangent-space +X and an orthogonal green specular map
        // each remove that same red highlight, proving both authored maps
        // participate in the coverage calculation.
        legacy_alpha_batch.material_slots[0].env_intensity = 0.f;
        auto sun_target = make_legacy_target();
        INFO(error);
        REQUIRE(sun_target);
        REQUIRE(renderer->compositeImpostorPostDeferred(
            *sun_target, legacy_alpha_scene, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(read_legacy_alpha(*sun_target)) -
                       128) <= 1);

        // A live raw-depth cascade applies the same forward-Z receiver
        // comparison as shadowUtil.glsl before the sun glint raises
        // coverage. The constant matrix puts every receiver at (0.5, 0.5,
        // 0.5); a stored 0.25 therefore shadows it and restores the authored
        // quarter coverage. Marking that cascade unbuilt returns fully lit.
        ALMetalTextureDescriptor shadow_descriptor;
        shadow_descriptor.type = ALMetalTextureType::texture_2d_array;
        shadow_descriptor.format = ALMetalPixelFormat::r32_float;
        shadow_descriptor.width = 8;
        shadow_descriptor.height = 8;
        shadow_descriptor.array_length = 4;
        shadow_descriptor.storage = ALMetalStorageMode::private_gpu;
        shadow_descriptor.usage = ALMetalTextureUsage::shader_read;
        shadow_descriptor.label =
            "Alchemy world legacy-alpha directional-shadow test";
        auto shadow_texture = ALMetalTexture::create(
            *device, shadow_descriptor, &error);
        INFO(error);
        REQUIRE(shadow_texture);
        auto shadow_upload = device->makeCommandBuffer(
            "Alchemy world legacy-alpha directional-shadow upload",
            &error);
        INFO(error);
        REQUIRE(shadow_upload);
        const std::array<float, 8 * 8> shadowed_depth = []
        {
            std::array<float, 8 * 8> value{};
            value.fill(0.25f);
            return value;
        }();
        const std::array<float, 8 * 8> lit_depth = []
        {
            std::array<float, 8 * 8> value{};
            value.fill(1.f);
            return value;
        }();
        for (std::uint32_t cascade = 0; cascade < 4; ++cascade)
        {
            const auto& depth = cascade == 0
                ? shadowed_depth : lit_depth;
            REQUIRE(shadow_texture->upload(
                *shadow_upload, 0, cascade, {}, depth.data(),
                8 * sizeof(float), &error));
        }
        REQUIRE(shadow_upload->commitAndWait(&error));
        INFO(error);

        ALMetalWorldDirectionalShadows directional_shadows;
        directional_shadows.depth_texture = shadow_texture.get();
        for (std::size_t cascade = 0; cascade < 4; ++cascade)
        {
            float* matrix = directional_shadows.constants
                                .shadow_matrix[cascade];
            matrix[12] = 0.5f;
            matrix[13] = 0.5f;
            matrix[14] = 0.5f;
            matrix[15] = 1.f;
        }
        directional_shadows.constants.shadow_clip[0] = 4.f;
        directional_shadows.constants.shadow_clip[1] = 8.f;
        directional_shadows.constants.shadow_clip[2] = 12.f;
        directional_shadows.constants.shadow_clip[3] = 16.f;
        directional_shadows.constants.resolution[0] = 8.f;
        directional_shadows.constants.resolution[1] = 8.f;
        directional_shadows.constants.resolution[2] = 32.f;
        directional_shadows.constants.resolution[3] = 32.f;
        directional_shadows.constants.parameters[2] = 200.f;
        directional_shadows.constants.parameters[3] = 32.f;
        directional_shadows.constants.config[0] = 4;
        directional_shadows.constants.config[1] = 0xeu;
        directional_shadows.constants.config[3] = 1;

        ALMetalWorldSimpleBatch shadowed_simple_pre_water =
            simple_pre_water;
        shadowed_simple_pre_water.pre_water_shadows = true;
        opaque_forward_scene.batches = &shadowed_simple_pre_water;
        opaque_forward_scene.batch_count = 1;
        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.reverse_z = false;
        opaque_forward_scene.reflection_probes = &reflection_probes;
        opaque_forward_scene.alpha_environment = &alpha_environment;
        opaque_forward_scene.alpha_lighting = &simple_alpha_lighting;
        opaque_forward_scene.alpha_directional_shadows = nullptr;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world pre-water alpha shadows are invalid");
        opaque_forward_scene.alpha_directional_shadows =
            &directional_shadows;
        error.clear();
        auto shadowed_simple_result = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(shadowed_simple_result);
        REQUIRE(shadowed_simple_result->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(std::abs(half_to_float(
                  pre_water_pixels[pre_water_left + 1]) - 0.0625f) <
              0.002f);

        directional_shadows.constants.config[1] = 0xfu;
        auto unbuilt_simple_result = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(unbuilt_simple_result);
        REQUIRE(unbuilt_simple_result->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(std::abs(half_to_float(
                  pre_water_pixels[pre_water_left + 1]) - 0.3125f) <
              0.002f);
        opaque_forward_scene.alpha_directional_shadows = nullptr;
        directional_shadows.constants.config[1] = 0xeu;
        legacy_alpha_scene.directional_shadows = &directional_shadows;

        auto shadow_target = make_legacy_target();
        INFO(error);
        REQUIRE(shadow_target);
        REQUIRE(renderer->compositeImpostorPostDeferred(
            *shadow_target, legacy_alpha_scene, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(
                           read_legacy_alpha(*shadow_target)) - 64) <= 1);

        directional_shadows.constants.config[3] = 3;
        auto pcss_shadow_target = make_legacy_target();
        INFO(error);
        REQUIRE(pcss_shadow_target);
        REQUIRE(renderer->compositeImpostorPostDeferred(
            *pcss_shadow_target, legacy_alpha_scene, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(
                           read_legacy_alpha(*pcss_shadow_target)) - 64) <= 1);

        directional_shadows.constants.config[1] = 0xfu;
        auto unbuilt_shadow_target = make_legacy_target();
        INFO(error);
        REQUIRE(unbuilt_shadow_target);
        REQUIRE(renderer->compositeImpostorPostDeferred(
            *unbuilt_shadow_target, legacy_alpha_scene, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(
                           read_legacy_alpha(*unbuilt_shadow_target)) -
                       128) <= 1);

        directional_shadows.constants.config[1] = 0xeu;
        directional_shadows.constants.config[2] = 1;
        directional_shadows.constants.config[3] = 1;
        auto reverse_shadow_target = make_legacy_target();
        INFO(error);
        REQUIRE(reverse_shadow_target);
        REQUIRE(renderer->compositeImpostorPostDeferred(
            *reverse_shadow_target, legacy_alpha_scene, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(
                           read_legacy_alpha(*reverse_shadow_target)) -
                       128) <= 1);
        legacy_alpha_scene.directional_shadows = nullptr;

        legacy_alpha_batch.material_slots[0].normal_texture =
            bump_normal.get();
        auto normal_map_target = make_legacy_target();
        INFO(error);
        REQUIRE(normal_map_target);
        REQUIRE(renderer->compositeImpostorPostDeferred(
            *normal_map_target, legacy_alpha_scene, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(
                           read_legacy_alpha(*normal_map_target)) - 64) <= 1);

        // The impostor-alpha legacy material uses the same raw normal-map
        // contract. Hold the bytes constant while changing only the backing
        // declaration and require its glare-derived coverage to stay exact.
        legacy_alpha_batch.material_slots[0].normal_texture =
            flat_normal.get();
        auto linear_flat_normal_target = make_legacy_target();
        INFO(error);
        REQUIRE(linear_flat_normal_target);
        REQUIRE(renderer->compositeImpostorPostDeferred(
            *linear_flat_normal_target, legacy_alpha_scene, &error));
        INFO(error);
        const std::uint8_t linear_flat_normal_alpha =
            read_legacy_alpha(*linear_flat_normal_target);
        legacy_alpha_batch.material_slots[0].normal_texture =
            srgb_flat_normal.get();
        auto srgb_flat_normal_target = make_legacy_target();
        INFO(error);
        REQUIRE(srgb_flat_normal_target);
        REQUIRE(renderer->compositeImpostorPostDeferred(
            *srgb_flat_normal_target, legacy_alpha_scene, &error));
        INFO(error);
        CHECK(read_legacy_alpha(*srgb_flat_normal_target) ==
              linear_flat_normal_alpha);

        legacy_alpha_batch.material_slots[0].normal_texture = nullptr;
        legacy_alpha_batch.material_slots[0].specular_texture =
            indexed_diffuse.get();
        auto specular_map_target = make_legacy_target();
        INFO(error);
        REQUIRE(specular_map_target);
        REQUIRE(renderer->compositeImpostorPostDeferred(
            *specular_map_target, legacy_alpha_scene, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(
                           read_legacy_alpha(*specular_map_target)) - 64) <= 1);

        legacy_alpha_batch.material_slots[0].specular_texture = nullptr;
        legacy_alpha_batch.material_slots[0].fullbright = 1.f;
        auto emissive_target = make_legacy_target();
        INFO(error);
        REQUIRE(emissive_target);
        REQUIRE(renderer->compositeImpostorPostDeferred(
            *emissive_target, legacy_alpha_scene, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(
                           read_legacy_alpha(*emissive_target)) - 64) <= 1);

        // Punctual glare follows the same legacy attenuation and spot/omni
        // contract as deferredUtil.glsl. Disable the sun, place an omni light
        // one metre above the eye-space surface and require raised coverage.
        legacy_alpha_batch.material_slots[0].fullbright = 0.f;
        legacy_lighting.sun_color[0] = 0.f;
        legacy_lighting.local_lights[0].position[2] = -0.75f;
        legacy_lighting.local_lights[0].diffuse[0] = 1.f;
        legacy_lighting.local_lights[0].parameters[0] = 4.f;
        legacy_lighting.local_lights[0].parameters[1] = 0.f;
        legacy_lighting.local_lights[0].parameters[2] = 1.f;
        auto local_light_target = make_legacy_target();
        INFO(error);
        REQUIRE(local_light_target);
        REQUIRE(renderer->compositeImpostorPostDeferred(
            *local_light_target, legacy_alpha_scene, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(
                           read_legacy_alpha(*local_light_target)) - 128) <= 1);

        // Object-skinned legacy alpha uses the same probe/material inputs but
        // writes depth, while the static variant above kept depth read-only.
        legacy_lighting.local_lights[0] = {};
        legacy_alpha_batch.material_slots[0].env_intensity = 1.f;
        legacy_alpha_batch.skin_palette = alpha_skin_palette.data();
        legacy_alpha_batch.skin_palette_float_count =
            alpha_skin_palette.size();
        legacy_alpha_batch.skin_joint_count = 1;
        legacy_alpha_batch.weight_offset = weight_offset;
        auto rigged_legacy_target = make_legacy_target();
        INFO(error);
        REQUIRE(rigged_legacy_target);
        REQUIRE(renderer->compositeImpostorPostDeferred(
            *rigged_legacy_target, legacy_alpha_scene, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(
                           read_legacy_alpha(*rigged_legacy_target)) -
                       128) <= 1);
        CHECK(std::abs(read_legacy_depth(*rigged_legacy_target) - 0.625f) <
              0.0001f);
        legacy_alpha_batch.skin_palette = nullptr;
        legacy_alpha_batch.skin_palette_float_count = 0;
        legacy_alpha_batch.skin_joint_count = 0;
        legacy_alpha_batch.weight_offset = 0;

        // The main-world legacy-material owner keeps materialF's lit RGB,
        // unlike the impostor fragment above, while retaining the same
        // glare-dependent coverage. Start with its fullbright mix so the
        // expected source is exactly decoded diffuse times decoded vertex
        // tint, then execute the same draw through static and rigged
        // pipelines over the retained final-color/depth target.
        ALMetalWorldSimpleBatch pre_water_material = legacy_alpha_batch;
        pre_water_material.pre_water_alpha = true;
        pre_water_material.pre_water_material = true;
        pre_water_material.pre_water_shadows = false;
        pre_water_material.material_slots[0].specular_color[3] = 0.f;
        pre_water_material.material_slots[0].env_intensity = 0.f;
        pre_water_material.material_slots[0].fullbright = 1.f;
        ALMetalWorldSimpleBatch pre_water_material_rigged =
            pre_water_material;
        pre_water_material_rigged.skin_palette = alpha_skin_palette.data();
        pre_water_material_rigged.skin_palette_float_count =
            alpha_skin_palette.size();
        pre_water_material_rigged.skin_joint_count = 1;
        pre_water_material_rigged.weight_offset = weight_offset;

        opaque_forward_scene.batches = &pre_water_material;
        opaque_forward_scene.batch_count = 1;
        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.reverse_z = false;
        opaque_forward_scene.reflection_probes = &reflection_probes;
        opaque_forward_scene.hero_probe = nullptr;
        opaque_forward_scene.screen_space_reflections = nullptr;
        opaque_forward_scene.alpha_environment = &alpha_environment;
        opaque_forward_scene.alpha_lighting = nullptr;
        opaque_forward_scene.alpha_directional_shadows = nullptr;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world pre-water alpha lighting is invalid");
        opaque_forward_scene.alpha_lighting = &simple_alpha_lighting;
        error.clear();
        auto material_fullbright_result =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(material_fullbright_result);
        REQUIRE(material_fullbright_result->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        REQUIRE(material_fullbright_result->depthStencilTexture()->readback(
            *device, 0, 0, {}, pre_water_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        const float material_coverage = coverage * coverage;
        const float material_uncovered = 1.f - material_coverage;
        const std::array<float, 3> material_source{{
            srgb_to_linear(128.f / 255.f) *
                srgb_to_linear(128.f / 255.f),
            srgb_to_linear(64.f / 255.f),
            srgb_to_linear(32.f / 255.f),
        }};
        const std::array<float, 3> retained_color{{
            0.25f, 0.125f, 0.0625f,
        }};
        const std::size_t material_pixel = center;
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            CHECK(std::abs(
                half_to_float(pre_water_pixels[
                    material_pixel + channel]) -
                (material_source[channel] * material_coverage +
                 retained_color[channel] * material_uncovered)) <
                0.002f);
        }
        CHECK(std::abs(
            half_to_float(pre_water_pixels[material_pixel + 3]) -
            0.5f * material_uncovered) < 0.002f);
        CHECK(std::abs(pre_water_depth[material_pixel / 4] - 0.625f) <
              0.0001f);

        opaque_forward_scene.batches = &pre_water_material_rigged;
        auto material_rigged_result = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(material_rigged_result);
        REQUIRE(material_rigged_result->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            CHECK(std::abs(
                half_to_float(pre_water_pixels[
                    material_pixel + channel]) -
                (material_source[channel] * material_coverage +
                 retained_color[channel] * material_uncovered)) <
                0.002f);
        }

        // Restore lit material behavior. A shadowed cascade removes the
        // modern directional term without changing authored coverage; the
        // all-unbuilt mask restores the fully lit result.
        pre_water_material.material_slots[0].fullbright = 0.f;
        pre_water_material.pre_water_shadows = true;
        opaque_forward_scene.batches = &pre_water_material;
        directional_shadows.constants.config[1] = 0xeu;
        directional_shadows.constants.config[2] = 0;
        directional_shadows.constants.config[3] = 1;
        opaque_forward_scene.alpha_directional_shadows =
            &directional_shadows;
        auto shadowed_material_result =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(shadowed_material_result);
        REQUIRE(shadowed_material_result->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            CHECK(std::abs(
                half_to_float(pre_water_pixels[
                    material_pixel + channel]) -
                retained_color[channel] * material_uncovered) < 0.002f);
        }
        directional_shadows.constants.config[1] = 0xfu;
        auto unbuilt_material_result =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(unbuilt_material_result);
        REQUIRE(unbuilt_material_result->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(half_to_float(
                  pre_water_pixels[material_pixel + 1]) >
              retained_color[1] * material_uncovered);
        opaque_forward_scene.alpha_directional_shadows = nullptr;
        directional_shadows.constants.config[1] = 0xeu;

        // The material fragment's fixed resource contract consumes the
        // same coherent hero/SSR finish as materialF.glsl. Invalid partial
        // packs fail before encoding. With direct light disabled, the
        // ordinary bright probe raises blue radiance and glare; the valid
        // black hero override removes both.
        pre_water_material.pre_water_shadows = false;
        pre_water_material.material_slots[0].specular_color[3] = 1.f;
        pre_water_material.material_slots[0].env_intensity = 1.f;
        alpha_environment.atmos_sunlit_linear[0] = 0.f;
        alpha_environment.atmos_sunlit_linear[1] = 0.f;
        alpha_environment.atmos_sunlit_linear[2] = 0.f;
        opaque_forward_scene.hero_probe = &invalid_hero;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world opaque post-deferred hero probe is invalid");
        opaque_forward_scene.hero_probe = nullptr;
        opaque_forward_scene.screen_space_reflections = &invalid_ssr;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world opaque post-deferred screen-space reflections are invalid");
        opaque_forward_scene.screen_space_reflections = nullptr;
        error.clear();
        auto ordinary_material_result =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(ordinary_material_result);
        REQUIRE(ordinary_material_result->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        const float ordinary_material_blue = half_to_float(
            pre_water_pixels[material_pixel + 2]);
        const float ordinary_material_alpha = half_to_float(
            pre_water_pixels[material_pixel + 3]);

        opaque_forward_scene.hero_probe = &hero_probe;
        auto hero_material_result = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(hero_material_result);
        REQUIRE(hero_material_result->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(ordinary_material_blue > half_to_float(
                  pre_water_pixels[material_pixel + 2]));
        CHECK(ordinary_material_alpha < half_to_float(
                  pre_water_pixels[material_pixel + 3]));
        opaque_forward_scene.hero_probe = nullptr;

        // A tangent-space reverse normal makes the transparent one-ray SSR
        // fixture hit its red lower-row history. Disable ordinary radiance
        // so the comparison isolates normal-map sampling, screen Y
        // orientation and the paired color/depth finish.
        const float material_default_radiance_scale =
            reflection_probes.constants.ref_params[0][1];
        const float material_radiance_scale =
            reflection_probes.constants.ref_params[1][1];
        reflection_probes.constants.ref_params[0][1] = 0.f;
        reflection_probes.constants.ref_params[1][1] = 0.f;
        pre_water_material.material_slots[0].normal_texture =
            ssr_normal.get();
        auto no_ssr_material_result =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(no_ssr_material_result);
        REQUIRE(no_ssr_material_result->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        const float no_ssr_material_red = half_to_float(
            pre_water_pixels[material_pixel + 0]);
        opaque_forward_scene.screen_space_reflections =
            &screen_space_reflections;
        auto ssr_material_result = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(ssr_material_result);
        REQUIRE(ssr_material_result->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(half_to_float(pre_water_pixels[material_pixel + 0]) >
              no_ssr_material_red);
        opaque_forward_scene.screen_space_reflections = nullptr;
        pre_water_material.material_slots[0].normal_texture = nullptr;
        reflection_probes.constants.ref_params[0][1] =
            material_default_radiance_scale;
        reflection_probes.constants.ref_params[1][1] =
            material_radiance_scale;

        // Local-light RGB uses the full legacy diffuse/specular model, not
        // the simple-alpha diffuse-only helper. With authored gloss and the
        // environment disabled it must add visible green over the retained
        // background while also preserving the coverage contract.
        pre_water_material.material_slots[0].env_intensity = 0.f;
        pre_water_material.material_slots[0].specular_color[3] = 0.f;
        simple_alpha_lighting.local_lights[0].position[2] = 10.f;
        simple_alpha_lighting.local_lights[0].diffuse[1] = 0.5f;
        simple_alpha_lighting.local_lights[0].parameters[0] = 100.f;
        simple_alpha_lighting.local_lights[0].parameters[2] = 1.f;
        pre_water_material.material_slots[0].normal_texture =
            flat_normal.get();
        auto local_material_result = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(local_material_result);
        REQUIRE(local_material_result->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(half_to_float(pre_water_pixels[material_pixel + 1]) >
              retained_color[1] * material_uncovered);
        std::array<std::uint16_t, 4> linear_legacy_alpha_color{};
        std::copy_n(pre_water_pixels.begin() + material_pixel, 4,
                    linear_legacy_alpha_color.begin());
        pre_water_material.material_slots[0].normal_texture =
            srgb_flat_normal.get();
        auto srgb_local_material_result =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(srgb_local_material_result);
        REQUIRE(srgb_local_material_result->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(pre_water_pixels[material_pixel + channel] ==
                  linear_legacy_alpha_color[channel]);
        }
        pre_water_material.material_slots[0].normal_texture = nullptr;
        simple_alpha_lighting.local_lights[0] = {};
        alpha_environment.atmos_sunlit_linear[0] = 1.f;
        alpha_environment.atmos_sunlit_linear[1] = 0.5f;
        alpha_environment.atmos_sunlit_linear[2] = 0.25f;

        // The glTF BLEND owner stays in the main-world forward slice rather
        // than falling back to its flat impostor bake. It consumes the same
        // four-map material, probe/BRDF, directional-shadow and seven-light
        // contracts as pbralphaF.glsl. Exercise the source-over static and
        // rigged pipelines first with an emissive-only source so the result
        // remains independent of direct-light and radiance-probe terms.
        ALMetalWorldSimpleBatch pre_water_pbr = legacy_alpha_batch;
        pre_water_pbr.pre_water_alpha = true;
        pre_water_pbr.pre_water_material = false;
        pre_water_pbr.pre_water_pbr = true;
        pre_water_pbr.pre_water_shadows = false;
        pre_water_pbr.material_slot_count = 0;
        pre_water_pbr.material_alpha_mode = 0;
        pre_water_pbr.pbr_slot_count = 1;
        pre_water_pbr.texture_count = 1;
        pre_water_pbr.diffuse_textures[0] = tree_diffuse.get();
        pre_water_pbr.double_sided = true;
        ALMetalWorldPBRSlot& pre_water_pbr_slot =
            pre_water_pbr.pbr_slots[0];
        pre_water_pbr_slot.normal_texture = flat_normal.get();
        pre_water_pbr_slot.orm_texture = pbr_orm_texture.get();
        pre_water_pbr_slot.emissive_texture = diffuse.get();
        pre_water_pbr_slot.emissive_color[1] = 1.f;
        pre_water_pbr_slot.roughness_factor = 1.f;
        pre_water_pbr_slot.metallic_factor = 0.f;
        pre_water_pbr_slot.alpha_cutoff = -1.f;
        ALMetalWorldSimpleBatch pre_water_pbr_rigged = pre_water_pbr;
        pre_water_pbr_rigged.skin_palette = alpha_skin_palette.data();
        pre_water_pbr_rigged.skin_palette_float_count =
            alpha_skin_palette.size();
        pre_water_pbr_rigged.skin_joint_count = 1;
        pre_water_pbr_rigged.weight_offset = weight_offset;

        opaque_forward_scene.batches = &pre_water_pbr;
        opaque_forward_scene.batch_count = 1;
        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.reverse_z = false;
        opaque_forward_scene.reflection_probes = &reflection_probes;
        opaque_forward_scene.hero_probe = nullptr;
        opaque_forward_scene.screen_space_reflections = nullptr;
        opaque_forward_scene.alpha_environment = &alpha_environment;
        opaque_forward_scene.alpha_lighting = &simple_alpha_lighting;
        opaque_forward_scene.alpha_directional_shadows = nullptr;
        pre_water_pbr_slot.normal_texture = nullptr;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world pre-water PBR slot is invalid");
        pre_water_pbr_slot.normal_texture = flat_normal.get();
        pre_water_pbr_slot.alpha_cutoff = 0.5f;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world pre-water PBR slot is invalid");
        pre_water_pbr_slot.alpha_cutoff = -1.f;

        const float pbr_default_radiance_scale =
            reflection_probes.constants.ref_params[0][1];
        const float pbr_radiance_scale =
            reflection_probes.constants.ref_params[1][1];
        reflection_probes.constants.ref_params[0][1] = 0.f;
        reflection_probes.constants.ref_params[1][1] = 0.f;
        alpha_environment.atmos_sunlit_linear[0] = 0.f;
        alpha_environment.atmos_sunlit_linear[1] = 0.f;
        alpha_environment.atmos_sunlit_linear[2] = 0.f;
        error.clear();
        auto static_pbr_alpha_result =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(static_pbr_alpha_result);
        REQUIRE(static_pbr_alpha_result->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        REQUIRE(static_pbr_alpha_result->depthStencilTexture()->readback(
            *device, 0, 0, {}, pre_water_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        std::array<float, 4> static_pbr_pixel{};
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            static_pbr_pixel[channel] = half_to_float(
                pre_water_pixels[material_pixel + channel]);
            CHECK(std::isfinite(static_pbr_pixel[channel]));
        }
        CHECK(static_pbr_pixel[1] >
              retained_color[1] * material_uncovered);
        const float static_pbr_depth =
            pre_water_depth[material_pixel / 4];

        opaque_forward_scene.batches = &pre_water_pbr_rigged;
        auto rigged_pbr_alpha_result =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(rigged_pbr_alpha_result);
        REQUIRE(rigged_pbr_alpha_result->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        REQUIRE(rigged_pbr_alpha_result->depthStencilTexture()->readback(
            *device, 0, 0, {}, pre_water_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(std::abs(
                half_to_float(pre_water_pixels[
                    material_pixel + channel]) -
                static_pbr_pixel[channel]) < 0.002f);
        }
        CHECK(std::abs(pre_water_depth[material_pixel / 4] -
                       static_pbr_depth) < 0.0001f);

        // A built cascade removes the aligned modern sun term; marking all
        // four cascades unbuilt restores it. This proves the PBR owner uses
        // the demanded live shadow state instead of silently rendering an
        // unshadowed approximation.
        opaque_forward_scene.batches = &pre_water_pbr;
        pre_water_pbr_slot.emissive_color[1] = 0.f;
        pre_water_pbr.pre_water_shadows = true;
        alpha_environment.atmos_sunlit_linear[0] = 1.f;
        alpha_environment.atmos_sunlit_linear[1] = 0.5f;
        alpha_environment.atmos_sunlit_linear[2] = 0.25f;
        directional_shadows.constants.config[1] = 0xeu;
        opaque_forward_scene.alpha_directional_shadows =
            &directional_shadows;
        auto shadowed_pbr_alpha_result =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(shadowed_pbr_alpha_result);
        REQUIRE(shadowed_pbr_alpha_result->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        const float shadowed_pbr_green = half_to_float(
            pre_water_pixels[material_pixel + 1]);
        directional_shadows.constants.config[1] = 0xfu;
        auto unbuilt_pbr_alpha_result =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(unbuilt_pbr_alpha_result);
        REQUIRE(unbuilt_pbr_alpha_result->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(half_to_float(pre_water_pixels[material_pixel + 1]) >
              shadowed_pbr_green);

        // With directional and probe radiance disabled, an aligned green
        // punctual light must still raise the PBR diffuse lobe.
        pre_water_pbr.pre_water_shadows = false;
        opaque_forward_scene.alpha_directional_shadows = nullptr;
        alpha_environment.atmos_sunlit_linear[0] = 0.f;
        alpha_environment.atmos_sunlit_linear[1] = 0.f;
        alpha_environment.atmos_sunlit_linear[2] = 0.f;
        simple_alpha_lighting.local_lights[0].position[2] = 10.f;
        simple_alpha_lighting.local_lights[0].diffuse[1] = 2.f;
        simple_alpha_lighting.local_lights[0].parameters[0] = 100.f;
        simple_alpha_lighting.local_lights[0].parameters[2] = 1.f;
        auto local_pbr_alpha_result =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(local_pbr_alpha_result);
        REQUIRE(local_pbr_alpha_result->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(half_to_float(pre_water_pixels[material_pixel + 1]) >
              retained_color[1] * material_uncovered);

        // GLTF_DATA_SAMPLER suppresses sRGB decoding for normal and ORM
        // maps even when an asset image shares sRGB storage with a colour
        // reference. Identical raw bytes must therefore shade identically
        // in the blended PBR owner, just as they do in the opaque G-buffer.
        std::array<std::uint16_t, 4> linear_pbr_data_color{};
        std::copy_n(pre_water_pixels.begin() + material_pixel, 4,
                    linear_pbr_data_color.begin());
        pre_water_pbr_slot.normal_texture = srgb_flat_normal.get();
        pre_water_pbr_slot.orm_texture = srgb_pbr_orm_texture.get();
        auto srgb_pbr_data_result = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(srgb_pbr_data_result);
        REQUIRE(srgb_pbr_data_result->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(pre_water_pixels[material_pixel + channel] ==
                  linear_pbr_data_color[channel]);
        }
        pre_water_pbr_slot.normal_texture = flat_normal.get();
        pre_water_pbr_slot.orm_texture = pbr_orm_texture.get();
        simple_alpha_lighting.local_lights[0] = {};

        // Finish the glossy radiance lobe through the same ordinary, SSR,
        // then hero order as pbralphaF.glsl. A black hero removes the blue
        // ordinary cube; with ordinary radiance disabled, the paired red
        // scene-history hit raises only the SSR-enabled result.
        reflection_probes.constants.ref_params[0][1] =
            pbr_default_radiance_scale;
        reflection_probes.constants.ref_params[1][1] =
            pbr_radiance_scale;
        pre_water_pbr_slot.roughness_factor = 0.f;
        pre_water_pbr_slot.metallic_factor = 1.f;

        // The production probe walk can leave its depth-sorted list for a
        // selected probe's neighbor list. A containing manual box reached
        // that way must suppress every automatic tap already accumulated,
        // including the default probe. Keep both array layers distinct so
        // this is an asymmetric physical control: without the neighbor edge
        // the red automatic/default family wins; with it, the blue manual
        // box is the only surviving family.
        ALMetalWorldReflectionProbes neighbor_probes = reflection_probes;
        neighbor_probes.constants.config[0] = 3.f;
        neighbor_probes.constants.ref_sphere[1][0] = 0.f;
        neighbor_probes.constants.ref_sphere[1][1] = 0.f;
        neighbor_probes.constants.ref_sphere[1][2] = 0.f;
        neighbor_probes.constants.ref_sphere[1][3] = 100.f;
        neighbor_probes.constants.ref_params[1][0] = 0.f;
        neighbor_probes.constants.ref_params[1][1] = 1.f;
        neighbor_probes.constants.ref_params[1][2] = 1.f;
        neighbor_probes.constants.ref_params[1][3] = -100.f;
        neighbor_probes.constants.ref_index[1][0] = 0;
        neighbor_probes.constants.ref_index[1][1] = -1;
        neighbor_probes.constants.ref_index[1][2] = 0;
        neighbor_probes.constants.ref_index[1][3] = 0;
        neighbor_probes.constants.ref_sphere[2][0] = 0.f;
        neighbor_probes.constants.ref_sphere[2][1] = 0.f;
        neighbor_probes.constants.ref_sphere[2][2] = 0.f;
        neighbor_probes.constants.ref_sphere[2][3] = 100.f;
        neighbor_probes.constants.ref_params[2][0] = 0.f;
        neighbor_probes.constants.ref_params[2][1] = 1.f;
        neighbor_probes.constants.ref_params[2][2] = 1.f;
        // Keep the box beyond the sorted walk; it is admitted only through
        // the neighbor edge below.
        neighbor_probes.constants.ref_params[2][3] = 100.f;
        neighbor_probes.constants.ref_index[2][0] = 1;
        neighbor_probes.constants.ref_index[2][1] = -1;
        neighbor_probes.constants.ref_index[2][2] = 0;
        neighbor_probes.constants.ref_index[2][3] = -1;
        neighbor_probes.constants.ref_box[2][0] = 0.25f;
        neighbor_probes.constants.ref_box[2][5] = 0.25f;
        neighbor_probes.constants.ref_box[2][10] = 0.25f;
        neighbor_probes.constants.ref_box[2][15] = 1.f;
        neighbor_probes.constants.ref_neighbor[0] = 2;

        opaque_forward_scene.reflection_probes = &neighbor_probes;
        auto automatic_probe_result =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(automatic_probe_result);
        REQUIRE(automatic_probe_result->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        const float automatic_probe_red = half_to_float(
            pre_water_pixels[material_pixel + 0]);
        const float automatic_probe_blue = half_to_float(
            pre_water_pixels[material_pixel + 2]);
        CHECK(automatic_probe_red > automatic_probe_blue);

        neighbor_probes.constants.ref_index[1][1] = 0;
        neighbor_probes.constants.ref_index[1][2] = 1;
        auto neighbor_box_result = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(neighbor_box_result);
        REQUIRE(neighbor_box_result->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        const float neighbor_box_red = half_to_float(
            pre_water_pixels[material_pixel + 0]);
        const float neighbor_box_blue = half_to_float(
            pre_water_pixels[material_pixel + 2]);
        CHECK(neighbor_box_blue > automatic_probe_blue);
        CHECK(neighbor_box_red < automatic_probe_red);
        opaque_forward_scene.reflection_probes = &reflection_probes;

        auto ordinary_pbr_alpha_result =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(ordinary_pbr_alpha_result);
        REQUIRE(ordinary_pbr_alpha_result->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        const float ordinary_pbr_blue = half_to_float(
            pre_water_pixels[material_pixel + 2]);
        opaque_forward_scene.hero_probe = &hero_probe;
        auto hero_pbr_alpha_result =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(hero_pbr_alpha_result);
        REQUIRE(hero_pbr_alpha_result->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(ordinary_pbr_blue > half_to_float(
                  pre_water_pixels[material_pixel + 2]));
        opaque_forward_scene.hero_probe = nullptr;

        reflection_probes.constants.ref_params[0][1] = 0.f;
        reflection_probes.constants.ref_params[1][1] = 0.f;
        pre_water_pbr_slot.normal_texture = ssr_normal.get();
        auto no_ssr_pbr_alpha_result =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(no_ssr_pbr_alpha_result);
        REQUIRE(no_ssr_pbr_alpha_result->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        const float no_ssr_pbr_red = half_to_float(
            pre_water_pixels[material_pixel + 0]);
        opaque_forward_scene.screen_space_reflections =
            &screen_space_reflections;
        auto ssr_pbr_alpha_result =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(ssr_pbr_alpha_result);
        REQUIRE(ssr_pbr_alpha_result->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(half_to_float(pre_water_pixels[material_pixel + 0]) >
              no_ssr_pbr_red);
        opaque_forward_scene.screen_space_reflections = nullptr;
        pre_water_pbr_slot.normal_texture = flat_normal.get();
        pre_water_pbr_slot.roughness_factor = 1.f;
        pre_water_pbr_slot.metallic_factor = 0.f;
        alpha_environment.atmos_sunlit_linear[0] = 1.f;
        alpha_environment.atmos_sunlit_linear[1] = 0.5f;
        alpha_environment.atmos_sunlit_linear[2] = 0.25f;
        reflection_probes.constants.ref_params[0][1] =
            pbr_default_radiance_scale;
        reflection_probes.constants.ref_params[1][1] =
            pbr_radiance_scale;
        directional_shadows.constants.config[1] = 0xeu;

        // GLSL calls mirrorClip for flat/simple alpha, legacy BLEND
        // materials, glTF PBR alpha and the earlier forward fullbright/shiny
        // families. These draws happen after the opaque G-buffer, so clipped
        // opaque depth cannot stand in for clipping the replayed geometry.
        // Cross the eye-space x=0 plane with each native vertex family: both
        // halves must draw normally, while the mirror variant must reject
        // every negative-x fragment and keep the positive half at exactly the
        // same depth.
        const auto check_mirror_clipped_forward =
            [&](ALMetalWorldSimpleBatch mirror_batch)
        {
            std::fill(std::begin(mirror_batch.modelview),
                      std::end(mirror_batch.modelview), 0.f);
            std::fill(std::begin(mirror_batch.modelview_projection),
                      std::end(mirror_batch.modelview_projection), 0.f);
            for (std::size_t diagonal = 0; diagonal < 4; ++diagonal)
            {
                mirror_batch.modelview[diagonal * 4 + diagonal] = 1.f;
                mirror_batch.modelview_projection[
                    diagonal * 4 + diagonal] = 1.f;
            }
            mirror_batch.modelview_projection[14] = -0.25f;
            mirror_batch.skin_palette = nullptr;
            mirror_batch.skin_palette_float_count = 0;
            mirror_batch.skin_joint_count = 0;
            mirror_batch.weight_offset = 0;

            opaque_forward_scene.batches = &mirror_batch;
            opaque_forward_scene.batch_count = 1;
            opaque_forward_scene.gbuffer = coverage_result.get();
            opaque_forward_scene.reverse_z = false;
            opaque_forward_scene.alpha_environment = &alpha_environment;
            opaque_forward_scene.alpha_lighting =
                &simple_alpha_lighting;
            opaque_forward_scene.alpha_directional_shadows = nullptr;
            opaque_forward_scene.mirror_clip = false;
            auto ordinary = renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
            INFO(error);
            REQUIRE(ordinary);
            std::array<float, 32 * 32> ordinary_depth{};
            REQUIRE(ordinary->depthStencilTexture()->readback(
                *device, 0, 0, {}, ordinary_depth.data(),
                32 * sizeof(float), &error));
            INFO(error);

            std::size_t ordinary_negative = 0;
            std::size_t ordinary_positive = 0;
            for (std::size_t y = 0; y < 32; ++y)
            {
                for (std::size_t x = 0; x < 32; ++x)
                {
                    if (std::abs(ordinary_depth[y * 32 + x] - 0.5f) <
                        0.0001f)
                    {
                        (x < 16 ? ordinary_negative : ordinary_positive)++;
                    }
                }
            }
            CHECK(ordinary_negative > 0);
            CHECK(ordinary_positive > 0);

            opaque_forward_scene.mirror_clip_plane[0] = 1.f;
            opaque_forward_scene.mirror_clip_plane[1] = 0.f;
            opaque_forward_scene.mirror_clip_plane[2] = 0.f;
            opaque_forward_scene.mirror_clip_plane[3] = 0.f;
            opaque_forward_scene.mirror_clip = true;
            auto clipped = renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
            INFO(error);
            REQUIRE(clipped);
            std::array<float, 32 * 32> clipped_depth{};
            REQUIRE(clipped->depthStencilTexture()->readback(
                *device, 0, 0, {}, clipped_depth.data(),
                32 * sizeof(float), &error));
            INFO(error);

            std::size_t clipped_negative = 0;
            std::size_t clipped_positive = 0;
            for (std::size_t y = 0; y < 32; ++y)
            {
                for (std::size_t x = 0; x < 32; ++x)
                {
                    if (std::abs(clipped_depth[y * 32 + x] - 0.5f) <
                        0.0001f)
                    {
                        (x < 16 ? clipped_negative : clipped_positive)++;
                    }
                }
            }
            CHECK(clipped_negative == 0);
            CHECK(clipped_positive == ordinary_positive);
            opaque_forward_scene.mirror_clip = false;
        };

        check_mirror_clipped_forward(pre_water_alpha);
        check_mirror_clipped_forward(pre_water_material);
        check_mirror_clipped_forward(pre_water_pbr);
        check_mirror_clipped_forward(normal_free_fullbright);
        ALMetalWorldSimpleBatch mirror_shiny = fullbright_batch;
        mirror_shiny.impostor_fullbright = false;
        mirror_shiny.impostor_shiny = true;
        mirror_shiny.alpha_mask = false;
        check_mirror_clipped_forward(mirror_shiny);

        // Particle batches differ from otherwise identical fullbright alpha
        // in two production states: anisotropic clamp sampling and disabled
        // culling. Shift a red/green two-texel source beyond U=1 so wrap
        // resolves red while the particle path clamps to green.
        ALMetalWorldSimpleBatch particle_alpha = legacy_alpha_batch;
        particle_alpha.pre_water_alpha = true;
        particle_alpha.pre_water_fullbright = true;
        particle_alpha.pre_water_material = false;
        particle_alpha.pre_water_pbr = false;
        particle_alpha.pre_water_shadows = false;
        particle_alpha.material_slot_count = 0;
        particle_alpha.material_alpha_mode = 0;
        particle_alpha.pbr_slot_count = 0;
        particle_alpha.texture_count = 1;
        particle_alpha.diffuse_textures[0] = pbr_base_texture.get();
        particle_alpha.texture_matrix[12] = 1.25f;
        particle_alpha.pre_water_particle = false;
        particle_alpha.pre_water_minimum_alpha = 0.004f;
        particle_alpha.pre_water_source_rgb =
            ALMetalBlendFactor::source_alpha;
        particle_alpha.pre_water_destination_rgb =
            ALMetalBlendFactor::one_minus_source_alpha;
        opaque_forward_scene.batches = &particle_alpha;
        auto wrapped_alpha_result = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(wrapped_alpha_result);
        REQUIRE(wrapped_alpha_result->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        const float wrapped_particle_red = half_to_float(
            pre_water_pixels[material_pixel + 0]);
        const float wrapped_particle_green = half_to_float(
            pre_water_pixels[material_pixel + 1]);

        particle_alpha.pre_water_particle = true;
        auto clamped_alpha_result = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(clamped_alpha_result);
        REQUIRE(clamped_alpha_result->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(half_to_float(pre_water_pixels[material_pixel + 0]) <
              wrapped_particle_red);
        CHECK(half_to_float(pre_water_pixels[material_pixel + 1]) >
              wrapped_particle_green);

        // When neither custom RGB factor is SOURCE_ALPHA, GL lowers the
        // cutoff to zero. A zero-alpha coloured texel must therefore execute
        // the lazy ONE/ONE pipeline and add RGB while destination alpha keeps
        // the pool's fixed ZERO/ONE_MINUS_SOURCE_ALPHA recurrence.
        ALMetalWorldSimpleBatch custom_alpha = particle_alpha;
        custom_alpha.pre_water_particle = false;
        custom_alpha.diffuse_textures[0] = zero_alpha_diffuse.get();
        custom_alpha.texture_matrix[12] = 0.f;
        custom_alpha.pre_water_minimum_alpha = 0.f;
        custom_alpha.pre_water_source_rgb = ALMetalBlendFactor::one;
        custom_alpha.pre_water_destination_rgb = ALMetalBlendFactor::one;
        opaque_forward_scene.batches = &custom_alpha;
        auto custom_alpha_result = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(custom_alpha_result);
        REQUIRE(custom_alpha_result->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(half_to_float(pre_water_pixels[material_pixel + 0]) >
              retained_color[0]);
        CHECK(std::abs(
            half_to_float(pre_water_pixels[material_pixel + 3]) -
            0.5f) < 0.002f);

        custom_alpha.pre_water_minimum_alpha = 0.002f;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error.find(
                  "Metal world opaque post-deferred batch is invalid") == 0);
        custom_alpha.pre_water_minimum_alpha = 0.f;
        error.clear();

        // Material family and skinning select distinct custom pipeline
        // entries. Execute every family so none can silently retain the
        // source-over descriptor while the shared blend key says otherwise.
        ALMetalWorldSimpleBatch custom_alpha_rigged = custom_alpha;
        custom_alpha_rigged.skin_palette = alpha_skin_palette.data();
        custom_alpha_rigged.skin_palette_float_count =
            alpha_skin_palette.size();
        custom_alpha_rigged.skin_joint_count = 1;
        custom_alpha_rigged.weight_offset = weight_offset;
        opaque_forward_scene.batches = &custom_alpha_rigged;
        auto custom_alpha_rigged_result =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(custom_alpha_rigged_result);

        ALMetalWorldSimpleBatch custom_simple = simple_pre_water;
        custom_simple.pre_water_source_rgb = ALMetalBlendFactor::one;
        custom_simple.pre_water_destination_rgb = ALMetalBlendFactor::one;
        custom_simple.pre_water_minimum_alpha = 0.f;
        opaque_forward_scene.batches = &custom_simple;
        auto custom_simple_result = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(custom_simple_result);

        ALMetalWorldSimpleBatch custom_material = pre_water_material;
        custom_material.pre_water_source_rgb = ALMetalBlendFactor::one;
        custom_material.pre_water_destination_rgb = ALMetalBlendFactor::one;
        custom_material.pre_water_minimum_alpha = 0.f;
        opaque_forward_scene.batches = &custom_material;
        auto custom_material_result = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(custom_material_result);

        ALMetalWorldSimpleBatch custom_pbr = pre_water_pbr;
        custom_pbr.pre_water_source_rgb = ALMetalBlendFactor::one;
        custom_pbr.pre_water_destination_rgb = ALMetalBlendFactor::one;
        custom_pbr.pre_water_minimum_alpha = 0.f;
        opaque_forward_scene.batches = &custom_pbr;
        auto custom_pbr_result = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(custom_pbr_result);

        // Flat class-3 underwater water follows the complete pre-water
        // family. It snapshots the retained color before sampling it,
        // preserves destination alpha, writes surface depth, and redraws
        // exclusion-stencilled pixels undistorted without marking them as
        // ordinary surface pixels.
        const std::array<float, 2> underwater_surface_cell{{-0.5f, 1.f}};
        auto underwater_surface_upload = device->makeCommandBuffer(
            "Alchemy underwater surface height upload", &error);
        REQUIRE(underwater_surface_upload);
        REQUIRE(water_cell_map->upload(
            *underwater_surface_upload, 0, 0, {},
            underwater_surface_cell.data(),
            sizeof(underwater_surface_cell), &error));
        REQUIRE(underwater_surface_upload->commitAndWait(&error));

        ALMetalWorldWaterHaze underwater_marker_haze = water_haze;
        underwater_marker_haze.above_water = false;
        underwater_marker_haze.cell_map = nullptr;
        underwater_marker_haze.draw_count = 0;
        underwater_marker_haze.water_plane[0] = 0.f;
        underwater_marker_haze.water_plane[1] = 0.f;
        underwater_marker_haze.water_plane[2] = 1.f;
        underwater_marker_haze.water_plane[3] = 1.f;
        underwater_marker_haze.fog[0] = 1.f;
        underwater_marker_haze.fog[1] = 0.f;

        ALMetalWorldWaterSurface underwater_surface;
        underwater_surface.field = water_haze;
        underwater_surface.field.above_water = true;
        underwater_surface.field.cell_map = water_cell_map.get();
        underwater_surface.field.default_height[0] = -0.5f;
        underwater_surface.field.water_plane[0] = 0.f;
        underwater_surface.field.water_plane[1] = 0.f;
        underwater_surface.field.water_plane[2] = 1.f;
        underwater_surface.field.water_plane[3] = 1.f;
        underwater_surface.field.fog[0] = 1.f;
        underwater_surface.field.fog[1] = 0.f;
        underwater_surface.normal_maps[0] = flat_normal.get();
        underwater_surface.normal_maps[1] = flat_normal.get();
        std::memcpy(underwater_surface.modelview,
                    identity.data(), sizeof(identity));
        underwater_surface.eye_position[2] = -1.f;
        underwater_surface.water_far[0] = 256.f;
        underwater_surface.parameters[1] = 0.05f;
        underwater_surface.parameters[2] = 1.f;
        underwater_surface.refracts = true;
        underwater_surface.has_excluded_surface = true;

        ALMetalWorldSimpleBatch underwater_surface_marker;
        underwater_surface_marker.water_surface = true;
        std::array<ALMetalWorldSimpleBatch, 3>
            underwater_surface_batches{{
                water_exclusion_batch,
                water_haze_marker,
                underwater_surface_marker,
            }};
        opaque_forward_scene.batches = underwater_surface_batches.data();
        opaque_forward_scene.batch_count =
            underwater_surface_batches.size();
        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.reverse_z = false;
        opaque_forward_scene.water_exclusion_surface = &water_surface;
        opaque_forward_scene.water_haze = &underwater_marker_haze;
        opaque_forward_scene.water_surface = nullptr;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world water-surface inputs are invalid");
        opaque_forward_scene.water_surface = &underwater_surface;
        error.clear();

        // Both authored water fragments call mirrorClipped in GLSL after
        // their derivative-dependent work. Exercise the same physical
        // crossing plane here: the rejected half must recover the retained
        // G-buffer depth, while the accepted half remains bit-for-bit the
        // ordinary native water result. The caller selects underwater or
        // above-water by installing its production surface and environment.
        const auto check_mirror_clipped_water_surface = [&]()
        {
            std::array<float, 32 * 32> base_depth{};
            REQUIRE(opaque_forward_scene.gbuffer->depthStencilTexture()->
                readback(*device, 0, 0, {}, base_depth.data(),
                         32 * sizeof(float), &error));
            INFO(error);

            opaque_forward_scene.mirror_clip = false;
            auto ordinary = renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
            INFO(error);
            REQUIRE(ordinary);
            std::array<float, 32 * 32> ordinary_depth{};
            REQUIRE(ordinary->depthStencilTexture()->readback(
                *device, 0, 0, {}, ordinary_depth.data(),
                32 * sizeof(float), &error));
            INFO(error);

            opaque_forward_scene.mirror_clip_plane[0] = 1.f;
            opaque_forward_scene.mirror_clip_plane[1] = 0.f;
            opaque_forward_scene.mirror_clip_plane[2] = 0.f;
            opaque_forward_scene.mirror_clip_plane[3] = 0.f;
            opaque_forward_scene.mirror_clip = true;
            auto clipped = renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
            INFO(error);
            REQUIRE(clipped);
            std::array<float, 32 * 32> clipped_depth{};
            REQUIRE(clipped->depthStencilTexture()->readback(
                *device, 0, 0, {}, clipped_depth.data(),
                32 * sizeof(float), &error));
            INFO(error);

            std::size_t ordinary_negative = 0;
            std::size_t ordinary_positive = 0;
            bool rejected_matches_base = true;
            bool retained_matches_ordinary = true;
            for (std::size_t y = 0; y < 32; ++y)
            {
                for (std::size_t x = 0; x < 32; ++x)
                {
                    const std::size_t pixel = y * 32 + x;
                    const bool water_changed_depth = std::abs(
                        ordinary_depth[pixel] - base_depth[pixel]) >
                        0.0001f;
                    if (x < 16)
                    {
                        ordinary_negative += water_changed_depth ? 1 : 0;
                        rejected_matches_base = rejected_matches_base &&
                            std::abs(clipped_depth[pixel] -
                                     base_depth[pixel]) < 0.0001f;
                    }
                    else
                    {
                        ordinary_positive += water_changed_depth ? 1 : 0;
                        retained_matches_ordinary =
                            retained_matches_ordinary &&
                            std::abs(clipped_depth[pixel] -
                                     ordinary_depth[pixel]) < 0.0001f;
                    }
                }
            }
            CHECK(ordinary_negative > 0);
            CHECK(ordinary_positive > 0);
            CHECK(rejected_matches_base);
            CHECK(retained_matches_ordinary);
            opaque_forward_scene.mirror_clip = false;
        };

        auto underwater_surface_result =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(underwater_surface_result);
        REQUIRE(underwater_surface_result->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        REQUIRE(underwater_surface_result->depthStencilTexture()->readback(
            *device, 0, 0, {}, pre_water_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK(std::abs(
            half_to_float(pre_water_pixels[stencil_center + 0]) -
            0.25f) < 0.002f);
        CHECK(std::abs(
            half_to_float(pre_water_pixels[stencil_center + 1]) -
            0.125f) < 0.002f);
        CHECK(std::abs(
            half_to_float(pre_water_pixels[stencil_center + 2]) -
            0.0625f) < 0.002f);
        CHECK(std::abs(
            half_to_float(pre_water_pixels[stencil_center + 3]) -
            0.5f) < 0.002f);
        CHECK(std::abs(
            pre_water_depth[stencil_center / 4] - 0.25f) < 0.0001f);
        check_mirror_clipped_water_surface();

        // The same shader handles both runtime hextile tiers. A one-texel
        // flat map makes their exact lattice reads deterministic while still
        // forcing every branch and cached production pipeline to execute.
        for (const float hextile : {1.f, 2.f})
        {
            underwater_surface.parameters[3] = hextile;
            auto hextile_surface = renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
            INFO(error);
            REQUIRE(hextile_surface);
        }
        underwater_surface.parameters[3] = 0.f;

        underwater_surface.wave_occlusion = true;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world flat water-surface inputs are invalid");
        underwater_surface.wave_occlusion = false;
        error.clear();

        // Opaque water has no screen copy: its source is the authored fog
        // colour. With zero density the colour reaches the target unchanged.
        underwater_surface.refracts = false;
        auto opaque_underwater_surface = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(opaque_underwater_surface);
        REQUIRE(opaque_underwater_surface->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(std::abs(
            half_to_float(pre_water_pixels[stencil_center + 0]) -
            srgb_to_linear(underwater_surface.field.fog_color[0])) <
            0.002f);
        CHECK(std::abs(
            half_to_float(pre_water_pixels[stencil_center + 3]) -
            0.5f) < 0.002f);
        underwater_surface.refracts = true;

        const std::array<float, 2> reverse_underwater_surface_cell{{
            0.5f, 1.f,
        }};
        auto reverse_underwater_surface_upload =
            device->makeCommandBuffer(
                "Alchemy reverse underwater surface height upload",
                &error);
        REQUIRE(reverse_underwater_surface_upload);
        REQUIRE(water_cell_map->upload(
            *reverse_underwater_surface_upload, 0, 0, {},
            reverse_underwater_surface_cell.data(),
            sizeof(reverse_underwater_surface_cell), &error));
        REQUIRE(reverse_underwater_surface_upload->commitAndWait(&error));
        underwater_surface.field.default_height[0] = 0.5f;
        opaque_forward_scene.gbuffer = reverse_coverage_result.get();
        opaque_forward_scene.reverse_z = true;
        auto reverse_underwater_surface =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_underwater_surface);
        REQUIRE(reverse_underwater_surface->depthStencilTexture()->readback(
            *device, 0, 0, {}, pre_water_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK(std::abs(
            pre_water_depth[stencil_center / 4] - 0.5f) < 0.0001f);

        // Native waves replace the patched cell with 8x8 fractional-odd
        // quad patches, displace their tessellated vertices from the baked
        // RG16F height field, then draw the exact four-part field including
        // its patch fringe. A constant unit big-height and 0.04 amplitude
        // move this -0.5 plane to z=0, hence forward depth 0.5.
        ALMetalTextureDescriptor wave_cell_descriptor =
            water_cell_descriptor;
        wave_cell_descriptor.width = 3;
        wave_cell_descriptor.height = 3;
        wave_cell_descriptor.label =
            "Alchemy wave water test height field";
        auto wave_cell_map = ALMetalTexture::create(
            *device, wave_cell_descriptor, &error);
        INFO(error);
        REQUIRE(wave_cell_map);
        std::array<float, 3 * 3 * 2> wave_cells{};
        for (std::size_t cell = 0; cell < 9; ++cell)
        {
            wave_cells[cell * 2] = -0.5f;
            wave_cells[cell * 2 + 1] = 1.f;
        }
        ALMetalTextureDescriptor wave_height_descriptor;
        wave_height_descriptor.format = ALMetalPixelFormat::rg16_float;
        wave_height_descriptor.width = 1;
        wave_height_descriptor.height = 1;
        wave_height_descriptor.storage = ALMetalStorageMode::private_gpu;
        wave_height_descriptor.usage = ALMetalTextureUsage::shader_read;
        wave_height_descriptor.label =
            "Alchemy wave water test baked heights";
        auto wave_height_map = ALMetalTexture::create(
            *device, wave_height_descriptor, &error);
        INFO(error);
        REQUIRE(wave_height_map);
        const std::array<std::uint16_t, 2> wave_height{{
            0x3c00u, 0u,
        }};
        auto wave_upload = device->makeCommandBuffer(
            "Alchemy wave water test upload", &error);
        REQUIRE(wave_upload);
        REQUIRE(wave_cell_map->upload(
            *wave_upload, 0, 0, {}, wave_cells.data(),
            3 * 2 * sizeof(float), &error));
        REQUIRE(wave_height_map->upload(
            *wave_upload, 0, 0, {}, wave_height.data(),
            sizeof(wave_height), &error));
        REQUIRE(wave_upload->commitAndWait(&error));

        ALMetalWorldWaterSurface underwater_wave = underwater_surface;
        underwater_wave.field.cell_map = wave_cell_map.get();
        underwater_wave.field.cell_square[0] = -1.5f;
        underwater_wave.field.cell_square[1] = -1.5f;
        underwater_wave.field.cell_square[2] = 1.f;
        underwater_wave.field.cell_square[3] = 3.f;
        underwater_wave.field.default_height[0] = -0.5f;
        underwater_wave.field.rings[0] = 1.5f;
        underwater_wave.field.draws[0] = {0u, 4u, 9u, true};
        underwater_wave.field.draws[1] = {1u, 9u, 12u, false};
        underwater_wave.field.draws[2] = {2u, 15u, 4u, false};
        underwater_wave.field.draws[3] = {3u, 27u, 4u, false};
        underwater_wave.field.draw_count = 4;
        underwater_wave.height_maps[0] = wave_height_map.get();
        underwater_wave.height_maps[1] = wave_height_map.get();
        underwater_wave.parameters[0] = 0.f;
        underwater_wave.wave_eye_density[2] = 4.f;
        underwater_wave.wave_eye_density[3] = 32.f;
        underwater_wave.wave_reach_amplitude[0] = 256.f;
        underwater_wave.wave_reach_amplitude[1] = 1.f;
        underwater_wave.wave_reach_amplitude[2] = 0.04f;
        underwater_wave.patch_rect[0] = 1;
        underwater_wave.patch_rect[1] = 1;
        underwater_wave.patch_rect[2] = 2;
        underwater_wave.patch_rect[3] = 2;
        underwater_wave.patch_count = 64;
        underwater_wave.tessellation_factors.assign(64 * 6, 0x3c00u);
        underwater_wave.waves = true;
        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.reverse_z = false;
        opaque_forward_scene.water_surface = &underwater_wave;
        auto underwater_wave_result = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(underwater_wave_result);
        REQUIRE(underwater_wave_result->depthStencilTexture()->readback(
            *device, 0, 0, {}, pre_water_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK(std::abs(
            pre_water_depth[stencil_center / 4] - 0.5f) < 0.02f);

        for (const float hextile : {1.f, 2.f})
        {
            underwater_wave.parameters[3] = hextile;
            auto tiled_wave = renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
            INFO(error);
            REQUIRE(tiled_wave);
        }
        underwater_wave.parameters[3] = 0.f;
        underwater_wave.patch_order[0] = 1;
        underwater_wave.patch_order[1] = 1;
        underwater_wave.patch_order[2] = 1;
        auto reversed_wave_order = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reversed_wave_order);
        underwater_wave.patch_order[0] = 0;
        underwater_wave.patch_order[1] = 0;
        underwater_wave.patch_order[2] = 0;
        std::fill_n(underwater_wave.tessellation_factors.begin(), 6, 0u);
        auto culled_wave_patch = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(culled_wave_patch);
        std::fill_n(
            underwater_wave.tessellation_factors.begin(), 6, 0x3c00u);

        underwater_wave.wave_occlusion = true;
        auto native_occlusion_wave =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(native_occlusion_wave);
        CHECK(native_occlusion_wave->descriptor().depth_stencil_shader_read);
        underwater_wave.wave_occlusion = false;

        underwater_wave.tessellation_factors.pop_back();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world wave water-surface inputs are invalid");
        underwater_wave.tessellation_factors.push_back(0x3c00u);
        underwater_wave.height_maps[0] = flat_normal.get();
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error ==
              "Metal world wave water-surface inputs are invalid");
        underwater_wave.height_maps[0] = wave_height_map.get();
        error.clear();

        // Above-water flat water owns the same field and normal layers but
        // adds a current-depth refraction guard, water-only probe traversal,
        // directional-shadowed sun glint and MAX glow-alpha blending.
        const std::array<float, 2> above_water_surface_cell{{-0.5f, 1.f}};
        auto above_water_surface_upload = device->makeCommandBuffer(
            "Alchemy above-water surface height upload", &error);
        REQUIRE(above_water_surface_upload);
        REQUIRE(water_cell_map->upload(
            *above_water_surface_upload, 0, 0, {},
            above_water_surface_cell.data(),
            sizeof(above_water_surface_cell), &error));
        REQUIRE(above_water_surface_upload->commitAndWait(&error));

        ALMetalTextureDescriptor water_legacy_environment_descriptor;
        water_legacy_environment_descriptor.type =
            ALMetalTextureType::texture_cube;
        water_legacy_environment_descriptor.format =
            ALMetalPixelFormat::rgba8_unorm;
        water_legacy_environment_descriptor.width = 1;
        water_legacy_environment_descriptor.height = 1;
        water_legacy_environment_descriptor.storage =
            ALMetalStorageMode::private_gpu;
        water_legacy_environment_descriptor.usage =
            ALMetalTextureUsage::shader_read;
        water_legacy_environment_descriptor.label =
            "Alchemy above-water legacy sky environment";
        auto water_legacy_environment = ALMetalTexture::create(
            *device, water_legacy_environment_descriptor, &error);
        INFO(error);
        REQUIRE(water_legacy_environment);
        const std::array<std::uint8_t, 4> water_legacy_blue{{
            0, 64, 255, 255,
        }};
        auto water_legacy_environment_upload =
            device->makeCommandBuffer(
                "Alchemy above-water legacy sky upload", &error);
        INFO(error);
        REQUIRE(water_legacy_environment_upload);
        for (std::uint32_t face = 0; face < 6; ++face)
        {
            REQUIRE(water_legacy_environment->upload(
                *water_legacy_environment_upload, 0, face, {},
                water_legacy_blue.data(), water_legacy_blue.size(),
                &error));
        }
        REQUIRE(water_legacy_environment_upload->commitAndWait(&error));
        INFO(error);

        // Reflection-probe-disabled forward rendering is one coherent
        // legacy-sky family, not a water-only exception. Exercise every
        // consumer against physical blue and black cube data before the
        // water-specific checks below: simple alpha receives the authored
        // ambiance blend, legacy material and shiny use the sRGB cube mix,
        // and PBR alpha decodes the same cube to linear radiance.
        ALMetalWorldOpaquePostDeferredScene no_probe_forward_scene =
            opaque_forward_scene;
        no_probe_forward_scene.gbuffer = coverage_result.get();
        no_probe_forward_scene.batches = &simple_pre_water;
        no_probe_forward_scene.batch_count = 1;
        no_probe_forward_scene.highlight_batches = nullptr;
        no_probe_forward_scene.highlight_batch_count = 0;
        no_probe_forward_scene.reflection_probes = nullptr;
        no_probe_forward_scene.legacy_environment =
            water_legacy_environment.get();
        no_probe_forward_scene.hero_probe = nullptr;
        no_probe_forward_scene.screen_space_reflections = nullptr;
        no_probe_forward_scene.water_exclusion_surface = nullptr;
        no_probe_forward_scene.water_haze = nullptr;
        no_probe_forward_scene.water_surface = nullptr;
        no_probe_forward_scene.atmospheric_haze = nullptr;
        no_probe_forward_scene.sky_behind = nullptr;
        no_probe_forward_scene.alpha_environment = &alpha_environment;
        no_probe_forward_scene.alpha_lighting = &simple_alpha_lighting;
        no_probe_forward_scene.alpha_directional_shadows = nullptr;
        no_probe_forward_scene.reverse_z = false;
        no_probe_forward_scene.publish_screen_space_reflection_history =
            false;

        alpha_environment.atmos_sunlit_linear[0] = 0.f;
        alpha_environment.atmos_sunlit_linear[1] = 0.f;
        alpha_environment.atmos_sunlit_linear[2] = 0.f;
        alpha_environment.atmos_amblit[0] = 0.f;
        alpha_environment.atmos_amblit[1] = 0.f;
        alpha_environment.atmos_amblit[2] = 0.f;
        alpha_environment.environment[0] = 1.f;
        simple_alpha_lighting.parameters[3] = 0.f;
        auto no_probe_simple = renderer->renderOpaquePostDeferred(
            no_probe_forward_scene, &error);
        INFO(error);
        REQUIRE(no_probe_simple);
        REQUIRE(no_probe_simple->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        const float ambiance_simple_green = half_to_float(
            pre_water_pixels[pre_water_left + 1]);
        alpha_environment.environment[0] = 0.f;
        auto no_probe_simple_zero_ambiance =
            renderer->renderOpaquePostDeferred(
                no_probe_forward_scene, &error);
        INFO(error);
        REQUIRE(no_probe_simple_zero_ambiance);
        REQUIRE(no_probe_simple_zero_ambiance->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(ambiance_simple_green > half_to_float(
                  pre_water_pixels[pre_water_left + 1]));

        ALMetalWorldSimpleBatch no_probe_material = pre_water_material;
        no_probe_material.pre_water_shadows = false;
        no_probe_material.material_slots[0].env_intensity = 1.f;
        no_probe_material.material_slots[0].specular_color[3] = 0.f;
        no_probe_forward_scene.batches = &no_probe_material;
        auto no_probe_material_blue = renderer->renderOpaquePostDeferred(
            no_probe_forward_scene, &error);
        INFO(error);
        REQUIRE(no_probe_material_blue);
        REQUIRE(no_probe_material_blue->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        const float legacy_material_blue = half_to_float(
            pre_water_pixels[material_pixel + 2]);
        no_probe_forward_scene.legacy_environment = hero_texture.get();
        auto no_probe_material_black = renderer->renderOpaquePostDeferred(
            no_probe_forward_scene, &error);
        INFO(error);
        REQUIRE(no_probe_material_black);
        REQUIRE(no_probe_material_black->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(legacy_material_blue > half_to_float(
                  pre_water_pixels[material_pixel + 2]));

        ALMetalWorldSimpleBatch no_probe_pbr = pre_water_pbr;
        no_probe_pbr.pre_water_shadows = false;
        no_probe_pbr.pbr_slots[0].emissive_color[0] = 0.f;
        no_probe_pbr.pbr_slots[0].emissive_color[1] = 0.f;
        no_probe_pbr.pbr_slots[0].emissive_color[2] = 0.f;
        no_probe_pbr.pbr_slots[0].roughness_factor = 0.f;
        no_probe_pbr.pbr_slots[0].metallic_factor = 1.f;
        no_probe_forward_scene.batches = &no_probe_pbr;
        no_probe_forward_scene.legacy_environment =
            water_legacy_environment.get();
        auto no_probe_pbr_blue = renderer->renderOpaquePostDeferred(
            no_probe_forward_scene, &error);
        INFO(error);
        REQUIRE(no_probe_pbr_blue);
        REQUIRE(no_probe_pbr_blue->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        const float legacy_pbr_blue = half_to_float(
            pre_water_pixels[material_pixel + 2]);
        no_probe_forward_scene.legacy_environment = hero_texture.get();
        auto no_probe_pbr_black = renderer->renderOpaquePostDeferred(
            no_probe_forward_scene, &error);
        INFO(error);
        REQUIRE(no_probe_pbr_black);
        REQUIRE(no_probe_pbr_black->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(legacy_pbr_blue > half_to_float(
                  pre_water_pixels[material_pixel + 2]));

        ALMetalWorldSimpleBatch no_probe_shiny = fullbright_batch;
        no_probe_shiny.impostor_fullbright = false;
        no_probe_shiny.impostor_shiny = true;
        no_probe_shiny.alpha_mask = false;
        for (std::size_t index = 0; index < 4; ++index)
        {
            no_probe_shiny.modelview[index * 4 + index] = 1.f;
        }
        no_probe_forward_scene.batches = &no_probe_shiny;
        no_probe_forward_scene.legacy_environment =
            water_legacy_environment.get();
        auto no_probe_shiny_blue = renderer->renderOpaquePostDeferred(
            no_probe_forward_scene, &error);
        INFO(error);
        REQUIRE(no_probe_shiny_blue);
        REQUIRE(no_probe_shiny_blue->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        const float legacy_shiny_blue = half_to_float(
            pre_water_pixels[fullbright_top + 2]);
        no_probe_forward_scene.legacy_environment = hero_texture.get();
        auto no_probe_shiny_black = renderer->renderOpaquePostDeferred(
            no_probe_forward_scene, &error);
        INFO(error);
        REQUIRE(no_probe_shiny_black);
        REQUIRE(no_probe_shiny_black->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(legacy_shiny_blue > half_to_float(
                  pre_water_pixels[fullbright_top + 2]));

        no_probe_forward_scene.legacy_environment = nullptr;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            no_probe_forward_scene, &error));
        CHECK(error == "Metal world forward environment is invalid");
        no_probe_forward_scene.legacy_environment =
            water_legacy_environment.get();
        no_probe_forward_scene.reflection_probes = &reflection_probes;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            no_probe_forward_scene, &error));
        CHECK(error == "Metal world forward environment is invalid");

        alpha_environment.environment[0] = 0.f;

        ALMetalWorldWaterSurface above_water_surface =
            underwater_surface;
        above_water_surface.field.default_height[0] = -0.5f;
        above_water_surface.eye_position[2] = 1.f;
        above_water_surface.normal_matrix[0][0] = 1.f;
        above_water_surface.normal_matrix[1][1] = 1.f;
        above_water_surface.normal_matrix[2][2] = 1.f;
        above_water_surface.normal_scale_glint[0] = 2.f;
        above_water_surface.normal_scale_glint[1] = 2.f;
        above_water_surface.normal_scale_glint[2] = 2.f;
        above_water_surface.normal_scale_glint[3] = 1.f;
        above_water_surface.optics[0] = 0.f;
        above_water_surface.optics[1] = 1.f;
        above_water_surface.optics[2] = 0.7f;
        above_water_surface.light_direction[2] = 1.f;
        above_water_surface.underwater = false;
        above_water_surface.has_excluded_surface = false;
        above_water_surface.uses_shadows = false;
        alpha_environment.atmos_sunlit[0] = 1.f;
        alpha_environment.atmos_sunlit[1] = 0.5f;
        alpha_environment.atmos_sunlit[2] = 0.25f;
        alpha_environment.atmos_sunlit[3] = 1.f;
        alpha_environment.atmos_sunlit_linear[0] = 1.f;
        alpha_environment.atmos_sunlit_linear[1] = 0.5f;
        alpha_environment.atmos_sunlit_linear[2] = 0.25f;
        alpha_environment.atmos_sunlit_linear[3] = 1.f;
        simple_alpha_lighting.parameters[3] = 0.f;
        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.reverse_z = false;
        opaque_forward_scene.reflection_probes = &reflection_probes;
        opaque_forward_scene.alpha_environment = &alpha_environment;
        opaque_forward_scene.alpha_lighting = &simple_alpha_lighting;
        opaque_forward_scene.alpha_directional_shadows = nullptr;
        opaque_forward_scene.water_surface = &above_water_surface;
        error.clear();
        auto above_water_surface_result =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(above_water_surface_result);
        REQUIRE(above_water_surface_result->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        REQUIRE(above_water_surface_result->depthStencilTexture()->readback(
            *device, 0, 0, {}, pre_water_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        std::size_t above_water_pixel = 0;
        float above_water_delta = 0.f;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            if (std::abs(pre_water_depth[pixel] - 0.25f) >= 0.0001f)
            {
                continue;
            }
            const float red = half_to_float(
                pre_water_pixels[pixel * 4 + 0]);
            const float green = half_to_float(
                pre_water_pixels[pixel * 4 + 1]);
            const float blue = half_to_float(
                pre_water_pixels[pixel * 4 + 2]);
            const float delta = std::abs(red - 0.25f) +
                std::abs(green - 0.125f) +
                std::abs(blue - 0.0625f);
            if (delta > above_water_delta)
            {
                above_water_delta = delta;
                above_water_pixel = pixel * 4;
            }
        }
        CHECK(above_water_delta > 0.01f);
        CHECK(std::abs(
            half_to_float(pre_water_pixels[above_water_pixel + 3]) -
            0.5f) < 0.002f);
        CHECK(std::abs(
            pre_water_depth[above_water_pixel / 4] - 0.25f) < 0.0001f);
        check_mirror_clipped_water_surface();

        // class3/deferred/reflectionProbeF.glsl deliberately samples default
        // probe zero along the reflected water ray without parallax. A
        // camera-relative default-probe centre must therefore not steer the
        // water into a different cubemap face. Use six distinct physical
        // faces and move only that centre across the 4 km automatic sphere;
        // generic sphere correction changes the result, while the required
        // water path remains invariant.
        ALMetalTextureDescriptor water_probe_descriptor = probe_descriptor;
        water_probe_descriptor.label =
            "Alchemy water default-probe no-parallax control";
        auto water_probe_texture = ALMetalTexture::create(
            *device, water_probe_descriptor, &error);
        INFO(error);
        REQUIRE(water_probe_texture);
        const std::array<std::array<std::uint8_t, 4>, 6>
            water_probe_faces{{
                {{255, 0, 0, 255}},
                {{0, 255, 0, 255}},
                {{0, 0, 255, 255}},
                {{255, 255, 0, 255}},
                {{255, 0, 255, 255}},
                {{0, 255, 255, 255}},
            }};
        auto water_probe_upload = device->makeCommandBuffer(
            "Alchemy water default-probe control upload", &error);
        INFO(error);
        REQUIRE(water_probe_upload);
        for (std::uint32_t slice = 0; slice < 12; ++slice)
        {
            const auto& face = water_probe_faces[slice % 6];
            REQUIRE(water_probe_texture->upload(
                *water_probe_upload, 0, slice, {},
                face.data(), face.size(), &error));
        }
        REQUIRE(water_probe_upload->commitAndWait(&error));
        INFO(error);

        ALMetalWorldReflectionProbes water_default_probe =
            reflection_probes;
        water_default_probe.radiance_texture = water_probe_texture.get();
        water_default_probe.constants.config[0] = 1.f;
        water_default_probe.constants.ref_index[0][0] = 0;
        water_default_probe.constants.ref_sphere[0][0] = 4000.f;
        opaque_forward_scene.reflection_probes = &water_default_probe;
        auto positive_probe_center = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(positive_probe_center);
        REQUIRE(positive_probe_center->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        std::array<float, 3> positive_probe_color{};
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            positive_probe_color[channel] = half_to_float(
                pre_water_pixels[above_water_pixel + channel]);
        }

        water_default_probe.constants.ref_sphere[0][0] = -4000.f;
        auto negative_probe_center = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(negative_probe_center);
        REQUIRE(negative_probe_center->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        float water_probe_center_delta = 0.f;
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            const float negative = half_to_float(
                pre_water_pixels[above_water_pixel + channel]);
            water_probe_center_delta += std::abs(
                positive_probe_color[channel] - negative);
        }
        INFO(positive_probe_color[0]);
        INFO(positive_probe_color[1]);
        INFO(positive_probe_color[2]);
        INFO(water_probe_center_delta);
        CHECK(water_probe_center_delta < 0.002f);
        opaque_forward_scene.reflection_probes = &reflection_probes;

        // Viewer assets share sRGB storage even when the active bind treats
        // them as data. GL's AnisoWrap water bind suppresses decoding; Metal
        // must therefore sample the compatible raw-storage view. The same
        // encoded tangent normal in linear and sRGB backing must shade the
        // water identically.
        above_water_surface.normal_maps[0] = bump_normal.get();
        above_water_surface.normal_maps[1] = bump_normal.get();
        auto linear_water_normal = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(linear_water_normal);
        REQUIRE(linear_water_normal->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        const std::array<float, 4> linear_water_normal_color{{
            half_to_float(pre_water_pixels[above_water_pixel + 0]),
            half_to_float(pre_water_pixels[above_water_pixel + 1]),
            half_to_float(pre_water_pixels[above_water_pixel + 2]),
            half_to_float(pre_water_pixels[above_water_pixel + 3]),
        }};
        above_water_surface.normal_maps[0] = srgb_bump_normal.get();
        above_water_surface.normal_maps[1] = srgb_bump_normal.get();
        auto srgb_water_normal = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(srgb_water_normal);
        REQUIRE(srgb_water_normal->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(std::abs(
                half_to_float(
                    pre_water_pixels[above_water_pixel + channel]) -
                linear_water_normal_color[channel]) < 0.002f);
        }
        above_water_surface.normal_maps[0] = flat_normal.get();
        above_water_surface.normal_maps[1] = flat_normal.get();

        // With reflection probes disabled, class2 water samples the current
        // sharp sky cube through env_mat and does not apply SSR or hero-probe
        // finishing. Prove the mutually exclusive Metal path consumes that
        // physical cube and rejects missing or ambiguous ownership.
        const std::array<float, 3> probe_water_color{{
            half_to_float(pre_water_pixels[above_water_pixel + 0]),
            half_to_float(pre_water_pixels[above_water_pixel + 1]),
            half_to_float(pre_water_pixels[above_water_pixel + 2]),
        }};
        opaque_forward_scene.reflection_probes = nullptr;
        opaque_forward_scene.legacy_environment =
            water_legacy_environment.get();
        auto legacy_above_water = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(legacy_above_water);
        REQUIRE(legacy_above_water->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        const std::array<float, 3> legacy_water_color{{
            half_to_float(pre_water_pixels[above_water_pixel + 0]),
            half_to_float(pre_water_pixels[above_water_pixel + 1]),
            half_to_float(pre_water_pixels[above_water_pixel + 2]),
        }};
        CHECK(legacy_water_color[2] > legacy_water_color[1]);
        CHECK(legacy_water_color[2] > legacy_water_color[0]);
        CHECK((std::abs(legacy_water_color[0] - probe_water_color[0]) +
               std::abs(legacy_water_color[1] - probe_water_color[1]) +
               std::abs(legacy_water_color[2] - probe_water_color[2])) >
              0.01f);

        opaque_forward_scene.reflection_probes = &reflection_probes;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world above-water environment is invalid");
        opaque_forward_scene.reflection_probes = nullptr;
        opaque_forward_scene.legacy_environment = nullptr;
        error.clear();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world above-water environment is invalid");
        opaque_forward_scene.reflection_probes = &reflection_probes;
        error.clear();

        ALMetalWorldWaterSurface above_water_wave =
            above_water_surface;
        above_water_wave.field.cell_map = wave_cell_map.get();
        above_water_wave.field.cell_square[0] = -1.5f;
        above_water_wave.field.cell_square[1] = -1.5f;
        above_water_wave.field.cell_square[2] = 1.f;
        above_water_wave.field.cell_square[3] = 3.f;
        above_water_wave.field.rings[0] = 1.5f;
        above_water_wave.field.draws = underwater_wave.field.draws;
        above_water_wave.field.draw_count = 4;
        above_water_wave.height_maps = underwater_wave.height_maps;
        std::memcpy(above_water_wave.wave_eye_density,
                    underwater_wave.wave_eye_density,
                    sizeof(above_water_wave.wave_eye_density));
        std::memcpy(above_water_wave.wave_reach_amplitude,
                    underwater_wave.wave_reach_amplitude,
                    sizeof(above_water_wave.wave_reach_amplitude));
        std::memcpy(above_water_wave.patch_rect,
                    underwater_wave.patch_rect,
                    sizeof(above_water_wave.patch_rect));
        std::memcpy(above_water_wave.patch_order,
                    underwater_wave.patch_order,
                    sizeof(above_water_wave.patch_order));
        above_water_wave.patch_count = underwater_wave.patch_count;
        above_water_wave.tessellation_factors =
            underwater_wave.tessellation_factors;
        above_water_wave.waves = true;
        opaque_forward_scene.water_surface = &above_water_wave;
        auto above_water_wave_result =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(above_water_wave_result);
        REQUIRE(above_water_wave_result->depthStencilTexture()->readback(
            *device, 0, 0, {}, pre_water_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        bool saw_above_wave_depth = false;
        for (float depth : pre_water_depth)
        {
            saw_above_wave_depth = saw_above_wave_depth ||
                std::abs(depth - 0.5f) < 0.02f;
        }
        CHECK(saw_above_wave_depth);
        opaque_forward_scene.water_surface = &above_water_surface;

        // A requested live cascade is mandatory. Once supplied, the same
        // shader executes both built and explicitly unbuilt shadow states.
        above_water_surface.uses_shadows = true;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world pre-water alpha shadows are invalid");
        opaque_forward_scene.alpha_directional_shadows =
            &directional_shadows;
        directional_shadows.constants.config[1] = 0xeu;
        error.clear();
        auto shadowed_above_water = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(shadowed_above_water);
        REQUIRE(shadowed_above_water->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        const float shadowed_water_red = half_to_float(
            pre_water_pixels[above_water_pixel]);
        directional_shadows.constants.config[1] = 0xfu;
        auto unbuilt_above_water = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(unbuilt_above_water);
        REQUIRE(unbuilt_above_water->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        CHECK(half_to_float(pre_water_pixels[above_water_pixel]) >
              shadowed_water_red);

        above_water_surface.uses_shadows = false;
        opaque_forward_scene.alpha_directional_shadows = nullptr;
        directional_shadows.constants.config[1] = 0xeu;

        // Opaque water replaces the missing scene copy with the authored
        // 2,048-metre water-fog source while retaining reflection/glint.
        above_water_surface.refracts = false;
        auto opaque_above_water = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(opaque_above_water);

        // Opaque above-water rendering has no refraction source and the GL
        // owner deliberately skips the pre-surface water-haze pass. The
        // native transaction must accept that exact shortened ordering while
        // still requiring haze for refractive or underwater surfaces.
        opaque_forward_scene.batches = &underwater_surface_marker;
        opaque_forward_scene.batch_count = 1;
        opaque_forward_scene.water_exclusion_surface = nullptr;
        opaque_forward_scene.water_haze = nullptr;
        auto opaque_above_water_without_haze =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(opaque_above_water_without_haze);
        above_water_surface.refracts = true;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world water-surface marker is invalid");
        error.clear();
        opaque_forward_scene.batches = underwater_surface_batches.data();
        opaque_forward_scene.batch_count =
            underwater_surface_batches.size();
        opaque_forward_scene.water_exclusion_surface = &water_surface;
        opaque_forward_scene.water_haze = &underwater_marker_haze;

        // Exercise the water-specific ordinary -> SSR -> hero finish and
        // the infinite-projection rim replacement with coherent resources.
        above_water_surface.optics[2] = 0.f;
        above_water_surface.water_far[1] = 8.f;
        above_water_surface.rim[0] = 100.f;
        above_water_surface.rim[1] = 100.f;
        above_water_surface.rim[2] = -100.f;
        above_water_surface.rim[3] = -100.f;
        opaque_forward_scene.hero_probe = &hero_probe;
        opaque_forward_scene.screen_space_reflections =
            &screen_space_reflections;
        auto finished_above_water = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(finished_above_water);
        REQUIRE(finished_above_water->colorTexture(0)->readback(
            *device, 0, 0, {}, pre_water_pixels.data(), 32 * 8,
            &error));
        CHECK(std::isfinite(half_to_float(
            pre_water_pixels[above_water_pixel])));
        opaque_forward_scene.hero_probe = nullptr;
        opaque_forward_scene.screen_space_reflections = nullptr;

        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.reverse_z = false;
        opaque_forward_scene.water_surface = nullptr;

        // Deferred atmospheric haze snapshots depth at its real ordered
        // boundary. Clear-depth sky pixels remain byte-for-byte untouched,
        // drawn pixels receive additive in-scatter plus multiplicative
        // extinction, and cutout coverage keeps destination alpha.
        ALMetalWorldSimpleBatch atmospheric_marker;
        atmospheric_marker.atmospheric_haze = true;
        ALMetalWorldAtmosphericHaze atmospheric_haze;
        std::memcpy(atmospheric_haze.inverse_projection,
                    identity.data(), sizeof(identity));
        atmospheric_haze.above_water = true;
        alpha_environment.water_plane[0] = 0.f;
        alpha_environment.water_plane[1] = 0.f;
        alpha_environment.water_plane[2] = 1.f;
        alpha_environment.water_plane[3] = 1.f;
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            alpha_environment.haze_extinction[channel] = 1.f;
            alpha_environment.haze_additive[channel] = 0.2f;
            alpha_environment.haze_additive_glow[channel] = 0.f;
        }
        alpha_environment.atmospheric[0] = 1.f;
        alpha_environment.atmospheric[1] = 1.f;
        alpha_environment.atmospheric[2] = 0.f;
        alpha_environment.atmospheric[3] = 1.f;
        alpha_environment.water_fog[2] = -1.f;
        opaque_forward_scene.batches = &atmospheric_marker;
        opaque_forward_scene.batch_count = 1;
        opaque_forward_scene.water_exclusion_surface = nullptr;
        opaque_forward_scene.water_haze = nullptr;
        opaque_forward_scene.atmospheric_haze = &atmospheric_haze;
        opaque_forward_scene.sky_behind = nullptr;
        opaque_forward_scene.alpha_environment = &alpha_environment;
        auto atmospheric_result = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(atmospheric_result);
        std::array<std::uint16_t, 32 * 32 * 4> atmospheric_pixels{};
        REQUIRE(atmospheric_result->colorTexture(0)->readback(
            *device, 0, 0, {}, atmospheric_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(atmospheric_pixels[0] == 0x3400);
        CHECK(atmospheric_pixels[1] == 0x3000);
        CHECK(atmospheric_pixels[2] == 0x2c00);
        CHECK(atmospheric_pixels[3] == 0x3800);
        CHECK(atmospheric_pixels[stencil_center + 0] != 0x3400);
        CHECK(atmospheric_pixels[stencil_center + 3] < 0x3800);

        atmospheric_haze.alpha_writes_coverage = true;
        auto coverage_atmosphere = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(coverage_atmosphere);
        REQUIRE(coverage_atmosphere->colorTexture(0)->readback(
            *device, 0, 0, {}, atmospheric_pixels.data(), 32 * 8,
            &error));
        CHECK(atmospheric_pixels[stencil_center + 3] == 0x3800);
        atmospheric_haze.alpha_writes_coverage = false;

        atmospheric_haze.inverse_projection[0] =
            std::numeric_limits<float>::quiet_NaN();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world atmospheric-haze inputs are invalid");
        atmospheric_haze.inverse_projection[0] = 1.f;
        error.clear();

        opaque_forward_scene.gbuffer = reverse_coverage_result.get();
        opaque_forward_scene.reverse_z = true;
        auto reverse_atmosphere = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_atmosphere);
        REQUIRE(reverse_atmosphere->colorTexture(0)->readback(
            *device, 0, 0, {}, atmospheric_pixels.data(), 32 * 8,
            &error));
        CHECK(atmospheric_pixels[stencil_center + 0] != 0x3400);

        // From below the surface, geometry below the water plane is masked
        // while the same far-depth rejection still preserves the sky.
        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.reverse_z = false;
        atmospheric_haze.above_water = false;
        alpha_environment.water_plane[3] = -10.f;
        alpha_environment.water_fog[2] = 1.f;
        auto masked_underwater_atmosphere =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(masked_underwater_atmosphere);
        REQUIRE(masked_underwater_atmosphere->colorTexture(0)->readback(
            *device, 0, 0, {}, atmospheric_pixels.data(), 32 * 8,
            &error));
        CHECK(atmospheric_pixels[stencil_center + 0] == 0x3400);
        CHECK(atmospheric_pixels[stencil_center + 1] == 0x3000);
        CHECK(atmospheric_pixels[stencil_center + 2] == 0x2c00);
        CHECK(atmospheric_pixels[stencil_center + 3] == 0x3800);

        // Above water, the stencil split runs ordinary haze off the surface
        // and converges surface pixels on the half-resolution WindLight sky.
        ALMetalRenderTargetDescriptor sky_behind_descriptor;
        sky_behind_descriptor.width = 16;
        sky_behind_descriptor.height = 16;
        sky_behind_descriptor.colors[0].format =
            ALMetalPixelFormat::rg11b10_float;
        auto sky_behind_target = ALMetalRenderTarget::create(
            *device, sky_behind_descriptor, &error);
        INFO(error);
        REQUIRE(sky_behind_target);
        ALMetalRenderPassConfig sky_behind_clear;
        sky_behind_clear.colors[0].load = ALMetalLoadAction::clear;
        sky_behind_clear.colors[0].store = ALMetalStoreAction::store;
        sky_behind_clear.colors[0].clear = {0.25, 0.25, 0.25, 1.0};
        auto sky_behind_pass = sky_behind_target->makeRenderPass(
            sky_behind_clear, &error);
        auto sky_behind_command = device->makeCommandBuffer(
            "Alchemy atmospheric sky-behind clear", &error);
        auto sky_behind_encoder = sky_behind_pass && sky_behind_command
            ? ALMetalRenderEncoder::begin(
                  *sky_behind_command, *sky_behind_pass,
                  "Alchemy atmospheric sky-behind clear encoder",
                  &error)
            : nullptr;
        REQUIRE(sky_behind_encoder);
        REQUIRE(sky_behind_encoder->end(&error));
        REQUIRE(sky_behind_command->commitAndWait(&error));

        atmospheric_haze.above_water = true;
        atmospheric_haze.sky_behind = true;
        atmospheric_haze.water_ground_fade = 1.f;
        alpha_environment.water_plane[3] = 1.f;
        alpha_environment.water_fog[2] = -1.f;
        std::array<ALMetalWorldSimpleBatch, 4> atmospheric_water_batches{{
            water_exclusion_batch,
            water_haze_marker,
            underwater_surface_marker,
            atmospheric_marker,
        }};
        opaque_forward_scene.batches = atmospheric_water_batches.data();
        opaque_forward_scene.batch_count = atmospheric_water_batches.size();
        opaque_forward_scene.water_exclusion_surface = &water_surface;
        opaque_forward_scene.water_haze = &underwater_marker_haze;
        opaque_forward_scene.water_surface = &above_water_surface;
        opaque_forward_scene.atmospheric_haze = &atmospheric_haze;
        opaque_forward_scene.sky_behind =
            sky_behind_target->colorTexture(0);
        auto sky_converged_atmosphere =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(sky_converged_atmosphere);
        REQUIRE(sky_converged_atmosphere->colorTexture(0)->readback(
            *device, 0, 0, {}, atmospheric_pixels.data(), 32 * 8,
            &error));
        REQUIRE(sky_converged_atmosphere->depthStencilTexture()->readback(
            *device, 0, 0, {}, pre_water_depth.data(),
            32 * sizeof(float), &error));
        bool saw_sky_convergence = false;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            if (std::abs(pre_water_depth[pixel] - 0.25f) > 0.0001f)
            {
                continue;
            }
            const float red = half_to_float(
                atmospheric_pixels[pixel * 4]);
            saw_sky_convergence = saw_sky_convergence ||
                std::abs(red - srgb_to_linear(0.25f)) < 0.01f;
        }
        CHECK(saw_sky_convergence);

        std::array<ALMetalWorldSimpleBatch, 4> misordered_atmosphere{{
            water_exclusion_batch,
            water_haze_marker,
            atmospheric_marker,
            underwater_surface_marker,
        }};
        opaque_forward_scene.batches = misordered_atmosphere.data();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world atmospheric-haze marker is invalid");
        error.clear();

        // Post-water alpha starts only after the atmospheric boundary and
        // selects the camera side of the same live water plane. Static draws
        // depth-test without writing; rigged draws retain the pool's depth
        // write. The group-local emissive replay changes alpha only and has
        // no legacy polygon offset.
        atmospheric_haze.sky_behind = false;
        atmospheric_haze.water_ground_fade = 0.f;
        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.reverse_z = false;
        opaque_forward_scene.water_exclusion_surface = nullptr;
        opaque_forward_scene.water_haze = nullptr;
        opaque_forward_scene.water_surface = nullptr;
        opaque_forward_scene.atmospheric_haze = &atmospheric_haze;
        opaque_forward_scene.sky_behind = nullptr;
        alpha_environment.water_plane[3] = 1.f;
        alpha_environment.water_fog[2] = -1.f;
        opaque_forward_scene.batches = &atmospheric_marker;
        opaque_forward_scene.batch_count = 1;
        auto post_water_atmospheric_baseline =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(post_water_atmospheric_baseline);
        REQUIRE(post_water_atmospheric_baseline->colorTexture(0)->readback(
            *device, 0, 0, {}, atmospheric_pixels.data(), 32 * 8,
            &error));
        INFO(error);

        ALMetalWorldSimpleBatch post_water_alpha = pre_water_alpha;
        post_water_alpha.pre_water_alpha = false;
        post_water_alpha.post_water_alpha = true;
        post_water_alpha.modelview_projection[12] = 0.f;
        std::array<ALMetalWorldSimpleBatch, 2> post_water_batches{{
            atmospheric_marker,
            post_water_alpha,
        }};
        opaque_forward_scene.batches = post_water_batches.data();
        opaque_forward_scene.batch_count = post_water_batches.size();
        auto post_water_result = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(post_water_result);
        std::array<std::uint16_t, 32 * 32 * 4> post_water_pixels{};
        std::array<float, 32 * 32> post_water_depth{};
        REQUIRE(post_water_result->colorTexture(0)->readback(
            *device, 0, 0, {}, post_water_pixels.data(), 32 * 8,
            &error));
        REQUIRE(post_water_result->depthStencilTexture()->readback(
            *device, 0, 0, {}, post_water_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK(post_water_pixels[stencil_center + 1] >
              atmospheric_pixels[stencil_center + 1]);
        CHECK(std::abs(
                  post_water_depth[stencil_center / 4] - 0.625f) <
              0.0001f);

        // The optional DoF replay follows every colour/glow batch, writes no
        // colour at all, and promotes qualifying static alpha into retained
        // depth. The flat production shader uses the explicit 0.33 cutoff.
        ALMetalWorldSimpleBatch post_water_depth_only = post_water_alpha;
        post_water_depth_only.post_water_depth_only = true;
        post_water_depth_only.pre_water_minimum_alpha = 0.33f;
        std::array<ALMetalWorldSimpleBatch, 3> post_water_dof_batches{{
            atmospheric_marker,
            post_water_alpha,
            post_water_depth_only,
        }};
        opaque_forward_scene.batches = post_water_dof_batches.data();
        opaque_forward_scene.batch_count = post_water_dof_batches.size();
        auto post_water_dof_result = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(post_water_dof_result);
        std::array<std::uint16_t, 32 * 32 * 4> post_water_dof_pixels{};
        REQUIRE(post_water_dof_result->colorTexture(0)->readback(
            *device, 0, 0, {}, post_water_dof_pixels.data(), 32 * 8,
            &error));
        REQUIRE(post_water_dof_result->depthStencilTexture()->readback(
            *device, 0, 0, {}, post_water_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK(post_water_dof_pixels == post_water_pixels);
        CHECK(std::abs(
                  post_water_depth[stencil_center / 4] - 0.5f) <
              0.0001f);

        std::array<ALMetalWorldSimpleBatch, 2> dof_without_color{{
            atmospheric_marker,
            post_water_depth_only,
        }};
        opaque_forward_scene.batches = dof_without_color.data();
        opaque_forward_scene.batch_count = dof_without_color.size();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world water-haze ordering is invalid");
        error.clear();

        // A transparent texel is rejected by the ordinary 0.33 flat cutoff.
        // Custom RGB factors make GL lower the cutoff to zero; the depth-only
        // pipeline must then accept that same texel while colour stays exact.
        post_water_dof_batches[2].diffuse_textures[0] =
            zero_alpha_diffuse.get();
        opaque_forward_scene.batches = post_water_dof_batches.data();
        opaque_forward_scene.batch_count = post_water_dof_batches.size();
        auto rejected_post_water_dof = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(rejected_post_water_dof);
        REQUIRE(rejected_post_water_dof->colorTexture(0)->readback(
            *device, 0, 0, {}, post_water_dof_pixels.data(), 32 * 8,
            &error));
        REQUIRE(rejected_post_water_dof->depthStencilTexture()->readback(
            *device, 0, 0, {}, post_water_depth.data(),
            32 * sizeof(float), &error));
        CHECK(post_water_dof_pixels == post_water_pixels);
        CHECK(std::abs(
                  post_water_depth[stencil_center / 4] - 0.625f) <
              0.0001f);

        post_water_dof_batches[2].pre_water_minimum_alpha = 0.f;
        post_water_dof_batches[2].pre_water_source_rgb =
            ALMetalBlendFactor::one;
        post_water_dof_batches[2].pre_water_destination_rgb =
            ALMetalBlendFactor::one;
        auto custom_post_water_dof = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(custom_post_water_dof);
        REQUIRE(custom_post_water_dof->colorTexture(0)->readback(
            *device, 0, 0, {}, post_water_dof_pixels.data(), 32 * 8,
            &error));
        REQUIRE(custom_post_water_dof->depthStencilTexture()->readback(
            *device, 0, 0, {}, post_water_depth.data(),
            32 * sizeof(float), &error));
        CHECK(post_water_dof_pixels == post_water_pixels);
        CHECK(std::abs(
                  post_water_depth[stencil_center / 4] - 0.5f) <
              0.0001f);

        // Legacy and PBR BLEND keep their live 0.004 cutoff and exact material
        // programs during the replay. Execute both dedicated no-colour PSOs.
        ALMetalWorldSimpleBatch post_water_material = pre_water_material;
        post_water_material.pre_water_alpha = false;
        post_water_material.post_water_alpha = true;
        post_water_material.modelview[14] = 0.25f;
        post_water_material.modelview_projection[14] = -0.25f;
        post_water_material.pre_water_minimum_alpha = 0.004f;
        ALMetalWorldSimpleBatch post_water_material_depth =
            post_water_material;
        post_water_material_depth.post_water_depth_only = true;
        ALMetalWorldSimpleBatch post_water_state_glow = legacy_glow_batch;
        post_water_state_glow.post_water_glow = true;
        std::array<ALMetalWorldSimpleBatch, 4> post_water_material_dof{{
            atmospheric_marker,
            post_water_material,
            post_water_state_glow,
            post_water_material_depth,
        }};
        opaque_forward_scene.batches = post_water_material_dof.data();
        opaque_forward_scene.batch_count = post_water_material_dof.size();
        auto post_water_material_dof_result =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(post_water_material_dof_result);
        REQUIRE(post_water_material_dof_result->depthStencilTexture()
                    ->readback(
                        *device, 0, 0, {}, post_water_depth.data(),
                        32 * sizeof(float), &error));
        CHECK(std::abs(
                  post_water_depth[material_pixel / 4] - 0.5f) <
              0.0001f);

        ALMetalWorldSimpleBatch post_water_pbr = pre_water_pbr;
        post_water_pbr.pre_water_alpha = false;
        post_water_pbr.post_water_alpha = true;
        post_water_pbr.modelview[14] = 0.25f;
        post_water_pbr.modelview_projection[14] = -0.25f;
        post_water_pbr.pre_water_minimum_alpha = 0.004f;
        ALMetalWorldSimpleBatch post_water_pbr_depth = post_water_pbr;
        post_water_pbr_depth.post_water_depth_only = true;
        std::array<ALMetalWorldSimpleBatch, 3> post_water_pbr_dof{{
            atmospheric_marker,
            post_water_pbr,
            post_water_pbr_depth,
        }};
        opaque_forward_scene.batches = post_water_pbr_dof.data();
        opaque_forward_scene.batch_count = post_water_pbr_dof.size();
        auto post_water_pbr_dof_result =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(post_water_pbr_dof_result);
        REQUIRE(post_water_pbr_dof_result->depthStencilTexture()->readback(
            *device, 0, 0, {}, post_water_depth.data(),
            32 * sizeof(float), &error));
        CHECK(std::abs(
                  post_water_depth[material_pixel / 4] - 0.5f) <
              0.0001f);

        opaque_forward_scene.batches = post_water_batches.data();
        opaque_forward_scene.batch_count = post_water_batches.size();

        post_water_batches[1].pre_water_alpha_writes_coverage = true;
        auto post_water_coverage_result =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(post_water_coverage_result);
        std::array<std::uint16_t, 32 * 32 * 4>
            post_water_coverage_pixels{};
        REQUIRE(post_water_coverage_result->colorTexture(0)->readback(
            *device, 0, 0, {}, post_water_coverage_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(post_water_coverage_pixels[stencil_center + 3] >
              post_water_pixels[stencil_center + 3]);
        post_water_batches[1].pre_water_alpha_writes_coverage = false;

        ALMetalWorldSimpleBatch post_water_rigged = post_water_alpha;
        post_water_rigged.weight_offset = weight_offset;
        post_water_rigged.skin_palette = alpha_skin_palette.data();
        post_water_rigged.skin_palette_float_count =
            alpha_skin_palette.size();
        post_water_rigged.skin_joint_count = 1;
        post_water_batches[1] = post_water_rigged;
        auto post_water_rigged_result =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(post_water_rigged_result);
        REQUIRE(post_water_rigged_result->depthStencilTexture()->readback(
            *device, 0, 0, {}, post_water_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK(std::abs(
                  post_water_depth[stencil_center / 4] - 0.5f) <
              0.0001f);

        post_water_batches[1] = post_water_alpha;
        ALMetalWorldSimpleBatch post_water_legacy_glow =
            legacy_glow_batch;
        post_water_legacy_glow.post_water_glow = true;
        std::array<ALMetalWorldSimpleBatch, 3> post_water_glow_batches{{
            atmospheric_marker,
            post_water_alpha,
            post_water_legacy_glow,
        }};
        opaque_forward_scene.batches = post_water_glow_batches.data();
        opaque_forward_scene.batch_count =
            post_water_glow_batches.size();
        auto post_water_glow_result =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(post_water_glow_result);
        std::array<std::uint16_t, 32 * 32 * 4>
            post_water_glow_pixels{};
        REQUIRE(post_water_glow_result->colorTexture(0)->readback(
            *device, 0, 0, {}, post_water_glow_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(post_water_glow_pixels[stencil_center + 0] ==
              post_water_pixels[stencil_center + 0]);
        CHECK(post_water_glow_pixels[stencil_center + 1] ==
              post_water_pixels[stencil_center + 1]);
        CHECK(post_water_glow_pixels[stencil_center + 2] ==
              post_water_pixels[stencil_center + 2]);
        CHECK(post_water_glow_pixels[stencil_center + 3] >
              post_water_pixels[stencil_center + 3]);

        // Particle culling is disabled around the entire GL group, including
        // its alpha-only emissive replay. A reversed-winding glow draw must
        // therefore survive for particles while an ordinary draw is culled.
        post_water_glow_batches[2].indices = reversed_indices.get();
        post_water_glow_batches[2].pre_water_particle = false;
        auto culled_legacy_particle_glow =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(culled_legacy_particle_glow);
        REQUIRE(culled_legacy_particle_glow->colorTexture(0)->readback(
            *device, 0, 0, {}, post_water_glow_pixels.data(), 32 * 8,
            &error));
        CHECK(post_water_glow_pixels[stencil_center + 3] ==
              post_water_pixels[stencil_center + 3]);
        post_water_glow_batches[2].pre_water_particle = true;
        auto unculled_legacy_particle_glow =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(unculled_legacy_particle_glow);
        REQUIRE(unculled_legacy_particle_glow->colorTexture(0)->readback(
            *device, 0, 0, {}, post_water_glow_pixels.data(), 32 * 8,
            &error));
        CHECK(post_water_glow_pixels[stencil_center + 3] >
              post_water_pixels[stencil_center + 3]);

        // GL's particle colour draw clamps its diffuse sampler, but the
        // group-local legacy emissive TexSetup deliberately rebinds wrap.
        // Move glow sampling beyond U=1 and prove that preceding particle
        // state cannot change the replay's alpha result.
        post_water_glow_batches[2].indices = indices.get();
        post_water_glow_batches[2].diffuse_textures[0] =
            pbr_base_texture.get();
        post_water_glow_batches[2].texture_matrix[12] = 1.25f;
        post_water_glow_batches[2].pre_water_particle = true;
        post_water_glow_batches[1].pre_water_particle = false;
        auto wrapped_legacy_particle_glow =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(wrapped_legacy_particle_glow);
        REQUIRE(wrapped_legacy_particle_glow->colorTexture(0)->readback(
            *device, 0, 0, {}, post_water_glow_pixels.data(), 32 * 8,
            &error));
        const std::uint16_t wrapped_legacy_glow_alpha =
            post_water_glow_pixels[stencil_center + 3];
        CHECK(wrapped_legacy_glow_alpha >
              post_water_pixels[stencil_center + 3]);
        post_water_glow_batches[1].pre_water_particle = true;
        auto uncontaminated_legacy_particle_glow =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(uncontaminated_legacy_particle_glow);
        REQUIRE(uncontaminated_legacy_particle_glow->colorTexture(0)
                    ->readback(
                        *device, 0, 0, {},
                        post_water_glow_pixels.data(), 32 * 8, &error));
        CHECK(post_water_glow_pixels[stencil_center + 3] ==
              wrapped_legacy_glow_alpha);
        post_water_glow_batches[1].pre_water_particle = false;

        ALMetalWorldSimpleBatch post_water_pbr_glow = pbr_glow_batch;
        post_water_pbr_glow.post_water_glow = true;
        post_water_pbr_glow.pbr_slots[0].alpha_cutoff = 0.004f;
        post_water_glow_batches[2] = post_water_pbr_glow;
        auto post_water_pbr_glow_result =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(post_water_pbr_glow_result);
        REQUIRE(post_water_pbr_glow_result->colorTexture(0)->readback(
            *device, 0, 0, {}, post_water_glow_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(post_water_glow_pixels[stencil_center + 0] ==
              post_water_pixels[stencil_center + 0]);
        CHECK(post_water_glow_pixels[stencil_center + 1] ==
              post_water_pixels[stencil_center + 1]);
        CHECK(post_water_glow_pixels[stencil_center + 2] ==
              post_water_pixels[stencil_center + 2]);
        CHECK(post_water_glow_pixels[stencil_center + 3] >
              post_water_pixels[stencil_center + 3]);

        post_water_glow_batches[2].indices = reversed_indices.get();
        post_water_glow_batches[2].pre_water_particle = false;
        auto culled_pbr_particle_glow = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(culled_pbr_particle_glow);
        REQUIRE(culled_pbr_particle_glow->colorTexture(0)->readback(
            *device, 0, 0, {}, post_water_glow_pixels.data(), 32 * 8,
            &error));
        CHECK(post_water_glow_pixels[stencil_center + 3] ==
              post_water_pixels[stencil_center + 3]);
        post_water_glow_batches[2].pre_water_particle = true;
        auto unculled_pbr_particle_glow =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(unculled_pbr_particle_glow);
        REQUIRE(unculled_pbr_particle_glow->colorTexture(0)->readback(
            *device, 0, 0, {}, post_water_glow_pixels.data(), 32 * 8,
            &error));
        CHECK(post_water_glow_pixels[stencil_center + 3] >
              post_water_pixels[stencil_center + 3]);

        // PBR material binds also restore anisotropic wrap for the emissive
        // excursion. Exercise the same contaminated sampler transition with
        // transformed base/emissive coordinates and require an exact match.
        post_water_glow_batches[2].indices = indices.get();
        post_water_glow_batches[2].diffuse_textures[0] =
            pbr_base_texture.get();
        post_water_glow_batches[2].pbr_slots[0].emissive_texture =
            pbr_base_texture.get();
        post_water_glow_batches[2].pbr_slots[0].emissive_color[0] = 1.f;
        post_water_glow_batches[2].pbr_slots[0].emissive_color[1] = 1.f;
        post_water_glow_batches[2].pbr_slots[0].emissive_color[2] = 1.f;
        post_water_glow_batches[2].texture_matrix[12] = 1.25f;
        post_water_glow_batches[2].pre_water_particle = true;
        post_water_glow_batches[1].pre_water_particle = false;
        auto wrapped_pbr_particle_glow =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(wrapped_pbr_particle_glow);
        REQUIRE(wrapped_pbr_particle_glow->colorTexture(0)->readback(
            *device, 0, 0, {}, post_water_glow_pixels.data(), 32 * 8,
            &error));
        const std::uint16_t wrapped_pbr_glow_alpha =
            post_water_glow_pixels[stencil_center + 3];
        CHECK(wrapped_pbr_glow_alpha >
              post_water_pixels[stencil_center + 3]);
        post_water_glow_batches[1].pre_water_particle = true;
        auto uncontaminated_pbr_particle_glow =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(uncontaminated_pbr_particle_glow);
        REQUIRE(uncontaminated_pbr_particle_glow->colorTexture(0)->readback(
            *device, 0, 0, {}, post_water_glow_pixels.data(), 32 * 8,
            &error));
        CHECK(post_water_glow_pixels[stencil_center + 3] ==
              wrapped_pbr_glow_alpha);

        post_water_batches[1].modelview[14] = -2.f;
        opaque_forward_scene.batches = post_water_batches.data();
        opaque_forward_scene.batch_count = post_water_batches.size();
        auto clipped_post_water = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(clipped_post_water);
        REQUIRE(clipped_post_water->colorTexture(0)->readback(
            *device, 0, 0, {}, post_water_glow_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(post_water_glow_pixels[stencil_center + 0] ==
              atmospheric_pixels[stencil_center + 0]);
        CHECK(post_water_glow_pixels[stencil_center + 1] ==
              atmospheric_pixels[stencil_center + 1]);
        CHECK(post_water_glow_pixels[stencil_center + 2] ==
              atmospheric_pixels[stencil_center + 2]);

        std::array<ALMetalWorldSimpleBatch, 2>
            post_water_before_atmosphere{{
                post_water_alpha,
                atmospheric_marker,
            }};
        opaque_forward_scene.batches =
            post_water_before_atmosphere.data();
        opaque_forward_scene.batch_count =
            post_water_before_atmosphere.size();
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        CHECK(error == "Metal world water-haze ordering is invalid");
        error.clear();

        post_water_batches[1] = post_water_alpha;
        post_water_batches[1].modelview_projection[14] = 0.25f;
        opaque_forward_scene.batches = post_water_batches.data();
        opaque_forward_scene.batch_count = post_water_batches.size();
        opaque_forward_scene.gbuffer = reverse_coverage_result.get();
        opaque_forward_scene.reverse_z = true;
        auto reverse_post_water = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_post_water);
        std::array<std::uint16_t, 32 * 32 * 4>
            reverse_post_water_pixels{};
        REQUIRE(reverse_post_water->colorTexture(0)->readback(
            *device, 0, 0, {}, reverse_post_water_pixels.data(), 32 * 8,
            &error));
        REQUIRE(reverse_post_water->depthStencilTexture()->readback(
            *device, 0, 0, {}, post_water_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK(std::abs(
                  post_water_depth[stencil_center / 4] - 0.25f) <
              0.0001f);

        ALMetalWorldSimpleBatch reverse_post_water_depth =
            post_water_batches[1];
        reverse_post_water_depth.post_water_depth_only = true;
        reverse_post_water_depth.pre_water_minimum_alpha = 0.33f;
        std::array<ALMetalWorldSimpleBatch, 3> reverse_post_water_dof{{
            atmospheric_marker,
            post_water_batches[1],
            reverse_post_water_depth,
        }};
        opaque_forward_scene.batches = reverse_post_water_dof.data();
        opaque_forward_scene.batch_count = reverse_post_water_dof.size();
        auto reverse_post_water_dof_result =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(reverse_post_water_dof_result);
        REQUIRE(reverse_post_water_dof_result->colorTexture(0)->readback(
            *device, 0, 0, {}, post_water_dof_pixels.data(), 32 * 8,
            &error));
        REQUIRE(reverse_post_water_dof_result->depthStencilTexture()
                    ->readback(
                        *device, 0, 0, {}, post_water_depth.data(),
                        32 * sizeof(float), &error));
        CHECK(post_water_dof_pixels == reverse_post_water_pixels);
        CHECK(std::abs(
                  post_water_depth[stencil_center / 4] - 0.5f) <
              0.0001f);

        atmospheric_haze = {};
        opaque_forward_scene.batches = &fullbright_batch;
        opaque_forward_scene.batch_count = 1;
        opaque_forward_scene.gbuffer = coverage_result.get();
        opaque_forward_scene.water_exclusion_surface = nullptr;
        opaque_forward_scene.water_haze = nullptr;
        opaque_forward_scene.water_surface = nullptr;
        opaque_forward_scene.atmospheric_haze = nullptr;
        opaque_forward_scene.sky_behind = nullptr;
        opaque_forward_scene.alpha_environment = nullptr;

        ALMetalWorldSimpleBatch shiny_batch = fullbright_batch;
        shiny_batch.impostor_fullbright = false;
        shiny_batch.impostor_shiny = true;
        shiny_batch.alpha_mask = false;
        for (std::size_t index = 0; index < 4; ++index)
        {
            shiny_batch.modelview[index * 4 + index] = 1.f;
        }
        alpha_scene.batches = &shiny_batch;
        alpha_scene.stamp_opaque_coverage = false;
        alpha_scene.reflection_probes = nullptr;
        CHECK_FALSE(renderer->compositeImpostorPostDeferred(
            *coverage_result, alpha_scene, &error));
        CHECK(error ==
              "Metal world shiny impostor reflection probes are invalid");
        error.clear();
        alpha_scene.reflection_probes = &reflection_probes;
        REQUIRE(renderer->compositeImpostorPostDeferred(
            *coverage_result, alpha_scene, &error));
        INFO(error);
        REQUIRE(coverage_result->colorTexture(0)->readback(
            *device, 0, 0, {}, alpha_albedo.data(), 32 * 4, &error));
        REQUIRE(coverage_result->colorTexture(1)->readback(
            *device, 0, 0, {}, alpha_orm.data(), 32 * 4, &error));
        REQUIRE(coverage_result->depthStencilTexture()->readback(
            *device, 0, 0, {}, alpha_depth.data(), 32 * sizeof(float),
            &error));
        INFO(error);
        CHECK(alpha_albedo[fullbright_top + 0] == 0);
        CHECK(std::abs(static_cast<int>(
                           alpha_albedo[fullbright_top + 1]) - 188) <= 2);
        CHECK(std::abs(static_cast<int>(
                           alpha_albedo[fullbright_top + 2]) - 99) <= 2);
        CHECK(alpha_albedo[fullbright_top + 3] == 255);
        CHECK(alpha_orm[fullbright_top + 0] == 0);
        CHECK(alpha_orm[fullbright_top + 1] == 0);
        CHECK(alpha_orm[fullbright_top + 2] == 0);
        CHECK(alpha_orm[fullbright_top + 3] == 0);
        CHECK(std::abs(alpha_depth[24 * 32 + 8] - 0.625f) < 0.0001f);

        // fullbrightShinyF also finishes its legacy radiance tap with the
        // hero probe at glossiness one. Replace blue cube radiance with red
        // and require the reflected channel to move without changing the
        // diffuse green contribution or opaque coverage.
        auto red_hero_upload = device->makeCommandBuffer(
            "Alchemy world hero-probe red upload", &error);
        INFO(error);
        REQUIRE(red_hero_upload);
        const std::array<std::uint8_t, 4> red_hero{{255, 0, 0, 255}};
        for (std::uint32_t face = 0; face < 6; ++face)
        {
            REQUIRE(hero_texture->upload(
                *red_hero_upload, 0, face, {}, red_hero.data(), 4,
                &error));
        }
        REQUIRE(red_hero_upload->commitAndWait(&error));
        INFO(error);
        alpha_scene.hero_probe = &hero_probe;
        REQUIRE(renderer->compositeImpostorPostDeferred(
            *coverage_result, alpha_scene, &error));
        INFO(error);
        REQUIRE(coverage_result->colorTexture(0)->readback(
            *device, 0, 0, {}, alpha_albedo.data(), 32 * 4, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(
                           alpha_albedo[fullbright_top + 0]) - 99) <= 2);
        CHECK(std::abs(static_cast<int>(
                           alpha_albedo[fullbright_top + 1]) - 188) <= 2);
        CHECK(alpha_albedo[fullbright_top + 2] == 0);
        CHECK(alpha_albedo[fullbright_top + 3] == 255);
        alpha_scene.hero_probe = nullptr;

        // The rigged owner uses the same probe traversal after applying its
        // rebased palette to eye position and normal, and remains an opaque
        // depth-writing pass.
        shiny_batch.modelview_projection[12] = 0.8f;
        shiny_batch.weight_offset = weight_offset;
        shiny_batch.skin_palette = alpha_skin_palette.data();
        shiny_batch.skin_palette_float_count = alpha_skin_palette.size();
        shiny_batch.skin_joint_count = 1;
        REQUIRE(renderer->compositeImpostorPostDeferred(
            *coverage_result, alpha_scene, &error));
        INFO(error);
        REQUIRE(coverage_result->colorTexture(0)->readback(
            *device, 0, 0, {}, alpha_albedo.data(), 32 * 4, &error));
        REQUIRE(coverage_result->depthStencilTexture()->readback(
            *device, 0, 0, {}, alpha_depth.data(), 32 * sizeof(float),
            &error));
        INFO(error);
        const std::size_t shiny_top_right = (24 * 32 + 24) * 4;
        CHECK(alpha_albedo[shiny_top_right + 0] == 0);
        CHECK(std::abs(static_cast<int>(
                           alpha_albedo[shiny_top_right + 1]) - 188) <= 2);
        CHECK(std::abs(static_cast<int>(
                           alpha_albedo[shiny_top_right + 2]) - 99) <= 2);
        CHECK(alpha_albedo[shiny_top_right + 3] == 255);
        CHECK(std::abs(alpha_depth[24 * 32 + 24] - 0.625f) < 0.0001f);

        // Restore the original fullbright source colour before the chained
        // emboss assertions below; shiny was deliberately tested at the same
        // static pixel so its probe mix could be compared directly.
        alpha_scene.batches = &fullbright_batch;
        alpha_scene.reflection_probes = nullptr;
        alpha_scene.stamp_opaque_coverage = true;
        REQUIRE(renderer->compositeImpostorPostDeferred(
            *coverage_result, alpha_scene, &error));
        INFO(error);

        // The post-bump owner samples one bump texture at its two precomputed
        // UV streams, then applies GL's BT_MULT_X2 blend to RGB only. A
        // half-strength emboss result dims linear green to its sRGB 188 byte
        // while preserving full coverage, every other attachment and depth.
        ALMetalWorldSimpleBatch emboss_batch = fullbright_batch;
        emboss_batch.impostor_fullbright = false;
        emboss_batch.impostor_emboss = true;
        emboss_batch.alpha_mask = false;
        emboss_batch.texcoord1_offset = emboss_texcoord_offset;
        emboss_batch.diffuse_textures[0] = emboss_bump.get();
        emboss_batch.texture_count = 1;
        emboss_batch.texture_matrix[12] = 0.25f;
        alpha_scene.batches = &emboss_batch;
        alpha_scene.stamp_opaque_coverage = false;
        REQUIRE(renderer->compositeImpostorPostDeferred(
            *coverage_result, alpha_scene, &error));
        INFO(error);
        REQUIRE(coverage_result->colorTexture(0)->readback(
            *device, 0, 0, {}, alpha_albedo.data(), 32 * 4, &error));
        REQUIRE(coverage_result->colorTexture(1)->readback(
            *device, 0, 0, {}, alpha_orm.data(), 32 * 4, &error));
        REQUIRE(coverage_result->depthStencilTexture()->readback(
            *device, 0, 0, {}, alpha_depth.data(), 32 * sizeof(float),
            &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(
                           alpha_albedo[fullbright_top + 1]) - 188) <= 2);
        CHECK(alpha_albedo[fullbright_top + 3] == 255);
        CHECK(alpha_orm[fullbright_top + 0] == 0);
        CHECK(alpha_orm[fullbright_top + 1] == 0);
        CHECK(alpha_orm[fullbright_top + 2] == 0);
        CHECK(alpha_orm[fullbright_top + 3] == 0);
        CHECK(std::abs(alpha_depth[24 * 32 + 8] - 0.625f) < 0.0001f);

        emboss_batch.weight_offset = weight_offset;
        emboss_batch.skin_palette = alpha_skin_palette.data();
        emboss_batch.skin_palette_float_count =
            alpha_skin_palette.size();
        emboss_batch.skin_joint_count = 1;
        REQUIRE(renderer->compositeImpostorPostDeferred(
            *coverage_result, alpha_scene, &error));
        INFO(error);
        REQUIRE(coverage_result->colorTexture(0)->readback(
            *device, 0, 0, {}, alpha_albedo.data(), 32 * 4, &error));
        REQUIRE(coverage_result->depthStencilTexture()->readback(
            *device, 0, 0, {}, alpha_depth.data(), 32 * sizeof(float),
            &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(
                           alpha_albedo[fullbright_top + 1]) - 137) <= 2);
        CHECK(alpha_albedo[fullbright_top + 3] == 255);
        CHECK(std::abs(alpha_depth[24 * 32 + 8] - 0.625f) < 0.0001f);

        scene.hdr = false;

        batch.tangent_offset =
            (vertex_bytes.size() + 15) & ~std::size_t{15};
        CHECK_FALSE(renderer->render(scene, &error));
        CHECK(error ==
              "Metal world simple geometry range exceeds its buffers");
        batch.tangent_offset = tangent_offset;
        error.clear();
        auto pbr_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(pbr_result);
        std::array<std::uint8_t, 32 * 32 * 4> pbr_albedo{};
        std::array<std::uint8_t, 32 * 32 * 4> pbr_orm{};
        std::array<std::uint16_t, 32 * 32 * 4> pbr_normal{};
        std::array<std::uint8_t, 32 * 32 * 4> pbr_emissive{};
        REQUIRE(pbr_result->colorTexture(0)->readback(
            *device, 0, 0, {}, pbr_albedo.data(), 32 * 4, &error));
        REQUIRE(pbr_result->colorTexture(1)->readback(
            *device, 0, 0, {}, pbr_orm.data(), 32 * 4, &error));
        REQUIRE(pbr_result->colorTexture(2)->readback(
            *device, 0, 0, {}, pbr_normal.data(), 32 * 8, &error));
        REQUIRE(pbr_result->colorTexture(3)->readback(
            *device, 0, 0, {}, pbr_emissive.data(), 32 * 4, &error));
        INFO(error);
        CHECK(pbr_albedo[center + 0] == 0);
        CHECK(pbr_albedo[center + 1] == 255);
        CHECK(pbr_albedo[center + 2] == 0);
        CHECK(pbr_albedo[center + 3] == 0);
        CHECK(std::abs(static_cast<int>(pbr_orm[center + 0]) - 128) <= 1);
        CHECK(std::abs(static_cast<int>(pbr_orm[center + 1]) - 64) <= 1);
        CHECK(std::abs(static_cast<int>(pbr_orm[center + 2]) - 32) <= 1);
        CHECK(pbr_orm[center + 3] <= 1);
        CHECK(pbr_normal[center + 0] > 65000);
        CHECK(std::abs(static_cast<int>(pbr_normal[center + 2]) -
                       32896) <= 2);
        CHECK(std::abs(static_cast<int>(pbr_normal[center + 3]) -
                       43908) <= 2);
        CHECK(std::abs(static_cast<int>(pbr_emissive[center + 0]) - 28) <= 1);
        CHECK(std::abs(static_cast<int>(pbr_emissive[center + 1]) - 13) <= 1);
        CHECK(pbr_emissive[center + 2] == 0);

        // PBR derives its clip distance from the eye-space position packed
        // alongside its material constants. Keep this separate from the
        // simple-path mirror test above: a zeroed PBR model-view matrix makes
        // every distance zero and incorrectly retains the whole triangle.
        scene.mirror_clip = true;
        scene.mirror_clip_plane[0] = 1.f;
        scene.mirror_clip_plane[1] = 0.f;
        scene.mirror_clip_plane[2] = 0.f;
        scene.mirror_clip_plane[3] = 0.f;
        auto pbr_mirror_clipped = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(pbr_mirror_clipped);
        std::array<std::uint8_t, 32 * 32 * 4> pbr_clipped_albedo{};
        REQUIRE(pbr_mirror_clipped->colorTexture(0)->readback(
            *device, 0, 0, {}, pbr_clipped_albedo.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(pbr_clipped_albedo[clipped_side + 0] == 255);
        CHECK(pbr_clipped_albedo[clipped_side + 1] == 0);
        CHECK(pbr_clipped_albedo[clipped_side + 2] == 255);
        CHECK(pbr_clipped_albedo[retained_side + 0] == 0);
        CHECK(pbr_clipped_albedo[retained_side + 1] == 255);
        CHECK(pbr_clipped_albedo[retained_side + 2] == 0);
        scene.mirror_clip = false;

        constexpr float half_pi = 1.5707963267948966f;
        batch.pbr_slots[0].texture_transform[1][2] = half_pi;
        batch.pbr_slots[1].texture_transform[1][2] = half_pi;
        auto rotated_pbr_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(rotated_pbr_result);
        std::array<std::uint16_t, 32 * 32 * 4> rotated_pbr_normal{};
        REQUIRE(rotated_pbr_result->colorTexture(2)->readback(
            *device, 0, 0, {}, rotated_pbr_normal.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(rotated_pbr_normal[center + 0]) -
                       32768) < 512);
        CHECK(rotated_pbr_normal[center + 1] < 512);
        batch.pbr_slots[0].texture_transform[1][2] = 0.f;
        batch.pbr_slots[1].texture_transform[1][2] = 0.f;

        batch.pbr_slot_count = 1;
        batch.texture_count = 1;
        auto scalar_pbr_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(scalar_pbr_result);
        std::array<std::uint8_t, 32 * 32 * 4> scalar_pbr_albedo{};
        REQUIRE(scalar_pbr_result->colorTexture(0)->readback(
            *device, 0, 0, {}, scalar_pbr_albedo.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(scalar_pbr_albedo[center + 0] == 0);
        CHECK(scalar_pbr_albedo[center + 1] == 255);
        CHECK(scalar_pbr_albedo[center + 2] == 0);
        batch.pbr_slot_count = 2;
        batch.texture_count = 2;

        // A masked PBR texel uses base texture alpha times streamed alpha and
        // the same half-byte equality bias as the GL owner.
        batch.alpha_mask = true;
        batch.pbr_slots[0].alpha_cutoff = 0.6f;
        batch.pbr_slots[1].alpha_cutoff = 0.6f;
        auto pbr_masked_out = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(pbr_masked_out);
        std::array<std::uint8_t, 32 * 32 * 4> pbr_masked_albedo{};
        REQUIRE(pbr_masked_out->colorTexture(0)->readback(
            *device, 0, 0, {}, pbr_masked_albedo.data(), 32 * 4, &error));
        INFO(error);
        CHECK(pbr_masked_albedo[center + 0] == 255);
        CHECK(pbr_masked_albedo[center + 1] == 0);
        CHECK(pbr_masked_albedo[center + 2] == 255);
        batch.pbr_slots[0].alpha_cutoff = 0.253f;
        batch.pbr_slots[1].alpha_cutoff = 0.253f;
        auto pbr_masked_in = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(pbr_masked_in);
        REQUIRE(pbr_masked_in->colorTexture(0)->readback(
            *device, 0, 0, {}, pbr_masked_albedo.data(), 32 * 4, &error));
        INFO(error);
        CHECK(pbr_masked_albedo[center + 0] == 0);
        CHECK(pbr_masked_albedo[center + 1] == 255);
        CHECK(pbr_masked_albedo[center + 2] == 0);

        // Reuse the same complete PBR contract through object skinning.
        batch.alpha_mask = false;
        batch.pbr_slots[0].alpha_cutoff = -1.f;
        batch.pbr_slots[1].alpha_cutoff = -1.f;
        batch.weight_offset = weight_offset;
        batch.skin_palette = skin_palette.data();
        batch.skin_palette_float_count = skin_palette.size();
        batch.skin_joint_count = 1;
        auto skinned_pbr_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(skinned_pbr_result);
        std::array<std::uint8_t, 32 * 32 * 4> skinned_pbr_albedo{};
        REQUIRE(skinned_pbr_result->colorTexture(0)->readback(
            *device, 0, 0, {}, skinned_pbr_albedo.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(skinned_pbr_albedo[translated_center + 0] == 0);
        CHECK(skinned_pbr_albedo[translated_center + 1] == 255);
        CHECK(skinned_pbr_albedo[translated_center + 2] == 0);

        // System-avatar eyes and body meshes have no streamed color. Rigid
        // parts use the live matrix stack; weighted parts use the legacy
        // scalar joint/blend stream and exact 45-float4 eye-space palette.
        batch = ALMetalWorldSimpleBatch{};
        batch.vertices = avatar_vertices.get();
        batch.position_offset = 0;
        batch.normal_offset = normal_offset;
        batch.texcoord_offset = texcoord_offset;
        batch.vertex_count = positions.size();
        batch.indices = indices.get();
        batch.index_count = index_values.size();
        batch.diffuse_textures[0] = diffuse.get();
        batch.texture_count = 1;
        batch.alpha_mask = true;
        batch.use_vertex_color = false;
        batch.alpha_cutoff_bias = false;
        batch.alpha_cutoff = 0.2f;
        batch.avatar_rigid = true;
        for (std::size_t index = 0; index < 4; ++index)
        {
            batch.modelview_projection[index * 4 + index] = 1.f;
            batch.modelview[index * 4 + index] = 1.f;
        }
        for (std::size_t index = 0; index < 3; ++index)
        {
            batch.normal_matrix[index][index] = 1.f;
        }
        scene.hdr = true;

        batch.avatar_skinning = true;
        CHECK_FALSE(renderer->render(scene, &error));
        CHECK(error == "Metal world simple batch is invalid");
        batch.avatar_skinning = false;
        error.clear();
        auto avatar_rigid_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(avatar_rigid_result);
        std::array<std::uint8_t, 32 * 32 * 4> avatar_rigid_albedo{};
        std::array<std::uint8_t, 32 * 32 * 4> avatar_rigid_specular{};
        REQUIRE(avatar_rigid_result->colorTexture(0)->readback(
            *device, 0, 0, {}, avatar_rigid_albedo.data(), 32 * 4,
            &error));
        REQUIRE(avatar_rigid_result->colorTexture(1)->readback(
            *device, 0, 0, {}, avatar_rigid_specular.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(avatar_rigid_albedo[center + 0]) -
                       128) <= 1);
        CHECK(std::abs(static_cast<int>(avatar_rigid_albedo[center + 1]) -
                       64) <= 1);
        CHECK(std::abs(static_cast<int>(avatar_rigid_albedo[center + 2]) -
                       32) <= 1);
        CHECK(avatar_rigid_specular[center + 0] == 0);
        CHECK(avatar_rigid_specular[center + 1] == 0);
        CHECK(avatar_rigid_specular[center + 2] == 0);
        CHECK(avatar_rigid_specular[center + 3] == 0);

        std::array<float, 45 * 4> avatar_palette{};
        avatar_palette[0] = 1.f;
        avatar_palette[3] = 0.75f;
        avatar_palette[15 * 4 + 1] = 1.f;
        avatar_palette[30 * 4 + 2] = 1.f;
        batch.avatar_rigid = false;
        batch.avatar_skinning = true;
        batch.weight_offset = avatar_weight_offset;
        batch.skin_palette = avatar_palette.data();
        batch.skin_palette_float_count = avatar_palette.size() - 1;
        batch.skin_joint_count = 15;
        CHECK_FALSE(renderer->render(scene, &error));
        CHECK(error == "Metal world avatar skinning data is invalid");
        batch.skin_palette_float_count = avatar_palette.size();
        error.clear();
        auto avatar_skinned_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(avatar_skinned_result);
        std::array<std::uint8_t, 32 * 32 * 4> avatar_skinned_albedo{};
        REQUIRE(avatar_skinned_result->colorTexture(0)->readback(
            *device, 0, 0, {}, avatar_skinned_albedo.data(), 32 * 4,
            &error));
        INFO(error);
        const std::size_t avatar_translated = (16 * 32 + 24) * 4;
        CHECK(avatar_skinned_albedo[center + 0] == 255);
        CHECK(avatar_skinned_albedo[center + 1] == 0);
        CHECK(avatar_skinned_albedo[center + 2] == 255);
        CHECK(std::abs(static_cast<int>(
                           avatar_skinned_albedo[avatar_translated + 0]) -
                       128) <= 1);
        CHECK(std::abs(static_cast<int>(
                           avatar_skinned_albedo[avatar_translated + 1]) -
                       64) <= 1);

        // The main-world avatar alpha pool is ordered before glow and the
        // ordinary pre-water alpha pool. It therefore has its own forward
        // family, while retaining the system-avatar scalar skin weights,
        // fixed 45-float4 palette and the same simple-alpha lighting pack.
        ALMetalWorldSimpleBatch avatar_alpha_batch = batch;
        avatar_alpha_batch.alpha_mask = false;
        avatar_alpha_batch.alpha_cutoff = 0.f;
        avatar_alpha_batch.avatar_alpha = true;
        avatar_alpha_batch.pre_water_simple = true;
        avatar_alpha_batch.pre_water_shadows = false;
        avatar_alpha_batch.pre_water_minimum_alpha = 0.2f;
        avatar_alpha_batch.pre_water_alpha_writes_coverage = false;
        ALMetalWorldSimpleBatch avatar_alpha_base_batch = batch;
        avatar_alpha_base_batch.modelview_projection[12] = -4.f;
        ALMetalWorldGBufferScene avatar_alpha_base_scene = scene;
        avatar_alpha_base_scene.batches = &avatar_alpha_base_batch;
        avatar_alpha_base_scene.batch_count = 1;
        auto avatar_alpha_gbuffer = renderer->render(
            avatar_alpha_base_scene, &error);
        INFO(error);
        REQUIRE(avatar_alpha_gbuffer);
        ALMetalWorldAlphaEnvironment avatar_alpha_environment =
            alpha_environment;
        avatar_alpha_environment.water_plane[0] = 0.f;
        avatar_alpha_environment.water_plane[1] = 0.f;
        avatar_alpha_environment.water_plane[2] = 1.f;
        avatar_alpha_environment.water_plane[3] = -1.f;
        avatar_alpha_environment.water_fog[2] = -1.f;
        opaque_forward_scene = {};
        opaque_forward_scene.gbuffer = avatar_alpha_gbuffer.get();
        opaque_forward_scene.composed_lighting = final_light.get();
        opaque_forward_scene.batches = &avatar_alpha_batch;
        opaque_forward_scene.batch_count = 1;
        opaque_forward_scene.reflection_probes = &reflection_probes;
        opaque_forward_scene.alpha_environment =
            &avatar_alpha_environment;
        opaque_forward_scene.alpha_lighting = &simple_alpha_lighting;
        opaque_forward_scene.width = 32;
        opaque_forward_scene.height = 32;
        opaque_forward_scene.hdr = true;
        avatar_alpha_batch.skin_palette_float_count =
            avatar_palette.size() - 1;
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        avatar_alpha_batch.skin_palette_float_count =
            avatar_palette.size();
        error.clear();
        auto avatar_alpha_result = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(avatar_alpha_result);

        // Transparent hair and skirts submit the same mesh two or three
        // times. Prove the native sidecar retains the GL owner's per-draw
        // state rather than turning every replay into a back-culled,
        // color-and-depth-writing pass.
        std::array<std::uint16_t, 32 * 32 * 4>
            avatar_alpha_color{};
        std::array<std::uint16_t, 32 * 32 * 4>
            avatar_alpha_base_color{};
        std::array<float, 32 * 32> avatar_alpha_depth{};
        std::array<float, 32 * 32> avatar_alpha_base_depth{};
        REQUIRE(avatar_alpha_result->colorTexture(0)->readback(
            *device, 0, 0, {}, avatar_alpha_color.data(), 32 * 8,
            &error));
        REQUIRE(final_light->colorTexture(0)->readback(
            *device, 0, 0, {}, avatar_alpha_base_color.data(), 32 * 8,
            &error));
        REQUIRE(avatar_alpha_result->depthStencilTexture()->readback(
            *device, 0, 0, {}, avatar_alpha_depth.data(),
            32 * sizeof(float), &error));
        REQUIRE(avatar_alpha_gbuffer->depthStencilTexture()->readback(
            *device, 0, 0, {}, avatar_alpha_base_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        std::size_t avatar_alpha_pixel = avatar_alpha_depth.size();
        std::size_t avatar_alpha_color_pixels = 0;
        std::size_t avatar_alpha_depth_pixels = 0;
        for (std::size_t pixel = 0;
             pixel < avatar_alpha_depth.size(); ++pixel)
        {
            const std::size_t sample = pixel * 4;
            const bool color_changed =
                avatar_alpha_color[sample + 0] !=
                    avatar_alpha_base_color[sample + 0] ||
                avatar_alpha_color[sample + 1] !=
                    avatar_alpha_base_color[sample + 1] ||
                avatar_alpha_color[sample + 2] !=
                    avatar_alpha_base_color[sample + 2] ||
                avatar_alpha_color[sample + 3] !=
                    avatar_alpha_base_color[sample + 3];
            const bool depth_changed =
                std::abs(avatar_alpha_depth[pixel] -
                         avatar_alpha_base_depth[pixel]) > 0.1f;
            avatar_alpha_color_pixels += color_changed ? 1 : 0;
            avatar_alpha_depth_pixels += depth_changed ? 1 : 0;
            if (avatar_alpha_pixel == avatar_alpha_depth.size() &&
                color_changed && depth_changed)
            {
                avatar_alpha_pixel = pixel;
            }
        }
        CAPTURE(avatar_alpha_color_pixels, avatar_alpha_depth_pixels);
        REQUIRE(avatar_alpha_color_pixels > 0);
        REQUIRE(avatar_alpha_depth_pixels > 0);
        REQUIRE(avatar_alpha_pixel < avatar_alpha_depth.size());
        const std::size_t avatar_alpha_sample = avatar_alpha_pixel * 4;
        CHECK(std::abs(half_to_float(
                           avatar_alpha_color[avatar_alpha_sample]) -
                       half_to_float(
                           avatar_alpha_base_color[avatar_alpha_sample])) >
              0.01f);
        CHECK(std::abs(avatar_alpha_depth[avatar_alpha_pixel] -
                       avatar_alpha_base_depth[avatar_alpha_pixel]) >
              0.1f);
        CHECK(avatar_alpha_color[avatar_alpha_sample + 3] ==
              avatar_alpha_base_color[avatar_alpha_sample + 3]);

        // First/third high-detail passes and the low-detail inside pass
        // blend color while retaining the incoming depth.
        avatar_alpha_batch.avatar_depth_write = false;
        auto avatar_alpha_readonly_depth =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(avatar_alpha_readonly_depth);
        REQUIRE(avatar_alpha_readonly_depth->depthStencilTexture()->readback(
            *device, 0, 0, {}, avatar_alpha_depth.data(),
            32 * sizeof(float), &error));
        REQUIRE(avatar_alpha_readonly_depth->colorTexture(0)->readback(
            *device, 0, 0, {}, avatar_alpha_color.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(std::abs(avatar_alpha_depth[avatar_alpha_pixel] -
                       avatar_alpha_base_depth[avatar_alpha_pixel]) <
              0.0001f);
        CHECK(std::abs(half_to_float(
                           avatar_alpha_color[avatar_alpha_sample]) -
                       half_to_float(
                           avatar_alpha_base_color[avatar_alpha_sample])) >
              0.01f);
        CHECK(avatar_alpha_color[avatar_alpha_sample + 3] ==
              avatar_alpha_base_color[avatar_alpha_sample + 3]);

        // The middle high-detail pass runs the alpha cutout and writes depth
        // but must leave every color channel untouched.
        avatar_alpha_batch.avatar_depth_write = true;
        avatar_alpha_batch.avatar_color_write = false;
        auto avatar_alpha_depth_only = renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(avatar_alpha_depth_only);
        REQUIRE(avatar_alpha_depth_only->depthStencilTexture()->readback(
            *device, 0, 0, {}, avatar_alpha_depth.data(),
            32 * sizeof(float), &error));
        REQUIRE(avatar_alpha_depth_only->colorTexture(0)->readback(
            *device, 0, 0, {}, avatar_alpha_color.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(std::abs(avatar_alpha_depth[avatar_alpha_pixel] -
                       avatar_alpha_base_depth[avatar_alpha_pixel]) >
              0.1f);
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(avatar_alpha_color[avatar_alpha_sample + channel] ==
                  avatar_alpha_base_color[avatar_alpha_sample + channel]);
        }

        // This fixture is front-facing. Front-culling therefore suppresses
        // it completely, while the ordinary back-cull state above retains
        // it; this is the low-detail inside/outside distinction.
        avatar_alpha_batch.avatar_color_write = true;
        avatar_alpha_batch.avatar_cull_mode = ALMetalCullMode::front;
        auto avatar_alpha_front_culled =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(avatar_alpha_front_culled);
        REQUIRE(avatar_alpha_front_culled->depthStencilTexture()->readback(
            *device, 0, 0, {}, avatar_alpha_depth.data(),
            32 * sizeof(float), &error));
        REQUIRE(avatar_alpha_front_culled->colorTexture(0)->readback(
            *device, 0, 0, {}, avatar_alpha_color.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(std::abs(avatar_alpha_depth[avatar_alpha_pixel] -
                       avatar_alpha_base_depth[avatar_alpha_pixel]) <
              0.0001f);
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(avatar_alpha_color[avatar_alpha_sample + channel] ==
                  avatar_alpha_base_color[avatar_alpha_sample + channel]);
        }
        avatar_alpha_batch.avatar_cull_mode =
            static_cast<ALMetalCullMode>(99);
        CHECK_FALSE(renderer->renderOpaquePostDeferred(
            opaque_forward_scene, &error));
        avatar_alpha_batch.avatar_cull_mode = ALMetalCullMode::back;
        error.clear();

        avatar_alpha_batch.avatar_cloth = true;
        avatar_alpha_batch.cloth_offset = avatar_cloth_offset;
        avatar_alpha_batch.avatar_wind[0] = 1.f;
        avatar_alpha_batch.avatar_wind[3] = 1.f;
        avatar_alpha_batch.avatar_sin_wave[3] = 3.141592f;
        auto avatar_alpha_cloth_result =
            renderer->renderOpaquePostDeferred(
                opaque_forward_scene, &error);
        INFO(error);
        REQUIRE(avatar_alpha_cloth_result);

        // With a unit wind strength and phase PI, the owner's minimax sine
        // produces a unit primary displacement. The clothing X vector moves
        // this triangle another quarter clip unit; its X wind also turns the
        // stored normal through the same exaggerated legacy perturbation.
        batch.avatar_cloth = true;
        batch.cloth_offset = avatar_cloth_offset;
        batch.avatar_wind[0] = 1.f;
        batch.avatar_wind[3] = 1.f;
        batch.avatar_sin_wave[3] = 3.141592f;
        auto avatar_cloth_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(avatar_cloth_result);
        std::array<std::uint8_t, 32 * 32 * 4> avatar_cloth_albedo{};
        std::array<std::uint16_t, 32 * 32 * 4> avatar_cloth_normal{};
        REQUIRE(avatar_cloth_result->colorTexture(0)->readback(
            *device, 0, 0, {}, avatar_cloth_albedo.data(), 32 * 4,
            &error));
        REQUIRE(avatar_cloth_result->colorTexture(2)->readback(
            *device, 0, 0, {}, avatar_cloth_normal.data(), 32 * 8,
            &error));
        INFO(error);
        const std::size_t avatar_cloth_translated = (16 * 32 + 28) * 4;
        CHECK(avatar_cloth_albedo[avatar_translated + 0] == 255);
        CHECK(avatar_cloth_albedo[avatar_translated + 1] == 0);
        CHECK(avatar_cloth_albedo[avatar_translated + 2] == 255);
        CHECK(std::abs(static_cast<int>(
                           avatar_cloth_albedo[
                               avatar_cloth_translated + 0]) - 128) <= 1);
        CHECK(avatar_cloth_normal[avatar_cloth_translated + 0] > 40000);
        CHECK(std::abs(static_cast<int>(
                           avatar_cloth_normal[
                               avatar_cloth_translated + 1]) - 32768) <= 2);
    }
}

TEST_CASE("almetal: avatar impostor replays a coherent baked G-buffer", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        auto renderer = ALMetalWorldGBufferRenderer::create(*device, &error);
        INFO(error);
        REQUIRE(renderer);

        const auto make_texture = [&device, &error](
            ALMetalPixelFormat format, const char* label)
        {
            ALMetalTextureDescriptor descriptor;
            descriptor.format = format;
            descriptor.width = 1;
            descriptor.height = 1;
            descriptor.storage = ALMetalStorageMode::private_gpu;
            descriptor.usage = ALMetalTextureUsage::shader_read;
            descriptor.label = label;
            auto texture = ALMetalTexture::create(
                *device, descriptor, &error);
            INFO(error);
            REQUIRE(texture);
            return texture;
        };

        auto albedo = make_texture(
            ALMetalPixelFormat::rgba8_unorm_srgb,
            "Alchemy impostor baked albedo");
        auto specular = make_texture(
            ALMetalPixelFormat::rgba8_unorm,
            "Alchemy impostor baked specular ORM");
        auto normal = make_texture(
            ALMetalPixelFormat::rgba16_unorm,
            "Alchemy impostor baked normal");
        auto emissive = make_texture(
            ALMetalPixelFormat::rgba8_unorm,
            "Alchemy impostor baked emissive");

        const std::array<std::uint8_t, 4> albedo_pixel{{
            128, 64, 32, 128,
        }};
        const std::array<std::uint8_t, 4> specular_pixel{{
            17, 34, 51, 68,
        }};
        const std::array<std::uint16_t, 4> normal_pixel{{
            65535, 32768, 16384, 43908,
        }};
        const std::array<std::uint8_t, 4> emissive_pixel{{
            11, 22, 33, 255,
        }};
        auto upload = device->makeCommandBuffer(
            "Alchemy impostor G-buffer upload", &error);
        INFO(error);
        REQUIRE(upload);
        REQUIRE(albedo->upload(
            *upload, 0, 0, {}, albedo_pixel.data(), 4, &error));
        REQUIRE(specular->upload(
            *upload, 0, 0, {}, specular_pixel.data(), 4, &error));
        REQUIRE(normal->upload(
            *upload, 0, 0, {}, normal_pixel.data(), 8, &error));
        REQUIRE(emissive->upload(
            *upload, 0, 0, {}, emissive_pixel.data(), 4, &error));
        REQUIRE(upload->commitAndWait(&error));
        INFO(error);

        ALMetalWorldSimpleBatch batch;
        batch.impostor = true;
        batch.impostor_textures = {
            albedo.get(), specular.get(), normal.get(), emissive.get(),
        };
        batch.impostor_left[0] = 0.8f;
        batch.impostor_up[1] = 0.8f;
        for (std::size_t axis = 0; axis < 4; ++axis)
        {
            batch.modelview_projection[axis * 4 + axis] = 1.f;
            batch.modelview[axis * 4 + axis] = 1.f;
            if (axis < 3)
            {
                batch.impostor_normal_rotation[axis][axis] = 1.f;
            }
        }

        ALMetalWorldGBufferScene scene;
        scene.batches = &batch;
        scene.batch_count = 1;
        scene.width = 32;
        scene.height = 32;
        scene.normal_hdr = true;
        scene.hdr = false;
        scene.clear_color[0] = 0.25f;
        scene.clear_color[1] = 0.125f;
        scene.clear_color[2] = 0.0625f;
        scene.clear_color[3] = 0.25f;

        auto result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(result);
        REQUIRE(device->waitUntilIdle(&error));
        INFO(error);
        std::array<std::uint8_t, 32 * 32 * 4> output_albedo{};
        std::array<std::uint8_t, 32 * 32 * 4> output_specular{};
        std::array<std::uint16_t, 32 * 32 * 4> output_normal{};
        std::array<std::uint8_t, 32 * 32 * 4> output_emissive{};
        REQUIRE(result->colorTexture(0)->readback(
            *device, 0, 0, {}, output_albedo.data(), 32 * 4, &error));
        REQUIRE(result->colorTexture(1)->readback(
            *device, 0, 0, {}, output_specular.data(), 32 * 4, &error));
        REQUIRE(result->colorTexture(2)->readback(
            *device, 0, 0, {}, output_normal.data(), 32 * 8, &error));
        REQUIRE(result->colorTexture(3)->readback(
            *device, 0, 0, {}, output_emissive.data(), 32 * 4, &error));
        INFO(error);

        const auto srgb_to_linear = [](float encoded)
        {
            return encoded <= 0.04045f
                ? encoded / 12.92f
                : std::pow((encoded + 0.055f) / 1.055f, 2.4f);
        };
        const auto linear_to_srgb = [](float linear)
        {
            return linear <= 0.0031308f
                ? linear * 12.92f
                : 1.055f * std::pow(linear, 1.f / 2.4f) - 0.055f;
        };
        const std::size_t center = (16 * 32 + 16) * 4;
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            const float encoded = albedo_pixel[channel] / 255.f;
            const float recovered = srgb_to_linear(encoded) /
                                    (albedo_pixel[3] / 255.f);
            const int expected = static_cast<int>(std::lround(
                std::clamp(linear_to_srgb(recovered), 0.f, 1.f) * 255.f));
            CHECK(std::abs(static_cast<int>(
                      output_albedo[center + channel]) - expected) <= 1);
        }
        CHECK(output_albedo[center + 3] == 0);
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(output_specular[center + channel] ==
                  specular_pixel[channel]);
        }
        CHECK(std::abs(static_cast<int>(output_normal[center + 0]) -
                       65535) <= 2);
        CHECK(std::abs(static_cast<int>(output_normal[center + 1]) -
                       32768) <= 2);
        CHECK(std::abs(static_cast<int>(output_normal[center + 2]) -
                       16384) <= 2);
        CHECK(std::abs(static_cast<int>(output_normal[center + 3]) -
                       43908) <= 2);
        CHECK(output_emissive[center + 0] == emissive_pixel[0]);
        CHECK(output_emissive[center + 1] == emissive_pixel[1]);
        CHECK(output_emissive[center + 2] == emissive_pixel[2]);
        CHECK(output_emissive[center + 3] == 0);

        std::array<float, 32 * 32> output_depth{};
        REQUIRE(result->depthStencilTexture()->readback(
            *device, 0, 0, {}, output_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);

        // Develop > Impostors draws four additive white line segments before
        // the billboard. The native owner expands those segments in screen
        // space because Metal has no wide-line state. At five pixels the
        // right edge reaches x=30; at the one-pixel floor it does not.
        const std::size_t outline_pixel = (16 * 32 + 30) * 4;
        const std::size_t outline_depth = 16 * 32 + 30;
        batch.impostor_debug_outline = true;
        batch.impostor_debug_line_width = 5.f;
        auto wide_outline = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(wide_outline);
        std::array<std::uint8_t, 32 * 32 * 4> wide_albedo{};
        std::array<std::uint8_t, 32 * 32 * 4> wide_specular{};
        std::array<std::uint16_t, 32 * 32 * 4> wide_normal{};
        std::array<std::uint8_t, 32 * 32 * 4> wide_emissive{};
        std::array<float, 32 * 32> wide_depth{};
        REQUIRE(wide_outline->colorTexture(0)->readback(
            *device, 0, 0, {}, wide_albedo.data(), 32 * 4, &error));
        REQUIRE(wide_outline->colorTexture(1)->readback(
            *device, 0, 0, {}, wide_specular.data(), 32 * 4, &error));
        REQUIRE(wide_outline->colorTexture(2)->readback(
            *device, 0, 0, {}, wide_normal.data(), 32 * 8, &error));
        REQUIRE(wide_outline->colorTexture(3)->readback(
            *device, 0, 0, {}, wide_emissive.data(), 32 * 4, &error));
        REQUIRE(wide_outline->depthStencilTexture()->readback(
            *device, 0, 0, {}, wide_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK(wide_albedo[outline_pixel + 0] == 255);
        CHECK(wide_albedo[outline_pixel + 1] == 255);
        CHECK(wide_albedo[outline_pixel + 2] == 255);
        CHECK(wide_albedo[outline_pixel + 3] ==
              output_albedo[outline_pixel + 3]);
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(wide_specular[outline_pixel + channel] ==
                  output_specular[outline_pixel + channel]);
            CHECK(wide_normal[outline_pixel + channel] ==
                  output_normal[outline_pixel + channel]);
            CHECK(wide_emissive[outline_pixel + channel] ==
                  output_emissive[outline_pixel + channel]);
            CHECK(wide_albedo[center + channel] ==
                  output_albedo[center + channel]);
        }
        CHECK(std::abs(wide_depth[outline_depth] - 0.5f) < 0.0001f);
        CHECK(std::abs(wide_depth[16 * 32 + 16] -
                       output_depth[16 * 32 + 16]) < 0.0001f);

        batch.impostor_debug_line_width = 1.f;
        auto narrow_outline = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(narrow_outline);
        std::array<std::uint8_t, 32 * 32 * 4> narrow_albedo{};
        std::array<float, 32 * 32> narrow_depth{};
        REQUIRE(narrow_outline->colorTexture(0)->readback(
            *device, 0, 0, {}, narrow_albedo.data(), 32 * 4, &error));
        REQUIRE(narrow_outline->depthStencilTexture()->readback(
            *device, 0, 0, {}, narrow_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(narrow_albedo[outline_pixel + channel] ==
                  output_albedo[outline_pixel + channel]);
        }
        CHECK(std::abs(narrow_depth[outline_depth] -
                       output_depth[outline_depth]) < 0.0001f);

        // The same screen-space edge writes the reverse-Z depth convention.
        batch.impostor_debug_line_width = 5.f;
        batch.impostor_center[2] = 0.5f;
        scene.reverse_z = true;
        auto reverse_outline = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(reverse_outline);
        std::array<float, 32 * 32> reverse_outline_depth{};
        REQUIRE(reverse_outline->depthStencilTexture()->readback(
            *device, 0, 0, {}, reverse_outline_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK(std::abs(reverse_outline_depth[outline_depth] - 0.5f) <
              0.0001f);
        scene.reverse_z = false;
        batch.impostor_center[2] = 0.f;

        // Mirror clipping uses the endpoint's original eye-space position,
        // not the screen-expanded vertex. The positive-X edge remains while
        // the negative-X edge is removed.
        scene.mirror_clip = true;
        scene.mirror_clip_plane[0] = 1.f;
        scene.mirror_clip_plane[1] = 0.f;
        scene.mirror_clip_plane[2] = 0.f;
        scene.mirror_clip_plane[3] = 0.f;
        auto clipped_outline = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(clipped_outline);
        std::array<std::uint8_t, 32 * 32 * 4> clipped_outline_albedo{};
        REQUIRE(clipped_outline->colorTexture(0)->readback(
            *device, 0, 0, {}, clipped_outline_albedo.data(),
            32 * 4, &error));
        INFO(error);
        CHECK(clipped_outline_albedo[outline_pixel + 0] == 255);
        CHECK(clipped_outline_albedo[outline_pixel + 1] == 255);
        CHECK(clipped_outline_albedo[outline_pixel + 2] == 255);
        const std::size_t clipped_edge = (16 * 32 + 1) * 4;
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(clipped_outline_albedo[clipped_edge + channel] ==
                  output_albedo[clipped_edge + channel]);
        }
        scene.mirror_clip = false;

        // A closer retained impostor occludes the later debug edge; the
        // outline participates in the same read/write depth convention.
        std::array<ALMetalWorldSimpleBatch, 2> depth_batches{{batch, batch}};
        depth_batches[0].impostor_debug_outline = false;
        depth_batches[0].impostor_debug_line_width = 0.f;
        depth_batches[0].impostor_center[2] = -0.5f;
        depth_batches[0].impostor_left[0] = 0.95f;
        depth_batches[0].impostor_up[1] = 0.95f;
        scene.batches = depth_batches.data();
        scene.batch_count = depth_batches.size();
        auto occluded_outline = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(occluded_outline);
        std::array<std::uint8_t, 32 * 32 * 4> occluded_albedo{};
        std::array<float, 32 * 32> occluded_depth{};
        REQUIRE(occluded_outline->colorTexture(0)->readback(
            *device, 0, 0, {}, occluded_albedo.data(), 32 * 4, &error));
        REQUIRE(occluded_outline->depthStencilTexture()->readback(
            *device, 0, 0, {}, occluded_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK_FALSE((occluded_albedo[outline_pixel + 0] == 255 &&
                     occluded_albedo[outline_pixel + 1] == 255 &&
                     occluded_albedo[outline_pixel + 2] == 255));
        CHECK(std::abs(occluded_depth[outline_depth] - 0.25f) < 0.0001f);
        scene.batches = &batch;
        scene.batch_count = 1;

        // Reject a debug payload without its owner and every width outside
        // the exact GL-produced one-to-five-pixel interval.
        batch.impostor_debug_outline = false;
        batch.impostor_debug_line_width = 1.f;
        CHECK_FALSE(renderer->render(scene, &error));
        CHECK(error == "Metal world impostor batch is invalid");
        batch.impostor_debug_outline = true;
        batch.impostor_debug_line_width = 0.f;
        error.clear();
        CHECK_FALSE(renderer->render(scene, &error));
        CHECK(error == "Metal world impostor batch is invalid");
        batch.impostor_debug_line_width = 6.f;
        error.clear();
        CHECK_FALSE(renderer->render(scene, &error));
        CHECK(error == "Metal world impostor batch is invalid");
        batch.impostor_debug_line_width =
            std::numeric_limits<float>::quiet_NaN();
        error.clear();
        CHECK_FALSE(renderer->render(scene, &error));
        CHECK(error == "Metal world impostor batch is invalid");
        batch.impostor_debug_outline = false;
        batch.impostor_debug_line_width = 0.f;
        error.clear();
        auto no_debug_outline = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(no_debug_outline);
        std::array<std::uint8_t, 32 * 32 * 4> no_debug_albedo{};
        std::array<float, 32 * 32> no_debug_depth{};
        REQUIRE(no_debug_outline->colorTexture(0)->readback(
            *device, 0, 0, {}, no_debug_albedo.data(), 32 * 4, &error));
        REQUIRE(no_debug_outline->depthStencilTexture()->readback(
            *device, 0, 0, {}, no_debug_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK(no_debug_albedo == output_albedo);
        CHECK(no_debug_depth == output_depth);

        // The viewer publishes a completed native impostor bake by moving
        // all four resolved attachments directly into the retained per-avatar
        // mirror. Prove that this ownership handoff stays sampleable without
        // a GL/PBO round trip and can immediately feed the world replay.
        scene.stamp_opaque_coverage = true;
        auto native_bake = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(native_bake);
        std::array<std::unique_ptr<ALMetalTexture>, 4> published_textures;
        for (std::size_t attachment = 0;
             attachment < published_textures.size(); ++attachment)
        {
            published_textures[attachment] =
                native_bake->takeColorTexture(attachment);
            REQUIRE(published_textures[attachment]);
            CHECK(native_bake->colorTexture(attachment) == nullptr);
            batch.impostor_textures[attachment] =
                published_textures[attachment].get();
        }
        scene.stamp_opaque_coverage = false;
        auto direct_replay = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(direct_replay);
        REQUIRE(device->waitUntilIdle(&error));
        INFO(error);
        std::array<std::uint8_t, 32 * 32 * 4> direct_albedo{};
        REQUIRE(direct_replay->colorTexture(0)->readback(
            *device, 0, 0, {}, direct_albedo.data(), 32 * 4, &error));
        INFO(error);
        CHECK(direct_albedo[center + 0] == output_albedo[center + 0]);
        CHECK(direct_albedo[center + 1] == output_albedo[center + 1]);
        CHECK(direct_albedo[center + 2] == output_albedo[center + 2]);
        CHECK(direct_albedo[center + 3] == 0);

        // Rotate the baked +X normal to +Y. The PBR flag and the blue
        // geometric-normal payload remain byte-for-byte material data.
        std::memset(batch.impostor_normal_rotation, 0,
                    sizeof(batch.impostor_normal_rotation));
        batch.impostor_normal_rotation[0][1] = 1.f;
        batch.impostor_normal_rotation[1][0] = -1.f;
        batch.impostor_normal_rotation[2][2] = 1.f;
        auto rotated = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(rotated);
        REQUIRE(device->waitUntilIdle(&error));
        output_normal.fill(0);
        REQUIRE(rotated->colorTexture(2)->readback(
            *device, 0, 0, {}, output_normal.data(), 32 * 8, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(output_normal[center + 0]) -
                       32768) <= 2);
        CHECK(std::abs(static_cast<int>(output_normal[center + 1]) -
                       65535) <= 2);
        CHECK(std::abs(static_cast<int>(output_normal[center + 2]) -
                       16384) <= 2);
        CHECK(std::abs(static_cast<int>(output_normal[center + 3]) -
                       43908) <= 2);

        batch.impostor_textures[3] = nullptr;
        error.clear();
        CHECK_FALSE(renderer->render(scene, &error));
        CHECK(error == "Metal world impostor batch is invalid");
    }
}

TEST_CASE("almetal: native world G-buffer feeds exact deferred point lights", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        auto renderer = ALMetalWorldGBufferRenderer::create(*device, &error);
        INFO(error);
        REQUIRE(renderer);

        const auto make_texture = [&device, &error](
            ALMetalPixelFormat format, const char* label)
        {
            ALMetalTextureDescriptor descriptor;
            descriptor.format = format;
            descriptor.width = 1;
            descriptor.height = 1;
            descriptor.storage = ALMetalStorageMode::private_gpu;
            descriptor.usage = ALMetalTextureUsage::shader_read;
            descriptor.label = label;
            auto texture = ALMetalTexture::create(
                *device, descriptor, &error);
            INFO(error);
            REQUIRE(texture);
            return texture;
        };

        auto albedo = make_texture(
            ALMetalPixelFormat::rgba8_unorm_srgb,
            "Alchemy local-light G-buffer albedo");
        auto specular = make_texture(
            ALMetalPixelFormat::rgba8_unorm,
            "Alchemy local-light G-buffer specular ORM");
        auto normal = make_texture(
            ALMetalPixelFormat::rgba16_unorm,
            "Alchemy local-light G-buffer normal");
        auto emissive = make_texture(
            ALMetalPixelFormat::rgba8_unorm,
            "Alchemy local-light G-buffer emissive");

        const std::array<std::uint8_t, 4> albedo_pixel{{
            128, 96, 64, 255,
        }};
        const std::array<std::uint8_t, 4> legacy_specular{{
            0, 0, 0, 0,
        }};
        const std::array<std::uint16_t, 4> legacy_normal{{
            32768, 32768, 0, 22282,
        }};
        const std::array<std::uint8_t, 4> black{{0, 0, 0, 0}};
        auto upload = device->makeCommandBuffer(
            "Alchemy local-light G-buffer upload", &error);
        INFO(error);
        REQUIRE(upload);
        REQUIRE(albedo->upload(
            *upload, 0, 0, {}, albedo_pixel.data(), 4, &error));
        REQUIRE(specular->upload(
            *upload, 0, 0, {}, legacy_specular.data(), 4, &error));
        REQUIRE(normal->upload(
            *upload, 0, 0, {}, legacy_normal.data(), 8, &error));
        REQUIRE(emissive->upload(
            *upload, 0, 0, {}, black.data(), 4, &error));
        REQUIRE(upload->commitAndWait(&error));
        INFO(error);

        ALMetalWorldSimpleBatch batch;
        batch.impostor = true;
        batch.impostor_textures = {
            albedo.get(), specular.get(), normal.get(), emissive.get(),
        };
        batch.impostor_center[2] = -0.5f;
        batch.impostor_left[0] = 0.75f;
        batch.impostor_up[1] = 0.75f;
        for (std::size_t axis = 0; axis < 4; ++axis)
        {
            batch.modelview_projection[axis * 4 + axis] = 1.f;
            if (axis < 3)
            {
                batch.impostor_normal_rotation[axis][axis] = 1.f;
            }
        }

        ALMetalWorldGBufferScene gbuffer_scene;
        gbuffer_scene.batches = &batch;
        gbuffer_scene.batch_count = 1;
        gbuffer_scene.width = 32;
        gbuffer_scene.height = 32;
        gbuffer_scene.normal_hdr = true;
        std::fill(std::begin(gbuffer_scene.clear_color),
                  std::end(gbuffer_scene.clear_color), 0.f);
        auto gbuffer = renderer->render(gbuffer_scene, &error);
        INFO(error);
        REQUIRE(gbuffer);

        std::array<ALMetalWorldLocalLight, 2> lights{};
        lights[0].position_radius[2] = 0.5f;
        lights[0].position_radius[3] = 2.f;
        lights[0].color_falloff[0] = 0.8f;
        lights[0].color_falloff[1] = 0.4f;
        lights[0].color_falloff[2] = 0.3f;
        lights[0].color_falloff[3] = 0.5f;
        lights[1] = lights[0];

        ALMetalWorldLocalLightingScene lighting_scene;
        lighting_scene.gbuffer = gbuffer.get();
        lighting_scene.lights = lights.data();
        lighting_scene.light_count = 1;
        lighting_scene.specular_exponent = 128.f;
        for (std::size_t axis = 0; axis < 4; ++axis)
        {
            lighting_scene.inverse_projection[axis * 4 + axis] = 1.f;
        }

        auto legacy = renderer->renderLocalLights(lighting_scene, &error);
        INFO(error);
        REQUIRE(legacy);
        REQUIRE(legacy->descriptor().colors[0].format ==
                ALMetalPixelFormat::rgba8_unorm);
        std::array<std::uint8_t, 32 * 32 * 4> legacy_pixels{};
        REQUIRE(legacy->colorTexture(0)->readback(
            *device, 0, 0, {}, legacy_pixels.data(), 32 * 4, &error));
        INFO(error);
        const std::size_t center = (16 * 32 + 16) * 4;
        const std::size_t outside = (2 * 32 + 2) * 4;
        CHECK(legacy_pixels[center + 0] > legacy_pixels[center + 1]);
        CHECK(legacy_pixels[center + 1] > legacy_pixels[center + 2]);
        CHECK(legacy_pixels[center + 2] > 0);
        CHECK(legacy_pixels[center + 3] == 0);
        CHECK(legacy_pixels[outside + 0] == 0);
        CHECK(legacy_pixels[outside + 1] == 0);
        CHECK(legacy_pixels[outside + 2] == 0);

        const auto srgb_to_linear = [](float encoded)
        {
            return encoded <= 0.04045f
                ? encoded / 12.92f
                : std::pow((encoded + 0.055f) / 1.055f, 2.4f);
        };
        const float center_ndc = 2.f * (16.5f / 32.f) - 1.f;
        const float light_distance = std::sqrt(
            1.f + 2.f * center_ndc * center_ndc);
        const float normalized_distance = light_distance / 2.f;
        float attenuation = 1.f - std::clamp(
            (normalized_distance + 0.5f) / 1.5f, 0.f, 1.f);
        attenuation = attenuation * attenuation * 2.f;
        const float normal_light = 1.f / light_distance;
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            const float expected_linear = srgb_to_linear(
                albedo_pixel[channel] / 255.f) *
                lights[0].color_falloff[channel] *
                normal_light * attenuation;
            const int expected = static_cast<int>(std::lround(
                std::clamp(expected_linear, 0.f, 1.f) * 255.f));
            CHECK(std::abs(static_cast<int>(
                      legacy_pixels[center + channel]) - expected) <= 1);
        }

        lighting_scene.lights = nullptr;
        lighting_scene.light_count = 0;
        auto unlit = renderer->renderLocalLights(lighting_scene, &error);
        INFO(error);
        REQUIRE(unlit);
        std::array<std::uint8_t, 32 * 32 * 4> unlit_pixels{};
        REQUIRE(unlit->colorTexture(0)->readback(
            *device, 0, 0, {}, unlit_pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(unlit_pixels[center + 0] == 0);
        CHECK(unlit_pixels[center + 1] == 0);
        CHECK(unlit_pixels[center + 2] == 0);
        lighting_scene.lights = lights.data();
        lighting_scene.light_count = 1;

        // Reverse-Z stores zero-to-one clip depth directly. Use the matching
        // projection/inverse pair and require the same reconstructed surface
        // and local-light result as the forward-Z path.
        batch.modelview_projection[10] = -1.f;
        gbuffer_scene.reverse_z = true;
        auto reverse_gbuffer = renderer->render(gbuffer_scene, &error);
        INFO(error);
        REQUIRE(reverse_gbuffer);
        lighting_scene.gbuffer = reverse_gbuffer.get();
        lighting_scene.inverse_projection[10] = -1.f;
        lighting_scene.reverse_z = true;
        auto reverse = renderer->renderLocalLights(lighting_scene, &error);
        INFO(error);
        REQUIRE(reverse);
        std::array<std::uint8_t, 32 * 32 * 4> reverse_pixels{};
        REQUIRE(reverse->colorTexture(0)->readback(
            *device, 0, 0, {}, reverse_pixels.data(), 32 * 4, &error));
        INFO(error);
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            CHECK(std::abs(static_cast<int>(
                      reverse_pixels[center + channel]) -
                  static_cast<int>(legacy_pixels[center + channel])) <= 1);
        }
        batch.modelview_projection[10] = 1.f;
        gbuffer_scene.reverse_z = false;
        lighting_scene.gbuffer = gbuffer.get();
        lighting_scene.inverse_projection[10] = 1.f;
        lighting_scene.reverse_z = false;

        lighting_scene.classic_mode = true;
        auto classic = renderer->renderLocalLights(lighting_scene, &error);
        INFO(error);
        REQUIRE(classic);
        std::array<std::uint8_t, 32 * 32 * 4> classic_pixels{};
        REQUIRE(classic->colorTexture(0)->readback(
            *device, 0, 0, {}, classic_pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(classic_pixels[center + 0] < legacy_pixels[center + 0]);
        CHECK(classic_pixels[center + 1] < legacy_pixels[center + 1]);

        lighting_scene.classic_mode = false;
        lighting_scene.light_count = 2;
        auto doubled = renderer->renderLocalLights(lighting_scene, &error);
        INFO(error);
        REQUIRE(doubled);
        std::array<std::uint8_t, 32 * 32 * 4> doubled_pixels{};
        REQUIRE(doubled->colorTexture(0)->readback(
            *device, 0, 0, {}, doubled_pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(doubled_pixels[center + 0] > legacy_pixels[center + 0]);
        CHECK(doubled_pixels[center + 1] > legacy_pixels[center + 1]);
        CHECK(doubled_pixels[center + 2] > legacy_pixels[center + 2]);

        // The projector owner uses one draw per cookie so every light keeps
        // its own sRGB mip chain. Its transitional shadow input is the pair
        // of raw GL spot-depth maps; Metal owns the exact filter and fade.
        ALMetalTextureDescriptor cookie_descriptor;
        cookie_descriptor.format = ALMetalPixelFormat::rgba8_unorm_srgb;
        cookie_descriptor.width = 1;
        cookie_descriptor.height = 1;
        cookie_descriptor.storage = ALMetalStorageMode::private_gpu;
        cookie_descriptor.usage = ALMetalTextureUsage::shader_read;
        cookie_descriptor.label = "Alchemy projector colored sRGB cookie";
        auto cookie = ALMetalTexture::create(
            *device, cookie_descriptor, &error);
        INFO(error);
        REQUIRE(cookie);

        ALMetalTextureDescriptor shadow_descriptor;
        shadow_descriptor.type = ALMetalTextureType::texture_2d_array;
        shadow_descriptor.format = ALMetalPixelFormat::r32_float;
        shadow_descriptor.width = 32;
        shadow_descriptor.height = 32;
        shadow_descriptor.array_length = 2;
        shadow_descriptor.storage = ALMetalStorageMode::private_gpu;
        shadow_descriptor.usage = ALMetalTextureUsage::shader_read;
        shadow_descriptor.label =
            "Alchemy projector raw spot-shadow depths";
        auto projector_shadows = ALMetalTexture::create(
            *device, shadow_descriptor, &error);
        INFO(error);
        REQUIRE(projector_shadows);

        const std::array<std::uint8_t, 4> colored_cookie{{
            128, 192, 255, 255,
        }};
        const std::array<float, 32 * 32> projector_shadowed_depth = []
        {
            std::array<float, 32 * 32> value{};
            value.fill(0.f);
            return value;
        }();
        const std::array<float, 32 * 32> projector_lit_depth = []
        {
            std::array<float, 32 * 32> value{};
            value.fill(1.f);
            return value;
        }();
        auto projector_upload = device->makeCommandBuffer(
            "Alchemy projector input upload", &error);
        INFO(error);
        REQUIRE(projector_upload);
        REQUIRE(cookie->upload(
            *projector_upload, 0, 0, {}, colored_cookie.data(), 4,
            &error));
        REQUIRE(projector_shadows->upload(
            *projector_upload, 0, 0, {}, projector_shadowed_depth.data(),
            32 * sizeof(float), &error));
        REQUIRE(projector_shadows->upload(
            *projector_upload, 0, 1, {}, projector_lit_depth.data(),
            32 * sizeof(float),
            &error));
        REQUIRE(projector_upload->commitAndWait(&error));
        INFO(error);

        std::array<ALMetalWorldProjectorLight, 2> projectors{};
        ALMetalWorldProjectorLight& projector = projectors[0];
        projector.cookie_texture = cookie.get();
        std::copy(std::begin(lights[0].position_radius),
                  std::end(lights[0].position_radius),
                  projector.position_radius);
        std::copy(std::begin(lights[0].color_falloff),
                  std::end(lights[0].color_falloff),
                  projector.color_falloff);
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            projector.color_falloff[channel] *= 4.f;
        }
        projector.projector_matrix[0] = 0.5f;
        projector.projector_matrix[5] = 0.5f;
        projector.projector_matrix[12] = 0.5f;
        projector.projector_matrix[13] = 0.5f;
        projector.projector_matrix[14] = 1.f;
        projector.projector_matrix[15] = 1.f;
        projector.projector_normal[2] = -1.f;
        projector.projector_normal[3] = 2.f;
        projector.projector_origin[2] = 0.5f;
        projector.projector_origin[3] = 2.f;
        projector.sampling[0] = 1.f;
        projector.shadow_channel = 1;
        projectors[1] = projector;

        ALMetalWorldDirectionalShadows projector_shadow_input;
        projector_shadow_input.depth_texture = projector_shadows.get();
        for (std::size_t slice = 0; slice < 2; ++slice)
        {
            float* matrix = projector_shadow_input.constants
                                .shadow_matrix[slice];
            matrix[0] = 0.5f;
            matrix[5] = 0.5f;
            matrix[12] = 0.5f;
            matrix[13] = 0.5f;
            matrix[14] = 0.5f;
            matrix[15] = 1.f;
        }
        projector_shadow_input.constants.shadow_clip[2] = 1.f;
        projector_shadow_input.constants.shadow_clip[3] = 2.f;
        projector_shadow_input.constants.resolution[0] = 32.f;
        projector_shadow_input.constants.resolution[1] = 32.f;
        projector_shadow_input.constants.resolution[2] = 32.f;
        projector_shadow_input.constants.resolution[3] = 32.f;
        projector_shadow_input.constants.parameters[2] = 32.f;
        projector_shadow_input.constants.parameters[3] = 32.f;
        projector_shadow_input.constants.config[0] = 2;
        projector_shadow_input.constants.config[3] = 1;

        ALMetalWorldProjectorLightingScene projector_scene;
        projector_scene.gbuffer = gbuffer.get();
        projector_scene.lights = projectors.data();
        projector_scene.light_count = 1;
        projector_scene.projector_shadows = &projector_shadow_input;
        projector_scene.specular_exponent = 128.f;
        projector_scene.normal_hdr = true;
        for (std::size_t axis = 0; axis < 4; ++axis)
        {
            projector_scene.inverse_projection[axis * 4 + axis] = 1.f;
        }
        auto projected = renderer->renderProjectorLights(
            projector_scene, &error);
        INFO(error);
        REQUIRE(projected);
        std::array<std::uint8_t, 32 * 32 * 4> projected_pixels{};
        REQUIRE(projected->colorTexture(0)->readback(
            *device, 0, 0, {}, projected_pixels.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(projected_pixels[center + 0] > 0);
        CHECK(projected_pixels[center + 1] > 0);
        CHECK(projected_pixels[center + 2] > 0);
        CHECK(projected_pixels[center + 3] == 0);
        CHECK(projected_pixels[outside + 0] == 0);
        CHECK(projected_pixels[outside + 1] == 0);
        CHECK(projected_pixels[outside + 2] == 0);
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            const float expected_linear = srgb_to_linear(
                albedo_pixel[channel] / 255.f) *
                projector.color_falloff[channel] *
                srgb_to_linear(colored_cookie[channel] / 255.f) *
                normal_light * attenuation;
            const int expected = static_cast<int>(std::lround(
                std::clamp(expected_linear, 0.f, 1.f) * 255.f));
            CHECK(std::abs(static_cast<int>(
                      projected_pixels[center + channel]) - expected) <= 1);
        }

        // Viewer projector focus is authorable over [-20, 20]. Negative
        // focus is consumed directly by both GLSL and MSL when selecting the
        // cookie mip; it is not malformed scene data.
        projector.projector_origin[3] = -3.5f;
        auto negative_focus = renderer->renderProjectorLights(
            projector_scene, &error);
        INFO(error);
        REQUIRE(negative_focus);
        std::array<std::uint8_t, 32 * 32 * 4> negative_focus_pixels{};
        REQUIRE(negative_focus->colorTexture(0)->readback(
            *device, 0, 0, {}, negative_focus_pixels.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(negative_focus_pixels[center + 0] > 0);
        CHECK(negative_focus_pixels[center + 1] > 0);
        CHECK(negative_focus_pixels[center + 2] > 0);
        projector.projector_origin[3] = 2.f;

        projector.shadow_channel = 0;
        auto shadowed = renderer->renderProjectorLights(
            projector_scene, &error);
        INFO(error);
        REQUIRE(shadowed);
        std::array<std::uint8_t, 32 * 32 * 4> shadowed_pixels{};
        REQUIRE(shadowed->colorTexture(0)->readback(
            *device, 0, 0, {}, shadowed_pixels.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(shadowed_pixels[center + 0] == 0);
        CHECK(shadowed_pixels[center + 1] == 0);
        CHECK(shadowed_pixels[center + 2] == 0);

        ALMetalWorldProjectorLightingScene missing_projector_shadows =
            projector_scene;
        missing_projector_shadows.projector_shadows = nullptr;
        error.clear();
        CHECK_FALSE(renderer->renderProjectorLights(
            missing_projector_shadows, &error));
        CHECK(error ==
              "Metal world projector shadows are incompatible");
        error.clear();

        // The same raw map is lit when the receiver itself is outside the
        // spot frustum; normal offset does not control this early decision.
        projector_shadow_input.constants.shadow_matrix[0][12] = 2.f;
        auto outside_shadow_frustum = renderer->renderProjectorLights(
            projector_scene, &error);
        INFO(error);
        REQUIRE(outside_shadow_frustum);
        std::array<std::uint8_t, 32 * 32 * 4>
            outside_shadow_frustum_pixels{};
        REQUIRE(outside_shadow_frustum->colorTexture(0)->readback(
            *device, 0, 0, {}, outside_shadow_frustum_pixels.data(),
            32 * 4, &error));
        INFO(error);
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            CHECK(std::abs(static_cast<int>(
                      outside_shadow_frustum_pixels[center + channel]) -
                  static_cast<int>(projected_pixels[center + channel])) <= 1);
        }
        projector_shadow_input.constants.shadow_matrix[0][12] = 0.5f;

        // Probe and hero cubemaps retain the same raw spot-shadow texture
        // while generateSunShadow rebuilds the eye-to-light matrix for each
        // face. Make the texture asymmetric and render two consecutive
        // views: a cache may reuse the depth allocation, but it must never
        // reuse the first view's matrix constants.
        std::array<float, 32 * 32> split_projector_depth{};
        for (std::size_t y = 0; y < 32; ++y)
        {
            for (std::size_t x = 16; x < 32; ++x)
            {
                split_projector_depth[y * 32 + x] = 1.f;
            }
        }
        auto split_shadow_upload = device->makeCommandBuffer(
            "Alchemy split projector shadow upload", &error);
        INFO(error);
        REQUIRE(split_shadow_upload);
        REQUIRE(projector_shadows->upload(
            *split_shadow_upload, 0, 0, {},
            split_projector_depth.data(), 32 * sizeof(float), &error));
        REQUIRE(split_shadow_upload->commitAndWait(&error));
        INFO(error);

        projector_shadow_input.constants.shadow_matrix[0][12] = 0.25f;
        auto first_projector_view = renderer->renderProjectorLights(
            projector_scene, &error);
        INFO(error);
        REQUIRE(first_projector_view);
        std::array<std::uint8_t, 32 * 32 * 4>
            first_projector_view_pixels{};
        REQUIRE(first_projector_view->colorTexture(0)->readback(
            *device, 0, 0, {}, first_projector_view_pixels.data(),
            32 * 4, &error));
        INFO(error);

        projector_shadow_input.constants.shadow_matrix[0][12] = 0.75f;
        auto second_projector_view = renderer->renderProjectorLights(
            projector_scene, &error);
        INFO(error);
        REQUIRE(second_projector_view);
        std::array<std::uint8_t, 32 * 32 * 4>
            second_projector_view_pixels{};
        REQUIRE(second_projector_view->colorTexture(0)->readback(
            *device, 0, 0, {}, second_projector_view_pixels.data(),
            32 * 4, &error));
        INFO(error);
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            CHECK(first_projector_view_pixels[center + channel] == 0);
            CHECK(std::abs(static_cast<int>(
                      second_projector_view_pixels[center + channel]) -
                  static_cast<int>(projected_pixels[center + channel])) <= 1);
        }

        auto restore_shadow_upload = device->makeCommandBuffer(
            "Alchemy projector shadow restore", &error);
        INFO(error);
        REQUIRE(restore_shadow_upload);
        REQUIRE(projector_shadows->upload(
            *restore_shadow_upload, 0, 0, {},
            projector_shadowed_depth.data(), 32 * sizeof(float), &error));
        REQUIRE(restore_shadow_upload->commitAndWait(&error));
        INFO(error);
        projector_shadow_input.constants.shadow_matrix[0][12] = 0.5f;

        projector_shadow_input.constants.config[1] = 1u;
        auto unbuilt_projector_shadow = renderer->renderProjectorLights(
            projector_scene, &error);
        INFO(error);
        REQUIRE(unbuilt_projector_shadow);
        std::array<std::uint8_t, 32 * 32 * 4>
            unbuilt_projector_shadow_pixels{};
        REQUIRE(unbuilt_projector_shadow->colorTexture(0)->readback(
            *device, 0, 0, {}, unbuilt_projector_shadow_pixels.data(),
            32 * 4, &error));
        INFO(error);
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            CHECK(std::abs(static_cast<int>(
                      unbuilt_projector_shadow_pixels[center + channel]) -
                  static_cast<int>(projected_pixels[center + channel])) <= 1);
        }
        projector_shadow_input.constants.config[1] = 0u;

        projector_shadow_input.constants.config[3] = 3u;
        auto pcss_projector_shadow = renderer->renderProjectorLights(
            projector_scene, &error);
        INFO(error);
        REQUIRE(pcss_projector_shadow);
        std::array<std::uint8_t, 32 * 32 * 4>
            pcss_projector_shadow_pixels{};
        REQUIRE(pcss_projector_shadow->colorTexture(0)->readback(
            *device, 0, 0, {}, pcss_projector_shadow_pixels.data(),
            32 * 4, &error));
        INFO(error);
        CHECK(pcss_projector_shadow_pixels[center + 0] == 0);
        CHECK(pcss_projector_shadow_pixels[center + 1] == 0);
        CHECK(pcss_projector_shadow_pixels[center + 2] == 0);
        projector_shadow_input.constants.config[3] = 1u;

        projector.sampling[1] = 0.5f;
        auto fading_shadow = renderer->renderProjectorLights(
            projector_scene, &error);
        INFO(error);
        REQUIRE(fading_shadow);
        std::array<std::uint8_t, 32 * 32 * 4> fading_pixels{};
        REQUIRE(fading_shadow->colorTexture(0)->readback(
            *device, 0, 0, {}, fading_pixels.data(), 32 * 4,
            &error));
        INFO(error);
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            CHECK(std::abs(
                      static_cast<int>(fading_pixels[center + channel]) * 2 -
                      static_cast<int>(projected_pixels[center + channel]))
                  <= 2);
        }

        projector.shadow_channel = 1;
        projector.sampling[1] = 0.f;
        const std::array<std::uint16_t, 4> backface_normal{{
            65535, 65535, 0, 22282,
        }};
        auto backface_upload = device->makeCommandBuffer(
            "Alchemy projector ambiance backface upload", &error);
        INFO(error);
        REQUIRE(backface_upload);
        REQUIRE(normal->upload(
            *backface_upload, 0, 0, {}, backface_normal.data(), 8,
            &error));
        REQUIRE(backface_upload->commitAndWait(&error));
        INFO(error);
        auto backface_gbuffer = renderer->render(gbuffer_scene, &error);
        INFO(error);
        REQUIRE(backface_gbuffer);
        projector_scene.gbuffer = backface_gbuffer.get();
        auto no_ambient_projector = renderer->renderProjectorLights(
            projector_scene, &error);
        INFO(error);
        REQUIRE(no_ambient_projector);
        std::array<std::uint8_t, 32 * 32 * 4>
            no_ambient_projector_pixels{};
        REQUIRE(no_ambient_projector->colorTexture(0)->readback(
            *device, 0, 0, {}, no_ambient_projector_pixels.data(),
            32 * 4, &error));
        INFO(error);
        projector.projector_plane[3] = 1.f;
        auto ambient_projector = renderer->renderProjectorLights(
            projector_scene, &error);
        INFO(error);
        REQUIRE(ambient_projector);
        std::array<std::uint8_t, 32 * 32 * 4>
            ambient_projector_pixels{};
        REQUIRE(ambient_projector->colorTexture(0)->readback(
            *device, 0, 0, {}, ambient_projector_pixels.data(),
            32 * 4, &error));
        INFO(error);
        CHECK(ambient_projector_pixels[center + 0] >
              no_ambient_projector_pixels[center + 0]);
        CHECK(ambient_projector_pixels[center + 1] >
              no_ambient_projector_pixels[center + 1]);
        projector.projector_plane[3] = 0.f;
        projector_scene.gbuffer = gbuffer.get();

        projector.projector_matrix[12] = 2.f;
        auto outside_cookie = renderer->renderProjectorLights(
            projector_scene, &error);
        INFO(error);
        REQUIRE(outside_cookie);
        std::array<std::uint8_t, 32 * 32 * 4>
            outside_cookie_pixels{};
        REQUIRE(outside_cookie->colorTexture(0)->readback(
            *device, 0, 0, {}, outside_cookie_pixels.data(),
            32 * 4, &error));
        INFO(error);
        CHECK(outside_cookie_pixels[center + 0] == 0);
        CHECK(outside_cookie_pixels[center + 1] == 0);
        CHECK(outside_cookie_pixels[center + 2] == 0);
        projector.projector_matrix[12] = 0.5f;

        projector_scene.classic_mode = true;
        auto classic_projector = renderer->renderProjectorLights(
            projector_scene, &error);
        INFO(error);
        REQUIRE(classic_projector);
        std::array<std::uint8_t, 32 * 32 * 4> classic_projector_pixels{};
        REQUIRE(classic_projector->colorTexture(0)->readback(
            *device, 0, 0, {}, classic_projector_pixels.data(),
            32 * 4, &error));
        INFO(error);
        CHECK(classic_projector_pixels[center + 1] <
              projected_pixels[center + 1]);
        projector_scene.classic_mode = false;

        const std::array<float, 32 * 32> reverse_shadowed_depth = []
        {
            std::array<float, 32 * 32> value{};
            value.fill(1.f);
            return value;
        }();
        const std::array<float, 32 * 32> reverse_lit_depth = []
        {
            std::array<float, 32 * 32> value{};
            value.fill(0.f);
            return value;
        }();
        auto reverse_shadow_upload = device->makeCommandBuffer(
            "Alchemy reverse-Z projector shadow upload", &error);
        INFO(error);
        REQUIRE(reverse_shadow_upload);
        REQUIRE(projector_shadows->upload(
            *reverse_shadow_upload, 0, 0, {},
            reverse_shadowed_depth.data(), 32 * sizeof(float), &error));
        REQUIRE(projector_shadows->upload(
            *reverse_shadow_upload, 0, 1, {}, reverse_lit_depth.data(),
            32 * sizeof(float), &error));
        REQUIRE(reverse_shadow_upload->commitAndWait(&error));
        INFO(error);
        projector_shadow_input.constants.config[2] = 1u;
        projector_scene.gbuffer = reverse_gbuffer.get();
        projector_scene.inverse_projection[10] = -1.f;
        projector_scene.reverse_z = true;
        auto reverse_projector = renderer->renderProjectorLights(
            projector_scene, &error);
        INFO(error);
        REQUIRE(reverse_projector);
        std::array<std::uint8_t, 32 * 32 * 4>
            reverse_projector_pixels{};
        REQUIRE(reverse_projector->colorTexture(0)->readback(
            *device, 0, 0, {}, reverse_projector_pixels.data(),
            32 * 4, &error));
        INFO(error);
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            CHECK(std::abs(static_cast<int>(
                      reverse_projector_pixels[center + channel]) -
                  static_cast<int>(projected_pixels[center + channel])) <= 1);
        }
        projector_scene.gbuffer = gbuffer.get();
        projector_scene.inverse_projection[10] = 1.f;
        projector_scene.reverse_z = false;
        projector_shadow_input.constants.config[2] = 0u;
        auto forward_shadow_upload = device->makeCommandBuffer(
            "Alchemy forward-Z projector shadow restore", &error);
        INFO(error);
        REQUIRE(forward_shadow_upload);
        REQUIRE(projector_shadows->upload(
            *forward_shadow_upload, 0, 0, {},
            projector_shadowed_depth.data(),
            32 * sizeof(float), &error));
        REQUIRE(projector_shadows->upload(
            *forward_shadow_upload, 0, 1, {}, projector_lit_depth.data(),
            32 * sizeof(float), &error));
        REQUIRE(forward_shadow_upload->commitAndWait(&error));
        INFO(error);

        projector_scene.light_count = 2;
        auto doubled_projector = renderer->renderProjectorLights(
            projector_scene, &error);
        INFO(error);
        REQUIRE(doubled_projector);
        std::array<std::uint8_t, 32 * 32 * 4>
            doubled_projector_pixels{};
        REQUIRE(doubled_projector->colorTexture(0)->readback(
            *device, 0, 0, {}, doubled_projector_pixels.data(),
            32 * 4, &error));
        INFO(error);
        CHECK(doubled_projector_pixels[center + 0] >
              projected_pixels[center + 0]);
        CHECK(doubled_projector_pixels[center + 1] >
              projected_pixels[center + 1]);
        projector_scene.light_count = 1;

        // A legacy environment-intensity payload keeps the fragment alive
        // outside its direct receiver. Its reflected ray intersects the
        // emitting plane and samples the cookie's specular LOD independently.
        const std::array<std::uint8_t, 4> reflective_specular{{
            255, 255, 255, 255,
        }};
        const std::array<std::uint16_t, 4> reflective_normal{{
            32768, 32768, 32768, 22282,
        }};
        auto reflective_upload = device->makeCommandBuffer(
            "Alchemy reflective projector G-buffer upload", &error);
        INFO(error);
        REQUIRE(reflective_upload);
        REQUIRE(specular->upload(
            *reflective_upload, 0, 0, {}, reflective_specular.data(),
            4, &error));
        REQUIRE(normal->upload(
            *reflective_upload, 0, 0, {}, reflective_normal.data(),
            8, &error));
        REQUIRE(reflective_upload->commitAndWait(&error));
        INFO(error);
        auto reflective_gbuffer = renderer->render(
            gbuffer_scene, &error);
        INFO(error);
        REQUIRE(reflective_gbuffer);
        projector_scene.gbuffer = reflective_gbuffer.get();
        projector.projector_matrix[12] = -0.02f;
        projector.projector_plane[2] = 3.f;
        auto reflected_projector = renderer->renderProjectorLights(
            projector_scene, &error);
        INFO(error);
        REQUIRE(reflected_projector);
        std::array<std::uint8_t, 32 * 32 * 4>
            reflected_projector_pixels{};
        REQUIRE(reflected_projector->colorTexture(0)->readback(
            *device, 0, 0, {}, reflected_projector_pixels.data(),
            32 * 4, &error));
        INFO(error);
        CHECK(reflected_projector_pixels[center + 0] > 0);
        CHECK(reflected_projector_pixels[center + 1] > 0);
        CHECK(reflected_projector_pixels[center + 3] == 0);
        projector.projector_matrix[12] = 0.5f;
        projector.projector_plane[2] = 0.f;
        projector_scene.gbuffer = gbuffer.get();

        // Switch the same native G-buffer owner to the packed PBR material
        // flag/roughness contract. The local-light pass must use the shared
        // GGX split and generated BRDF energy-compensation table rather than
        // interpreting these bytes as legacy specular/glossiness.
        const std::array<std::uint8_t, 4> pbr_orm{{
            255, 128, 0, 0,
        }};
        const std::array<std::uint16_t, 4> pbr_normal{{
            32768, 32768, 0, 43908,
        }};
        auto pbr_upload = device->makeCommandBuffer(
            "Alchemy local-light PBR G-buffer upload", &error);
        INFO(error);
        REQUIRE(pbr_upload);
        REQUIRE(specular->upload(
            *pbr_upload, 0, 0, {}, pbr_orm.data(), 4, &error));
        REQUIRE(normal->upload(
            *pbr_upload, 0, 0, {}, pbr_normal.data(), 8, &error));
        REQUIRE(pbr_upload->commitAndWait(&error));
        INFO(error);
        auto pbr_gbuffer = renderer->render(gbuffer_scene, &error);
        INFO(error);
        REQUIRE(pbr_gbuffer);
        batch.modelview_projection[10] = -1.f;
        gbuffer_scene.reverse_z = true;
        auto pbr_reverse_gbuffer = renderer->render(
            gbuffer_scene, &error);
        INFO(error);
        REQUIRE(pbr_reverse_gbuffer);
        batch.modelview_projection[10] = 1.f;
        gbuffer_scene.reverse_z = false;
        lighting_scene.gbuffer = pbr_gbuffer.get();
        lighting_scene.light_count = 1;
        auto pbr = renderer->renderLocalLights(lighting_scene, &error);
        INFO(error);
        REQUIRE(pbr);
        std::array<std::uint8_t, 32 * 32 * 4> pbr_pixels{};
        REQUIRE(pbr->colorTexture(0)->readback(
            *device, 0, 0, {}, pbr_pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(pbr_pixels[center + 0] > 0);
        CHECK(pbr_pixels[center + 1] > 0);
        CHECK(pbr_pixels[center + 2] > 0);
        CHECK(pbr_pixels[center + 3] == 0);
        CHECK(pbr_pixels[center + 0] != legacy_pixels[center + 0]);

        projector_scene.gbuffer = pbr_gbuffer.get();
        auto pbr_projector = renderer->renderProjectorLights(
            projector_scene, &error);
        INFO(error);
        REQUIRE(pbr_projector);
        std::array<std::uint8_t, 32 * 32 * 4>
            pbr_projector_pixels{};
        REQUIRE(pbr_projector->colorTexture(0)->readback(
            *device, 0, 0, {}, pbr_projector_pixels.data(),
            32 * 4, &error));
        INFO(error);
        CHECK(pbr_projector_pixels[center + 0] > 0);
        CHECK(pbr_projector_pixels[center + 1] > 0);
        CHECK(pbr_projector_pixels[center + 2] > 0);
        CHECK(pbr_projector_pixels[center + 3] == 0);
        CHECK(pbr_projector_pixels[center + 0] !=
              projected_pixels[center + 0]);
        projector_scene.gbuffer = gbuffer.get();

        // Fill only the clear-depth pixels of both forward- and reverse-Z
        // retained G-buffers with a full HDRI dome. A one-texel panorama
        // makes the expected transfer independent of direction while the
        // indexed strip still exercises the production geometry contract.
        const std::array<std::array<float, 4>, 4> sky_vertices{{
            {{-1.f, -1.f, 0.f, 1.f}},
            {{ 1.f, -1.f, 0.f, 1.f}},
            {{-1.f,  1.f, 0.f, 1.f}},
            {{ 1.f,  1.f, 0.f, 1.f}},
        }};
        const std::array<std::uint16_t, 4> sky_indices{{0, 1, 2, 3}};
        ALMetalBufferDescriptor sky_vertex_descriptor;
        sky_vertex_descriptor.length = sizeof(sky_vertices);
        sky_vertex_descriptor.storage = ALMetalStorageMode::shared;
        sky_vertex_descriptor.label = "Alchemy HDRI sky test vertices";
        auto sky_vertex_buffer = ALMetalBuffer::create(
            *device, sky_vertex_descriptor, &error);
        INFO(error);
        REQUIRE(sky_vertex_buffer);
        REQUIRE(sky_vertex_buffer->write(
            0, sky_vertices.data(), sizeof(sky_vertices), &error));
        ALMetalBufferDescriptor sky_index_descriptor;
        sky_index_descriptor.length = sizeof(sky_indices);
        sky_index_descriptor.storage = ALMetalStorageMode::shared;
        sky_index_descriptor.label = "Alchemy HDRI sky test indices";
        auto sky_index_buffer = ALMetalBuffer::create(
            *device, sky_index_descriptor, &error);
        INFO(error);
        REQUIRE(sky_index_buffer);
        REQUIRE(sky_index_buffer->write(
            0, sky_indices.data(), sizeof(sky_indices), &error));

        ALMetalTextureDescriptor hdri_descriptor;
        hdri_descriptor.format = ALMetalPixelFormat::rgba16_float;
        hdri_descriptor.width = 1;
        hdri_descriptor.height = 1;
        hdri_descriptor.storage = ALMetalStorageMode::private_gpu;
        hdri_descriptor.usage = ALMetalTextureUsage::shader_read;
        hdri_descriptor.label = "Alchemy full HDRI sky test panorama";
        auto hdri_texture = ALMetalTexture::create(
            *device, hdri_descriptor, &error);
        INFO(error);
        REQUIRE(hdri_texture);
        const std::array<std::uint16_t, 4> hdri_pixel{{
            0x3800, 0x3400, 0x3a00, 0x3c00,
        }}; // linear (0.5, 0.25, 0.75, 1.0)
        auto hdri_upload = device->makeCommandBuffer(
            "Alchemy full HDRI sky test upload", &error);
        INFO(error);
        REQUIRE(hdri_upload);
        REQUIRE(hdri_texture->upload(
            *hdri_upload, 0, 0, {}, hdri_pixel.data(), 8, &error));
        REQUIRE(hdri_upload->commitAndWait(&error));
        INFO(error);

        ALMetalWorldHDRISkyBatch sky_batch;
        sky_batch.vertices = sky_vertex_buffer.get();
        sky_batch.vertex_count = 4;
        sky_batch.indices = sky_index_buffer.get();
        sky_batch.index_count = 4;
        for (std::size_t axis = 0; axis < 4; ++axis)
        {
            sky_batch.modelview_projection[axis * 4 + axis] = 1.f;
        }
        ALMetalWorldHDRISkyScene sky_scene;
        sky_scene.batches = &sky_batch;
        sky_scene.batch_count = 1;
        sky_scene.environment_texture = hdri_texture.get();
        sky_scene.environment_rotation[0][0] = 1.f;
        sky_scene.environment_rotation[1][1] = 1.f;
        sky_scene.environment_rotation[2][2] = 1.f;
        sky_scene.exposure_scale = 1.f;
        sky_scene.width = 32;
        sky_scene.height = 32;
        sky_scene.normal_hdr = true;

        std::array<std::uint8_t, 32 * 32 * 4> before_sky_albedo{};
        REQUIRE(pbr_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, before_sky_albedo.data(), 32 * 4,
            &error));
        INFO(error);
        REQUIRE(renderer->compositeHDRISky(
            *pbr_gbuffer, sky_scene, &error));
        INFO(error);
        std::array<std::uint8_t, 32 * 32 * 4> sky_albedo{};
        std::array<std::uint16_t, 32 * 32 * 4> sky_normal{};
        REQUIRE(pbr_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, sky_albedo.data(), 32 * 4, &error));
        REQUIRE(pbr_gbuffer->colorTexture(2)->readback(
            *device, 0, 0, {}, sky_normal.data(), 32 * 8, &error));
        INFO(error);
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(sky_albedo[center + channel] ==
                  before_sky_albedo[center + channel]);
        }
        CHECK(std::abs(static_cast<int>(sky_albedo[outside + 0]) - 188)
              <= 1);
        CHECK(std::abs(static_cast<int>(sky_albedo[outside + 1]) - 137)
              <= 1);
        CHECK(std::abs(static_cast<int>(sky_albedo[outside + 2]) - 225)
              <= 1);
        CHECK(sky_albedo[outside + 3] == 255);
        CHECK(sky_normal[outside + 0] == 0);
        CHECK(sky_normal[outside + 1] == 0);
        CHECK(sky_normal[outside + 2] == 0);
        CHECK(sky_normal[outside + 3] == 65535);

        sky_scene.reverse_z = true;
        REQUIRE(renderer->compositeHDRISky(
            *pbr_reverse_gbuffer, sky_scene, &error));
        INFO(error);
        std::array<std::uint8_t, 32 * 32 * 4> reverse_sky_albedo{};
        REQUIRE(pbr_reverse_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, reverse_sky_albedo.data(), 32 * 4,
            &error));
        INFO(error);
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(reverse_sky_albedo[outside + channel] ==
                  sky_albedo[outside + channel]);
        }
        sky_scene.reverse_z = false;

        // Sky draw pools are inside renderGeomDeferred's polygon-mode
        // scope. Prove the retained full-screen strip becomes real Metal
        // line geometry rather than filling an otherwise clear-depth pixel.
        auto wireframe_sky_gbuffer = renderer->render(
            gbuffer_scene, &error);
        INFO(error);
        REQUIRE(wireframe_sky_gbuffer);
        std::array<std::uint8_t, 32 * 32 * 4>
            before_wireframe_sky{};
        REQUIRE(wireframe_sky_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, before_wireframe_sky.data(), 32 * 4,
            &error));
        sky_scene.wireframe = true;
        REQUIRE(renderer->compositeHDRISky(
            *wireframe_sky_gbuffer, sky_scene, &error));
        INFO(error);
        std::array<std::uint8_t, 32 * 32 * 4> wireframe_sky{};
        REQUIRE(wireframe_sky_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, wireframe_sky.data(), 32 * 4, &error));
        const std::size_t clear_sky_interior = (16 * 32 + 3) * 4;
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(wireframe_sky[clear_sky_interior + channel] ==
                  before_wireframe_sky[clear_sky_interior + channel]);
        }
        CHECK(wireframe_sky != before_wireframe_sky);
        sky_scene.wireframe = false;

        ALMetalWorldHDRISkyScene invalid_sky_scene = sky_scene;
        invalid_sky_scene.environment_texture = nullptr;
        error.clear();
        CHECK_FALSE(renderer->compositeHDRISky(
            *pbr_gbuffer, invalid_sky_scene, &error));
        CHECK(error == "Metal world HDRI sky scene is incomplete");
        error.clear();

        // Replace the same clear-depth pixels with skyF.glsl's non-HDRI
        // WindLight branch. Zero optic maps isolate the atmospheric terms;
        // the family-specific all-zero normal marker distinguishes this
        // display-encoded transfer from the linear HDRI transaction.
        auto rainbow = make_texture(
            ALMetalPixelFormat::rgba8_unorm,
            "Alchemy WindLight sky rainbow optic");
        auto halo = make_texture(
            ALMetalPixelFormat::rgba8_unorm,
            "Alchemy WindLight sky halo optic");
        const std::array<std::uint8_t, 4> zero_optic{{0, 0, 0, 0}};
        auto optic_upload = device->makeCommandBuffer(
            "Alchemy WindLight sky optic upload", &error);
        INFO(error);
        REQUIRE(optic_upload);
        REQUIRE(rainbow->upload(
            *optic_upload, 0, 0, {}, zero_optic.data(), 4, &error));
        REQUIRE(halo->upload(
            *optic_upload, 0, 0, {}, zero_optic.data(), 4, &error));
        REQUIRE(optic_upload->commitAndWait(&error));
        INFO(error);

        ALMetalWorldWindLightSkyScene windlight_scene;
        windlight_scene.batches = &sky_batch;
        windlight_scene.batch_count = 1;
        windlight_scene.rainbow_texture = rainbow.get();
        windlight_scene.halo_texture = halo.get();
        windlight_scene.constants.light_density[1] = 1.f;
        windlight_scene.constants.light_density[3] = 0.001f;
        windlight_scene.constants.blue_horizon[0] = 0.4f;
        windlight_scene.constants.blue_horizon[1] = 0.3f;
        windlight_scene.constants.blue_horizon[2] = 0.2f;
        windlight_scene.constants.blue_horizon[3] = 0.1f;
        windlight_scene.constants.glow[0] = 1.f;
        windlight_scene.constants.glow[2] = -1.f;
        windlight_scene.constants.glow[3] = 1000.f;
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            windlight_scene.constants.haze_extinction[channel] = 0.5f;
            windlight_scene.constants.blue_weight[channel] = 1.f;
            windlight_scene.constants.haze_weight[channel] = 1.f;
            windlight_scene.constants.sky_light[channel] = 0.5f;
            windlight_scene.constants.sky_ambient[channel] = 0.2f;
            windlight_scene.constants.sky_light_atten[channel] = 0.1f;
            windlight_scene.constants.sky_ambient_below[channel] = 0.1f;
        }
        windlight_scene.constants.sky_ambient_below[3] = 0.2f;
        windlight_scene.constants.optics[1] = 10.f;
        windlight_scene.sky_hdr_scale = 2.f;
        windlight_scene.width = 32;
        windlight_scene.height = 32;
        windlight_scene.normal_hdr = true;

        REQUIRE(renderer->compositeWindLightSky(
            *pbr_gbuffer, windlight_scene, &error));
        INFO(error);
        std::array<std::uint8_t, 32 * 32 * 4> windlight_albedo{};
        std::array<std::uint16_t, 32 * 32 * 4> windlight_normal{};
        REQUIRE(pbr_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, windlight_albedo.data(), 32 * 4,
            &error));
        REQUIRE(pbr_gbuffer->colorTexture(2)->readback(
            *device, 0, 0, {}, windlight_normal.data(), 32 * 8,
            &error));
        INFO(error);
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(windlight_albedo[center + channel] ==
                  before_sky_albedo[center + channel]);
        }
        CHECK(windlight_albedo[outside + 0] > 0);
        CHECK(windlight_albedo[outside + 1] > 0);
        CHECK(windlight_albedo[outside + 2] > 0);
        CHECK(windlight_albedo[outside + 3] == 255);
        CHECK(windlight_normal[outside + 0] == 0);
        CHECK(windlight_normal[outside + 1] == 0);
        CHECK(windlight_normal[outside + 2] == 0);
        CHECK(windlight_normal[outside + 3] == 0);

        // Fetched viewer optics use sRGB backing even though the GL sky binds
        // them as raw data with AnisoWrap.  The same encoded rainbow/halo
        // bytes in linear and sRGB storage must therefore produce identical
        // asymmetric dome and sky-behind output.  Sampling the default sRGB
        // view would decode before rainbow's pow and visibly darken the sky.
        auto encoded_rainbow = make_texture(
            ALMetalPixelFormat::rgba8_unorm_srgb,
            "Alchemy WindLight encoded rainbow optic");
        auto encoded_halo = make_texture(
            ALMetalPixelFormat::rgba8_unorm_srgb,
            "Alchemy WindLight encoded halo optic");
        auto raw_rainbow = make_texture(
            ALMetalPixelFormat::rgba8_unorm,
            "Alchemy WindLight raw rainbow optic");
        auto raw_halo = make_texture(
            ALMetalPixelFormat::rgba8_unorm,
            "Alchemy WindLight raw halo optic");
        const std::array<std::uint8_t, 4> rainbow_optic{{
            72, 137, 211, 255,
        }};
        const std::array<std::uint8_t, 4> halo_optic{{
            193, 91, 43, 255,
        }};
        auto encoded_optic_upload = device->makeCommandBuffer(
            "Alchemy WindLight encoded optic upload", &error);
        INFO(error);
        REQUIRE(encoded_optic_upload);
        REQUIRE(encoded_rainbow->upload(
            *encoded_optic_upload, 0, 0, {}, rainbow_optic.data(), 4,
            &error));
        REQUIRE(raw_rainbow->upload(
            *encoded_optic_upload, 0, 0, {}, rainbow_optic.data(), 4,
            &error));
        REQUIRE(encoded_halo->upload(
            *encoded_optic_upload, 0, 0, {}, halo_optic.data(), 4,
            &error));
        REQUIRE(raw_halo->upload(
            *encoded_optic_upload, 0, 0, {}, halo_optic.data(), 4,
            &error));
        REQUIRE(encoded_optic_upload->commitAndWait(&error));
        INFO(error);

        ALMetalWorldWindLightSkyScene optic_scene = windlight_scene;
        std::fill(std::begin(optic_scene.constants.blue_horizon),
                  std::end(optic_scene.constants.blue_horizon), 0.f);
        optic_scene.constants.optics[0] = 0.35f;
        optic_scene.constants.optics[1] = 17.f;
        optic_scene.constants.optics[2] = 0.2f;
        optic_scene.rainbow_texture = raw_rainbow.get();
        optic_scene.halo_texture = raw_halo.get();
        auto raw_optic_gbuffer = renderer->render(gbuffer_scene, &error);
        INFO(error);
        REQUIRE(raw_optic_gbuffer);
        REQUIRE(renderer->compositeWindLightSky(
            *raw_optic_gbuffer, optic_scene, &error));
        INFO(error);
        std::array<std::uint8_t, 32 * 32 * 4> raw_optic_pixels{};
        REQUIRE(raw_optic_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, raw_optic_pixels.data(), 32 * 4,
            &error));
        INFO(error);

        optic_scene.rainbow_texture = encoded_rainbow.get();
        optic_scene.halo_texture = encoded_halo.get();
        auto encoded_optic_gbuffer = renderer->render(
            gbuffer_scene, &error);
        INFO(error);
        REQUIRE(encoded_optic_gbuffer);
        REQUIRE(renderer->compositeWindLightSky(
            *encoded_optic_gbuffer, optic_scene, &error));
        INFO(error);
        std::array<std::uint8_t, 32 * 32 * 4> encoded_optic_pixels{};
        REQUIRE(encoded_optic_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, encoded_optic_pixels.data(), 32 * 4,
            &error));
        INFO(error);
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(encoded_optic_pixels[outside + channel] ==
                  raw_optic_pixels[outside + channel]);
        }
        CHECK(raw_optic_pixels[outside + 0] > 0);
        CHECK(raw_optic_pixels[outside + 1] > 0);
        CHECK(raw_optic_pixels[outside + 2] > 0);

        optic_scene.rainbow_texture = raw_rainbow.get();
        optic_scene.halo_texture = raw_halo.get();
        auto raw_optic_sky_behind = renderer->renderWindLightSkyBehind(
            optic_scene, &error);
        INFO(error);
        REQUIRE(raw_optic_sky_behind);
        optic_scene.rainbow_texture = encoded_rainbow.get();
        optic_scene.halo_texture = encoded_halo.get();
        auto encoded_optic_sky_behind =
            renderer->renderWindLightSkyBehind(optic_scene, &error);
        INFO(error);
        REQUIRE(encoded_optic_sky_behind);
        std::array<std::uint8_t, 16 * 16 * 4>
            raw_optic_sky_behind_pixels{};
        std::array<std::uint8_t, 16 * 16 * 4>
            encoded_optic_sky_behind_pixels{};
        REQUIRE(raw_optic_sky_behind->colorTexture(0)->readback(
            *device, 0, 0, {}, raw_optic_sky_behind_pixels.data(),
            16 * 4, &error));
        REQUIRE(encoded_optic_sky_behind->colorTexture(0)->readback(
            *device, 0, 0, {}, encoded_optic_sky_behind_pixels.data(),
            16 * 4, &error));
        INFO(error);
        CHECK(raw_optic_sky_behind_pixels ==
              encoded_optic_sky_behind_pixels);

        auto windlight_sky_behind =
            renderer->renderWindLightSkyBehind(
                windlight_scene, &error);
        INFO(error);
        REQUIRE(windlight_sky_behind);
        CHECK(windlight_sky_behind->descriptor().width == 16);
        CHECK(windlight_sky_behind->descriptor().height == 16);
        CHECK(windlight_sky_behind->descriptor().colors[0].format ==
              ALMetalPixelFormat::rgba8_unorm);
        std::array<std::uint8_t, 16 * 16 * 4> sky_behind_pixels{};
        REQUIRE(windlight_sky_behind->colorTexture(0)->readback(
            *device, 0, 0, {}, sky_behind_pixels.data(), 16 * 4,
            &error));
        INFO(error);
        CHECK(std::any_of(
            sky_behind_pixels.begin(), sky_behind_pixels.end(),
            [](std::uint8_t value) { return value != 0; }));

        windlight_scene.hdr = true;
        auto hdr_windlight_sky_behind =
            renderer->renderWindLightSkyBehind(
                windlight_scene, &error);
        INFO(error);
        REQUIRE(hdr_windlight_sky_behind);
        CHECK(hdr_windlight_sky_behind->descriptor().colors[0].format ==
              ALMetalPixelFormat::rg11b10_float);
        windlight_scene.hdr = false;

        const float saved_sky_density =
            windlight_scene.constants.light_density[3];
        windlight_scene.constants.light_density[3] = -1.f;
        CHECK_FALSE(renderer->renderWindLightSkyBehind(
            windlight_scene, &error));
        CHECK(error ==
              "Metal world WindLight sky-behind scene is incomplete");
        windlight_scene.constants.light_density[3] = saved_sky_density;
        error.clear();

        // Replay one production-layout star quad over the atmospheric dome.
        // Rendering the same star over a black WindLight transaction isolates
        // its stored RGB contribution. The colored-dome result must then be
        // the raw encoded-byte sum (within one quantization step), not an sRGB
        // decode/blend/re-encode result.
        struct StarBufferData
        {
            std::array<std::array<float, 4>, 6> positions{};
            std::array<std::array<std::uint8_t, 4>, 6> colors{};
            std::array<std::array<float, 2>, 6> texcoords{};
        } star_data;
        const float star_coordinate =
            2.f * (2.5f / 32.f) - 1.f;
        const std::array<std::array<float, 2>, 6> star_corners{{
            {{-1.f, -1.f}}, {{ 1.f, -1.f}}, {{ 1.f,  1.f}},
            {{-1.f, -1.f}}, {{ 1.f,  1.f}}, {{-1.f,  1.f}},
        }};
        for (std::size_t vertex = 0; vertex < 6; ++vertex)
        {
            star_data.positions[vertex] = {
                star_coordinate, star_coordinate, 0.5f, 1.f,
            };
            star_data.colors[vertex] = {220, 180, 140, 128};
            star_data.texcoords[vertex] = star_corners[vertex];
        }
        ALMetalBufferDescriptor star_buffer_descriptor;
        star_buffer_descriptor.length = sizeof(star_data);
        star_buffer_descriptor.storage = ALMetalStorageMode::shared;
        star_buffer_descriptor.label =
            "Alchemy WindLight star production-layout vertices";
        auto star_buffer = ALMetalBuffer::create(
            *device, star_buffer_descriptor, &error);
        INFO(error);
        REQUIRE(star_buffer);
        REQUIRE(star_buffer->write(
            0, &star_data, sizeof(star_data), &error));

        ALMetalWorldStarBatch star_batch;
        star_batch.vertices = star_buffer.get();
        star_batch.position_offset = offsetof(
            StarBufferData, positions);
        star_batch.color_offset = offsetof(StarBufferData, colors);
        star_batch.texcoord_offset = offsetof(
            StarBufferData, texcoords);
        star_batch.vertex_count = 6;
        for (std::size_t axis = 0; axis < 4; ++axis)
        {
            star_batch.modelview_projection[axis * 4 + axis] = 1.f;
        }
        ALMetalWorldStarScene star_scene;
        star_scene.batches = &star_batch;
        star_scene.batch_count = 1;
        star_scene.star_alpha = 1.f;
        star_scene.time = 0.f;
        star_scene.width = 32;
        star_scene.height = 32;
        star_scene.normal_hdr = true;
        REQUIRE(renderer->compositeWindLightStars(
            *pbr_gbuffer, star_scene, &error));
        INFO(error);
        std::array<std::uint8_t, 32 * 32 * 4> star_albedo{};
        std::array<std::uint16_t, 32 * 32 * 4> star_normal{};
        REQUIRE(pbr_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, star_albedo.data(), 32 * 4, &error));
        REQUIRE(pbr_gbuffer->colorTexture(2)->readback(
            *device, 0, 0, {}, star_normal.data(), 32 * 8, &error));
        INFO(error);
        CHECK(star_albedo[outside + 0] >
              windlight_albedo[outside + 0]);
        CHECK(star_albedo[outside + 1] >
              windlight_albedo[outside + 1]);
        CHECK(star_normal[outside + 0] == 0);
        CHECK(star_normal[outside + 1] == 65535);
        CHECK(star_normal[outside + 2] == 0);
        CHECK(star_normal[outside + 3] == 0);
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(star_albedo[center + channel] ==
                  windlight_albedo[center + channel]);
        }

        auto star_source_gbuffer = renderer->render(
            gbuffer_scene, &error);
        INFO(error);
        REQUIRE(star_source_gbuffer);
        ALMetalWorldWindLightSkyScene black_windlight_scene =
            windlight_scene;
        std::fill(std::begin(
                      black_windlight_scene.constants.blue_horizon),
                  std::end(
                      black_windlight_scene.constants.blue_horizon),
                  0.f);
        REQUIRE(renderer->compositeWindLightSky(
            *star_source_gbuffer, black_windlight_scene, &error));
        REQUIRE(renderer->compositeWindLightStars(
            *star_source_gbuffer, star_scene, &error));
        INFO(error);
        std::array<std::uint8_t, 32 * 32 * 4> star_source_albedo{};
        REQUIRE(star_source_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, star_source_albedo.data(),
            32 * 4, &error));
        INFO(error);
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            const int raw_sum = std::min(
                255, static_cast<int>(
                         windlight_albedo[outside + channel]) +
                     static_cast<int>(
                         star_source_albedo[outside + channel]));
            CHECK(std::abs(static_cast<int>(
                      star_albedo[outside + channel]) - raw_sum) <= 1);
        }

        // The live moon texture alpha suppresses the whole star quad when its
        // direction intersects the moon quad. Missing mask storage fails
        // before encoding rather than drawing through the moon.
        auto opaque_moon = make_texture(
            ALMetalPixelFormat::rgba8_unorm,
            "Alchemy WindLight star opaque moon mask");
        const std::array<std::uint8_t, 4> opaque_moon_pixel{{
            255, 255, 255, 255,
        }};
        auto moon_upload = device->makeCommandBuffer(
            "Alchemy WindLight star moon-mask upload", &error);
        INFO(error);
        REQUIRE(moon_upload);
        REQUIRE(opaque_moon->upload(
            *moon_upload, 0, 0, {}, opaque_moon_pixel.data(), 4,
            &error));
        REQUIRE(moon_upload->commitAndWait(&error));
        INFO(error);
        auto masked_star_gbuffer = renderer->render(
            gbuffer_scene, &error);
        INFO(error);
        REQUIRE(masked_star_gbuffer);
        REQUIRE(renderer->compositeWindLightSky(
            *masked_star_gbuffer, windlight_scene, &error));
        star_scene.moon_mask = true;
        star_scene.moon_texture = opaque_moon.get();
        const float star_length = std::sqrt(
            2.f * star_coordinate * star_coordinate + 0.25f);
        star_scene.moon_quad_center[0] =
            star_coordinate / star_length;
        star_scene.moon_quad_center[1] =
            star_coordinate / star_length;
        star_scene.moon_quad_center[2] = 0.5f / star_length;
        star_scene.moon_quad_u[0] = 1.f;
        star_scene.moon_quad_v[1] = 1.f;
        REQUIRE(renderer->compositeWindLightStars(
            *masked_star_gbuffer, star_scene, &error));
        INFO(error);
        std::array<std::uint8_t, 32 * 32 * 4> masked_star_albedo{};
        REQUIRE(masked_star_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, masked_star_albedo.data(),
            32 * 4, &error));
        INFO(error);
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(masked_star_albedo[outside + channel] ==
                  windlight_albedo[outside + channel]);
        }
        star_scene.moon_texture = nullptr;
        error.clear();
        CHECK_FALSE(renderer->compositeWindLightStars(
            *masked_star_gbuffer, star_scene, &error));
        CHECK(error ==
              "Metal world WindLight star scene is incomplete");
        error.clear();
        star_scene.moon_mask = false;
        std::fill(std::begin(star_scene.moon_quad_center),
                  std::end(star_scene.moon_quad_center), 0.f);
        std::fill(std::begin(star_scene.moon_quad_u),
                  std::end(star_scene.moon_quad_u), 0.f);
        std::fill(std::begin(star_scene.moon_quad_v),
                  std::end(star_scene.moon_quad_v), 0.f);

        windlight_scene.reverse_z = true;
        REQUIRE(renderer->compositeWindLightSky(
            *pbr_reverse_gbuffer, windlight_scene, &error));
        INFO(error);
        std::array<std::uint8_t, 32 * 32 * 4>
            reverse_windlight_albedo{};
        REQUIRE(pbr_reverse_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, reverse_windlight_albedo.data(),
            32 * 4, &error));
        INFO(error);
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(reverse_windlight_albedo[outside + channel] ==
                  windlight_albedo[outside + channel]);
        }
        star_scene.reverse_z = true;
        REQUIRE(renderer->compositeWindLightStars(
            *pbr_reverse_gbuffer, star_scene, &error));
        INFO(error);
        std::array<std::uint8_t, 32 * 32 * 4>
            reverse_star_albedo{};
        REQUIRE(pbr_reverse_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, reverse_star_albedo.data(),
            32 * 4, &error));
        INFO(error);
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(reverse_star_albedo[outside + channel] ==
                  star_albedo[outside + channel]);
        }
        star_scene.reverse_z = false;
        windlight_scene.reverse_z = false;

        // Source-over the indexed sun/moon quads after the stars. The sun's
        // two live environment textures blend before its alpha blends into
        // the raw display-encoded vintage storage, exactly as the GL sky pool
        // does with framebuffer sRGB disabled.
        struct HeavenlyBodyBufferData
        {
            std::array<std::array<float, 4>, 4> positions{};
            std::array<std::array<float, 2>, 4> texcoords{};
        } body_data;
        const float body_extent = 4.f / 32.f;
        body_data.positions = {{
            {{star_coordinate - body_extent,
              star_coordinate + body_extent, 0.5f, 1.f}},
            {{star_coordinate - body_extent,
              star_coordinate - body_extent, 0.5f, 1.f}},
            {{star_coordinate + body_extent,
              star_coordinate + body_extent, 0.5f, 1.f}},
            {{star_coordinate + body_extent,
              star_coordinate - body_extent, 0.5f, 1.f}},
        }};
        body_data.texcoords = {{
            {{0.f, 1.f}}, {{0.f, 0.f}},
            {{1.f, 1.f}}, {{1.f, 0.f}},
        }};
        const std::array<std::uint16_t, 6> body_indices{{
            0, 2, 1, 1, 2, 3,
        }};
        ALMetalBufferDescriptor body_vertex_descriptor;
        body_vertex_descriptor.length = sizeof(body_data);
        body_vertex_descriptor.storage = ALMetalStorageMode::shared;
        body_vertex_descriptor.label =
            "Alchemy WindLight heavenly-body production-layout vertices";
        auto body_vertex_buffer = ALMetalBuffer::create(
            *device, body_vertex_descriptor, &error);
        INFO(error);
        REQUIRE(body_vertex_buffer);
        REQUIRE(body_vertex_buffer->write(
            0, &body_data, sizeof(body_data), &error));
        ALMetalBufferDescriptor body_index_descriptor;
        body_index_descriptor.length = sizeof(body_indices);
        body_index_descriptor.storage = ALMetalStorageMode::shared;
        body_index_descriptor.label =
            "Alchemy WindLight heavenly-body production-layout indices";
        auto body_index_buffer = ALMetalBuffer::create(
            *device, body_index_descriptor, &error);
        INFO(error);
        REQUIRE(body_index_buffer);
        REQUIRE(body_index_buffer->write(
            0, body_indices.data(), sizeof(body_indices), &error));

        auto sun_a = make_texture(
            ALMetalPixelFormat::rgba8_unorm,
            "Alchemy WindLight sun texture A");
        auto sun_b = make_texture(
            ALMetalPixelFormat::rgba8_unorm,
            "Alchemy WindLight sun texture B");
        const std::array<std::uint8_t, 4> sun_a_pixel{{
            200, 40, 20, 128,
        }};
        const std::array<std::uint8_t, 4> sun_b_pixel{{
            40, 200, 100, 128,
        }};
        auto sun_upload = device->makeCommandBuffer(
            "Alchemy WindLight sun texture upload", &error);
        INFO(error);
        REQUIRE(sun_upload);
        REQUIRE(sun_a->upload(
            *sun_upload, 0, 0, {}, sun_a_pixel.data(), 4, &error));
        REQUIRE(sun_b->upload(
            *sun_upload, 0, 0, {}, sun_b_pixel.data(), 4, &error));
        REQUIRE(sun_upload->commitAndWait(&error));
        INFO(error);

        ALMetalWorldHeavenlyBodyBatch body_batch;
        body_batch.vertices = body_vertex_buffer.get();
        body_batch.position_offset = offsetof(
            HeavenlyBodyBufferData, positions);
        body_batch.texcoord_offset = offsetof(
            HeavenlyBodyBufferData, texcoords);
        body_batch.indices = body_index_buffer.get();
        body_batch.index_type = ALMetalIndexType::uint16;
        body_batch.vertex_count = 4;
        body_batch.index_count = 6;
        body_batch.texture_a = sun_a.get();
        body_batch.texture_b = sun_b.get();
        body_batch.parameters[0] = 0.25f;
        for (std::size_t axis = 0; axis < 4; ++axis)
        {
            body_batch.modelview_projection[axis * 4 + axis] = 1.f;
        }
        ALMetalWorldHeavenlyBodyScene body_scene;
        body_scene.batches = &body_batch;
        body_scene.batch_count = 1;
        body_scene.width = 32;
        body_scene.height = 32;
        body_scene.normal_hdr = true;

        REQUIRE(renderer->compositeWindLightHeavenlyBodies(
            *pbr_gbuffer, body_scene, &error));
        INFO(error);
        body_scene.reverse_z = true;
        REQUIRE(renderer->compositeWindLightHeavenlyBodies(
            *pbr_reverse_gbuffer, body_scene, &error));
        INFO(error);
        body_scene.reverse_z = false;
        std::array<std::uint8_t, 32 * 32 * 4> sun_albedo{};
        std::array<std::uint8_t, 32 * 32 * 4> reverse_sun_albedo{};
        std::array<std::uint16_t, 32 * 32 * 4> sun_normal{};
        REQUIRE(pbr_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, sun_albedo.data(), 32 * 4, &error));
        REQUIRE(pbr_reverse_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, reverse_sun_albedo.data(),
            32 * 4, &error));
        REQUIRE(pbr_gbuffer->colorTexture(2)->readback(
            *device, 0, 0, {}, sun_normal.data(), 32 * 8, &error));
        INFO(error);
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(reverse_sun_albedo[outside + channel] ==
                  sun_albedo[outside + channel]);
            CHECK(sun_albedo[center + channel] ==
                  star_albedo[center + channel]);
        }
        CHECK(sun_normal[outside + 0] == star_normal[outside + 0]);
        CHECK(sun_normal[outside + 1] == star_normal[outside + 1]);
        CHECK(sun_normal[outside + 2] == star_normal[outside + 2]);
        CHECK(sun_normal[outside + 3] == star_normal[outside + 3]);

        auto sun_source_gbuffer = renderer->render(
            gbuffer_scene, &error);
        INFO(error);
        REQUIRE(sun_source_gbuffer);
        REQUIRE(renderer->compositeWindLightSky(
            *sun_source_gbuffer, black_windlight_scene, &error));
        REQUIRE(renderer->compositeWindLightHeavenlyBodies(
            *sun_source_gbuffer, body_scene, &error));
        INFO(error);
        std::array<std::uint8_t, 32 * 32 * 4> sun_source_albedo{};
        REQUIRE(sun_source_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, sun_source_albedo.data(),
            32 * 4, &error));
        INFO(error);
        const float sun_alpha = 128.f / 255.f;
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            const int raw_source_over = std::min(
                255, static_cast<int>(std::lround(
                    static_cast<float>(
                        star_albedo[outside + channel]) *
                    (1.f - sun_alpha))) +
                    static_cast<int>(
                        sun_source_albedo[outside + channel]));
            CHECK(std::abs(static_cast<int>(
                      sun_albedo[outside + channel]) -
                  raw_source_over) <= 2);
        }

        // The moon uses only texture A, discards the transparent surround,
        // scales RGB by moon brightness and applies the legacy z-direction
        // horizon fade to alpha before source-over blending.
        auto moon_texture = make_texture(
            ALMetalPixelFormat::rgba8_unorm,
            "Alchemy WindLight moon texture");
        auto transparent_moon = make_texture(
            ALMetalPixelFormat::rgba8_unorm,
            "Alchemy WindLight transparent moon surround");
        const std::array<std::uint8_t, 4> moon_pixel{{
            160, 80, 40, 128,
        }};
        const std::array<std::uint8_t, 4> transparent_moon_pixel{{
            255, 255, 255, 2,
        }};
        auto body_upload = device->makeCommandBuffer(
            "Alchemy WindLight moon texture upload", &error);
        INFO(error);
        REQUIRE(body_upload);
        REQUIRE(moon_texture->upload(
            *body_upload, 0, 0, {}, moon_pixel.data(), 4, &error));
        REQUIRE(transparent_moon->upload(
            *body_upload, 0, 0, {}, transparent_moon_pixel.data(),
            4, &error));
        REQUIRE(body_upload->commitAndWait(&error));
        INFO(error);

        auto moon_gbuffer = renderer->render(gbuffer_scene, &error);
        INFO(error);
        REQUIRE(moon_gbuffer);
        REQUIRE(renderer->compositeWindLightSky(
            *moon_gbuffer, black_windlight_scene, &error));
        std::array<std::uint8_t, 32 * 32 * 4> moon_before{};
        REQUIRE(moon_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, moon_before.data(), 32 * 4, &error));
        body_batch.moon = true;
        body_batch.texture_a = transparent_moon.get();
        body_batch.texture_b = transparent_moon.get();
        body_batch.parameters[0] = 0.5f;
        body_batch.parameters[1] = 0.25f;
        REQUIRE(renderer->compositeWindLightHeavenlyBodies(
            *moon_gbuffer, body_scene, &error));
        INFO(error);
        std::array<std::uint8_t, 32 * 32 * 4> transparent_moon_albedo{};
        REQUIRE(moon_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, transparent_moon_albedo.data(),
            32 * 4, &error));
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(transparent_moon_albedo[outside + channel] ==
                  moon_before[outside + channel]);
        }

        body_batch.texture_a = moon_texture.get();
        body_batch.texture_b = moon_texture.get();
        REQUIRE(renderer->compositeWindLightHeavenlyBodies(
            *moon_gbuffer, body_scene, &error));
        INFO(error);
        std::array<std::uint8_t, 32 * 32 * 4> moon_albedo{};
        REQUIRE(moon_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, moon_albedo.data(), 32 * 4, &error));
        INFO(error);
        const float moon_fade = 0.25f * 0.25f * 4.f;
        const float moon_alpha = 128.f / 255.f * moon_fade;
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            const int expected = static_cast<int>(std::lround(
                static_cast<float>(moon_pixel[channel]) * 0.5f *
                moon_alpha));
            CHECK(std::abs(static_cast<int>(
                      moon_albedo[outside + channel]) - expected) <= 1);
            CHECK(moon_albedo[center + channel] ==
                  moon_before[center + channel]);
        }

        body_batch.texture_a = nullptr;
        error.clear();
        CHECK_FALSE(renderer->compositeWindLightHeavenlyBodies(
            *moon_gbuffer, body_scene, &error));
        CHECK(error ==
              "Metal world WindLight heavenly-body batch is invalid");
        error.clear();
        body_batch.moon = false;
        body_batch.texture_a = sun_a.get();
        body_batch.texture_b = sun_b.get();
        body_batch.parameters[0] = 0.25f;
        body_batch.parameters[1] = 0.f;

        // Replay one production-layout meteor streak after the bodies. Its
        // CPU-premultiplied packed color is linearized in the vertex stage,
        // shaped along/across the streak and additively accumulated in the
        // same raw encoded storage convention as stars.
        struct MeteorBufferData
        {
            std::array<std::array<float, 4>, 6> positions{};
            std::array<std::array<float, 4>, 6> normals{};
            std::array<std::array<std::uint8_t, 4>, 6> colors{};
            std::array<std::array<float, 2>, 6> texcoords{};
        } meteor_data;
        const std::array<std::array<float, 2>, 6> meteor_coordinates{{
            {{-1.f, -1.f}}, {{ 1.f, -1.f}}, {{ 1.f,  1.f}},
            {{-1.f, -1.f}}, {{ 1.f,  1.f}}, {{-1.f,  1.f}},
        }};
        for (std::size_t vertex = 0; vertex < 6; ++vertex)
        {
            meteor_data.positions[vertex] = {
                star_coordinate, star_coordinate, 0.5f, 1.f,
            };
            meteor_data.normals[vertex] = {
                body_extent, 0.f, 0.f, 0.f,
            };
            meteor_data.colors[vertex] = {180, 120, 60, 64};
            meteor_data.texcoords[vertex] = meteor_coordinates[vertex];
        }
        ALMetalBufferDescriptor meteor_buffer_descriptor;
        meteor_buffer_descriptor.length = sizeof(meteor_data);
        meteor_buffer_descriptor.storage = ALMetalStorageMode::shared;
        meteor_buffer_descriptor.label =
            "Alchemy WindLight meteor production-layout vertices";
        auto meteor_buffer = ALMetalBuffer::create(
            *device, meteor_buffer_descriptor, &error);
        INFO(error);
        REQUIRE(meteor_buffer);
        REQUIRE(meteor_buffer->write(
            0, &meteor_data, sizeof(meteor_data), &error));
        ALMetalWorldMeteorBatch meteor_batch;
        meteor_batch.vertices = meteor_buffer.get();
        meteor_batch.position_offset = offsetof(
            MeteorBufferData, positions);
        meteor_batch.normal_offset = offsetof(
            MeteorBufferData, normals);
        meteor_batch.color_offset = offsetof(
            MeteorBufferData, colors);
        meteor_batch.texcoord_offset = offsetof(
            MeteorBufferData, texcoords);
        meteor_batch.vertex_count = 6;
        for (std::size_t axis = 0; axis < 4; ++axis)
        {
            meteor_batch.modelview_projection[axis * 4 + axis] = 1.f;
        }
        ALMetalWorldMeteorScene meteor_scene;
        meteor_scene.batches = &meteor_batch;
        meteor_scene.batch_count = 1;
        meteor_scene.width_pixels = 1.5f;
        meteor_scene.width = 32;
        meteor_scene.height = 32;
        meteor_scene.normal_hdr = true;

        REQUIRE(renderer->compositeWindLightMeteors(
            *pbr_gbuffer, meteor_scene, &error));
        INFO(error);
        meteor_scene.reverse_z = true;
        REQUIRE(renderer->compositeWindLightMeteors(
            *pbr_reverse_gbuffer, meteor_scene, &error));
        INFO(error);
        meteor_scene.reverse_z = false;
        std::array<std::uint8_t, 32 * 32 * 4> meteor_albedo{};
        std::array<std::uint8_t, 32 * 32 * 4> reverse_meteor_albedo{};
        REQUIRE(pbr_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, meteor_albedo.data(), 32 * 4,
            &error));
        REQUIRE(pbr_reverse_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, reverse_meteor_albedo.data(),
            32 * 4, &error));
        INFO(error);
        CHECK(meteor_albedo[outside + 0] > sun_albedo[outside + 0]);
        CHECK(meteor_albedo[outside + 1] > sun_albedo[outside + 1]);
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(reverse_meteor_albedo[outside + channel] ==
                  meteor_albedo[outside + channel]);
            CHECK(meteor_albedo[center + channel] ==
                  sun_albedo[center + channel]);
        }

        auto meteor_source_gbuffer = renderer->render(
            gbuffer_scene, &error);
        INFO(error);
        REQUIRE(meteor_source_gbuffer);
        REQUIRE(renderer->compositeWindLightSky(
            *meteor_source_gbuffer, black_windlight_scene, &error));
        REQUIRE(renderer->compositeWindLightMeteors(
            *meteor_source_gbuffer, meteor_scene, &error));
        INFO(error);
        std::array<std::uint8_t, 32 * 32 * 4>
            meteor_source_albedo{};
        REQUIRE(meteor_source_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, meteor_source_albedo.data(),
            32 * 4, &error));
        INFO(error);
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            const int raw_sum = std::min(
                255, static_cast<int>(sun_albedo[outside + channel]) +
                     static_cast<int>(
                         meteor_source_albedo[outside + channel]));
            CHECK(std::abs(static_cast<int>(
                      meteor_albedo[outside + channel]) - raw_sum) <= 1);
        }
        meteor_scene.width_pixels = 0.f;
        error.clear();
        CHECK_FALSE(renderer->compositeWindLightMeteors(
            *meteor_source_gbuffer, meteor_scene, &error));
        CHECK(error == "Metal world WindLight meteor scene is incomplete");
        error.clear();
        meteor_scene.width_pixels = 1.5f;

        // The procedural aurora reuses the indexed dome. Give its physical
        // fixture a positive local Z so screen pixels span elevation and
        // azimuth while the identity MVP still covers the full target.
        const std::array<std::array<float, 4>, 4> aurora_vertices{{
            {{-1.f, -1.f, 1.f, 1.f}},
            {{ 1.f, -1.f, 1.f, 1.f}},
            {{-1.f,  1.f, 1.f, 1.f}},
            {{ 1.f,  1.f, 1.f, 1.f}},
        }};
        ALMetalBufferDescriptor aurora_vertex_descriptor;
        aurora_vertex_descriptor.length = sizeof(aurora_vertices);
        aurora_vertex_descriptor.storage = ALMetalStorageMode::shared;
        aurora_vertex_descriptor.label =
            "Alchemy WindLight aurora dome vertices";
        auto aurora_vertex_buffer = ALMetalBuffer::create(
            *device, aurora_vertex_descriptor, &error);
        INFO(error);
        REQUIRE(aurora_vertex_buffer);
        REQUIRE(aurora_vertex_buffer->write(
            0, aurora_vertices.data(), sizeof(aurora_vertices), &error));
        ALMetalWorldHDRISkyBatch aurora_batch = sky_batch;
        aurora_batch.vertices = aurora_vertex_buffer.get();
        ALMetalWorldAuroraScene aurora_scene;
        aurora_scene.batches = &aurora_batch;
        aurora_scene.batch_count = 1;
        aurora_scene.intensity = 1.f;
        aurora_scene.time = 123.f;
        aurora_scene.width = 32;
        aurora_scene.height = 32;
        aurora_scene.normal_hdr = true;

        REQUIRE(renderer->compositeWindLightAurora(
            *pbr_gbuffer, aurora_scene, &error));
        INFO(error);
        aurora_scene.reverse_z = true;
        REQUIRE(renderer->compositeWindLightAurora(
            *pbr_reverse_gbuffer, aurora_scene, &error));
        INFO(error);
        aurora_scene.reverse_z = false;
        std::array<std::uint8_t, 32 * 32 * 4> aurora_albedo{};
        std::array<std::uint8_t, 32 * 32 * 4>
            reverse_aurora_albedo{};
        REQUIRE(pbr_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, aurora_albedo.data(), 32 * 4,
            &error));
        REQUIRE(pbr_reverse_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, reverse_aurora_albedo.data(),
            32 * 4, &error));
        INFO(error);
        CHECK(reverse_aurora_albedo == aurora_albedo);
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(aurora_albedo[center + channel] ==
                  meteor_albedo[center + channel]);
        }

        auto aurora_source_gbuffer = renderer->render(
            gbuffer_scene, &error);
        INFO(error);
        REQUIRE(aurora_source_gbuffer);
        REQUIRE(renderer->compositeWindLightSky(
            *aurora_source_gbuffer, black_windlight_scene, &error));
        std::array<std::uint8_t, 32 * 32 * 4>
            aurora_source_before{};
        REQUIRE(aurora_source_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, aurora_source_before.data(),
            32 * 4, &error));
        REQUIRE(renderer->compositeWindLightAurora(
            *aurora_source_gbuffer, aurora_scene, &error));
        INFO(error);
        std::array<std::uint8_t, 32 * 32 * 4>
            aurora_source_albedo{};
        REQUIRE(aurora_source_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, aurora_source_albedo.data(),
            32 * 4, &error));
        INFO(error);
        bool found_aurora = false;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            const std::size_t byte = pixel * 4;
            if (aurora_source_albedo[byte + 0] ==
                    aurora_source_before[byte + 0] &&
                aurora_source_albedo[byte + 1] ==
                    aurora_source_before[byte + 1] &&
                aurora_source_albedo[byte + 2] ==
                    aurora_source_before[byte + 2])
            {
                continue;
            }
            found_aurora = true;
            for (std::size_t channel = 0; channel < 3; ++channel)
            {
                const int raw_sum = std::min(
                    255, static_cast<int>(meteor_albedo[byte + channel]) +
                         static_cast<int>(
                             aurora_source_albedo[byte + channel]) -
                         static_cast<int>(
                             aurora_source_before[byte + channel]));
                CHECK(std::abs(static_cast<int>(
                          aurora_albedo[byte + channel]) - raw_sum) <= 1);
            }
            break;
        }
        CHECK(found_aurora);
        aurora_scene.intensity = 0.f;
        error.clear();
        CHECK_FALSE(renderer->compositeWindLightAurora(
            *aurora_source_gbuffer, aurora_scene, &error));
        CHECK(error == "Metal world WindLight aurora scene is incomplete");
        error.clear();
        aurora_scene.intensity = 1.f;

        // Clouds are the final non-HDRI WindLight layer. Their retained dome
        // adds the production float2 UV plane and interpolates the two live
        // wrap-filtered noise textures before source-over composition.
        struct CloudBufferData
        {
            std::array<std::array<float, 4>, 4> positions{};
            std::array<std::array<float, 2>, 4> texcoords{};
        } cloud_data;
        cloud_data.positions = aurora_vertices;
        cloud_data.texcoords = {{
            {{0.f, 0.f}}, {{1.f, 0.f}},
            {{0.f, 1.f}}, {{1.f, 1.f}},
        }};
        ALMetalBufferDescriptor cloud_vertex_descriptor;
        cloud_vertex_descriptor.length = sizeof(cloud_data);
        cloud_vertex_descriptor.storage = ALMetalStorageMode::shared;
        cloud_vertex_descriptor.label =
            "Alchemy WindLight cloud production-layout vertices";
        auto cloud_vertex_buffer = ALMetalBuffer::create(
            *device, cloud_vertex_descriptor, &error);
        INFO(error);
        REQUIRE(cloud_vertex_buffer);
        REQUIRE(cloud_vertex_buffer->write(
            0, &cloud_data, sizeof(cloud_data), &error));

        auto cloud_noise_a = make_texture(
            ALMetalPixelFormat::rgba8_unorm,
            "Alchemy WindLight cloud noise A");
        auto cloud_noise_b = make_texture(
            ALMetalPixelFormat::rgba8_unorm,
            "Alchemy WindLight cloud noise B");
        auto encoded_cloud_noise_a = make_texture(
            ALMetalPixelFormat::rgba8_unorm_srgb,
            "Alchemy WindLight encoded cloud noise A");
        auto encoded_cloud_noise_b = make_texture(
            ALMetalPixelFormat::rgba8_unorm_srgb,
            "Alchemy WindLight encoded cloud noise B");
        const std::array<std::uint8_t, 4> cloud_noise_a_pixel{{
            204, 0, 0, 255,
        }};
        const std::array<std::uint8_t, 4> cloud_noise_b_pixel{{
            51, 0, 0, 255,
        }};
        auto cloud_upload = device->makeCommandBuffer(
            "Alchemy WindLight cloud noise upload", &error);
        INFO(error);
        REQUIRE(cloud_upload);
        REQUIRE(cloud_noise_a->upload(
            *cloud_upload, 0, 0, {}, cloud_noise_a_pixel.data(),
            4, &error));
        REQUIRE(cloud_noise_b->upload(
            *cloud_upload, 0, 0, {}, cloud_noise_b_pixel.data(),
            4, &error));
        REQUIRE(encoded_cloud_noise_a->upload(
            *cloud_upload, 0, 0, {}, cloud_noise_a_pixel.data(),
            4, &error));
        REQUIRE(encoded_cloud_noise_b->upload(
            *cloud_upload, 0, 0, {}, cloud_noise_b_pixel.data(),
            4, &error));
        REQUIRE(cloud_upload->commitAndWait(&error));
        INFO(error);

        ALMetalWorldCloudBatch cloud_batch;
        cloud_batch.vertices = cloud_vertex_buffer.get();
        cloud_batch.position_offset = offsetof(CloudBufferData, positions);
        cloud_batch.texcoord_offset = offsetof(CloudBufferData, texcoords);
        cloud_batch.indices = sky_index_buffer.get();
        cloud_batch.index_count = 4;
        cloud_batch.vertex_count = 4;
        for (std::size_t axis = 0; axis < 4; ++axis)
        {
            cloud_batch.modelview_projection[axis * 4 + axis] = 1.f;
        }
        ALMetalWorldCloudScene cloud_scene;
        cloud_scene.batches = &cloud_batch;
        cloud_scene.batch_count = 1;
        cloud_scene.noise_texture = cloud_noise_a.get();
        cloud_scene.next_noise_texture = cloud_noise_b.get();
        cloud_scene.constants.light_density[1] = 1.f;
        cloud_scene.constants.light_density[3] = 0.001f;
        cloud_scene.constants.blue_horizon[0] = 0.4f;
        cloud_scene.constants.blue_horizon[1] = 0.3f;
        cloud_scene.constants.blue_horizon[2] = 0.2f;
        cloud_scene.constants.blue_horizon[3] = 0.1f;
        cloud_scene.constants.glow[0] = 1.f;
        cloud_scene.constants.glow[2] = -1.f;
        cloud_scene.constants.glow[3] = 1000.f;
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            cloud_scene.constants.haze_extinction[channel] = 0.5f;
            cloud_scene.constants.blue_weight[channel] = 1.f;
            cloud_scene.constants.haze_weight[channel] = 1.f;
            cloud_scene.constants.sky_sunlight[channel] = 0.5f;
            cloud_scene.constants.atmos_ambient[channel] = 0.2f;
            cloud_scene.constants.sky_light_atten[channel] = 0.1f;
            cloud_scene.constants.cloud_sunlight[channel] = 0.4f;
            cloud_scene.constants.cloud_color_shadow[channel] =
                0.6f - static_cast<float>(channel) * 0.1f;
        }
        cloud_scene.constants.cloud_color_shadow[3] = 0.25f;
        cloud_scene.constants.cloud_pos_density1[2] = 0.2f;
        cloud_scene.constants.cloud_pos_density2[2] = 0.5f;
        cloud_scene.constants.parameters[0] = 1.f;
        cloud_scene.constants.parameters[1] = 0.f;
        cloud_scene.constants.parameters[2] = 0.25f;
        cloud_scene.constants.parameters[3] = 0.5f;
        cloud_scene.width = 32;
        cloud_scene.height = 32;
        cloud_scene.normal_hdr = true;

        REQUIRE(renderer->compositeWindLightClouds(
            *pbr_gbuffer, cloud_scene, &error));
        INFO(error);
        cloud_scene.reverse_z = true;
        REQUIRE(renderer->compositeWindLightClouds(
            *pbr_reverse_gbuffer, cloud_scene, &error));
        INFO(error);
        cloud_scene.reverse_z = false;
        std::array<std::uint8_t, 32 * 32 * 4> cloud_albedo{};
        std::array<std::uint8_t, 32 * 32 * 4>
            reverse_cloud_albedo{};
        REQUIRE(pbr_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, cloud_albedo.data(), 32 * 4,
            &error));
        REQUIRE(pbr_reverse_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, reverse_cloud_albedo.data(),
            32 * 4, &error));
        INFO(error);
        CHECK(reverse_cloud_albedo == cloud_albedo);
        CHECK(cloud_albedo[outside + 0] !=
              aurora_albedo[outside + 0]);
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(cloud_albedo[center + channel] ==
                  aurora_albedo[center + channel]);
        }

        auto cloud_source_gbuffer = renderer->render(
            gbuffer_scene, &error);
        INFO(error);
        REQUIRE(cloud_source_gbuffer);
        REQUIRE(renderer->compositeWindLightSky(
            *cloud_source_gbuffer, black_windlight_scene, &error));
        REQUIRE(renderer->compositeWindLightClouds(
            *cloud_source_gbuffer, cloud_scene, &error));
        INFO(error);
        std::array<std::uint8_t, 32 * 32 * 4>
            cloud_source_albedo{};
        REQUIRE(cloud_source_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, cloud_source_albedo.data(),
            32 * 4, &error));
        INFO(error);
        constexpr float cloud_alpha = 0.36399375f;
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            const int expected = static_cast<int>(std::lround(
                static_cast<float>(aurora_albedo[outside + channel]) *
                (1.f - cloud_alpha))) +
                static_cast<int>(cloud_source_albedo[outside + channel]);
            CHECK(std::abs(static_cast<int>(
                      cloud_albedo[outside + channel]) - expected) <= 2);
        }

        // Like the rainbow/halo optics above, production cloud noise is a
        // fetched sRGB-backed asset consumed by GLSL through raw AnisoWrap.
        // Byte-identical raw and sRGB storage must produce the same full
        // source-over result; default sRGB sampling changes cloud density.
        auto encoded_cloud_gbuffer = renderer->render(
            gbuffer_scene, &error);
        INFO(error);
        REQUIRE(encoded_cloud_gbuffer);
        REQUIRE(renderer->compositeWindLightSky(
            *encoded_cloud_gbuffer, black_windlight_scene, &error));
        ALMetalWorldCloudScene encoded_cloud_scene = cloud_scene;
        encoded_cloud_scene.noise_texture = encoded_cloud_noise_a.get();
        encoded_cloud_scene.next_noise_texture =
            encoded_cloud_noise_b.get();
        REQUIRE(renderer->compositeWindLightClouds(
            *encoded_cloud_gbuffer, encoded_cloud_scene, &error));
        INFO(error);
        std::array<std::uint8_t, 32 * 32 * 4>
            encoded_cloud_albedo{};
        REQUIRE(encoded_cloud_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, encoded_cloud_albedo.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(encoded_cloud_albedo == cloud_source_albedo);

        auto cloud_a_gbuffer = renderer->render(gbuffer_scene, &error);
        auto cloud_b_gbuffer = renderer->render(gbuffer_scene, &error);
        INFO(error);
        REQUIRE(cloud_a_gbuffer);
        REQUIRE(cloud_b_gbuffer);
        REQUIRE(renderer->compositeWindLightSky(
            *cloud_a_gbuffer, black_windlight_scene, &error));
        REQUIRE(renderer->compositeWindLightSky(
            *cloud_b_gbuffer, black_windlight_scene, &error));
        cloud_scene.next_noise_texture = cloud_noise_a.get();
        cloud_scene.constants.parameters[2] = 0.f;
        REQUIRE(renderer->compositeWindLightClouds(
            *cloud_a_gbuffer, cloud_scene, &error));
        cloud_scene.noise_texture = cloud_noise_b.get();
        cloud_scene.next_noise_texture = cloud_noise_b.get();
        REQUIRE(renderer->compositeWindLightClouds(
            *cloud_b_gbuffer, cloud_scene, &error));
        INFO(error);
        std::array<std::uint8_t, 32 * 32 * 4> cloud_a_albedo{};
        std::array<std::uint8_t, 32 * 32 * 4> cloud_b_albedo{};
        REQUIRE(cloud_a_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, cloud_a_albedo.data(), 32 * 4,
            &error));
        REQUIRE(cloud_b_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, cloud_b_albedo.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(cloud_a_albedo[outside + 0] >
              cloud_source_albedo[outside + 0]);
        CHECK(cloud_b_albedo[outside + 0] <
              cloud_source_albedo[outside + 0]);
        cloud_scene.noise_texture = cloud_noise_a.get();
        cloud_scene.next_noise_texture = cloud_noise_b.get();
        cloud_scene.constants.parameters[2] = 0.25f;

        ALMetalWorldCloudScene invalid_cloud_scene = cloud_scene;
        invalid_cloud_scene.noise_texture = nullptr;
        error.clear();
        CHECK_FALSE(renderer->compositeWindLightClouds(
            *cloud_source_gbuffer, invalid_cloud_scene, &error));
        CHECK(error == "Metal world WindLight cloud scene is incomplete");
        error.clear();

        ALMetalWorldWindLightSkyScene invalid_windlight_scene =
            windlight_scene;
        invalid_windlight_scene.halo_texture = nullptr;
        error.clear();
        CHECK_FALSE(renderer->compositeWindLightSky(
            *pbr_gbuffer, invalid_windlight_scene, &error));
        CHECK(error == "Metal world WindLight sky scene is incomplete");
        error.clear();

        // Partial HDRI is one fail-closed transaction: WindLight first owns
        // every clear-depth pixel, then HDRI overwrites exactly the left-hand
        // pixel centers selected by skyF.glsl's split inequality.
        auto split_gbuffer = renderer->render(gbuffer_scene, &error);
        INFO(error);
        REQUIRE(split_gbuffer);
        REQUIRE(renderer->compositeWindLightSky(
            *split_gbuffer, windlight_scene, &error));
        sky_scene.horizontal_fraction = 0.5f;
        REQUIRE(renderer->compositeHDRISky(
            *split_gbuffer, sky_scene, &error));
        INFO(error);
        std::array<std::uint8_t, 32 * 32 * 4> split_albedo{};
        std::array<std::uint16_t, 32 * 32 * 4> split_normal{};
        REQUIRE(split_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, split_albedo.data(), 32 * 4,
            &error));
        REQUIRE(split_gbuffer->colorTexture(2)->readback(
            *device, 0, 0, {}, split_normal.data(), 32 * 8,
            &error));
        INFO(error);
        const std::size_t split_left = (2 * 32 + 2) * 4;
        const std::size_t split_right = (2 * 32 + 29) * 4;
        const std::size_t split_last_hdri = (2 * 32 + 15) * 4;
        const std::size_t split_first_windlight = (2 * 32 + 16) * 4;
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(split_albedo[split_left + channel] ==
                  sky_albedo[split_left + channel]);
            CHECK(split_albedo[split_right + channel] ==
                  windlight_albedo[split_right + channel]);
            CHECK(split_albedo[center + channel] ==
                  before_sky_albedo[center + channel]);
        }
        CHECK(split_normal[split_left + 3] == 65535);
        CHECK(split_normal[split_right + 3] == 0);
        CHECK(split_normal[split_last_hdri + 3] == 65535);
        CHECK(split_normal[split_first_windlight + 3] == 0);

        batch.modelview_projection[10] = -1.f;
        gbuffer_scene.reverse_z = true;
        auto reverse_split_gbuffer = renderer->render(
            gbuffer_scene, &error);
        INFO(error);
        REQUIRE(reverse_split_gbuffer);
        windlight_scene.reverse_z = true;
        REQUIRE(renderer->compositeWindLightSky(
            *reverse_split_gbuffer, windlight_scene, &error));
        sky_scene.reverse_z = true;
        REQUIRE(renderer->compositeHDRISky(
            *reverse_split_gbuffer, sky_scene, &error));
        std::array<std::uint8_t, 32 * 32 * 4> reverse_split_albedo{};
        REQUIRE(reverse_split_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, reverse_split_albedo.data(),
            32 * 4, &error));
        INFO(error);
        CHECK(reverse_split_albedo == split_albedo);
        batch.modelview_projection[10] = 1.f;
        gbuffer_scene.reverse_z = false;
        windlight_scene.reverse_z = false;
        sky_scene.reverse_z = false;

        sky_scene.horizontal_fraction = 0.f;
        REQUIRE(renderer->compositeHDRISky(
            *split_gbuffer, sky_scene, &error));
        std::array<std::uint8_t, 32 * 32 * 4> zero_split_albedo{};
        REQUIRE(split_gbuffer->colorTexture(0)->readback(
            *device, 0, 0, {}, zero_split_albedo.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(zero_split_albedo == split_albedo);

        sky_scene.horizontal_fraction = 1.1f;
        error.clear();
        CHECK_FALSE(renderer->compositeHDRISky(
            *split_gbuffer, sky_scene, &error));
        CHECK(error == "Metal world HDRI sky scene is incomplete");
        error.clear();
        sky_scene.horizontal_fraction = 1.f;

        // Restore the HDRI family before the existing light-map and base
        // checks so each transfer is independently identified by its marker.
        REQUIRE(renderer->compositeHDRISky(
            *pbr_gbuffer, sky_scene, &error));
        sky_scene.reverse_z = true;
        REQUIRE(renderer->compositeHDRISky(
            *pbr_reverse_gbuffer, sky_scene, &error));
        sky_scene.reverse_z = false;
        INFO(error);

        // The retained native G-buffer now owns the two-channel deferred
        // light map as well. With no shadows or SSAO both geometry and the
        // cleared sky are fully lit. Enabling the directional owner with no
        // built cascades still applies the exact shading-normal facing cut.
        ALMetalWorldLightMapScene light_map_scene;
        light_map_scene.gbuffer = pbr_gbuffer.get();
        for (std::size_t axis = 0; axis < 4; ++axis)
        {
            light_map_scene.constants
                .inverse_projection[axis * 4 + axis] = 1.f;
        }
        light_map_scene.constants.inverse_projection[14] = -1.f;
        light_map_scene.constants.light_direction[2] = 1.f;
        light_map_scene.constants.screen[0] = 32.f;
        light_map_scene.constants.screen[1] = 32.f;
        light_map_scene.constants.config[3] = 1;
        auto native_light_map = renderer->renderLightMap(
            light_map_scene, &error);
        INFO(error);
        REQUIRE(native_light_map);
        std::array<std::uint8_t, 32 * 32 * 2> native_light_pixels{};
        REQUIRE(native_light_map->colorTexture(0)->readback(
            *device, 0, 0, {}, native_light_pixels.data(), 32 * 2,
            &error));
        INFO(error);
        const std::size_t light_center = (16 * 32 + 16) * 2;
        const std::size_t light_outside = (2 * 32 + 2) * 2;
        CHECK(native_light_pixels[light_center + 0] == 255);
        CHECK(native_light_pixels[light_center + 1] == 255);
        CHECK(native_light_pixels[light_outside + 0] == 255);
        CHECK(native_light_pixels[light_outside + 1] == 255);

        light_map_scene.constants.config[1] = 1;
        light_map_scene.constants.light_direction[2] = -1.f;
        auto back_facing_light_map = renderer->renderLightMap(
            light_map_scene, &error);
        INFO(error);
        REQUIRE(back_facing_light_map);
        std::array<std::uint8_t, 32 * 32 * 2> back_facing_pixels{};
        REQUIRE(back_facing_light_map->colorTexture(0)->readback(
            *device, 0, 0, {}, back_facing_pixels.data(), 32 * 2,
            &error));
        INFO(error);
        CHECK(back_facing_pixels[light_center + 0] == 0);
        CHECK(back_facing_pixels[light_center + 1] == 255);
        CHECK(back_facing_pixels[light_outside + 0] == 255);

        // A constant raw-depth cascade maps the receiver to depth 0.5. Its
        // stored 0.25 is shadowing under forward-Z, while declaring the same
        // cascade unbuilt restores fully lit without sampling it.
        ALMetalTextureDescriptor world_shadow_descriptor;
        world_shadow_descriptor.type =
            ALMetalTextureType::texture_2d_array;
        world_shadow_descriptor.format = ALMetalPixelFormat::r32_float;
        world_shadow_descriptor.width = 8;
        world_shadow_descriptor.height = 8;
        world_shadow_descriptor.array_length = 4;
        world_shadow_descriptor.storage = ALMetalStorageMode::private_gpu;
        world_shadow_descriptor.usage = ALMetalTextureUsage::shader_read;
        world_shadow_descriptor.label =
            "Alchemy world light-map directional-shadow test";
        auto world_shadow_texture = ALMetalTexture::create(
            *device, world_shadow_descriptor, &error);
        INFO(error);
        REQUIRE(world_shadow_texture);
        const std::array<float, 8 * 8> shadowed_depth = []
        {
            std::array<float, 8 * 8> value{};
            value.fill(0.25f);
            return value;
        }();
        const std::array<float, 8 * 8> fully_lit_depth = []
        {
            std::array<float, 8 * 8> value{};
            value.fill(1.f);
            return value;
        }();
        auto world_shadow_upload = device->makeCommandBuffer(
            "Alchemy world light-map directional-shadow upload", &error);
        INFO(error);
        REQUIRE(world_shadow_upload);
        for (std::uint32_t cascade = 0; cascade < 4; ++cascade)
        {
            const auto& values = cascade == 0
                ? shadowed_depth : fully_lit_depth;
            REQUIRE(world_shadow_texture->upload(
                *world_shadow_upload, 0, cascade, {}, values.data(),
                8 * sizeof(float), &error));
        }
        REQUIRE(world_shadow_upload->commitAndWait(&error));
        INFO(error);

        ALMetalWorldDirectionalShadows world_shadows;
        world_shadows.depth_texture = world_shadow_texture.get();
        for (std::size_t cascade = 0; cascade < 4; ++cascade)
        {
            float* matrix = world_shadows.constants
                                .shadow_matrix[cascade];
            matrix[12] = 0.5f;
            matrix[13] = 0.5f;
            matrix[14] = 0.5f;
            matrix[15] = 1.f;
        }
        world_shadows.constants.shadow_clip[0] = 4.f;
        world_shadows.constants.shadow_clip[1] = 8.f;
        world_shadows.constants.shadow_clip[2] = 12.f;
        world_shadows.constants.shadow_clip[3] = 16.f;
        world_shadows.constants.resolution[0] = 8.f;
        world_shadows.constants.resolution[1] = 8.f;
        world_shadows.constants.resolution[2] = 32.f;
        world_shadows.constants.resolution[3] = 32.f;
        world_shadows.constants.parameters[2] = 200.f;
        world_shadows.constants.parameters[3] = 32.f;
        world_shadows.constants.config[0] = 4;
        world_shadows.constants.config[1] = 0xeu;
        world_shadows.constants.config[3] = 1;
        light_map_scene.directional_shadows = &world_shadows;
        light_map_scene.constants.light_direction[2] = 1.f;
        auto shadowed_light_map = renderer->renderLightMap(
            light_map_scene, &error);
        INFO(error);
        REQUIRE(shadowed_light_map);
        std::array<std::uint8_t, 32 * 32 * 2> shadowed_light_pixels{};
        REQUIRE(shadowed_light_map->colorTexture(0)->readback(
            *device, 0, 0, {}, shadowed_light_pixels.data(), 32 * 2,
            &error));
        INFO(error);
        CHECK(shadowed_light_pixels[light_center + 0] == 0);
        CHECK(shadowed_light_pixels[light_center + 1] == 255);
        world_shadows.constants.config[1] = 0xfu;
        auto unbuilt_light_map = renderer->renderLightMap(
            light_map_scene, &error);
        INFO(error);
        REQUIRE(unbuilt_light_map);
        std::array<std::uint8_t, 32 * 32 * 2> unbuilt_light_pixels{};
        REQUIRE(unbuilt_light_map->colorTexture(0)->readback(
            *device, 0, 0, {}, unbuilt_light_pixels.data(), 32 * 2,
            &error));
        INFO(error);
        CHECK(unbuilt_light_pixels[light_center + 0] == 255);

        // Shadow storage retains GL row order: row zero is the lower row for
        // both a GL mirror upload and a native caster render. An asymmetric
        // cascade makes a second Y inversion in the Metal consumer visible.
        // The lower half shadows a receiver mapped to v=0.25, while the same
        // receiver moved to the upper half at v=0.75 is fully lit.
        std::array<float, 8 * 8> lower_rows_shadowed = fully_lit_depth;
        for (std::size_t y = 0; y < 4; ++y)
        {
            std::fill_n(lower_rows_shadowed.begin() + y * 8, 8, 0.25f);
        }
        auto asymmetric_shadow_upload = device->makeCommandBuffer(
            "Alchemy asymmetric directional-shadow upload", &error);
        INFO(error);
        REQUIRE(asymmetric_shadow_upload);
        REQUIRE(world_shadow_texture->upload(
            *asymmetric_shadow_upload, 0, 0, {},
            lower_rows_shadowed.data(), 8 * sizeof(float), &error));
        REQUIRE(asymmetric_shadow_upload->commitAndWait(&error));
        INFO(error);

        world_shadows.constants.config[1] = 0xeu;
        world_shadows.constants.shadow_matrix[0][13] = 0.25f;
        auto lower_shadow_light_map = renderer->renderLightMap(
            light_map_scene, &error);
        INFO(error);
        REQUIRE(lower_shadow_light_map);
        std::array<std::uint8_t, 32 * 32 * 2> lower_shadow_pixels{};
        REQUIRE(lower_shadow_light_map->colorTexture(0)->readback(
            *device, 0, 0, {}, lower_shadow_pixels.data(), 32 * 2,
            &error));
        INFO(error);
        CHECK(lower_shadow_pixels[light_center + 0] == 0);

        world_shadows.constants.shadow_matrix[0][13] = 0.75f;
        auto upper_lit_light_map = renderer->renderLightMap(
            light_map_scene, &error);
        INFO(error);
        REQUIRE(upper_lit_light_map);
        std::array<std::uint8_t, 32 * 32 * 2> upper_lit_pixels{};
        REQUIRE(upper_lit_light_map->colorTexture(0)->readback(
            *device, 0, 0, {}, upper_lit_pixels.data(), 32 * 2,
            &error));
        INFO(error);
        CHECK(upper_lit_pixels[light_center + 0] == 255);

        // Reflection-probe captures take shadowUtil.glsl's uniform
        // cube_snapshot shortcut: one hardware tap instead of the ordinary
        // 2/4/6-wide or PCSS filter. Compare tiers retain the tap's bilinear
        // 2x2 depth comparison, while Ultra's raw point sampler reads one
        // texel. A single lit texel at the lower-left of the four around
        // (0.5, 0.5) distinguishes both contracts from the full filters.
        std::array<float, 8 * 8> probe_single_tap_depth = shadowed_depth;
        probe_single_tap_depth[3 * 8 + 3] = 1.f;
        auto probe_shadow_upload = device->makeCommandBuffer(
            "Alchemy probe single-tap shadow upload", &error);
        INFO(error);
        REQUIRE(probe_shadow_upload);
        REQUIRE(world_shadow_texture->upload(
            *probe_shadow_upload, 0, 0, {},
            probe_single_tap_depth.data(), 8 * sizeof(float), &error));
        REQUIRE(probe_shadow_upload->commitAndWait(&error));
        INFO(error);

        world_shadows.constants.shadow_matrix[0][13] = 0.5f;
        for (std::uint32_t quality = 0; quality < 3; ++quality)
        {
            CAPTURE(quality);
            world_shadows.constants.config[3] = quality |
                ALMetalWorldDirectionalShadowConstants::probe_single_tap;
            auto probe_compare_light_map = renderer->renderLightMap(
                light_map_scene, &error);
            INFO(error);
            REQUIRE(probe_compare_light_map);
            std::array<std::uint8_t, 32 * 32 * 2> probe_compare_pixels{};
            REQUIRE(probe_compare_light_map->colorTexture(0)->readback(
                *device, 0, 0, {}, probe_compare_pixels.data(), 32 * 2,
                &error));
            INFO(error);
            CHECK(std::abs(static_cast<int>(
                               probe_compare_pixels[light_center + 0]) -
                           64) <= 1);
        }

        world_shadows.constants.config[3] = 3u |
            ALMetalWorldDirectionalShadowConstants::probe_single_tap;
        auto probe_raw_light_map = renderer->renderLightMap(
            light_map_scene, &error);
        INFO(error);
        REQUIRE(probe_raw_light_map);
        std::array<std::uint8_t, 32 * 32 * 2> probe_raw_pixels{};
        REQUIRE(probe_raw_light_map->colorTexture(0)->readback(
            *device, 0, 0, {}, probe_raw_pixels.data(), 32 * 2,
            &error));
        INFO(error);
        CHECK(probe_raw_pixels[light_center + 0] == 0);

        world_shadows.constants.config[3] = 0x8u;
        error.clear();
        CHECK_FALSE(renderer->renderLightMap(light_map_scene, &error));
        CHECK(error == "Metal world light-map scene is incomplete");
        world_shadows.constants.config[3] = 1u;

        light_map_scene.directional_shadows = nullptr;
        light_map_scene.constants.config[1] = 0;

        light_map_scene.gbuffer = pbr_reverse_gbuffer.get();
        light_map_scene.constants.inverse_projection[10] = -1.f;
        light_map_scene.constants.config[0] = 1;
        auto reverse_light_map = renderer->renderLightMap(
            light_map_scene, &error);
        INFO(error);
        REQUIRE(reverse_light_map);
        std::array<std::uint8_t, 32 * 32 * 2> reverse_light_pixels{};
        REQUIRE(reverse_light_map->colorTexture(0)->readback(
            *device, 0, 0, {}, reverse_light_pixels.data(), 32 * 2,
            &error));
        INFO(error);
        CHECK(reverse_light_pixels[light_center + 0] ==
              native_light_pixels[light_center + 0]);
        CHECK(reverse_light_pixels[light_center + 1] ==
              native_light_pixels[light_center + 1]);
        light_map_scene.gbuffer = pbr_gbuffer.get();
        light_map_scene.constants.inverse_projection[10] = 1.f;
        light_map_scene.constants.config[0] = 0;

        // SSAO consumes the exact 128-square reflected-noise contract and
        // applies the same twelve-tap bilateral blur on each axis. A stepped
        // retained G-buffer must contain occlusion, and a non-zero blur must
        // redistribute at least one occluded texel without touching R.
        ALMetalTextureDescriptor noise_descriptor;
        noise_descriptor.format = ALMetalPixelFormat::rg32_float;
        noise_descriptor.width = 128;
        noise_descriptor.height = 128;
        noise_descriptor.storage = ALMetalStorageMode::private_gpu;
        noise_descriptor.usage = ALMetalTextureUsage::shader_read;
        noise_descriptor.label = "Alchemy world SSAO reflected noise";
        auto noise_texture = ALMetalTexture::create(
            *device, noise_descriptor, &error);
        INFO(error);
        REQUIRE(noise_texture);
        std::array<float, 128 * 128 * 2> noise_values{};
        for (std::size_t texel = 0; texel < 128 * 128; ++texel)
        {
            constexpr float directions[4][2] = {
                {1.f, 0.f}, {0.f, 1.f},
                {-1.f, 0.f}, {0.f, -1.f},
            };
            noise_values[texel * 2 + 0] =
                directions[texel & 3u][0];
            noise_values[texel * 2 + 1] =
                directions[texel & 3u][1];
        }
        auto noise_upload = device->makeCommandBuffer(
            "Alchemy world SSAO reflected-noise upload", &error);
        INFO(error);
        REQUIRE(noise_upload);
        REQUIRE(noise_texture->upload(
            *noise_upload, 0, 0, {}, noise_values.data(),
            128 * 2 * sizeof(float), &error));
        REQUIRE(noise_upload->commitAndWait(&error));
        INFO(error);

        std::array<ALMetalWorldSimpleBatch, 2> occlusion_batches{{
            batch, batch,
        }};
        occlusion_batches[0].impostor_left[0] = 0.9f;
        occlusion_batches[0].impostor_up[1] = 0.9f;
        occlusion_batches[1].impostor_center[0] = 0.25f;
        occlusion_batches[1].impostor_center[2] = -0.9f;
        occlusion_batches[1].impostor_left[0] = 0.2f;
        occlusion_batches[1].impostor_up[1] = 0.6f;
        ALMetalWorldGBufferScene occlusion_scene = gbuffer_scene;
        occlusion_scene.batches = occlusion_batches.data();
        occlusion_scene.batch_count = occlusion_batches.size();
        auto occlusion_gbuffer = renderer->render(
            occlusion_scene, &error);
        INFO(error);
        REQUIRE(occlusion_gbuffer);

        light_map_scene.gbuffer = occlusion_gbuffer.get();
        light_map_scene.noise_texture = noise_texture.get();
        light_map_scene.constants.ssao[0] = 96.f;
        light_map_scene.constants.ssao[1] = 96.f;
        light_map_scene.constants.ssao[2] = 4.f;
        light_map_scene.constants.ssao[3] = 0.25f;
        for (std::size_t tap = 0; tap < 4; ++tap)
        {
            const float offset = static_cast<float>(tap);
            const float weight = std::exp(
                -(offset * offset) / 8.f);
            light_map_scene.constants.blur_taps[tap][0] = weight;
            light_map_scene.constants.blur_taps[tap][1] = weight;
            light_map_scene.constants.blur_taps[tap][2] = offset;
        }
        light_map_scene.constants.blur[1] = 0.1f;
        light_map_scene.constants.config[2] = 1;
        auto unblurred_ssao = renderer->renderLightMap(
            light_map_scene, &error);
        INFO(error);
        REQUIRE(unblurred_ssao);
        std::array<std::uint8_t, 32 * 32 * 2> unblurred_ssao_pixels{};
        REQUIRE(unblurred_ssao->colorTexture(0)->readback(
            *device, 0, 0, {}, unblurred_ssao_pixels.data(), 32 * 2,
            &error));
        INFO(error);
        light_map_scene.constants.blur[0] = 1.5f;
        auto blurred_ssao = renderer->renderLightMap(
            light_map_scene, &error);
        INFO(error);
        REQUIRE(blurred_ssao);
        std::array<std::uint8_t, 32 * 32 * 2> blurred_ssao_pixels{};
        REQUIRE(blurred_ssao->colorTexture(0)->readback(
            *device, 0, 0, {}, blurred_ssao_pixels.data(), 32 * 2,
            &error));
        INFO(error);
        bool found_occlusion = false;
        bool found_blur_change = false;
        std::uint8_t minimum_unblurred = 255;
        std::uint8_t minimum_blurred = 255;
        std::size_t changed_pixels = 0;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            CHECK(blurred_ssao_pixels[pixel * 2 + 0] ==
                  unblurred_ssao_pixels[pixel * 2 + 0]);
            found_occlusion = found_occlusion ||
                unblurred_ssao_pixels[pixel * 2 + 1] < 255;
            minimum_unblurred = std::min(
                minimum_unblurred,
                unblurred_ssao_pixels[pixel * 2 + 1]);
            minimum_blurred = std::min(
                minimum_blurred,
                blurred_ssao_pixels[pixel * 2 + 1]);
            if (blurred_ssao_pixels[pixel * 2 + 1] !=
                unblurred_ssao_pixels[pixel * 2 + 1])
            {
                found_blur_change = true;
                ++changed_pixels;
            }
        }
        CAPTURE(minimum_unblurred, minimum_blurred, changed_pixels);
        CHECK(found_occlusion);
        CHECK(found_blur_change);

        ALMetalWorldLightMapScene invalid_light_map_scene;
        error.clear();
        CHECK_FALSE(renderer->renderLightMap(
            invalid_light_map_scene, &error));
        CHECK(error == "Metal world light-map scene is incomplete");
        error.clear();

        // Consume the same retained PBR G-buffer through the base deferred
        // owner. One constant ordinary probe proves that its packed SH row
        // and roughness-selected radiance cube are both live inputs; the
        // borrowed RG light map then proves direct shadow and SSAO response.
        ALMetalTextureDescriptor radiance_descriptor;
        radiance_descriptor.type = ALMetalTextureType::texture_cube_array;
        radiance_descriptor.format = ALMetalPixelFormat::rgba8_unorm;
        radiance_descriptor.width = 1;
        radiance_descriptor.height = 1;
        radiance_descriptor.array_length = 1;
        radiance_descriptor.storage = ALMetalStorageMode::private_gpu;
        radiance_descriptor.usage = ALMetalTextureUsage::shader_read;
        radiance_descriptor.label = "Alchemy base-light probe radiance";
        auto radiance = ALMetalTexture::create(
            *device, radiance_descriptor, &error);
        INFO(error);
        REQUIRE(radiance);

        ALMetalTextureDescriptor irradiance_descriptor;
        irradiance_descriptor.format = ALMetalPixelFormat::rgba32_uint;
        irradiance_descriptor.width = 4;
        irradiance_descriptor.height = 1;
        irradiance_descriptor.storage = ALMetalStorageMode::private_gpu;
        irradiance_descriptor.usage = ALMetalTextureUsage::shader_read;
        irradiance_descriptor.label = "Alchemy base-light packed SH row";
        auto irradiance = ALMetalTexture::create(
            *device, irradiance_descriptor, &error);
        INFO(error);
        REQUIRE(irradiance);

        ALMetalTextureDescriptor light_map_descriptor;
        light_map_descriptor.format = ALMetalPixelFormat::rg8_unorm;
        light_map_descriptor.width = 32;
        light_map_descriptor.height = 32;
        light_map_descriptor.storage = ALMetalStorageMode::private_gpu;
        light_map_descriptor.usage = ALMetalTextureUsage::shader_read;
        light_map_descriptor.label = "Alchemy base-light borrowed light map";
        auto light_map = ALMetalTexture::create(
            *device, light_map_descriptor, &error);
        INFO(error);
        REQUIRE(light_map);

        const std::array<std::uint8_t, 4> green_radiance{{
            0, 128, 0, 255,
        }};
        std::array<std::uint32_t, 16> packed_sh{};
        packed_sh[0] = 0x3c003c00u;
        packed_sh[1] = 0x00003c00u;
        std::array<std::uint8_t, 32 * 32 * 2> full_light_map{};
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            full_light_map[pixel * 2 + 0] = 255;
            full_light_map[pixel * 2 + 1] = 255;
        }
        auto base_upload = device->makeCommandBuffer(
            "Alchemy base-light inputs upload", &error);
        INFO(error);
        REQUIRE(base_upload);
        for (std::uint32_t face = 0; face < 6; ++face)
        {
            REQUIRE(radiance->upload(
                *base_upload, 0, face, {}, green_radiance.data(), 4,
                &error));
        }
        REQUIRE(irradiance->upload(
            *base_upload, 0, 0, {}, packed_sh.data(), 4 * 16, &error));
        REQUIRE(light_map->upload(
            *base_upload, 0, 0, {}, full_light_map.data(), 32 * 2,
            &error));
        REQUIRE(base_upload->commitAndWait(&error));
        INFO(error);

        ALMetalWorldReflectionProbes base_probes;
        base_probes.radiance_texture = radiance.get();
        base_probes.irradiance_texture = irradiance.get();
        base_probes.constants.ref_sphere[0][3] = 100.f;
        base_probes.constants.ref_params[0][0] = 1.f;
        base_probes.constants.ref_params[0][1] = 1.f;
        base_probes.constants.ref_params[0][2] = 1.f;
        base_probes.constants.ref_index[0][0] = 0;
        base_probes.constants.ref_index[0][1] = -1;
        base_probes.constants.env_matrix[0][0] = 1.f;
        base_probes.constants.env_matrix[1][1] = 1.f;
        base_probes.constants.env_matrix[2][2] = 1.f;
        base_probes.constants.config[0] = 1.f;
        base_probes.constants.config[1] = 0.f;

        ALMetalWorldBaseLightingScene base_scene;
        base_scene.gbuffer = pbr_gbuffer.get();
        base_scene.light_map = light_map.get();
        base_scene.reflection_probes = &base_probes;
        for (std::size_t axis = 0; axis < 4; ++axis)
        {
            base_scene.constants.inverse_projection[axis * 4 + axis] = 1.f;
        }
        base_scene.constants.light_direction[2] = 1.f;
        base_scene.constants.atmos_sunlit_linear[0] = 1.f;
        base_scene.constants.atmos_sunlit_linear[1] = 1.f;
        base_scene.constants.atmos_sunlit_linear[2] = 1.f;
        base_scene.constants.lighting[0] = 1.f;
        base_scene.constants.lighting[1] = 1.f;
        base_scene.constants.lighting[2] = 0.25f;
        base_scene.constants.lighting[3] = 0.25f;
        base_scene.constants.surface[0] = 128.f;
        base_scene.constants.surface[1] = 1.f;
        base_scene.constants.ssao_effect[0][0] = 1.f;
        base_scene.constants.ssao_effect[1][1] = 1.f;
        base_scene.constants.ssao_effect[2][2] = 1.f;
        base_scene.constants.config[2] = 1;

        auto base_lit = renderer->renderBaseLighting(base_scene, &error);
        INFO(error);
        REQUIRE(base_lit);
        std::array<std::uint8_t, 32 * 32 * 4> base_pixels{};
        REQUIRE(base_lit->colorTexture(0)->readback(
            *device, 0, 0, {}, base_pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(base_pixels[center + 0] > 0);
        CHECK(base_pixels[center + 1] > 0);
        CHECK(base_pixels[center + 2] > 0);
        CHECK(base_pixels[center + 3] == 0);
        CHECK(base_pixels[outside + 0] == 0);
        CHECK(base_pixels[outside + 1] == 0);
        CHECK(base_pixels[outside + 2] == 0);

        // Reflection probes are an optional viewer setting. Their disabled
        // GL variant samples the sharp legacy sky cube and uses the authored
        // ambiance blend instead of requiring a probe-array/SH pair. Prove
        // the native base owner accepts that mutually exclusive resource
        // family and actually consumes its radiance.
        ALMetalTextureDescriptor legacy_environment_descriptor;
        legacy_environment_descriptor.type =
            ALMetalTextureType::texture_cube;
        legacy_environment_descriptor.format =
            ALMetalPixelFormat::rgba8_unorm;
        legacy_environment_descriptor.width = 1;
        legacy_environment_descriptor.height = 1;
        legacy_environment_descriptor.storage =
            ALMetalStorageMode::private_gpu;
        legacy_environment_descriptor.usage =
            ALMetalTextureUsage::shader_read;
        legacy_environment_descriptor.label =
            "Alchemy base-light legacy sky environment";
        auto legacy_environment = ALMetalTexture::create(
            *device, legacy_environment_descriptor, &error);
        INFO(error);
        REQUIRE(legacy_environment);
        const std::array<std::uint8_t, 4> blue_environment{{
            0, 64, 255, 255,
        }};
        auto legacy_environment_upload = device->makeCommandBuffer(
            "Alchemy base-light legacy sky upload", &error);
        INFO(error);
        REQUIRE(legacy_environment_upload);
        for (std::uint32_t face = 0; face < 6; ++face)
        {
            REQUIRE(legacy_environment->upload(
                *legacy_environment_upload, 0, face, {},
                blue_environment.data(), blue_environment.size(),
                &error));
        }
        REQUIRE(legacy_environment_upload->commitAndWait(&error));
        INFO(error);

        ALMetalWorldBaseLightingScene legacy_environment_scene =
            base_scene;
        legacy_environment_scene.reflection_probes = nullptr;
        legacy_environment_scene.legacy_environment =
            legacy_environment.get();
        legacy_environment_scene.constants.environment[0] = 0.5f;
        legacy_environment_scene.constants.environment_config[0] = 1;
        auto legacy_environment_lit = renderer->renderBaseLighting(
            legacy_environment_scene, &error);
        INFO(error);
        REQUIRE(legacy_environment_lit);
        std::array<std::uint8_t, 32 * 32 * 4>
            legacy_environment_pixels{};
        REQUIRE(legacy_environment_lit->colorTexture(0)->readback(
            *device, 0, 0, {}, legacy_environment_pixels.data(),
            32 * 4, &error));
        INFO(error);
        CHECK(legacy_environment_pixels[center + 2] > 0);
        CHECK((legacy_environment_pixels[center + 0] !=
                   base_pixels[center + 0] ||
               legacy_environment_pixels[center + 1] !=
                   base_pixels[center + 1] ||
               legacy_environment_pixels[center + 2] !=
                   base_pixels[center + 2]));

        legacy_environment_scene.constants.environment_config[0] = 0;
        error.clear();
        CHECK_FALSE(renderer->renderBaseLighting(
            legacy_environment_scene, &error));
        CHECK(error == "Metal world base-light scene is incomplete");
        legacy_environment_scene.constants.environment_config[0] = 1;
        legacy_environment_scene.reflection_probes = &base_probes;
        error.clear();
        CHECK_FALSE(renderer->renderBaseLighting(
            legacy_environment_scene, &error));
        CHECK(error == "Metal world base-light scene is incomplete");

        // GL writes this base result into screen first, then adds ordinary
        // and projector lights with ONE/ONE blending. The native owner keeps
        // that boundary separate from post-deferred geometry and output
        // transforms while reproducing the exact three-target sum.
        ALMetalWorldLightingCompositionScene composition_scene;
        composition_scene.base_lighting = base_lit.get();
        composition_scene.local_lighting = legacy.get();
        composition_scene.projector_lighting = projected.get();
        auto composed = renderer->composeLighting(
            composition_scene, &error);
        INFO(error);
        REQUIRE(composed);
        REQUIRE(composed->descriptor().colors[0].format ==
                ALMetalPixelFormat::rgba8_unorm);
        std::array<std::uint8_t, 32 * 32 * 4> composed_pixels{};
        REQUIRE(composed->colorTexture(0)->readback(
            *device, 0, 0, {}, composed_pixels.data(), 32 * 4,
            &error));
        INFO(error);
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            const int expected = std::min(
                static_cast<int>(base_pixels[center + channel]) +
                    static_cast<int>(legacy_pixels[center + channel]) +
                    static_cast<int>(projected_pixels[center + channel]),
                255);
            CHECK(std::abs(static_cast<int>(
                      composed_pixels[center + channel]) - expected) <= 1);
            CHECK(composed_pixels[outside + channel] == 0);
        }
        CHECK(composed_pixels[center + 3] == 0);
        CHECK(composed_pixels[outside + 3] == 0);

        // The integrated route carries exact G-buffer depth through lighting
        // composition and transfers the resulting owner into opaque-forward
        // rendering. The same target must survive in place: color and depth
        // stay bit-identical without a redundant full-frame color blit.
        ALMetalWorldLightingCompositionScene continued_composition_scene =
            composition_scene;
        continued_composition_scene.depth_source = pbr_gbuffer.get();
        continued_composition_scene.depth_stencil_shader_read = true;
        auto continued_composed = renderer->composeLighting(
            continued_composition_scene, &error);
        INFO(error);
        REQUIRE(continued_composed);
        REQUIRE(continued_composed->descriptor().depth_stencil_format ==
                ALMetalPixelFormat::depth32_float_stencil8);
        CHECK(continued_composed->descriptor().depth_stencil_shader_read);
        const ALMetalRenderTarget* continued_identity =
            continued_composed.get();
        ALMetalWorldOpaquePostDeferredScene continued_opaque_scene;
        continued_opaque_scene.gbuffer = pbr_gbuffer.get();
        continued_opaque_scene.composed_lighting =
            continued_composed.get();
        continued_opaque_scene.width = 32;
        continued_opaque_scene.height = 32;
        auto continued_opaque = renderer->renderOpaquePostDeferred(
            continued_opaque_scene, std::move(continued_composed), &error);
        INFO(error);
        REQUIRE(continued_opaque);
        CHECK(continued_opaque.get() == continued_identity);
        std::array<std::uint8_t, 32 * 32 * 4>
            continued_composed_pixels{};
        std::array<float, 32 * 32> continued_depth{};
        std::array<float, 32 * 32> source_depth{};
        REQUIRE(continued_opaque->colorTexture(0)->readback(
            *device, 0, 0, {}, continued_composed_pixels.data(), 32 * 4,
            &error));
        REQUIRE(continued_opaque->depthStencilTexture()->readback(
            *device, 0, 0, {}, continued_depth.data(),
            32 * sizeof(float), &error));
        REQUIRE(pbr_gbuffer->depthStencilTexture()->readback(
            *device, 0, 0, {}, source_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK(continued_composed_pixels == composed_pixels);
        CHECK(continued_depth == source_depth);

        // Production no longer materializes ordinary/projector targets or a
        // fourth composition target. Base lighting carries exact G-buffer
        // depth, then both additive families load and continue that same
        // owner. Compare the physical result with the retained standalone
        // three-target contract before proving the owner also survives the
        // opaque-forward handoff.
        ALMetalWorldProjectorLightingScene accumulated_projector_scene =
            projector_scene;
        accumulated_projector_scene.gbuffer = pbr_gbuffer.get();
        ALMetalWorldLightingCompositionScene accumulation_reference_scene;
        accumulation_reference_scene.base_lighting = base_lit.get();
        accumulation_reference_scene.local_lighting = pbr.get();
        accumulation_reference_scene.projector_lighting =
            pbr_projector.get();
        auto accumulation_reference = renderer->composeLighting(
            accumulation_reference_scene, &error);
        INFO(error);
        REQUIRE(accumulation_reference);
        std::array<std::uint8_t, 32 * 32 * 4>
            accumulation_reference_pixels{};
        REQUIRE(accumulation_reference->colorTexture(0)->readback(
            *device, 0, 0, {}, accumulation_reference_pixels.data(),
            32 * 4, &error));

        ALMetalWorldBaseLightingScene accumulated_base_scene = base_scene;
        accumulated_base_scene.carry_depth = true;
        accumulated_base_scene.depth_stencil_shader_read = true;
        auto accumulated = renderer->renderBaseLighting(
            accumulated_base_scene, &error);
        INFO(error);
        REQUIRE(accumulated);
        REQUIRE(accumulated->descriptor().depth_stencil_format ==
                ALMetalPixelFormat::depth32_float_stencil8);
        CHECK(accumulated->descriptor().depth_stencil_shader_read);
        const ALMetalRenderTarget* accumulated_identity = accumulated.get();
        REQUIRE(renderer->accumulateLocalLights(
            *accumulated, lighting_scene, &error));
        INFO(error);
        REQUIRE(renderer->accumulateProjectorLights(
            *accumulated, accumulated_projector_scene, &error));
        INFO(error);
        std::array<std::uint8_t, 32 * 32 * 4> accumulated_pixels{};
        std::array<float, 32 * 32> accumulated_depth{};
        REQUIRE(accumulated->colorTexture(0)->readback(
            *device, 0, 0, {}, accumulated_pixels.data(), 32 * 4,
            &error));
        REQUIRE(accumulated->depthStencilTexture()->readback(
            *device, 0, 0, {}, accumulated_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK(accumulated_pixels == accumulation_reference_pixels);
        CHECK(accumulated_depth == source_depth);

        ALMetalWorldOpaquePostDeferredScene accumulated_opaque_scene;
        accumulated_opaque_scene.gbuffer = pbr_gbuffer.get();
        accumulated_opaque_scene.composed_lighting = accumulated.get();
        accumulated_opaque_scene.width = 32;
        accumulated_opaque_scene.height = 32;
        auto accumulated_opaque = renderer->renderOpaquePostDeferred(
            accumulated_opaque_scene, std::move(accumulated), &error);
        INFO(error);
        REQUIRE(accumulated_opaque);
        CHECK(accumulated_opaque.get() == accumulated_identity);

        // The production path encodes the light map, carried-depth base and
        // both in-place additive families into one command buffer. A fresh
        // renderer must generate the shared BRDF LUT only once inside that
        // batch, and canceling an earlier batch must not leave the renderer
        // claiming that discarded generation is available to the next one.
        auto batched_renderer = ALMetalWorldGBufferRenderer::create(
            *device, &error);
        INFO(error);
        REQUIRE(batched_renderer);
        REQUIRE(batched_renderer->beginCommandBatch(
            "Alchemy discarded deferred-light test batch", &error));
        auto discarded_base = batched_renderer->renderBaseLighting(
            base_scene, &error);
        INFO(error);
        REQUIRE(discarded_base);
        batched_renderer->cancelCommandBatch();

        ALMetalWorldLocalLightingScene batched_local_scene =
            lighting_scene;
        batched_local_scene.gbuffer = pbr_gbuffer.get();
        ALMetalWorldLightMapScene batched_light_map_scene;
        batched_light_map_scene.gbuffer = pbr_gbuffer.get();
        for (std::size_t axis = 0; axis < 4; ++axis)
        {
            batched_light_map_scene.constants
                .inverse_projection[axis * 4 + axis] = 1.f;
        }
        batched_light_map_scene.constants.inverse_projection[14] = -1.f;
        batched_light_map_scene.constants.light_direction[2] = 1.f;
        batched_light_map_scene.constants.screen[0] = 32.f;
        batched_light_map_scene.constants.screen[1] = 32.f;
        batched_light_map_scene.constants.config[3] = 1;
        REQUIRE(batched_renderer->beginCommandBatch(
            "Alchemy deferred-light test batch", &error));
        auto batched_light_map = batched_renderer->renderLightMap(
            batched_light_map_scene, &error);
        INFO(error);
        REQUIRE(batched_light_map);
        ALMetalWorldBaseLightingScene batched_base_scene = base_scene;
        batched_base_scene.light_map =
            batched_light_map->colorTexture(0);
        batched_base_scene.carry_depth = true;
        batched_base_scene.depth_stencil_shader_read = true;
        auto batched_base = batched_renderer->renderBaseLighting(
            batched_base_scene, &error);
        INFO(error);
        REQUIRE(batched_base);
        const ALMetalRenderTarget* batched_identity = batched_base.get();
        REQUIRE(batched_renderer->accumulateLocalLights(
            *batched_base, batched_local_scene, &error));
        INFO(error);
        REQUIRE(batched_renderer->accumulateProjectorLights(
            *batched_base, accumulated_projector_scene, &error));
        INFO(error);
        CHECK(batched_base.get() == batched_identity);
        REQUIRE(batched_renderer->commitCommandBatch(&error));
        INFO(error);

        std::array<std::uint8_t, 32 * 32 * 2> batched_light_map_pixels{};
        std::array<std::uint8_t, 32 * 32 * 4>
            batched_accumulated_pixels{};
        std::array<float, 32 * 32> batched_depth{};
        REQUIRE(batched_light_map->colorTexture(0)->readback(
            *device, 0, 0, {}, batched_light_map_pixels.data(), 32 * 2,
            &error));
        REQUIRE(batched_base->colorTexture(0)->readback(
            *device, 0, 0, {}, batched_accumulated_pixels.data(), 32 * 4,
            &error));
        REQUIRE(batched_base->depthStencilTexture()->readback(
            *device, 0, 0, {}, batched_depth.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK(batched_light_map_pixels == full_light_map);
        CHECK(batched_accumulated_pixels ==
              accumulation_reference_pixels);
        CHECK(batched_depth == source_depth);

        // Merely seeing clear depth and a normal alpha of one is not enough:
        // the base owner above discarded the sky until this explicit native
        // transaction bit is set. Once set, the sRGB attachment decodes the
        // vintage HDRI exactly once and transfers its linear color unlit.
        base_scene.constants.sky[0] = 1;
        auto base_with_hdri = renderer->renderBaseLighting(
            base_scene, &error);
        INFO(error);
        REQUIRE(base_with_hdri);
        std::array<std::uint8_t, 32 * 32 * 4> base_hdri_pixels{};
        REQUIRE(base_with_hdri->colorTexture(0)->readback(
            *device, 0, 0, {}, base_hdri_pixels.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(
                  base_hdri_pixels[outside + 0]) - 128) <= 1);
        CHECK(std::abs(static_cast<int>(
                  base_hdri_pixels[outside + 1]) - 64) <= 1);
        CHECK(std::abs(static_cast<int>(
                  base_hdri_pixels[outside + 2]) - 191) <= 1);
        CHECK(base_hdri_pixels[outside + 3] == 0);
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(base_hdri_pixels[center + channel] ==
                  base_pixels[center + channel]);
        }

        // Layer the stars again before base transfer. Their additive green
        // normal channel is the reference SKIP_ATMOS value while red, blue
        // and alpha retain the WindLight family marker.
        REQUIRE(renderer->compositeWindLightSky(
            *pbr_gbuffer, windlight_scene, &error));
        REQUIRE(renderer->compositeWindLightStars(
            *pbr_gbuffer, star_scene, &error));
        INFO(error);
        base_scene.constants.sky[2] = 1;
        base_scene.constants.sky_transfer[0] = 2.f;
        auto base_with_windlight = renderer->renderBaseLighting(
            base_scene, &error);
        INFO(error);
        REQUIRE(base_with_windlight);
        std::array<std::uint8_t, 32 * 32 * 4>
            base_windlight_pixels{};
        REQUIRE(base_with_windlight->colorTexture(0)->readback(
            *device, 0, 0, {}, base_windlight_pixels.data(),
            32 * 4, &error));
        INFO(error);
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            const float expected_linear = std::clamp(
                srgb_to_linear(
                    star_albedo[outside + channel] / 255.f) * 2.f,
                0.f, 1.f);
            const int expected = static_cast<int>(std::lround(
                expected_linear * 255.f));
            CHECK(std::abs(static_cast<int>(
                      base_windlight_pixels[outside + channel]) -
                  expected) <= 1);
            CHECK(base_windlight_pixels[center + channel] ==
                  base_pixels[center + channel]);
        }
        CHECK(base_windlight_pixels[outside + 3] == 0);

        // Family 2 decodes the partial split per pixel: the HDRI marker stays
        // linear and unscaled, while the WindLight marker receives the exact
        // display decode and sky_hdr_scale.
        base_scene.gbuffer = split_gbuffer.get();
        base_scene.constants.sky[2] = 2;
        auto base_with_split = renderer->renderBaseLighting(
            base_scene, &error);
        INFO(error);
        REQUIRE(base_with_split);
        std::array<std::uint8_t, 32 * 32 * 4> base_split_pixels{};
        REQUIRE(base_with_split->colorTexture(0)->readback(
            *device, 0, 0, {}, base_split_pixels.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(
                  base_split_pixels[split_left + 0]) - 128) <= 1);
        CHECK(std::abs(static_cast<int>(
                  base_split_pixels[split_left + 1]) - 64) <= 1);
        CHECK(std::abs(static_cast<int>(
                  base_split_pixels[split_left + 2]) - 191) <= 1);
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            const float expected_linear = std::clamp(
                srgb_to_linear(
                    windlight_albedo[split_right + channel] / 255.f) *
                    2.f,
                0.f, 1.f);
            const int expected = static_cast<int>(std::lround(
                expected_linear * 255.f));
            CHECK(std::abs(static_cast<int>(
                      base_split_pixels[split_right + channel]) -
                  expected) <= 1);
            CHECK(base_split_pixels[center + channel] ==
                  base_pixels[center + channel]);
        }
        CHECK(base_split_pixels[split_left + 3] == 0);
        CHECK(base_split_pixels[split_right + 3] == 0);
        base_scene.gbuffer = pbr_gbuffer.get();

        REQUIRE(renderer->compositeHDRISky(
            *pbr_gbuffer, sky_scene, &error));
        INFO(error);
        base_scene.constants.sky[0] = 0;
        base_scene.constants.sky[2] = 0;
        base_scene.constants.sky_transfer[0] = 1.f;

        // Finish the ordinary probe result the same way as the deferred GLSL
        // owner. A 0.8-gloss PBR surface reads the hero probe at LOD 0.8:
        // its two-level red-to-blue cube therefore raises blue over the
        // ordinary green probe. The declared heroMaxLod also proves that an
        // incomplete glossiest-quarter mip family fails before encoding.
        const std::array<std::uint8_t, 4> glossy_pbr_orm{{
            255, 51, 255, 0,
        }};
        const std::array<std::uint16_t, 4> glossy_pbr_normal{{
            32768, 32768, 32896, 43908,
        }};
        auto glossy_upload = device->makeCommandBuffer(
            "Alchemy glossy base-light G-buffer upload", &error);
        INFO(error);
        REQUIRE(glossy_upload);
        REQUIRE(specular->upload(
            *glossy_upload, 0, 0, {}, glossy_pbr_orm.data(), 4,
            &error));
        REQUIRE(normal->upload(
            *glossy_upload, 0, 0, {}, glossy_pbr_normal.data(), 8,
            &error));
        REQUIRE(glossy_upload->commitAndWait(&error));
        INFO(error);
        auto glossy_gbuffer = renderer->render(gbuffer_scene, &error);
        INFO(error);
        REQUIRE(glossy_gbuffer);

        auto restore_pbr_upload = device->makeCommandBuffer(
            "Alchemy restore PBR base-light G-buffer upload", &error);
        INFO(error);
        REQUIRE(restore_pbr_upload);
        REQUIRE(specular->upload(
            *restore_pbr_upload, 0, 0, {}, pbr_orm.data(), 4, &error));
        REQUIRE(normal->upload(
            *restore_pbr_upload, 0, 0, {}, pbr_normal.data(), 8,
            &error));
        REQUIRE(restore_pbr_upload->commitAndWait(&error));
        INFO(error);

        base_scene.gbuffer = glossy_gbuffer.get();
        base_scene.constants.lighting[0] = 0.f;
        base_scene.constants.lighting[1] = 0.f;
        auto glossy_ordinary = renderer->renderBaseLighting(
            base_scene, &error);
        INFO(error);
        REQUIRE(glossy_ordinary);
        std::array<std::uint8_t, 32 * 32 * 4> glossy_ordinary_pixels{};
        REQUIRE(glossy_ordinary->colorTexture(0)->readback(
            *device, 0, 0, {}, glossy_ordinary_pixels.data(), 32 * 4,
            &error));
        INFO(error);

        ALMetalTextureDescriptor base_hero_descriptor;
        base_hero_descriptor.type = ALMetalTextureType::texture_cube;
        base_hero_descriptor.format = ALMetalPixelFormat::rgba8_unorm;
        base_hero_descriptor.width = 2;
        base_hero_descriptor.height = 2;
        base_hero_descriptor.mipmap_level_count = 2;
        base_hero_descriptor.storage = ALMetalStorageMode::private_gpu;
        base_hero_descriptor.usage = ALMetalTextureUsage::shader_read;
        base_hero_descriptor.label =
            "Alchemy base-light hero-probe mip family";
        auto base_hero_texture = ALMetalTexture::create(
            *device, base_hero_descriptor, &error);
        INFO(error);
        REQUIRE(base_hero_texture);
        const std::array<std::uint8_t, 2 * 2 * 4> red_hero_mip{{
            255, 0, 0, 255, 255, 0, 0, 255,
            255, 0, 0, 255, 255, 0, 0, 255,
        }};
        const std::array<std::uint8_t, 4> blue_hero_mip{{
            0, 0, 255, 255,
        }};
        auto base_hero_upload = device->makeCommandBuffer(
            "Alchemy base-light hero-probe upload", &error);
        INFO(error);
        REQUIRE(base_hero_upload);
        for (std::uint32_t face = 0; face < 6; ++face)
        {
            REQUIRE(base_hero_texture->upload(
                *base_hero_upload, 0, face, {}, red_hero_mip.data(),
                2 * 4, &error));
            REQUIRE(base_hero_texture->upload(
                *base_hero_upload, 1, face, {}, blue_hero_mip.data(),
                4, &error));
        }
        REQUIRE(base_hero_upload->commitAndWait(&error));
        INFO(error);

        ALMetalWorldHeroProbe base_hero;
        base_hero.radiance_texture = base_hero_texture.get();
        base_hero.constants.clip_plane[3] = 1.f;
        base_hero.constants.config[1] = 1;
        base_hero.constants.config[2] = 4;
        base_scene.hero_probe = &base_hero;
        auto glossy_hero = renderer->renderBaseLighting(base_scene, &error);
        INFO(error);
        REQUIRE(glossy_hero);
        std::array<std::uint8_t, 32 * 32 * 4> glossy_hero_pixels{};
        REQUIRE(glossy_hero->colorTexture(0)->readback(
            *device, 0, 0, {}, glossy_hero_pixels.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(glossy_hero_pixels[center + 2] >
              glossy_ordinary_pixels[center + 2]);

        base_hero.constants.config[2] = 8;
        error.clear();
        CHECK_FALSE(renderer->renderBaseLighting(base_scene, &error));
        CHECK(error == "Metal world base-light hero probe is invalid");
        error.clear();
        base_hero.constants.config[2] = 4;
        base_scene.hero_probe = nullptr;

        // A uniform hero cube only proves that hero sampling changes the
        // result; it cannot catch a wrong face or row convention. Exercise
        // the production base-light consumer with a fully metallic,
        // glossiness-one surface and an asymmetric cube. In the GL cube
        // convention used by the viewer, +Y within the +Z face addresses
        // its first stored rows. A 90-degree environment rotation then maps
        // the same center reflection onto +X.
        const std::array<std::uint8_t, 4> oriented_pbr_orm{{
            255, 0, 255, 0,
        }};
        auto oriented_gbuffer_upload = device->makeCommandBuffer(
            "Alchemy oriented hero-consumer G-buffer upload", &error);
        INFO(error);
        REQUIRE(oriented_gbuffer_upload);
        REQUIRE(specular->upload(
            *oriented_gbuffer_upload, 0, 0, {},
            oriented_pbr_orm.data(), 4, &error));
        REQUIRE(normal->upload(
            *oriented_gbuffer_upload, 0, 0, {},
            glossy_pbr_normal.data(), 8, &error));
        REQUIRE(oriented_gbuffer_upload->commitAndWait(&error));
        INFO(error);
        auto oriented_gbuffer = renderer->render(gbuffer_scene, &error);
        INFO(error);
        REQUIRE(oriented_gbuffer);

        auto oriented_gbuffer_restore = device->makeCommandBuffer(
            "Alchemy restore oriented hero-consumer G-buffer upload",
            &error);
        INFO(error);
        REQUIRE(oriented_gbuffer_restore);
        REQUIRE(specular->upload(
            *oriented_gbuffer_restore, 0, 0, {}, pbr_orm.data(), 4,
            &error));
        REQUIRE(normal->upload(
            *oriented_gbuffer_restore, 0, 0, {}, pbr_normal.data(), 8,
            &error));
        REQUIRE(oriented_gbuffer_restore->commitAndWait(&error));
        INFO(error);

        ALMetalTextureDescriptor oriented_hero_descriptor;
        oriented_hero_descriptor.type = ALMetalTextureType::texture_cube;
        oriented_hero_descriptor.format = ALMetalPixelFormat::rgba8_unorm;
        oriented_hero_descriptor.width = 4;
        oriented_hero_descriptor.height = 4;
        oriented_hero_descriptor.mipmap_level_count = 1;
        oriented_hero_descriptor.storage =
            ALMetalStorageMode::private_gpu;
        oriented_hero_descriptor.usage = ALMetalTextureUsage::shader_read;
        oriented_hero_descriptor.label =
            "Alchemy asymmetric base-light hero cube";
        auto oriented_hero_texture = ALMetalTexture::create(
            *device, oriented_hero_descriptor, &error);
        INFO(error);
        REQUIRE(oriented_hero_texture);

        const std::array<std::array<std::uint8_t, 4>, 6>
            oriented_face_colors{{
                {{255, 0, 0, 255}},
                {{0, 255, 255, 255}},
                {{255, 255, 0, 255}},
                {{255, 0, 255, 255}},
                {{0, 255, 0, 255}},
                {{255, 255, 255, 255}},
            }};
        std::array<std::array<std::uint8_t, 4 * 4 * 4>, 6>
            oriented_faces{};
        for (std::uint32_t face = 0; face < 6; ++face)
        {
            for (std::uint32_t y = 0; y < 4; ++y)
            {
                const std::array<std::uint8_t, 4> color =
                    face == 4 && y >= 2
                        ? std::array<std::uint8_t, 4>{{0, 0, 255, 255}}
                        : oriented_face_colors[face];
                for (std::uint32_t x = 0; x < 4; ++x)
                {
                    const std::size_t texel = (y * 4 + x) * 4;
                    std::copy(color.begin(), color.end(),
                              oriented_faces[face].begin() + texel);
                }
            }
        }
        auto oriented_hero_upload = device->makeCommandBuffer(
            "Alchemy asymmetric base-light hero upload", &error);
        INFO(error);
        REQUIRE(oriented_hero_upload);
        for (std::uint32_t face = 0; face < 6; ++face)
        {
            REQUIRE(oriented_hero_texture->upload(
                *oriented_hero_upload, 0, face, {},
                oriented_faces[face].data(), 4 * 4, &error));
        }
        REQUIRE(oriented_hero_upload->commitAndWait(&error));
        INFO(error);

        ALMetalWorldHeroProbe oriented_hero;
        oriented_hero.radiance_texture = oriented_hero_texture.get();
        oriented_hero.constants.hero_sphere[3] = 100.f;
        oriented_hero.constants.clip_plane[3] = 1.f;
        oriented_hero.constants.config[0] = 1;
        oriented_hero.constants.config[1] = 1;
        oriented_hero.constants.config[2] = 0;
        base_scene.gbuffer = oriented_gbuffer.get();
        base_scene.hero_probe = &oriented_hero;

        auto oriented_identity = renderer->renderBaseLighting(
            base_scene, &error);
        INFO(error);
        REQUIRE(oriented_identity);
        std::array<std::uint8_t, 32 * 32 * 4>
            oriented_identity_pixels{};
        REQUIRE(oriented_identity->colorTexture(0)->readback(
            *device, 0, 0, {}, oriented_identity_pixels.data(),
            32 * 4, &error));
        INFO(error);
        const std::size_t positive_y = (20 * 32 + 16) * 4;
        const std::size_t negative_y = (11 * 32 + 16) * 4;
        CHECK(oriented_identity_pixels[positive_y + 1] >
              oriented_identity_pixels[positive_y + 2]);
        CHECK(oriented_identity_pixels[negative_y + 2] >
              oriented_identity_pixels[negative_y + 1]);

        std::fill(&base_probes.constants.env_matrix[0][0],
                  &base_probes.constants.env_matrix[0][0] + 12, 0.f);
        base_probes.constants.env_matrix[0][2] = -1.f;
        base_probes.constants.env_matrix[1][1] = 1.f;
        base_probes.constants.env_matrix[2][0] = 1.f;
        auto oriented_rotated = renderer->renderBaseLighting(
            base_scene, &error);
        INFO(error);
        REQUIRE(oriented_rotated);
        std::array<std::uint8_t, 32 * 32 * 4>
            oriented_rotated_pixels{};
        REQUIRE(oriented_rotated->colorTexture(0)->readback(
            *device, 0, 0, {}, oriented_rotated_pixels.data(),
            32 * 4, &error));
        INFO(error);
        CHECK(oriented_rotated_pixels[center + 0] >
              oriented_rotated_pixels[center + 1]);
        CHECK(oriented_rotated_pixels[center + 0] >
              oriented_rotated_pixels[center + 2]);

        std::fill(&base_probes.constants.env_matrix[0][0],
                  &base_probes.constants.env_matrix[0][0] + 12, 0.f);
        base_probes.constants.env_matrix[0][0] = 1.f;
        base_probes.constants.env_matrix[1][1] = 1.f;
        base_probes.constants.env_matrix[2][2] = 1.f;
        base_scene.gbuffer = pbr_gbuffer.get();
        base_scene.hero_probe = nullptr;

        // The opaque SSR finish uses the same 0.567 gloss threshold and GGX
        // dominant ray as reflectionProbeF. Turn the surface toward the view,
        // arrange a first-step red history hit, and require that hit to raise
        // red over the ordinary-probe-only result. Incomplete paired history
        // remains fail-closed.
        const std::array<std::uint8_t, 4> glossy_legacy_specular{{
            255, 255, 255, 204,
        }};
        const std::array<std::uint16_t, 4> reverse_legacy_normal{{
            65535, 65535, 65535, 22282,
        }};
        auto ssr_gbuffer_upload = device->makeCommandBuffer(
            "Alchemy base-light SSR G-buffer upload", &error);
        INFO(error);
        REQUIRE(ssr_gbuffer_upload);
        REQUIRE(specular->upload(
            *ssr_gbuffer_upload, 0, 0, {},
            glossy_legacy_specular.data(), 4,
            &error));
        REQUIRE(normal->upload(
            *ssr_gbuffer_upload, 0, 0, {}, reverse_legacy_normal.data(), 8,
            &error));
        REQUIRE(ssr_gbuffer_upload->commitAndWait(&error));
        INFO(error);
        auto ssr_gbuffer = renderer->render(gbuffer_scene, &error);
        INFO(error);
        REQUIRE(ssr_gbuffer);

        auto ssr_restore_upload = device->makeCommandBuffer(
            "Alchemy restore base-light SSR inputs", &error);
        INFO(error);
        REQUIRE(ssr_restore_upload);
        REQUIRE(specular->upload(
            *ssr_restore_upload, 0, 0, {}, pbr_orm.data(), 4, &error));
        REQUIRE(normal->upload(
            *ssr_restore_upload, 0, 0, {}, pbr_normal.data(), 8,
            &error));
        REQUIRE(ssr_restore_upload->commitAndWait(&error));
        INFO(error);

        base_scene.gbuffer = ssr_gbuffer.get();
        auto no_ssr = renderer->renderBaseLighting(base_scene, &error);
        INFO(error);
        REQUIRE(no_ssr);
        std::array<std::uint8_t, 32 * 32 * 4> no_ssr_pixels{};
        REQUIRE(no_ssr->colorTexture(0)->readback(
            *device, 0, 0, {}, no_ssr_pixels.data(), 32 * 4, &error));
        INFO(error);

        ALMetalWorldScreenSpaceReflections invalid_base_ssr;
        invalid_base_ssr.constants.config[1] = 1;
        base_scene.screen_space_reflections = &invalid_base_ssr;
        error.clear();
        CHECK_FALSE(renderer->renderBaseLighting(base_scene, &error));
        CHECK(error ==
              "Metal world base-light screen-space reflections are invalid");
        error.clear();

        ALMetalTextureDescriptor base_ssr_color_descriptor;
        base_ssr_color_descriptor.format = ALMetalPixelFormat::rgba8_unorm;
        base_ssr_color_descriptor.width = 1;
        base_ssr_color_descriptor.height = 1;
        base_ssr_color_descriptor.storage = ALMetalStorageMode::private_gpu;
        base_ssr_color_descriptor.usage = ALMetalTextureUsage::shader_read;
        base_ssr_color_descriptor.label =
            "Alchemy base-light SSR scene color";
        auto base_ssr_color = ALMetalTexture::create(
            *device, base_ssr_color_descriptor, &error);
        INFO(error);
        REQUIRE(base_ssr_color);
        ALMetalTextureDescriptor base_ssr_depth_descriptor =
            base_ssr_color_descriptor;
        base_ssr_depth_descriptor.format = ALMetalPixelFormat::r32_float;
        base_ssr_depth_descriptor.label =
            "Alchemy base-light SSR scene depth";
        auto base_ssr_depth = ALMetalTexture::create(
            *device, base_ssr_depth_descriptor, &error);
        INFO(error);
        REQUIRE(base_ssr_depth);
        const std::array<std::uint8_t, 4> red_ssr{{255, 0, 0, 255}};
        const float ssr_hit_depth = 0.5f;
        auto base_ssr_upload = device->makeCommandBuffer(
            "Alchemy base-light SSR history upload", &error);
        INFO(error);
        REQUIRE(base_ssr_upload);
        REQUIRE(base_ssr_color->upload(
            *base_ssr_upload, 0, 0, {}, red_ssr.data(), 4, &error));
        REQUIRE(base_ssr_depth->upload(
            *base_ssr_upload, 0, 0, {}, &ssr_hit_depth, sizeof(float),
            &error));
        REQUIRE(base_ssr_upload->commitAndWait(&error));
        INFO(error);

        ALMetalWorldScreenSpaceReflections base_ssr;
        base_ssr.scene_color = base_ssr_color.get();
        base_ssr.scene_depth = base_ssr_depth.get();
        for (std::size_t axis = 0; axis < 4; ++axis)
        {
            base_ssr.constants.projection[axis * 4 + axis] = 1.f;
            base_ssr.constants.inverse_projection[axis * 4 + axis] = 1.f;
            base_ssr.constants.inverse_modelview_delta[axis * 4 + axis] =
                1.f;
        }
        base_ssr.constants.inverse_projection[14] = -0.4f;
        base_ssr.constants.screen[0] = 32.f;
        base_ssr.constants.screen[1] = 32.f;
        base_ssr.constants.screen[2] = 32.f;
        base_ssr.constants.trace[0] = 4.f;
        base_ssr.constants.trace[1] = 0.1f;
        base_ssr.constants.trace[2] = 0.2f;
        base_ssr.constants.trace[3] = 0.001f;
        base_ssr.constants.sampling[0] = 1.f;
        base_ssr.constants.sampling[1] = 1.6f;
        base_ssr.constants.config[1] = 1;
        base_scene.screen_space_reflections = &base_ssr;
        auto with_ssr = renderer->renderBaseLighting(base_scene, &error);
        INFO(error);
        REQUIRE(with_ssr);
        std::array<std::uint8_t, 32 * 32 * 4> with_ssr_pixels{};
        REQUIRE(with_ssr->colorTexture(0)->readback(
            *device, 0, 0, {}, with_ssr_pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(with_ssr_pixels[center + 0] > no_ssr_pixels[center + 0]);
        base_scene.screen_space_reflections = nullptr;
        base_scene.gbuffer = pbr_gbuffer.get();
        base_scene.constants.lighting[0] = 1.f;
        base_scene.constants.lighting[1] = 1.f;

        std::array<std::uint8_t, 32 * 32 * 2> occluded_light_map{};
        auto occluded_upload = device->makeCommandBuffer(
            "Alchemy occluded base-light map upload", &error);
        INFO(error);
        REQUIRE(occluded_upload);
        REQUIRE(light_map->upload(
            *occluded_upload, 0, 0, {}, occluded_light_map.data(),
            32 * 2, &error));
        REQUIRE(occluded_upload->commitAndWait(&error));
        INFO(error);
        base_scene.constants.config[3] = 1;
        auto base_occluded = renderer->renderBaseLighting(
            base_scene, &error);
        INFO(error);
        REQUIRE(base_occluded);
        std::array<std::uint8_t, 32 * 32 * 4> base_occluded_pixels{};
        REQUIRE(base_occluded->colorTexture(0)->readback(
            *device, 0, 0, {}, base_occluded_pixels.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(base_occluded_pixels[center + 0] <
              base_pixels[center + 0]);
        CHECK(base_occluded_pixels[center + 1] <
              base_pixels[center + 1]);
        CHECK(base_occluded_pixels[center + 2] <
              base_pixels[center + 2]);

        auto restored_upload = device->makeCommandBuffer(
            "Alchemy restored base-light map upload", &error);
        INFO(error);
        REQUIRE(restored_upload);
        REQUIRE(light_map->upload(
            *restored_upload, 0, 0, {}, full_light_map.data(),
            32 * 2, &error));
        REQUIRE(restored_upload->commitAndWait(&error));
        INFO(error);

        base_scene.constants.config[3] = 0;
        base_scene.gbuffer = pbr_reverse_gbuffer.get();
        base_scene.constants.inverse_projection[10] = -1.f;
        base_scene.constants.config[0] = 1;
        auto base_reverse = renderer->renderBaseLighting(
            base_scene, &error);
        INFO(error);
        REQUIRE(base_reverse);
        std::array<std::uint8_t, 32 * 32 * 4> base_reverse_pixels{};
        REQUIRE(base_reverse->colorTexture(0)->readback(
            *device, 0, 0, {}, base_reverse_pixels.data(), 32 * 4,
            &error));
        INFO(error);
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            CHECK(std::abs(static_cast<int>(
                      base_reverse_pixels[center + channel]) -
                  static_cast<int>(base_pixels[center + channel])) <= 1);
        }

        base_scene.gbuffer = gbuffer.get();
        base_scene.constants.inverse_projection[10] = 1.f;
        base_scene.constants.config[0] = 0;
        base_scene.constants.atmos_amblit[0] = 0.25f;
        base_scene.constants.atmos_amblit[1] = 0.25f;
        base_scene.constants.atmos_amblit[2] = 0.25f;
        auto base_legacy = renderer->renderBaseLighting(
            base_scene, &error);
        INFO(error);
        REQUIRE(base_legacy);
        std::array<std::uint8_t, 32 * 32 * 4> base_legacy_pixels{};
        REQUIRE(base_legacy->colorTexture(0)->readback(
            *device, 0, 0, {}, base_legacy_pixels.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(base_legacy_pixels[center + 0] > 0);
        CHECK(base_legacy_pixels[center + 1] > 0);
        CHECK(base_legacy_pixels[center + 2] > 0);

        base_scene.constants.config[1] = 1;
        base_scene.constants.atmos_sunlit[0] = 1.f;
        base_scene.constants.atmos_sunlit[1] = 1.f;
        base_scene.constants.atmos_sunlit[2] = 1.f;
        auto base_classic = renderer->renderBaseLighting(
            base_scene, &error);
        INFO(error);
        REQUIRE(base_classic);
        std::array<std::uint8_t, 32 * 32 * 4> base_classic_pixels{};
        REQUIRE(base_classic->colorTexture(0)->readback(
            *device, 0, 0, {}, base_classic_pixels.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(base_classic_pixels[center + 0] > 0);
        CHECK(base_classic_pixels[center + 1] > 0);
        CHECK(base_classic_pixels[center + 2] > 0);

        ALMetalWorldBaseLightingScene invalid_base_scene;
        error.clear();
        CHECK_FALSE(renderer->renderBaseLighting(
            invalid_base_scene, &error));
        CHECK(error == "Metal world base-light scene is incomplete");

        // The same owner must preserve the HDR screen format. A zero R11G11B10
        // emissive plane is sufficient because local point lights do not add
        // the emissive attachment, but its format is part of the G-buffer ABI.
        auto hdr_emissive = make_texture(
            ALMetalPixelFormat::rg11b10_float,
            "Alchemy local-light HDR G-buffer emissive");
        const std::uint32_t zero_emissive = 0;
        auto hdr_upload = device->makeCommandBuffer(
            "Alchemy local-light HDR emissive upload", &error);
        INFO(error);
        REQUIRE(hdr_upload);
        REQUIRE(hdr_emissive->upload(
            *hdr_upload, 0, 0, {}, &zero_emissive,
            sizeof(zero_emissive), &error));
        REQUIRE(hdr_upload->commitAndWait(&error));
        INFO(error);
        batch.impostor_textures[3] = hdr_emissive.get();
        gbuffer_scene.hdr = true;
        auto hdr_gbuffer = renderer->render(gbuffer_scene, &error);
        INFO(error);
        REQUIRE(hdr_gbuffer);
        sky_scene.hdr = true;
        REQUIRE(renderer->compositeHDRISky(
            *hdr_gbuffer, sky_scene, &error));
        INFO(error);
        auto hdr_split_gbuffer = renderer->render(
            gbuffer_scene, &error);
        INFO(error);
        REQUIRE(hdr_split_gbuffer);
        windlight_scene.hdr = true;
        REQUIRE(renderer->compositeWindLightSky(
            *hdr_split_gbuffer, windlight_scene, &error));
        sky_scene.horizontal_fraction = 0.5f;
        REQUIRE(renderer->compositeHDRISky(
            *hdr_split_gbuffer, sky_scene, &error));
        INFO(error);
        std::array<std::uint32_t, 32 * 32> hdr_split_emissive{};
        std::array<std::uint16_t, 32 * 32 * 4> hdr_split_normal{};
        REQUIRE(hdr_split_gbuffer->colorTexture(3)->readback(
            *device, 0, 0, {}, hdr_split_emissive.data(), 32 * 4,
            &error));
        REQUIRE(hdr_split_gbuffer->colorTexture(2)->readback(
            *device, 0, 0, {}, hdr_split_normal.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(hdr_split_emissive[split_left / 4] != 0);
        CHECK(hdr_split_emissive[split_right / 4] != 0);
        CHECK(hdr_split_normal[split_left + 3] == 65535);
        CHECK(hdr_split_normal[split_right + 3] == 0);
        sky_scene.horizontal_fraction = 1.f;
        base_scene.gbuffer = hdr_gbuffer.get();
        base_scene.hdr = true;
        base_scene.hero_probe = nullptr;
        base_scene.screen_space_reflections = nullptr;
        base_scene.constants.inverse_projection[10] = 1.f;
        base_scene.constants.config[0] = 0;
        base_scene.constants.config[1] = 0;
        base_scene.constants.config[3] = 0;
        base_scene.constants.sky[0] = 1;
        base_scene.constants.sky[1] = 1;
        auto hdr_base = renderer->renderBaseLighting(base_scene, &error);
        INFO(error);
        REQUIRE(hdr_base);
        std::array<std::uint16_t, 32 * 32 * 4> hdr_base_pixels{};
        REQUIRE(hdr_base->colorTexture(0)->readback(
            *device, 0, 0, {}, hdr_base_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(hdr_base_pixels[outside + 0] >= 0x37e0);
        CHECK(hdr_base_pixels[outside + 0] <= 0x3820);
        CHECK(hdr_base_pixels[outside + 1] >= 0x33e0);
        CHECK(hdr_base_pixels[outside + 1] <= 0x3420);
        CHECK(hdr_base_pixels[outside + 2] >= 0x39c0);
        CHECK(hdr_base_pixels[outside + 2] <= 0x3a40);
        CHECK(hdr_base_pixels[outside + 3] == 0);

        base_scene.gbuffer = hdr_split_gbuffer.get();
        base_scene.constants.sky[2] = 2;
        base_scene.constants.sky_transfer[0] = 2.f;
        auto hdr_split_base = renderer->renderBaseLighting(
            base_scene, &error);
        INFO(error);
        REQUIRE(hdr_split_base);
        std::array<std::uint16_t, 32 * 32 * 4>
            hdr_split_base_pixels{};
        REQUIRE(hdr_split_base->colorTexture(0)->readback(
            *device, 0, 0, {}, hdr_split_base_pixels.data(),
            32 * 8, &error));
        INFO(error);
        CHECK(hdr_split_base_pixels[split_left + 0] >= 0x37e0);
        CHECK(hdr_split_base_pixels[split_left + 0] <= 0x3820);
        CHECK(hdr_split_base_pixels[split_left + 1] >= 0x33e0);
        CHECK(hdr_split_base_pixels[split_left + 1] <= 0x3420);
        CHECK(hdr_split_base_pixels[split_left + 2] >= 0x39c0);
        CHECK(hdr_split_base_pixels[split_left + 2] <= 0x3a40);
        CHECK(hdr_split_base_pixels[split_right + 0] > 0);
        CHECK(hdr_split_base_pixels[split_right + 1] > 0);
        CHECK(hdr_split_base_pixels[split_right + 2] > 0);
        base_scene.gbuffer = hdr_gbuffer.get();
        base_scene.constants.sky[2] = 0;
        base_scene.constants.sky_transfer[0] = 1.f;

        // Exercise the HDR WindLight variant: it retains display-encoded
        // color in R11G11B10F, then the base owner decodes and scales it.
        REQUIRE(renderer->compositeWindLightSky(
            *hdr_gbuffer, windlight_scene, &error));
        star_scene.hdr = true;
        REQUIRE(renderer->compositeWindLightStars(
            *hdr_gbuffer, star_scene, &error));
        std::array<std::uint32_t, 32 * 32> hdr_body_before{};
        REQUIRE(hdr_gbuffer->colorTexture(3)->readback(
            *device, 0, 0, {}, hdr_body_before.data(), 32 * 4,
            &error));
        body_scene.hdr = true;
        REQUIRE(renderer->compositeWindLightHeavenlyBodies(
            *hdr_gbuffer, body_scene, &error));
        INFO(error);
        std::array<std::uint32_t, 32 * 32> hdr_body_after{};
        REQUIRE(hdr_gbuffer->colorTexture(3)->readback(
            *device, 0, 0, {}, hdr_body_after.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(hdr_body_after[outside / 4] !=
              hdr_body_before[outside / 4]);
        CHECK(hdr_body_after[center / 4] ==
              hdr_body_before[center / 4]);
        meteor_scene.hdr = true;
        REQUIRE(renderer->compositeWindLightMeteors(
            *hdr_gbuffer, meteor_scene, &error));
        INFO(error);
        std::array<std::uint32_t, 32 * 32> hdr_meteor_after{};
        REQUIRE(hdr_gbuffer->colorTexture(3)->readback(
            *device, 0, 0, {}, hdr_meteor_after.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(hdr_meteor_after[outside / 4] !=
              hdr_body_after[outside / 4]);
        CHECK(hdr_meteor_after[center / 4] ==
              hdr_body_after[center / 4]);
        aurora_scene.hdr = true;
        REQUIRE(renderer->compositeWindLightAurora(
            *hdr_gbuffer, aurora_scene, &error));
        INFO(error);
        std::array<std::uint32_t, 32 * 32> hdr_aurora_after{};
        REQUIRE(hdr_gbuffer->colorTexture(3)->readback(
            *device, 0, 0, {}, hdr_aurora_after.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(hdr_aurora_after != hdr_meteor_after);
        CHECK(hdr_aurora_after[center / 4] ==
              hdr_meteor_after[center / 4]);
        cloud_scene.hdr = true;
        REQUIRE(renderer->compositeWindLightClouds(
            *hdr_gbuffer, cloud_scene, &error));
        INFO(error);
        std::array<std::uint32_t, 32 * 32> hdr_cloud_after{};
        REQUIRE(hdr_gbuffer->colorTexture(3)->readback(
            *device, 0, 0, {}, hdr_cloud_after.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(hdr_cloud_after[outside / 4] !=
              hdr_aurora_after[outside / 4]);
        CHECK(hdr_cloud_after[center / 4] ==
              hdr_aurora_after[center / 4]);
        std::array<std::uint16_t, 32 * 32 * 4> hdr_windlight_normal{};
        REQUIRE(hdr_gbuffer->colorTexture(2)->readback(
            *device, 0, 0, {}, hdr_windlight_normal.data(),
            32 * 8, &error));
        INFO(error);
        CHECK(hdr_windlight_normal[outside + 0] == 0);
        CHECK(hdr_windlight_normal[outside + 1] == 65535);
        CHECK(hdr_windlight_normal[outside + 2] == 0);
        CHECK(hdr_windlight_normal[outside + 3] == 0);
        base_scene.constants.sky[2] = 1;
        base_scene.constants.sky_transfer[0] = 2.f;
        auto hdr_windlight_base = renderer->renderBaseLighting(
            base_scene, &error);
        INFO(error);
        REQUIRE(hdr_windlight_base);
        std::array<std::uint16_t, 32 * 32 * 4>
            hdr_windlight_pixels{};
        REQUIRE(hdr_windlight_base->colorTexture(0)->readback(
            *device, 0, 0, {}, hdr_windlight_pixels.data(),
            32 * 8, &error));
        INFO(error);
        CHECK(hdr_windlight_pixels[outside + 0] > 0);
        CHECK(hdr_windlight_pixels[outside + 1] > 0);
        CHECK(hdr_windlight_pixels[outside + 2] > 0);
        CHECK(hdr_windlight_pixels[outside + 3] == 0);
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(hdr_windlight_pixels[center + channel] ==
                  hdr_base_pixels[center + channel]);
        }
        base_scene.constants.sky[2] = 0;
        base_scene.constants.sky_transfer[0] = 1.f;
        lighting_scene.gbuffer = hdr_gbuffer.get();
        lighting_scene.hdr = true;
        auto hdr = renderer->renderLocalLights(lighting_scene, &error);
        INFO(error);
        REQUIRE(hdr);
        CHECK(hdr->descriptor().colors[0].format ==
              ALMetalPixelFormat::rgba16_float);
        std::array<std::uint16_t, 32 * 32 * 4> hdr_pixels{};
        REQUIRE(hdr->colorTexture(0)->readback(
            *device, 0, 0, {}, hdr_pixels.data(), 32 * 8, &error));
        INFO(error);
        CHECK(hdr_pixels[center + 0] > 0);
        CHECK(hdr_pixels[center + 1] > 0);
        CHECK(hdr_pixels[center + 2] > 0);
        CHECK(hdr_pixels[center + 3] == 0);

        ALMetalWorldLightingCompositionScene hdr_composition_scene;
        hdr_composition_scene.base_lighting = hdr.get();
        hdr_composition_scene.local_lighting = hdr.get();
        hdr_composition_scene.projector_lighting = hdr.get();
        hdr_composition_scene.hdr = true;
        auto hdr_composed = renderer->composeLighting(
            hdr_composition_scene, &error);
        INFO(error);
        REQUIRE(hdr_composed);
        REQUIRE(hdr_composed->descriptor().colors[0].format ==
                ALMetalPixelFormat::rgba16_float);
        std::array<std::uint16_t, 32 * 32 * 4> hdr_composed_pixels{};
        REQUIRE(hdr_composed->colorTexture(0)->readback(
            *device, 0, 0, {}, hdr_composed_pixels.data(), 32 * 8,
            &error));
        INFO(error);
        CHECK(hdr_composed_pixels[center + 0] > hdr_pixels[center + 0]);
        CHECK(hdr_composed_pixels[center + 1] > hdr_pixels[center + 1]);
        CHECK(hdr_composed_pixels[center + 2] > hdr_pixels[center + 2]);
        CHECK(hdr_composed_pixels[center + 3] == 0);

        composition_scene.local_lighting = hdr.get();
        error.clear();
        CHECK_FALSE(renderer->composeLighting(
            composition_scene, &error));
        CHECK(error ==
              "Metal world lighting composition targets are incompatible");

        ALMetalWorldLightingCompositionScene invalid_composition_scene;
        error.clear();
        CHECK_FALSE(renderer->composeLighting(
            invalid_composition_scene, &error));
        CHECK(error ==
              "Metal world lighting composition is incomplete");

        ALMetalWorldProjectorLightingScene invalid_projector_scene;
        error.clear();
        CHECK_FALSE(renderer->renderProjectorLights(
            invalid_projector_scene, &error));
        CHECK(error ==
              "Metal world projector-light scene is incomplete");

        ALMetalWorldLocalLightingScene invalid_scene;
        error.clear();
        CHECK_FALSE(renderer->renderLocalLights(invalid_scene, &error));
        CHECK(error == "Metal world local-light scene is incomplete");
    }
}

TEST_CASE("almetal: native final color publishes coherent SSR history", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        auto renderer = ALMetalWorldGBufferRenderer::create(
            *device, &error);
        INFO(error);
        REQUIRE(renderer);

        ALMetalRenderTargetDescriptor source_descriptor;
        source_descriptor.width = 2;
        source_descriptor.height = 2;
        source_descriptor.colors[0].format =
            ALMetalPixelFormat::rgba8_unorm;
        source_descriptor.depth_stencil_format =
            ALMetalPixelFormat::depth32_float_stencil8;
        source_descriptor.depth_stencil_shader_read = true;
        source_descriptor.label = "Alchemy SSR-history source test";
        auto source = ALMetalRenderTarget::create(
            *device, source_descriptor, &error);
        INFO(error);
        REQUIRE(source);

        // Metal row zero is the top row. The history publisher deliberately
        // reverses it so the retained data matches glReadPixels' historical
        // lower-row-first layout consumed by the existing SSR math.
        const std::array<std::uint8_t, 16> source_pixels{{
            255,   0,   0, 255,   0, 255,   0, 255,
              0,   0, 255, 255, 255, 255, 255, 255,
        }};
        auto upload = device->makeCommandBuffer(
            "Alchemy SSR-history source upload", &error);
        INFO(error);
        REQUIRE(upload);
        id<MTLBuffer> source_staging = [nativeDevice(*device)
            newBufferWithBytes:source_pixels.data()
                      length:source_pixels.size()
                     options:MTLResourceStorageModeShared];
        REQUIRE(source_staging);
        id<MTLBlitCommandEncoder> source_blit =
            [nativeCommand(*upload) blitCommandEncoder];
        REQUIRE(source_blit);
        [source_blit copyFromBuffer:source_staging
                       sourceOffset:0
                  sourceBytesPerRow:2 * 4
                sourceBytesPerImage:source_pixels.size()
                         sourceSize:MTLSizeMake(2, 2, 1)
                          toTexture:(__bridge id<MTLTexture>)
                              source->colorTexture(0)->nativeHandle()
                   destinationSlice:0
                   destinationLevel:0
                  destinationOrigin:MTLOriginMake(0, 0, 0)];
        [source_blit endEncoding];
        REQUIRE(upload->commitAndWait(&error));
        INFO(error);

        ALMetalRenderPassConfig source_config;
        source_config.colors[0].load = ALMetalLoadAction::load;
        source_config.colors[0].store = ALMetalStoreAction::store;
        source_config.depth_load = ALMetalLoadAction::clear;
        source_config.depth_store = ALMetalStoreAction::store;
        source_config.clear_depth = 0.625;
        source_config.stencil_load = ALMetalLoadAction::clear;
        source_config.stencil_store = ALMetalStoreAction::store;
        auto source_pass = source->makeRenderPass(source_config, &error);
        auto source_command = source_pass
            ? device->makeCommandBuffer(
                  "Alchemy SSR-history source depth clear", &error)
            : nullptr;
        auto source_encoder = source_command && source_pass
            ? ALMetalRenderEncoder::begin(
                  *source_command, *source_pass,
                  "Alchemy SSR-history source depth encoder", &error)
            : nullptr;
        INFO(error);
        REQUIRE(source_encoder);
        REQUIRE(source_encoder->end(&error));
        REQUIRE(source_command->commitAndWait(&error));
        INFO(error);

        std::unique_ptr<ALMetalRenderTarget> history;
        REQUIRE(renderer->updateScreenSpaceReflectionHistory(
            *source, history, &error));
        INFO(error);
        REQUIRE(history);
        CHECK(history->descriptor().color_attachment_count == 2);
        CHECK(history->descriptor().colors[0].format ==
              ALMetalPixelFormat::rgba8_unorm);
        CHECK(history->descriptor().colors[1].format ==
              ALMetalPixelFormat::r32_float);

        std::array<std::uint8_t, 16> history_pixels{};
        std::array<float, 4> history_depth{};
        REQUIRE(history->colorTexture(0)->readback(
            *device, 0, 0, {}, history_pixels.data(), 2 * 4, &error));
        REQUIRE(history->colorTexture(1)->readback(
            *device, 0, 0, {}, history_depth.data(), 2 * sizeof(float),
            &error));
        INFO(error);
        const std::array<std::uint8_t, 16> expected_pixels{{
              0,   0, 255, 255, 255, 255, 255, 255,
            255,   0,   0, 255,   0, 255,   0, 255,
        }};
        CHECK(history_pixels == expected_pixels);
        for (float depth : history_depth)
        {
            CHECK(std::abs(depth - 0.625f) < 0.0001f);
        }

        ALMetalRenderTarget* retained_history = history.get();
        REQUIRE(renderer->updateScreenSpaceReflectionHistory(
            *source, history, &error));
        INFO(error);
        CHECK(history.get() == retained_history);
    }
}

TEST_CASE("almetal: world exposure matches the production meter and history", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        auto renderer = ALMetalWorldGBufferRenderer::create(
            *device, &error);
        INFO(error);
        REQUIRE(renderer);

        constexpr std::uint32_t width = 128;
        constexpr std::uint32_t height = 72;
        const auto make_target = [&](
            ALMetalPixelFormat format, const void* pixels,
            std::size_t bytes_per_row, const char* label)
        {
            ALMetalRenderTargetDescriptor descriptor;
            descriptor.width = width;
            descriptor.height = height;
            descriptor.colors[0].format = format;
            descriptor.label = label;
            auto target = ALMetalRenderTarget::create(
                *device, descriptor, &error);
            INFO(error);
            REQUIRE(target);
            auto upload = device->makeCommandBuffer(label, &error);
            INFO(error);
            REQUIRE(upload);
            id<MTLBuffer> staging = [nativeDevice(*device)
                newBufferWithBytes:pixels
                          length:bytes_per_row * height
                         options:MTLResourceStorageModeShared];
            REQUIRE(staging);
            id<MTLBlitCommandEncoder> blit =
                [nativeCommand(*upload) blitCommandEncoder];
            REQUIRE(blit);
            [blit copyFromBuffer:staging
                    sourceOffset:0
               sourceBytesPerRow:bytes_per_row
             sourceBytesPerImage:bytes_per_row * height
                      sourceSize:MTLSizeMake(width, height, 1)
                       toTexture:(__bridge id<MTLTexture>)
                           target->colorTexture(0)->nativeHandle()
                destinationSlice:0
                destinationLevel:0
               destinationOrigin:MTLOriginMake(0, 0, 0)];
            [blit endEncoding];
            REQUIRE(upload->commit(&error));
            INFO(error);
            return target;
        };
        const auto half_to_float = [](std::uint16_t value)
        {
            const std::uint32_t sign =
                static_cast<std::uint32_t>(value & 0x8000u) << 16;
            std::uint32_t exponent = (value >> 10) & 0x1fu;
            std::uint32_t mantissa = value & 0x03ffu;
            std::uint32_t bits = 0;
            if (exponent == 0)
            {
                if (mantissa == 0)
                {
                    bits = sign;
                }
                else
                {
                    std::int32_t unbiased = -14;
                    while ((mantissa & 0x0400u) == 0)
                    {
                        mantissa <<= 1;
                        --unbiased;
                    }
                    mantissa &= 0x03ffu;
                    bits = sign |
                        (static_cast<std::uint32_t>(unbiased + 127) << 23) |
                        (mantissa << 13);
                }
            }
            else if (exponent == 0x1fu)
            {
                bits = sign | 0x7f800000u | (mantissa << 13);
            }
            else
            {
                bits = sign | ((exponent + 112u) << 23) |
                    (mantissa << 13);
            }
            float result = 0.f;
            std::memcpy(&result, &bits, sizeof(result));
            return result;
        };

        std::vector<std::uint16_t> scene_pixels(
            width * height * 4, 0x3400u); // uniform linear 0.25
        for (std::size_t pixel = 0; pixel < width * height; ++pixel)
        {
            scene_pixels[pixel * 4 + 3] = 0x3c00u;
        }
        std::vector<std::uint32_t> normal_pixels(
            width * height, 1u << 30u); // HAS_ATMOS quantizes to alpha 1/3
        auto source = make_target(
            ALMetalPixelFormat::rgba16_float, scene_pixels.data(),
            width * 4 * sizeof(std::uint16_t),
            "Alchemy world exposure uniform source");
        auto normal = make_target(
            ALMetalPixelFormat::rgb10a2_unorm, normal_pixels.data(),
            width * sizeof(std::uint32_t),
            "Alchemy world exposure ground normal");

        ALMetalWorldExposureScene exposure_scene;
        exposure_scene.source = source.get();
        exposure_scene.normal = normal->colorTexture(0);
        exposure_scene.delta_seconds = 1.f;
        exposure_scene.metering_mode = 0;
        auto exposure = renderer->renderExposure(
            exposure_scene, &error);
        INFO(error);
        REQUIRE(exposure);
        CHECK(exposure->descriptor().width == 1);
        CHECK(exposure->descriptor().height == 1);
        CHECK(exposure->descriptor().colors[0].format ==
              ALMetalPixelFormat::rgba16_float);
        std::array<std::uint16_t, 4> exposure_pixel{};
        REQUIRE(exposure->colorTexture(0)->readback(
            *device, 0, 0, {}, exposure_pixel.data(),
            sizeof(exposure_pixel), &error));
        INFO(error);
        const float target_ev = std::log2(0.25f) - std::log2(0.18f);
        const float expected_ev = target_ev * (1.f - std::exp(-3.f));
        CHECK(std::abs(half_to_float(exposure_pixel[0]) -
                       std::exp2(-expected_ev)) < 0.002f);
        CHECK(std::abs(half_to_float(exposure_pixel[1]) -
                       expected_ev) < 0.002f);
        CHECK(std::abs(half_to_float(exposure_pixel[2]) -
                       target_ev) < 0.002f);
        const float first_ev = half_to_float(exposure_pixel[1]);

        // The second frame adapts from the first frame's half-float EV, just
        // as exposureF.glsl samples mLastExposure after its target swap.
        std::fill(scene_pixels.begin(), scene_pixels.end(), 0x3c00u);
        auto bright_source = make_target(
            ALMetalPixelFormat::rgba16_float, scene_pixels.data(),
            width * 4 * sizeof(std::uint16_t),
            "Alchemy world exposure bright source");
        exposure_scene.source = bright_source.get();
        exposure_scene.previous = exposure->colorTexture(0);
        auto adapted = renderer->renderExposure(
            exposure_scene, &error);
        INFO(error);
        REQUIRE(adapted);
        REQUIRE(adapted->colorTexture(0)->readback(
            *device, 0, 0, {}, exposure_pixel.data(),
            sizeof(exposure_pixel), &error));
        const float bright_target = -std::log2(0.18f);
        const float expected_adapted = first_ev +
            (bright_target - first_ev) * (1.f - std::exp(-3.f));
        CHECK(std::abs(half_to_float(exposure_pixel[2]) -
                       bright_target) < 0.003f);
        CHECK(std::abs(half_to_float(exposure_pixel[1]) -
                       expected_adapted) < 0.003f);

        // A main-world renderer that finishes warming after GL has already
        // adapted cannot continue from that unowned history. Its synchronized
        // restart deliberately supplies no previous texture, which means the
        // first native update advances from fixed EV 0 rather than from the
        // stale first-frame value above. Keep this asymmetric: the two
        // expected values differ, so accidentally retaining history fails.
        exposure_scene.previous = nullptr;
        auto restarted = renderer->renderExposure(
            exposure_scene, &error);
        INFO(error);
        REQUIRE(restarted);
        REQUIRE(restarted->colorTexture(0)->readback(
            *device, 0, 0, {}, exposure_pixel.data(),
            sizeof(exposure_pixel), &error));
        const float expected_restarted =
            bright_target * (1.f - std::exp(-3.f));
        CHECK(std::abs(expected_restarted - expected_adapted) > 0.01f);
        CHECK(std::abs(half_to_float(exposure_pixel[1]) -
                       expected_restarted) < 0.003f);

        // Sky weight zero removes the HDRI/skip-atmos half from the meter,
        // while weight one retains its brighter log-luminance contribution.
        for (std::uint32_t y = 0; y < height; ++y)
        {
            for (std::uint32_t x = 0; x < width; ++x)
            {
                const std::size_t pixel = y * width + x;
                const std::uint16_t value = x < width / 2
                    ? 0x3400u : 0x3c00u;
                scene_pixels[pixel * 4 + 0] = value;
                scene_pixels[pixel * 4 + 1] = value;
                scene_pixels[pixel * 4 + 2] = value;
                scene_pixels[pixel * 4 + 3] = 0x3c00u;
                normal_pixels[pixel] = x < width / 2
                    ? 1u << 30u : 0u;
            }
        }
        auto split_source = make_target(
            ALMetalPixelFormat::rgba16_float, scene_pixels.data(),
            width * 4 * sizeof(std::uint16_t),
            "Alchemy world exposure split source");
        auto split_normal = make_target(
            ALMetalPixelFormat::rgb10a2_unorm, normal_pixels.data(),
            width * sizeof(std::uint32_t),
            "Alchemy world exposure split normal");
        exposure_scene.source = split_source.get();
        exposure_scene.normal = split_normal->colorTexture(0);
        exposure_scene.previous = nullptr;
        exposure_scene.delta_seconds = 100.f;
        exposure_scene.sky_weight = 0.f;
        const std::uint64_t exposure_batch_count =
            ALMetalDevice::committedCommandBufferCount();
        REQUIRE(renderer->beginCommandBatch(
            "Alchemy exposure-history command-batch regression", &error));
        auto ground_only = renderer->renderExposure(
            exposure_scene, &error);
        INFO(error);
        REQUIRE(ground_only);
        exposure_scene.sky_weight = 1.f;
        auto sky_weighted = renderer->renderExposure(
            exposure_scene, &error);
        INFO(error);
        REQUIRE(sky_weighted);
        REQUIRE(renderer->commitCommandBatch(&error));
        INFO(error);
        CHECK(ALMetalDevice::committedCommandBufferCount() ==
              exposure_batch_count + 1);
        REQUIRE(ground_only->colorTexture(0)->readback(
            *device, 0, 0, {}, exposure_pixel.data(),
            sizeof(exposure_pixel), &error));
        CHECK(std::abs(half_to_float(exposure_pixel[2]) -
                       target_ev) < 0.002f);
        REQUIRE(sky_weighted->colorTexture(0)->readback(
            *device, 0, 0, {}, exposure_pixel.data(),
            sizeof(exposure_pixel), &error));
        // The default 10%/95% trim keeps 40% of the ground half and 45% of
        // the sky half, so this deliberately is not the untrimmed midpoint.
        const float trimmed_log_luminance = (-2.f * 0.40f) / 0.85f;
        CHECK(std::abs(half_to_float(exposure_pixel[2]) -
                       (trimmed_log_luminance - std::log2(0.18f))) <
              0.003f);

        // Display post consumes the exposure texel on-GPU. The scalar is set
        // to a deliberately wrong value so this assertion proves the dynamic
        // pipeline, rather than the legacy constant path, was selected.
        ALMetalWorldDisplayPostScene display;
        display.source = split_source.get();
        display.adapted_exposure_texture = ground_only->colorTexture(0);
        display.hdr = true;
        display.adapted_exposure = 0.f;
        display.tonemap_mix = 0.f;
        auto display_output = renderer->renderDisplayPost(display, &error);
        INFO(error);
        REQUIRE(display_output);
        std::vector<std::uint32_t> display_pixels(width * height);
        REQUIRE(display_output->colorTexture(0)->readback(
            *device, 0, 0, {}, display_pixels.data(),
            width * sizeof(std::uint32_t), &error));
        CHECK((display_pixels[0] & 0x3fffffffu) != 0u);

        ALMetalWorldExposureScene invalid;
        error.clear();
        CHECK_FALSE(renderer->renderExposure(invalid, &error));
        CHECK(error == "Metal world exposure scene is incomplete");
        invalid.source = source.get();
        invalid.normal = source->colorTexture(0);
        error.clear();
        CHECK_FALSE(renderer->renderExposure(invalid, &error));
        CHECK(error == "Metal world exposure source is incompatible");
        invalid.normal = normal->colorTexture(0);
        invalid.high_fraction = 0.f;
        error.clear();
        CHECK_FALSE(renderer->renderExposure(invalid, &error));
        CHECK(error == "Metal world exposure state is invalid");

        display.adapted_exposure_texture = source->colorTexture(0);
        error.clear();
        CHECK_FALSE(renderer->renderDisplayPost(display, &error));
        CHECK(error ==
              "Metal world display-post exposure is incompatible");
    }
}

TEST_CASE("almetal: world lens flare owns visibility history and display", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        auto renderer = ALMetalWorldGBufferRenderer::create(*device, &error);
        INFO(error);
        REQUIRE(renderer);

        constexpr std::uint32_t width = 16;
        constexpr std::uint32_t height = 12;
        const auto make_source = [&](std::uint16_t value,
                                     const char* label)
        {
            std::vector<std::uint16_t> pixels(width * height * 4, value);
            for (std::size_t pixel = 0; pixel < width * height; ++pixel)
            {
                pixels[pixel * 4 + 3] = 0x3c00u;
            }
            ALMetalRenderTargetDescriptor descriptor;
            descriptor.width = width;
            descriptor.height = height;
            descriptor.colors[0].format =
                ALMetalPixelFormat::rgba16_float;
            descriptor.label = label;
            auto target = ALMetalRenderTarget::create(
                *device, descriptor, &error);
            INFO(error);
            REQUIRE(target);
            auto upload = device->makeCommandBuffer(label, &error);
            INFO(error);
            REQUIRE(upload);
            const std::size_t row_bytes =
                width * 4 * sizeof(std::uint16_t);
            id<MTLBuffer> staging = [nativeDevice(*device)
                newBufferWithBytes:pixels.data()
                          length:pixels.size() * sizeof(std::uint16_t)
                         options:MTLResourceStorageModeShared];
            REQUIRE(staging);
            id<MTLBlitCommandEncoder> blit =
                [nativeCommand(*upload) blitCommandEncoder];
            REQUIRE(blit);
            [blit copyFromBuffer:staging
                    sourceOffset:0
               sourceBytesPerRow:row_bytes
             sourceBytesPerImage:row_bytes * height
                      sourceSize:MTLSizeMake(width, height, 1)
                       toTexture:(__bridge id<MTLTexture>)
                           target->colorTexture(0)->nativeHandle()
                destinationSlice:0
                destinationLevel:0
               destinationOrigin:MTLOriginMake(0, 0, 0)];
            [blit endEncoding];
            REQUIRE(upload->commit(&error));
            INFO(error);
            return target;
        };
        const auto make_depth = [&](double value, const char* label)
        {
            ALMetalRenderTargetDescriptor descriptor;
            descriptor.width = width;
            descriptor.height = height;
            descriptor.color_attachment_count = 0;
            descriptor.depth_stencil_format =
                ALMetalPixelFormat::depth32_float_stencil8;
            descriptor.depth_stencil_shader_read = true;
            descriptor.label = label;
            auto target = ALMetalRenderTarget::create(
                *device, descriptor, &error);
            INFO(error);
            REQUIRE(target);
            ALMetalRenderPassConfig clear;
            clear.depth_load = ALMetalLoadAction::clear;
            clear.depth_store = ALMetalStoreAction::store;
            clear.clear_depth = value;
            clear.stencil_load = ALMetalLoadAction::clear;
            clear.stencil_store = ALMetalStoreAction::store;
            auto pass = target->makeRenderPass(clear, &error);
            auto command = pass ? device->makeCommandBuffer(label, &error)
                                : nullptr;
            auto encoder = command && pass ? ALMetalRenderEncoder::begin(
                *command, *pass, label, &error) : nullptr;
            INFO(error);
            REQUIRE(encoder);
            REQUIRE(encoder->end(&error));
            REQUIRE(command->commitAndWait(&error));
            return target;
        };
        const auto half_to_float = [](std::uint16_t value)
        {
            const std::uint32_t sign =
                static_cast<std::uint32_t>(value & 0x8000u) << 16;
            std::uint32_t exponent = (value >> 10) & 0x1fu;
            std::uint32_t mantissa = value & 0x03ffu;
            std::uint32_t bits = 0;
            if (exponent == 0)
            {
                if (mantissa == 0)
                {
                    bits = sign;
                }
                else
                {
                    std::int32_t unbiased = -14;
                    while ((mantissa & 0x0400u) == 0)
                    {
                        mantissa <<= 1;
                        --unbiased;
                    }
                    mantissa &= 0x03ffu;
                    bits = sign |
                        (static_cast<std::uint32_t>(unbiased + 127) << 23) |
                        (mantissa << 13);
                }
            }
            else if (exponent == 0x1fu)
            {
                bits = sign | 0x7f800000u | (mantissa << 13);
            }
            else
            {
                bits = sign | ((exponent + 112u) << 23) |
                    (mantissa << 13);
            }
            float result = 0.f;
            std::memcpy(&result, &bits, sizeof(result));
            return result;
        };

        auto bright = make_source(0x4400u, "Alchemy flare bright source");
        auto dark = make_source(0x2e66u, "Alchemy flare display source");
        auto sky_depth = make_depth(0.0, "Alchemy flare sky depth");
        auto geometry_depth = make_depth(1.0, "Alchemy flare geometry depth");

        ALMetalWorldLensFlareStateScene state_scene;
        state_scene.source = bright.get();
        state_scene.depth_texture = sky_depth->depthStencilTexture();
        state_scene.delta_seconds = 0.25f;
        state_scene.sun_uv[0] = 0.5f;
        state_scene.sun_uv[1] = 0.5f;
        state_scene.edge_visibility = 1.f;
        state_scene.occlusion_radius = 0.1f;
        state_scene.fade_time = 0.1f;
        state_scene.reverse_z = true;
        const std::uint64_t flare_batch_count =
            ALMetalDevice::committedCommandBufferCount();
        REQUIRE(renderer->beginCommandBatch(
            "Alchemy flare-history command-batch regression", &error));
        auto visible = renderer->renderLensFlareState(state_scene, &error);
        INFO(error);
        REQUIRE(visible);
        CHECK(visible->descriptor().width == 2);
        CHECK(visible->descriptor().height == 1);
        CHECK(visible->descriptor().colors[0].format ==
              ALMetalPixelFormat::rgba16_float);
        std::array<std::uint16_t, 8> visible_pixels{};

        state_scene.previous = visible->colorTexture(0);
        state_scene.depth_texture = geometry_depth->depthStencilTexture();
        state_scene.delta_seconds = 0.1f;
        auto occluded = renderer->renderLensFlareState(state_scene, &error);
        INFO(error);
        REQUIRE(occluded);
        REQUIRE(renderer->commitCommandBatch(&error));
        INFO(error);
        CHECK(ALMetalDevice::committedCommandBufferCount() ==
              flare_batch_count + 1);
        REQUIRE(visible->colorTexture(0)->readback(
            *device, 0, 0, {}, visible_pixels.data(),
            sizeof(visible_pixels), &error));
        INFO(error);
        // Uniform RGB 4 has overbright drive RGB 2. The initial state uses a
        // zero history and the authored dt clamp/slew, so it lands at 2 to
        // half precision while the raw/reference/anchor texel records 2.
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            CHECK(std::abs(half_to_float(visible_pixels[channel]) - 2.f) <
                  0.003f);
        }
        CHECK(std::abs(half_to_float(visible_pixels[4]) - 2.f) < 0.003f);
        CHECK(std::abs(half_to_float(visible_pixels[5]) - 2.f) < 0.003f);
        CHECK(std::abs(half_to_float(visible_pixels[6]) - 2.f) < 0.003f);
        CHECK(std::abs(half_to_float(visible_pixels[7]) - 0.25f) <
              0.0005f);
        std::array<std::uint16_t, 8> occluded_pixels{};
        REQUIRE(occluded->colorTexture(0)->readback(
            *device, 0, 0, {}, occluded_pixels.data(),
            sizeof(occluded_pixels), &error));
        const float faded = half_to_float(occluded_pixels[0]);
        CHECK(faded > 0.f);
        CHECK(faded < half_to_float(visible_pixels[0]));
        CHECK(half_to_float(occluded_pixels[4]) == 0.f);
        CHECK(half_to_float(occluded_pixels[5]) > faded);

        ALMetalWorldDisplayPostScene display;
        display.source = dark.get();
        display.hdr = true;
        display.static_exposure = 0.5f;
        display.tonemap_mix = 0.f;
        auto baseline = renderer->renderDisplayPost(display, &error);
        INFO(error);
        REQUIRE(baseline);
        display.lens_flare_state_texture = visible->colorTexture(0);
        display.lens_flare_strength = 1.f;
        display.lens_flare_sun_uv[0] = 0.5f;
        display.lens_flare_sun_uv[1] = 0.5f;
        display.lens_flare_streak_intensity = 0.f;
        auto flared = renderer->renderDisplayPost(display, &error);
        INFO(error);
        REQUIRE(flared);
        std::array<std::uint32_t, width * height> baseline_pixels{};
        std::array<std::uint32_t, width * height> flared_pixels{};
        REQUIRE(baseline->colorTexture(0)->readback(
            *device, 0, 0, {}, baseline_pixels.data(), width * 4, &error));
        REQUIRE(flared->colorTexture(0)->readback(
            *device, 0, 0, {}, flared_pixels.data(), width * 4, &error));
        const std::size_t center = (height / 2) * width + width / 2;
        CHECK((flared_pixels[center] & 0x3ffu) >
              (baseline_pixels[center] & 0x3ffu));
        CHECK(flared_pixels != baseline_pixels);

        const auto render_flare_pixels = [&](const auto& flare_scene)
        {
            auto output = renderer->renderDisplayPost(flare_scene, &error);
            INFO(error);
            REQUIRE(output);
            std::array<std::uint32_t, width * height> pixels{};
            REQUIRE(output->colorTexture(0)->readback(
                *device, 0, 0, {}, pixels.data(), width * 4, &error));
            INFO(error);
            return pixels;
        };
        // Exercise every independently gated display family. Comparisons use
        // the same immutable state texel and source, so each nonzero delta is
        // attributable to the selected analytical branch.
        ALMetalWorldDisplayPostScene streak_scene = display;
        streak_scene.lens_flare_glow = 0.f;
        streak_scene.lens_flare_streak_width = 0.05f;
        streak_scene.lens_flare_streak_intensity = 1.f;
        streak_scene.lens_flare_chromatic_spread = 0.f;
        const auto streak_pixels = render_flare_pixels(streak_scene);
        CHECK(streak_pixels != baseline_pixels);
        CHECK(streak_pixels != flared_pixels);

        ALMetalWorldDisplayPostScene fringe_scene = streak_scene;
        fringe_scene.lens_flare_chromatic_spread = 0.05f;
        const auto fringe_pixels = render_flare_pixels(fringe_scene);
        CHECK(fringe_pixels != streak_pixels);

        ALMetalWorldDisplayPostScene ghost_scene = display;
        ghost_scene.lens_flare_sun_uv[0] = 0.25f;
        ghost_scene.lens_flare_glow = 0.f;
        ghost_scene.lens_flare_streak_intensity = 0.f;
        ghost_scene.lens_flare_ghost = 1.f;
        ghost_scene.lens_flare_ghost_count = 3;
        const auto ghost_pixels = render_flare_pixels(ghost_scene);
        CHECK(ghost_pixels != baseline_pixels);

        ALMetalWorldDisplayPostScene halo_scene = display;
        halo_scene.lens_flare_sun_uv[0] = 0.25f;
        halo_scene.lens_flare_glow = 0.f;
        halo_scene.lens_flare_streak_intensity = 0.f;
        halo_scene.lens_flare_halo = 1.f;
        halo_scene.lens_flare_halo_radius = 0.2f;
        halo_scene.lens_flare_halo_width = 0.1f;
        const auto halo_pixels = render_flare_pixels(halo_scene);
        CHECK(halo_pixels != baseline_pixels);
        CHECK(halo_pixels != ghost_pixels);

        ALMetalWorldDisplayPostScene star_scene = display;
        star_scene.lens_flare_glow = 0.f;
        star_scene.lens_flare_streak_intensity = 0.f;
        star_scene.lens_flare_starburst = 1.f;
        star_scene.lens_flare_starburst_spikes = 6;
        star_scene.lens_flare_starburst_sharpness = 12.f;
        star_scene.lens_flare_starburst_falloff = 8.f;
        const auto star_pixels = render_flare_pixels(star_scene);
        CHECK(star_pixels != baseline_pixels);
        CHECK(star_pixels != halo_pixels);

        // One dense independent scalar oracle covers all families together,
        // including RGB-separated streak fringes and integer loop counts.
        ALMetalWorldDisplayPostScene combined = display;
        combined.lens_flare_sun_uv[0] = 0.25f;
        combined.lens_flare_sun_uv[1] = 0.45f;
        combined.lens_flare_strength = 0.7f;
        combined.lens_flare_sky_hdr_scale = 1.4f;
        combined.lens_flare_light_color[0] = 0.8f;
        combined.lens_flare_light_color[1] = 0.6f;
        combined.lens_flare_light_color[2] = 0.4f;
        combined.lens_flare_streak_length = 0.7f;
        combined.lens_flare_streak_falloff = 2.f;
        combined.lens_flare_streak_width = 0.04f;
        combined.lens_flare_streak_intensity = 0.8f;
        combined.lens_flare_streak_tint[0] = 0.5f;
        combined.lens_flare_streak_tint[1] = 0.7f;
        combined.lens_flare_streak_tint[2] = 0.9f;
        combined.lens_flare_chromatic_spread = 0.03f;
        combined.lens_flare_glow = 0.6f;
        combined.lens_flare_glow_radius = 0.2f;
        combined.lens_flare_glow_falloff = 5.f;
        combined.lens_flare_ghost = 0.5f;
        combined.lens_flare_ghost_count = 3;
        combined.lens_flare_ghost_spacing = 0.4f;
        combined.lens_flare_halo = 0.7f;
        combined.lens_flare_halo_radius = 0.3f;
        combined.lens_flare_halo_width = 0.12f;
        combined.lens_flare_starburst = 0.8f;
        combined.lens_flare_starburst_spikes = 5;
        combined.lens_flare_starburst_sharpness = 10.f;
        combined.lens_flare_starburst_falloff = 7.f;
        const auto combined_pixels = render_flare_pixels(combined);
        const auto smoothstep_cpu = [](float low, float high, float value)
        {
            const float t = std::clamp(
                (value - low) / (high - low), 0.f, 1.f);
            return t * t * (3.f - 2.f * t);
        };
        const auto srgb_cpu = [](float linear)
        {
            linear = std::max(linear, 0.f);
            return linear > 0.0031308f
                ? 1.055f * std::pow(linear, 1.f / 2.4f) - 0.055f
                : linear * 12.92f;
        };
        const auto unorm10_cpu = [](float value)
        {
            return static_cast<std::uint32_t>(std::lround(
                std::clamp(value, 0.f, 1.f) * 1023.f));
        };
        const float source_value = half_to_float(0x2e66u);
        const std::array<float, 3> state_drive{{
            half_to_float(visible_pixels[0]),
            half_to_float(visible_pixels[1]),
            half_to_float(visible_pixels[2]),
        }};
        for (std::uint32_t y = 0; y < height; ++y)
        {
            for (std::uint32_t x = 0; x < width; ++x)
            {
                const float u = (static_cast<float>(x) + 0.5f) / width;
                const float v = (static_cast<float>(y) + 0.5f) / height;
                const float dx = u - combined.lens_flare_sun_uv[0];
                const float dy = v - combined.lens_flare_sun_uv[1];
                const float aspect = static_cast<float>(width) / height;
                std::array<float, 3> flare{};

                const float gx = dx * aspect;
                const float glow = std::exp(
                    -(gx * gx + dy * dy) *
                    combined.lens_flare_glow_falloff /
                    (combined.lens_flare_glow_radius *
                     combined.lens_flare_glow_radius));
                for (std::size_t channel = 0; channel < 3; ++channel)
                {
                    flare[channel] += state_drive[channel] * glow *
                        combined.lens_flare_glow *
                        combined.lens_flare_sky_hdr_scale;
                }

                const float fringe_width =
                    combined.lens_flare_streak_width +
                    combined.lens_flare_chromatic_spread * 0.5f;
                if (std::abs(dy) < fringe_width * 8.f)
                {
                    const float horizontal = std::abs(dx) * aspect;
                    const float horizontal_falloff = std::exp(
                        -horizontal * combined.lens_flare_streak_falloff /
                        combined.lens_flare_streak_length);
                    const float streak = std::exp(
                        -dy * dy /
                        (combined.lens_flare_streak_width *
                         combined.lens_flare_streak_width)) *
                        horizontal_falloff;
                    const float red_y = std::abs(
                        dy + combined.lens_flare_chromatic_spread);
                    const float blue_y = std::abs(
                        dy - combined.lens_flare_chromatic_spread);
                    const float red = std::exp(
                        -red_y * red_y / (fringe_width * fringe_width)) *
                        horizontal_falloff;
                    const float blue = std::exp(
                        -blue_y * blue_y / (fringe_width * fringe_width)) *
                        horizontal_falloff;
                    flare[0] += state_drive[0] * red *
                        combined.lens_flare_streak_tint[0] *
                        combined.lens_flare_streak_intensity;
                    flare[1] += state_drive[1] * streak *
                        combined.lens_flare_streak_tint[1] *
                        combined.lens_flare_streak_intensity;
                    flare[2] += state_drive[2] * blue *
                        combined.lens_flare_streak_tint[2] *
                        combined.lens_flare_streak_intensity;
                }

                for (std::uint32_t ghost = 0;
                     ghost < combined.lens_flare_ghost_count; ++ghost)
                {
                    const float scale = 1.f / (ghost + 1.f);
                    const float t = combined.lens_flare_ghost_spacing *
                        (ghost + 1.f);
                    const float ghost_u =
                        combined.lens_flare_sun_uv[0] +
                        (0.5f - combined.lens_flare_sun_uv[0]) * t;
                    const float ghost_v =
                        combined.lens_flare_sun_uv[1] +
                        (0.5f - combined.lens_flare_sun_uv[1]) * t;
                    const float ghost_dx = (u - ghost_u) * aspect;
                    const float ghost_dy = v - ghost_v;
                    const float radius = 0.04f * scale + 0.02f;
                    const float disk = 1.f - smoothstep_cpu(
                        radius * 0.5f, radius,
                        std::sqrt(ghost_dx * ghost_dx +
                                  ghost_dy * ghost_dy));
                    for (std::size_t channel = 0; channel < 3; ++channel)
                    {
                        flare[channel] += state_drive[channel] * disk *
                            scale * combined.lens_flare_ghost;
                    }
                }

                const float halo_u = 1.f -
                    combined.lens_flare_sun_uv[0];
                const float halo_v = 1.f -
                    combined.lens_flare_sun_uv[1];
                const float halo_dx = (u - halo_u) * aspect;
                const float halo_dy = v - halo_v;
                float halo = 1.f - std::abs(
                    std::sqrt(halo_dx * halo_dx + halo_dy * halo_dy) -
                    combined.lens_flare_halo_radius) /
                    combined.lens_flare_halo_width;
                halo = std::clamp(halo, 0.f, 1.f);
                halo *= halo;
                for (std::size_t channel = 0; channel < 3; ++channel)
                {
                    flare[channel] += state_drive[channel] * halo * 0.3f *
                        combined.lens_flare_halo;
                }

                const float star_x = dx * aspect;
                const float star_distance = std::sqrt(
                    star_x * star_x + dy * dy);
                const float envelope = std::exp(
                    -star_distance *
                    combined.lens_flare_starburst_falloff) *
                    smoothstep_cpu(0.f, combined.lens_flare_glow_radius,
                                   star_distance);
                if (envelope > 1.e-5f)
                {
                    const float angle = std::atan2(dy, star_x);
                    const float primary = static_cast<float>(
                        combined.lens_flare_starburst_spikes);
                    const float sharp =
                        combined.lens_flare_starburst_sharpness;
                    const float pattern =
                        std::pow(std::abs(std::cos(angle * primary)),
                                 sharp) * 0.5f +
                        std::pow(std::abs(std::cos(
                                     angle * primary * 2.f + 0.5f)),
                                 sharp * 1.33f) * 0.3f +
                        std::pow(std::abs(std::cos(
                                     angle * primary * 4.f + 1.f)),
                                 sharp * 1.66f) * 0.2f;
                    for (std::size_t channel = 0; channel < 3; ++channel)
                    {
                        flare[channel] += state_drive[channel] * pattern *
                            envelope * combined.lens_flare_starburst *
                            combined.lens_flare_sky_hdr_scale;
                    }
                }

                const std::size_t pixel =
                    static_cast<std::size_t>(y) * width + x;
                for (std::uint32_t channel = 0; channel < 3; ++channel)
                {
                    flare[channel] = std::max(
                        flare[channel] * combined.lens_flare_strength *
                        combined.lens_flare_light_color[channel] * 0.15f,
                        0.f);
                    const float display_value = srgb_cpu(std::clamp(
                        (source_value + flare[channel]) *
                            combined.static_exposure,
                        0.f, 1.f));
                    const std::uint32_t actual =
                        (combined_pixels[pixel] >> (channel * 10u)) & 0x3ffu;
                    const std::uint32_t expected =
                        unorm10_cpu(display_value);
                    CAPTURE(x, y, channel, actual, expected);
                    CHECK(std::abs(static_cast<int>(actual) -
                                   static_cast<int>(expected)) <= 2);
                }
            }
        }

        ALMetalWorldLensFlareStateScene invalid;
        error.clear();
        CHECK_FALSE(renderer->renderLensFlareState(invalid, &error));
        CHECK(error == "Metal world lens-flare state scene is incomplete");
        invalid = state_scene;
        invalid.previous = dark->colorTexture(0);
        error.clear();
        CHECK_FALSE(renderer->renderLensFlareState(invalid, &error));
        CHECK(error == "Metal world lens-flare history is incompatible");
        display.lens_flare_state_texture = nullptr;
        error.clear();
        CHECK_FALSE(renderer->renderDisplayPost(display, &error));
        CHECK(error == "Metal world display-post state is invalid");
        display.lens_flare_state_texture = visible->colorTexture(0);
        display.lens_flare_ghost_count = 9;
        error.clear();
        CHECK_FALSE(renderer->renderDisplayPost(display, &error));
        CHECK(error == "Metal world display-post state is invalid");
    }
}

TEST_CASE("almetal: world lens dirt owns its plate and light response", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        auto renderer = ALMetalWorldGBufferRenderer::create(*device, &error);
        INFO(error);
        REQUIRE(renderer);

        constexpr std::uint32_t width = 24;
        constexpr std::uint32_t height = 16;
        ALMetalWorldLensDirtScene dirt_scene;
        dirt_scene.width = width;
        dirt_scene.height = height;
        dirt_scene.seed = 19.f;
        dirt_scene.grime = 1.1f;
        dirt_scene.mote_scale = 1.25f;
        dirt_scene.smudge = 0.8f;
        dirt_scene.scratches = 7;
        dirt_scene.toe = 1.4f;
        dirt_scene.gain = 1.2f;
        auto dirt = renderer->renderLensDirt(dirt_scene, &error);
        INFO(error);
        REQUIRE(dirt);
        CHECK(dirt->descriptor().width == width);
        CHECK(dirt->descriptor().height == height);
        CHECK(dirt->descriptor().colors[0].format ==
              ALMetalPixelFormat::r8_unorm);
        std::array<std::uint8_t, width * height> dirt_pixels{};
        REQUIRE(dirt->colorTexture(0)->readback(
            *device, 0, 0, {}, dirt_pixels.data(), width, &error));
        INFO(error);
        const auto [minimum, maximum] = std::minmax_element(
            dirt_pixels.begin(), dirt_pixels.end());
        CHECK(*maximum > *minimum);
        CHECK(std::count_if(
                  dirt_pixels.begin(), dirt_pixels.end(),
                  [](std::uint8_t value) { return value != 0; }) >
              static_cast<std::ptrdiff_t>(width));

        auto repeated = renderer->renderLensDirt(dirt_scene, &error);
        INFO(error);
        REQUIRE(repeated);
        std::array<std::uint8_t, width * height> repeated_pixels{};
        REQUIRE(repeated->colorTexture(0)->readback(
            *device, 0, 0, {}, repeated_pixels.data(), width, &error));
        CHECK(repeated_pixels == dirt_pixels);

        ALMetalWorldLensDirtScene reseeded_scene = dirt_scene;
        reseeded_scene.seed += 1.f;
        auto reseeded = renderer->renderLensDirt(reseeded_scene, &error);
        INFO(error);
        REQUIRE(reseeded);
        std::array<std::uint8_t, width * height> reseeded_pixels{};
        REQUIRE(reseeded->colorTexture(0)->readback(
            *device, 0, 0, {}, reseeded_pixels.data(), width, &error));
        CHECK(reseeded_pixels != dirt_pixels);

        const auto make_source = [&](std::uint16_t value,
                                     const char* label)
        {
            std::vector<std::uint16_t> pixels(width * height * 4, value);
            for (std::size_t pixel = 0; pixel < width * height; ++pixel)
            {
                pixels[pixel * 4 + 3] = 0x3c00u;
            }
            ALMetalRenderTargetDescriptor descriptor;
            descriptor.width = width;
            descriptor.height = height;
            descriptor.colors[0].format =
                ALMetalPixelFormat::rgba16_float;
            descriptor.label = label;
            auto target = ALMetalRenderTarget::create(
                *device, descriptor, &error);
            INFO(error);
            REQUIRE(target);
            auto command = device->makeCommandBuffer(label, &error);
            INFO(error);
            REQUIRE(command);
            id<MTLBuffer> staging = [nativeDevice(*device)
                newBufferWithBytes:pixels.data()
                          length:pixels.size() * sizeof(std::uint16_t)
                         options:MTLResourceStorageModeShared];
            REQUIRE(staging);
            id<MTLBlitCommandEncoder> blit =
                [nativeCommand(*command) blitCommandEncoder];
            REQUIRE(blit);
            const std::size_t row_bytes =
                width * 4 * sizeof(std::uint16_t);
            [blit copyFromBuffer:staging
                    sourceOffset:0
               sourceBytesPerRow:row_bytes
             sourceBytesPerImage:row_bytes * height
                      sourceSize:MTLSizeMake(width, height, 1)
                       toTexture:(__bridge id<MTLTexture>)
                           target->colorTexture(0)->nativeHandle()
                destinationSlice:0
                destinationLevel:0
               destinationOrigin:MTLOriginMake(0, 0, 0)];
            [blit endEncoding];
            REQUIRE(command->commit(&error));
            INFO(error);
            return target;
        };
        auto source = make_source(
            0x2e66u, "Alchemy lens-dirt display source");

        ALMetalTextureDescriptor flare_descriptor;
        flare_descriptor.format = ALMetalPixelFormat::rgba16_float;
        flare_descriptor.width = 2;
        flare_descriptor.height = 1;
        flare_descriptor.storage = ALMetalStorageMode::private_gpu;
        flare_descriptor.usage = ALMetalTextureUsage::shader_read;
        flare_descriptor.label = "Alchemy lens-dirt flare state";
        auto flare_state = ALMetalTexture::create(
            *device, flare_descriptor, &error);
        INFO(error);
        REQUIRE(flare_state);
        const std::array<std::uint16_t, 8> flare_pixels{{
            0x3c00u, 0x3c00u, 0x3c00u, 0u,
            0u, 0u, 0u, 0u,
        }};
        auto flare_upload = device->makeCommandBuffer(
            "Alchemy lens-dirt flare-state upload", &error);
        INFO(error);
        REQUIRE(flare_upload);
        REQUIRE(flare_state->upload(
            *flare_upload, 0, 0, {}, flare_pixels.data(),
            sizeof(flare_pixels), &error));
        REQUIRE(flare_upload->commit(&error));
        INFO(error);

        ALMetalWorldDisplayPostScene display;
        display.source = source.get();
        display.hdr = true;
        display.tonemap_mix = 0.f;
        display.lens_flare_state_texture = flare_state.get();
        display.lens_flare_strength = 1.f;
        display.lens_flare_sun_uv[0] = 0.5f;
        display.lens_flare_sun_uv[1] = 0.5f;
        display.lens_flare_streak_intensity = 0.f;
        display.lens_flare_glow = 1.f;
        display.lens_flare_glow_radius = 0.5f;
        display.lens_flare_glow_falloff = 1.f;
        display.lens_flare_ghost = 0.f;
        display.lens_flare_halo = 0.f;
        display.lens_flare_starburst = 0.f;
        display.lens_dirt_texture = dirt->colorTexture(0);

        auto without_dirt = renderer->renderDisplayPost(display, &error);
        INFO(error);
        REQUIRE(without_dirt);
        std::array<std::uint32_t, width * height> baseline{};
        REQUIRE(without_dirt->colorTexture(0)->readback(
            *device, 0, 0, {}, baseline.data(), width * 4, &error));

        display.lens_dirt_strength = 1.5f;
        display.lens_dirt_flare_response = 0.75f;
        auto with_dirt = renderer->renderDisplayPost(display, &error);
        INFO(error);
        REQUIRE(with_dirt);
        std::array<std::uint32_t, width * height> dirt_output{};
        REQUIRE(with_dirt->colorTexture(0)->readback(
            *device, 0, 0, {}, dirt_output.data(), width * 4, &error));
        CHECK(dirt_output != baseline);

        const auto half_to_float = [](std::uint16_t value)
        {
            const std::uint32_t sign =
                static_cast<std::uint32_t>(value & 0x8000u) << 16;
            std::uint32_t exponent = (value >> 10) & 0x1fu;
            std::uint32_t mantissa = value & 0x03ffu;
            std::uint32_t bits = 0;
            if (exponent == 0)
            {
                if (mantissa == 0)
                {
                    bits = sign;
                }
                else
                {
                    std::int32_t unbiased = -14;
                    while ((mantissa & 0x0400u) == 0)
                    {
                        mantissa <<= 1;
                        --unbiased;
                    }
                    mantissa &= 0x03ffu;
                    bits = sign |
                        (static_cast<std::uint32_t>(unbiased + 127) << 23) |
                        (mantissa << 13);
                }
            }
            else
            {
                bits = exponent == 0x1fu
                    ? sign | 0x7f800000u | (mantissa << 13)
                    : sign | ((exponent + 112u) << 23) |
                        (mantissa << 13);
            }
            float result = 0.f;
            std::memcpy(&result, &bits, sizeof(result));
            return result;
        };
        const auto srgb = [](float linear)
        {
            linear = std::max(linear, 0.f);
            return linear > 0.0031308f
                ? 1.055f * std::pow(linear, 1.f / 2.4f) - 0.055f
                : linear * 12.92f;
        };
        const float source_value = half_to_float(0x2e66u);
        const float aspect = static_cast<float>(width) / height;
        for (std::uint32_t y = 0; y < height; ++y)
        {
            for (std::uint32_t x = 0; x < width; ++x)
            {
                const float u = (static_cast<float>(x) + 0.5f) / width;
                const float v = (static_cast<float>(y) + 0.5f) / height;
                const float dx = (u - 0.5f) * aspect;
                const float dy = v - 0.5f;
                const float flare = std::exp(
                    -(dx * dx + dy * dy) / (0.5f * 0.5f)) * 0.15f;
                const std::size_t pixel =
                    static_cast<std::size_t>(y) * width + x;
                const float dirt_value = dirt_pixels[pixel] / 255.f;
                const float linear = source_value + flare +
                    flare * 0.75f * dirt_value * 1.5f;
                const std::uint32_t expected =
                    static_cast<std::uint32_t>(std::lround(
                        std::clamp(srgb(std::clamp(linear, 0.f, 1.f)),
                                   0.f, 1.f) * 1023.f));
                for (std::uint32_t channel = 0; channel < 3; ++channel)
                {
                    const std::uint32_t actual =
                        (dirt_output[pixel] >> (channel * 10u)) & 0x3ffu;
                    CAPTURE(x, y, channel, actual, expected, dirt_value);
                    CHECK(std::abs(static_cast<int>(actual) -
                                   static_cast<int>(expected)) <= 2);
                }
            }
        }

        // A uniform completed bloom pyramid also lights the plate, while a
        // zero bloom response leaves the ordinary bloom composite unchanged.
        ALMetalWorldBloomScene bloom_scene;
        bloom_scene.source = source.get();
        bloom_scene.mip_count = 3;
        bloom_scene.threshold = 100.f;
        bloom_scene.knee = 0.f;
        bloom_scene.scatter = 1.f;
        bloom_scene.alpha_glow_boost = 0.5f;
        auto bloom = renderer->renderBloom(bloom_scene, &error);
        INFO(error);
        REQUIRE(bloom);
        ALMetalWorldDisplayPostScene bloom_display;
        bloom_display.source = source.get();
        bloom_display.bloom_texture = bloom->colorTexture(0);
        bloom_display.bloom_strength = 0.25f;
        bloom_display.hdr = true;
        bloom_display.tonemap_mix = 0.f;
        bloom_display.lens_dirt_texture = dirt->colorTexture(0);
        bloom_display.lens_dirt_strength = 1.f;
        bloom_display.lens_dirt_bloom_response = 0.f;
        auto bloom_clean = renderer->renderDisplayPost(
            bloom_display, &error);
        INFO(error);
        REQUIRE(bloom_clean);
        bloom_display.lens_dirt_bloom_response = 1.f;
        auto bloom_dirty = renderer->renderDisplayPost(
            bloom_display, &error);
        INFO(error);
        REQUIRE(bloom_dirty);
        std::array<std::uint32_t, width * height> bloom_clean_pixels{};
        std::array<std::uint32_t, width * height> bloom_dirty_pixels{};
        REQUIRE(bloom_clean->colorTexture(0)->readback(
            *device, 0, 0, {}, bloom_clean_pixels.data(), width * 4,
            &error));
        REQUIRE(bloom_dirty->colorTexture(0)->readback(
            *device, 0, 0, {}, bloom_dirty_pixels.data(), width * 4,
            &error));
        CHECK(bloom_dirty_pixels != bloom_clean_pixels);

        ALMetalWorldLensDirtScene invalid;
        error.clear();
        CHECK_FALSE(renderer->renderLensDirt(invalid, &error));
        CHECK(error == "Metal world lens-dirt scene is invalid");
        invalid = dirt_scene;
        invalid.scratches = 33;
        error.clear();
        CHECK_FALSE(renderer->renderLensDirt(invalid, &error));
        CHECK(error == "Metal world lens-dirt scene is invalid");
        display.lens_dirt_texture = nullptr;
        error.clear();
        CHECK_FALSE(renderer->renderDisplayPost(display, &error));
        CHECK(error == "Metal world display-post state is invalid");
        display.lens_dirt_texture = dirt->colorTexture(0);
        display.lens_dirt_strength = 2.1f;
        error.clear();
        CHECK_FALSE(renderer->renderDisplayPost(display, &error));
        CHECK(error == "Metal world display-post state is invalid");
    }
}

TEST_CASE("almetal: world bloom matches the production HDR pyramid", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        auto renderer = ALMetalWorldGBufferRenderer::create(
            *device, &error);
        INFO(error);
        REQUIRE(renderer);

        constexpr std::uint32_t width = 8;
        constexpr std::uint32_t height = 8;
        std::array<std::uint16_t, width * height * 4> pixels{};
        for (std::size_t pixel = 0; pixel < width * height; ++pixel)
        {
            pixels[pixel * 4 + 0] = 0x3400u; // linear 0.25 red
            pixels[pixel * 4 + 3] = 0x3c00u; // alpha/glow tag 1.0
        }
        ALMetalRenderTargetDescriptor source_descriptor;
        source_descriptor.width = width;
        source_descriptor.height = height;
        source_descriptor.colors[0].format =
            ALMetalPixelFormat::rgba16_float;
        source_descriptor.label = "Alchemy world bloom test source";
        auto source = ALMetalRenderTarget::create(
            *device, source_descriptor, &error);
        INFO(error);
        REQUIRE(source);

        auto upload = device->makeCommandBuffer(
            "Alchemy world bloom test upload", &error);
        INFO(error);
        REQUIRE(upload);
        id<MTLBuffer> staging = [nativeDevice(*device)
            newBufferWithBytes:pixels.data()
                      length:sizeof(pixels)
                     options:MTLResourceStorageModeShared];
        REQUIRE(staging);
        id<MTLBlitCommandEncoder> blit =
            [nativeCommand(*upload) blitCommandEncoder];
        REQUIRE(blit);
        [blit copyFromBuffer:staging
                sourceOffset:0
           sourceBytesPerRow:width * 4 * sizeof(std::uint16_t)
         sourceBytesPerImage:sizeof(pixels)
                  sourceSize:MTLSizeMake(width, height, 1)
                   toTexture:(__bridge id<MTLTexture>)
                       source->colorTexture(0)->nativeHandle()
            destinationSlice:0
            destinationLevel:0
           destinationOrigin:MTLOriginMake(0, 0, 0)];
        [blit endEncoding];
        REQUIRE(upload->commit(&error));
        INFO(error);

        // Threshold suppresses ordinary HDR extraction, leaving only the
        // legacy alpha/glow term: 0.25 * 1 * 0.5 * 2 = 0.25. A uniform field
        // stays 0.25 through normalized downsampling. Three levels then add
        // 0.25 + (0.25 + 0.25) = 0.75 into the top mip.
        ALMetalWorldBloomScene bloom_scene;
        bloom_scene.source = source.get();
        bloom_scene.mip_count = 3;
        bloom_scene.threshold = 100.f;
        bloom_scene.knee = 0.f;
        bloom_scene.scatter = 1.f;
        bloom_scene.alpha_glow_boost = 0.5f;
        auto bloom = renderer->renderBloom(bloom_scene, &error);
        INFO(error);
        REQUIRE(bloom);
        CHECK(bloom->descriptor().width == width);
        CHECK(bloom->descriptor().height == height);
        CHECK(bloom->descriptor().colors[0].format ==
              ALMetalPixelFormat::rg11b10_float);

        ALMetalWorldDisplayPostScene display;
        display.source = source.get();
        display.bloom_texture = bloom->colorTexture(0);
        display.hdr = true;
        display.bloom_strength = 1.f;
        display.tonemap_mix = 0.f;
        auto output = renderer->renderDisplayPost(display, &error);
        INFO(error);
        REQUIRE(output);
        std::array<std::uint32_t, width * height> packed{};
        REQUIRE(output->colorTexture(0)->readback(
            *device, 0, 0, {}, packed.data(), width * sizeof(std::uint32_t),
            &error));
        INFO(error);
        CHECK((packed[0] & 0x3ffu) == 0x3ffu);
        CHECK(((packed[0] >> 10u) & 0x3ffu) == 0u);
        CHECK(((packed[0] >> 20u) & 0x3ffu) == 0u);
        CHECK((packed[0] >> 30u) == 3u);

        // Production encodes bloom, display mapping and final BGRA8
        // presentation as one dependent optical-post transaction. Prove the
        // complete chain advances the process-wide submission counter once
        // and remains byte-identical to standalone submission.
        ALMetalWorldPresentationScene standalone_presentation_scene;
        standalone_presentation_scene.source = output.get();
        auto standalone_presentation = renderer->renderPresentationPost(
            standalone_presentation_scene, &error);
        INFO(error);
        REQUIRE(standalone_presentation);
        std::array<std::uint8_t, width * height * 4>
            standalone_presentation_pixels{};
        REQUIRE(standalone_presentation->colorTexture(0)->readback(
            *device, 0, 0, {}, standalone_presentation_pixels.data(),
            width * 4, &error));
        INFO(error);

        const std::uint64_t submissions_before_batch =
            ALMetalDevice::committedCommandBufferCount();
        REQUIRE(renderer->beginCommandBatch(
            "Alchemy optical-post command-batch regression", &error));
        auto batched_bloom = renderer->renderBloom(
            bloom_scene, &error);
        INFO(error);
        REQUIRE(batched_bloom);
        ALMetalWorldDisplayPostScene batched_display_scene = display;
        batched_display_scene.bloom_texture =
            batched_bloom->colorTexture(0);
        auto batched_display = renderer->renderDisplayPost(
            batched_display_scene, &error);
        INFO(error);
        REQUIRE(batched_display);
        ALMetalWorldPresentationScene batched_presentation_scene;
        batched_presentation_scene.source = batched_display.get();
        auto batched_presentation = renderer->renderPresentationPost(
            batched_presentation_scene, &error);
        INFO(error);
        REQUIRE(batched_presentation);
        REQUIRE(renderer->commitCommandBatch(&error));
        INFO(error);
        CHECK(ALMetalDevice::committedCommandBufferCount() ==
              submissions_before_batch + 1);
        std::array<std::uint8_t, width * height * 4>
            batched_presentation_pixels{};
        REQUIRE(batched_presentation->colorTexture(0)->readback(
            *device, 0, 0, {}, batched_presentation_pixels.data(),
            width * 4, &error));
        INFO(error);
        CHECK(batched_presentation_pixels ==
              standalone_presentation_pixels);

        // colorCorrect scales only the completed pyramid, not the scene.
        // 0.25 + 0.75 * 0.25 = 0.4375 linear before the display transfer.
        display.bloom_strength = 0.25f;
        auto quarter = renderer->renderDisplayPost(display, &error);
        INFO(error);
        REQUIRE(quarter);
        REQUIRE(quarter->colorTexture(0)->readback(
            *device, 0, 0, {}, packed.data(), width * sizeof(std::uint32_t),
            &error));
        const float encoded =
            1.055f * std::pow(0.4375f, 1.f / 2.4f) - 0.055f;
        const int expected = static_cast<int>(std::lround(encoded * 1023.f));
        CHECK(std::abs(static_cast<int>(packed[0] & 0x3ffu) - expected) <= 2);

        // Halation carries its warm-luminance response through RGBA16F alpha
        // and composites its tint independently of ordinary bloom strength.
        ALMetalWorldBloomScene halation_scene = bloom_scene;
        halation_scene.threshold = 0.1f;
        halation_scene.alpha_glow_boost = 0.f;
        halation_scene.halation = true;
        halation_scene.halation_weights[0] = 1.f;
        halation_scene.halation_weights[1] = 0.f;
        halation_scene.halation_weights[2] = 0.f;
        auto halation = renderer->renderBloom(halation_scene, &error);
        INFO(error);
        REQUIRE(halation);
        CHECK(halation->descriptor().colors[0].format ==
              ALMetalPixelFormat::rgba16_float);
        std::array<std::uint16_t, width * height * 4> halation_pixels{};
        REQUIRE(halation->colorTexture(0)->readback(
            *device, 0, 0, {}, halation_pixels.data(),
            width * 4 * sizeof(std::uint16_t), &error));
        CHECK(halation_pixels[3] != 0u);

        ALMetalWorldDisplayPostScene halation_display;
        halation_display.source = source.get();
        halation_display.bloom_texture = halation->colorTexture(0);
        halation_display.hdr = true;
        halation_display.halation_strength = 1.f;
        halation_display.halation_tint[0] = 0.f;
        halation_display.halation_tint[1] = 1.f;
        halation_display.halation_tint[2] = 0.f;
        halation_display.tonemap_mix = 0.f;
        auto halation_output = renderer->renderDisplayPost(
            halation_display, &error);
        INFO(error);
        REQUIRE(halation_output);
        REQUIRE(halation_output->colorTexture(0)->readback(
            *device, 0, 0, {}, packed.data(), width * sizeof(std::uint32_t),
            &error));
        CHECK(((packed[0] >> 10u) & 0x3ffu) > (packed[0] & 0x3ffu));
        CHECK(((packed[0] >> 20u) & 0x3ffu) == 0u);

        // A uniform 0.25 extract stays 0.25 through each normalized arm.
        // Four additive arms therefore produce an exact 1.0 half-float sum.
        ALMetalWorldBloomScene cross_scene = bloom_scene;
        cross_scene.cross_filter = true;
        std::unique_ptr<ALMetalRenderTarget> cross_filter;
        auto cross_bloom = renderer->renderBloom(
            cross_scene, &error, &cross_filter);
        INFO(error);
        REQUIRE(cross_bloom);
        REQUIRE(cross_filter);
        CHECK(cross_filter->descriptor().width == width / 2u);
        CHECK(cross_filter->descriptor().height == height / 2u);
        CHECK(cross_filter->descriptor().colors[0].format ==
              ALMetalPixelFormat::rgba16_float);
        std::array<std::uint16_t, (width / 2) * (height / 2) * 4>
            cross_pixels{};
        REQUIRE(cross_filter->colorTexture(0)->readback(
            *device, 0, 0, {}, cross_pixels.data(),
            (width / 2) * 4 * sizeof(std::uint16_t), &error));
        CHECK(cross_pixels[0] == 0x3c00u);
        CHECK(cross_pixels[1] == 0u);
        CHECK(cross_pixels[2] == 0u);
        CHECK(cross_pixels[3] == 0u);

        ALMetalWorldDisplayPostScene cross_display;
        cross_display.source = source.get();
        cross_display.bloom_texture = cross_bloom->colorTexture(0);
        cross_display.cross_filter_texture =
            cross_filter->colorTexture(0);
        cross_display.hdr = true;
        cross_display.bloom_strength = 0.25f;
        cross_display.cross_filter_strength = 0.5f;
        cross_display.tonemap_mix = 0.f;
        auto cross_output = renderer->renderDisplayPost(
            cross_display, &error);
        INFO(error);
        REQUIRE(cross_output);
        REQUIRE(cross_output->colorTexture(0)->readback(
            *device, 0, 0, {}, packed.data(), width * sizeof(std::uint32_t),
            &error));
        const float cross_encoded =
            1.055f * std::pow(0.5625f, 1.f / 2.4f) - 0.055f;
        const int cross_expected = static_cast<int>(std::lround(
            cross_encoded * 1023.f));
        CHECK(std::abs(static_cast<int>(packed[0] & 0x3ffu) -
                       cross_expected) <= 2);

        error.clear();
        CHECK_FALSE(renderer->renderBloom(cross_scene, &error));
        CHECK(error == "Metal world bloom state is invalid");
        cross_display.cross_filter_texture = bloom->colorTexture(0);
        error.clear();
        CHECK_FALSE(renderer->renderDisplayPost(cross_display, &error));
        CHECK(error ==
              "Metal world display-post cross-filter is incompatible");

        halation_display.bloom_texture = bloom->colorTexture(0);
        error.clear();
        CHECK_FALSE(renderer->renderDisplayPost(
            halation_display, &error));
        CHECK(error == "Metal world display-post bloom is incompatible");

        ALMetalWorldBloomScene invalid;
        error.clear();
        CHECK_FALSE(renderer->renderBloom(invalid, &error));
        CHECK(error == "Metal world bloom scene is incomplete");
        invalid.source = source.get();
        invalid.mip_count = 2;
        error.clear();
        CHECK_FALSE(renderer->renderBloom(invalid, &error));
        CHECK(error == "Metal world bloom state is invalid");
        invalid.mip_count = 3;
        invalid.resolution_scale = 4;
        error.clear();
        CHECK_FALSE(renderer->renderBloom(invalid, &error));
        CHECK(error == "Metal world bloom pyramid is too shallow");
        invalid.resolution_scale = 0;
        invalid.halation_weights[0] =
            std::numeric_limits<float>::quiet_NaN();
        error.clear();
        CHECK_FALSE(renderer->renderBloom(invalid, &error));
        CHECK(error == "Metal world bloom state is invalid");

        display.bloom_texture = output->colorTexture(0);
        display.bloom_strength = 1.f;
        error.clear();
        CHECK_FALSE(renderer->renderDisplayPost(display, &error));
        CHECK(error ==
              "Metal world display-post bloom is incompatible");
    }
}

TEST_CASE("almetal: RLVa vision sphere owns every post mode", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        auto renderer = ALMetalWorldGBufferRenderer::create(
            *device, &error);
        INFO(error);
        REQUIRE(renderer);

        constexpr std::uint32_t width = 9;
        constexpr std::uint32_t height = 9;
        std::array<std::uint32_t, width * height> input{};
        std::array<float, width * height> depth_pixels{};
        for (std::uint32_t y = 0; y < height; ++y)
        {
            for (std::uint32_t x = 0; x < width; ++x)
            {
                const std::uint32_t red = x * 100u + 23u;
                const std::uint32_t green = y * 100u + 31u;
                const std::uint32_t blue =
                    ((x + y) * 53u + 47u) % 900u;
                input[y * width + x] = red | (green << 10u) |
                    (blue << 20u) | (3u << 30u);
                depth_pixels[y * width + x] = 0.5f;
            }
        }

        ALMetalRenderTargetDescriptor source_descriptor;
        source_descriptor.width = width;
        source_descriptor.height = height;
        source_descriptor.colors[0].format =
            ALMetalPixelFormat::rgb10a2_unorm;
        source_descriptor.label = "Alchemy RLVa sphere test source";
        auto source = ALMetalRenderTarget::create(
            *device, source_descriptor, &error);
        INFO(error);
        REQUIRE(source);

        ALMetalTextureDescriptor depth_descriptor;
        depth_descriptor.format = ALMetalPixelFormat::depth32_float;
        depth_descriptor.width = width;
        depth_descriptor.height = height;
        depth_descriptor.storage = ALMetalStorageMode::private_gpu;
        depth_descriptor.usage = ALMetalTextureUsage::shader_read;
        depth_descriptor.label = "Alchemy RLVa sphere test depth";
        auto depth = ALMetalTexture::create(
            *device, depth_descriptor, &error);
        INFO(error);
        REQUIRE(depth);

        auto upload = device->makeCommandBuffer(
            "Alchemy RLVa sphere test upload", &error);
        INFO(error);
        REQUIRE(upload);
        id<MTLBuffer> staging = [nativeDevice(*device)
            newBufferWithBytes:input.data()
                      length:sizeof(input)
                     options:MTLResourceStorageModeShared];
        REQUIRE(staging);
        id<MTLBlitCommandEncoder> blit =
            [nativeCommand(*upload) blitCommandEncoder];
        REQUIRE(blit);
        [blit copyFromBuffer:staging
                sourceOffset:0
           sourceBytesPerRow:width * sizeof(std::uint32_t)
         sourceBytesPerImage:sizeof(input)
                  sourceSize:MTLSizeMake(width, height, 1)
                   toTexture:(__bridge id<MTLTexture>)
                       source->colorTexture(0)->nativeHandle()
            destinationSlice:0
            destinationLevel:0
           destinationOrigin:MTLOriginMake(0, 0, 0)];
        [blit endEncoding];
        REQUIRE(depth->upload(
            *upload, 0, 0, {}, depth_pixels.data(),
            width * sizeof(float), &error));
        REQUIRE(upload->commitAndWait(&error));
        INFO(error);

        ALMetalWorldRlvSphereScene scene;
        scene.source = source.get();
        scene.depth_texture = depth.get();
        scene.inverse_projection[0] = 1.f;
        scene.inverse_projection[5] = 1.f;
        scene.inverse_projection[10] = 1.f;
        scene.inverse_projection[15] = 1.f;
        scene.origin[3] = 1.f;
        scene.distance_value[0] = 0.f;
        scene.distance_value[1] = 0.f;
        scene.distance_value[2] = 1.f;
        scene.distance_value[3] = 2.f;
        scene.effect[0] = 1.f;
        scene.mode = 0;

        const auto render = [&](ALMetalWorldRlvSphereScene& request)
        {
            auto target = renderer->renderRlvSphere(request, &error);
            INFO(error);
            REQUIRE(target);
            std::array<std::uint32_t, width * height> pixels{};
            REQUIRE(target->colorTexture(0)->readback(
                *device, 0, 0, {}, pixels.data(),
                width * sizeof(std::uint32_t), &error));
            INFO(error);
            return pixels;
        };
        const auto channel = [](std::uint32_t pixel, std::uint32_t index)
        {
            return (pixel >> (index * 10u)) & 0x3ffu;
        };

        // The centre reconstructs at the sphere origin and remains the
        // source colour; a corner is farther away and blends strongly red.
        // This is the asymmetric control that proves the pass consumes the
        // retained depth and inverse projection rather than a flat overlay.
        const auto depth_weighted = render(scene);
        const std::size_t centre = (height / 2u) * width + width / 2u;
        CHECK(channel(depth_weighted[centre], 0) ==
              channel(input[centre], 0));
        CHECK(channel(depth_weighted[0], 0) >
              channel(depth_weighted[centre], 0));
        CHECK((depth_weighted[0] >> 30u) == 0u);

        // Move the origin far outside the reconstructed view and extend the
        // maximum value, yielding a uniform strength of one for the
        // remaining mode-specific controls.
        scene.origin[0] = 100.f;
        scene.distance_value[0] = 1.f;
        scene.distance_value[1] = 0.f;
        scene.distance_value[2] = 1.f;
        scene.distance_value[3] = 1.f;
        scene.extend_max = true;

        const auto blend = render(scene);
        CHECK(channel(blend[centre], 0) == 1023u);
        CHECK(channel(blend[centre], 1) == 0u);
        CHECK(channel(blend[centre], 2) == 0u);

        scene.mode = 1;
        const auto fixed_blur = render(scene);
        CHECK(fixed_blur != input);
        CHECK((fixed_blur[centre] >> 30u) == 0u);

        scene.mode = 2;
        scene.effect[0] = 7.f;
        const auto variable_blur = render(scene);
        CHECK(variable_blur != input);
        CHECK(variable_blur != fixed_blur);

        scene.mode = 3;
        scene.effect[0] = 1.f;
        scene.effect[1] = 0.f;
        scene.effect[2] = -1.f;
        scene.effect[3] = 0.f;
        const auto chromatic = render(scene);
        CHECK(channel(chromatic[centre], 0) ==
              channel(input[centre + 1u], 0));
        CHECK(channel(chromatic[centre], 1) ==
              channel(input[centre], 1));
        CHECK(channel(chromatic[centre], 2) ==
              channel(input[centre - 1u], 2));

        scene.mode = 4;
        scene.effect[0] = 3.f;
        scene.effect[1] = 3.f;
        const auto pixelated = render(scene);
        CHECK(pixelated[0] == pixelated[1]);
        CHECK(pixelated[1] == pixelated[2]);
        CHECK(pixelated[2] != pixelated[3]);
        CHECK(pixelated[0] == pixelated[width]);

        ALMetalWorldRlvSphereScene invalid;
        error.clear();
        CHECK_FALSE(renderer->renderRlvSphere(invalid, &error));
        CHECK(error == "Metal world RLVa sphere scene is incomplete");
        invalid = scene;
        invalid.mode = 5;
        error.clear();
        CHECK_FALSE(renderer->renderRlvSphere(invalid, &error));
        CHECK(error == "Metal world RLVa sphere state is invalid");
        invalid = scene;
        invalid.inverse_projection[0] =
            std::numeric_limits<float>::quiet_NaN();
        error.clear();
        CHECK_FALSE(renderer->renderRlvSphere(invalid, &error));
        CHECK(error == "Metal world RLVa sphere state is invalid");
    }
}

TEST_CASE("almetal: world CAS matches the standalone production kernel", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        auto renderer = ALMetalWorldGBufferRenderer::create(
            *device, &error);
        INFO(error);
        REQUIRE(renderer);

        constexpr std::uint32_t width = 5;
        constexpr std::uint32_t height = 5;
        std::array<std::uint32_t, width * height> input{};
        for (std::uint32_t y = 0; y < height; ++y)
        {
            for (std::uint32_t x = 0; x < width; ++x)
            {
                const std::uint32_t red =
                    64u + (x * 173u + y * 71u) % 800u;
                const std::uint32_t green =
                    96u + (x * 43u + y * 191u) % 800u;
                const std::uint32_t blue =
                    128u + (x * 127u + y * 53u) % 760u;
                input[y * width + x] = red | (green << 10u) |
                    (blue << 20u) | (3u << 30u);
            }
        }

        ALMetalRenderTargetDescriptor descriptor;
        descriptor.width = width;
        descriptor.height = height;
        descriptor.colors[0].format =
            ALMetalPixelFormat::rgb10a2_unorm;
        descriptor.label = "Alchemy world CAS test source";
        auto source = ALMetalRenderTarget::create(
            *device, descriptor, &error);
        INFO(error);
        REQUIRE(source);

        auto upload = device->makeCommandBuffer(
            "Alchemy world CAS test upload", &error);
        INFO(error);
        REQUIRE(upload);
        id<MTLBuffer> staging = [nativeDevice(*device)
            newBufferWithBytes:input.data()
                      length:sizeof(input)
                     options:MTLResourceStorageModeShared];
        REQUIRE(staging);
        id<MTLBlitCommandEncoder> blit =
            [nativeCommand(*upload) blitCommandEncoder];
        REQUIRE(blit);
        [blit copyFromBuffer:staging
                sourceOffset:0
           sourceBytesPerRow:width * sizeof(std::uint32_t)
         sourceBytesPerImage:sizeof(input)
                  sourceSize:MTLSizeMake(width, height, 1)
                   toTexture:(__bridge id<MTLTexture>)
                       source->colorTexture(0)->nativeHandle()
            destinationSlice:0
            destinationLevel:0
           destinationOrigin:MTLOriginMake(0, 0, 0)];
        [blit endEncoding];
        REQUIRE(upload->commit(&error));
        INFO(error);

        constexpr float sharpness = 0.4f;
        auto output = renderer->renderCAS(*source, sharpness, &error);
        INFO(error);
        REQUIRE(output);
        CHECK(output->descriptor().width == width);
        CHECK(output->descriptor().height == height);
        CHECK(output->descriptor().colors[0].format ==
              ALMetalPixelFormat::rgb10a2_unorm);

        std::array<std::uint32_t, width * height> actual{};
        REQUIRE(output->colorTexture(0)->readback(
            *device, 0, 0, {}, actual.data(),
            width * sizeof(std::uint32_t), &error));
        INFO(error);

        const auto bits_to_float = [](std::uint32_t bits)
        {
            float value = 0.f;
            std::memcpy(&value, &bits, sizeof(value));
            return value;
        };
        const auto float_to_bits = [](float value)
        {
            std::uint32_t bits = 0;
            std::memcpy(&bits, &value, sizeof(bits));
            return bits;
        };
        const auto low_reciprocal = [&](float value)
        {
            return bits_to_float(0x7ef07ebbu - float_to_bits(value));
        };
        const auto low_sqrt = [&](float value)
        {
            return bits_to_float(
                (float_to_bits(value) >> 1u) + 0x1fbc4639u);
        };
        const auto medium_reciprocal = [&](float value)
        {
            const float estimate = bits_to_float(
                0x7ef19fffu - float_to_bits(value));
            return estimate * (-estimate * value + 2.f);
        };
        const auto sample = [&](int x, int y, std::uint32_t channel)
        {
            x = std::clamp(x, 0, static_cast<int>(width) - 1);
            y = std::clamp(y, 0, static_cast<int>(height) - 1);
            return static_cast<float>(
                (input[static_cast<std::size_t>(y) * width +
                       static_cast<std::size_t>(x)] >> (channel * 10u)) &
                0x3ffu) / 1023.f;
        };
        const float peak = -1.f /
            (8.f + (5.f - 8.f) * sharpness);
        const auto oracle = [&](int x, int y, std::uint32_t channel)
        {
            const float a = sample(x - 1, y - 1, channel);
            const float b = sample(x,     y - 1, channel);
            const float c = sample(x + 1, y - 1, channel);
            const float d = sample(x - 1, y,     channel);
            const float e = sample(x,     y,     channel);
            const float f = sample(x + 1, y,     channel);
            const float g = sample(x - 1, y + 1, channel);
            const float h = sample(x,     y + 1, channel);
            const float i = sample(x + 1, y + 1, channel);
            float minimum = std::min({d, e, f, b, h});
            minimum += std::min({minimum, a, c, g, i});
            float maximum = std::max({d, e, f, b, h});
            maximum += std::max({maximum, a, c, g, i});
            float amplitude = std::clamp(
                std::min(minimum, 2.f - maximum) *
                    low_reciprocal(maximum),
                0.f, 1.f);
            amplitude = low_sqrt(amplitude);
            const float weight = amplitude * peak;
            const float reciprocal_weight = medium_reciprocal(
                1.f + 4.f * weight);
            return std::clamp(
                ((b + d + f + h) * weight + e) * reciprocal_weight,
                0.f, 1.f);
        };

        for (std::uint32_t y = 0; y < height; ++y)
        {
            for (std::uint32_t x = 0; x < width; ++x)
            {
                const std::uint32_t packed = actual[y * width + x];
                CAPTURE(x, y, packed);
                for (std::uint32_t channel = 0; channel < 3; ++channel)
                {
                    const int expected = static_cast<int>(std::lround(
                        oracle(static_cast<int>(x), static_cast<int>(y),
                               channel) * 1023.f));
                    const int observed = static_cast<int>(
                        (packed >> (channel * 10u)) & 0x3ffu);
                    CAPTURE(channel, expected, observed);
                    CHECK(std::abs(observed - expected) <= 1);
                }
                CHECK((packed >> 30u) == 0u);
            }
        }

        error.clear();
        CHECK_FALSE(renderer->renderCAS(*source, 0.f, &error));
        CHECK(error == "Metal world CAS state is invalid");

        ALMetalRenderTargetDescriptor wrong_descriptor = descriptor;
        wrong_descriptor.colors[0].format = ALMetalPixelFormat::rgba8_unorm;
        auto wrong_source = ALMetalRenderTarget::create(
            *device, wrong_descriptor, &error);
        INFO(error);
        REQUIRE(wrong_source);
        error.clear();
        CHECK_FALSE(renderer->renderCAS(
            *wrong_source, sharpness, &error));
        CHECK(error == "Metal world CAS source is incompatible");
    }
}

TEST_CASE("almetal: world FXAA matches every production quality preset", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        auto renderer = ALMetalWorldGBufferRenderer::create(
            *device, &error);
        INFO(error);
        REQUIRE(renderer);

        constexpr std::uint32_t width = 19;
        constexpr std::uint32_t height = 17;
        std::array<std::uint32_t, width * height> input{};
        for (std::uint32_t y = 0; y < height; ++y)
        {
            for (std::uint32_t x = 0; x < width; ++x)
            {
                const bool bright = x * 3u + y * 2u >= 31u;
                const std::uint32_t red = bright
                    ? 900u : 80u;
                const std::uint32_t green = bright
                    ? 750u : 60u;
                const std::uint32_t blue = bright
                    ? 600u : 100u;
                input[y * width + x] = red | (green << 10u) |
                    (blue << 20u) | (3u << 30u);
            }
        }

        ALMetalRenderTargetDescriptor descriptor;
        descriptor.width = width;
        descriptor.height = height;
        descriptor.colors[0].format =
            ALMetalPixelFormat::rgb10a2_unorm;
        descriptor.label = "Alchemy world FXAA test source";
        auto source = ALMetalRenderTarget::create(
            *device, descriptor, &error);
        INFO(error);
        REQUIRE(source);

        auto upload = device->makeCommandBuffer(
            "Alchemy world FXAA test upload", &error);
        INFO(error);
        REQUIRE(upload);
        id<MTLBuffer> staging = [nativeDevice(*device)
            newBufferWithBytes:input.data()
                      length:sizeof(input)
                     options:MTLResourceStorageModeShared];
        REQUIRE(staging);
        id<MTLBlitCommandEncoder> blit =
            [nativeCommand(*upload) blitCommandEncoder];
        REQUIRE(blit);
        [blit copyFromBuffer:staging
                sourceOffset:0
           sourceBytesPerRow:width * sizeof(std::uint32_t)
         sourceBytesPerImage:sizeof(input)
                  sourceSize:MTLSizeMake(width, height, 1)
                   toTexture:(__bridge id<MTLTexture>)
                       source->colorTexture(0)->nativeHandle()
            destinationSlice:0
            destinationLevel:0
           destinationOrigin:MTLOriginMake(0, 0, 0)];
        [blit endEncoding];
        REQUIRE(upload->commit(&error));
        INFO(error);

        using Color = std::array<float, 4>;
        const auto mirror = [](int coordinate, int size)
        {
            const int period = size * 2;
            coordinate %= period;
            if (coordinate < 0)
            {
                coordinate += period;
            }
            return coordinate < size
                ? coordinate : period - 1 - coordinate;
        };
        const auto texel = [&](int x, int y)
        {
            const std::uint32_t packed = input[
                static_cast<std::size_t>(mirror(y, height)) * width +
                static_cast<std::size_t>(mirror(x, width))];
            return Color{{
                static_cast<float>(packed & 0x3ffu) / 1023.f,
                static_cast<float>((packed >> 10u) & 0x3ffu) / 1023.f,
                static_cast<float>((packed >> 20u) & 0x3ffu) / 1023.f,
                static_cast<float>(packed >> 30u) / 3.f,
            }};
        };
        const auto sample = [&](float u, float v)
        {
            const float px = u * static_cast<float>(width) - 0.5f;
            const float py = v * static_cast<float>(height) - 0.5f;
            const int x0 = static_cast<int>(std::floor(px));
            const int y0 = static_cast<int>(std::floor(py));
            const float tx = px - static_cast<float>(x0);
            const float ty = py - static_cast<float>(y0);
            const Color c00 = texel(x0, y0);
            const Color c10 = texel(x0 + 1, y0);
            const Color c01 = texel(x0, y0 + 1);
            const Color c11 = texel(x0 + 1, y0 + 1);
            Color value{};
            for (std::size_t channel = 0; channel < value.size(); ++channel)
            {
                const float top = c00[channel] +
                    (c10[channel] - c00[channel]) * tx;
                const float bottom = c01[channel] +
                    (c11[channel] - c01[channel]) * tx;
                value[channel] = top + (bottom - top) * ty;
            }
            return value;
        };
        const auto luma = [](const Color& color)
        {
            return color[0] * 0.299f + color[1] * 0.587f +
                color[2] * 0.114f;
        };
        constexpr std::array<std::uint32_t, 4> step_counts{{
            5u, 6u, 11u, 12u,
        }};
        constexpr float steps[4][12] = {
            {1.f, 1.5f, 2.f, 4.f, 12.f},
            {1.f, 1.5f, 2.f, 2.f, 2.f, 8.f},
            {1.f, 1.5f, 2.f, 2.f, 2.f, 2.f, 2.f, 2.f, 2.f, 4.f, 8.f},
            {1.f, 1.f, 1.f, 1.f, 1.f, 1.5f, 2.f, 2.f, 2.f, 2.f, 4.f, 8.f},
        };
        const auto oracle = [&](std::uint32_t x, std::uint32_t y,
                                std::uint32_t quality)
        {
            const float reciprocal_x = 1.f / static_cast<float>(width);
            const float reciprocal_y = 1.f / static_cast<float>(height);
            float position_x = (static_cast<float>(x) + 0.5f) *
                reciprocal_x;
            float position_y = (static_cast<float>(y) + 0.5f) *
                reciprocal_y;
            const Color center = sample(position_x, position_y);
            const float luma_center = luma(center);
            float luma_south = luma(sample(
                position_x, position_y + reciprocal_y));
            const float luma_east = luma(sample(
                position_x + reciprocal_x, position_y));
            float luma_north = luma(sample(
                position_x, position_y - reciprocal_y));
            const float luma_west = luma(sample(
                position_x - reciprocal_x, position_y));
            const float range_max = std::max({
                luma_south, luma_east, luma_north, luma_west,
                luma_center});
            const float range_min = std::min({
                luma_south, luma_east, luma_north, luma_west,
                luma_center});
            const float range = range_max - range_min;
            if (range < std::max(0.03f, range_max * 0.07f))
            {
                return Color{{center[0], center[1], center[2],
                              luma_center}};
            }

            const float luma_nw = luma(sample(
                position_x - reciprocal_x, position_y - reciprocal_y));
            const float luma_se = luma(sample(
                position_x + reciprocal_x, position_y + reciprocal_y));
            const float luma_ne = luma(sample(
                position_x + reciprocal_x, position_y - reciprocal_y));
            const float luma_sw = luma(sample(
                position_x - reciprocal_x, position_y + reciprocal_y));
            const float luma_ns = luma_north + luma_south;
            const float luma_we = luma_west + luma_east;
            const float edge_horizontal =
                std::abs(-2.f * luma_west + luma_nw + luma_sw) +
                std::abs(-2.f * luma_center + luma_ns) * 2.f +
                std::abs(-2.f * luma_east + luma_ne + luma_se);
            const float edge_vertical =
                std::abs(-2.f * luma_south + luma_sw + luma_se) +
                std::abs(-2.f * luma_center + luma_we) * 2.f +
                std::abs(-2.f * luma_north + luma_nw + luma_ne);
            float length_sign = reciprocal_x;
            const bool horizontal_span =
                edge_horizontal >= edge_vertical;
            const float subpixel_a =
                (luma_ns + luma_we) * 2.f +
                luma_nw + luma_sw + luma_ne + luma_se;
            if (!horizontal_span)
            {
                luma_north = luma_west;
                luma_south = luma_east;
            }
            if (horizontal_span)
            {
                length_sign = reciprocal_y;
            }
            const float subpixel_b =
                subpixel_a * (1.f / 12.f) - luma_center;
            const float gradient_north = luma_north - luma_center;
            const float gradient_south = luma_south - luma_center;
            float luma_nn = luma_north + luma_center;
            const float luma_ss = luma_south + luma_center;
            const bool pair_north =
                std::abs(gradient_north) >= std::abs(gradient_south);
            const float gradient = std::max(
                std::abs(gradient_north), std::abs(gradient_south));
            if (pair_north)
            {
                length_sign = -length_sign;
            }
            const float subpixel_c = std::clamp(
                std::abs(subpixel_b) / range, 0.f, 1.f);
            float base_x = position_x;
            float base_y = position_y;
            const float offset_x = horizontal_span ? reciprocal_x : 0.f;
            const float offset_y = horizontal_span ? 0.f : reciprocal_y;
            if (!horizontal_span)
            {
                base_x += length_sign * 0.5f;
            }
            if (horizontal_span)
            {
                base_y += length_sign * 0.5f;
            }
            float north_x = base_x - offset_x * steps[quality][0];
            float north_y = base_y - offset_y * steps[quality][0];
            float south_x = base_x + offset_x * steps[quality][0];
            float south_y = base_y + offset_y * steps[quality][0];
            float luma_end_north = luma(sample(north_x, north_y));
            float luma_end_south = luma(sample(south_x, south_y));
            if (!pair_north)
            {
                luma_nn = luma_ss;
            }
            const float gradient_scaled = gradient * 0.25f;
            const bool luma_m_less_than_zero =
                luma_center - luma_nn * 0.5f < 0.f;
            luma_end_north -= luma_nn * 0.5f;
            luma_end_south -= luma_nn * 0.5f;
            bool done_north =
                std::abs(luma_end_north) >= gradient_scaled;
            bool done_south =
                std::abs(luma_end_south) >= gradient_scaled;
            for (std::uint32_t step = 1;
                 step < step_counts[quality]; ++step)
            {
                if (!done_north)
                {
                    north_x -= offset_x * steps[quality][step];
                    north_y -= offset_y * steps[quality][step];
                }
                if (!done_south)
                {
                    south_x += offset_x * steps[quality][step];
                    south_y += offset_y * steps[quality][step];
                }
                if (step + 1 == step_counts[quality] ||
                    (done_north && done_south))
                {
                    break;
                }
                if (!done_north)
                {
                    luma_end_north = luma(sample(north_x, north_y)) -
                        luma_nn * 0.5f;
                }
                if (!done_south)
                {
                    luma_end_south = luma(sample(south_x, south_y)) -
                        luma_nn * 0.5f;
                }
                done_north =
                    std::abs(luma_end_north) >= gradient_scaled;
                done_south =
                    std::abs(luma_end_south) >= gradient_scaled;
            }
            float distance_north = position_x - north_x;
            float distance_south = south_x - position_x;
            if (!horizontal_span)
            {
                distance_north = position_y - north_y;
                distance_south = south_y - position_y;
            }
            const bool good_span_north =
                (luma_end_north < 0.f) != luma_m_less_than_zero;
            const bool good_span_south =
                (luma_end_south < 0.f) != luma_m_less_than_zero;
            const bool good_span = distance_north < distance_south
                ? good_span_north : good_span_south;
            const float pixel_offset =
                std::min(distance_north, distance_south) *
                    (-1.f / (distance_south + distance_north)) + 0.5f;
            const float subpixel_c2 = subpixel_c * subpixel_c;
            const float subpixel_f =
                (-2.f * subpixel_c + 3.f) * subpixel_c2;
            const float subpixel_h =
                subpixel_f * subpixel_f * 0.75f;
            const float final_offset = std::max(
                good_span ? pixel_offset : 0.f, subpixel_h);
            if (!horizontal_span)
            {
                position_x += final_offset * length_sign;
            }
            if (horizontal_span)
            {
                position_y += final_offset * length_sign;
            }
            Color result = sample(position_x, position_y);
            result[3] = luma_center;
            return result;
        };

        std::array<std::array<std::uint32_t, width * height>, 4> actual{};
        for (std::uint32_t quality = 0; quality < 4; ++quality)
        {
            auto output = renderer->renderFXAA(
                *source, quality, &error);
            INFO(error);
            REQUIRE(output);
            CHECK(output->descriptor().width == width);
            CHECK(output->descriptor().height == height);
            CHECK(output->descriptor().colors[0].format ==
                  ALMetalPixelFormat::rgb10a2_unorm);
            REQUIRE(output->colorTexture(0)->readback(
                *device, 0, 0, {}, actual[quality].data(),
                width * sizeof(std::uint32_t), &error));
            INFO(error);
            for (std::uint32_t y = 0; y < height; ++y)
            {
                for (std::uint32_t x = 0; x < width; ++x)
                {
                    const Color expected = oracle(x, y, quality);
                    const std::uint32_t packed =
                        actual[quality][y * width + x];
                    CAPTURE(quality, x, y, packed);
                    for (std::uint32_t channel = 0; channel < 3; ++channel)
                    {
                        const int expected_unorm = static_cast<int>(
                            std::lround(expected[channel] * 1023.f));
                        const int observed = static_cast<int>(
                            (packed >> (channel * 10u)) & 0x3ffu);
                        CAPTURE(channel, expected_unorm, observed);
                        CHECK(std::abs(observed - expected_unorm) <= 2);
                    }
                    const int expected_alpha = static_cast<int>(
                        std::lround(expected[3] * 3.f));
                    CHECK(static_cast<int>(packed >> 30u) ==
                          expected_alpha);
                }
            }
        }

        CHECK(std::mismatch(
                  actual.front().begin(), actual.front().end(),
                  actual.back().begin()).first != actual.front().end());

        error.clear();
        CHECK_FALSE(renderer->renderFXAA(*source, 4, &error));
        CHECK(error == "Metal world FXAA state is invalid");

        ALMetalRenderTargetDescriptor wrong_descriptor = descriptor;
        wrong_descriptor.colors[0].format =
            ALMetalPixelFormat::rgba8_unorm;
        auto wrong_source = ALMetalRenderTarget::create(
            *device, wrong_descriptor, &error);
        INFO(error);
        REQUIRE(wrong_source);
        error.clear();
        CHECK_FALSE(renderer->renderFXAA(*wrong_source, 0, &error));
        CHECK(error == "Metal world FXAA source is incompatible");
    }
}

TEST_CASE("almetal: world SMAA edge and complete transaction match reference", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        auto renderer = ALMetalWorldGBufferRenderer::create(
            *device, &error);
        INFO(error);
        REQUIRE(renderer);

        constexpr std::uint32_t width = 13;
        constexpr std::uint32_t height = 11;
        std::array<std::uint32_t, width * height> input{};
        std::array<float, width * height> depth{};
        for (std::uint32_t y = 0; y < height; ++y)
        {
            for (std::uint32_t x = 0; x < width; ++x)
            {
                std::uint32_t value = 100u;
                if (x >= 6)
                {
                    value += 80u;
                }
                if (y >= 5)
                {
                    value += 170u;
                }
                input[y * width + x] = value | (value << 10u) |
                    (value << 20u) | (3u << 30u);
                depth[y * width + x] = x >= 6 ? 0.8f : 0.2f;
            }
        }

        ALMetalRenderTargetDescriptor descriptor;
        descriptor.width = width;
        descriptor.height = height;
        descriptor.colors[0].format =
            ALMetalPixelFormat::rgb10a2_unorm;
        descriptor.label = "Alchemy world SMAA edge test source";
        auto source = ALMetalRenderTarget::create(
            *device, descriptor, &error);
        INFO(error);
        REQUIRE(source);

        ALMetalTextureDescriptor depth_descriptor;
        depth_descriptor.width = width;
        depth_descriptor.height = height;
        depth_descriptor.format = ALMetalPixelFormat::depth32_float;
        depth_descriptor.storage = ALMetalStorageMode::private_gpu;
        depth_descriptor.usage = ALMetalTextureUsage::shader_read;
        depth_descriptor.label = "Alchemy world SMAA predication test depth";
        auto predication = ALMetalTexture::create(
            *device, depth_descriptor, &error);
        INFO(error);
        REQUIRE(predication);

        auto upload = device->makeCommandBuffer(
            "Alchemy world SMAA edge test upload", &error);
        INFO(error);
        REQUIRE(upload);
        REQUIRE(predication->upload(
            *upload, 0, 0, {}, depth.data(), width * sizeof(float),
            &error));
        id<MTLBuffer> staging = [nativeDevice(*device)
            newBufferWithBytes:input.data()
                      length:sizeof(input)
                     options:MTLResourceStorageModeShared];
        REQUIRE(staging);
        id<MTLBlitCommandEncoder> blit =
            [nativeCommand(*upload) blitCommandEncoder];
        REQUIRE(blit);
        [blit copyFromBuffer:staging
                sourceOffset:0
           sourceBytesPerRow:width * sizeof(std::uint32_t)
         sourceBytesPerImage:sizeof(input)
                  sourceSize:MTLSizeMake(width, height, 1)
                   toTexture:(__bridge id<MTLTexture>)
                       source->colorTexture(0)->nativeHandle()
            destinationSlice:0
            destinationLevel:0
           destinationOrigin:MTLOriginMake(0, 0, 0)];
        [blit endEncoding];
        REQUIRE(upload->commitAndWait(&error));
        INFO(error);

        const auto clamp_x = [](int value)
        {
            return std::clamp(value, 0, static_cast<int>(width) - 1);
        };
        const auto clamp_y = [](int value)
        {
            return std::clamp(value, 0, static_cast<int>(height) - 1);
        };
        const auto color = [&](int x, int y, std::uint32_t channel)
        {
            const std::uint32_t packed = input[
                static_cast<std::size_t>(clamp_y(y)) * width +
                static_cast<std::size_t>(clamp_x(x))];
            return static_cast<float>(
                (packed >> (channel * 10u)) & 0x3ffu) / 1023.f;
        };
        const auto depth_value = [&](int x, int y)
        {
            return depth[static_cast<std::size_t>(clamp_y(y)) * width +
                         static_cast<std::size_t>(clamp_x(x))];
        };
        const auto color_delta = [&](int x0, int y0, int x1, int y1)
        {
            float maximum = 0.f;
            for (std::uint32_t channel = 0; channel < 3; ++channel)
            {
                maximum = std::max(maximum, std::abs(
                    color(x0, y0, channel) -
                    color(x1, y1, channel)));
            }
            return maximum;
        };
        constexpr std::array<float, 4> thresholds{{
            0.15f, 0.10f, 0.10f, 0.05f,
        }};
        const auto oracle = [&](int x, int y, std::uint32_t quality,
                                bool predicated)
        {
            float threshold_x = thresholds[quality];
            float threshold_y = thresholds[quality];
            if (predicated)
            {
                const float center = depth_value(x, y);
                const float pred_x = std::abs(
                    center - depth_value(x - 1, y)) >= 0.002f
                    ? 1.f : 0.f;
                const float pred_y = std::abs(
                    center - depth_value(x, y + 1)) >= 0.002f
                    ? 1.f : 0.f;
                threshold_x = 2.f * thresholds[quality] *
                    (1.f - 0.8f * pred_x);
                threshold_y = 2.f * thresholds[quality] *
                    (1.f - 0.8f * pred_y);
            }

            const float delta_x = color_delta(x, y, x - 1, y);
            const float delta_y = color_delta(x, y, x, y + 1);
            float edge_x = delta_x >= threshold_x ? 1.f : 0.f;
            float edge_y = delta_y >= threshold_y ? 1.f : 0.f;
            if (edge_x + edge_y == 0.f)
            {
                return std::array<std::uint8_t, 4>{{0, 0, 0, 0}};
            }

            const float delta_right = color_delta(x, y, x + 1, y);
            const float delta_bottom = color_delta(x, y, x, y - 1);
            float max_x = std::max(delta_x, delta_right);
            float max_y = std::max(delta_y, delta_bottom);
            const float delta_left_left =
                color_delta(x, y, x - 2, y);
            const float delta_top_top =
                color_delta(x, y, x, y + 2);
            max_x = std::max(max_x, delta_left_left);
            max_y = std::max(max_y, delta_top_top);
            const float final_delta = std::max(max_x, max_y);
            edge_x *= 2.f * delta_x >= final_delta ? 1.f : 0.f;
            edge_y *= 2.f * delta_y >= final_delta ? 1.f : 0.f;
            return std::array<std::uint8_t, 4>{{
                static_cast<std::uint8_t>(edge_x * 255.f),
                static_cast<std::uint8_t>(edge_y * 255.f), 0, 0,
            }};
        };

        const auto check_output = [&](const ALMetalRenderTarget& output,
                                      std::uint32_t quality,
                                      bool predicated)
        {
            CHECK(output.descriptor().width == width);
            CHECK(output.descriptor().height == height);
            CHECK(output.descriptor().colors[0].format ==
                  ALMetalPixelFormat::rgba8_unorm);
            std::array<std::uint8_t, width * height * 4> actual{};
            REQUIRE(output.colorTexture(0)->readback(
                *device, 0, 0, {}, actual.data(), width * 4, &error));
            INFO(error);
            for (std::uint32_t y = 0; y < height; ++y)
            {
                for (std::uint32_t x = 0; x < width; ++x)
                {
                    const auto expected = oracle(
                        static_cast<int>(x), static_cast<int>(y),
                        quality, predicated);
                    CAPTURE(quality, predicated, x, y);
                    for (std::size_t channel = 0;
                         channel < expected.size(); ++channel)
                    {
                        CAPTURE(channel, expected[channel],
                                actual[(y * width + x) * 4 + channel]);
                        CHECK(actual[(y * width + x) * 4 + channel] ==
                              expected[channel]);
                    }
                }
            }
        };

        for (std::uint32_t quality = 0; quality < 4; ++quality)
        {
            ALMetalWorldSMAAEdgeScene scene;
            scene.source = source.get();
            scene.quality = quality;
            auto output = renderer->renderSMAAEdges(scene, &error);
            INFO(error);
            REQUIRE(output);
            check_output(*output, quality, false);
        }

        ALMetalWorldSMAAEdgeScene predicated_scene;
        predicated_scene.source = source.get();
        predicated_scene.predication_texture = predication.get();
        predicated_scene.quality = 1;
        predicated_scene.predication_threshold = 0.002f;
        predicated_scene.predication_scale = 2.f;
        predicated_scene.predication_strength = 0.8f;
        auto predicated_output = renderer->renderSMAAEdges(
            predicated_scene, &error);
        INFO(error);
        REQUIRE(predicated_output);
        check_output(*predicated_output, 1, true);

        // Compose the already oracle-checked stages independently, then
        // prove the production transaction publishes that exact final image.
        ALMetalWorldSMAAWeightScene staged_weight_scene;
        staged_weight_scene.edges = predicated_output.get();
        staged_weight_scene.quality = predicated_scene.quality;
        auto staged_weights = renderer->renderSMAABlendWeights(
            staged_weight_scene, &error);
        INFO(error);
        REQUIRE(staged_weights);
        ALMetalWorldSMAANeighborhoodScene staged_neighborhood_scene;
        staged_neighborhood_scene.source = source.get();
        staged_neighborhood_scene.weights = staged_weights.get();
        auto staged_output = renderer->renderSMAANeighborhood(
            staged_neighborhood_scene, &error);
        INFO(error);
        REQUIRE(staged_output);

        ALMetalWorldSMAAScene complete_scene;
        complete_scene.source = source.get();
        complete_scene.predication_texture = predication.get();
        complete_scene.quality = predicated_scene.quality;
        complete_scene.predication_threshold =
            predicated_scene.predication_threshold;
        complete_scene.predication_scale =
            predicated_scene.predication_scale;
        complete_scene.predication_strength =
            predicated_scene.predication_strength;
        auto complete_output = renderer->renderSMAA(
            complete_scene, &error);
        INFO(error);
        REQUIRE(complete_output);
        CHECK(complete_output->descriptor().width == width);
        CHECK(complete_output->descriptor().height == height);
        CHECK(complete_output->descriptor().colors[0].format ==
              ALMetalPixelFormat::rgb10a2_unorm);
        std::array<std::uint32_t, width * height> staged_bytes{};
        std::array<std::uint32_t, width * height> complete_bytes{};
        REQUIRE(staged_output->colorTexture(0)->readback(
            *device, 0, 0, {}, staged_bytes.data(),
            width * sizeof(std::uint32_t), &error));
        INFO(error);
        REQUIRE(complete_output->colorTexture(0)->readback(
            *device, 0, 0, {}, complete_bytes.data(),
            width * sizeof(std::uint32_t), &error));
        INFO(error);
        CHECK(complete_bytes == staged_bytes);

        ALMetalWorldSMAAScene invalid_complete;
        error.clear();
        CHECK_FALSE(renderer->renderSMAA(invalid_complete, &error));
        CHECK(error == "Metal world SMAA edge scene is incomplete");
        invalid_complete.source = source.get();
        invalid_complete.quality = 4;
        error.clear();
        CHECK_FALSE(renderer->renderSMAA(invalid_complete, &error));
        CHECK(error == "Metal world SMAA edge state is invalid");

        ALMetalWorldSMAAEdgeScene invalid;
        error.clear();
        CHECK_FALSE(renderer->renderSMAAEdges(invalid, &error));
        CHECK(error == "Metal world SMAA edge scene is incomplete");
        invalid.source = source.get();
        invalid.quality = 4;
        error.clear();
        CHECK_FALSE(renderer->renderSMAAEdges(invalid, &error));
        CHECK(error == "Metal world SMAA edge state is invalid");
        invalid.quality = 0;
        invalid.predication_scale = 0.f;
        error.clear();
        CHECK_FALSE(renderer->renderSMAAEdges(invalid, &error));
        CHECK(error == "Metal world SMAA edge state is invalid");

        ALMetalTextureDescriptor wrong_predication_descriptor =
            depth_descriptor;
        wrong_predication_descriptor.format =
            ALMetalPixelFormat::r32_float;
        auto wrong_predication = ALMetalTexture::create(
            *device, wrong_predication_descriptor, &error);
        INFO(error);
        REQUIRE(wrong_predication);
        invalid.predication_scale = 2.f;
        invalid.predication_texture = wrong_predication.get();
        error.clear();
        CHECK_FALSE(renderer->renderSMAAEdges(invalid, &error));
        CHECK(error ==
              "Metal world SMAA predication texture is incompatible");
    }
}

TEST_CASE("almetal: world SMAA blending weights match lookup reference", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        auto renderer = ALMetalWorldGBufferRenderer::create(
            *device, &error);
        INFO(error);
        REQUIRE(renderer);

        constexpr std::uint32_t width = 33;
        constexpr std::uint32_t height = 31;
        std::vector<std::uint8_t> edge_bytes(width * height * 4, 0);
        const auto mark = [&](std::uint32_t x, std::uint32_t y,
                              bool west, bool north)
        {
            std::uint8_t* pixel = edge_bytes.data() +
                (static_cast<std::size_t>(y) * width + x) * 4;
            pixel[0] = west ? 255 : pixel[0];
            pixel[1] = north ? 255 : pixel[1];
        };
        for (std::uint32_t x = 3; x < 30; ++x)
        {
            mark(x, 15, false, true);
        }
        for (std::uint32_t y = 2; y < 29; ++y)
        {
            mark(16, y, true, false);
        }
        for (std::uint32_t step = 5; step < 26; ++step)
        {
            mark(step, step - 2, true, true);
            mark(32 - step, step, true, true);
        }
        for (std::uint32_t x = 7; x < 14; ++x)
        {
            mark(x, 8, false, true);
        }
        for (std::uint32_t y = 8; y < 14; ++y)
        {
            mark(7, y, true, false);
        }

        ALMetalRenderTargetDescriptor edge_descriptor;
        edge_descriptor.width = width;
        edge_descriptor.height = height;
        edge_descriptor.colors[0].format =
            ALMetalPixelFormat::rgba8_unorm;
        edge_descriptor.label = "Alchemy world SMAA weight test edges";
        auto edges = ALMetalRenderTarget::create(
            *device, edge_descriptor, &error);
        INFO(error);
        REQUIRE(edges);
        auto upload = device->makeCommandBuffer(
            "Alchemy world SMAA weight test upload", &error);
        INFO(error);
        REQUIRE(upload);
        id<MTLBuffer> staging = [nativeDevice(*device)
            newBufferWithBytes:edge_bytes.data()
                      length:edge_bytes.size()
                     options:MTLResourceStorageModeShared];
        REQUIRE(staging);
        id<MTLBlitCommandEncoder> blit =
            [nativeCommand(*upload) blitCommandEncoder];
        REQUIRE(blit);
        [blit copyFromBuffer:staging
                sourceOffset:0
           sourceBytesPerRow:width * 4
         sourceBytesPerImage:edge_bytes.size()
                  sourceSize:MTLSizeMake(width, height, 1)
                   toTexture:(__bridge id<MTLTexture>)
                       edges->colorTexture(0)->nativeHandle()
            destinationSlice:0
            destinationLevel:0
           destinationOrigin:MTLOriginMake(0, 0, 0)];
        [blit endEncoding];
        REQUIRE(upload->commitAndWait(&error));
        INFO(error);

        std::vector<std::uint8_t> area_lookup(AREATEX_SIZE);
        for (std::uint32_t row = 0; row < AREATEX_HEIGHT; ++row)
        {
            const std::uint32_t source_row = AREATEX_HEIGHT - 1u - row;
            std::memcpy(area_lookup.data() + row * AREATEX_PITCH,
                        areaTexBytes + source_row * AREATEX_PITCH,
                        AREATEX_PITCH);
        }
        std::vector<std::uint8_t> search_lookup(SEARCHTEX_SIZE);
        for (std::uint32_t row = 0; row < SEARCHTEX_HEIGHT; ++row)
        {
            const std::uint32_t source_row = SEARCHTEX_HEIGHT - 1u - row;
            std::memcpy(search_lookup.data() + row * SEARCHTEX_PITCH,
                        searchTexBytes + source_row * SEARCHTEX_PITCH,
                        SEARCHTEX_PITCH);
        }
        const SMAAWeightOracle oracle{
            width, height, edge_bytes, area_lookup, search_lookup,
        };

        std::array<std::vector<std::uint8_t>, 4> results;
        for (std::uint32_t quality = 0; quality < 4; ++quality)
        {
            ALMetalWorldSMAAWeightScene scene;
            scene.edges = edges.get();
            scene.quality = quality;
            auto output = renderer->renderSMAABlendWeights(scene, &error);
            INFO(error);
            REQUIRE(output);
            CHECK(output->descriptor().width == width);
            CHECK(output->descriptor().height == height);
            CHECK(output->descriptor().colors[0].format ==
                  ALMetalPixelFormat::rgba8_unorm);
            results[quality].resize(width * height * 4);
            REQUIRE(output->colorTexture(0)->readback(
                *device, 0, 0, {}, results[quality].data(), width * 4,
                &error));
            INFO(error);

            std::array<std::size_t, 4> nonzero{};
            for (std::uint32_t y = 0; y < height; ++y)
            {
                for (std::uint32_t x = 0; x < width; ++x)
                {
                    const SMAAVec4 expected = oracle.pixel(x, y, quality);
                    const std::array<float, 4> channels{{
                        expected.x, expected.y, expected.z, expected.w,
                    }};
                    for (std::size_t channel = 0;
                         channel < channels.size(); ++channel)
                    {
                        const int expected_byte = static_cast<int>(
                            std::lround(std::clamp(
                                channels[channel], 0.f, 1.f) * 255.f));
                        const int actual = results[quality][
                            (static_cast<std::size_t>(y) * width + x) * 4 +
                            channel];
                        CAPTURE(quality, x, y, channel,
                                expected_byte, actual);
                        CHECK(std::abs(actual - expected_byte) <= 1);
                        nonzero[channel] += actual != 0 ? 1 : 0;
                    }
                }
            }
            CAPTURE(quality, nonzero[0], nonzero[1],
                    nonzero[2], nonzero[3]);
            for (std::size_t channel = 0; channel < nonzero.size(); ++channel)
            {
                CAPTURE(channel);
                CHECK(nonzero[channel] > 0);
            }
        }
        CHECK(results[0] != results[1]);
        CHECK(results[1] != results[2]);
        CHECK(results[2] != results[3]);

        ALMetalWorldSMAAWeightScene invalid;
        error.clear();
        CHECK_FALSE(renderer->renderSMAABlendWeights(invalid, &error));
        CHECK(error == "Metal world SMAA weight scene is incomplete");
        invalid.edges = edges.get();
        invalid.quality = 4;
        error.clear();
        CHECK_FALSE(renderer->renderSMAABlendWeights(invalid, &error));
        CHECK(error == "Metal world SMAA weight state is invalid");

        ALMetalRenderTargetDescriptor wrong_descriptor = edge_descriptor;
        wrong_descriptor.colors[0].format =
            ALMetalPixelFormat::rgb10a2_unorm;
        auto wrong_edges = ALMetalRenderTarget::create(
            *device, wrong_descriptor, &error);
        INFO(error);
        REQUIRE(wrong_edges);
        invalid.quality = 0;
        invalid.edges = wrong_edges.get();
        error.clear();
        CHECK_FALSE(renderer->renderSMAABlendWeights(invalid, &error));
        CHECK(error == "Metal world SMAA edge target is incompatible");
    }
}

TEST_CASE("almetal: world SMAA neighborhood blend matches linear-light reference", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        auto renderer = ALMetalWorldGBufferRenderer::create(
            *device, &error);
        INFO(error);
        REQUIRE(renderer);

        constexpr std::uint32_t width = 11;
        constexpr std::uint32_t height = 9;
        std::array<std::uint32_t, width * height> source_bytes{};
        std::array<std::uint8_t, width * height * 4> weight_bytes{};
        for (std::uint32_t y = 0; y < height; ++y)
        {
            for (std::uint32_t x = 0; x < width; ++x)
            {
                const std::uint32_t red = (37u + x * 71u + y * 19u) & 1023u;
                const std::uint32_t green = (91u + x * 23u + y * 83u) & 1023u;
                const std::uint32_t blue = (13u + x * 47u + y * 41u) & 1023u;
                const std::uint32_t alpha = (x + 2u * y) & 3u;
                source_bytes[y * width + x] =
                    red | (green << 10u) | (blue << 20u) | (alpha << 30u);
                std::uint8_t* weight = weight_bytes.data() +
                    (static_cast<std::size_t>(y) * width + x) * 4;
                weight[0] = static_cast<std::uint8_t>(
                    (17u + x * 31u + y * 11u) & 255u);
                weight[1] = static_cast<std::uint8_t>(
                    (29u + x * 7u + y * 37u) & 255u);
                weight[2] = static_cast<std::uint8_t>(
                    (43u + x * 19u + y * 13u) & 255u);
                weight[3] = static_cast<std::uint8_t>(
                    (61u + x * 5u + y * 23u) & 255u);
            }
        }
        for (std::uint32_t y = 3; y <= 5; ++y)
        {
            for (std::uint32_t x = 4; x <= 6; ++x)
            {
                std::fill_n(weight_bytes.data() +
                    (static_cast<std::size_t>(y) * width + x) * 4,
                    4, static_cast<std::uint8_t>(0));
            }
        }

        ALMetalRenderTargetDescriptor source_descriptor;
        source_descriptor.width = width;
        source_descriptor.height = height;
        source_descriptor.colors[0].format =
            ALMetalPixelFormat::rgb10a2_unorm;
        source_descriptor.label = "Alchemy SMAA neighborhood test source";
        auto source = ALMetalRenderTarget::create(
            *device, source_descriptor, &error);
        INFO(error);
        REQUIRE(source);
        ALMetalRenderTargetDescriptor weight_descriptor;
        weight_descriptor.width = width;
        weight_descriptor.height = height;
        weight_descriptor.colors[0].format =
            ALMetalPixelFormat::rgba8_unorm;
        weight_descriptor.label = "Alchemy SMAA neighborhood test weights";
        auto weights = ALMetalRenderTarget::create(
            *device, weight_descriptor, &error);
        INFO(error);
        REQUIRE(weights);

        auto upload = device->makeCommandBuffer(
            "Alchemy SMAA neighborhood test upload", &error);
        INFO(error);
        REQUIRE(upload);
        id<MTLBuffer> source_staging = [nativeDevice(*device)
            newBufferWithBytes:source_bytes.data()
                      length:sizeof(source_bytes)
                     options:MTLResourceStorageModeShared];
        id<MTLBuffer> weight_staging = [nativeDevice(*device)
            newBufferWithBytes:weight_bytes.data()
                      length:sizeof(weight_bytes)
                     options:MTLResourceStorageModeShared];
        REQUIRE(source_staging);
        REQUIRE(weight_staging);
        id<MTLBlitCommandEncoder> blit =
            [nativeCommand(*upload) blitCommandEncoder];
        REQUIRE(blit);
        [blit copyFromBuffer:source_staging
                sourceOffset:0
           sourceBytesPerRow:width * sizeof(std::uint32_t)
         sourceBytesPerImage:sizeof(source_bytes)
                  sourceSize:MTLSizeMake(width, height, 1)
                   toTexture:(__bridge id<MTLTexture>)
                       source->colorTexture(0)->nativeHandle()
            destinationSlice:0
            destinationLevel:0
           destinationOrigin:MTLOriginMake(0, 0, 0)];
        [blit copyFromBuffer:weight_staging
                sourceOffset:0
           sourceBytesPerRow:width * 4
         sourceBytesPerImage:sizeof(weight_bytes)
                  sourceSize:MTLSizeMake(width, height, 1)
                   toTexture:(__bridge id<MTLTexture>)
                       weights->colorTexture(0)->nativeHandle()
            destinationSlice:0
            destinationLevel:0
           destinationOrigin:MTLOriginMake(0, 0, 0)];
        [blit endEncoding];
        REQUIRE(upload->commitAndWait(&error));
        INFO(error);

        ALMetalWorldSMAANeighborhoodScene scene;
        scene.source = source.get();
        scene.weights = weights.get();
        auto output = renderer->renderSMAANeighborhood(scene, &error);
        INFO(error);
        REQUIRE(output);
        CHECK(output->descriptor().width == width);
        CHECK(output->descriptor().height == height);
        CHECK(output->descriptor().colors[0].format ==
              ALMetalPixelFormat::rgb10a2_unorm);
        std::array<std::uint32_t, width * height> actual{};
        REQUIRE(output->colorTexture(0)->readback(
            *device, 0, 0, {}, actual.data(),
            width * sizeof(std::uint32_t), &error));
        INFO(error);

        const auto mirror_index = [](int index, int size)
        {
            if (index < 0)
            {
                return -index - 1;
            }
            if (index >= size)
            {
                return 2 * size - index - 1;
            }
            return index;
        };
        const auto weight = [&](int x, int y, std::uint32_t channel)
        {
            x = mirror_index(x, static_cast<int>(width));
            y = mirror_index(y, static_cast<int>(height));
            return weight_bytes[
                (static_cast<std::size_t>(y) * width + x) * 4 + channel] /
                255.f;
        };
        const auto unpack = [](std::uint32_t packed)
        {
            return std::array<float, 4>{{
                static_cast<float>(packed & 1023u) / 1023.f,
                static_cast<float>((packed >> 10u) & 1023u) / 1023.f,
                static_cast<float>((packed >> 20u) & 1023u) / 1023.f,
                static_cast<float>((packed >> 30u) & 3u) / 3.f,
            }};
        };
        const auto sample_source = [&](float x, float y)
        {
            x = std::clamp(x, 0.f, static_cast<float>(width - 1));
            y = std::clamp(y, 0.f, static_cast<float>(height - 1));
            const int x0 = static_cast<int>(std::floor(x));
            const int y0 = static_cast<int>(std::floor(y));
            const int x1 = std::min(x0 + 1, static_cast<int>(width) - 1);
            const int y1 = std::min(y0 + 1, static_cast<int>(height) - 1);
            const float fraction_x = x - x0;
            const float fraction_y = y - y0;
            const auto top_left = unpack(source_bytes[y0 * width + x0]);
            const auto top_right = unpack(source_bytes[y0 * width + x1]);
            const auto bottom_left = unpack(source_bytes[y1 * width + x0]);
            const auto bottom_right = unpack(source_bytes[y1 * width + x1]);
            std::array<float, 4> result{};
            for (std::size_t channel = 0; channel < result.size(); ++channel)
            {
                result[channel] = std::lerp(
                    std::lerp(top_left[channel], top_right[channel], fraction_x),
                    std::lerp(bottom_left[channel], bottom_right[channel], fraction_x),
                    fraction_y);
            }
            return result;
        };
        const auto to_linear = [](float encoded)
        {
            return encoded <= 0.04045f
                ? encoded / 12.92f
                : std::pow((encoded + 0.055f) / 1.055f, 2.4f);
        };
        const auto to_srgb = [](float linear)
        {
            return linear < 0.0031308f
                ? linear * 12.92f
                : 1.055f * std::pow(linear, 0.41666f) - 0.055f;
        };

        std::size_t horizontal_count = 0;
        std::size_t vertical_count = 0;
        std::size_t copy_count = 0;
        for (std::uint32_t y = 0; y < height; ++y)
        {
            for (std::uint32_t x = 0; x < width; ++x)
            {
                const float right = weight(x + 1, y, 3);
                const float top = weight(x, static_cast<int>(y) - 1, 1);
                const float bottom = weight(x, y, 0);
                const float left = weight(x, y, 2);
                const float total = right + top + left + bottom;
                std::array<float, 4> expected{};
                if (total < 1e-5f)
                {
                    expected = sample_source(x, y);
                    for (std::size_t channel = 0; channel < 3; ++channel)
                    {
                        expected[channel] = to_srgb(
                            to_linear(expected[channel]));
                    }
                    ++copy_count;
                }
                else
                {
                    const bool horizontal = std::max(right, left) >
                        std::max(top, bottom);
                    const float first_weight = horizontal ? right : top;
                    const float second_weight = horizontal ? left : bottom;
                    const float normalization = first_weight + second_weight;
                    const float first = first_weight / normalization;
                    const float second = second_weight / normalization;
                    const auto first_color = horizontal
                        ? sample_source(x + right, y)
                        : sample_source(x, y - top);
                    const auto second_color = horizontal
                        ? sample_source(x - left, y)
                        : sample_source(x, y + bottom);
                    for (std::size_t channel = 0; channel < 3; ++channel)
                    {
                        expected[channel] = to_srgb(
                            first * to_linear(first_color[channel]) +
                            second * to_linear(second_color[channel]));
                    }
                    expected[3] = first * first_color[3] +
                        second * second_color[3];
                    horizontal_count += horizontal ? 1 : 0;
                    vertical_count += horizontal ? 0 : 1;
                }

                const std::uint32_t packed = actual[y * width + x];
                const std::array<int, 4> actual_channels{{
                    static_cast<int>(packed & 1023u),
                    static_cast<int>((packed >> 10u) & 1023u),
                    static_cast<int>((packed >> 20u) & 1023u),
                    static_cast<int>((packed >> 30u) & 3u),
                }};
                const std::array<int, 4> expected_channels{{
                    static_cast<int>(std::lround(std::clamp(
                        expected[0], 0.f, 1.f) * 1023.f)),
                    static_cast<int>(std::lround(std::clamp(
                        expected[1], 0.f, 1.f) * 1023.f)),
                    static_cast<int>(std::lround(std::clamp(
                        expected[2], 0.f, 1.f) * 1023.f)),
                    static_cast<int>(std::lround(std::clamp(
                        expected[3], 0.f, 1.f) * 3.f)),
                }};
                CAPTURE(x, y);
                for (std::size_t channel = 0; channel < 4; ++channel)
                {
                    CAPTURE(channel, expected_channels[channel],
                            actual_channels[channel]);
                    CHECK(std::abs(actual_channels[channel] -
                                   expected_channels[channel]) <= 1);
                }
            }
        }
        CHECK(horizontal_count > 0);
        CHECK(vertical_count > 0);
        CHECK(copy_count > 0);

        ALMetalWorldSMAANeighborhoodScene invalid;
        error.clear();
        CHECK_FALSE(renderer->renderSMAANeighborhood(invalid, &error));
        CHECK(error == "Metal world SMAA neighborhood scene is incomplete");
        invalid.source = source.get();
        invalid.weights = source.get();
        error.clear();
        CHECK_FALSE(renderer->renderSMAANeighborhood(invalid, &error));
        CHECK(error == "Metal world SMAA weight target is incompatible");
        invalid.source = weights.get();
        invalid.weights = weights.get();
        error.clear();
        CHECK_FALSE(renderer->renderSMAANeighborhood(invalid, &error));
        CHECK(error == "Metal world SMAA neighborhood source is incompatible");
    }
}

TEST_CASE("almetal: world depth of field matches the HDR gather and combine reference", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        auto renderer = ALMetalWorldGBufferRenderer::create(
            *device, &error);
        INFO(error);
        REQUIRE(renderer);

        constexpr std::uint32_t width = 9;
        constexpr std::uint32_t height = 7;
        constexpr std::array<std::uint16_t, 7> levels{{
            0x3000u, 0x3400u, 0x3800u, 0x3c00u,
            0x4000u, 0x4400u, 0x4800u,
        }}; // 0.125, 0.25, 0.5, 1, 2, 4, 8.
        std::array<std::uint16_t, width * height * 4> source_pixels{};
        std::array<float, width * height> depth_pixels{};
        for (std::uint32_t y = 0; y < height; ++y)
        {
            for (std::uint32_t x = 0; x < width; ++x)
            {
                const std::size_t pixel =
                    static_cast<std::size_t>(y) * width + x;
                source_pixels[pixel * 4 + 0] =
                    levels[(x * 3u + y) % levels.size()];
                source_pixels[pixel * 4 + 1] =
                    levels[(x + y * 2u + 1u) % levels.size()];
                source_pixels[pixel * 4 + 2] =
                    levels[(x * 2u + y * 3u + 2u) % levels.size()];
                source_pixels[pixel * 4 + 3] =
                    levels[1u + (x + y) % 3u];
                depth_pixels[pixel] = x < 3u ? 1.f : (x == 3u ? 0.5f : 0.f);
            }
        }

        ALMetalRenderTargetDescriptor source_descriptor;
        source_descriptor.width = width;
        source_descriptor.height = height;
        source_descriptor.colors[0].format =
            ALMetalPixelFormat::rgba16_float;
        source_descriptor.label = "Alchemy world depth-of-field test source";
        auto source = ALMetalRenderTarget::create(
            *device, source_descriptor, &error);
        INFO(error);
        REQUIRE(source);

        ALMetalTextureDescriptor depth_descriptor;
        depth_descriptor.format = ALMetalPixelFormat::depth32_float;
        depth_descriptor.width = width;
        depth_descriptor.height = height;
        depth_descriptor.storage = ALMetalStorageMode::private_gpu;
        depth_descriptor.usage = ALMetalTextureUsage::shader_read;
        depth_descriptor.label = "Alchemy world depth-of-field test depth";
        auto depth = ALMetalTexture::create(
            *device, depth_descriptor, &error);
        INFO(error);
        REQUIRE(depth);

        auto upload = device->makeCommandBuffer(
            "Alchemy world depth-of-field test upload", &error);
        INFO(error);
        REQUIRE(upload);
        id<MTLBuffer> source_staging = [nativeDevice(*device)
            newBufferWithBytes:source_pixels.data()
                      length:sizeof(source_pixels)
                     options:MTLResourceStorageModeShared];
        REQUIRE(source_staging);
        id<MTLBlitCommandEncoder> source_blit =
            [nativeCommand(*upload) blitCommandEncoder];
        REQUIRE(source_blit);
        [source_blit copyFromBuffer:source_staging
                       sourceOffset:0
                  sourceBytesPerRow:width * 4 * sizeof(std::uint16_t)
                sourceBytesPerImage:sizeof(source_pixels)
                         sourceSize:MTLSizeMake(width, height, 1)
                          toTexture:(__bridge id<MTLTexture>)
                              source->colorTexture(0)->nativeHandle()
                   destinationSlice:0
                   destinationLevel:0
                  destinationOrigin:MTLOriginMake(0, 0, 0)];
        [source_blit endEncoding];
        REQUIRE(depth->upload(
            *upload, 0, 0, {}, depth_pixels.data(),
            width * sizeof(float), &error));
        REQUIRE(upload->commitAndWait(&error));
        INFO(error);

        ALMetalWorldDepthOfFieldScene base;
        base.source = source.get();
        base.depth_texture = depth.get();
        base.inverse_projection[0] = 1.f;
        base.inverse_projection[5] = 1.f;
        base.inverse_projection[10] = 1.f;
        base.inverse_projection[14] = -2.f;
        base.inverse_projection[15] = 1.f;
        base.focal_distance = -2.f;
        base.blur_constant = 24.f / 1.414f;
        base.tan_pixel_angle = 1.f;
        base.magnification = 1.f;
        base.max_cof = 4.f;
        base.resolution_scale = 0.75f;
        base.highlight_threshold = 1.f;
        base.highlight_gain = 0.5f;
        base.highlight_clamp = 2.f;

        const auto half_to_float = [](std::uint16_t value)
        {
            const std::uint32_t exponent = (value >> 10u) & 0x1fu;
            const std::uint32_t mantissa = value & 0x3ffu;
            float result = exponent == 0u
                ? std::ldexp(static_cast<float>(mantissa), -24)
                : std::ldexp(static_cast<float>(mantissa + 0x400u),
                             static_cast<int>(exponent) - 25);
            return (value & 0x8000u) != 0u ? -result : result;
        };
        using Pixel = std::array<float, 4>;
        std::vector<Pixel> source_reference(width * height);
        for (std::size_t pixel = 0; pixel < source_reference.size(); ++pixel)
        {
            for (std::size_t channel = 0; channel < 4; ++channel)
            {
                source_reference[pixel][channel] = half_to_float(
                    source_pixels[pixel * 4 + channel]);
            }
        }
        const auto mirror = [](float value)
        {
            value = std::fmod(value, 2.f);
            if (value < 0.f)
            {
                value += 2.f;
            }
            return value > 1.f ? 2.f - value : value;
        };
        const auto point_coordinate = [&](float value, std::uint32_t size)
        {
            return static_cast<std::uint32_t>(std::clamp(
                static_cast<int>(std::floor(mirror(value) * size)),
                0, static_cast<int>(size) - 1));
        };
        const auto sample_source = [&](float u, float v)
        {
            const std::uint32_t x = point_coordinate(u, width);
            const std::uint32_t y = point_coordinate(v, height);
            return source_reference[static_cast<std::size_t>(y) * width + x];
        };
        const auto sample_depth = [&](float u, float v)
        {
            const std::uint32_t x = point_coordinate(u, width);
            const std::uint32_t y = point_coordinate(v, height);
            return depth_pixels[static_cast<std::size_t>(y) * width + x];
        };
        const auto circle_of_confusion = [&](float u, float v)
        {
            const float ndc_z = sample_depth(u, v) * 2.f - 1.f;
            const float position_z = ndc_z - 2.f;
            const float defocus = base.focal_distance / position_z - 1.f;
            const float pixel_length =
                base.tan_pixel_angle * -base.focal_distance;
            return std::clamp(
                defocus * (base.blur_constant * 1.414f /
                           (base.magnification * pixel_length)),
                -base.max_cof, base.max_cof);
        };
        const auto add_sample = [&](Pixel& sum, float& sum_weight,
                                    Pixel sample)
        {
            const float peak = std::max(
                sample[0], std::max(sample[1], sample[2]));
            if (peak > base.highlight_clamp)
            {
                const float scale = base.highlight_clamp / peak;
                sample[0] *= scale;
                sample[1] *= scale;
                sample[2] *= scale;
            }
            const float clamped_peak = std::max(
                sample[0], std::max(sample[1], sample[2]));
            const float weight = 1.f + base.highlight_gain *
                std::max(clamped_peak - base.highlight_threshold, 0.f);
            for (std::size_t channel = 0; channel < 4; ++channel)
            {
                sum[channel] += sample[channel] * weight;
            }
            sum_weight += weight;
        };

        const std::uint32_t blur_width = static_cast<std::uint32_t>(
            width * base.resolution_scale);
        const std::uint32_t blur_height = static_cast<std::uint32_t>(
            height * base.resolution_scale);
        REQUIRE(blur_width == 6u);
        REQUIRE(blur_height == 5u);
        const float resolution_scale = std::min(
            blur_width / static_cast<float>(width),
            blur_height / static_cast<float>(height));
        std::vector<Pixel> blur_reference(blur_width * blur_height);
        constexpr float pi = 3.14159265358979323846f;
        for (std::uint32_t y = 0; y < blur_height; ++y)
        {
            for (std::uint32_t x = 0; x < blur_width; ++x)
            {
                const float u = (x + 0.5f) / blur_width;
                const float v = (y + 0.5f) / blur_height;
                Pixel sum = sample_source(u, v);
                float sum_weight = 1.f;
                float circle = circle_of_confusion(u, v);
                const float maximum_radius =
                    std::max(std::abs(circle), 0.0001f);
                if (circle < -0.5f)
                {
                    circle = std::abs(circle);
                    while (circle > 0.5f)
                    {
                        const int iterations = static_cast<int>(std::max(
                            1.f, circle * 3.7f));
                        const float step_angle = 2.f * pi / iterations;
                        const float turn_sine = std::sin(step_angle);
                        const float turn_cosine = std::cos(step_angle);
                        float sine = std::sin(circle);
                        float cosine = std::cos(circle);
                        for (int tap = 0; tap < iterations; ++tap)
                        {
                            const float current_sine = sine;
                            const float current_cosine = cosine;
                            sine = current_sine * turn_cosine +
                                current_cosine * turn_sine;
                            cosine = current_cosine * turn_cosine -
                                current_sine * turn_sine;
                            const float sample_u = u +
                                circle * current_sine / width;
                            const float sample_v = v +
                                circle * current_cosine / height;
                            const float sampled_circle =
                                -circle_of_confusion(sample_u, sample_v);
                            if (sampled_circle > circle + 0.001f)
                            {
                                add_sample(
                                    sum, sum_weight,
                                    sample_source(sample_u, sample_v));
                            }
                        }
                        circle -= 1.f;
                    }
                }
                for (float& channel : sum)
                {
                    channel /= std::max(sum_weight, 0.0001f);
                }
                blur_reference[
                    static_cast<std::size_t>(y) * blur_width + x] = sum;
                CHECK(maximum_radius >= 0.0001f);
            }
        }

        const auto sample_blur = [&](float u, float v)
        {
            const float px = u * blur_width - 0.5f;
            const float py = v * blur_height - 0.5f;
            const int low_x = static_cast<int>(std::floor(px));
            const int low_y = static_cast<int>(std::floor(py));
            const float fraction_x = px - std::floor(px);
            const float fraction_y = py - std::floor(py);
            const int tap_x[4] = {low_x, low_x + 1, low_x, low_x + 1};
            const int tap_y[4] = {low_y, low_y, low_y + 1, low_y + 1};
            const float weights[4] = {
                (1.f - fraction_x) * (1.f - fraction_y),
                fraction_x * (1.f - fraction_y),
                (1.f - fraction_x) * fraction_y,
                fraction_x * fraction_y,
            };
            Pixel filtered{};
            Pixel accepted{};
            float accepted_weight = 0.f;
            for (std::size_t tap = 0; tap < 4; ++tap)
            {
                const int x = std::clamp(
                    tap_x[tap], 0, static_cast<int>(blur_width) - 1);
                const int y = std::clamp(
                    tap_y[tap], 0, static_cast<int>(blur_height) - 1);
                const Pixel& value = blur_reference[
                    static_cast<std::size_t>(y) * blur_width + x];
                for (std::size_t channel = 0; channel < 3; ++channel)
                {
                    filtered[channel] += value[channel] * weights[tap];
                }
                if (circle_of_confusion(
                        (x + 0.5f) / blur_width,
                        (y + 0.5f) / blur_height) <= 0.f)
                {
                    for (std::size_t channel = 0; channel < 3; ++channel)
                    {
                        accepted[channel] +=
                            value[channel] * weights[tap];
                    }
                    accepted_weight += weights[tap];
                }
            }
            if (accepted_weight > 0.f)
            {
                for (std::size_t channel = 0; channel < 3; ++channel)
                {
                    accepted[channel] /= accepted_weight;
                }
                return accepted;
            }
            return filtered;
        };

        std::vector<Pixel> expected(width * height);
        for (std::uint32_t y = 0; y < height; ++y)
        {
            for (std::uint32_t x = 0; x < width; ++x)
            {
                const float u = (x + 0.5f) / width;
                const float v = (y + 0.5f) / height;
                const Pixel sharp = sample_source(u, v);
                Pixel result = sharp;
                const float circle = circle_of_confusion(u, v);
                const float amount = circle > 0.f ? 0.f : std::min(
                    std::abs(circle) * resolution_scale *
                    resolution_scale, 1.f);
                if (amount > 0.f)
                {
                    const Pixel blurred = sample_blur(u, v);
                    for (std::size_t channel = 0; channel < 3; ++channel)
                    {
                        result[channel] = std::lerp(
                            result[channel], blurred[channel], amount);
                    }
                }
                expected[static_cast<std::size_t>(y) * width + x] = result;
            }
        }

        std::array<std::vector<std::uint16_t>, 8> variants;
        for (std::size_t rgba16 = 0; rgba16 < 2; ++rgba16)
        {
            for (std::size_t shaped = 0; shaped < 2; ++shaped)
            {
                for (std::size_t near_blur = 0; near_blur < 2; ++near_blur)
                {
                    ALMetalWorldDepthOfFieldScene scene = base;
                    scene.rgba16_blur = rgba16 != 0;
                    scene.near_blur = near_blur != 0;
                    if (shaped != 0)
                    {
                        scene.aperture_blades = 6;
                        scene.aperture_rotation = 0.2f;
                        scene.aperture_curvature = 0.3f;
                        scene.anamorphic_squeeze = 1.4f;
                        scene.cat_eye = 0.2f;
                        scene.fringe_amount = 0.3f;
                        scene.spherical_aberration = 0.4f;
                        scene.field_stretch = 0.2f;
                        scene.field_falloff = 2.5f;
                        scene.coma_asymmetry = 0.3f;
                    }
                    const std::size_t variant = rgba16 * 4u +
                        shaped * 2u + near_blur;
                    auto output = renderer->renderDepthOfField(scene, &error);
                    INFO(error);
                    CAPTURE(rgba16, shaped, near_blur);
                    REQUIRE(output);
                    CHECK(output->descriptor().width == width);
                    CHECK(output->descriptor().height == height);
                    CHECK(output->descriptor().colors[0].format ==
                          ALMetalPixelFormat::rgba16_float);
                    variants[variant].resize(width * height * 4);
                    REQUIRE(output->colorTexture(0)->readback(
                        *device, 0, 0, {}, variants[variant].data(),
                        width * 4 * sizeof(std::uint16_t), &error));
                    INFO(error);
                    for (std::size_t pixel = 0;
                         pixel < width * height; ++pixel)
                    {
                        CHECK(variants[variant][pixel * 4 + 3] ==
                              source_pixels[pixel * 4 + 3]);
                        for (std::size_t channel = 0; channel < 3; ++channel)
                        {
                            CHECK(std::isfinite(half_to_float(
                                variants[variant][pixel * 4 + channel])));
                        }
                    }
                }
            }
        }

        std::size_t changed_far_pixels = 0;
        for (std::size_t pixel = 0; pixel < width * height; ++pixel)
        {
            for (std::size_t channel = 0; channel < 3; ++channel)
            {
                const float actual = half_to_float(
                    variants[4][pixel * 4 + channel]);
                const float wanted = expected[pixel][channel];
                CAPTURE(pixel, channel, actual, wanted);
                CHECK(std::abs(actual - wanted) < 0.075f);
            }
            if (depth_pixels[pixel] == 0.f &&
                variants[4][pixel * 4] != source_pixels[pixel * 4])
            {
                ++changed_far_pixels;
            }
        }
        CHECK(changed_far_pixels > 0);
        CHECK(variants[4] != variants[5]);
        CHECK(variants[4] != variants[6]);
        for (std::size_t pixel = 0; pixel < width * height; ++pixel)
        {
            for (std::size_t channel = 0; channel < 3; ++channel)
            {
                const float compact = half_to_float(
                    variants[0][pixel * 4 + channel]);
                const float precise = half_to_float(
                    variants[4][pixel * 4 + channel]);
                CAPTURE(pixel, channel, compact, precise);
                CHECK(std::abs(compact - precise) < 0.09f);
            }
        }

        ALMetalWorldDepthOfFieldScene reverse = base;
        reverse.rgba16_blur = true;
        reverse.reverse_z = true;
        reverse.inverse_projection[10] = 2.f;
        reverse.inverse_projection[14] = -3.f;
        auto reverse_output = renderer->renderDepthOfField(reverse, &error);
        INFO(error);
        REQUIRE(reverse_output);
        std::vector<std::uint16_t> reverse_pixels(width * height * 4);
        REQUIRE(reverse_output->colorTexture(0)->readback(
            *device, 0, 0, {}, reverse_pixels.data(),
            width * 4 * sizeof(std::uint16_t), &error));
        INFO(error);
        CHECK(reverse_pixels == variants[4]);

        // The production world target carries a combined D32F/S8 attachment.
        // Prove that its depth plane is a valid sampled input, independently
        // of the standalone D32F oracle texture above.
        ALMetalRenderTargetDescriptor combined_descriptor;
        combined_descriptor.width = width;
        combined_descriptor.height = height;
        combined_descriptor.color_attachment_count = 0;
        combined_descriptor.depth_stencil_format =
            ALMetalPixelFormat::depth32_float_stencil8;
        combined_descriptor.depth_stencil_shader_read = true;
        combined_descriptor.label =
            "Alchemy world depth-of-field combined-depth test";
        auto combined_depth = ALMetalRenderTarget::create(
            *device, combined_descriptor, &error);
        INFO(error);
        REQUIRE(combined_depth);
        ALMetalRenderPassConfig clear_config;
        clear_config.depth_load = ALMetalLoadAction::clear;
        clear_config.depth_store = ALMetalStoreAction::store;
        clear_config.clear_depth = 0.0;
        clear_config.stencil_load = ALMetalLoadAction::clear;
        clear_config.stencil_store = ALMetalStoreAction::store;
        auto clear_pass = combined_depth->makeRenderPass(
            clear_config, &error);
        auto clear_command = clear_pass ? device->makeCommandBuffer(
            "Alchemy depth-of-field combined-depth clear", &error)
            : nullptr;
        auto clear_encoder = clear_command && clear_pass
            ? ALMetalRenderEncoder::begin(
                  *clear_command, *clear_pass,
                  "Alchemy depth-of-field combined-depth encoder", &error)
            : nullptr;
        INFO(error);
        REQUIRE(clear_encoder);
        REQUIRE(clear_encoder->end(&error));
        REQUIRE(clear_command->commitAndWait(&error));
        base.depth_texture = combined_depth->depthStencilTexture();
        auto combined_result = renderer->renderDepthOfField(base, &error);
        INFO(error);
        REQUIRE(combined_result);

        ALMetalWorldDepthOfFieldScene invalid;
        error.clear();
        CHECK_FALSE(renderer->renderDepthOfField(invalid, &error));
        CHECK(error == "Metal world depth-of-field scene is incomplete");
        invalid = base;
        invalid.max_cof = 0.f;
        error.clear();
        CHECK_FALSE(renderer->renderDepthOfField(invalid, &error));
        CHECK(error == "Metal world depth-of-field state is invalid");
        ALMetalTextureDescriptor wrong_depth_descriptor = depth_descriptor;
        wrong_depth_descriptor.format = ALMetalPixelFormat::r32_float;
        auto wrong_depth = ALMetalTexture::create(
            *device, wrong_depth_descriptor, &error);
        INFO(error);
        REQUIRE(wrong_depth);
        invalid = base;
        invalid.depth_texture = wrong_depth.get();
        error.clear();
        CHECK_FALSE(renderer->renderDepthOfField(invalid, &error));
        CHECK(error == "Metal world depth-of-field inputs are incompatible");
    }
}

TEST_CASE("almetal: world display post owns the real post target formats", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        auto renderer = ALMetalWorldGBufferRenderer::create(
            *device, &error);
        INFO(error);
        REQUIRE(renderer);

        const auto make_source = [&](
            ALMetalPixelFormat format, std::uint32_t width,
            std::uint32_t height, const void* pixels,
            std::size_t bytes_per_row, const char* label)
        {
            ALMetalRenderTargetDescriptor descriptor;
            descriptor.width = width;
            descriptor.height = height;
            descriptor.colors[0].format = format;
            descriptor.label = label;
            auto target = ALMetalRenderTarget::create(
                *device, descriptor, &error);
            INFO(error);
            REQUIRE(target);
            auto upload = device->makeCommandBuffer(label, &error);
            INFO(error);
            REQUIRE(upload);
            id<MTLBuffer> staging = [nativeDevice(*device)
                newBufferWithBytes:pixels
                          length:bytes_per_row * height
                         options:MTLResourceStorageModeShared];
            REQUIRE(staging);
            id<MTLBlitCommandEncoder> blit =
                [nativeCommand(*upload) blitCommandEncoder];
            REQUIRE(blit);
            [blit copyFromBuffer:staging
                    sourceOffset:0
               sourceBytesPerRow:bytes_per_row
             sourceBytesPerImage:bytes_per_row * height
                      sourceSize:MTLSizeMake(width, height, 1)
                       toTexture:(__bridge id<MTLTexture>)
                           target->colorTexture(0)->nativeHandle()
                destinationSlice:0
                destinationLevel:0
               destinationOrigin:MTLOriginMake(0, 0, 0)];
            [blit endEncoding];
            REQUIRE(upload->commit(&error));
            INFO(error);
            return target;
        };
        const auto srgb = [](float linear)
        {
            linear = std::max(linear, 0.f);
            return linear > 0.0031308f
                ? 1.055f * std::pow(linear, 1.f / 2.4f) - 0.055f
                : linear * 12.92f;
        };
        const auto unorm10 = [](float value)
        {
            return static_cast<std::uint32_t>(std::lround(
                std::clamp(value, 0.f, 1.f) * 1023.f));
        };
        const auto channel10 = [](std::uint32_t packed,
                                  std::uint32_t channel)
        {
            return (packed >> (channel * 10u)) & 0x3ffu;
        };

        const std::array<std::uint16_t, 8> hdr_pixels{{
            0x3800u, 0x3400u, 0x3000u, 0x3800u,
            0x3400u, 0x0000u, 0x0000u, 0x3800u,
        }}; // (.5,.25,.125,.5), then premultiplied (.25,0,0,.5)
        auto hdr_source = make_source(
            ALMetalPixelFormat::rgba16_float, 2, 1,
            hdr_pixels.data(), 2 * 4 * sizeof(std::uint16_t),
            "Alchemy HDR display-post test source");

        ALMetalWorldDisplayPostScene scene;
        scene.source = hdr_source.get();
        scene.hdr = true;
        scene.tonemap_mix = 0.f;
        auto hdr_output = renderer->renderDisplayPost(scene, &error);
        INFO(error);
        REQUIRE(hdr_output);
        CHECK(hdr_output->descriptor().width == 2);
        CHECK(hdr_output->descriptor().height == 1);
        CHECK(hdr_output->descriptor().colors[0].format ==
              ALMetalPixelFormat::rgb10a2_unorm);
        std::array<std::uint32_t, 2> packed{};
        REQUIRE(hdr_output->colorTexture(0)->readback(
            *device, 0, 0, {}, packed.data(), sizeof(packed), &error));
        INFO(error);
        const auto identity_grade_expected = packed;
        CHECK(std::abs(static_cast<int>(channel10(packed[0], 0)) -
                       static_cast<int>(unorm10(srgb(0.5f)))) <= 1);
        CHECK(std::abs(static_cast<int>(channel10(packed[0], 1)) -
                       static_cast<int>(unorm10(srgb(0.25f)))) <= 1);
        CHECK(std::abs(static_cast<int>(channel10(packed[0], 2)) -
                       static_cast<int>(unorm10(srgb(0.125f)))) <= 1);
        CHECK((packed[0] >> 30u) == 2u);

        // A modern clean-plate snapshot uses the HDR source and output
        // storage but selects colorCorrectF's gamma-only permutation. Prove
        // that exposure and tonemapping are ignored without applying the
        // separate legacy-sky gamma curve.
        scene.bypass_tonemap = true;
        scene.static_exposure = 4.f;
        scene.adapted_exposure = 0.5f;
        scene.tonemap_mix = 1.f;
        scene.tonemap_type = 3;
        scene.tonemap_params[0] = 4.f;
        auto clean_plate_output = renderer->renderDisplayPost(scene, &error);
        INFO(error);
        REQUIRE(clean_plate_output);
        REQUIRE(clean_plate_output->colorTexture(0)->readback(
            *device, 0, 0, {}, packed.data(), sizeof(packed), &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(channel10(packed[0], 0)) -
                       static_cast<int>(unorm10(srgb(0.5f)))) <= 1);
        CHECK(std::abs(static_cast<int>(channel10(packed[0], 1)) -
                       static_cast<int>(unorm10(srgb(0.25f)))) <= 1);
        CHECK(std::abs(static_cast<int>(channel10(packed[0], 2)) -
                       static_cast<int>(unorm10(srgb(0.125f)))) <= 1);
        scene.bypass_tonemap = false;

        // A legacy sky uses the same HDR/bloom storage path, but GLSL's
        // LEGACY_GAMMA permutation skips exposure and tonemapping before
        // applying 1-pow(1-sRGB,gamma) in display space.
        scene.legacy_gamma = true;
        scene.legacy_gamma_exponent = 2.f;
        scene.static_exposure = 4.f;
        scene.adapted_exposure = 0.5f;
        scene.tonemap_mix = 1.f;
        scene.tonemap_type = 3;
        scene.tonemap_params[0] = 4.f;
        auto legacy_output = renderer->renderDisplayPost(scene, &error);
        INFO(error);
        REQUIRE(legacy_output);
        REQUIRE(legacy_output->colorTexture(0)->readback(
            *device, 0, 0, {}, packed.data(), sizeof(packed), &error));
        INFO(error);
        const auto legacy_gamma = [](float display)
        {
            return 1.f - std::pow(
                1.f - std::clamp(display, 0.f, 1.f), 2.f);
        };
        CHECK(std::abs(static_cast<int>(channel10(packed[0], 0)) -
                       static_cast<int>(unorm10(
                           legacy_gamma(srgb(0.5f))))) <= 1);
        CHECK(std::abs(static_cast<int>(channel10(packed[0], 1)) -
                       static_cast<int>(unorm10(
                           legacy_gamma(srgb(0.25f))))) <= 1);
        CHECK(std::abs(static_cast<int>(channel10(packed[0], 2)) -
                       static_cast<int>(unorm10(
                           legacy_gamma(srgb(0.125f))))) <= 1);
        scene.legacy_gamma = false;
        scene.legacy_gamma_exponent = 1.f;
        scene.static_exposure = 1.f;
        scene.adapted_exposure = 1.f;
        scene.tonemap_mix = 0.f;
        scene.tonemap_type = 0;
        scene.tonemap_params[0] = 0.f;
        REQUIRE(hdr_output->colorTexture(0)->readback(
            *device, 0, 0, {}, packed.data(), sizeof(packed), &error));
        INFO(error);

        auto hdr_sample = renderer->renderDisplaySample(
            *hdr_output, 2, 1, &error);
        INFO(error);
        REQUIRE(hdr_sample);
        CHECK(hdr_sample->descriptor().colors[0].format ==
              ALMetalPixelFormat::rgba8_unorm);
        std::array<std::uint8_t, 8> hdr_sample_pixels{};
        REQUIRE(hdr_sample->colorTexture(0)->readback(
            *device, 0, 0, {}, hdr_sample_pixels.data(),
            sizeof(hdr_sample_pixels), &error));
        INFO(error);
        for (std::size_t pixel = 0; pixel < 2; ++pixel)
        {
            for (std::size_t channel = 0; channel < 3; ++channel)
            {
                const int expected = static_cast<int>(std::lround(
                    channel10(packed[pixel], channel) *
                    (255.f / 1023.f)));
                CAPTURE(pixel, channel);
                CHECK(std::abs(
                    static_cast<int>(hdr_sample_pixels[pixel * 4 + channel]) -
                    expected) <= 1);
            }
            const int expected_alpha = static_cast<int>(std::lround(
                (packed[pixel] >> 30u) * (255.f / 3.f)));
            CHECK(std::abs(static_cast<int>(
                               hdr_sample_pixels[pixel * 4 + 3]) -
                           expected_alpha) <= 1);
        }
        auto decimated = renderer->renderDisplaySample(
            *hdr_output, 1, 1, &error);
        INFO(error);
        REQUIRE(decimated);
        CHECK(decimated->descriptor().width == 1);
        CHECK(decimated->descriptor().height == 1);
        std::array<std::uint8_t, 4> decimated_pixel{};
        REQUIRE(decimated->colorTexture(0)->readback(
            *device, 0, 0, {}, decimated_pixel.data(),
            sizeof(decimated_pixel), &error));
        CHECK(std::equal(
            decimated_pixel.begin(), decimated_pixel.end(),
            hdr_sample_pixels.begin() + 4));

        scene.cutout_premultiplied = true;
        auto cutout_output = renderer->renderDisplayPost(scene, &error);
        INFO(error);
        REQUIRE(cutout_output);
        REQUIRE(cutout_output->colorTexture(0)->readback(
            *device, 0, 0, {}, packed.data(), sizeof(packed), &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(channel10(packed[1], 0)) -
                       static_cast<int>(unorm10(srgb(0.5f) * 0.5f))) <= 1);
        CHECK(channel10(packed[1], 1) == 0u);
        CHECK(channel10(packed[1], 2) == 0u);
        CHECK((packed[1] >> 30u) == 2u);

        // Snapshot cutouts take the same HDR color path but cross an RGBA8
        // boundary so coverage is not reduced to RGB10_A2's two alpha bits.
        // The premultiplied half-coverage source must therefore remain 128,
        // not the ordinary target's quantized 170.
        scene.preserve_alpha = true;
        auto precise_cutout_output = renderer->renderDisplayPost(
            scene, &error);
        INFO(error);
        REQUIRE(precise_cutout_output);
        CHECK(precise_cutout_output->descriptor().colors[0].format ==
              ALMetalPixelFormat::rgba8_unorm);
        std::array<std::uint8_t, 8> precise_cutout_pixels{};
        REQUIRE(precise_cutout_output->colorTexture(0)->readback(
            *device, 0, 0, {}, precise_cutout_pixels.data(),
            sizeof(precise_cutout_pixels), &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(precise_cutout_pixels[4]) -
                       static_cast<int>(std::lround(
                           srgb(0.5f) * 0.5f * 255.f))) <= 1);
        CHECK(precise_cutout_pixels[5] == 0u);
        CHECK(precise_cutout_pixels[6] == 0u);
        CHECK(std::abs(static_cast<int>(precise_cutout_pixels[7]) - 128) <=
              1);
        scene.preserve_alpha = false;

        // Static and adapted exposure multiply before the same Reinhard
        // branch as tonemapUtilF.glsl, then the RGB10_A2 target quantizes the
        // display-space result while preserving two-bit coverage.
        scene.cutout_premultiplied = false;
        scene.static_exposure = 4.f;
        scene.adapted_exposure = 0.5f;
        scene.tonemap_mix = 1.f;
        scene.tonemap_type = 3;
        scene.tonemap_params[0] = 4.f;
        auto reinhard_output = renderer->renderDisplayPost(scene, &error);
        INFO(error);
        REQUIRE(reinhard_output);
        REQUIRE(reinhard_output->colorTexture(0)->readback(
            *device, 0, 0, {}, packed.data(), sizeof(packed), &error));
        INFO(error);
        const auto reinhard = [](float value)
        {
            return value * (1.f + value / 4.f) / (1.f + value);
        };
        CHECK(std::abs(static_cast<int>(channel10(packed[0], 0)) -
                       static_cast<int>(unorm10(srgb(reinhard(1.f))))) <= 1);
        CHECK(std::abs(static_cast<int>(channel10(packed[0], 1)) -
                       static_cast<int>(unorm10(srgb(reinhard(0.5f))))) <= 1);
        CHECK(std::abs(static_cast<int>(channel10(packed[0], 2)) -
                       static_cast<int>(unorm10(srgb(reinhard(0.25f))))) <= 1);

        // Exercise every analytical color-grade family in colorCorrectF's
        // exact linear/tonemap/display ordering. The artist 3D LUT and baked
        // channel curves remain separate texture-backed owners.
        scene.static_exposure = 1.f;
        scene.adapted_exposure = 1.f;
        scene.tonemap_mix = 0.f;
        scene.tonemap_type = 0;
        scene.tonemap_params[0] = 0.f;
        ALMetalWorldColorGrade& grade = scene.color_grade;
        grade.enabled = true;
        std::copy_n(std::array<float, 3>{{1.1f, 0.9f, 1.05f}}.begin(),
                    3, grade.white_balance_gain);
        std::copy_n(std::array<float, 3>{{0.02f, -0.01f, 0.03f}}.begin(),
                    3, grade.lift);
        std::copy_n(std::array<float, 3>{{0.9f, 1.1f, 0.8f}}.begin(),
                    3, grade.inverse_gamma);
        std::copy_n(std::array<float, 3>{{1.05f, 0.95f, 1.1f}}.begin(),
                    3, grade.gain);
        std::copy_n(std::array<float, 3>{{1.2f, 0.9f, 0.8f}}.begin(),
                    3, grade.shadow_ratio);
        std::copy_n(std::array<float, 3>{{0.9f, 1.1f, 1.f}}.begin(),
                    3, grade.midtone_ratio);
        std::copy_n(std::array<float, 3>{{0.8f, 1.f, 1.2f}}.begin(),
                    3, grade.highlight_ratio);
        grade.midtone_amount = 0.35f;
        grade.split_amount = 0.45f;
        grade.shadow_ramp[0] = 2.5f;
        grade.shadow_ramp[1] = -0.375f;
        grade.highlight_ramp[0] = 2.5f;
        grade.highlight_ramp[1] = -1.25f;
        grade.black_white_scale = 1.1f;
        grade.black_white_bias = -0.05f;
        grade.brightness_contrast_scale = 1.15f;
        grade.brightness_contrast_bias = -0.04f;
        grade.highlights_scaled = 0.12f;
        grade.shadows_scaled = -0.08f;
        grade.saturation = 1.2f;
        grade.vibrance = 0.25f;
        grade.hue_shift = 0.1f;
        auto grade_output = renderer->renderDisplayPost(scene, &error);
        INFO(error);
        REQUIRE(grade_output);
        REQUIRE(grade_output->colorTexture(0)->readback(
            *device, 0, 0, {}, packed.data(), sizeof(packed), &error));
        INFO(error);

        using Color3 = std::array<float, 3>;
        const auto mix_color = [](const Color3& first,
                                  const Color3& second, float amount)
        {
            Color3 result{};
            for (std::size_t channel = 0; channel < 3; ++channel)
            {
                result[channel] = first[channel] +
                    (second[channel] - first[channel]) * amount;
            }
            return result;
        };
        const auto luma = [](const Color3& color)
        {
            return color[0] * 0.2126f + color[1] * 0.7152f +
                color[2] * 0.0722f;
        };
        const auto smoothstep = [](float edge0, float edge1, float value)
        {
            const float t = std::clamp(
                (value - edge0) / (edge1 - edge0), 0.f, 1.f);
            return t * t * (3.f - 2.f * t);
        };
        const auto ramp = [](float value, const float pair[2])
        {
            const float t = std::clamp(
                value * pair[0] + pair[1], 0.f, 1.f);
            return t * t * (3.f - 2.f * t);
        };
        const auto hue_shift = [](Color3 color, float shift)
        {
            const float maximum = std::max({color[0], color[1], color[2]});
            const float minimum = std::min({color[0], color[1], color[2]});
            const float delta = maximum - minimum;
            float hue = 0.f;
            if (delta > 1.e-10f)
            {
                if (maximum == color[0])
                {
                    hue = (color[1] - color[2]) / delta;
                }
                else if (maximum == color[1])
                {
                    hue = (color[2] - color[0]) / delta + 2.f;
                }
                else
                {
                    hue = (color[0] - color[1]) / delta + 4.f;
                }
                hue /= 6.f;
                hue -= std::floor(hue);
            }
            hue = hue + shift - std::floor(hue + shift);
            const float saturation = maximum > 1.e-10f
                ? delta / maximum : 0.f;
            const float sector = hue * 6.f;
            const int index = static_cast<int>(std::floor(sector));
            const float fraction = sector - std::floor(sector);
            const float p = maximum * (1.f - saturation);
            const float q = maximum * (1.f - saturation * fraction);
            const float t = maximum *
                (1.f - saturation * (1.f - fraction));
            switch (index % 6)
            {
            case 0: return Color3{{maximum, t, p}};
            case 1: return Color3{{q, maximum, p}};
            case 2: return Color3{{p, maximum, t}};
            case 3: return Color3{{p, q, maximum}};
            case 4: return Color3{{t, p, maximum}};
            default: return Color3{{maximum, p, q}};
            }
        };

        Color3 expected_grade{{0.5f, 0.25f, 0.125f}};
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            expected_grade[channel] *= grade.white_balance_gain[channel];
            expected_grade[channel] = std::pow(
                std::max(expected_grade[channel] * grade.gain[channel] +
                             grade.lift[channel],
                         0.f),
                grade.inverse_gamma[channel]);
            expected_grade[channel] = std::clamp(
                expected_grade[channel], 0.f, 1.f);
        }
        const float split_luma = luma(expected_grade);
        const float high = ramp(split_luma, grade.highlight_ramp);
        const float low = 1.f - ramp(split_luma, grade.shadow_ramp);
        const float middle = std::max(1.f - high - low, 0.f);
        expected_grade = mix_color(
            expected_grade,
            Color3{{grade.shadow_ratio[0] * split_luma,
                    grade.shadow_ratio[1] * split_luma,
                    grade.shadow_ratio[2] * split_luma}},
            low * grade.split_amount);
        expected_grade = mix_color(
            expected_grade,
            Color3{{grade.midtone_ratio[0] * split_luma,
                    grade.midtone_ratio[1] * split_luma,
                    grade.midtone_ratio[2] * split_luma}},
            middle * grade.midtone_amount);
        expected_grade = mix_color(
            expected_grade,
            Color3{{grade.highlight_ratio[0] * split_luma,
                    grade.highlight_ratio[1] * split_luma,
                    grade.highlight_ratio[2] * split_luma}},
            high * grade.split_amount);
        for (float& channel : expected_grade)
        {
            channel = srgb(channel) * grade.black_white_scale +
                grade.black_white_bias;
            channel = channel * grade.brightness_contrast_scale +
                grade.brightness_contrast_bias;
        }
        const float recovery_luma = luma(expected_grade);
        const float highlight_mask = smoothstep(0.5f, 1.f, recovery_luma);
        const float shadow_mask = 1.f -
            smoothstep(0.f, 0.5f, recovery_luma);
        for (float& channel : expected_grade)
        {
            channel += (1.f - channel) *
                (grade.highlights_scaled * highlight_mask);
            channel += channel * (grade.shadows_scaled * shadow_mask);
        }
        const float saturation_luma = luma(expected_grade);
        expected_grade = mix_color(
            Color3{{saturation_luma, saturation_luma, saturation_luma}},
            expected_grade, grade.saturation);
        const float vibrance_luma = luma(expected_grade);
        const float color_range =
            *std::max_element(expected_grade.begin(), expected_grade.end()) -
            *std::min_element(expected_grade.begin(), expected_grade.end());
        expected_grade = mix_color(
            Color3{{vibrance_luma, vibrance_luma, vibrance_luma}},
            expected_grade, 1.f + grade.vibrance * (1.f - color_range));
        for (float& channel : expected_grade)
        {
            channel = std::clamp(channel, 0.f, 1.f);
        }
        expected_grade = hue_shift(expected_grade, grade.hue_shift);
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            CAPTURE(channel, expected_grade[channel]);
            CHECK(std::abs(static_cast<int>(channel10(packed[0], channel)) -
                           static_cast<int>(unorm10(expected_grade[channel]))) <=
                  3);
        }

        // The artist LUT uses a 2D array with one blue slice per cube layer;
        // Metal performs the same half-texel XY addressing and explicit
        // adjacent-slice blend as hardware trilinear 3D sampling. The baked
        // channel curves then sample their RGBA16 row independently.
        ALMetalTextureDescriptor lut_descriptor;
        lut_descriptor.type = ALMetalTextureType::texture_2d_array;
        lut_descriptor.format = ALMetalPixelFormat::rgba16_unorm;
        lut_descriptor.width = 2;
        lut_descriptor.height = 2;
        lut_descriptor.array_length = 2;
        lut_descriptor.storage = ALMetalStorageMode::private_gpu;
        lut_descriptor.usage = ALMetalTextureUsage::shader_read;
        lut_descriptor.label = "Alchemy color-grade LUT test";
        auto color_lut = ALMetalTexture::create(
            *device, lut_descriptor, &error);
        INFO(error);
        REQUIRE(color_lut);
        ALMetalTextureDescriptor curve_descriptor;
        curve_descriptor.format = ALMetalPixelFormat::rgba16_unorm;
        curve_descriptor.width = 4;
        curve_descriptor.height = 1;
        curve_descriptor.storage = ALMetalStorageMode::private_gpu;
        curve_descriptor.usage = ALMetalTextureUsage::shader_read;
        curve_descriptor.label = "Alchemy channel-curve test";
        auto tone_curve = ALMetalTexture::create(
            *device, curve_descriptor, &error);
        INFO(error);
        REQUIRE(tone_curve);
        const auto unorm16 = [](float value)
        {
            return static_cast<std::uint16_t>(std::lround(
                std::clamp(value, 0.f, 1.f) * 65535.f));
        };
        std::array<std::uint16_t, 2 * 2 * 2 * 4> lut_texels{};
        for (std::size_t z = 0; z < 2; ++z)
        {
            for (std::size_t y = 0; y < 2; ++y)
            {
                for (std::size_t x = 0; x < 2; ++x)
                {
                    const std::size_t texel = ((z * 2 + y) * 2 + x) * 4;
                    lut_texels[texel] = unorm16(
                        0.1f + 0.7f * x + 0.1f * y + 0.05f * z);
                    lut_texels[texel + 1] = unorm16(
                        0.05f + 0.2f * x + 0.6f * y + 0.05f * z);
                    lut_texels[texel + 2] = unorm16(
                        0.02f + 0.1f * x + 0.15f * y + 0.7f * z);
                    lut_texels[texel + 3] = 0xffffu;
                }
            }
        }
        const std::array<std::uint16_t, 4 * 4> curve_texels{{
            0, 0, 0, 0xffffu,
            unorm16(0.15f), unorm16(0.35f), unorm16(0.1f), 0xffffu,
            unorm16(0.65f), unorm16(0.75f), unorm16(0.8f), 0xffffu,
            0xffffu, 0xffffu, 0xffffu, 0xffffu,
        }};
        auto grade_upload = device->makeCommandBuffer(
            "Alchemy color-grade texture test upload", &error);
        INFO(error);
        REQUIRE(grade_upload);
        REQUIRE(color_lut->upload(
            *grade_upload, 0, 0, {}, lut_texels.data(),
            2 * 4 * sizeof(std::uint16_t), &error));
        REQUIRE(color_lut->upload(
            *grade_upload, 0, 1, {}, lut_texels.data() + 2 * 2 * 4,
            2 * 4 * sizeof(std::uint16_t), &error));
        REQUIRE(tone_curve->upload(
            *grade_upload, 0, 0, {}, curve_texels.data(),
            curve_texels.size() * sizeof(std::uint16_t), &error));
        REQUIRE(grade_upload->commitAndWait(&error));
        INFO(error);

        grade.color_lut_texture = color_lut.get();
        grade.color_lut_size = 2;
        grade.color_lut_flip_green = true;
        grade.color_lut_swap_blue_green = true;
        grade.color_lut_strength = 0.65f;
        grade.tone_curve_texture = tone_curve.get();
        grade.tone_curve_scale = 0.75f;
        grade.tone_curve_bias = 0.125f;
        grade.tone_curve_amount = 0.6f;
        auto artist_grade_output = renderer->renderDisplayPost(scene, &error);
        INFO(error);
        REQUIRE(artist_grade_output);
        REQUIRE(artist_grade_output->colorTexture(0)->readback(
            *device, 0, 0, {}, packed.data(), sizeof(packed), &error));
        INFO(error);

        const auto lut_sample = [&](Color3 coordinate)
        {
            const float sx = std::clamp(coordinate[0], 0.f, 1.f);
            const float sy = std::clamp(coordinate[1], 0.f, 1.f);
            const float sz = std::clamp(coordinate[2], 0.f, 1.f);
            Color3 result{};
            for (std::size_t channel = 0; channel < 3; ++channel)
            {
                const auto value = [&](std::size_t x, std::size_t y,
                                       std::size_t z)
                {
                    return lut_texels[((z * 2 + y) * 2 + x) * 4 + channel] /
                        65535.f;
                };
                const float low_y = value(0, 0, 0) +
                    (value(1, 0, 0) - value(0, 0, 0)) * sx;
                const float high_y = value(0, 1, 0) +
                    (value(1, 1, 0) - value(0, 1, 0)) * sx;
                const float low_z = low_y + (high_y - low_y) * sy;
                const float next_low_y = value(0, 0, 1) +
                    (value(1, 0, 1) - value(0, 0, 1)) * sx;
                const float next_high_y = value(0, 1, 1) +
                    (value(1, 1, 1) - value(0, 1, 1)) * sx;
                const float high_z = next_low_y +
                    (next_high_y - next_low_y) * sy;
                result[channel] = low_z + (high_z - low_z) * sz;
            }
            return result;
        };
        Color3 lut_coordinate{{
            expected_grade[0], expected_grade[2],
            1.f - expected_grade[1]}};
        expected_grade = mix_color(
            expected_grade, lut_sample(lut_coordinate),
            grade.color_lut_strength);
        Color3 curved{};
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            const float position = std::clamp(
                expected_grade[channel], 0.f, 1.f) * 3.f;
            const std::size_t low_index = static_cast<std::size_t>(
                std::floor(position));
            const std::size_t high_index = std::min(low_index + 1, 3ul);
            const float low_value =
                curve_texels[low_index * 4 + channel] / 65535.f;
            const float high_value =
                curve_texels[high_index * 4 + channel] / 65535.f;
            curved[channel] = low_value + (high_value - low_value) *
                (position - std::floor(position));
        }
        expected_grade = mix_color(
            expected_grade, curved, grade.tone_curve_amount);
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            CAPTURE(channel, expected_grade[channel]);
            CHECK(std::abs(static_cast<int>(channel10(packed[0], channel)) -
                           static_cast<int>(unorm10(expected_grade[channel]))) <=
                  3);
        }
        scene.color_grade = ALMetalWorldColorGrade{};
        scene.color_grade.enabled = true;
        auto identity_grade_output = renderer->renderDisplayPost(
            scene, &error);
        INFO(error);
        REQUIRE(identity_grade_output);
        std::array<std::uint32_t, 2> identity_grade_packed{};
        REQUIRE(identity_grade_output->colorTexture(0)->readback(
            *device, 0, 0, {}, identity_grade_packed.data(),
            sizeof(identity_grade_packed), &error));
        CHECK(identity_grade_packed == identity_grade_expected);
        scene.color_grade.enabled = false;

        // Chromatic aberration is the first display-post operation: R/B use
        // independently rotated radial/tangential bilinear taps while G/A
        // remain at the exact center. Exercise nontrivial angle, anisotropy,
        // falloff and both offset axes against an independent scalar oracle.
        constexpr std::uint32_t chromatic_width = 32;
        constexpr std::uint32_t chromatic_height = 24;
        std::array<std::uint8_t,
                   chromatic_width * chromatic_height * 4>
            chromatic_source_pixels{};
        for (std::uint32_t y = 0; y < chromatic_height; ++y)
        {
            for (std::uint32_t x = 0; x < chromatic_width; ++x)
            {
                const std::size_t texel =
                    (y * chromatic_width + x) * 4;
                chromatic_source_pixels[texel] =
                    static_cast<std::uint8_t>(x * 6u + y * 2u);
                chromatic_source_pixels[texel + 1] =
                    static_cast<std::uint8_t>(40u + x * 2u + y * 3u);
                chromatic_source_pixels[texel + 2] =
                    static_cast<std::uint8_t>(20u + x * 3u + y * 5u);
                chromatic_source_pixels[texel + 3] =
                    static_cast<std::uint8_t>(80u + x + y * 2u);
            }
        }
        auto chromatic_source = make_source(
            ALMetalPixelFormat::rgba8_unorm,
            chromatic_width, chromatic_height,
            chromatic_source_pixels.data(), chromatic_width * 4,
            "Alchemy chromatic-aberration test source");
        ALMetalWorldDisplayPostScene chromatic_scene;
        chromatic_scene.source = chromatic_source.get();
        auto chromatic_disabled = renderer->renderDisplayPost(
            chromatic_scene, &error);
        INFO(error);
        REQUIRE(chromatic_disabled);
        chromatic_scene.chromatic_aberration_amount = 0.02f;
        chromatic_scene.chromatic_aberration_reciprocal_falloff = 0.75f;
        chromatic_scene.chromatic_aberration_anisotropy = 0.25f;
        chromatic_scene.chromatic_aberration_angle_sin_cos[0] = 0.6f;
        chromatic_scene.chromatic_aberration_angle_sin_cos[1] = 0.8f;
        chromatic_scene.chromatic_aberration_offset_r[0] = -0.75f;
        chromatic_scene.chromatic_aberration_offset_r[1] = 0.4f;
        chromatic_scene.chromatic_aberration_offset_b[0] = 0.9f;
        chromatic_scene.chromatic_aberration_offset_b[1] = -0.35f;
        auto chromatic_output = renderer->renderDisplayPost(
            chromatic_scene, &error);
        INFO(error);
        REQUIRE(chromatic_output);
        std::array<std::uint8_t,
                   chromatic_width * chromatic_height * 4>
            chromatic_disabled_pixels{};
        std::array<std::uint8_t,
                   chromatic_width * chromatic_height * 4>
            chromatic_output_pixels{};
        REQUIRE(chromatic_disabled->colorTexture(0)->readback(
            *device, 0, 0, {}, chromatic_disabled_pixels.data(),
            chromatic_width * 4, &error));
        REQUIRE(chromatic_output->colorTexture(0)->readback(
            *device, 0, 0, {}, chromatic_output_pixels.data(),
            chromatic_width * 4, &error));
        INFO(error);
        CHECK(chromatic_output_pixels != chromatic_disabled_pixels);
        for (std::size_t texel = 0;
             texel < chromatic_width * chromatic_height; ++texel)
        {
            CHECK(chromatic_output_pixels[texel * 4 + 1] ==
                  chromatic_disabled_pixels[texel * 4 + 1]);
            CHECK(chromatic_output_pixels[texel * 4 + 3] ==
                  chromatic_disabled_pixels[texel * 4 + 3]);
        }

        const auto bilinear_channel = [&](float u, float v,
                                          std::size_t channel)
        {
            const float pixel_x = u * chromatic_width - 0.5f;
            const float pixel_y = v * chromatic_height - 0.5f;
            const int low_x = static_cast<int>(std::floor(pixel_x));
            const int low_y = static_cast<int>(std::floor(pixel_y));
            const int high_x = low_x + 1;
            const int high_y = low_y + 1;
            const float fraction_x = pixel_x - std::floor(pixel_x);
            const float fraction_y = pixel_y - std::floor(pixel_y);
            const auto value = [&](int x, int y)
            {
                x = std::clamp(
                    x, 0, static_cast<int>(chromatic_width) - 1);
                y = std::clamp(
                    y, 0, static_cast<int>(chromatic_height) - 1);
                return chromatic_source_pixels[
                    (static_cast<std::size_t>(y) * chromatic_width +
                     static_cast<std::size_t>(x)) * 4 + channel] / 255.f;
            };
            const float low = value(low_x, low_y) +
                (value(high_x, low_y) - value(low_x, low_y)) * fraction_x;
            const float high = value(low_x, high_y) +
                (value(high_x, high_y) - value(low_x, high_y)) * fraction_x;
            return low + (high - low) * fraction_y;
        };
        const std::array<std::array<std::uint32_t, 2>, 4>
            oracle_pixels{{{{4, 5}}, {{27, 5}}, {{4, 18}}, {{27, 18}}}};
        for (const auto& coordinate : oracle_pixels)
        {
            const std::uint32_t x = coordinate[0];
            const std::uint32_t y = coordinate[1];
            const float u = (static_cast<float>(x) + 0.5f) /
                static_cast<float>(chromatic_width);
            const float v = (static_cast<float>(y) + 0.5f) /
                static_cast<float>(chromatic_height);
            float direction_x = (u - 0.5f) * 0.75f;
            float direction_y = v - 0.5f;
            const float aspect = static_cast<float>(chromatic_width) /
                static_cast<float>(chromatic_height);
            const float scale_x = std::max(aspect, 1.f);
            const float scale_y = std::max(1.f / aspect, 1.f);
            const float normalized_distance = std::clamp(
                std::hypot(direction_x * scale_x,
                           direction_y * scale_y) /
                    (0.5f * std::hypot(scale_x, scale_y)),
                0.f, 1.f);
            const float strength = 0.02f * std::pow(
                normalized_distance, 0.75f);
            const float radial_x =
                0.8f * direction_x - 0.6f * direction_y;
            const float radial_y =
                0.6f * direction_x + 0.8f * direction_y;
            const float tangential_x = -radial_y;
            const float tangential_y = radial_x;
            const float red_u = u +
                (radial_x * -0.75f + tangential_x * 0.4f) * strength;
            const float red_v = v +
                (radial_y * -0.75f + tangential_y * 0.4f) * strength;
            const float blue_u = u +
                (radial_x * 0.9f + tangential_x * -0.35f) * strength;
            const float blue_v = v +
                (radial_y * 0.9f + tangential_y * -0.35f) * strength;
            const std::size_t texel =
                (static_cast<std::size_t>(y) * chromatic_width + x) * 4;
            const int expected_red = static_cast<int>(std::lround(
                std::clamp(srgb(bilinear_channel(red_u, red_v, 0)),
                           0.f, 1.f) * 255.f));
            const int expected_blue = static_cast<int>(std::lround(
                std::clamp(srgb(bilinear_channel(blue_u, blue_v, 2)),
                           0.f, 1.f) * 255.f));
            CAPTURE(x, y, red_u, red_v, blue_u, blue_v);
            CHECK(std::abs(static_cast<int>(
                               chromatic_output_pixels[texel]) -
                           expected_red) <= 1);
            CHECK(std::abs(static_cast<int>(
                               chromatic_output_pixels[texel + 2]) -
                           expected_blue) <= 1);
        }

        // The non-HDR GLSL variant has no exposure/tonemap permutation; it
        // clamps the linear RGBA8 source and performs only the display
        // transfer before its first eight-bit storage boundary.
        const std::array<std::uint8_t, 4> vintage_pixel{{
            64u, 128u, 255u, 128u,
        }};
        auto vintage_source = make_source(
            ALMetalPixelFormat::rgba8_unorm, 1, 1,
            vintage_pixel.data(), sizeof(vintage_pixel),
            "Alchemy vintage display-post test source");
        ALMetalWorldDisplayPostScene vintage;
        vintage.source = vintage_source.get();
        vintage.static_exposure = 0.f;
        vintage.adapted_exposure = 0.f;
        auto vintage_output = renderer->renderDisplayPost(vintage, &error);
        INFO(error);
        REQUIRE(vintage_output);
        CHECK(vintage_output->descriptor().colors[0].format ==
              ALMetalPixelFormat::rgba8_unorm);
        std::array<std::uint8_t, 4> vintage_result{};
        REQUIRE(vintage_output->colorTexture(0)->readback(
            *device, 0, 0, {}, vintage_result.data(),
            sizeof(vintage_result), &error));
        INFO(error);
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            const int expected = static_cast<int>(std::lround(
                std::clamp(srgb(vintage_pixel[channel] / 255.f),
                           0.f, 1.f) * 255.f));
            CAPTURE(channel);
            CHECK(std::abs(static_cast<int>(vintage_result[channel]) -
                           expected) <= 1);
        }
        CHECK(vintage_result[3] == 128u);

        // A legacy 3D clamp sampler saturates an over-range blue coordinate.
        // The array representation has to do that before converting blue to
        // a layer index. Drive it above one via the authored green flip and
        // blue/green swap, while X also falls below zero, and compare against
        // the independently clamped trilinear oracle.
        vintage.color_grade.enabled = true;
        vintage.color_grade.brightness_contrast_scale = 2.f;
        vintage.color_grade.brightness_contrast_bias = -1.5f;
        vintage.color_grade.color_lut_texture = color_lut.get();
        vintage.color_grade.color_lut_size = 2;
        vintage.color_grade.color_lut_flip_green = true;
        vintage.color_grade.color_lut_swap_blue_green = true;
        vintage.color_grade.color_lut_strength = 1.f;
        auto clamped_lut_output = renderer->renderDisplayPost(
            vintage, &error);
        INFO(error);
        REQUIRE(clamped_lut_output);
        std::array<std::uint8_t, 4> clamped_lut_result{};
        REQUIRE(clamped_lut_output->colorTexture(0)->readback(
            *device, 0, 0, {}, clamped_lut_result.data(),
            sizeof(clamped_lut_result), &error));
        INFO(error);
        Color3 clamped_lut_coordinate{{
            srgb(vintage_pixel[0] / 255.f) * 2.f - 1.5f,
            srgb(vintage_pixel[2] / 255.f) * 2.f - 1.5f,
            1.f - (srgb(vintage_pixel[1] / 255.f) * 2.f - 1.5f),
        }};
        const Color3 clamped_lut_expected = lut_sample(
            clamped_lut_coordinate);
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            CAPTURE(channel, clamped_lut_expected[channel]);
            const int expected = static_cast<int>(std::lround(
                std::clamp(clamped_lut_expected[channel], 0.f, 1.f) *
                255.f));
            CHECK(std::abs(
                static_cast<int>(clamped_lut_result[channel]) - expected) <=
                1);
        }
        CHECK(clamped_lut_result[3] == 128u);
        vintage.color_grade = ALMetalWorldColorGrade{};

        auto vintage_sample = renderer->renderDisplaySample(
            *vintage_output, 1, 1, &error);
        INFO(error);
        REQUIRE(vintage_sample);
        std::array<std::uint8_t, 4> vintage_sample_result{};
        REQUIRE(vintage_sample->colorTexture(0)->readback(
            *device, 0, 0, {}, vintage_sample_result.data(),
            sizeof(vintage_sample_result), &error));
        CHECK(vintage_sample_result == vintage_result);

        std::array<std::uint8_t, 8 * 8 * 4> dither_source_pixels{};
        for (std::size_t pixel = 0; pixel < 8 * 8; ++pixel)
        {
            std::copy(vintage_pixel.begin(), vintage_pixel.end(),
                      dither_source_pixels.begin() + pixel * 4);
        }
        auto dither_source = make_source(
            ALMetalPixelFormat::rgba8_unorm, 8, 8,
            dither_source_pixels.data(), 8 * 4,
            "Alchemy display-post dither test source");
        ALMetalWorldDisplayPostScene dither_scene;
        dither_scene.source = dither_source.get();
        dither_scene.dither_amount = 1.f;
        auto static_dither = renderer->renderDisplayPost(
            dither_scene, &error);
        INFO(error);
        REQUIRE(static_dither);
        dither_scene.dither_animated = true;
        dither_scene.frame_id = 73;
        auto animated_dither = renderer->renderDisplayPost(
            dither_scene, &error);
        INFO(error);
        REQUIRE(animated_dither);
        std::array<std::uint8_t, 8 * 8 * 4> static_dither_pixels{};
        std::array<std::uint8_t, 8 * 8 * 4> animated_dither_pixels{};
        REQUIRE(static_dither->colorTexture(0)->readback(
            *device, 0, 0, {}, static_dither_pixels.data(), 8 * 4,
            &error));
        REQUIRE(animated_dither->colorTexture(0)->readback(
            *device, 0, 0, {}, animated_dither_pixels.data(), 8 * 4,
            &error));
        CHECK(static_dither_pixels != animated_dither_pixels);
        for (std::size_t pixel = 0; pixel < 8 * 8; ++pixel)
        {
            CHECK(static_dither_pixels[pixel * 4 + 3] == 128u);
            CHECK(animated_dither_pixels[pixel * 4 + 3] == 128u);
        }

        ALMetalWorldDisplayPostScene invalid;
        error.clear();
        CHECK_FALSE(renderer->renderDisplayPost(invalid, &error));
        CHECK(error == "Metal world display-post scene is incomplete");
        invalid.source = vintage_source.get();
        invalid.hdr = true;
        error.clear();
        CHECK_FALSE(renderer->renderDisplayPost(invalid, &error));
        CHECK(error == "Metal world display-post source is incompatible");
        invalid.source = hdr_source.get();
        invalid.static_exposure = -1.f;
        error.clear();
        CHECK_FALSE(renderer->renderDisplayPost(invalid, &error));
        CHECK(error == "Metal world display-post state is invalid");
        invalid.static_exposure = 1.f;
        invalid.tonemap_type = 7;
        error.clear();
        CHECK_FALSE(renderer->renderDisplayPost(invalid, &error));
        CHECK(error == "Metal world display-post state is invalid");
        invalid.tonemap_type = 6;
        error.clear();
        CHECK_FALSE(renderer->renderDisplayPost(invalid, &error));
        CHECK(error == "Metal world display-post state is invalid");
        invalid.tonemap_type = 0;
        invalid.dither_amount = 2.f;
        error.clear();
        CHECK_FALSE(renderer->renderDisplayPost(invalid, &error));
        CHECK(error == "Metal world display-post state is invalid");
        invalid.dither_amount = 0.f;
        invalid.chromatic_aberration_amount = 0.021f;
        error.clear();
        CHECK_FALSE(renderer->renderDisplayPost(invalid, &error));
        CHECK(error == "Metal world display-post state is invalid");
        invalid.chromatic_aberration_amount = 0.f;
        invalid.chromatic_aberration_reciprocal_falloff = 0.f;
        error.clear();
        CHECK_FALSE(renderer->renderDisplayPost(invalid, &error));
        CHECK(error == "Metal world display-post state is invalid");
        invalid.chromatic_aberration_reciprocal_falloff = 1.f;
        invalid.chromatic_aberration_angle_sin_cos[0] = 2.f;
        error.clear();
        CHECK_FALSE(renderer->renderDisplayPost(invalid, &error));
        CHECK(error == "Metal world display-post state is invalid");
        invalid.chromatic_aberration_angle_sin_cos[0] = 0.f;
        invalid.chromatic_aberration_angle_sin_cos[1] = 0.f;
        error.clear();
        CHECK_FALSE(renderer->renderDisplayPost(invalid, &error));
        CHECK(error == "Metal world display-post state is invalid");
        invalid.chromatic_aberration_angle_sin_cos[1] = 1.f;
        invalid.color_grade.enabled = true;
        invalid.color_grade.saturation = 3.f;
        error.clear();
        CHECK_FALSE(renderer->renderDisplayPost(invalid, &error));
        CHECK(error == "Metal world display-post state is invalid");
        invalid.color_grade.saturation = 1.f;
        invalid.color_grade.color_lut_size = 2;
        invalid.color_grade.color_lut_strength = 0.5f;
        error.clear();
        CHECK_FALSE(renderer->renderDisplayPost(invalid, &error));
        CHECK(error == "Metal world display-post state is invalid");
        invalid.color_grade.color_lut_size = 0;
        invalid.color_grade.color_lut_strength = 0.f;
        invalid.color_grade.tone_curve_texture = tone_curve.get();
        invalid.color_grade.tone_curve_scale = 0.6f;
        invalid.color_grade.tone_curve_bias = 0.125f;
        invalid.color_grade.tone_curve_amount = 0.5f;
        error.clear();
        CHECK_FALSE(renderer->renderDisplayPost(invalid, &error));
        CHECK(error == "Metal world display-post state is invalid");

        error.clear();
        CHECK_FALSE(renderer->renderDisplaySample(
            *hdr_output, 0, 1, &error));
        CHECK(error == "Metal world display sample is incomplete");
        error.clear();
        CHECK_FALSE(renderer->renderDisplaySample(
            *hdr_source, 1, 1, &error));
        CHECK(error ==
              "Metal world display sample source is incompatible");
    }
}

TEST_CASE("almetal: world final presentation owns the complete print chain", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        auto renderer = ALMetalWorldGBufferRenderer::create(
            *device, &error);
        INFO(error);
        REQUIRE(renderer);

        constexpr std::uint32_t width = 16;
        constexpr std::uint32_t height = 12;
        const auto make_source = [&](
            ALMetalPixelFormat format, const void* pixels,
            std::size_t bytes_per_row, const char* label)
        {
            ALMetalRenderTargetDescriptor descriptor;
            descriptor.width = width;
            descriptor.height = height;
            descriptor.colors[0].format = format;
            descriptor.label = label;
            auto target = ALMetalRenderTarget::create(
                *device, descriptor, &error);
            INFO(error);
            REQUIRE(target);
            auto command = device->makeCommandBuffer(label, &error);
            INFO(error);
            REQUIRE(command);
            id<MTLBuffer> staging = [nativeDevice(*device)
                newBufferWithBytes:pixels
                          length:bytes_per_row * height
                         options:MTLResourceStorageModeShared];
            REQUIRE(staging);
            id<MTLBlitCommandEncoder> blit =
                [nativeCommand(*command) blitCommandEncoder];
            REQUIRE(blit);
            [blit copyFromBuffer:staging
                    sourceOffset:0
               sourceBytesPerRow:bytes_per_row
             sourceBytesPerImage:bytes_per_row * height
                      sourceSize:MTLSizeMake(width, height, 1)
                       toTexture:(__bridge id<MTLTexture>)
                           target->colorTexture(0)->nativeHandle()
                destinationSlice:0
                destinationLevel:0
               destinationOrigin:MTLOriginMake(0, 0, 0)];
            [blit endEncoding];
            REQUIRE(command->commit(&error));
            INFO(error);
            return target;
        };
        const auto read_output = [&](const ALMetalRenderTarget& target)
        {
            std::array<std::uint8_t, width * height * 4> pixels{};
            REQUIRE(target.colorTexture(0)->readback(
                *device, 0, 0, {}, pixels.data(), width * 4, &error));
            INFO(error);
            return pixels;
        };
        const auto texel = [](std::uint32_t x, std::uint32_t y)
        {
            return (static_cast<std::size_t>(y) * width + x) * 4;
        };

        // Identity proves the RGB10_A2 input boundary, the exact one-to-one
        // sample, BGRA surface storage, and alpha preservation before any
        // optional print treatment is enabled.
        std::array<std::uint32_t, width * height> hdr_pixels{};
        for (std::uint32_t y = 0; y < height; ++y)
        {
            for (std::uint32_t x = 0; x < width; ++x)
            {
                const std::uint32_t red = 41u + x * 47u + y * 3u;
                const std::uint32_t green = 73u + x * 7u + y * 53u;
                const std::uint32_t blue = 109u + x * 29u + y * 17u;
                const std::uint32_t alpha = (x + y) & 3u;
                hdr_pixels[static_cast<std::size_t>(y) * width + x] =
                    (red & 0x3ffu) | ((green & 0x3ffu) << 10u) |
                    ((blue & 0x3ffu) << 20u) | (alpha << 30u);
            }
        }
        auto hdr_source = make_source(
            ALMetalPixelFormat::rgb10a2_unorm, hdr_pixels.data(),
            width * sizeof(std::uint32_t),
            "Alchemy final-presentation RGB10 source");
        ALMetalWorldPresentationScene identity_scene;
        identity_scene.source = hdr_source.get();
        auto identity = renderer->renderPresentationPost(
            identity_scene, &error);
        INFO(error);
        REQUIRE(identity);
        CHECK(identity->descriptor().width == width);
        CHECK(identity->descriptor().height == height);
        CHECK(identity->descriptor().colors[0].format ==
              ALMetalPixelFormat::bgra8_unorm);
        const auto identity_pixels = read_output(*identity);
        for (std::size_t pixel = 0; pixel < hdr_pixels.size(); ++pixel)
        {
            const std::uint32_t packed = hdr_pixels[pixel];
            const std::array<std::uint32_t, 4> expected{{
                static_cast<std::uint32_t>(std::lround(
                    ((packed >> 20u) & 0x3ffu) * (255.f / 1023.f))),
                static_cast<std::uint32_t>(std::lround(
                    ((packed >> 10u) & 0x3ffu) * (255.f / 1023.f))),
                static_cast<std::uint32_t>(std::lround(
                    (packed & 0x3ffu) * (255.f / 1023.f))),
                ((packed >> 30u) & 3u) * 85u,
            }};
            for (std::size_t channel = 0; channel < 4; ++channel)
            {
                CAPTURE(pixel, channel, expected[channel]);
                CHECK(std::abs(
                    static_cast<int>(identity_pixels[pixel * 4 + channel]) -
                    static_cast<int>(expected[channel])) <= 1);
            }
        }

        // The production post chain keeps its display successor, selected
        // antialiasing/CAS pass and final presentation in one explicit
        // command buffer. Prove that dependent targets are sampleable before
        // the shared submission and that the result matches the historical
        // standalone command-buffer sequence byte for byte.
        error.clear();
        REQUIRE(renderer->beginCommandBatch(
            "Alchemy post-chain command-batch regression", &error));
        auto batched_fxaa = renderer->renderFXAA(
            *hdr_source, 2, &error);
        INFO(error);
        REQUIRE(batched_fxaa);
        auto batched_cas = renderer->renderCAS(
            *batched_fxaa, 0.4f, &error);
        INFO(error);
        REQUIRE(batched_cas);
        ALMetalWorldPresentationScene batched_scene;
        batched_scene.source = batched_cas.get();
        auto batched_post = renderer->renderPresentationPost(
            batched_scene, &error);
        INFO(error);
        REQUIRE(batched_post);
        REQUIRE(renderer->commitCommandBatch(&error));
        INFO(error);
        const auto batched_post_pixels = read_output(*batched_post);

        auto standalone_fxaa = renderer->renderFXAA(
            *hdr_source, 2, &error);
        INFO(error);
        REQUIRE(standalone_fxaa);
        auto standalone_cas = renderer->renderCAS(
            *standalone_fxaa, 0.4f, &error);
        INFO(error);
        REQUIRE(standalone_cas);
        ALMetalWorldPresentationScene standalone_scene;
        standalone_scene.source = standalone_cas.get();
        auto standalone_post = renderer->renderPresentationPost(
            standalone_scene, &error);
        INFO(error);
        REQUIRE(standalone_post);
        CHECK(batched_post_pixels == read_output(*standalone_post));

        // The ordinary display-encoded path is the other authored source
        // format. A constant image also makes every following operation's
        // spatial and color behavior independently observable.
        constexpr std::array<std::uint8_t, 4> flat_rgba{{
            64u, 128u, 192u, 191u,
        }};
        std::array<std::uint8_t, width * height * 4> flat_pixels{};
        for (std::size_t pixel = 0; pixel < width * height; ++pixel)
        {
            std::copy(flat_rgba.begin(), flat_rgba.end(),
                      flat_pixels.begin() + pixel * 4);
        }
        auto flat_source = make_source(
            ALMetalPixelFormat::rgba8_unorm, flat_pixels.data(), width * 4,
            "Alchemy final-presentation RGBA8 source");
        ALMetalWorldPresentationScene flat_scene;
        flat_scene.source = flat_source.get();
        auto flat = renderer->renderPresentationPost(flat_scene, &error);
        INFO(error);
        REQUIRE(flat);
        const auto flat_output = read_output(*flat);
        for (std::size_t pixel = 0; pixel < width * height; ++pixel)
        {
            CHECK(flat_output[pixel * 4 + 0] == flat_rgba[2]);
            CHECK(flat_output[pixel * 4 + 1] == flat_rgba[1]);
            CHECK(flat_output[pixel * 4 + 2] == flat_rgba[0]);
            CHECK(flat_output[pixel * 4 + 3] == flat_rgba[3]);
        }

        ALMetalWorldPresentationScene lens_scene = flat_scene;
        lens_scene.lens_distortion_amount = 1.f;
        lens_scene.lens_distortion_k[0] = 0.5f;
        lens_scene.lens_distortion_k[1] = 0.25f;
        lens_scene.lens_distortion_scale = 2.f;
        auto distorted = renderer->renderPresentationPost(
            lens_scene, &error);
        INFO(error);
        REQUIRE(distorted);
        const auto distorted_pixels = read_output(*distorted);
        const std::size_t corner = texel(0, 0);
        CHECK(distorted_pixels[corner + 0] == 0u);
        CHECK(distorted_pixels[corner + 1] == 0u);
        CHECK(distorted_pixels[corner + 2] == 0u);
        CHECK(distorted_pixels[corner + 3] == flat_rgba[3]);
        const std::size_t center = texel(width / 2, height / 2);
        CHECK(distorted_pixels[center + 0] == flat_rgba[2]);
        CHECK(distorted_pixels[center + 1] == flat_rgba[1]);
        CHECK(distorted_pixels[center + 2] == flat_rgba[0]);

        ALMetalWorldPresentationScene vignette_scene = flat_scene;
        vignette_scene.vignette_amount = 1.f;
        vignette_scene.vignette_radius = 0.7f;
        vignette_scene.vignette_softness = 0.3f;
        vignette_scene.vignette_shape = 0.25f;
        vignette_scene.vignette_outer_color[0] = 1.f;
        vignette_scene.vignette_middle_color[1] = 1.f;
        vignette_scene.vignette_middle_point = 0.5f;
        vignette_scene.vignette_aspect[0] = width;
        vignette_scene.vignette_aspect[1] = height;
        auto vignette = renderer->renderPresentationPost(
            vignette_scene, &error);
        INFO(error);
        REQUIRE(vignette);
        const auto vignette_pixels = read_output(*vignette);
        CHECK(vignette_pixels[corner + 0] == 0u);
        CHECK(vignette_pixels[corner + 1] == 0u);
        CHECK(vignette_pixels[corner + 2] == 255u);
        CHECK(vignette_pixels[corner + 3] == flat_rgba[3]);
        CHECK(vignette_pixels[center + 0] == flat_rgba[2]);
        CHECK(vignette_pixels[center + 1] == flat_rgba[1]);
        CHECK(vignette_pixels[center + 2] == flat_rgba[0]);
        const std::size_t middle = texel(11, height / 2);
        CHECK(vignette_pixels[middle + 1] > flat_rgba[1]);

        // Reproduce the protan daltonization path on the CPU. This checks the
        // display/linear round trip and the exact error redistribution, not
        // merely that enabling the mode changes a pixel.
        const auto linear = [](float value)
        {
            return value <= 0.04045f
                ? value / 12.92f
                : std::pow((value + 0.055f) / 1.055f, 2.4f);
        };
        const auto srgb = [](float value)
        {
            value = std::clamp(value, 0.f, 1.f);
            return value <= 0.0031308f
                ? value * 12.92f
                : 1.055f * std::pow(value, 1.f / 2.4f) - 0.055f;
        };
        std::array<float, 3> cvd_linear{{
            linear(flat_rgba[0] / 255.f),
            linear(flat_rgba[1] / 255.f),
            linear(flat_rgba[2] / 255.f),
        }};
        const std::array<float, 3> simulated{{
            cvd_linear[0] * 0.152286f + cvd_linear[1] * 1.052583f -
                cvd_linear[2] * 0.204868f,
            cvd_linear[0] * 0.114503f + cvd_linear[1] * 0.786281f +
                cvd_linear[2] * 0.099216f,
            cvd_linear[0] * -0.003882f - cvd_linear[1] * 0.048116f +
                cvd_linear[2] * 1.051998f,
        }};
        const float red_error = cvd_linear[0] - simulated[0];
        const float green_error = cvd_linear[1] - simulated[1];
        const std::array<float, 3> compensated{{
            srgb(cvd_linear[0]),
            srgb(cvd_linear[1] + red_error * 0.7f + green_error),
            srgb(cvd_linear[2] + red_error * 0.7f),
        }};
        ALMetalWorldPresentationScene cvd_scene = flat_scene;
        cvd_scene.cvd_mode = 1;
        cvd_scene.cvd_amount = 1.f;
        auto cvd = renderer->renderPresentationPost(cvd_scene, &error);
        INFO(error);
        REQUIRE(cvd);
        const auto cvd_pixels = read_output(*cvd);
        const std::array<float, 3> expected_bgr{{
            compensated[2], compensated[1], compensated[0],
        }};
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            const int expected = static_cast<int>(std::lround(
                expected_bgr[channel] * 255.f));
            CAPTURE(channel, expected);
            CHECK(std::abs(
                static_cast<int>(cvd_pixels[center + channel]) -
                expected) <= 1);
        }
        CHECK(cvd_pixels[center + 3] == flat_rgba[3]);

        ALMetalWorldPresentationScene grain_scene = flat_scene;
        grain_scene.grain_amount = 1.f;
        grain_scene.grain_style = 1;
        grain_scene.grain_size = 3.f;
        grain_scene.grain_range = 0.5f;
        grain_scene.grain_animated = false;
        auto frozen_grain = renderer->renderPresentationPost(
            grain_scene, &error);
        INFO(error);
        REQUIRE(frozen_grain);
        const auto frozen_grain_pixels = read_output(*frozen_grain);
        auto repeated_grain = renderer->renderPresentationPost(
            grain_scene, &error);
        INFO(error);
        REQUIRE(repeated_grain);
        CHECK(read_output(*repeated_grain) == frozen_grain_pixels);
        CHECK(frozen_grain_pixels != flat_output);
        grain_scene.grain_animated = true;
        grain_scene.frame_id = 73;
        auto animated_grain = renderer->renderPresentationPost(
            grain_scene, &error);
        INFO(error);
        REQUIRE(animated_grain);
        const auto animated_grain_pixels = read_output(*animated_grain);
        CHECK(animated_grain_pixels != frozen_grain_pixels);
        for (std::size_t pixel = 0; pixel < width * height; ++pixel)
        {
            CHECK(animated_grain_pixels[pixel * 4 + 3] == flat_rgba[3]);
        }

        ALMetalWorldPresentationScene dither_scene = flat_scene;
        dither_scene.dither_amount = 1.f;
        dither_scene.dither_bits = 8;
        dither_scene.dither_animated = false;
        auto frozen_dither = renderer->renderPresentationPost(
            dither_scene, &error);
        INFO(error);
        REQUIRE(frozen_dither);
        const auto frozen_dither_pixels = read_output(*frozen_dither);
        dither_scene.dither_animated = true;
        dither_scene.frame_id = 37;
        auto animated_dither = renderer->renderPresentationPost(
            dither_scene, &error);
        INFO(error);
        REQUIRE(animated_dither);
        const auto animated_dither_pixels = read_output(*animated_dither);
        CHECK(frozen_dither_pixels != flat_output);
        CHECK(animated_dither_pixels != frozen_dither_pixels);

        ALMetalWorldPresentationScene preview_scene = flat_scene;
        preview_scene.preview_mode = 7;
        auto preview = renderer->renderPresentationPost(
            preview_scene, &error);
        INFO(error);
        REQUIRE(preview);
        const auto preview_pixels = read_output(*preview);
        CHECK(std::abs(static_cast<int>(preview_pixels[center + 0]) - 0) <= 1);
        CHECK(std::abs(static_cast<int>(preview_pixels[center + 1]) - 179) <= 1);
        CHECK(std::abs(static_cast<int>(preview_pixels[center + 2]) - 77) <= 1);
        CHECK(preview_pixels[center + 3] == flat_rgba[3]);

        std::array<std::uint8_t, width * height * 4> reference_pixels{};
        for (std::size_t pixel = 0; pixel < width * height; ++pixel)
        {
            reference_pixels[pixel * 4 + 0] = 224u;
            reference_pixels[pixel * 4 + 1] = 32u;
            reference_pixels[pixel * 4 + 2] = 80u;
            reference_pixels[pixel * 4 + 3] = 63u;
        }
        auto reference_source = make_source(
            ALMetalPixelFormat::rgba8_unorm, reference_pixels.data(),
            width * 4, "Alchemy final-presentation reference still");
        auto reference = renderer->capturePresentationReference(
            *reference_source, &error);
        INFO(error);
        REQUIRE(reference);
        CHECK(reference->descriptor().colors[0].format ==
              ALMetalPixelFormat::rgba8_unorm);
        std::array<std::uint8_t, width * height * 4>
            captured_reference_pixels{};
        REQUIRE(reference->colorTexture(0)->readback(
            *device, 0, 0, {}, captured_reference_pixels.data(),
            width * 4, &error));
        INFO(error);
        CHECK(captured_reference_pixels == reference_pixels);
        ALMetalWorldPresentationScene reference_scene = flat_scene;
        reference_scene.reference_texture = reference->colorTexture(0);
        reference_scene.reference_mode = 1;
        reference_scene.reference_position = 0.5f;
        auto wipe = renderer->renderPresentationPost(
            reference_scene, &error);
        INFO(error);
        REQUIRE(wipe);
        const auto wipe_pixels = read_output(*wipe);
        const std::size_t left = texel(1, height / 2);
        const std::size_t right = texel(width - 2, height / 2);
        CHECK(wipe_pixels[left + 0] == 80u);
        CHECK(wipe_pixels[left + 1] == 32u);
        CHECK(wipe_pixels[left + 2] == 224u);
        CHECK(wipe_pixels[left + 3] == 63u);
        CHECK(wipe_pixels[right + 0] == flat_rgba[2]);
        CHECK(wipe_pixels[right + 1] == flat_rgba[1]);
        CHECK(wipe_pixels[right + 2] == flat_rgba[0]);
        CHECK(wipe_pixels[right + 3] == flat_rgba[3]);
        reference_scene.reference_mode = 2;
        auto side_by_side = renderer->renderPresentationPost(
            reference_scene, &error);
        INFO(error);
        REQUIRE(side_by_side);
        const auto side_by_side_pixels = read_output(*side_by_side);
        CHECK(side_by_side_pixels[left + 2] == 224u);
        CHECK(side_by_side_pixels[right + 2] == flat_rgba[0]);

        ALMetalWorldPresentationScene invalid;
        error.clear();
        CHECK_FALSE(renderer->renderPresentationPost(invalid, &error));
        CHECK(error == "Metal world presentation scene is invalid");
        invalid = flat_scene;
        invalid.reference_mode = 3;
        error.clear();
        CHECK_FALSE(renderer->renderPresentationPost(invalid, &error));
        CHECK(error == "Metal world presentation scene is invalid");
        invalid = flat_scene;
        invalid.reference_mode = 1;
        error.clear();
        CHECK_FALSE(renderer->renderPresentationPost(invalid, &error));
        CHECK(error == "Metal world presentation reference is missing");
        invalid.reference_texture = hdr_source->colorTexture(0);
        error.clear();
        CHECK_FALSE(renderer->renderPresentationPost(invalid, &error));
        CHECK(error ==
              "Metal world presentation reference is incompatible");
        invalid = flat_scene;
        invalid.cvd_mode = 4;
        error.clear();
        CHECK_FALSE(renderer->renderPresentationPost(invalid, &error));
        CHECK(error == "Metal world presentation scene is invalid");
        invalid = flat_scene;
        invalid.lens_distortion_k[0] = 0.51f;
        error.clear();
        CHECK_FALSE(renderer->renderPresentationPost(invalid, &error));
        CHECK(error == "Metal world presentation scene is invalid");
        invalid = flat_scene;
        invalid.grain_tint[1] = 1.01f;
        error.clear();
        CHECK_FALSE(renderer->renderPresentationPost(invalid, &error));
        CHECK(error == "Metal world presentation scene is invalid");

        std::array<std::uint16_t, width * height * 4> half_pixels{};
        auto half_source = make_source(
            ALMetalPixelFormat::rgba16_float, half_pixels.data(),
            width * 4 * sizeof(std::uint16_t),
            "Alchemy incompatible final-presentation source");
        invalid = flat_scene;
        invalid.source = half_source.get();
        error.clear();
        CHECK_FALSE(renderer->renderPresentationPost(invalid, &error));
        CHECK(error == "Metal world presentation source is incompatible");
        error.clear();
        CHECK_FALSE(renderer->capturePresentationReference(
            *half_source, &error));
        CHECK(error ==
              "Metal world presentation-reference source is incompatible");
    }
}

TEST_CASE("almetal: native final color serves one-shot scene pixels", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        auto renderer = ALMetalWorldGBufferRenderer::create(
            *device, &error);
        INFO(error);
        REQUIRE(renderer);

        ALMetalRenderTargetDescriptor descriptor;
        descriptor.width = 2;
        descriptor.height = 2;
        descriptor.colors[0].format = ALMetalPixelFormat::rgba8_unorm;
        descriptor.label = "Alchemy scene-pixel RGBA8 test target";
        auto source = ALMetalRenderTarget::create(
            *device, descriptor, &error);
        INFO(error);
        REQUIRE(source);
        const std::array<std::uint8_t, 16> pixels{{
            255,   0,  64, 255,   0, 255,   0, 128,
              0,   0, 255, 255, 255, 255, 255,   0,
        }};
        auto upload = device->makeCommandBuffer(
            "Alchemy scene-pixel RGBA8 upload", &error);
        INFO(error);
        REQUIRE(upload);
        id<MTLBuffer> staging = [nativeDevice(*device)
            newBufferWithBytes:pixels.data()
                      length:pixels.size()
                     options:MTLResourceStorageModeShared];
        REQUIRE(staging);
        id<MTLBlitCommandEncoder> blit =
            [nativeCommand(*upload) blitCommandEncoder];
        REQUIRE(blit);
        [blit copyFromBuffer:staging
                sourceOffset:0
           sourceBytesPerRow:2 * 4
         sourceBytesPerImage:pixels.size()
                  sourceSize:MTLSizeMake(2, 2, 1)
                   toTexture:(__bridge id<MTLTexture>)
                       source->colorTexture(0)->nativeHandle()
            destinationSlice:0
            destinationLevel:0
           destinationOrigin:MTLOriginMake(0, 0, 0)];
        [blit endEncoding];
        REQUIRE(upload->commit(&error));
        INFO(error);

        float color[4]{};
        REQUIRE(renderer->readSceneColorPixel(
            *source, 0, 0, color, &error));
        INFO(error);
        CHECK(color[0] == 1.f);
        CHECK(color[1] == 0.f);
        CHECK(std::abs(color[2] - 64.f / 255.f) < 0.000001f);
        CHECK(color[3] == 1.f);
        REQUIRE(renderer->readSceneColorPixel(
            *source, 1, 1, color, &error));
        INFO(error);
        CHECK(color[0] == 1.f);
        CHECK(color[1] == 1.f);
        CHECK(color[2] == 1.f);
        CHECK(color[3] == 0.f);

        const std::array<float, 4> untouched{{-1.f, -2.f, -3.f, -4.f}};
        std::copy(untouched.begin(), untouched.end(), color);
        error.clear();
        CHECK_FALSE(renderer->readSceneColorPixel(
            *source, 2, 0, color, &error));
        CHECK(error == "Metal world scene-pixel source is incompatible");
        CHECK(std::equal(untouched.begin(), untouched.end(), color));

        descriptor.width = 1;
        descriptor.height = 1;
        descriptor.colors[0].format = ALMetalPixelFormat::rgba16_float;
        descriptor.label = "Alchemy scene-pixel RGBA16F test target";
        error.clear();
        auto hdr_source = ALMetalRenderTarget::create(
            *device, descriptor, &error);
        INFO(error);
        REQUIRE(hdr_source);
        const std::array<std::uint16_t, 4> half_pixel{{
            0x3800u, 0xb400u, 0x3c00u, 0x0001u,
        }};
        upload = device->makeCommandBuffer(
            "Alchemy scene-pixel RGBA16F upload", &error);
        INFO(error);
        REQUIRE(upload);
        staging = [nativeDevice(*device)
            newBufferWithBytes:half_pixel.data()
                      length:half_pixel.size() * sizeof(half_pixel[0])
                     options:MTLResourceStorageModeShared];
        REQUIRE(staging);
        blit = [nativeCommand(*upload) blitCommandEncoder];
        REQUIRE(blit);
        [blit copyFromBuffer:staging
                sourceOffset:0
           sourceBytesPerRow:half_pixel.size() * sizeof(half_pixel[0])
         sourceBytesPerImage:half_pixel.size() * sizeof(half_pixel[0])
                  sourceSize:MTLSizeMake(1, 1, 1)
                   toTexture:(__bridge id<MTLTexture>)
                       hdr_source->colorTexture(0)->nativeHandle()
            destinationSlice:0
            destinationLevel:0
           destinationOrigin:MTLOriginMake(0, 0, 0)];
        [blit endEncoding];
        REQUIRE(upload->commit(&error));
        INFO(error);
        REQUIRE(renderer->readSceneColorPixel(
            *hdr_source, 0, 0, color, &error));
        INFO(error);
        CHECK(color[0] == 0.5f);
        CHECK(color[1] == -0.25f);
        CHECK(color[2] == 1.f);
        CHECK(color[3] == std::ldexp(1.f, -24));
    }
}

TEST_CASE("almetal: native hero faces publish filtered cube radiance", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        auto renderer = ALMetalWorldGBufferRenderer::create(
            *device, &error);
        INFO(error);
        REQUIRE(renderer);

        ALMetalRenderTargetDescriptor source_descriptor;
        source_descriptor.width = 4;
        source_descriptor.height = 4;
        source_descriptor.colors[0].format =
            ALMetalPixelFormat::rgba8_unorm;
        source_descriptor.label = "Alchemy native hero-face source test";
        auto source = ALMetalRenderTarget::create(
            *device, source_descriptor, &error);
        INFO(error);
        REQUIRE(source);

        std::array<std::array<std::uint8_t, 4 * 4 * 4>, 6>
            source_faces{};
        for (std::uint32_t face = 0; face < 6; ++face)
        {
            for (std::uint32_t y = 0; y < 4; ++y)
            {
                for (std::uint32_t x = 0; x < 4; ++x)
                {
                    const std::size_t texel = (y * 4 + x) * 4;
                    source_faces[face][texel + 0] =
                        static_cast<std::uint8_t>(face * 32 + x * 7 + y);
                    source_faces[face][texel + 1] =
                        static_cast<std::uint8_t>(face * 11 + x * 3 + y * 13);
                    source_faces[face][texel + 2] =
                        static_cast<std::uint8_t>(face * 19 + x * 17 + y * 5);
                    source_faces[face][texel + 3] = 255;
                }
            }
        }
        std::unique_ptr<ALMetalTexture> source_cube;
        std::unique_ptr<ALMetalTexture> radiance_cube;
        std::uint32_t valid_faces = 0;

        for (std::uint32_t face = 0; face < 6; ++face)
        {
            const std::array<std::uint8_t, 4 * 4 * 4>& pixels =
                source_faces[face];
            auto upload = device->makeCommandBuffer(
                "Alchemy native hero-face test upload", &error);
            INFO(error);
            REQUIRE(upload);
            id<MTLBuffer> staging = [nativeDevice(*device)
                newBufferWithBytes:pixels.data()
                          length:pixels.size()
                         options:MTLResourceStorageModeShared];
            REQUIRE(staging);
            id<MTLBlitCommandEncoder> blit =
                [nativeCommand(*upload) blitCommandEncoder];
            REQUIRE(blit);
            [blit copyFromBuffer:staging
                    sourceOffset:0
               sourceBytesPerRow:4 * 4
             sourceBytesPerImage:pixels.size()
                      sourceSize:MTLSizeMake(4, 4, 1)
                       toTexture:(__bridge id<MTLTexture>)
                           source->colorTexture(0)->nativeHandle()
                destinationSlice:0
                destinationLevel:0
               destinationOrigin:MTLOriginMake(0, 0, 0)];
            [blit endEncoding];
            REQUIRE(upload->commit(&error));
            INFO(error);
            REQUIRE(renderer->updateHeroProbeFace(
                *source, face, 1, source_cube, valid_faces, &error));
            INFO(error);
            CHECK(valid_faces == ((1u << (face + 1)) - 1u));
            if (face == 0)
            {
                error.clear();
                CHECK_FALSE(renderer->filterHeroProbeRadiance(
                    *source_cube, valid_faces, 1, 0.5f,
                    radiance_cube, &error));
                CHECK(error ==
                      "Metal hero-probe radiance source is incomplete");
            }
        }
        REQUIRE(source_cube);
        CHECK(source_cube->descriptor().type ==
              ALMetalTextureType::texture_cube);
        CHECK(source_cube->descriptor().mipmap_level_count == 2);

        // cubeSnapshot renders each GL face with these forward/up vectors.
        // Native world vertices flip clip-space Y, so Metal storage row zero
        // retains GL's lower framebuffer row.  At texel coordinates (u, v),
        // the captured world direction is therefore
        // forward + u * (forward x up) + v * up.  Sample the production-
        // copied cube through the physical Metal cube sampler at every texel
        // centre: any face swap, row/column flip, or quarter-turn fails this
        // asymmetric oracle instead of merely proving same-slice blits.
        constexpr std::size_t direction_count = 6 * 4 * 4;
        constexpr std::array<std::array<float, 3>, 6> look{{
            {{ 1.f,  0.f,  0.f}}, {{-1.f,  0.f,  0.f}},
            {{ 0.f,  1.f,  0.f}}, {{ 0.f, -1.f,  0.f}},
            {{ 0.f,  0.f,  1.f}}, {{ 0.f,  0.f, -1.f}},
        }};
        constexpr std::array<std::array<float, 3>, 6> up{{
            {{0.f, -1.f,  0.f}}, {{0.f, -1.f,  0.f}},
            {{0.f,  0.f,  1.f}}, {{0.f,  0.f, -1.f}},
            {{0.f, -1.f,  0.f}}, {{0.f, -1.f,  0.f}},
        }};
        std::array<std::array<float, 4>, direction_count> directions{};
        for (std::uint32_t face = 0; face < 6; ++face)
        {
            const std::array<float, 3> right{{
                look[face][1] * up[face][2] -
                    look[face][2] * up[face][1],
                look[face][2] * up[face][0] -
                    look[face][0] * up[face][2],
                look[face][0] * up[face][1] -
                    look[face][1] * up[face][0],
            }};
            for (std::uint32_t y = 0; y < 4; ++y)
            {
                const float v =
                    2.f * (static_cast<float>(y) + 0.5f) / 4.f - 1.f;
                for (std::uint32_t x = 0; x < 4; ++x)
                {
                    const float u =
                        2.f * (static_cast<float>(x) + 0.5f) / 4.f - 1.f;
                    const std::size_t index = face * 16 + y * 4 + x;
                    for (std::size_t axis = 0; axis < 3; ++axis)
                    {
                        directions[index][axis] = look[face][axis] +
                            u * right[axis] + v * up[face][axis];
                    }
                    directions[index][3] = 0.f;
                }
            }
        }

        auto library = ALMetalShaderLibrary::loadBuiltin(*device, &error);
        INFO(error);
        REQUIRE(library);
        ALMetalComputePipelineDescriptor sample_descriptor;
        sample_descriptor.library = library.get();
        sample_descriptor.function =
            "almetal_test_sample_cube_directions";
        sample_descriptor.label =
            "Alchemy hero cube-camera orientation sample pipeline";
        auto sample_pipeline = ALMetalComputePipeline::create(
            *device, sample_descriptor, &error);
        INFO(error);
        REQUIRE(sample_pipeline);

        ALMetalBufferDescriptor direction_descriptor;
        direction_descriptor.length = sizeof(directions);
        direction_descriptor.storage = ALMetalStorageMode::shared;
        direction_descriptor.label =
            "Alchemy hero cube-camera sample directions";
        auto direction_buffer = ALMetalBuffer::create(
            *device, direction_descriptor, &error);
        INFO(error);
        REQUIRE(direction_buffer);
        REQUIRE(direction_buffer->write(
            0, directions.data(), sizeof(directions), &error));

        std::array<std::array<float, 4>, direction_count> samples{};
        ALMetalBufferDescriptor sample_result_descriptor;
        sample_result_descriptor.length = sizeof(samples);
        sample_result_descriptor.storage = ALMetalStorageMode::shared;
        sample_result_descriptor.label =
            "Alchemy hero cube-camera orientation samples";
        auto sample_results = ALMetalBuffer::create(
            *device, sample_result_descriptor, &error);
        INFO(error);
        REQUIRE(sample_results);

        auto sample_command = device->makeCommandBuffer(
            "Alchemy hero cube-camera orientation sample", &error);
        INFO(error);
        REQUIRE(sample_command);
        auto sample_encoder = ALMetalComputeEncoder::begin(
            *sample_command,
            "Alchemy hero cube-camera orientation sample encoder",
            &error);
        INFO(error);
        REQUIRE(sample_encoder);
        REQUIRE(sample_encoder->setPipeline(*sample_pipeline, &error));
        REQUIRE(sample_encoder->setTexture(0, source_cube.get(), &error));
        REQUIRE(sample_encoder->setBuffer(
            0, *direction_buffer, 0, &error));
        REQUIRE(sample_encoder->setBuffer(
            1, *sample_results, 0, &error));
        REQUIRE(sample_encoder->dispatch(
            direction_count, 1, 1, 32, 1, 1, &error));
        REQUIRE(sample_encoder->end(&error));
        REQUIRE(sample_command->commitAndWait(&error));
        INFO(error);
        REQUIRE(sample_results->read(
            0, samples.data(), sizeof(samples), &error));
        INFO(error);
        for (std::uint32_t face = 0; face < 6; ++face)
        {
            for (std::uint32_t y = 0; y < 4; ++y)
            {
                for (std::uint32_t x = 0; x < 4; ++x)
                {
                    const std::size_t index = face * 16 + y * 4 + x;
                    const std::size_t texel = (y * 4 + x) * 4;
                    CAPTURE(face, x, y);
                    for (std::size_t channel = 0; channel < 4; ++channel)
                    {
                        CHECK(std::abs(samples[index][channel] -
                            static_cast<float>(
                                source_faces[face][texel + channel]) /
                                255.f) < 0.001f);
                    }
                }
            }
        }

        REQUIRE(renderer->filterHeroProbeRadiance(
            *source_cube, valid_faces, 1, 0.5f,
            radiance_cube, &error));
        INFO(error);
        REQUIRE(radiance_cube);
        CHECK(radiance_cube->descriptor().type ==
              ALMetalTextureType::texture_cube);
        CHECK(radiance_cube->descriptor().format ==
              ALMetalPixelFormat::rgba8_unorm);
        CHECK(radiance_cube->descriptor().mipmap_level_count == 2);

        for (std::uint32_t face = 0; face < 6; ++face)
        {
            std::array<std::uint8_t, 4 * 4 * 4> pixels{};
            REQUIRE(radiance_cube->readback(
                *device, 0, face, {}, pixels.data(), 4 * 4, &error));
            INFO(error);
            for (std::uint32_t y = 1; y <= 2; ++y)
            {
                for (std::uint32_t x = 1; x <= 2; ++x)
                {
                    const std::size_t texel = (y * 4 + x) * 4;
                    CHECK(std::abs(static_cast<int>(pixels[texel + 0]) -
                                   source_faces[face][texel + 0]) <= 1);
                    CHECK(std::abs(static_cast<int>(pixels[texel + 1]) -
                                   source_faces[face][texel + 1]) <= 1);
                    CHECK(std::abs(static_cast<int>(pixels[texel + 2]) -
                                   source_faces[face][texel + 2]) <= 1);
                    CHECK(std::abs(
                        static_cast<int>(pixels[texel + 3]) - 128) <= 1);
                }
            }
        }

        ALMetalTexture* retained_radiance = radiance_cube.get();
        REQUIRE(renderer->filterHeroProbeRadiance(
            *source_cube, valid_faces, 1, 1.f,
            radiance_cube, &error));
        INFO(error);
        CHECK(radiance_cube.get() == retained_radiance);

        ALMetalRenderTargetDescriptor invalid_descriptor =
            source_descriptor;
        invalid_descriptor.height = 2;
        auto invalid = ALMetalRenderTarget::create(
            *device, invalid_descriptor, &error);
        INFO(error);
        REQUIRE(invalid);
        error.clear();
        CHECK_FALSE(renderer->updateHeroProbeFace(
            *invalid, 0, 1, source_cube, valid_faces, &error));
        CHECK(error == "Metal hero-probe face source is incompatible");

        // Production HDR faces use RGBA16F and publish filtered R11G11B10F.
        // Clear each face to a distinct value so the test covers that format
        // branch and preserves cube-slice addressing independently of the
        // stronger per-pixel RGBA8 orientation checks above.
        ALMetalRenderTargetDescriptor hdr_descriptor = source_descriptor;
        hdr_descriptor.colors[0].format =
            ALMetalPixelFormat::rgba16_float;
        hdr_descriptor.label = "Alchemy native HDR hero-face source test";
        auto hdr_source = ALMetalRenderTarget::create(
            *device, hdr_descriptor, &error);
        INFO(error);
        REQUIRE(hdr_source);
        std::unique_ptr<ALMetalTexture> hdr_source_cube;
        std::unique_ptr<ALMetalTexture> hdr_radiance_cube;
        std::uint32_t hdr_valid_faces = 0;
        for (std::uint32_t face = 0; face < 6; ++face)
        {
            ALMetalRenderPassConfig clear;
            clear.colors[0].load = ALMetalLoadAction::clear;
            clear.colors[0].store = ALMetalStoreAction::store;
            clear.colors[0].clear = {
                0.125 * double(face + 1),
                0.0625 * double(face + 1),
                0.03125 * double(face + 1), 1.0};
            auto pass = hdr_source->makeRenderPass(clear, &error);
            auto command = pass ? device->makeCommandBuffer(
                "Alchemy native HDR hero-face clear", &error) : nullptr;
            auto encoder = command && pass ? ALMetalRenderEncoder::begin(
                *command, *pass,
                "Alchemy native HDR hero-face clear encoder", &error)
                : nullptr;
            INFO(error);
            REQUIRE(encoder);
            REQUIRE(encoder->end(&error));
            REQUIRE(command->commitAndWait(&error));
            REQUIRE(renderer->updateHeroProbeFace(
                *hdr_source, face, 1, hdr_source_cube,
                hdr_valid_faces, &error));
            INFO(error);
        }
        REQUIRE(renderer->filterHeroProbeRadiance(
            *hdr_source_cube, hdr_valid_faces, 1, 1.f,
            hdr_radiance_cube, &error));
        INFO(error);
        REQUIRE(hdr_radiance_cube);
        CHECK(hdr_radiance_cube->descriptor().format ==
              ALMetalPixelFormat::rg11b10_float);
        CHECK(hdr_radiance_cube->descriptor().mipmap_level_count == 2);
        std::array<std::uint32_t, 4 * 4> hdr_face_zero{};
        std::array<std::uint32_t, 4 * 4> hdr_face_five{};
        REQUIRE(hdr_radiance_cube->readback(
            *device, 0, 0, {}, hdr_face_zero.data(), 4 * 4, &error));
        REQUIRE(hdr_radiance_cube->readback(
            *device, 0, 5, {}, hdr_face_five.data(), 4 * 4, &error));
        INFO(error);
        CHECK(hdr_face_zero[4 + 1] != 0);
        CHECK(hdr_face_five[4 + 1] != 0);
        CHECK(hdr_face_zero[4 + 1] != hdr_face_five[4 + 1]);
    }
}

TEST_CASE("almetal: native ordinary probes filter radiance and project SH", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        auto renderer = ALMetalWorldGBufferRenderer::create(
            *device, &error);
        INFO(error);
        REQUIRE(renderer);

        ALMetalRenderTargetDescriptor source_descriptor;
        source_descriptor.width = 8;
        source_descriptor.height = 8;
        source_descriptor.colors[0].format =
            ALMetalPixelFormat::rgba8_unorm;
        source_descriptor.label =
            "Alchemy native ordinary-probe supersample test";
        auto source = ALMetalRenderTarget::create(
            *device, source_descriptor, &error);
        INFO(error);
        REQUIRE(source);

        std::unique_ptr<ALMetalTexture> source_cube;
        std::unique_ptr<ALMetalTexture> radiance_cube;
        std::uint32_t valid_faces = 0;
        CHECK_FALSE(renderer->updateReflectionProbeFace(
            *source, 0, 3, 1,
            source_cube, valid_faces, &error));
        CHECK(error ==
              "Metal reflection-probe face source is incompatible");
        error.clear();
        for (std::uint32_t face = 0; face < 6; ++face)
        {
            const std::array<std::uint8_t, 4> color{{
                static_cast<std::uint8_t>(32 + face * 24),
                static_cast<std::uint8_t>(16 + face * 17),
                static_cast<std::uint8_t>(8 + face * 11), 255,
            }};
            std::array<std::uint8_t, 8 * 8 * 4> pixels{};
            for (std::size_t texel = 0; texel < 8 * 8; ++texel)
            {
                std::copy(color.begin(), color.end(),
                          pixels.begin() + texel * 4);
            }
            auto upload = device->makeCommandBuffer(
                "Alchemy ordinary-probe face upload", &error);
            INFO(error);
            REQUIRE(upload);
            id<MTLBuffer> staging = [nativeDevice(*device)
                newBufferWithBytes:pixels.data()
                          length:pixels.size()
                         options:MTLResourceStorageModeShared];
            REQUIRE(staging);
            id<MTLBlitCommandEncoder> blit =
                [nativeCommand(*upload) blitCommandEncoder];
            REQUIRE(blit);
            [blit copyFromBuffer:staging
                    sourceOffset:0
               sourceBytesPerRow:8 * 4
             sourceBytesPerImage:pixels.size()
                      sourceSize:MTLSizeMake(8, 8, 1)
                       toTexture:(__bridge id<MTLTexture>)
                           source->colorTexture(0)->nativeHandle()
                destinationSlice:0
                destinationLevel:0
               destinationOrigin:MTLOriginMake(0, 0, 0)];
            [blit endEncoding];
            REQUIRE(upload->commit(&error));
            REQUIRE(renderer->updateReflectionProbeFace(
                *source, face, 4, 1,
                source_cube, valid_faces, &error));
            INFO(error);
            CHECK(valid_faces == ((1u << (face + 1)) - 1u));
            if (face == 0)
            {
                CHECK_FALSE(renderer->filterReflectionProbeRadiance(
                    *source_cube, valid_faces, 1,
                    radiance_cube, &error));
                CHECK(error ==
                      "Metal reflection-probe radiance source is incomplete");
                error.clear();
            }
        }
        REQUIRE(source_cube);
        CHECK(source_cube->descriptor().width == 4);
        CHECK(source_cube->descriptor().mipmap_level_count == 2);
        REQUIRE(renderer->filterReflectionProbeRadiance(
            *source_cube, valid_faces, 1, radiance_cube, &error));
        INFO(error);
        REQUIRE(radiance_cube);
        CHECK(radiance_cube->descriptor().format ==
              ALMetalPixelFormat::rgba8_unorm);
        CHECK(radiance_cube->descriptor().mipmap_level_count == 2);
        std::array<std::uint8_t, 4 * 4 * 4> face_zero{};
        std::array<std::uint8_t, 4 * 4 * 4> face_five{};
        REQUIRE(radiance_cube->readback(
            *device, 0, 0, {}, face_zero.data(), 4 * 4, &error));
        REQUIRE(radiance_cube->readback(
            *device, 0, 5, {}, face_five.data(), 4 * 4, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(face_zero[0]) - 32) <= 1);
        CHECK(std::abs(static_cast<int>(face_zero[1]) - 16) <= 1);
        CHECK(std::abs(static_cast<int>(face_zero[2]) - 8) <= 1);
        CHECK(std::abs(static_cast<int>(face_five[0]) - 152) <= 1);
        CHECK(std::abs(static_cast<int>(face_five[1]) - 101) <= 1);
        CHECK(std::abs(static_cast<int>(face_five[2]) - 63) <= 1);

        // Replace every source face with one uniform environment. Its SH has
        // only the DC coefficient, which gives an exact projection oracle
        // while still exercising the half-packed texture row and shared
        // completion buffer used by the default preview.
        const std::array<std::uint8_t, 4> uniform_color{{64, 128, 192, 255}};
        std::array<std::uint8_t, 8 * 8 * 4> uniform_pixels{};
        for (std::size_t texel = 0; texel < 8 * 8; ++texel)
        {
            std::copy(uniform_color.begin(), uniform_color.end(),
                      uniform_pixels.begin() + texel * 4);
        }
        for (std::uint32_t face = 0; face < 6; ++face)
        {
            auto upload = device->makeCommandBuffer(
                "Alchemy uniform ordinary-probe face upload", &error);
            INFO(error);
            REQUIRE(upload);
            id<MTLBuffer> staging = [nativeDevice(*device)
                newBufferWithBytes:uniform_pixels.data()
                          length:uniform_pixels.size()
                         options:MTLResourceStorageModeShared];
            REQUIRE(staging);
            id<MTLBlitCommandEncoder> blit =
                [nativeCommand(*upload) blitCommandEncoder];
            REQUIRE(blit);
            [blit copyFromBuffer:staging
                    sourceOffset:0
               sourceBytesPerRow:8 * 4
             sourceBytesPerImage:uniform_pixels.size()
                      sourceSize:MTLSizeMake(8, 8, 1)
                       toTexture:(__bridge id<MTLTexture>)
                           source->colorTexture(0)->nativeHandle()
                destinationSlice:0
                destinationLevel:0
               destinationOrigin:MTLOriginMake(0, 0, 0)];
            [blit endEncoding];
            REQUIRE(upload->commit(&error));
            REQUIRE(renderer->updateReflectionProbeFace(
                *source, face, 4, 1,
                source_cube, valid_faces, &error));
            INFO(error);
        }

        ALMetalTextureDescriptor sh_descriptor;
        sh_descriptor.format = ALMetalPixelFormat::rgba32_uint;
        sh_descriptor.width = 4;
        sh_descriptor.height = 8;
        sh_descriptor.storage = ALMetalStorageMode::private_gpu;
        sh_descriptor.usage = ALMetalTextureUsage::shader_read |
                              ALMetalTextureUsage::shader_write;
        sh_descriptor.label = "Alchemy native ordinary-probe SH test";
        auto sh_texture = ALMetalTexture::create(
            *device, sh_descriptor, &error);
        INFO(error);
        REQUIRE(sh_texture);
        std::unique_ptr<ALMetalBuffer> packed_words;
        std::unique_ptr<ALMetalCommandBuffer> pending;
        REQUIRE(renderer->projectReflectionProbeSH(
            *source_cube, valid_faces, 0, 4,
            *sh_texture, 3, packed_words, pending, &error));
        INFO(error);
        REQUIRE(packed_words);
        REQUIRE(pending);

        // Realtime reflection probes begin the radiance pass on the frame
        // after this asynchronous SH projection.  Prove that its publication
        // can remain nonblocking: a dependent blit committed to the viewer's
        // one Metal queue must observe the projected row without a CPU wait.
        ALMetalTextureDescriptor published_sh_descriptor = sh_descriptor;
        published_sh_descriptor.label =
            "Alchemy queue-ordered ordinary-probe SH publication test";
        auto published_sh = ALMetalTexture::create(
            *device, published_sh_descriptor, &error);
        INFO(error);
        REQUIRE(published_sh);
        auto publication = device->makeCommandBuffer(
            "Alchemy queue-ordered ordinary-probe SH publication", &error);
        INFO(error);
        REQUIRE(publication);
        ALMetalTextureCopy sh_publication_copy;
        sh_publication_copy.source_region = {0, 3, 4, 1};
        sh_publication_copy.destination_y = 5;
        REQUIRE(published_sh->copyFrom(
            *publication, *sh_texture, sh_publication_copy, &error));
        REQUIRE(publication->commitAndWait(&error));
        CHECK(pending->status() == ALMetalCommandStatus::completed);
        INFO(error);

        std::array<std::uint32_t, 16> buffer_words{};
        std::array<std::uint32_t, 16> texture_words{};
        REQUIRE(packed_words->read(
            0, buffer_words.data(), sizeof(buffer_words), &error));
        const ALMetalRegion2D sh_row{0, 5, 4, 1};
        REQUIRE(published_sh->readback(
            *device, 0, 0, sh_row, texture_words.data(),
            4 * 4 * sizeof(std::uint32_t), &error));
        INFO(error);
        CHECK(buffer_words == texture_words);

        const auto half_to_float = [](std::uint16_t value)
        {
            const float magnitude = ((value >> 10) & 0x1fu) == 0
                ? std::ldexp(static_cast<float>(value & 0x3ffu), -24)
                : std::ldexp(
                      static_cast<float>((value & 0x3ffu) + 0x400u),
                      static_cast<int>((value >> 10) & 0x1fu) - 25);
            return (value & 0x8000u) != 0 ? -magnitude : magnitude;
        };
        std::array<float, 32> coefficients{};
        for (std::size_t index = 0; index < buffer_words.size(); ++index)
        {
            coefficients[index * 2] = half_to_float(
                static_cast<std::uint16_t>(buffer_words[index]));
            coefficients[index * 2 + 1] = half_to_float(
                static_cast<std::uint16_t>(buffer_words[index] >> 16));
        }
        constexpr float dc_scale = 0.282095f * 4.f * 3.1415926536f;
        CHECK(std::abs(coefficients[0] -
                       (64.f / 255.f) * dc_scale) < 0.01f);
        CHECK(std::abs(coefficients[1] -
                       (128.f / 255.f) * dc_scale) < 0.01f);
        CHECK(std::abs(coefficients[2] -
                       (192.f / 255.f) * dc_scale) < 0.01f);
        for (std::size_t coefficient = 3; coefficient < 27; ++coefficient)
        {
            CHECK(std::abs(coefficients[coefficient]) < 0.01f);
        }
        for (std::size_t padding = 27; padding < 32; ++padding)
        {
            CHECK(coefficients[padding] == 0.f);
        }
        CHECK_FALSE(renderer->projectReflectionProbeSH(
            *source_cube, valid_faces, 0, 4,
            *sh_texture, 8, packed_words, pending, &error));
        CHECK(error ==
              "Metal reflection-probe SH inputs are incompatible");
    }
}

TEST_CASE("almetal: classic terrain tessellates its height field into the world G-buffer", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        auto renderer = ALMetalWorldGBufferRenderer::create(*device, &error);
        INFO(error);
        REQUIRE(renderer);

        const std::array<std::array<float, 4>, 4> control_points{{
            {{0.f, 0.f, 0.f, 1.f}},
            {{2.f, 0.f, 0.f, 1.f}},
            {{2.f, 2.f, 0.f, 1.f}},
            {{0.f, 2.f, 0.f, 1.f}},
        }};
        ALMetalBufferDescriptor vertex_descriptor;
        vertex_descriptor.length = sizeof(control_points);
        vertex_descriptor.storage = ALMetalStorageMode::shared;
        vertex_descriptor.label = "Alchemy terrain test control points";
        auto vertices = ALMetalBuffer::create(
            *device, vertex_descriptor, &error);
        INFO(error);
        REQUIRE(vertices);
        REQUIRE(vertices->write(
            0, control_points.data(), sizeof(control_points), &error));

        ALMetalTextureDescriptor detail_descriptor;
        detail_descriptor.format = ALMetalPixelFormat::rgba8_unorm_srgb;
        detail_descriptor.width = 1;
        detail_descriptor.height = 1;
        detail_descriptor.storage = ALMetalStorageMode::private_gpu;
        detail_descriptor.usage = ALMetalTextureUsage::shader_read;
        detail_descriptor.label = "Alchemy terrain red sRGB detail";
        auto detail = ALMetalTexture::create(
            *device, detail_descriptor, &error);
        INFO(error);
        REQUIRE(detail);

        ALMetalTextureDescriptor ramp_descriptor = detail_descriptor;
        ramp_descriptor.format = ALMetalPixelFormat::rgba8_unorm;
        ramp_descriptor.label = "Alchemy terrain opaque alpha ramp";
        auto ramp = ALMetalTexture::create(*device, ramp_descriptor, &error);
        INFO(error);
        REQUIRE(ramp);

        ALMetalTextureDescriptor overlay_descriptor = detail_descriptor;
        overlay_descriptor.label = "Alchemy terrain encoded parcel overlay";
        auto overlay = ALMetalTexture::create(
            *device, overlay_descriptor, &error);
        INFO(error);
        REQUIRE(overlay);

        ALMetalTextureDescriptor height_descriptor;
        height_descriptor.format = ALMetalPixelFormat::r32_float;
        height_descriptor.width = 8;
        height_descriptor.height = 8;
        height_descriptor.storage = ALMetalStorageMode::private_gpu;
        height_descriptor.usage = ALMetalTextureUsage::shader_read;
        height_descriptor.label = "Alchemy terrain flat height map";
        auto height = ALMetalTexture::create(
            *device, height_descriptor, &error);
        INFO(error);
        REQUIRE(height);

        ALMetalTextureDescriptor composition_descriptor = height_descriptor;
        composition_descriptor.format = ALMetalPixelFormat::rg16_float;
        composition_descriptor.label = "Alchemy terrain composition map";
        auto composition = ALMetalTexture::create(
            *device, composition_descriptor, &error);
        INFO(error);
        REQUIRE(composition);

        const std::array<std::uint8_t, 4> detail_pixel{{255, 0, 0, 255}};
        const std::array<std::uint8_t, 4> ramp_pixel{{0, 0, 0, 255}};
        const std::array<std::uint8_t, 4> overlay_pixel{{128, 128, 128, 255}};
        std::array<float, 64> height_pixels{};
        for (std::size_t row = 0; row < 8; ++row)
        {
            for (std::size_t column = 0; column < 8; ++column)
            {
                // Texel (x,y) holds grid x + 2*y: one and two metres of
                // rise per metre, so both surface modes must emit the same
                // non-axis-aligned slope.
                height_pixels[row * 8 + column] =
                    (static_cast<float>(column) - 2.f) +
                    2.f * (static_cast<float>(row) - 2.f);
            }
        }
        const std::array<std::uint16_t, 128> composition_pixels{};
        auto upload = device->makeCommandBuffer(
            "Alchemy terrain test texture upload", &error);
        INFO(error);
        REQUIRE(upload);
        REQUIRE(detail->upload(
            *upload, 0, 0, {}, detail_pixel.data(), 4, &error));
        REQUIRE(ramp->upload(
            *upload, 0, 0, {}, ramp_pixel.data(), 4, &error));
        REQUIRE(overlay->upload(
            *upload, 0, 0, {}, overlay_pixel.data(), 4, &error));
        REQUIRE(height->upload(
            *upload, 0, 0, {}, height_pixels.data(), 8 * sizeof(float),
            &error));
        REQUIRE(composition->upload(
            *upload, 0, 0, {}, composition_pixels.data(),
            8 * 2 * sizeof(std::uint16_t), &error));
        REQUIRE(upload->commitAndWait(&error));
        INFO(error);

        ALMetalWorldSimpleBatch batch;
        batch.terrain = true;
        batch.vertices = vertices.get();
        batch.vertex_count = control_points.size();
        batch.texture_count = 4;
        for (std::size_t texture = 0; texture < 4; ++texture)
        {
            batch.diffuse_textures[texture] = detail.get();
        }
        batch.terrain_height_texture = height.get();
        batch.terrain_composition_texture = composition.get();
        batch.terrain_alpha_ramp_texture = ramp.get();
        std::fill_n(
            batch.terrain_tessellation_factors, 6, std::uint16_t{0x4400});
        batch.terrain_grid_scale = 1.f;
        batch.terrain_region_scale = 4.f;
        batch.terrain_detail_scale = 1.f;
        batch.terrain_triplanar_blend = 8.f;
        batch.terrain_smoothing = true;
        batch.terrain_triplanar = true;
        batch.terrain_tessellation_pinned = true;
        batch.modelview_projection[0] = 0.8f;
        batch.modelview_projection[5] = 0.8f;
        // Flatten clip Z so the test can exercise heights beyond the
        // canonical clip volume without changing the expected footprint.
        batch.modelview_projection[10] = 0.f;
        batch.modelview_projection[12] = -0.8f;
        batch.modelview_projection[13] = -0.8f;
        batch.modelview_projection[15] = 1.f;
        for (std::size_t axis = 0; axis < 3; ++axis)
        {
            batch.normal_matrix[axis][axis] = 1.f;
        }

        ALMetalWorldGBufferScene scene;
        scene.batches = &batch;
        scene.batch_count = 1;
        scene.width = 32;
        scene.height = 32;
        scene.normal_hdr = true;
        scene.hdr = true;

        batch.terrain_tessellation_factors[0] = 0;
        CHECK_FALSE(renderer->render(scene, &error));
        CHECK(error == "Metal world terrain batch is invalid");
        batch.terrain_tessellation_factors[0] = 0x4400;
        error.clear();

        batch.terrain_parcel_overlay_texture = ramp.get();
        CHECK_FALSE(renderer->render(scene, &error));
        CHECK(error == "Metal world terrain batch is invalid");
        batch.terrain_parcel_overlay_texture = nullptr;
        error.clear();

        auto result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(result);
        REQUIRE(device->waitUntilIdle(&error));
        INFO(error);

        std::array<std::uint8_t, 32 * 32 * 4> albedo{};
        REQUIRE(result->colorTexture(0)->readback(
            *device, 0, 0, {}, albedo.data(), 32 * 4, &error));
        INFO(error);
        std::array<std::uint8_t, 32 * 32 * 4> specular{};
        REQUIRE(result->colorTexture(1)->readback(
            *device, 0, 0, {}, specular.data(), 32 * 4, &error));
        INFO(error);
        std::array<std::uint16_t, 32 * 32 * 4> normal{};
        REQUIRE(result->colorTexture(2)->readback(
            *device, 0, 0, {}, normal.data(), 32 * 8, &error));
        INFO(error);

        const std::size_t center = (16 * 32 + 16) * 4;
        CHECK(albedo[center + 0] == 255);
        CHECK(albedo[center + 1] == 0);
        CHECK(albedo[center + 2] == 0);
        CHECK(albedo[center + 3] == 0);
        for (std::size_t channel = 0; channel < 4; ++channel)
        {
            CHECK(specular[center + channel] == 0);
        }
        CHECK(std::abs(static_cast<int>(normal[center + 0]) - 24576) <= 1);
        CHECK(std::abs(static_cast<int>(normal[center + 1]) - 16384) <= 1);
        CHECK(normal[center + 2] == 0);
        CHECK(std::abs(static_cast<int>(normal[center + 3]) - 22282) <= 2);

        // The live parcel overlay's Metal mirror is sRGB, so sampling decodes
        // before blending and the sRGB G-buffer store encodes it back to the
        // original byte. This guards against a missing or double decode.
        batch.terrain_parcel_overlay_texture = overlay.get();
        auto overlay_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(overlay_result);
        REQUIRE(device->waitUntilIdle(&error));
        INFO(error);
        albedo.fill(0);
        REQUIRE(overlay_result->colorTexture(0)->readback(
            *device, 0, 0, {}, albedo.data(), 32 * 4, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(albedo[center + 0]) - 128) <= 1);
        CHECK(std::abs(static_cast<int>(albedo[center + 1]) - 128) <= 1);
        CHECK(std::abs(static_cast<int>(albedo[center + 2]) - 128) <= 1);
        CHECK(albedo[center + 3] == 0);
        batch.terrain_parcel_overlay_texture = nullptr;

        const std::size_t outside = (1 * 32 + 1) * 4;
        CHECK(albedo[outside + 0] == 255);
        CHECK(albedo[outside + 1] == 0);
        CHECK(albedo[outside + 2] == 255);
        CHECK(albedo[outside + 3] == 255);

        // Exercise the world-stable hex lattice through every triplanar
        // projection. The single-texel detail remains red through all cell
        // rotations and blends, while the nontrivial places cover both the
        // direct and mirrored-side placement paths.
        batch.terrain_hex = true;
        batch.terrain_triplanar_blend = 1.f;
        const float hex_fraction[2][4] = {
            {0.125f, 0.75f, 0.5f, 0.25f},
            {0.875f, 0.375f, 0.625f, 0.9375f},
        };
        const std::int32_t hex_base[2][4] = {
            {17, -31, std::numeric_limits<std::int32_t>::min(), -1048577},
            {-2147483647, 2147483646, 0, 0},
        };
        std::memcpy(batch.terrain_hex_fraction,
                    hex_fraction, sizeof(hex_fraction));
        std::memcpy(batch.terrain_hex_base, hex_base, sizeof(hex_base));

        batch.terrain_hex_fraction[1][3] = 1.f;
        CHECK_FALSE(renderer->render(scene, &error));
        CHECK(error == "Metal world terrain batch is invalid");
        batch.terrain_hex_fraction[1][3] = hex_fraction[1][3];
        error.clear();

        auto hex_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(hex_result);
        REQUIRE(device->waitUntilIdle(&error));
        INFO(error);
        albedo.fill(0);
        REQUIRE(hex_result->colorTexture(0)->readback(
            *device, 0, 0, {}, albedo.data(), 32 * 4, &error));
        INFO(error);
        CHECK(albedo[center + 0] == 255);
        CHECK(albedo[center + 1] == 0);
        CHECK(albedo[center + 2] == 0);
        CHECK(albedo[center + 3] == 0);

        // The collision-surface evaluator and dynamic fractional-odd
        // pipeline reproduce the same analytic plane through a different
        // production variant.
        batch.terrain_hex = false;
        batch.terrain_smoothing = false;
        batch.terrain_triplanar = false;
        batch.terrain_tessellation_pinned = false;
        std::fill_n(
            batch.terrain_tessellation_factors, 6, std::uint16_t{0x4200});
        auto dynamic_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(dynamic_result);
        REQUIRE(device->waitUntilIdle(&error));
        INFO(error);
        normal.fill(0);
        REQUIRE(dynamic_result->colorTexture(2)->readback(
            *device, 0, 0, {}, normal.data(), 32 * 8, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(normal[center + 0]) - 24576) <= 1);
        CHECK(std::abs(static_cast<int>(normal[center + 1]) - 16384) <= 1);
        CHECK(normal[center + 2] == 0);
        CHECK(std::abs(static_cast<int>(normal[center + 3]) - 22282) <= 2);
    }
}

TEST_CASE("almetal: PBR terrain preserves material tiers, paint ownership and masking", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        auto renderer = ALMetalWorldGBufferRenderer::create(*device, &error);
        INFO(error);
        REQUIRE(renderer);

        const std::array<std::array<float, 4>, 4> control_points{{
            {{0.f, 0.f, 0.f, 1.f}},
            {{2.f, 0.f, 0.f, 1.f}},
            {{2.f, 2.f, 0.f, 1.f}},
            {{0.f, 2.f, 0.f, 1.f}},
        }};
        ALMetalBufferDescriptor vertex_descriptor;
        vertex_descriptor.length = sizeof(control_points);
        vertex_descriptor.storage = ALMetalStorageMode::shared;
        vertex_descriptor.label = "Alchemy PBR terrain test control points";
        auto vertices = ALMetalBuffer::create(
            *device, vertex_descriptor, &error);
        INFO(error);
        REQUIRE(vertices);
        REQUIRE(vertices->write(
            0, control_points.data(), sizeof(control_points), &error));

        const auto make_texture = [&device, &error](
            ALMetalPixelFormat format, std::uint32_t width,
            std::uint32_t height, const char* label)
        {
            ALMetalTextureDescriptor descriptor;
            descriptor.format = format;
            descriptor.width = width;
            descriptor.height = height;
            descriptor.storage = ALMetalStorageMode::private_gpu;
            descriptor.usage = ALMetalTextureUsage::shader_read;
            descriptor.label = label;
            auto texture = ALMetalTexture::create(
                *device, descriptor, &error);
            INFO(error);
            REQUIRE(texture);
            return texture;
        };

        auto base0 = make_texture(
            ALMetalPixelFormat::rgba8_unorm_srgb, 1, 1,
            "Alchemy PBR terrain material zero base");
        auto base1 = make_texture(
            ALMetalPixelFormat::rgba8_unorm_srgb, 1, 1,
            "Alchemy PBR terrain material one base");
        auto base2 = make_texture(
            ALMetalPixelFormat::rgba8_unorm_srgb, 1, 1,
            "Alchemy PBR terrain material two base");
        auto base3 = make_texture(
            ALMetalPixelFormat::rgba8_unorm_srgb, 1, 1,
            "Alchemy PBR terrain material three base");
        auto normal_map = make_texture(
            ALMetalPixelFormat::rgba8_unorm, 1, 1,
            "Alchemy PBR terrain normal");
        auto orm_map = make_texture(
            ALMetalPixelFormat::rgba8_unorm, 1, 1,
            "Alchemy PBR terrain ORM");
        auto emissive_map = make_texture(
            ALMetalPixelFormat::rgba8_unorm_srgb, 1, 1,
            "Alchemy PBR terrain emissive");
        auto paint_map = make_texture(
            ALMetalPixelFormat::rgba8_unorm, 1, 1,
            "Alchemy PBR terrain paint map");
        auto alpha_ramp = make_texture(
            ALMetalPixelFormat::rgba8_unorm, 1, 1,
            "Alchemy PBR terrain alpha ramp");
        auto height = make_texture(
            ALMetalPixelFormat::r32_float, 8, 8,
            "Alchemy PBR terrain flat height map");
        auto composition = make_texture(
            ALMetalPixelFormat::rg16_float, 8, 8,
            "Alchemy PBR terrain composition map");

        const std::array<std::uint8_t, 4> base0_pixel{{
            255, 255, 255, 128,
        }};
        const std::array<std::uint8_t, 4> base1_pixel{{
            0, 255, 0, 255,
        }};
        const std::array<std::uint8_t, 4> base2_pixel{{
            255, 0, 0, 255,
        }};
        const std::array<std::uint8_t, 4> base3_pixel{{
            0, 0, 255, 255,
        }};
        const std::array<std::uint8_t, 4> normal_pixel{{
            128, 128, 255, 255,
        }};
        const std::array<std::uint8_t, 4> orm_pixel{{
            64, 128, 192, 255,
        }};
        const std::array<std::uint8_t, 4> emissive_pixel{{
            255, 255, 255, 255,
        }};
        const std::array<std::uint8_t, 4> zero_pixel{};
        std::array<float, 64> height_pixels{};
        const std::array<std::uint16_t, 128> composition_pixels{};
        auto upload = device->makeCommandBuffer(
            "Alchemy PBR terrain texture upload", &error);
        INFO(error);
        REQUIRE(upload);
        REQUIRE(base0->upload(
            *upload, 0, 0, {}, base0_pixel.data(), 4, &error));
        REQUIRE(base1->upload(
            *upload, 0, 0, {}, base1_pixel.data(), 4, &error));
        REQUIRE(base2->upload(
            *upload, 0, 0, {}, base2_pixel.data(), 4, &error));
        REQUIRE(base3->upload(
            *upload, 0, 0, {}, base3_pixel.data(), 4, &error));
        REQUIRE(normal_map->upload(
            *upload, 0, 0, {}, normal_pixel.data(), 4, &error));
        REQUIRE(orm_map->upload(
            *upload, 0, 0, {}, orm_pixel.data(), 4, &error));
        REQUIRE(emissive_map->upload(
            *upload, 0, 0, {}, emissive_pixel.data(), 4, &error));
        REQUIRE(paint_map->upload(
            *upload, 0, 0, {}, zero_pixel.data(), 4, &error));
        REQUIRE(alpha_ramp->upload(
            *upload, 0, 0, {}, zero_pixel.data(), 4, &error));
        REQUIRE(height->upload(
            *upload, 0, 0, {}, height_pixels.data(), 8 * sizeof(float),
            &error));
        REQUIRE(composition->upload(
            *upload, 0, 0, {}, composition_pixels.data(),
            8 * 2 * sizeof(std::uint16_t), &error));
        REQUIRE(upload->commitAndWait(&error));
        INFO(error);

        ALMetalWorldSimpleBatch batch;
        batch.terrain = true;
        batch.terrain_pbr = true;
        batch.vertices = vertices.get();
        batch.vertex_count = control_points.size();
        batch.texture_count = 4;
        batch.pbr_slot_count = 4;
        batch.diffuse_textures[0] = base0.get();
        batch.diffuse_textures[1] = base1.get();
        batch.diffuse_textures[2] = base2.get();
        batch.diffuse_textures[3] = base3.get();
        for (std::size_t material = 0; material < 4; ++material)
        {
            ALMetalWorldPBRSlot& slot = batch.pbr_slots[material];
            slot.normal_texture = normal_map.get();
            slot.orm_texture = orm_map.get();
            slot.emissive_texture = emissive_map.get();
            batch.terrain_uv_transform[material][0] = 1.f;
            batch.terrain_uv_transform[material][3] = 1.f;
            batch.terrain_normal_axes[material][0] = 1.f;
            batch.terrain_normal_axes[material][3] = 1.f;
        }
        batch.pbr_slots[0].base_color_factor[0] = 0.5f;
        batch.pbr_slots[0].base_color_factor[2] = 0.25f;
        batch.pbr_slots[0].roughness_factor = 0.5f;
        batch.pbr_slots[0].metallic_factor = 0.5f;
        batch.pbr_slots[0].emissive_color[0] = 0.25f;
        batch.pbr_slots[0].emissive_color[1] = 0.5f;
        batch.pbr_slots[0].emissive_color[2] = 1.f;
        batch.terrain_height_texture = height.get();
        batch.terrain_composition_texture = composition.get();
        batch.terrain_paint_texture = paint_map.get();
        batch.terrain_paint_type = 1;
        batch.terrain_pbr_detail = 0;
        std::fill_n(
            batch.terrain_tessellation_factors, 6, std::uint16_t{0x4400});
        batch.terrain_grid_scale = 1.f;
        batch.terrain_region_scale = 4.f;
        batch.terrain_detail_scale = 1.f;
        batch.terrain_triplanar_blend = 8.f;
        batch.terrain_smoothing = true;
        batch.terrain_tessellation_pinned = true;
        batch.modelview_projection[0] = 0.8f;
        batch.modelview_projection[5] = 0.8f;
        batch.modelview_projection[10] = 0.f;
        batch.modelview_projection[12] = -0.8f;
        batch.modelview_projection[13] = -0.8f;
        batch.modelview_projection[15] = 1.f;
        for (std::size_t axis = 0; axis < 4; ++axis)
        {
            batch.terrain_modelview[axis * 4 + axis] = 1.f;
            if (axis < 3)
            {
                batch.normal_matrix[axis][axis] = 1.f;
            }
        }

        ALMetalWorldGBufferScene scene;
        scene.batches = &batch;
        scene.batch_count = 1;
        scene.width = 32;
        scene.height = 32;
        scene.normal_hdr = true;
        scene.hdr = true;

        batch.terrain_pbr_detail = -5;
        CHECK_FALSE(renderer->render(scene, &error));
        CHECK(error == "Metal world terrain batch is invalid");
        batch.terrain_pbr_detail = 0;
        error.clear();

        batch.terrain_uv_transform[0][0] =
            std::numeric_limits<float>::quiet_NaN();
        CHECK_FALSE(renderer->render(scene, &error));
        CHECK(error == "Metal world terrain batch is invalid");
        batch.terrain_uv_transform[0][0] = 1.f;
        error.clear();

        batch.terrain_alpha_ramp_texture = alpha_ramp.get();
        CHECK_FALSE(renderer->render(scene, &error));
        CHECK(error == "Metal world terrain batch is invalid");
        batch.terrain_alpha_ramp_texture = nullptr;
        error.clear();

        auto result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(result);
        REQUIRE(device->waitUntilIdle(&error));
        INFO(error);
        std::array<std::uint8_t, 32 * 32 * 4> albedo{};
        std::array<std::uint8_t, 32 * 32 * 4> orm{};
        std::array<std::uint16_t, 32 * 32 * 4> normal{};
        std::array<std::uint8_t, 32 * 32 * 4> emissive{};
        REQUIRE(result->colorTexture(0)->readback(
            *device, 0, 0, {}, albedo.data(), 32 * 4, &error));
        REQUIRE(result->colorTexture(1)->readback(
            *device, 0, 0, {}, orm.data(), 32 * 4, &error));
        REQUIRE(result->colorTexture(2)->readback(
            *device, 0, 0, {}, normal.data(), 32 * 8, &error));
        REQUIRE(result->colorTexture(3)->readback(
            *device, 0, 0, {}, emissive.data(), 32 * 4, &error));
        INFO(error);

        const std::size_t center = (16 * 32 + 16) * 4;
        CHECK(std::abs(static_cast<int>(albedo[center + 0]) - 188) <= 1);
        CHECK(albedo[center + 1] == 255);
        CHECK(std::abs(static_cast<int>(albedo[center + 2]) - 137) <= 1);
        CHECK(albedo[center + 3] == 0);
        CHECK(std::abs(static_cast<int>(orm[center + 0]) - 64) <= 1);
        CHECK(std::abs(static_cast<int>(orm[center + 1]) - 64) <= 1);
        CHECK(std::abs(static_cast<int>(orm[center + 2]) - 96) <= 1);
        CHECK(orm[center + 3] <= 1);
        CHECK(std::abs(static_cast<int>(normal[center + 0]) - 32896) <= 4);
        CHECK(std::abs(static_cast<int>(normal[center + 1]) - 32896) <= 4);
        CHECK(std::abs(static_cast<int>(normal[center + 2]) - 32896) <= 2);
        CHECK(std::abs(static_cast<int>(normal[center + 3]) - 43908) <= 2);
        CHECK(std::any_of(
            emissive.begin() + center, emissive.begin() + center + 4,
            [](std::uint8_t value) { return value != 0; }));

        // The runtime detail selector reproduces all five source shader
        // permutations without multiplying the Metal pipeline count.
        for (std::int32_t detail = -4; detail < 0; ++detail)
        {
            CAPTURE(detail);
            batch.terrain_pbr_detail = detail;
            auto tier_result = renderer->render(scene, &error);
            INFO(error);
            REQUIRE(tier_result);
            REQUIRE(device->waitUntilIdle(&error));
            INFO(error);
            orm.fill(0);
            normal.fill(0);
            emissive.fill(0);
            REQUIRE(tier_result->colorTexture(1)->readback(
                *device, 0, 0, {}, orm.data(), 32 * 4, &error));
            REQUIRE(tier_result->colorTexture(2)->readback(
                *device, 0, 0, {}, normal.data(), 32 * 8, &error));
            REQUIRE(tier_result->colorTexture(3)->readback(
                *device, 0, 0, {}, emissive.data(), 32 * 4, &error));
            INFO(error);
            const int expected_ao = detail >= -1 ? 64 : 255;
            const int expected_roughness = detail >= -3 ? 64 : 255;
            const int expected_metal = detail >= -3 ? 96 : 0;
            const int expected_normal = detail >= -2 ? 32896 : 32768;
            CHECK(std::abs(static_cast<int>(orm[center + 0]) -
                           expected_ao) <= 1);
            CHECK(std::abs(static_cast<int>(orm[center + 1]) -
                           expected_roughness) <= 1);
            CHECK(std::abs(static_cast<int>(orm[center + 2]) -
                           expected_metal) <= 1);
            CHECK(std::abs(static_cast<int>(normal[center + 0]) -
                           expected_normal) <= 4);
            CHECK(std::all_of(
                emissive.begin() + center, emissive.begin() + center + 4,
                [](std::uint8_t value) { return value == 0; }));
        }
        batch.terrain_pbr_detail = 0;

        // The height-ramp mode's all-zero ramp selects material three. A
        // fully opaque parcel overlay then replaces that linear-space blend.
        batch.terrain_paint_type = 0;
        batch.terrain_paint_texture = nullptr;
        batch.terrain_alpha_ramp_texture = alpha_ramp.get();
        auto ramp_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(ramp_result);
        REQUIRE(device->waitUntilIdle(&error));
        albedo.fill(0);
        REQUIRE(ramp_result->colorTexture(0)->readback(
            *device, 0, 0, {}, albedo.data(), 32 * 4, &error));
        INFO(error);
        CHECK(albedo[center + 0] == 0);
        CHECK(albedo[center + 1] == 0);
        CHECK(albedo[center + 2] == 255);

        batch.terrain_parcel_overlay_texture = base2.get();
        auto overlay_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(overlay_result);
        REQUIRE(device->waitUntilIdle(&error));
        albedo.fill(0);
        REQUIRE(overlay_result->colorTexture(0)->readback(
            *device, 0, 0, {}, albedo.data(), 32 * 4, &error));
        INFO(error);
        CHECK(albedo[center + 0] == 255);
        CHECK(albedo[center + 1] == 0);
        CHECK(albedo[center + 2] == 0);
        batch.terrain_parcel_overlay_texture = nullptr;

        // Constant maps make the expected material invariant while every
        // material-specific lattice origin and triplanar projection executes.
        batch.terrain_hex = true;
        batch.terrain_triplanar = true;
        batch.terrain_triplanar_blend = 1.f;
        for (std::size_t element = 0; element < 8; ++element)
        {
            for (std::size_t component = 0; component < 4; ++component)
            {
                batch.terrain_hex_fraction[element][component] =
                    0.0625f * static_cast<float>(component + 1);
                batch.terrain_hex_base[element][component] =
                    static_cast<std::int32_t>(
                        element * 131 + component * 17) - 509;
            }
        }
        batch.terrain_hex_base[7][3] =
            std::numeric_limits<std::int32_t>::min();
        auto hex_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(hex_result);
        REQUIRE(device->waitUntilIdle(&error));
        albedo.fill(0);
        REQUIRE(hex_result->colorTexture(0)->readback(
            *device, 0, 0, {}, albedo.data(), 32 * 4, &error));
        INFO(error);
        CHECK(albedo[center + 0] == 0);
        CHECK(albedo[center + 1] == 0);
        CHECK(albedo[center + 2] == 255);

        batch.terrain_hex_fraction[7][3] = 1.f;
        CHECK_FALSE(renderer->render(scene, &error));
        CHECK(error == "Metal world terrain batch is invalid");
        batch.terrain_hex_fraction[7][3] = 0.25f;
        error.clear();

        batch.terrain_hex = false;
        batch.terrain_triplanar = false;
        batch.terrain_flat_normals = true;
        auto flat_result = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(flat_result);

        // Paint-map material zero carries half alpha. The blended cutoff uses
        // the same half-byte bias as the OpenGL owner.
        batch.terrain_flat_normals = false;
        batch.terrain_paint_type = 1;
        batch.terrain_alpha_ramp_texture = nullptr;
        batch.terrain_paint_texture = paint_map.get();
        batch.alpha_mask = true;
        batch.pbr_slots[0].alpha_cutoff = 0.75f;
        auto masked_out = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(masked_out);
        REQUIRE(device->waitUntilIdle(&error));
        albedo.fill(0);
        REQUIRE(masked_out->colorTexture(0)->readback(
            *device, 0, 0, {}, albedo.data(), 32 * 4, &error));
        INFO(error);
        CHECK(albedo[center + 0] == 255);
        CHECK(albedo[center + 1] == 0);
        CHECK(albedo[center + 2] == 255);

        batch.alpha_mask = false;
        CHECK_FALSE(renderer->render(scene, &error));
        CHECK(error == "Metal world PBR terrain mask state is invalid");
        batch.alpha_mask = true;
        batch.pbr_slots[0].alpha_cutoff = 0.5f;
        error.clear();
        auto masked_in = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(masked_in);
        REQUIRE(device->waitUntilIdle(&error));
        albedo.fill(0);
        REQUIRE(masked_in->colorTexture(0)->readback(
            *device, 0, 0, {}, albedo.data(), 32 * 4, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(albedo[center + 0]) - 188) <= 1);
        CHECK(albedo[center + 1] == 255);
        CHECK(std::abs(static_cast<int>(albedo[center + 2]) - 137) <= 1);
    }
}

TEST_CASE("almetal: lit preview renders multiple indexed depth-tested batches", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        auto renderer = ALMetalLitPreviewRenderer::create(*device, &error);
        INFO(error);
        REQUIRE(renderer);

        // Two coincident triangles exercise indexed SoA fetch and depth. The
        // nearer triangle has an X normal/red light; the farther one has a Y
        // normal/green light and must not overwrite it.
        const std::array<std::array<float, 4>, 6> positions{{
            {{-0.8f, -0.8f,  0.5f, 1.f}},
            {{ 0.8f, -0.8f,  0.5f, 1.f}},
            {{ 0.0f,  0.8f,  0.5f, 1.f}},
            {{-0.8f, -0.8f, -0.5f, 1.f}},
            {{ 0.8f, -0.8f, -0.5f, 1.f}},
            {{ 0.0f,  0.8f, -0.5f, 1.f}},
        }};
        const std::array<std::array<float, 4>, 6> normals{{
            {{0.f, 1.f, 0.f, 0.f}}, {{0.f, 1.f, 0.f, 0.f}},
            {{0.f, 1.f, 0.f, 0.f}}, {{1.f, 0.f, 0.f, 0.f}},
            {{1.f, 0.f, 0.f, 0.f}}, {{1.f, 0.f, 0.f, 0.f}},
        }};
        const std::array<std::array<float, 2>, 6> texcoords{{
            {{0.f, 0.f}}, {{0.f, 0.f}}, {{0.f, 0.f}},
            {{0.f, 0.f}}, {{0.f, 0.f}}, {{0.f, 0.f}},
        }};
        const std::array<std::array<float, 4>, 6> skin_weights{{
            {{0.5f, 0.f, 0.f, 0.f}}, {{0.5f, 0.f, 0.f, 0.f}},
            {{0.5f, 0.f, 0.f, 0.f}}, {{0.5f, 0.f, 0.f, 0.f}},
            {{0.5f, 0.f, 0.f, 0.f}}, {{0.5f, 0.f, 0.f, 0.f}},
        }};
        const std::array<float, 6> avatar_weights{{
            0.5f, 0.5f, 0.5f, 0.5f, 0.5f, 0.5f,
        }};
        const std::array<std::array<float, 4>, 6> avatar_clothing{{
            {{0.5f, 0.f, 0.f, 1.f}}, {{0.5f, 0.f, 0.f, 1.f}},
            {{0.5f, 0.f, 0.f, 1.f}}, {{0.5f, 0.f, 0.f, 1.f}},
            {{0.5f, 0.f, 0.f, 1.f}}, {{0.5f, 0.f, 0.f, 1.f}},
        }};
        const std::array<std::array<std::uint8_t, 4>, 6> rigged_colors{{
            {{128, 255, 255, 128}}, {{128, 255, 255, 128}},
            {{128, 255, 255, 128}}, {{128, 255, 255, 128}},
            {{128, 255, 255, 128}}, {{128, 255, 255, 128}},
        }};
        const std::array<std::array<std::uint8_t, 4>, 6> emissive_colors{{
            {{0, 0, 0, 128}}, {{0, 0, 0, 128}},
            {{0, 0, 0, 128}}, {{0, 0, 0, 128}},
            {{0, 0, 0, 128}}, {{0, 0, 0, 128}},
        }};
        constexpr std::size_t rigged_color_alignment_padding = 8;
        std::array<std::uint8_t,
                   sizeof(positions) + sizeof(normals) + sizeof(texcoords) +
                       sizeof(skin_weights) + sizeof(avatar_weights) +
                       sizeof(avatar_clothing) +
                       rigged_color_alignment_padding + sizeof(rigged_colors) +
                       sizeof(emissive_colors)>
            vertex_bytes{};
        std::memcpy(vertex_bytes.data(), positions.data(), sizeof(positions));
        std::memcpy(vertex_bytes.data() + sizeof(positions), normals.data(), sizeof(normals));
        std::memcpy(vertex_bytes.data() + sizeof(positions) + sizeof(normals),
                    texcoords.data(), sizeof(texcoords));
        const std::size_t skin_weight_offset =
            sizeof(positions) + sizeof(normals) + sizeof(texcoords);
        std::memcpy(vertex_bytes.data() + skin_weight_offset,
                    skin_weights.data(), sizeof(skin_weights));
        const std::size_t avatar_cloth_offset =
            skin_weight_offset + sizeof(skin_weights);
        std::memcpy(vertex_bytes.data() + avatar_cloth_offset,
                    avatar_clothing.data(), sizeof(avatar_clothing));
        const std::size_t avatar_weight_offset =
            avatar_cloth_offset + sizeof(avatar_clothing);
        std::memcpy(vertex_bytes.data() + avatar_weight_offset,
                    avatar_weights.data(), sizeof(avatar_weights));
        const std::size_t rigged_color_offset =
            avatar_weight_offset + sizeof(avatar_weights) +
            rigged_color_alignment_padding;
        std::memcpy(vertex_bytes.data() + rigged_color_offset,
                    rigged_colors.data(), sizeof(rigged_colors));
        const std::size_t emissive_color_offset =
            rigged_color_offset + sizeof(rigged_colors);
        std::memcpy(vertex_bytes.data() + emissive_color_offset,
                    emissive_colors.data(), sizeof(emissive_colors));
        const std::array<std::uint16_t, 9> indices{{
            0, 1, 2, 3, 4, 5,
            // The same near triangle with reversed winding verifies that the
            // explicit edge path preserves GL polygon-mode back-face culling.
            5, 4, 3,
        }};

        ALMetalBufferDescriptor vertex_descriptor;
        vertex_descriptor.length = vertex_bytes.size();
        vertex_descriptor.storage = ALMetalStorageMode::shared;
        vertex_descriptor.label = "Alchemy sculpt preview test vertices";
        auto vertices = ALMetalBuffer::create(*device, vertex_descriptor, &error);
        INFO(error);
        REQUIRE(vertices);
        REQUIRE(vertices->write(0, vertex_bytes.data(), vertex_bytes.size(), &error));

        ALMetalBufferDescriptor index_descriptor;
        index_descriptor.length = sizeof(indices);
        index_descriptor.storage = ALMetalStorageMode::shared;
        index_descriptor.label = "Alchemy sculpt preview test indices";
        auto index_buffer = ALMetalBuffer::create(*device, index_descriptor, &error);
        INFO(error);
        REQUIRE(index_buffer);
        REQUIRE(index_buffer->write(0, indices.data(), sizeof(indices), &error));

        // Convex decomposition meshes are CPU-owned, tightly-packed float3
        // triangle lists. Put the farther hull first so the output differs if
        // the required all-hull depth prepass is accidentally omitted.
        const std::array<std::array<float, 3>, 6> hull_positions{{
            {{-0.8f, -0.8f,  0.5f}},
            {{ 0.8f, -0.8f,  0.5f}},
            {{ 0.0f,  0.8f,  0.5f}},
            {{-0.8f, -0.8f, -0.5f}},
            {{ 0.8f, -0.8f, -0.5f}},
            {{ 0.0f,  0.8f, -0.5f}},
        }};
        ALMetalBufferDescriptor hull_descriptor;
        hull_descriptor.length = sizeof(hull_positions);
        hull_descriptor.storage = ALMetalStorageMode::shared;
        hull_descriptor.label = "Alchemy flat convex-hull preview vertices";
        auto hull_vertices = ALMetalBuffer::create(
            *device, hull_descriptor, &error);
        INFO(error);
        REQUIRE(hull_vertices);
        REQUIRE(hull_vertices->write(
            0, hull_positions.data(), sizeof(hull_positions), &error));

        ALMetalTextureDescriptor destination_descriptor;
        destination_descriptor.format = ALMetalPixelFormat::rgba8_unorm;
        destination_descriptor.width = 32;
        destination_descriptor.height = 32;
        destination_descriptor.storage = ALMetalStorageMode::private_gpu;
        destination_descriptor.usage = ALMetalTextureUsage::shader_read;
        destination_descriptor.label = "Alchemy sculpt preview destination template";
        auto destination_template = ALMetalTexture::create(
            *device, destination_descriptor, &error);
        INFO(error);
        REQUIRE(destination_template);

        ALMetalTextureDescriptor diffuse_descriptor;
        diffuse_descriptor.format = ALMetalPixelFormat::rgba8_unorm_srgb;
        diffuse_descriptor.width = 1;
        diffuse_descriptor.height = 1;
        diffuse_descriptor.storage = ALMetalStorageMode::private_gpu;
        diffuse_descriptor.usage = ALMetalTextureUsage::shader_read;
        diffuse_descriptor.label = "Alchemy textured preview encoded-color source";
        auto diffuse_texture = ALMetalTexture::create(
            *device, diffuse_descriptor, &error);
        INFO(error);
        REQUIRE(diffuse_texture);
        const std::array<std::uint8_t, 4> diffuse_pixel{{128, 64, 32, 255}};
        auto upload = device->makeCommandBuffer(
            "Alchemy textured preview upload", &error);
        INFO(error);
        REQUIRE(upload);
        REQUIRE(diffuse_texture->upload(
            *upload, 0, 0, {}, diffuse_pixel.data(), 4, &error));
        REQUIRE(upload->commitAndWait(&error));
        INFO(error);

        diffuse_descriptor.label =
            "Alchemy textured preview half-alpha encoded-color source";
        auto half_alpha_diffuse_texture = ALMetalTexture::create(
            *device, diffuse_descriptor, &error);
        INFO(error);
        REQUIRE(half_alpha_diffuse_texture);
        const std::array<std::uint8_t, 4> half_alpha_diffuse_pixel{{
            128, 64, 32, 128,
        }};
        auto half_alpha_upload = device->makeCommandBuffer(
            "Alchemy half-alpha textured preview upload", &error);
        INFO(error);
        REQUIRE(half_alpha_upload);
        REQUIRE(half_alpha_diffuse_texture->upload(
            *half_alpha_upload, 0, 0, {}, half_alpha_diffuse_pixel.data(), 4,
            &error));
        REQUIRE(half_alpha_upload->commitAndWait(&error));
        INFO(error);

        diffuse_descriptor.width = 2;
        diffuse_descriptor.label =
            "Alchemy PBR preview UV-transform source";
        auto pbr_transform_texture = ALMetalTexture::create(
            *device, diffuse_descriptor, &error);
        INFO(error);
        REQUIRE(pbr_transform_texture);
        const std::array<std::uint8_t, 8> pbr_transform_pixels{{
            128, 0, 0, 255,
            0, 128, 0, 255,
        }};
        auto pbr_transform_upload = device->makeCommandBuffer(
            "Alchemy PBR preview UV-transform upload", &error);
        INFO(error);
        REQUIRE(pbr_transform_upload);
        REQUIRE(pbr_transform_texture->upload(
            *pbr_transform_upload, 0, 0, {}, pbr_transform_pixels.data(), 8,
            &error));
        REQUIRE(pbr_transform_upload->commitAndWait(&error));
        INFO(error);

        diffuse_descriptor.label =
            "Alchemy PBR preview emissive UV-transform source";
        auto pbr_emissive_texture = ALMetalTexture::create(
            *device, diffuse_descriptor, &error);
        INFO(error);
        REQUIRE(pbr_emissive_texture);
        const std::array<std::uint8_t, 8> pbr_emissive_pixels{{
            0, 0, 0, 255,
            255, 255, 255, 255,
        }};
        auto pbr_emissive_upload = device->makeCommandBuffer(
            "Alchemy PBR preview emissive upload", &error);
        INFO(error);
        REQUIRE(pbr_emissive_upload);
        REQUIRE(pbr_emissive_texture->upload(
            *pbr_emissive_upload, 0, 0, {}, pbr_emissive_pixels.data(), 8,
            &error));
        REQUIRE(pbr_emissive_upload->commitAndWait(&error));
        INFO(error);

        ALMetalLitPreviewBatch batch;
        batch.vertices = vertices.get();
        batch.position_offset = 0;
        batch.normal_offset = sizeof(positions);
        batch.texcoord_offset = sizeof(positions) + sizeof(normals);
        batch.vertex_count = positions.size();
        batch.indices = index_buffer.get();
        batch.index_count = indices.size();
        batch.destination_template = destination_template.get();
        for (std::size_t index = 0; index < 4; ++index)
        {
            batch.modelview_projection[index * 4 + index] = 1.f;
        }
        for (std::size_t index = 0; index < 3; ++index)
        {
            batch.normal_matrix[index][index] = 1.f;
        }
        batch.light_direction[0][0] = 1.f;
        batch.light_direction[1][1] = 1.f;
        batch.light_diffuse[0][0] = 1.f;
        batch.light_diffuse[1][1] = 1.f;
        batch.diffuse_color[0] = 0.9f;
        batch.diffuse_color[1] = 0.9f;
        batch.diffuse_color[2] = 0.9f;
        batch.diffuse_color[3] = 1.f;

        batch.normal_offset = vertex_bytes.size();
        CHECK_FALSE(renderer->render(batch, &error));
        CHECK(error == "Metal lit preview geometry range exceeds its buffers");
        batch.normal_offset = sizeof(positions);
        error.clear();

        ALMetalLitPreviewBatch batches[3] = {batch, batch, batch};
        batches[0].index_count = 3;
        batches[1].index_offset = sizeof(std::uint16_t) * 3;
        batches[1].index_count = 3;
        batches[1].texture = diffuse_texture.get();
        std::memset(batches[0].light_direction, 0,
                    sizeof(batches[0].light_direction));
        std::memset(batches[0].light_diffuse, 0,
                    sizeof(batches[0].light_diffuse));
        batches[0].light_direction[0][1] = 1.f;
        batches[0].light_diffuse[0][1] = 1.f;
        std::memset(batches[1].light_direction, 0,
                    sizeof(batches[1].light_direction));
        std::memset(batches[1].light_diffuse, 0,
                    sizeof(batches[1].light_diffuse));
        batches[1].light_direction[0][0] = 1.f;
        batches[1].light_diffuse[0][0] = 1.f;
        batches[1].show_edges = true;
        batches[1].edge_color[0] = 1.f;
        batches[1].edge_color[1] = 0.f;
        batches[1].edge_color[2] = 0.f;
        batches[1].edge_color[3] = 1.f;
        batches[2].index_offset = sizeof(std::uint16_t) * 6;
        batches[2].index_count = 3;
        batches[2].show_edges = true;
        batches[2].edge_color[0] = 0.f;
        batches[2].edge_color[1] = 1.f;
        batches[2].edge_color[2] = 0.f;
        batches[2].edge_color[3] = 1.f;

        batches[1].index_count = 2;
        CHECK_FALSE(renderer->render(batches[1], &error));
        CHECK(error == "Metal lit preview edges require complete triangle indices");
        batches[1].index_count = 3;
        error.clear();

        batches[1].texcoord_offset = vertex_bytes.size();
        CHECK_FALSE(renderer->render(batches[1], &error));
        CHECK(error == "Metal lit preview geometry range exceeds its buffers");
        batches[1].texcoord_offset = sizeof(positions) + sizeof(normals);
        error.clear();

        ALMetalLitPreviewScene scene;
        scene.batches = batches;
        scene.batch_count = 3;
        scene.destination_descriptor = &destination_template->descriptor();
        scene.clear_color[0] = 0.169f;
        scene.clear_color[1] = 0.169f;
        scene.clear_color[2] = 0.169f;
        auto rendered = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(rendered);
        CHECK(alMetalHasUsage(rendered->descriptor().usage,
                              ALMetalTextureUsage::render_target));
        std::array<std::uint8_t, 32 * 32 * 4> pixels{};
        REQUIRE(rendered->readback(*device, 0, 0, {}, pixels.data(), 32 * 4, &error));
        INFO(error);

        const std::size_t center = (16 * 32 + 16) * 4;
        // The sRGB source is intentionally sampled through its linear UNORM
        // view, matching legacy AnisoWrap/GL_SKIP_DECODE. 128 * 0.9 = 115.2;
        // hardware sRGB decode would instead produce roughly 50 here.
        CHECK(std::abs(static_cast<int>(pixels[center + 0]) - 115) <= 1);
        CHECK(pixels[center + 1] <= 1);
        CHECK(pixels[center + 2] <= 1);
        CHECK(pixels[center + 3] == 255);
        std::size_t red_edge_pixels = 0;
        for (std::size_t offset = 0; offset < pixels.size(); offset += 4)
        {
            if (pixels[offset + 0] >= 254 && pixels[offset + 1] <= 1 &&
                pixels[offset + 2] <= 1 && pixels[offset + 3] == 255)
            {
                ++red_edge_pixels;
            }
        }
        CHECK(red_edge_pixels == 76);
        std::size_t back_face_edge_pixels = 0;
        for (std::size_t offset = 0; offset < pixels.size(); offset += 4)
        {
            if (pixels[offset + 0] <= 1 && pixels[offset + 1] >= 254 &&
                pixels[offset + 2] <= 1 && pixels[offset + 3] == 255)
            {
                ++back_face_edge_pixels;
            }
        }
        CHECK(back_face_edge_pixels == 0);
        const std::size_t corner = 4;
        CHECK(std::abs(static_cast<int>(pixels[corner + 0]) - 43) <= 1);
        CHECK(std::abs(static_cast<int>(pixels[corner + 1]) - 43) <= 1);
        CHECK(std::abs(static_cast<int>(pixels[corner + 2]) - 43) <= 1);
        CHECK(pixels[corner + 3] == 255);

        // The ordinary model-physics overlay clears depth after the model,
        // retains its color, then source-alpha blends the physics mesh. Reuse
        // the farther triangle: it was rejected above, so seeing it here also
        // proves that the explicit pass boundary cleared depth.
        std::array<ALMetalLitPreviewBatch, 4> overlay_batches{{
            batches[0], batches[1], batches[2], batch,
        }};
        ALMetalLitPreviewBatch& overlay = overlay_batches[3];
        overlay.index_offset = 0;
        overlay.index_count = 3;
        overlay.texture = nullptr;
        overlay.show_edges = false;
        overlay.clear_depth_before = true;
        overlay.alpha_blending = true;
        std::memset(overlay.light_direction, 0,
                    sizeof(overlay.light_direction));
        std::memset(overlay.light_diffuse, 0,
                    sizeof(overlay.light_diffuse));
        overlay.light_direction[0][1] = 1.f;
        overlay.light_diffuse[0][2] = 1.f;
        overlay.diffuse_color[0] = 1.f;
        overlay.diffuse_color[1] = 1.f;
        overlay.diffuse_color[2] = 1.f;
        overlay.diffuse_color[3] = 0.5f;

        scene.batches = overlay_batches.data();
        scene.batch_count = overlay_batches.size();
        auto rendered_overlay = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(rendered_overlay);
        std::array<std::uint8_t, 32 * 32 * 4> overlay_pixels{};
        REQUIRE(rendered_overlay->readback(
            *device, 0, 0, {}, overlay_pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(overlay_pixels[center + 0]) - 58) <= 1);
        CHECK(overlay_pixels[center + 1] <= 1);
        CHECK(std::abs(static_cast<int>(overlay_pixels[center + 2]) - 128) <= 1);
        CHECK(std::abs(static_cast<int>(overlay_pixels[center + 3]) - 191) <= 1);

        ALMetalLitPreviewBatch far_hull;
        far_hull.vertices = hull_vertices.get();
        far_hull.vertex_count = 3;
        far_hull.geometry =
            ALMetalLitPreviewGeometry::unindexed_flat_triangles;
        far_hull.depth_prepass = true;
        far_hull.clear_depth_before = true;
        far_hull.alpha_blending = true;
        far_hull.destination_template = destination_template.get();
        far_hull.diffuse_color[0] = 0.f;
        far_hull.diffuse_color[1] = 1.f;
        far_hull.diffuse_color[2] = 0.f;
        far_hull.diffuse_color[3] = 0.5f;
        for (std::size_t index = 0; index < 4; ++index)
        {
            far_hull.modelview_projection[index * 4 + index] = 1.f;
        }
        ALMetalLitPreviewBatch near_hull = far_hull;
        near_hull.position_offset = sizeof(float) * 3 * 3;
        near_hull.clear_depth_before = false;
        near_hull.diffuse_color[0] = 1.f;
        near_hull.diffuse_color[1] = 0.f;

        far_hull.vertex_count = 2;
        CHECK_FALSE(renderer->render(far_hull, &error));
        CHECK(error == "Metal flat preview requires an unindexed triangle list");
        far_hull.vertex_count = 3;
        error.clear();

        std::array<ALMetalLitPreviewBatch, 2> hull_batches{{
            far_hull, near_hull,
        }};
        ALMetalLitPreviewScene hull_scene;
        hull_scene.batches = hull_batches.data();
        hull_scene.batch_count = hull_batches.size();
        hull_scene.destination_descriptor = &destination_template->descriptor();
        hull_scene.clear_color[0] = 0.169f;
        hull_scene.clear_color[1] = 0.169f;
        hull_scene.clear_color[2] = 0.169f;
        auto rendered_hulls = renderer->render(hull_scene, &error);
        INFO(error);
        REQUIRE(rendered_hulls);
        std::array<std::uint8_t, 32 * 32 * 4> hull_pixels{};
        REQUIRE(rendered_hulls->readback(
            *device, 0, 0, {}, hull_pixels.data(), 32 * 4, &error));
        INFO(error);
        // Only the nearer red hull contributes. If the far green hull were
        // blended before depth became complete, green would be about 75.
        CHECK(std::abs(static_cast<int>(hull_pixels[center + 0]) - 149) <= 1);
        CHECK(std::abs(static_cast<int>(hull_pixels[center + 1]) - 22) <= 1);
        CHECK(std::abs(static_cast<int>(hull_pixels[center + 2]) - 22) <= 1);
        CHECK(std::abs(static_cast<int>(hull_pixels[center + 3]) - 191) <= 1);

        // Joint diagnostics use a compact shared float3 stream for lines and
        // one renderer-owned unit sphere. Exercise both geometry modes and
        // the legacy read-only GL_GREATER pass used for occluded bones.
        const std::array<std::array<float, 3>, 2> line_positions{{
            {{-0.75f, 0.f, 0.f}}, {{0.75f, 0.f, 0.f}},
        }};
        ALMetalBufferDescriptor line_descriptor;
        line_descriptor.length = sizeof(line_positions);
        line_descriptor.storage = ALMetalStorageMode::shared;
        line_descriptor.label = "Alchemy diagnostic preview line vertices";
        auto line_vertices = ALMetalBuffer::create(
            *device, line_descriptor, &error);
        INFO(error);
        REQUIRE(line_vertices);
        REQUIRE(line_vertices->write(
            0, line_positions.data(), sizeof(line_positions), &error));

        ALMetalLitPreviewBatch line_batch;
        line_batch.vertices = line_vertices.get();
        line_batch.vertex_count = line_positions.size();
        line_batch.geometry =
            ALMetalLitPreviewGeometry::unindexed_flat_lines;
        line_batch.destination_template = destination_template.get();
        line_batch.diffuse_color[0] = 0.f;
        line_batch.diffuse_color[1] = 0.f;
        line_batch.diffuse_color[2] = 1.f;
        line_batch.diffuse_color[3] = 1.f;
        for (std::size_t index = 0; index < 4; ++index)
        {
            line_batch.modelview_projection[index * 4 + index] = 1.f;
        }
        line_batch.vertex_count = 1;
        CHECK_FALSE(renderer->render(line_batch, &error));
        CHECK(error == "Metal flat-line preview requires complete line segments");
        line_batch.vertex_count = line_positions.size();
        error.clear();
        auto rendered_line = renderer->render(line_batch, &error);
        INFO(error);
        REQUIRE(rendered_line);
        std::array<std::uint8_t, 32 * 32 * 4> line_pixels{};
        REQUIRE(rendered_line->readback(
            *device, 0, 0, {}, line_pixels.data(), 32 * 4, &error));
        INFO(error);
        std::size_t blue_line_pixels = 0;
        for (std::size_t offset = 0; offset < line_pixels.size(); offset += 4)
        {
            if (line_pixels[offset + 0] <= 1 &&
                line_pixels[offset + 1] <= 1 &&
                line_pixels[offset + 2] >= 254 &&
                line_pixels[offset + 3] == 255)
            {
                ++blue_line_pixels;
            }
        }
        CHECK(blue_line_pixels >= 20);

        ALMetalLitPreviewBatch sphere_batch;
        sphere_batch.geometry = ALMetalLitPreviewGeometry::unit_sphere;
        sphere_batch.destination_template = destination_template.get();
        sphere_batch.diffuse_color[0] = 0.f;
        sphere_batch.diffuse_color[1] = 1.f;
        sphere_batch.diffuse_color[2] = 1.f;
        sphere_batch.diffuse_color[3] = 1.f;
        sphere_batch.modelview_projection[0] = 0.25f;
        sphere_batch.modelview_projection[5] = 0.25f;
        sphere_batch.modelview_projection[10] = 0.25f;
        sphere_batch.modelview_projection[14] = 0.5f;
        sphere_batch.modelview_projection[15] = 1.f;

        ALMetalLitPreviewBatch near_surface = batch;
        near_surface.index_offset = sizeof(std::uint16_t) * 3;
        near_surface.index_count = 3;
        near_surface.texture = nullptr;
        near_surface.show_edges = false;
        sphere_batch.depth_mode =
            ALMetalLitPreviewDepthMode::greater_read_only;
        std::array<ALMetalLitPreviewBatch, 2> diagnostic_batches{{
            near_surface, sphere_batch,
        }};
        ALMetalLitPreviewScene diagnostic_scene;
        diagnostic_scene.batches = diagnostic_batches.data();
        diagnostic_scene.batch_count = diagnostic_batches.size();
        diagnostic_scene.destination_descriptor =
            &destination_template->descriptor();
        auto rendered_diagnostics = renderer->render(
            diagnostic_scene, &error);
        INFO(error);
        REQUIRE(rendered_diagnostics);
        std::array<std::uint8_t, 32 * 32 * 4> diagnostic_pixels{};
        REQUIRE(rendered_diagnostics->readback(
            *device, 0, 0, {}, diagnostic_pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(diagnostic_pixels[center + 0] <= 1);
        CHECK(diagnostic_pixels[center + 1] >= 254);
        CHECK(diagnostic_pixels[center + 2] >= 254);
        CHECK(diagnostic_pixels[center + 3] == 255);

        // Reproduce the viewer's rebased one-joint object-skinning palette.
        // The joint contributes +0.25 X in its local translation and the
        // separate origin contributes another +0.25 X, moving the triangle
        // by exactly +0.5 in clip space. The textured and edge pipelines both
        // consume the same packed integer-index/fractional-weight stream.
        const std::array<float, 16> skin_palette{{
            0.25f, 0.f, 0.f, 0.f,
            1.f, 0.f, 0.f, 0.25f,
            0.f, 1.f, 0.f, 0.f,
            0.f, 0.f, 1.f, 0.f,
        }};
        ALMetalLitPreviewBatch skinned = batch;
        skinned.index_offset = 0;
        skinned.index_count = 3;
        skinned.texture = diffuse_texture.get();
        skinned.show_edges = true;
        skinned.weight_offset = skin_weight_offset;
        skinned.skin_palette = skin_palette.data();
        skinned.skin_palette_float_count = skin_palette.size();
        skinned.skin_joint_count = 1;
        skinned.edge_color[0] = 1.f;
        skinned.edge_color[1] = 0.f;
        skinned.edge_color[2] = 0.f;
        skinned.edge_color[3] = 1.f;

        auto rendered_skinned = renderer->render(skinned, &error);
        INFO(error);
        REQUIRE(rendered_skinned);
        std::array<std::uint8_t, 32 * 32 * 4> skinned_pixels{};
        REQUIRE(rendered_skinned->readback(
            *device, 0, 0, {}, skinned_pixels.data(), 32 * 4, &error));
        INFO(error);
        const std::size_t translated_interior = (16 * 32 + 24) * 4;
        CHECK(skinned_pixels[translated_interior + 0] <= 1);
        CHECK(std::abs(static_cast<int>(
            skinned_pixels[translated_interior + 1]) - 58) <= 1);
        CHECK(skinned_pixels[translated_interior + 2] <= 1);
        CHECK(skinned_pixels[translated_interior + 3] == 255);

        // Deferred rigged attachments decode both diffuse and vertex tint,
        // multiply them in linear space, and re-encode for the hint texture.
        // 128 sRGB multiplied by 128 sRGB becomes 61 sRGB, unlike an encoded
        // byte multiply (64). Accepted deferred coverage is opaque.
        ALMetalLitPreviewBatch deferred_rigged = skinned;
        deferred_rigged.show_edges = false;
        deferred_rigged.deferred_rigged = true;
        deferred_rigged.color_offset = rigged_color_offset;
        auto rendered_deferred_rigged = renderer->render(
            deferred_rigged, &error);
        INFO(error);
        REQUIRE(rendered_deferred_rigged);
        std::array<std::uint8_t, 32 * 32 * 4> deferred_rigged_pixels{};
        REQUIRE(rendered_deferred_rigged->readback(
            *device, 0, 0, {}, deferred_rigged_pixels.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(
            deferred_rigged_pixels[translated_interior + 0]) - 61) <= 1);
        CHECK(deferred_rigged_pixels[translated_interior + 1] == 64);
        CHECK(deferred_rigged_pixels[translated_interior + 2] == 32);
        CHECK(deferred_rigged_pixels[translated_interior + 3] == 255);

        deferred_rigged.alpha_cutoff = 0.6f;
        auto rendered_deferred_mask = renderer->render(
            deferred_rigged, &error);
        INFO(error);
        REQUIRE(rendered_deferred_mask);
        std::array<std::uint8_t, 32 * 32 * 4> deferred_mask_pixels{};
        REQUIRE(rendered_deferred_mask->readback(
            *device, 0, 0, {}, deferred_mask_pixels.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(deferred_mask_pixels[translated_interior + 0] == 38);
        CHECK(deferred_mask_pixels[translated_interior + 1] == 51);
        CHECK(deferred_mask_pixels[translated_interior + 2] == 77);
        CHECK(deferred_mask_pixels[translated_interior + 3] == 255);

        // Legacy-material attachment 0 uses the same linear diffuse/tint
        // product, but its mask tests texture alpha alone. Vertex alpha is
        // unrelated to deferred coverage, which is stamped from depth.
        ALMetalLitPreviewBatch legacy_material = deferred_rigged;
        legacy_material.deferred_rigged = false;
        legacy_material.legacy_material_rigged = true;
        legacy_material.alpha_cutoff = 0.75f;
        auto rendered_legacy_material = renderer->render(
            legacy_material, &error);
        INFO(error);
        REQUIRE(rendered_legacy_material);
        std::array<std::uint8_t, 32 * 32 * 4> legacy_material_pixels{};
        REQUIRE(rendered_legacy_material->readback(
            *device, 0, 0, {}, legacy_material_pixels.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(
            legacy_material_pixels[translated_interior + 0]) - 61) <= 1);
        CHECK(legacy_material_pixels[translated_interior + 1] == 64);
        CHECK(legacy_material_pixels[translated_interior + 2] == 32);
        CHECK(legacy_material_pixels[translated_interior + 3] == 255);

        legacy_material.texture = half_alpha_diffuse_texture.get();
        legacy_material.alpha_cutoff = 0.6f;
        auto rendered_legacy_material_discard = renderer->render(
            legacy_material, &error);
        INFO(error);
        REQUIRE(rendered_legacy_material_discard);
        std::array<std::uint8_t, 32 * 32 * 4>
            legacy_material_discard_pixels{};
        REQUIRE(rendered_legacy_material_discard->readback(
            *device, 0, 0, {}, legacy_material_discard_pixels.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(legacy_material_discard_pixels[translated_interior + 0] == 38);
        CHECK(legacy_material_discard_pixels[translated_interior + 1] == 51);
        CHECK(legacy_material_discard_pixels[translated_interior + 2] == 77);
        CHECK(legacy_material_discard_pixels[translated_interior + 3] == 255);

        // Opaque/masked PBR writes the same attachment-0 base-color product,
        // but its MASK cutoff uses texture alpha times the streamed
        // baseColorFactor alpha. The U8 vertex color is that streamed factor.
        ALMetalLitPreviewBatch pbr = deferred_rigged;
        pbr.deferred_rigged = false;
        pbr.pbr_rigged = true;
        pbr.alpha_cutoff = 0.f;
        auto rendered_pbr = renderer->render(pbr, &error);
        INFO(error);
        REQUIRE(rendered_pbr);
        std::array<std::uint8_t, 32 * 32 * 4> pbr_pixels{};
        REQUIRE(rendered_pbr->readback(
            *device, 0, 0, {}, pbr_pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(
            pbr_pixels[translated_interior + 0]) - 61) <= 1);
        CHECK(pbr_pixels[translated_interior + 1] == 64);
        CHECK(pbr_pixels[translated_interior + 2] == 32);
        CHECK(pbr_pixels[translated_interior + 3] == 255);

        // Blended PBR in an impostor bake is intentionally flat albedo, not
        // forward lighting: pbralphaF writes base colour and true coverage.
        // Reproduce the sRGB target's linear-space blend and the alpha pool's
        // src.a + (1-src.a)*dst.a coverage recurrence. Both texture and
        // streamed baseColorFactor alpha are 128/255 here.
        ALMetalLitPreviewBatch pbr_blend = pbr;
        pbr_blend.pbr_blend = true;
        pbr_blend.texture = half_alpha_diffuse_texture.get();
        pbr_blend.alpha_cutoff = 0.004f;
        ALMetalLitPreviewScene pbr_blend_scene;
        pbr_blend_scene.batches = &pbr_blend;
        pbr_blend_scene.batch_count = 1;
        pbr_blend_scene.destination_descriptor =
            &destination_template->descriptor();
        pbr_blend_scene.clear_color[0] = 0.169f;
        pbr_blend_scene.clear_color[1] = 0.2f;
        pbr_blend_scene.clear_color[2] = 0.3f;
        pbr_blend_scene.clear_color[3] = 0.f;
        auto rendered_pbr_blend = renderer->render(
            pbr_blend_scene, &error);
        INFO(error);
        REQUIRE(rendered_pbr_blend);
        std::array<std::uint8_t, 32 * 32 * 4> pbr_blend_pixels{};
        REQUIRE(rendered_pbr_blend->readback(
            *device, 0, 0, {}, pbr_blend_pixels.data(), 32 * 4, &error));
        INFO(error);
        const auto srgb_to_linear = [](float encoded)
        {
            return encoded <= 0.04045f
                ? encoded / 12.92f
                : std::pow((encoded + 0.055f) / 1.055f, 2.4f);
        };
        const auto linear_to_srgb = [](float linear)
        {
            return linear <= 0.0031308f
                ? linear * 12.92f
                : 1.055f * std::pow(linear, 1.f / 2.4f) - 0.055f;
        };
        const float half = 128.f / 255.f;
        const float blend_coverage = half * half;
        const std::array<float, 3> texture_encoded{{
            128.f / 255.f, 64.f / 255.f, 32.f / 255.f,
        }};
        const std::array<float, 3> tint_encoded{{half, 1.f, 1.f}};
        const std::array<float, 3> clear_encoded{{
            43.f / 255.f, 51.f / 255.f, 77.f / 255.f,
        }};
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            const float source = srgb_to_linear(texture_encoded[channel]) *
                                 srgb_to_linear(tint_encoded[channel]);
            const float destination =
                srgb_to_linear(clear_encoded[channel]);
            const int expected = static_cast<int>(std::lround(
                linear_to_srgb(source * blend_coverage +
                    destination * (1.f - blend_coverage)) * 255.f));
            CHECK(std::abs(static_cast<int>(
                pbr_blend_pixels[translated_interior + channel]) -
                expected) <= 1);
        }
        CHECK(std::abs(static_cast<int>(
            pbr_blend_pixels[translated_interior + 3]) -
            static_cast<int>(std::lround(blend_coverage * 255.f))) <= 1);

        // Opaque PBR glow replaces the coverage stamp's alpha with emissive
        // luminance. Its texture transform is independent from base colour:
        // offset U=0.75 selects the white emissive texel, whose 0.75 factor
        // and 128/255 streamed TE glow produce exactly 96/255.
        ALMetalLitPreviewBatch pbr_glow = pbr;
        pbr_glow.pbr_glow = true;
        pbr_glow.pbr_emissive_texture = pbr_emissive_texture.get();
        pbr_glow.emissive_offset = emissive_color_offset;
        pbr_glow.pbr_emissive_transform[4] = 0.75f;
        pbr_glow.pbr_emissive_color[0] = 0.25f;
        pbr_glow.pbr_emissive_color[1] = 0.5f;
        pbr_glow.pbr_emissive_color[2] = 0.75f;
        auto rendered_pbr_glow = renderer->render(pbr_glow, &error);
        INFO(error);
        REQUIRE(rendered_pbr_glow);
        std::array<std::uint8_t, 32 * 32 * 4> pbr_glow_pixels{};
        REQUIRE(rendered_pbr_glow->readback(
            *device, 0, 0, {}, pbr_glow_pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(
            pbr_glow_pixels[translated_interior + 0]) - 61) <= 1);
        CHECK(pbr_glow_pixels[translated_interior + 1] == 64);
        CHECK(pbr_glow_pixels[translated_interior + 2] == 32);
        CHECK(std::abs(static_cast<int>(
            pbr_glow_pixels[translated_interior + 3]) - 96) <= 1);

        pbr_glow.pbr_emissive_texture = nullptr;
        error.clear();
        CHECK_FALSE(renderer->render(pbr_glow, &error));
        CHECK(error == "Metal PBR rigged preview data is invalid");

        pbr_glow.pbr_emissive_texture = pbr_emissive_texture.get();
        pbr_glow.pbr_blend = true;
        error.clear();
        CHECK_FALSE(renderer->render(pbr_glow, &error));
        CHECK(error == "Metal PBR rigged preview data is invalid");

        pbr.alpha_cutoff = 0.6f;
        auto rendered_pbr_mask = renderer->render(pbr, &error);
        INFO(error);
        REQUIRE(rendered_pbr_mask);
        std::array<std::uint8_t, 32 * 32 * 4> pbr_mask_pixels{};
        REQUIRE(rendered_pbr_mask->readback(
            *device, 0, 0, {}, pbr_mask_pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(pbr_mask_pixels[translated_interior + 0] == 38);
        CHECK(pbr_mask_pixels[translated_interior + 1] == 51);
        CHECK(pbr_mask_pixels[translated_interior + 2] == 77);
        CHECK(pbr_mask_pixels[translated_interior + 3] == 255);

        // Mirror the PBR vertex shader's texture animation followed by the
        // handed KHR transform. UV 0 becomes 0.5 under texture_matrix0, then
        // scale 0.5 plus offset 0.5 selects the green texel at U=0.75. The
        // reversed triangle verifies material-driven double-sided culling.
        pbr.texture = pbr_transform_texture.get();
        pbr.alpha_cutoff = 0.f;
        pbr.index_offset = sizeof(std::uint16_t) * 6;
        pbr.index_count = 3;
        pbr.pbr_double_sided = true;
        pbr.pbr_base_color_transform[0] = 0.5f;
        pbr.pbr_base_color_transform[1] = 1.f;
        pbr.pbr_base_color_transform[4] = 0.5f;
        pbr.texture_matrix[12] = 0.5f;
        auto rendered_pbr_transform = renderer->render(pbr, &error);
        INFO(error);
        REQUIRE(rendered_pbr_transform);
        std::array<std::uint8_t, 32 * 32 * 4> pbr_transform_output{};
        REQUIRE(rendered_pbr_transform->readback(
            *device, 0, 0, {}, pbr_transform_output.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(pbr_transform_output[translated_interior + 0] <= 1);
        CHECK(std::abs(static_cast<int>(
            pbr_transform_output[translated_interior + 1]) - 128) <= 1);
        CHECK(pbr_transform_output[translated_interior + 2] <= 1);
        CHECK(pbr_transform_output[translated_interior + 3] == 255);

        pbr.pbr_base_color_transform[0] =
            std::numeric_limits<float>::quiet_NaN();
        error.clear();
        CHECK_FALSE(renderer->render(pbr, &error));
        CHECK(error == "Metal PBR rigged preview data is invalid");

        // The post-deferred fullbright mask uses texture alpha alone: outside
        // the alpha pool the U8 vertex alpha is legacy shininess. A 0.75
        // cutoff therefore keeps the opaque texel despite the 0.5 vertex
        // alpha. The dedicated vertex path must not require a normal stream.
        ALMetalLitPreviewBatch fullbright_mask = deferred_rigged;
        fullbright_mask.deferred_rigged = false;
        fullbright_mask.fullbright_mask_rigged = true;
        fullbright_mask.alpha_cutoff = 0.75f;
        fullbright_mask.normal_offset = vertex_bytes.size();
        auto rendered_fullbright_mask = renderer->render(
            fullbright_mask, &error);
        INFO(error);
        REQUIRE(rendered_fullbright_mask);
        std::array<std::uint8_t, 32 * 32 * 4> fullbright_mask_pixels{};
        REQUIRE(rendered_fullbright_mask->readback(
            *device, 0, 0, {}, fullbright_mask_pixels.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(
            fullbright_mask_pixels[translated_interior + 0]) - 61) <= 1);
        CHECK(fullbright_mask_pixels[translated_interior + 1] == 64);
        CHECK(fullbright_mask_pixels[translated_interior + 2] == 32);
        CHECK(fullbright_mask_pixels[translated_interior + 3] == 255);

        fullbright_mask.texture = half_alpha_diffuse_texture.get();
        fullbright_mask.alpha_cutoff = 0.6f;
        auto rendered_fullbright_mask_discard = renderer->render(
            fullbright_mask, &error);
        INFO(error);
        REQUIRE(rendered_fullbright_mask_discard);
        std::array<std::uint8_t, 32 * 32 * 4>
            fullbright_mask_discard_pixels{};
        REQUIRE(rendered_fullbright_mask_discard->readback(
            *device, 0, 0, {}, fullbright_mask_discard_pixels.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(fullbright_mask_discard_pixels[translated_interior + 0] == 38);
        CHECK(fullbright_mask_discard_pixels[translated_interior + 1] == 51);
        CHECK(fullbright_mask_discard_pixels[translated_interior + 2] == 77);
        CHECK(fullbright_mask_discard_pixels[translated_interior + 3] == 255);

        // Ordinary post-deferred fullbright attachments blend in linear
        // space against the decoded sRGB destination. Both texture and
        // vertex alpha contribute to coverage, while the RGB-only GL color
        // mask preserves the destination alpha. With two half-alpha inputs,
        // the exact coverage is roughly one quarter.
        ALMetalLitPreviewBatch fullbright = fullbright_mask;
        fullbright.fullbright_mask_rigged = false;
        fullbright.fullbright_rigged = true;
        fullbright.alpha_cutoff = 0.f;
        auto rendered_fullbright = renderer->render(fullbright, &error);
        INFO(error);
        REQUIRE(rendered_fullbright);
        std::array<std::uint8_t, 32 * 32 * 4> fullbright_pixels{};
        REQUIRE(rendered_fullbright->readback(
            *device, 0, 0, {}, fullbright_pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(
            fullbright_pixels[translated_interior + 0]) - 45) <= 1);
        CHECK(std::abs(static_cast<int>(
            fullbright_pixels[translated_interior + 1]) - 55) <= 1);
        CHECK(std::abs(static_cast<int>(
            fullbright_pixels[translated_interior + 2]) - 69) <= 1);
        CHECK(fullbright_pixels[translated_interior + 3] == 255);

        fullbright.fullbright_mask_rigged = true;
        error.clear();
        CHECK_FALSE(renderer->render(fullbright, &error));
        CHECK(error == "Metal fullbright mask rigged preview data is invalid");

        deferred_rigged.color_offset = vertex_bytes.size();
        error.clear();
        CHECK_FALSE(renderer->render(deferred_rigged, &error));
        CHECK(error == "Metal deferred rigged preview data is invalid");

        // Keep local mesh detail out of the region-scale add. A single
        // pre-MVP addition at 2^24 collapses the triangle's positive-X half;
        // the rebased two-term transform preserves this interior sample.
        std::array<float, 16> precision_palette = skin_palette;
        constexpr float large_origin = 16777216.f;
        precision_palette[0] = large_origin;
        precision_palette[7] = 0.f;
        ALMetalLitPreviewBatch precision_skinned = skinned;
        precision_skinned.skin_palette = precision_palette.data();
        precision_skinned.texture = nullptr;
        precision_skinned.show_edges = false;
        precision_skinned.modelview_projection[12] = -large_origin;
        auto rendered_precision = renderer->render(precision_skinned, &error);
        INFO(error);
        REQUIRE(rendered_precision);
        std::array<std::uint8_t, 32 * 32 * 4> precision_pixels{};
        REQUIRE(rendered_precision->readback(
            *device, 0, 0, {}, precision_pixels.data(), 32 * 4, &error));
        INFO(error);
        std::size_t preserved_local_pixels = 0;
        for (std::size_t pixel = 0; pixel < precision_pixels.size(); pixel += 4)
        {
            if (precision_pixels[pixel + 0] <= 1 &&
                std::abs(static_cast<int>(precision_pixels[pixel + 1]) - 230) <= 1 &&
                precision_pixels[pixel + 2] <= 1 &&
                precision_pixels[pixel + 3] == 255)
            {
                ++preserved_local_pixels;
            }
        }
        CHECK(preserved_local_pixels > 50);

        // Exercise the legacy system-avatar scalar weight convention used by
        // clothing/body previews. Weight 0.5 blends joint 0 identity with a
        // joint 1 transform translated +0.5 X, producing +0.25 X. The chosen
        // sample lies inside only the translated triangle.
        std::array<float, 45 * 4> avatar_palette{};
        for (std::size_t joint = 0; joint < 15; ++joint)
        {
            avatar_palette[joint * 4 + 0] = 1.f;
            avatar_palette[(15 + joint) * 4 + 1] = 1.f;
            avatar_palette[(30 + joint) * 4 + 2] = 1.f;
        }
        avatar_palette[1 * 4 + 3] = 0.5f;

        ALMetalLitPreviewBatch avatar_skinned = batch;
        avatar_skinned.index_offset = 0;
        avatar_skinned.index_count = 3;
        avatar_skinned.weight_offset = avatar_weight_offset;
        avatar_skinned.skin_palette = avatar_palette.data();
        avatar_skinned.skin_palette_float_count = avatar_palette.size();
        avatar_skinned.skin_joint_count = 15;
        avatar_skinned.avatar_skinning = true;
        std::memset(avatar_skinned.light_direction, 0,
                    sizeof(avatar_skinned.light_direction));
        std::memset(avatar_skinned.light_diffuse, 0,
                    sizeof(avatar_skinned.light_diffuse));
        avatar_skinned.light_direction[0][1] = 1.f;
        avatar_skinned.light_diffuse[0][0] = 1.f;
        std::fill(std::begin(avatar_skinned.diffuse_color),
                  std::end(avatar_skinned.diffuse_color), 1.f);

        auto rendered_avatar = renderer->render(avatar_skinned, &error);
        INFO(error);
        REQUIRE(rendered_avatar);
        std::array<std::uint8_t, 32 * 32 * 4> avatar_pixels{};
        REQUIRE(rendered_avatar->readback(
            *device, 0, 0, {}, avatar_pixels.data(), 32 * 4, &error));
        INFO(error);
        const std::size_t avatar_translated_interior = (16 * 32 + 24) * 4;
        CHECK(avatar_pixels[avatar_translated_interior + 0] >= 254);
        CHECK(avatar_pixels[avatar_translated_interior + 1] <= 1);
        CHECK(avatar_pixels[avatar_translated_interior + 2] <= 1);
        CHECK(avatar_pixels[avatar_translated_interior + 3] == 255);

        avatar_skinned.texture = diffuse_texture.get();
        auto rendered_avatar_textured = renderer->render(
            avatar_skinned, &error);
        INFO(error);
        REQUIRE(rendered_avatar_textured);
        std::array<std::uint8_t, 32 * 32 * 4> avatar_textured_pixels{};
        REQUIRE(rendered_avatar_textured->readback(
            *device, 0, 0, {}, avatar_textured_pixels.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(avatar_textured_pixels[avatar_translated_interior + 0] > 0);
        CHECK(avatar_textured_pixels[avatar_translated_interior + 3] == 255);

        ALMetalLitPreviewBatch avatar_skinned_unlit = avatar_skinned;
        avatar_skinned_unlit.avatar_unlit = true;
        auto rendered_avatar_skinned_unlit = renderer->render(
            avatar_skinned_unlit, &error);
        INFO(error);
        REQUIRE(rendered_avatar_skinned_unlit);
        std::array<std::uint8_t, 32 * 32 * 4> avatar_skinned_unlit_pixels{};
        REQUIRE(rendered_avatar_skinned_unlit->readback(
            *device, 0, 0, {}, avatar_skinned_unlit_pixels.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(avatar_skinned_unlit_pixels[avatar_translated_interior + 0] == 128);
        CHECK(avatar_skinned_unlit_pixels[avatar_translated_interior + 1] == 64);
        CHECK(avatar_skinned_unlit_pixels[avatar_translated_interior + 2] == 32);
        CHECK(avatar_skinned_unlit_pixels[avatar_translated_interior + 3] == 255);

        // Match avatarSkinV.glsl's optional clothing stream. With zero phase,
        // frequency, gravity and view-depth terms, wind strength one plus the
        // source shader's minimax sine approximation makes clothing.x move
        // every vertex slightly more than +0.5 before the palette adds its
        // existing +0.25 translation.
        const std::size_t avatar_cloth_interior = (16 * 32 + 28) * 4;
        CHECK(avatar_skinned_unlit_pixels[avatar_cloth_interior + 0] == 38);
        CHECK(avatar_skinned_unlit_pixels[avatar_cloth_interior + 1] == 51);
        CHECK(avatar_skinned_unlit_pixels[avatar_cloth_interior + 2] == 77);
        CHECK(avatar_skinned_unlit_pixels[avatar_cloth_interior + 3] == 255);
        ALMetalLitPreviewBatch avatar_cloth = avatar_skinned_unlit;
        avatar_cloth.cloth_offset = avatar_cloth_offset;
        avatar_cloth.avatar_cloth = true;
        avatar_cloth.avatar_wind[3] = 1.f;
        auto rendered_avatar_cloth = renderer->render(avatar_cloth, &error);
        INFO(error);
        REQUIRE(rendered_avatar_cloth);
        std::array<std::uint8_t, 32 * 32 * 4> avatar_cloth_pixels{};
        REQUIRE(rendered_avatar_cloth->readback(
            *device, 0, 0, {}, avatar_cloth_pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(avatar_cloth_pixels[avatar_cloth_interior + 0] == 128);
        CHECK(avatar_cloth_pixels[avatar_cloth_interior + 1] == 64);
        CHECK(avatar_cloth_pixels[avatar_cloth_interior + 2] == 32);
        CHECK(avatar_cloth_pixels[avatar_cloth_interior + 3] == 255);

        avatar_cloth.cloth_offset = vertex_bytes.size();
        error.clear();
        CHECK_FALSE(renderer->render(avatar_cloth, &error));
        CHECK(error == "Metal avatar cloth preview data is invalid");

        // Rigid avatar parts use the same one-light/wrapped-back response and
        // alpha-tested texture path without a palette or weight stream.
        ALMetalLitPreviewBatch rigid_avatar = batch;
        rigid_avatar.index_offset = 0;
        rigid_avatar.index_count = 3;
        rigid_avatar.avatar_lighting = true;
        rigid_avatar.modelview_projection[12] = 0.25f;
        std::memset(rigid_avatar.light_direction, 0,
                    sizeof(rigid_avatar.light_direction));
        std::memset(rigid_avatar.light_diffuse, 0,
                    sizeof(rigid_avatar.light_diffuse));
        rigid_avatar.light_direction[0][1] = 1.f;
        rigid_avatar.light_diffuse[0][2] = 1.f;
        std::fill(std::begin(rigid_avatar.diffuse_color),
                  std::end(rigid_avatar.diffuse_color), 1.f);
        auto rendered_rigid_avatar = renderer->render(rigid_avatar, &error);
        INFO(error);
        REQUIRE(rendered_rigid_avatar);
        std::array<std::uint8_t, 32 * 32 * 4> rigid_avatar_pixels{};
        REQUIRE(rendered_rigid_avatar->readback(
            *device, 0, 0, {}, rigid_avatar_pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(rigid_avatar_pixels[avatar_translated_interior + 0] <= 1);
        CHECK(rigid_avatar_pixels[avatar_translated_interior + 1] <= 1);
        CHECK(rigid_avatar_pixels[avatar_translated_interior + 2] >= 254);
        CHECK(rigid_avatar_pixels[avatar_translated_interior + 3] == 255);

        rigid_avatar.texture = diffuse_texture.get();
        auto rendered_rigid_avatar_textured = renderer->render(
            rigid_avatar, &error);
        INFO(error);
        REQUIRE(rendered_rigid_avatar_textured);

        rigid_avatar.avatar_lighting = false;
        rigid_avatar.avatar_unlit = true;
        auto rendered_rigid_avatar_unlit = renderer->render(
            rigid_avatar, &error);
        INFO(error);
        REQUIRE(rendered_rigid_avatar_unlit);
        std::array<std::uint8_t, 32 * 32 * 4> rigid_avatar_unlit_pixels{};
        REQUIRE(rendered_rigid_avatar_unlit->readback(
            *device, 0, 0, {}, rigid_avatar_unlit_pixels.data(), 32 * 4,
            &error));
        INFO(error);
        CHECK(rigid_avatar_unlit_pixels[avatar_translated_interior + 0] == 128);
        CHECK(rigid_avatar_unlit_pixels[avatar_translated_interior + 1] == 64);
        CHECK(rigid_avatar_unlit_pixels[avatar_translated_interior + 2] == 32);
        CHECK(rigid_avatar_unlit_pixels[avatar_translated_interior + 3] == 255);

        ALMetalLitPreviewScene avatar_hint_scene;
        avatar_hint_scene.batches = &rigid_avatar;
        avatar_hint_scene.batch_count = 1;
        avatar_hint_scene.background_texture = diffuse_texture.get();
        avatar_hint_scene.destination_descriptor =
            &destination_template->descriptor();
        auto rendered_avatar_hint = renderer->render(avatar_hint_scene, &error);
        INFO(error);
        REQUIRE(rendered_avatar_hint);
        std::array<std::uint8_t, 32 * 32 * 4> avatar_hint_pixels{};
        REQUIRE(rendered_avatar_hint->readback(
            *device, 0, 0, {}, avatar_hint_pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(avatar_hint_pixels[corner + 0] == 128);
        CHECK(avatar_hint_pixels[corner + 1] == 64);
        CHECK(avatar_hint_pixels[corner + 2] == 32);
        CHECK(avatar_hint_pixels[corner + 3] == 255);

        rigid_avatar.show_edges = true;
        CHECK_FALSE(renderer->render(rigid_avatar, &error));
        CHECK(error == "Metal avatar preview mode is invalid");
        rigid_avatar.show_edges = false;
        rigid_avatar.avatar_lighting = true;
        CHECK_FALSE(renderer->render(rigid_avatar, &error));
        CHECK(error == "Metal avatar preview mode is invalid");
        rigid_avatar.avatar_lighting = false;
        rigid_avatar.texture = nullptr;
        CHECK_FALSE(renderer->render(rigid_avatar, &error));
        CHECK(error == "Metal avatar preview mode is invalid");
        rigid_avatar.texture = diffuse_texture.get();
        rigid_avatar.skin_palette = avatar_palette.data();
        rigid_avatar.skin_palette_float_count = avatar_palette.size();
        rigid_avatar.skin_joint_count = 15;
        CHECK_FALSE(renderer->render(rigid_avatar, &error));
        CHECK(error == "Metal avatar preview mode is invalid");

        avatar_skinned.skin_joint_count = 14;
        CHECK_FALSE(renderer->render(avatar_skinned, &error));
        CHECK(error == "Metal lit preview skinning data is invalid");
        avatar_skinned.skin_joint_count = 15;
        avatar_skinned.show_edges = true;
        error.clear();
        CHECK_FALSE(renderer->render(avatar_skinned, &error));
        CHECK(error == "Metal lit preview skinning data is invalid");

        skinned.skin_joint_count = 0;
        CHECK_FALSE(renderer->render(skinned, &error));
        CHECK(error == "Metal lit preview skinning data is invalid");

        ALMetalTextureDescriptor srgb_destination =
            destination_template->descriptor();
        srgb_destination.format = ALMetalPixelFormat::rgba8_unorm_srgb;
        srgb_destination.label = "Alchemy sRGB preview destination descriptor";
        scene.destination_descriptor = &srgb_destination;
        error.clear();
        auto rendered_srgb = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(rendered_srgb);
        CHECK(rendered_srgb->descriptor().format ==
              ALMetalPixelFormat::rgba8_unorm_srgb);
    }
}

TEST_CASE("almetal: BC texture transfer honors block rows and edge dimensions", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);

        ALMetalTextureDescriptor descriptor;
        descriptor.format = ALMetalPixelFormat::bc1_rgba;
        descriptor.width = 7;
        descriptor.height = 5;
        descriptor.storage = ALMetalStorageMode::private_gpu;
        descriptor.label = "Alchemy BC1 transfer texture";
        auto texture = ALMetalTexture::create(*device, descriptor, &error);
        INFO(error);
        REQUIRE(texture);
        CHECK(texture->isCompressed());
        CHECK(texture->blockWidth() == 4);
        CHECK(texture->blockHeight() == 4);
        CHECK(texture->bytesPerBlock() == 8);
        CHECK(texture->bytesPerPixel() == 0);

        constexpr std::size_t row_pitch = 2 * 8;
        std::array<std::uint8_t, row_pitch * 2> source{};
        for (std::size_t index = 0; index < source.size(); ++index)
        {
            source[index] = static_cast<std::uint8_t>(index * 13u + 5u);
        }
        auto command = device->makeCommandBuffer("Alchemy BC1 upload", &error);
        INFO(error);
        REQUIRE(command);
        REQUIRE(texture->upload(*command, 0, 0, {}, source.data(), row_pitch, &error));
        REQUIRE(command->commitAndWait(&error));
        INFO(error);

        std::array<std::uint8_t, row_pitch * 2> result{};
        REQUIRE(texture->readback(*device, 0, 0, {}, result.data(), row_pitch, &error));
        INFO(error);
        CHECK(result == source);
    }
}

TEST_CASE("almetal: memoryless MSAA target resolves while depth remains transient", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);

        ALMetalRenderTargetDescriptor target_descriptor;
        target_descriptor.width = 13;
        target_descriptor.height = 7;
        target_descriptor.sample_count = 4;
        target_descriptor.color_attachment_count = 1;
        target_descriptor.colors[0].format = ALMetalPixelFormat::bgra8_unorm;
        target_descriptor.colors[0].label = "Alchemy MSAA color";
        target_descriptor.depth_stencil_format = ALMetalPixelFormat::depth32_float;
        target_descriptor.memoryless_multisample = true;
        target_descriptor.memoryless_depth_stencil = true;
        target_descriptor.label = "Alchemy MSAA target";
        auto target = ALMetalRenderTarget::create(*device, target_descriptor, &error);
        INFO(error);
        REQUIRE(target);
        REQUIRE(target->colorTexture(0));
        REQUIRE(target->multisampleColorTexture(0));
        REQUIRE(target->depthStencilTexture());
        CHECK(target->multisampleColorTexture(0)->descriptor().storage == ALMetalStorageMode::memoryless);
        CHECK(target->depthStencilTexture()->descriptor().storage == ALMetalStorageMode::memoryless);

        ALMetalRenderPassConfig pass_config;
        pass_config.colors[0].load = ALMetalLoadAction::clear;
        pass_config.colors[0].store = ALMetalStoreAction::multisample_resolve;
        pass_config.colors[0].clear = {0.2, 0.4, 0.6, 1.0};
        pass_config.depth_load = ALMetalLoadAction::clear;
        pass_config.depth_store = ALMetalStoreAction::dont_care;
        pass_config.clear_depth = 0.0;
        auto pass = target->makeRenderPass(pass_config, &error);
        INFO(error);
        REQUIRE(pass);

        auto command = device->makeCommandBuffer("Alchemy MSAA resolve test", &error);
        INFO(error);
        REQUIRE(command);
        id<MTLRenderCommandEncoder> encoder = [nativeCommand(*command)
            renderCommandEncoderWithDescriptor:(__bridge MTLRenderPassDescriptor*)pass->nativeHandle()];
        REQUIRE(encoder);
        [encoder endEncoding];
        REQUIRE(command->commitAndWait(&error));
        INFO(error);

        std::array<std::uint8_t, 13 * 7 * 4> pixels{};
        REQUIRE(target->colorTexture(0)->readback(*device, 0, 0, {}, pixels.data(), 13 * 4, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(pixels[0]) - 153) <= 1);
        CHECK(std::abs(static_cast<int>(pixels[1]) - 102) <= 1);
        CHECK(std::abs(static_cast<int>(pixels[2]) - 51) <= 1);
        CHECK(pixels[3] == 255);
    }
}

TEST_CASE("almetal: frame scheduler bounds work and recovers abandoned slots", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        auto scheduler = ALMetalFrameScheduler::create(*device, 2, &error);
        INFO(error);
        REQUIRE(scheduler);

        auto first = scheduler->beginFrame("Alchemy scheduled frame one", 100, &error);
        auto abandoned = scheduler->beginFrame("Alchemy abandoned frame", 100, &error);
        REQUIRE(first);
        REQUIRE(abandoned);
        auto blocked = scheduler->beginFrame("Alchemy blocked frame", 1, &error);
        CHECK_FALSE(blocked);

        abandoned.reset();
        auto second = scheduler->beginFrame("Alchemy scheduled frame two", 100, &error);
        INFO(error);
        REQUIRE(second);
        CHECK(first->slot() != second->slot());
        REQUIRE(scheduler->submit(*first, &error));
        REQUIRE(scheduler->submit(*second, &error));
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);

        const ALMetalFrameStats stats = scheduler->stats();
        CHECK(stats.maximum_in_flight == 2);
        CHECK(stats.begun == 3);
        CHECK(stats.submitted == 2);
        CHECK(stats.completed == 2);
        CHECK(stats.failed == 0);
        CHECK(stats.in_flight == 0);
    }
}

TEST_CASE("almetal: bundled MSL compute pipeline dispatches through typed bindings", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        auto library = ALMetalShaderLibrary::loadBuiltin(*device, &error);
        INFO(error);
        REQUIRE(library);
        CHECK(library->hasFunction("almetal_test_compute"));

        ALMetalComputePipelineDescriptor pipeline_descriptor;
        pipeline_descriptor.library = library.get();
        pipeline_descriptor.function = "almetal_test_compute";
        pipeline_descriptor.label = "Alchemy typed compute test";
        auto pipeline = ALMetalComputePipeline::create(*device, pipeline_descriptor, &error);
        INFO(error);
        REQUIRE(pipeline);
        CHECK(pipeline->threadExecutionWidth() > 0);

        constexpr std::uint32_t count = 257;
        std::array<std::uint32_t, count> values{};
        for (std::uint32_t index = 0; index < count; ++index)
        {
            values[index] = index * 5u + 1u;
        }
        ALMetalBufferDescriptor buffer_descriptor;
        buffer_descriptor.length = sizeof(values);
        buffer_descriptor.storage = ALMetalStorageMode::shared;
        buffer_descriptor.label = "Alchemy compute values";
        auto buffer = ALMetalBuffer::create(*device, buffer_descriptor, &error);
        INFO(error);
        REQUIRE(buffer);
        REQUIRE(buffer->write(0, values.data(), sizeof(values), &error));

        auto command = device->makeCommandBuffer("Alchemy typed compute dispatch", &error);
        INFO(error);
        REQUIRE(command);
        auto encoder = ALMetalComputeEncoder::begin(*command, "Alchemy compute encoder", &error);
        INFO(error);
        REQUIRE(encoder);
        REQUIRE(encoder->setPipeline(*pipeline, &error));
        REQUIRE(encoder->setBuffer(0, *buffer, 0, &error));
        const std::uint32_t addend = 19;
        REQUIRE(encoder->setBytes(1, &addend, sizeof(addend), &error));
        const std::uint32_t group_width = std::min(
            pipeline->threadExecutionWidth(), pipeline->maximumTotalThreadsPerThreadgroup());
        REQUIRE(encoder->dispatch(count, 1, 1, group_width, 1, 1, &error));
        REQUIRE(encoder->end(&error));
        REQUIRE(command->commitAndWait(&error));
        INFO(error);

        std::array<std::uint32_t, count> result{};
        REQUIRE(buffer->read(0, result.data(), sizeof(result), &error));
        for (std::uint32_t index = 0; index < count; ++index)
        {
            CHECK(result[index] == values[index] * 3u + addend);
        }
    }
}

TEST_CASE("almetal: water depth pyramid culls only wholly hidden wave patches", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        auto library = ALMetalShaderLibrary::loadBuiltin(*device, &error);
        INFO(error);
        REQUIRE(library);

        const auto make_pipeline = [&](const char* function)
        {
            ALMetalComputePipelineDescriptor descriptor;
            descriptor.library = library.get();
            descriptor.function = function;
            descriptor.label = function;
            return ALMetalComputePipeline::create(
                *device, descriptor, &error);
        };
        auto first_pipeline = make_pipeline(
            "almetal_world_depth_pyramid_first");
        auto last_pipeline = make_pipeline(
            "almetal_world_depth_pyramid_last");
        auto cull_pipeline = make_pipeline(
            "almetal_world_water_wave_occlusion");
        INFO(error);
        REQUIRE(first_pipeline);
        REQUIRE(last_pipeline);
        REQUIRE(cull_pipeline);

        ALMetalTextureDescriptor source_descriptor;
        source_descriptor.format = ALMetalPixelFormat::r32_float;
        source_descriptor.width = 5;
        source_descriptor.height = 3;
        source_descriptor.storage = ALMetalStorageMode::private_gpu;
        source_descriptor.usage = ALMetalTextureUsage::shader_read;
        source_descriptor.label =
            "Alchemy water depth-pyramid test source";
        auto source = ALMetalTexture::create(
            *device, source_descriptor, &error);
        INFO(error);
        REQUIRE(source);

        std::array<std::unique_ptr<ALMetalTexture>, 8> pyramid;
        ALMetalTextureDescriptor level_descriptor;
        level_descriptor.format = ALMetalPixelFormat::r32_float;
        level_descriptor.storage = ALMetalStorageMode::private_gpu;
        level_descriptor.usage = ALMetalTextureUsage::shader_read |
                                 ALMetalTextureUsage::shader_write;
        for (std::size_t level = 0; level < pyramid.size(); ++level)
        {
            level_descriptor.width = 128u >> level;
            level_descriptor.height = 128u >> level;
            level_descriptor.label =
                "Alchemy water depth-pyramid test level " +
                std::to_string(level);
            pyramid[level] = ALMetalTexture::create(
                *device, level_descriptor, &error);
            INFO(error);
            REQUIRE(pyramid[level]);
        }

        const auto upload_source = [&](const std::array<float, 15>& values)
        {
            auto command = device->makeCommandBuffer(
                "Alchemy water depth-pyramid source upload", &error);
            REQUIRE(command);
            REQUIRE(source->upload(
                *command, 0, 0, {}, values.data(),
                5 * sizeof(float), &error));
            REQUIRE(command->commitAndWait(&error));
            INFO(error);
        };
        const auto build_pyramid = [&](std::uint32_t reverse_z)
        {
            auto command = device->makeCommandBuffer(
                "Alchemy water depth-pyramid test", &error);
            REQUIRE(command);
            auto first = ALMetalComputeEncoder::begin(
                *command, "Alchemy water depth-pyramid first test", &error);
            REQUIRE(first);
            REQUIRE(first->setPipeline(*first_pipeline, &error));
            REQUIRE(first->setTexture(0, source.get(), &error));
            REQUIRE(first->setBytes(
                0, &reverse_z, sizeof(reverse_z), &error));
            for (std::size_t level = 0; level < 5; ++level)
            {
                REQUIRE(first->setTexture(
                    static_cast<std::uint32_t>(level + 1),
                    pyramid[level].get(), &error));
            }
            REQUIRE(first->dispatch(
                128, 128, 1, 16, 16, 1, &error));
            REQUIRE(first->end(&error));

            auto last = ALMetalComputeEncoder::begin(
                *command, "Alchemy water depth-pyramid last test", &error);
            REQUIRE(last);
            REQUIRE(last->setPipeline(*last_pipeline, &error));
            REQUIRE(last->setTexture(0, pyramid[4].get(), &error));
            REQUIRE(last->setBytes(
                0, &reverse_z, sizeof(reverse_z), &error));
            for (std::size_t level = 5; level < 8; ++level)
            {
                REQUIRE(last->setTexture(
                    static_cast<std::uint32_t>(level - 4),
                    pyramid[level].get(), &error));
            }
            REQUIRE(last->dispatch(
                16, 16, 1, 16, 16, 1, &error));
            REQUIRE(last->end(&error));
            REQUIRE(command->commitAndWait(&error));
            INFO(error);
        };

        std::array<float, 15> depth_values{};
        depth_values.fill(0.1f);
        depth_values.back() = 0.9f;
        upload_source(depth_values);
        build_pyramid(0u);
        float coarsest = 0.f;
        REQUIRE(pyramid[7]->readback(
            *device, 0, 0, {}, &coarsest, sizeof(float), &error));
        INFO(error);
        CHECK(std::abs(coarsest - 0.9f) < 0.0001f);
        build_pyramid(1u);
        REQUIRE(pyramid[7]->readback(
            *device, 0, 0, {}, &coarsest, sizeof(float), &error));
        INFO(error);
        CHECK(std::abs(coarsest - 0.1f) < 0.0001f);

        ALMetalTextureDescriptor cell_descriptor;
        cell_descriptor.format = ALMetalPixelFormat::rg32_float;
        cell_descriptor.width = 3;
        cell_descriptor.height = 3;
        cell_descriptor.storage = ALMetalStorageMode::private_gpu;
        cell_descriptor.usage = ALMetalTextureUsage::shader_read;
        cell_descriptor.label =
            "Alchemy water wave-occlusion test cell map";
        auto cell_map = ALMetalTexture::create(
            *device, cell_descriptor, &error);
        INFO(error);
        REQUIRE(cell_map);
        std::array<float, 3 * 3 * 2> cells{};
        for (std::size_t cell = 0; cell < 9; ++cell)
        {
            cells[cell * 2] = 0.5f;
            cells[cell * 2 + 1] = 1.f;
        }
        auto cell_upload = device->makeCommandBuffer(
            "Alchemy water wave-occlusion cell upload", &error);
        REQUIRE(cell_upload);
        REQUIRE(cell_map->upload(
            *cell_upload, 0, 0, {}, cells.data(),
            3 * 2 * sizeof(float), &error));
        REQUIRE(cell_upload->commitAndWait(&error));

        std::array<std::uint16_t, 64 * 6> factor_values{};
        factor_values.fill(0x3c00u);
        ALMetalBufferDescriptor factor_descriptor;
        factor_descriptor.length = sizeof(factor_values);
        factor_descriptor.storage = ALMetalStorageMode::shared;
        factor_descriptor.label =
            "Alchemy water wave-occlusion test factors";
        auto factors = ALMetalBuffer::create(
            *device, factor_descriptor, &error);
        INFO(error);
        REQUIRE(factors);

        struct alignas(16) WaterOcclusionConstants
        {
            float modelview_projection[16]{};
            float cell_square[4]{};
            float screen_displacement[4]{};
            std::int32_t patch_rect[4]{};
            std::int32_t patch_order[4]{};
            std::uint32_t config[4]{};
        } constants;
        static_assert(sizeof(WaterOcclusionConstants) == 144);
        constants.modelview_projection[0] = 1.f;
        constants.modelview_projection[5] = 1.f;
        constants.modelview_projection[10] = 1.f;
        constants.modelview_projection[15] = 1.f;
        constants.cell_square[0] = -1.5f;
        constants.cell_square[1] = -1.5f;
        constants.cell_square[2] = 1.f;
        constants.cell_square[3] = 3.f;
        constants.screen_displacement[0] = 5.f;
        constants.screen_displacement[1] = 3.f;
        constants.screen_displacement[2] = 0.1f;
        constants.patch_rect[0] = 1;
        constants.patch_rect[1] = 1;
        constants.patch_rect[2] = 2;
        constants.patch_rect[3] = 2;
        constants.config[0] = 64;
        constants.config[1] = 8;

        const auto run_cull = [&](float scene_depth,
                                  std::uint32_t reverse_z,
                                  bool expect_culled)
        {
            depth_values.fill(scene_depth);
            upload_source(depth_values);
            build_pyramid(reverse_z);
            factor_values.fill(0x3c00u);
            REQUIRE(factors->write(
                0, factor_values.data(), sizeof(factor_values), &error));
            constants.config[2] = reverse_z;
            auto command = device->makeCommandBuffer(
                "Alchemy water wave-occlusion test", &error);
            REQUIRE(command);
            auto cull = ALMetalComputeEncoder::begin(
                *command, "Alchemy water wave-occlusion test", &error);
            REQUIRE(cull);
            REQUIRE(cull->setPipeline(*cull_pipeline, &error));
            REQUIRE(cull->setBuffer(0, *factors, 0, &error));
            REQUIRE(cull->setBytes(
                1, &constants, sizeof(constants), &error));
            REQUIRE(cull->setTexture(0, cell_map.get(), &error));
            for (std::size_t level = 0; level < pyramid.size(); ++level)
            {
                REQUIRE(cull->setTexture(
                    static_cast<std::uint32_t>(level + 1),
                    pyramid[level].get(), &error));
            }
            REQUIRE(cull->dispatch(64, 1, 1, 64, 1, 1, &error));
            REQUIRE(cull->end(&error));
            REQUIRE(command->commitAndWait(&error));
            INFO(error);
            REQUIRE(factors->read(
                0, factor_values.data(), sizeof(factor_values), &error));
            const std::uint16_t expected =
                expect_culled ? 0u : 0x3c00u;
            CHECK(std::all_of(
                factor_values.begin(), factor_values.end(),
                [expected](std::uint16_t value)
                {
                    return value == expected;
                }));
        };
        run_cull(0.1f, 0u, true);
        run_cull(0.9f, 0u, false);
        run_cull(0.9f, 1u, true);
        run_cull(0.1f, 1u, false);
    }
}

TEST_CASE("almetal: bundled MSL render pipeline draws a typed triangle", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        auto library = ALMetalShaderLibrary::loadBuiltin(*device, &error);
        INFO(error);
        REQUIRE(library);
        CHECK(library->hasFunction("almetal_test_vertex"));
        CHECK(library->hasFunction("almetal_test_fragment"));

        ALMetalRenderTargetDescriptor target_descriptor;
        target_descriptor.width = 32;
        target_descriptor.height = 32;
        target_descriptor.color_attachment_count = 1;
        target_descriptor.colors[0].format = ALMetalPixelFormat::rgba8_unorm;
        target_descriptor.depth_stencil_format = ALMetalPixelFormat::depth32_float;
        target_descriptor.label = "Alchemy typed triangle target";
        auto target = ALMetalRenderTarget::create(*device, target_descriptor, &error);
        INFO(error);
        REQUIRE(target);

        ALMetalRenderPipelineDescriptor pipeline_descriptor;
        pipeline_descriptor.library = library.get();
        pipeline_descriptor.vertex_function = "almetal_test_vertex";
        pipeline_descriptor.fragment_function = "almetal_test_fragment";
        pipeline_descriptor.color_attachment_count = 1;
        pipeline_descriptor.colors[0].format = ALMetalPixelFormat::rgba8_unorm;
        pipeline_descriptor.depth_stencil_format = ALMetalPixelFormat::depth32_float;
        pipeline_descriptor.label = "Alchemy typed triangle pipeline";
        auto pipeline = ALMetalRenderPipeline::create(*device, pipeline_descriptor, &error);
        INFO(error);
        REQUIRE(pipeline);

        ALMetalDepthStencilDescriptor depth_descriptor;
        depth_descriptor.depth_compare = ALMetalCompareFunction::less_equal;
        depth_descriptor.depth_write_enabled = true;
        depth_descriptor.label = "Alchemy typed triangle depth";
        auto depth_state = ALMetalDepthStencilState::create(*device, depth_descriptor, &error);
        INFO(error);
        REQUIRE(depth_state);

        ALMetalSamplerDescriptor sampler_descriptor;
        sampler_descriptor.max_anisotropy = 8;
        sampler_descriptor.label = "Alchemy linear repeat sampler";
        auto sampler = ALMetalSamplerState::create(*device, sampler_descriptor, &error);
        INFO(error);
        REQUIRE(sampler);

        struct Vertex
        {
            float position[2];
            float color[4];
        };
        const std::array<Vertex, 3> vertices{{
            {{-0.9f, -0.9f}, {0.125f, 0.5f, 0.875f, 1.0f}},
            {{ 0.9f, -0.9f}, {0.125f, 0.5f, 0.875f, 1.0f}},
            {{ 0.0f,  0.9f}, {0.125f, 0.5f, 0.875f, 1.0f}},
        }};
        ALMetalBufferDescriptor vertex_descriptor;
        vertex_descriptor.length = sizeof(vertices);
        vertex_descriptor.storage = ALMetalStorageMode::shared;
        vertex_descriptor.label = "Alchemy typed triangle vertices";
        auto vertex_buffer = ALMetalBuffer::create(*device, vertex_descriptor, &error);
        INFO(error);
        REQUIRE(vertex_buffer);
        REQUIRE(vertex_buffer->write(0, vertices.data(), sizeof(vertices), &error));

        ALMetalRenderPassConfig pass_config;
        pass_config.colors[0].load = ALMetalLoadAction::clear;
        pass_config.colors[0].store = ALMetalStoreAction::store;
        pass_config.colors[0].clear = {0.0, 0.0, 0.0, 1.0};
        pass_config.depth_load = ALMetalLoadAction::clear;
        pass_config.depth_store = ALMetalStoreAction::dont_care;
        pass_config.clear_depth = 1.0;
        auto pass = target->makeRenderPass(pass_config, &error);
        INFO(error);
        REQUIRE(pass);

        auto command = device->makeCommandBuffer("Alchemy typed triangle draw", &error);
        INFO(error);
        REQUIRE(command);
        auto encoder = ALMetalRenderEncoder::begin(*command, *pass, "Alchemy triangle encoder", &error);
        INFO(error);
        REQUIRE(encoder);
        REQUIRE(encoder->setPipeline(*pipeline, &error));
        REQUIRE(encoder->setDepthStencilState(depth_state.get(), &error));
        REQUIRE(encoder->setVertexBuffer(0, *vertex_buffer, 0, &error));
        REQUIRE(encoder->setFragmentSampler(0, sampler.get(), &error));
        REQUIRE(encoder->setViewport({0.0, 0.0, 32.0, 32.0, 0.0, 1.0}, &error));
        REQUIRE(encoder->setScissor({0, 0, 32, 32}, &error));
        REQUIRE(encoder->setCullMode(ALMetalCullMode::none, &error));
        REQUIRE(encoder->setFrontFacingWinding(ALMetalWinding::counter_clockwise, &error));
        REQUIRE(encoder->draw(ALMetalPrimitiveType::triangle, 0, 3, 1, &error));
        REQUIRE(encoder->end(&error));
        REQUIRE(command->commitAndWait(&error));
        INFO(error);

        std::array<std::uint8_t, 32 * 32 * 4> pixels{};
        REQUIRE(target->colorTexture(0)->readback(*device, 0, 0, {}, pixels.data(), 32 * 4, &error));
        INFO(error);
        const std::size_t center = (16 * 32 + 16) * 4;
        CHECK(std::abs(static_cast<int>(pixels[center + 0]) - 32) <= 1);
        CHECK(std::abs(static_cast<int>(pixels[center + 1]) - 128) <= 1);
        CHECK(std::abs(static_cast<int>(pixels[center + 2]) - 223) <= 1);
        CHECK(pixels[center + 3] == 255);
    }
}

TEST_CASE("almetal: typed depth-stencil state preserves masked stencil semantics", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        auto library = ALMetalShaderLibrary::loadBuiltin(*device, &error);
        INFO(error);
        REQUIRE(library);

        ALMetalRenderTargetDescriptor target_descriptor;
        target_descriptor.width = 32;
        target_descriptor.height = 32;
        target_descriptor.color_attachment_count = 1;
        target_descriptor.colors[0].format =
            ALMetalPixelFormat::rgba8_unorm;
        target_descriptor.depth_stencil_format =
            ALMetalPixelFormat::depth32_float_stencil8;
        target_descriptor.label = "Alchemy typed stencil target";
        auto target = ALMetalRenderTarget::create(
            *device, target_descriptor, &error);
        INFO(error);
        REQUIRE(target);

        ALMetalRenderPipelineDescriptor pipeline_descriptor;
        pipeline_descriptor.library = library.get();
        pipeline_descriptor.vertex_function = "almetal_test_vertex";
        pipeline_descriptor.fragment_function = "almetal_test_fragment";
        pipeline_descriptor.color_attachment_count = 1;
        pipeline_descriptor.colors[0].format =
            ALMetalPixelFormat::rgba8_unorm;
        pipeline_descriptor.depth_stencil_format =
            ALMetalPixelFormat::depth32_float_stencil8;
        pipeline_descriptor.label = "Alchemy typed stencil color pipeline";
        auto color_pipeline = ALMetalRenderPipeline::create(
            *device, pipeline_descriptor, &error);
        INFO(error);
        REQUIRE(color_pipeline);
        pipeline_descriptor.colors[0].write_mask =
            ALMetalColorWriteMask::none;
        pipeline_descriptor.label = "Alchemy typed stencil mark pipeline";
        auto mark_pipeline = ALMetalRenderPipeline::create(
            *device, pipeline_descriptor, &error);
        INFO(error);
        REQUIRE(mark_pipeline);

        ALMetalDepthStencilDescriptor mark_descriptor;
        mark_descriptor.depth_compare = ALMetalCompareFunction::always;
        mark_descriptor.depth_write_enabled = false;
        mark_descriptor.stencil_enabled = true;
        mark_descriptor.front_stencil.depth_stencil_pass =
            ALMetalStencilOperation::replace;
        mark_descriptor.front_stencil.read_mask = 0x1u;
        mark_descriptor.front_stencil.write_mask = 0x1u;
        mark_descriptor.back_stencil = mark_descriptor.front_stencil;
        mark_descriptor.label = "Alchemy typed stencil mark";
        auto mark_state = ALMetalDepthStencilState::create(
            *device, mark_descriptor, &error);
        INFO(error);
        REQUIRE(mark_state);

        ALMetalDepthStencilDescriptor test_descriptor;
        test_descriptor.depth_compare = ALMetalCompareFunction::always;
        test_descriptor.depth_write_enabled = false;
        test_descriptor.stencil_enabled = true;
        test_descriptor.front_stencil.compare =
            ALMetalCompareFunction::equal;
        test_descriptor.front_stencil.read_mask = 0x1u;
        test_descriptor.front_stencil.write_mask = 0u;
        test_descriptor.back_stencil = test_descriptor.front_stencil;
        test_descriptor.label = "Alchemy typed stencil test";
        auto test_state = ALMetalDepthStencilState::create(
            *device, test_descriptor, &error);
        INFO(error);
        REQUIRE(test_state);

        struct Vertex
        {
            float position[2];
            float color[4];
        };
        const auto make_vertices = [](const std::array<float, 4>& color)
        {
            return std::array<Vertex, 3>{{
                {{-0.9f, -0.9f}, {color[0], color[1], color[2], color[3]}},
                {{ 0.9f, -0.9f}, {color[0], color[1], color[2], color[3]}},
                {{ 0.0f,  0.9f}, {color[0], color[1], color[2], color[3]}},
            }};
        };
        const auto green_vertices = make_vertices({0.f, 1.f, 0.f, 1.f});
        const auto red_vertices = make_vertices({1.f, 0.f, 0.f, 1.f});
        ALMetalBufferDescriptor buffer_descriptor;
        buffer_descriptor.length = sizeof(green_vertices);
        buffer_descriptor.storage = ALMetalStorageMode::shared;
        buffer_descriptor.label = "Alchemy typed stencil vertices";
        auto green_buffer = ALMetalBuffer::create(
            *device, buffer_descriptor, &error);
        auto red_buffer = ALMetalBuffer::create(
            *device, buffer_descriptor, &error);
        INFO(error);
        REQUIRE(green_buffer);
        REQUIRE(red_buffer);
        REQUIRE(green_buffer->write(
            0, green_vertices.data(), sizeof(green_vertices), &error));
        REQUIRE(red_buffer->write(
            0, red_vertices.data(), sizeof(red_vertices), &error));

        ALMetalRenderPassConfig pass_config;
        pass_config.colors[0].load = ALMetalLoadAction::clear;
        pass_config.colors[0].store = ALMetalStoreAction::store;
        pass_config.colors[0].clear = {0.0, 0.0, 0.0, 1.0};
        pass_config.depth_load = ALMetalLoadAction::clear;
        pass_config.depth_store = ALMetalStoreAction::dont_care;
        pass_config.clear_depth = 1.0;
        pass_config.stencil_load = ALMetalLoadAction::clear;
        pass_config.stencil_store = ALMetalStoreAction::store;
        pass_config.clear_stencil = 0;
        auto pass = target->makeRenderPass(pass_config, &error);
        INFO(error);
        REQUIRE(pass);

        auto command = device->makeCommandBuffer(
            "Alchemy typed stencil draw", &error);
        INFO(error);
        REQUIRE(command);
        auto encoder = ALMetalRenderEncoder::begin(
            *command, *pass, "Alchemy typed stencil encoder", &error);
        INFO(error);
        REQUIRE(encoder);
        REQUIRE(encoder->setViewport(
            {0.0, 0.0, 32.0, 32.0, 0.0, 1.0}, &error));
        REQUIRE(encoder->setScissor({0, 0, 32, 32}, &error));
        REQUIRE(encoder->setCullMode(ALMetalCullMode::none, &error));

        // Reference 3 is masked to bit zero, exactly like the water mask's
        // independent EXCLUDE_BIT and SURFACE_BIT transactions.
        REQUIRE(encoder->setPipeline(*mark_pipeline, &error));
        REQUIRE(encoder->setDepthStencilState(mark_state.get(), &error));
        REQUIRE(encoder->setStencilReferenceValue(3u, &error));
        REQUIRE(encoder->setVertexBuffer(0, *green_buffer, 0, &error));
        REQUIRE(encoder->draw(
            ALMetalPrimitiveType::triangle, 0, 3, 1, &error));

        REQUIRE(encoder->setPipeline(*color_pipeline, &error));
        REQUIRE(encoder->setDepthStencilState(test_state.get(), &error));
        REQUIRE(encoder->setStencilReferenceValue(1u, &error));
        REQUIRE(encoder->setVertexBuffer(0, *green_buffer, 0, &error));
        REQUIRE(encoder->draw(
            ALMetalPrimitiveType::triangle, 0, 3, 1, &error));

        // The zero reference must fail over the marked triangle. If stencil
        // comparison or the read mask is lost, this red draw overwrites it.
        REQUIRE(encoder->setStencilReferenceValue(0u, &error));
        REQUIRE(encoder->setVertexBuffer(0, *red_buffer, 0, &error));
        REQUIRE(encoder->draw(
            ALMetalPrimitiveType::triangle, 0, 3, 1, &error));
        REQUIRE(encoder->end(&error));
        REQUIRE(command->commitAndWait(&error));
        INFO(error);

        std::array<std::uint8_t, 32 * 32 * 4> pixels{};
        REQUIRE(target->colorTexture(0)->readback(
            *device, 0, 0, {}, pixels.data(), 32 * 4, &error));
        INFO(error);
        const std::size_t center = (16 * 32 + 16) * 4;
        CHECK(pixels[center + 0] == 0);
        CHECK(pixels[center + 1] == 255);
        CHECK(pixels[center + 2] == 0);
        CHECK(pixels[center + 3] == 255);
        CHECK(pixels[0] == 0);
        CHECK(pixels[1] == 0);
        CHECK(pixels[2] == 0);
        CHECK(pixels[3] == 255);
    }
}

TEST_CASE("almetal: a native quad patch tessellates through the typed render encoder", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);

        const std::string source = R"metal(
#include <metal_stdlib>
using namespace metal;

struct TessellatedVertex
{
    float4 position [[position]];
    float2 uv;
};

[[patch(quad, 4)]]
vertex TessellatedVertex almetal_test_tessellated_quad(
    const device float2* control_points [[buffer(0)]],
    uint patch_id [[patch_id]],
    float2 uv [[position_in_patch]])
{
    const uint base = patch_id * 4;
    const float2 bottom = mix(control_points[base], control_points[base + 1], uv.x);
    const float2 top = mix(control_points[base + 3], control_points[base + 2], uv.x);

    TessellatedVertex result;
    result.position = float4(mix(bottom, top, uv.y), 0.0f, 1.0f);
    result.uv = uv;
    return result;
}

fragment float4 almetal_test_tessellated_color(TessellatedVertex input [[stage_in]])
{
    return float4(input.uv, 0.25f, 1.0f);
}
)metal";
        auto library = ALMetalShaderLibrary::compileSource(
            *device, source, "Alchemy tessellation test library", &error);
        INFO(error);
        REQUIRE(library);

        ALMetalRenderPipelineDescriptor pipeline_descriptor;
        pipeline_descriptor.library = library.get();
        pipeline_descriptor.vertex_function = "almetal_test_tessellated_quad";
        pipeline_descriptor.fragment_function = "almetal_test_tessellated_color";
        pipeline_descriptor.color_attachment_count = 1;
        pipeline_descriptor.colors[0].format = ALMetalPixelFormat::rgba8_unorm;
        pipeline_descriptor.tessellation.enabled = true;
        pipeline_descriptor.tessellation.partition_mode =
            ALMetalTessellationPartitionMode::integer;
        pipeline_descriptor.tessellation.maximum_factor = 16;
        pipeline_descriptor.tessellation.factor_scale_enabled = true;
        pipeline_descriptor.tessellation.factor_step_function =
            ALMetalTessellationFactorStepFunction::per_patch;
        pipeline_descriptor.tessellation.output_winding =
            ALMetalTessellationOutputWinding::counter_clockwise;
        pipeline_descriptor.label = "Alchemy typed quad tessellation pipeline";

        ALMetalRenderPipelineDescriptor invalid_descriptor = pipeline_descriptor;
        invalid_descriptor.tessellation.maximum_factor = 65;
        CHECK_FALSE(ALMetalRenderPipeline::create(*device, invalid_descriptor, &error));
        CHECK_FALSE(error.empty());
        error.clear();

        auto pipeline = ALMetalRenderPipeline::create(*device, pipeline_descriptor, &error);
        INFO(error);
        REQUIRE(pipeline);
        CHECK(pipeline->descriptor().tessellation.enabled);
        CHECK(pipeline->descriptor().tessellation.maximum_factor == 16);

        ALMetalRenderTargetDescriptor target_descriptor;
        target_descriptor.width = 32;
        target_descriptor.height = 32;
        target_descriptor.color_attachment_count = 1;
        target_descriptor.colors[0].format = ALMetalPixelFormat::rgba8_unorm;
        target_descriptor.label = "Alchemy tessellation target";
        auto target = ALMetalRenderTarget::create(*device, target_descriptor, &error);
        INFO(error);
        REQUIRE(target);

        const std::array<std::array<float, 2>, 4> control_points{{
            {{-0.8f, -0.8f}},
            {{ 0.8f, -0.8f}},
            {{ 0.8f,  0.8f}},
            {{-0.8f,  0.8f}},
        }};
        ALMetalBufferDescriptor control_point_descriptor;
        control_point_descriptor.length = sizeof(control_points);
        control_point_descriptor.storage = ALMetalStorageMode::shared;
        control_point_descriptor.label = "Alchemy quad control points";
        auto control_point_buffer = ALMetalBuffer::create(
            *device, control_point_descriptor, &error);
        INFO(error);
        REQUIRE(control_point_buffer);
        REQUIRE(control_point_buffer->write(
            0, control_points.data(), sizeof(control_points), &error));

        // Four outer and two inner half-precision factors, each set to 4.0.
        std::array<std::uint16_t, 128> tessellation_factors{};
        std::fill_n(tessellation_factors.begin(), 6, std::uint16_t{0x4400});
        ALMetalBufferDescriptor factor_descriptor;
        factor_descriptor.length = sizeof(tessellation_factors);
        factor_descriptor.storage = ALMetalStorageMode::shared;
        factor_descriptor.label = "Alchemy quad tessellation factors";
        auto factor_buffer = ALMetalBuffer::create(*device, factor_descriptor, &error);
        INFO(error);
        REQUIRE(factor_buffer);
        REQUIRE(factor_buffer->write(
            0, tessellation_factors.data(), sizeof(tessellation_factors), &error));

        ALMetalRenderPassConfig pass_config;
        pass_config.colors[0].load = ALMetalLoadAction::clear;
        pass_config.colors[0].store = ALMetalStoreAction::store;
        pass_config.colors[0].clear = {0.0, 0.0, 0.0, 1.0};
        auto pass = target->makeRenderPass(pass_config, &error);
        INFO(error);
        REQUIRE(pass);

        auto command = device->makeCommandBuffer("Alchemy typed quad tessellation", &error);
        INFO(error);
        REQUIRE(command);
        auto encoder = ALMetalRenderEncoder::begin(
            *command, *pass, "Alchemy tessellation encoder", &error);
        INFO(error);
        REQUIRE(encoder);
        REQUIRE(encoder->setPipeline(*pipeline, &error));
        REQUIRE(encoder->setVertexBuffer(0, *control_point_buffer, 0, &error));
        REQUIRE(encoder->setViewport({0.0, 0.0, 32.0, 32.0, 0.0, 1.0}, &error));
        REQUIRE(encoder->setScissor({0, 0, 32, 32}, &error));
        REQUIRE(encoder->setCullMode(ALMetalCullMode::none, &error));

        CHECK_FALSE(encoder->draw(ALMetalPrimitiveType::triangle, 0, 3, 1, &error));
        CHECK_FALSE(encoder->drawPatches(4, 0, 1, 1, 0, &error));
        CHECK_FALSE(encoder->setTessellationFactorBuffer(
            *factor_buffer, factor_buffer->length(), 0, &error));
        CHECK_FALSE(encoder->setTessellationFactorBuffer(*factor_buffer, 2, 0, &error));
        CHECK_FALSE(encoder->setTessellationFactorBuffer(*factor_buffer, 0, 2, &error));
        CHECK_FALSE(encoder->setTessellationFactorScale(
            std::numeric_limits<float>::quiet_NaN(), &error));
        error.clear();

        REQUIRE(encoder->setTessellationFactorBuffer(*factor_buffer, 0, 0, &error));
        REQUIRE(encoder->setTessellationFactorScale(1.0f, &error));
        REQUIRE(encoder->drawPatches(4, 0, 1, 1, 0, &error));
        REQUIRE(encoder->end(&error));
        REQUIRE(command->commitAndWait(&error));
        INFO(error);

        std::array<std::uint8_t, 32 * 32 * 4> pixels{};
        REQUIRE(target->colorTexture(0)->readback(
            *device, 0, 0, {}, pixels.data(), 32 * 4, &error));
        INFO(error);
        const std::size_t center = (16 * 32 + 16) * 4;
        CHECK(std::abs(static_cast<int>(pixels[center + 0]) - 128) <= 9);
        CHECK(std::abs(static_cast<int>(pixels[center + 1]) - 128) <= 9);
        CHECK(std::abs(static_cast<int>(pixels[center + 2]) - 64) <= 1);
        CHECK(pixels[center + 3] == 255);

        const std::size_t outside = (1 * 32 + 1) * 4;
        CHECK(pixels[outside + 0] == 0);
        CHECK(pixels[outside + 1] == 0);
        CHECK(pixels[outside + 2] == 0);
        CHECK(pixels[outside + 3] == 255);
    }
}

TEST_CASE("almetal: PBR material preview preserves glTF texture semantics", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        auto renderer = ALMetalPBRPreviewRenderer::create(*device, &error);
        INFO(error);
        REQUIRE(renderer);

        constexpr std::size_t position_offset = 0;
        constexpr std::size_t normal_offset =
            position_offset + sizeof(float) * 4 * 3;
        constexpr std::size_t texcoord_offset =
            normal_offset + sizeof(float) * 4 * 3;
        constexpr std::size_t color_offset =
            texcoord_offset + sizeof(float) * 2 * 3;
        constexpr std::size_t tangent_offset =
            (color_offset + sizeof(std::uint8_t) * 4 * 3 + 15) & ~std::size_t{15};
        std::array<std::uint8_t,
                   tangent_offset + sizeof(float) * 4 * 3> vertex_bytes{};
        const float positions[3][4] = {
            {-1.f, -1.f, 0.f, 1.f},
            { 3.f, -1.f, 0.f, 1.f},
            {-1.f,  3.f, 0.f, 1.f},
        };
        const float normals[3][4] = {
            {0.f, 0.f, 1.f, 0.f},
            {0.f, 0.f, 1.f, 0.f},
            {0.f, 0.f, 1.f, 0.f},
        };
        const float texcoords[3][2] = {
            {0.25f, 0.5f}, {0.25f, 0.5f}, {0.25f, 0.5f},
        };
        const std::uint8_t colors[3][4] = {
            {255, 255, 255, 255},
            {255, 255, 255, 255},
            {255, 255, 255, 255},
        };
        const float tangents[3][4] = {
            {1.f, 0.f, 0.f, 1.f},
            {1.f, 0.f, 0.f, 1.f},
            {1.f, 0.f, 0.f, 1.f},
        };
        std::memcpy(vertex_bytes.data() + position_offset,
                    positions, sizeof(positions));
        std::memcpy(vertex_bytes.data() + normal_offset,
                    normals, sizeof(normals));
        std::memcpy(vertex_bytes.data() + texcoord_offset,
                    texcoords, sizeof(texcoords));
        std::memcpy(vertex_bytes.data() + color_offset,
                    colors, sizeof(colors));
        std::memcpy(vertex_bytes.data() + tangent_offset,
                    tangents, sizeof(tangents));

        ALMetalBufferDescriptor vertex_descriptor;
        vertex_descriptor.length = vertex_bytes.size();
        vertex_descriptor.storage = ALMetalStorageMode::shared;
        vertex_descriptor.label = "Alchemy PBR preview test vertices";
        auto vertex_buffer = ALMetalBuffer::create(
            *device, vertex_descriptor, &error);
        INFO(error);
        REQUIRE(vertex_buffer);
        REQUIRE(vertex_buffer->write(
            0, vertex_bytes.data(), vertex_bytes.size(), &error));

        const std::array<std::uint16_t, 3> indices{{0, 1, 2}};
        ALMetalBufferDescriptor index_descriptor;
        index_descriptor.length = sizeof(indices);
        index_descriptor.storage = ALMetalStorageMode::shared;
        index_descriptor.label = "Alchemy PBR preview test indices";
        auto index_buffer = ALMetalBuffer::create(
            *device, index_descriptor, &error);
        INFO(error);
        REQUIRE(index_buffer);
        REQUIRE(index_buffer->write(
            0, indices.data(), sizeof(indices), &error));

        auto make_texture = [&](ALMetalPixelFormat format,
                                std::uint32_t width,
                                const std::uint8_t* bytes,
                                std::size_t bytes_per_row,
                                const char* label)
        {
            ALMetalTextureDescriptor descriptor;
            descriptor.format = format;
            descriptor.width = width;
            descriptor.height = 1;
            descriptor.storage = ALMetalStorageMode::private_gpu;
            descriptor.usage = ALMetalTextureUsage::shader_read;
            descriptor.label = label;
            auto texture = ALMetalTexture::create(*device, descriptor, &error);
            INFO(error);
            REQUIRE(texture);
            auto upload = device->makeCommandBuffer(label, &error);
            INFO(error);
            REQUIRE(upload);
            REQUIRE(texture->upload(
                *upload, 0, 0, {}, bytes, bytes_per_row, &error));
            REQUIRE(upload->commitAndWait(&error));
            INFO(error);
            return texture;
        };

        const std::array<std::uint8_t, 4> opaque_black{{0, 0, 0, 255}};
        const std::array<std::uint8_t, 4> opaque_white{{255, 255, 255, 255}};
        const std::array<std::uint8_t, 4> half_alpha_black{{0, 0, 0, 128}};
        const std::array<std::uint8_t, 4> flat_normal{{128, 128, 255, 255}};
        const std::array<std::uint8_t, 4> zero_ambient_orm{{0, 255, 0, 255}};
        const std::array<std::uint8_t, 4> glossy_metal_orm{{255, 0, 255, 255}};
        const std::array<std::uint8_t, 4> rough_metal_orm{{255, 255, 255, 255}};
        const std::array<std::uint8_t, 4> black_emissive{{0, 0, 0, 255}};
        const std::array<std::uint8_t, 8> red_green_emissive{{
            255, 0, 0, 255, 0, 255, 0, 255,
        }};
        auto base = make_texture(
            ALMetalPixelFormat::rgba8_unorm_srgb, 1,
            opaque_black.data(), 4, "Alchemy PBR preview test base");
        auto white_base = make_texture(
            ALMetalPixelFormat::rgba8_unorm_srgb, 1,
            opaque_white.data(), 4,
            "Alchemy PBR preview direct-light test base");
        auto cutout_base = make_texture(
            ALMetalPixelFormat::rgba8_unorm_srgb, 1,
            half_alpha_black.data(), 4,
            "Alchemy PBR preview test cutout base");
        auto normal = make_texture(
            ALMetalPixelFormat::rgba8_unorm, 1,
            flat_normal.data(), 4, "Alchemy PBR preview test normal");
        auto orm = make_texture(
            ALMetalPixelFormat::rgba8_unorm, 1,
            zero_ambient_orm.data(), 4, "Alchemy PBR preview test ORM");
        auto glossy_metal = make_texture(
            ALMetalPixelFormat::rgba8_unorm, 1,
            glossy_metal_orm.data(), 4,
            "Alchemy PBR preview glossy-metal test ORM");
        auto rough_metal = make_texture(
            ALMetalPixelFormat::rgba8_unorm, 1,
            rough_metal_orm.data(), 4,
            "Alchemy PBR preview rough-metal test ORM");
        auto emissive = make_texture(
            ALMetalPixelFormat::rgba8_unorm_srgb, 2,
            red_green_emissive.data(), 8,
            "Alchemy PBR preview test emissive");
        auto unlit_emissive = make_texture(
            ALMetalPixelFormat::rgba8_unorm_srgb, 1,
            black_emissive.data(), 4,
            "Alchemy PBR preview direct-light test emissive");

        ALMetalTextureDescriptor environment_descriptor;
        environment_descriptor.type = ALMetalTextureType::texture_cube;
        environment_descriptor.format = ALMetalPixelFormat::rgba16_float;
        environment_descriptor.width = 1;
        environment_descriptor.height = 1;
        environment_descriptor.storage = ALMetalStorageMode::private_gpu;
        environment_descriptor.usage = ALMetalTextureUsage::shader_read;
        environment_descriptor.label =
            "Alchemy PBR preview test environment";
        auto environment_texture = ALMetalTexture::create(
            *device, environment_descriptor, &error);
        INFO(error);
        REQUIRE(environment_texture);
        const std::array<std::uint16_t, 4> black_environment{{0, 0, 0, 0}};
        auto environment_upload = device->makeCommandBuffer(
            "Alchemy PBR preview test environment upload", &error);
        INFO(error);
        REQUIRE(environment_upload);
        for (std::uint32_t face = 0; face < 6; ++face)
        {
            REQUIRE(environment_texture->upload(
                *environment_upload, 0, face, {},
                black_environment.data(), sizeof(black_environment),
                &error));
        }
        REQUIRE(environment_upload->commitAndWait(&error));
        INFO(error);

        ALMetalTextureDescriptor filtered_environment_descriptor =
            environment_descriptor;
        filtered_environment_descriptor.width = 2;
        filtered_environment_descriptor.height = 2;
        filtered_environment_descriptor.mipmap_level_count = 2;
        filtered_environment_descriptor.label =
            "Alchemy PBR preview filtered test environment";
        auto filtered_environment = ALMetalTexture::create(
            *device, filtered_environment_descriptor, &error);
        INFO(error);
        REQUIRE(filtered_environment);
        auto filtered_environment_upload = device->makeCommandBuffer(
            "Alchemy PBR preview filtered environment upload", &error);
        INFO(error);
        REQUIRE(filtered_environment_upload);
        for (std::uint32_t face = 0; face < 6; ++face)
        {
            std::array<std::uint16_t, 2 * 2 * 4> mip0{};
            for (std::size_t texel = 0; texel < 4; ++texel)
            {
                // Metal cube slice 4 is +Z. The smooth lookup at this test's
                // centre must select it, rather than any blue neighbour.
                mip0[texel * 4 + (face == 4 ? 0 : 2)] = 0x3c00;
                mip0[texel * 4 + 3] = 0x3c00;
            }
            const std::array<std::uint16_t, 4> mip1{{
                0, 0x3c00, 0, 0x3c00,
            }};
            REQUIRE(filtered_environment->upload(
                *filtered_environment_upload, 0, face, {},
                mip0.data(), 2 * 4 * sizeof(std::uint16_t), &error));
            REQUIRE(filtered_environment->upload(
                *filtered_environment_upload, 1, face, {},
                mip1.data(), 4 * sizeof(std::uint16_t), &error));
        }
        REQUIRE(filtered_environment_upload->commitAndWait(&error));
        INFO(error);

        ALMetalTextureDescriptor destination_descriptor;
        destination_descriptor.format = ALMetalPixelFormat::rgba8_unorm;
        destination_descriptor.width = 32;
        destination_descriptor.height = 32;
        destination_descriptor.storage = ALMetalStorageMode::private_gpu;
        destination_descriptor.usage = ALMetalTextureUsage::shader_read;
        destination_descriptor.label = "Alchemy PBR preview test output";

        ALMetalPBRPreviewBatch batch;
        batch.vertices = vertex_buffer.get();
        batch.position_offset = position_offset;
        batch.normal_offset = normal_offset;
        batch.texcoord_offset = texcoord_offset;
        batch.color_offset = color_offset;
        batch.tangent_offset = tangent_offset;
        batch.vertex_count = 3;
        batch.indices = index_buffer.get();
        batch.index_type = ALMetalIndexType::uint16;
        batch.index_count = 3;
        batch.base_color_texture = base.get();
        batch.normal_texture = normal.get();
        batch.orm_texture = orm.get();
        batch.emissive_texture = emissive.get();
        const float identity[16] = {
            1.f, 0.f, 0.f, 0.f,
            0.f, 1.f, 0.f, 0.f,
            0.f, 0.f, 1.f, 0.f,
            0.f, 0.f, 0.f, 1.f,
        };
        std::memcpy(batch.modelview_projection, identity, sizeof(identity));
        std::memcpy(batch.modelview, identity, sizeof(identity));
        batch.modelview[14] = -2.f;
        batch.normal_matrix[0][0] = 1.f;
        batch.normal_matrix[1][1] = 1.f;
        batch.normal_matrix[2][2] = 1.f;
        batch.emissive_color[0] = 1.f;
        batch.emissive_color[1] = 1.f;
        batch.emissive_color[2] = 1.f;
        batch.sun_color[0] = 0.f;
        batch.sun_color[1] = 0.f;
        batch.sun_color[2] = 0.f;
        batch.metallic_factor = 0.f;
        batch.roughness_factor = 1.f;
        batch.alpha_cutoff = 0.f;
        batch.double_sided = true;

        ALMetalPBRPreviewScene scene;
        ALMetalPBRPreviewEnvironment environment;
        environment.radiance_texture = environment_texture.get();
        scene.batches = &batch;
        scene.batch_count = 1;
        scene.destination_descriptor = &destination_descriptor;
        scene.environment = &environment;
        scene.exposure = 1.f;
        scene.tonemap_mix = 0.f;
        scene.tonemap_type = 1;

        auto read_center = [&](const ALMetalTexture& texture)
        {
            std::array<std::uint8_t, 32 * 32 * 4> pixels{};
            REQUIRE(texture.readback(
                *device, 0, 0, {}, pixels.data(), 32 * 4, &error));
            INFO(error);
            const std::size_t center = (16 * 32 + 16) * 4;
            return std::array<std::uint8_t, 4>{{
                pixels[center], pixels[center + 1],
                pixels[center + 2], pixels[center + 3],
            }};
        };

        auto red_output = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(red_output);
        const auto red = read_center(*red_output);
        CHECK(red[0] == 255);
        CHECK(red[1] == 0);
        CHECK(red[2] == 0);
        CHECK(red[3] == 255);

        batch.texture_transform[3][4] = 0.5f;
        auto green_output = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(green_output);
        const auto green = read_center(*green_output);
        CHECK(green[0] == 0);
        CHECK(green[1] == 255);
        CHECK(green[2] == 0);
        CHECK(green[3] == 255);

        destination_descriptor.format =
            ALMetalPixelFormat::rgba8_unorm_srgb;
        auto srgb_output = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(srgb_output);
        CHECK(srgb_output->descriptor().format ==
              ALMetalPixelFormat::rgba8_unorm_srgb);
        const auto srgb_green = read_center(*srgb_output);
        CHECK(srgb_green[0] == 0);
        CHECK(srgb_green[1] == 255);
        CHECK(srgb_green[2] == 0);
        CHECK(srgb_green[3] == 255);
        destination_descriptor.format = ALMetalPixelFormat::rgba8_unorm;

        // At normal incidence with perceptual roughness 1, this is the GL
        // forward path's height-correlated GGX plus its generated 1024-sample
        // BRDF-table energy compensation, its real sun-disc widening and the
        // shared punctual scale of 3. The table's half-float quantization and
        // encoded output allow a two-byte envelope around the analytic 132.
        batch.base_color_texture = white_base.get();
        batch.emissive_texture = unlit_emissive.get();
        batch.sun_color[0] = 0.25f;
        batch.sun_color[1] = 0.25f;
        batch.sun_color[2] = 0.25f;
        auto direct_output = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(direct_output);
        const auto direct = read_center(*direct_output);
        CHECK(std::abs(static_cast<int>(direct[0]) - 132) <= 2);
        CHECK(std::abs(static_cast<int>(direct[1]) - 132) <= 2);
        CHECK(std::abs(static_cast<int>(direct[2]) - 132) <= 2);
        CHECK(direct[3] == 255);
        batch.base_color_texture = base.get();
        batch.emissive_texture = emissive.get();
        batch.sun_color[0] = 0.f;
        batch.sun_color[1] = 0.f;
        batch.sun_color[2] = 0.f;

        // A coherent environment carries the cube's face orientation and
        // roughness-filtered mip chain. The centre reflection points at +Z:
        // smooth metal reads red from slice 4/mip 0, while rough metal reads
        // the green final mip shared by every face.
        environment.radiance_texture = filtered_environment.get();
        environment.max_lod = 1.f;
        batch.base_color_texture = white_base.get();
        batch.emissive_texture = unlit_emissive.get();
        batch.orm_texture = glossy_metal.get();
        batch.metallic_factor = 1.f;
        auto smooth_environment_output = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(smooth_environment_output);
        const auto smooth_environment = read_center(
            *smooth_environment_output);
        CHECK(smooth_environment[0] > 200);
        CHECK(smooth_environment[1] < 4);
        CHECK(smooth_environment[2] < 4);

        batch.orm_texture = rough_metal.get();
        auto rough_environment_output = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(rough_environment_output);
        const auto rough_environment = read_center(*rough_environment_output);
        CHECK(rough_environment[0] < 4);
        CHECK(rough_environment[1] > 60);
        CHECK(rough_environment[2] < 4);

        // The packed SH row is consumed in the same coefficient order as
        // reflectionProbeF.glsl. A green unit L0 coefficient therefore adds
        // diffuse green while a black radiance cube contributes no specular.
        environment.radiance_texture = environment_texture.get();
        environment.max_lod = 0.f;
        environment.sh_coefficients[0][0] = 0x3c000000u;
        batch.metallic_factor = 0.f;
        auto sh_environment_output = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(sh_environment_output);
        const auto sh_environment = read_center(*sh_environment_output);
        CHECK(sh_environment[0] < 4);
        CHECK(sh_environment[1] > 100);
        CHECK(sh_environment[2] < 4);

        environment.sh_coefficients[0][0] = 0;
        batch.base_color_texture = base.get();
        batch.emissive_texture = emissive.get();
        batch.orm_texture = orm.get();
        batch.metallic_factor = 0.f;

        // colorCorrect's lateral chromatic aberration samples R and B away
        // from the centre tap while leaving G and coverage at the centre. Feed
        // it a spatial step at one quarter of the frame (away from the clean
        // optical centre), and prove both displaced channels change while the
        // centre channels remain bit-identical.
        std::array<std::uint8_t, 64 * 4> chromatic_emissive_bytes{};
        for (std::size_t texel = 0; texel < 64; ++texel)
        {
            const bool left = texel < 16;
            chromatic_emissive_bytes[texel * 4 + 0] = left ? 0 : 255;
            chromatic_emissive_bytes[texel * 4 + 1] = 32;
            chromatic_emissive_bytes[texel * 4 + 2] = left ? 255 : 0;
            chromatic_emissive_bytes[texel * 4 + 3] = 255;
        }
        auto chromatic_emissive = make_texture(
            ALMetalPixelFormat::rgba8_unorm_srgb, 64,
            chromatic_emissive_bytes.data(), 64 * 4,
            "Alchemy PBR preview chromatic-aberration test emissive");
        const float screen_texcoords[3][2] = {
            {0.f, 0.5f}, {2.f, 0.5f}, {0.f, 0.5f},
        };
        REQUIRE(vertex_buffer->write(
            texcoord_offset, screen_texcoords, sizeof(screen_texcoords),
            &error));
        batch.texture_transform[3][4] = 0.f;
        batch.emissive_texture = chromatic_emissive.get();
        auto chromatic_baseline = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(chromatic_baseline);
        scene.chromatic_aberration_strength = 1.f;
        scene.chromatic_aberration_falloff = 1.f;
        scene.chromatic_aberration_angle = 0.f;
        auto chromatic_output = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(chromatic_output);
        std::array<std::uint8_t, 32 * 32 * 4> baseline_pixels{};
        std::array<std::uint8_t, 32 * 32 * 4> chromatic_pixels{};
        REQUIRE(chromatic_baseline->readback(
            *device, 0, 0, {}, baseline_pixels.data(), 32 * 4, &error));
        REQUIRE(chromatic_output->readback(
            *device, 0, 0, {}, chromatic_pixels.data(), 32 * 4, &error));
        int red_delta = 0;
        int blue_delta = 0;
        bool green_unchanged = true;
        bool alpha_unchanged = true;
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            red_delta = std::max(
                red_delta,
                std::abs(static_cast<int>(chromatic_pixels[pixel * 4]) -
                         static_cast<int>(baseline_pixels[pixel * 4])));
            blue_delta = std::max(
                blue_delta,
                std::abs(static_cast<int>(chromatic_pixels[pixel * 4 + 2]) -
                         static_cast<int>(baseline_pixels[pixel * 4 + 2])));
            green_unchanged = green_unchanged &&
                chromatic_pixels[pixel * 4 + 1] ==
                    baseline_pixels[pixel * 4 + 1];
            alpha_unchanged = alpha_unchanged &&
                chromatic_pixels[pixel * 4 + 3] ==
                    baseline_pixels[pixel * 4 + 3];
        }
        CHECK(red_delta > 8);
        CHECK(blue_delta > 8);
        CHECK(green_unchanged);
        CHECK(alpha_unchanged);
        scene.chromatic_aberration_strength = 0.f;
        batch.emissive_texture = emissive.get();
        REQUIRE(vertex_buffer->write(
            texcoord_offset, texcoords, sizeof(texcoords), &error));

        // The GL owner alpha-composites linear HDR first, then applies the
        // full-frame post pass. Half-covered unit red therefore encodes 0.5
        // linear (~188), rather than blending an encoded 255 down to 128.
        batch.texture_transform[3][4] = 0.f;
        batch.base_color_texture = cutout_base.get();
        batch.alpha_cutoff = 0.f;
        auto blended_output = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(blended_output);
        const auto blended = read_center(*blended_output);
        CHECK(std::abs(static_cast<int>(blended[0]) - 188) <= 1);
        CHECK(blended[1] == 0);
        CHECK(blended[2] == 0);
        CHECK(std::abs(static_cast<int>(blended[3]) - 128) <= 1);

        // The preview asks generateExposure for an unadapted one-frame value.
        // Pinning min/max to EV 1 makes its dynamic scale exactly 0.5.
        batch.base_color_texture = base.get();
        scene.meter_exposure = true;
        scene.exposure_min_ev = 1.f;
        scene.exposure_max_ev = 1.f;
        auto exposed_output = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(exposed_output);
        const auto exposed = read_center(*exposed_output);
        CHECK(std::abs(static_cast<int>(exposed[0]) - 188) <= 1);
        CHECK(exposed[1] == 0);
        CHECK(exposed[2] == 0);
        CHECK(exposed[3] == 255);

        // With a full target of unit red, the meter's exact luminance is
        // 0.2126. Placing that at the 0.18 key produces scale 0.18/0.2126.
        scene.exposure_min_ev = -3.f;
        scene.exposure_max_ev = 4.f;
        auto metered_output = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(metered_output);
        const auto metered = read_center(*metered_output);
        const float expected_linear = 0.18f / 0.2126f;
        const float expected_encoded =
            1.055f * std::pow(expected_linear, 1.f / 2.4f) - 0.055f;
        const int expected_byte = static_cast<int>(
            std::lround(expected_encoded * 255.f));
        CHECK(std::abs(static_cast<int>(metered[0]) - expected_byte) <= 1);
        CHECK(metered[1] == 0);
        CHECK(metered[2] == 0);
        CHECK(metered[3] == 255);
        scene.meter_exposure = false;

        // A uniform 0.25-red HDR target with a threshold above the scene and
        // alpha-glow boost 0.5 extracts 0.25 at every level. Three pyramid
        // levels add back to 0.75, bringing the post input to unit red.
        batch.emissive_color[0] = 0.25f;
        auto quarter_red_output = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(quarter_red_output);
        const auto quarter_red = read_center(*quarter_red_output);
        CHECK(std::abs(static_cast<int>(quarter_red[0]) - 137) <= 1);
        scene.bloom_enabled = true;
        scene.bloom_mip_count = 3;
        scene.bloom_threshold = 100.f;
        scene.bloom_knee = 0.f;
        scene.bloom_alpha_glow_boost = 0.5f;
        scene.bloom_strength = 1.f;
        scene.bloom_scatter = 1.f;
        auto bloomed_output = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(bloomed_output);
        const auto bloomed = read_center(*bloomed_output);
        CHECK(bloomed[0] == 255);
        CHECK(bloomed[1] == 0);
        CHECK(bloomed[2] == 0);
        CHECK(bloomed[3] == 255);

        // A uniform field remains uniform through every normalized four-tap
        // streak pass. Four arms therefore sum four copies of the 0.25 bloom
        // extract; the final composite scales both the pyramid and streaks by
        // bloom strength, matching colorCorrectF.glsl.
        scene.bloom_strength = 0.25f;
        auto quarter_bloom_output = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(quarter_bloom_output);
        const auto quarter_bloom = read_center(*quarter_bloom_output);
        CHECK(std::abs(static_cast<int>(quarter_bloom[0]) - 177) <= 2);
        scene.cross_filter_enabled = true;
        scene.cross_filter_strength = 1.f;
        scene.cross_filter_points = 4;
        scene.cross_filter_angle = 13.f;
        scene.cross_filter_length = 1.f;
        scene.cross_filter_falloff = 1.5f;
        scene.cross_filter_chromatic = 1.f;
        auto streaked_output = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(streaked_output);
        const auto streaked = read_center(*streaked_output);
        CHECK(std::abs(static_cast<int>(streaked[0]) - 216) <= 2);
        CHECK(streaked[1] == 0);
        CHECK(streaked[2] == 0);
        CHECK(streaked[3] == 255);
        scene.cross_filter_enabled = false;
        scene.cross_filter_strength = 0.f;

        // Halation travels independently in alpha and is tinted only at the
        // pre-exposure composite. A 0.05 uniform excess sums to 0.15 here.
        scene.bloom_strength = 0.f;
        scene.bloom_halation = true;
        scene.bloom_halation_strength = 1.f;
        scene.bloom_threshold = 0.2f;
        scene.bloom_halation_tint[0] = 0.f;
        scene.bloom_halation_tint[1] = 1.f;
        scene.bloom_halation_tint[2] = 0.f;
        scene.bloom_halation_weights[0] = 1.f;
        scene.bloom_halation_weights[1] = 0.f;
        scene.bloom_halation_weights[2] = 0.f;
        auto halation_output = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(halation_output);
        const auto halation = read_center(*halation_output);
        CHECK(std::abs(static_cast<int>(halation[0]) - 137) <= 1);
        CHECK(std::abs(static_cast<int>(halation[1]) - 108) <= 2);
        CHECK(halation[2] == 0);
        CHECK(halation[3] == 255);
        batch.emissive_color[0] = 1.f;
        scene.bloom_enabled = false;
        scene.bloom_strength = 0.325f;
        scene.bloom_halation = false;
        scene.bloom_halation_strength = 0.f;

        batch.base_color_texture = cutout_base.get();
        batch.alpha_cutoff = 0.75f;
        auto cutout_output = renderer->render(scene, &error);
        INFO(error);
        REQUIRE(cutout_output);
        const auto cutout = read_center(*cutout_output);
        CHECK(cutout[0] == 0);
        CHECK(cutout[1] == 0);
        CHECK(cutout[2] == 0);
        CHECK(cutout[3] == 0);

        batch.base_color_texture = base.get();
        batch.alpha_cutoff = 0.f;
        scene.tonemap_mix = 1.f;
        for (std::uint32_t type = 2; type <= 6; ++type)
        {
            scene.tonemap_type = type;
            std::fill(std::begin(scene.tonemap_params),
                      std::end(scene.tonemap_params), 0.f);
            if (type == 2 || type == 3 || type == 4)
            {
                scene.tonemap_params[0] = 1.f;
            }
            else if (type == 6)
            {
                std::fill(std::begin(scene.tonemap_params),
                          std::end(scene.tonemap_params), 1.f);
            }
            auto mapped_output = renderer->render(scene, &error);
            INFO(error);
            CAPTURE(type);
            REQUIRE(mapped_output);
            CHECK(read_center(*mapped_output)[3] == 255);
        }

        scene.tonemap_type = 6;
        std::fill(std::begin(scene.tonemap_params),
                  std::end(scene.tonemap_params), 0.f);
        error.clear();
        CHECK_FALSE(renderer->render(scene, &error));
        CHECK(error == "Metal PBR preview post state is invalid");
        scene.tonemap_type = 7;
        error.clear();
        CHECK_FALSE(renderer->render(scene, &error));
        CHECK(error == "Metal PBR preview post state is invalid");
        scene.tonemap_type = 1;
        scene.tonemap_mix = 0.f;
        scene.bloom_mip_count = 2;
        error.clear();
        CHECK_FALSE(renderer->render(scene, &error));
        CHECK(error == "Metal PBR preview post state is invalid");
        scene.bloom_mip_count = 3;
        scene.cross_filter_points = 1;
        error.clear();
        CHECK_FALSE(renderer->render(scene, &error));
        CHECK(error == "Metal PBR preview post state is invalid");
        scene.cross_filter_points = 4;
        scene.chromatic_aberration_falloff = 0.25f;
        error.clear();
        CHECK_FALSE(renderer->render(scene, &error));
        CHECK(error == "Metal PBR preview post state is invalid");
        scene.chromatic_aberration_falloff = 1.f;
        scene.environment = nullptr;
        error.clear();
        CHECK_FALSE(renderer->render(scene, &error));
        CHECK(error == "Metal PBR preview scene is incomplete");
        scene.environment = &environment;
        environment.radiance_texture = nullptr;
        error.clear();
        CHECK_FALSE(renderer->render(scene, &error));
        CHECK(error == "Metal PBR preview environment is invalid");
        environment.radiance_texture = environment_texture.get();
        batch.normal_texture = nullptr;
        error.clear();
        CHECK_FALSE(renderer->render(scene, &error));
        CHECK(error == "Metal PBR preview batch is invalid");
        batch.normal_texture = normal.get();
        batch.tangent_offset += sizeof(float);
        error.clear();
        CHECK_FALSE(renderer->render(scene, &error));
        CHECK(error == "Metal PBR preview batch is invalid");
    }
}

TEST_CASE("almetal: production UI renderer consumes the viewer SoA layout", "[almetal]")
{
    @autoreleasepool
    {
        static_assert(sizeof(ALMetalUIMatrices) == 368);

        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        auto scheduler = ALMetalFrameScheduler::create(*device, 3, &error);
        INFO(error);
        REQUIRE(scheduler);
        auto renderer = ALMetalUIRenderer::create(*device, *scheduler, &error);
        INFO(error);
        REQUIRE(renderer);

        // Exactly LLVertexBuffer's production structure-of-arrays layout:
        // float4 positions, then float2 texcoords, then byte colors.
        constexpr std::size_t position_offset = 0;
        constexpr std::size_t texcoord_offset = sizeof(float) * 4 * 3;
        constexpr std::size_t color_offset = texcoord_offset + sizeof(float) * 2 * 3;
        std::array<std::uint8_t, color_offset + 4 * 3> bytes{};
        const float positions[3][4] = {
            {-0.8f, -0.8f, 0.f, 1.f},
            { 0.8f, -0.8f, 0.f, 1.f},
            { 0.0f,  0.8f, 0.f, 1.f},
        };
        const float texcoords[3][2] = {{0.f, 0.f}, {0.f, 0.f}, {0.f, 0.f}};
        const std::uint8_t colors[3][4] = {
            {255, 32, 16, 255}, {255, 32, 16, 255}, {255, 32, 16, 255},
        };
        std::memcpy(bytes.data() + position_offset, positions, sizeof(positions));
        std::memcpy(bytes.data() + texcoord_offset, texcoords, sizeof(texcoords));
        std::memcpy(bytes.data() + color_offset, colors, sizeof(colors));

        ALMetalBufferDescriptor buffer_descriptor;
        buffer_descriptor.length = bytes.size();
        buffer_descriptor.storage = ALMetalStorageMode::shared;
        buffer_descriptor.label = "Alchemy production UI test SoA";
        auto buffer = ALMetalBuffer::create(*device, buffer_descriptor, &error);
        INFO(error);
        REQUIRE(buffer);
        REQUIRE(buffer->write(0, bytes.data(), bytes.size(), &error));

        ALMetalTextureDescriptor texture_descriptor;
        texture_descriptor.format = ALMetalPixelFormat::rgba8_unorm;
        texture_descriptor.width = 1;
        texture_descriptor.height = 1;
        texture_descriptor.mipmap_level_count = 1;
        texture_descriptor.storage = ALMetalStorageMode::private_gpu;
        texture_descriptor.usage = ALMetalTextureUsage::shader_read;
        texture_descriptor.label = "Alchemy production UI test white";
        auto texture = ALMetalTexture::create(*device, texture_descriptor, &error);
        INFO(error);
        REQUIRE(texture);
        const std::array<std::uint8_t, 4> white = {255, 255, 255, 255};
        auto upload = device->makeCommandBuffer("Alchemy production UI test upload", &error);
        REQUIRE(upload);
        REQUIRE(texture->upload(*upload, 0, 0, {}, white.data(), 4, &error));
        REQUIRE(upload->commitAndWait(&error));
        INFO(error);

        ALMetalUIBatch batch;
        batch.vertices = buffer.get();
        batch.position_offset = position_offset;
        batch.texcoord_offset = texcoord_offset;
        batch.color_offset = color_offset;
        batch.texture = texture.get();
        batch.sampler.min_filter = ALMetalSamplerFilter::nearest;
        batch.sampler.mag_filter = ALMetalSamplerFilter::nearest;
        batch.sampler.mip_filter = ALMetalSamplerMipFilter::none;
        batch.sampler.address_s = ALMetalSamplerAddressMode::clamp_to_edge;
        batch.sampler.address_t = ALMetalSamplerAddressMode::clamp_to_edge;
        batch.sampler.address_r = ALMetalSamplerAddressMode::clamp_to_edge;
        batch.blend.enabled = false;
        batch.viewport = {0.0, 0.0, 32.0, 32.0, 0.0, 1.0};
        batch.scissor = {0, 0, 32, 32};
        batch.target_width = 32;
        batch.target_height = 32;
        batch.vertex_count = 3;
        for (int i = 0; i < 4; ++i)
        {
            batch.matrices.modelview[i * 4 + i] = 1.f;
            batch.matrices.projection[i * 4 + i] = 1.f;
            batch.matrices.modelview_projection[i * 4 + i] = 1.f;
            batch.matrices.inverse_projection[i * 4 + i] = 1.f;
            batch.matrices.texture0[i * 4 + i] = 1.f;
        }

        REQUIRE(renderer->draw(batch, &error));
        INFO(error);
        REQUIRE(renderer->hasOpenFrame());
        REQUIRE(renderer->endFrame(&error));
        INFO(error);
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);

        const ALMetalTexture* output = renderer->outputTexture();
        REQUIRE(output);
        std::array<std::uint8_t, 32 * 32 * 4> pixels{};
        REQUIRE(output->readback(*device, 0, 0, {}, pixels.data(), 32 * 4, &error));
        INFO(error);
        const std::size_t center = (16 * 32 + 16) * 4;
        CHECK(pixels[center + 0] == 16);  // BGRA target
        CHECK(pixels[center + 1] == 32);
        CHECK(pixels[center + 2] == 255);
        CHECK(pixels[center + 3] == 255);
        CHECK(pixels[0] == 0);
        CHECK(pixels[1] == 0);
        CHECK(pixels[2] == 0);
        CHECK(pixels[3] == 0);

        // Offscreen UI flips vertex Y so its output retains GL's lower-left
        // row convention. A GL top-half clip therefore follows that geometry
        // into the texture's lower half; converting the scissor a second time
        // would reject the entire top/bottom viewer chrome while a full-height
        // side toolbar continued to render.
        const float top_positions[3][4] = {
            {-0.8f, 0.2f, 0.f, 1.f},
            { 0.8f, 0.2f, 0.f, 1.f},
            { 0.0f, 0.8f, 0.f, 1.f},
        };
        REQUIRE(buffer->write(
            position_offset, top_positions, sizeof(top_positions), &error));
        auto clipped_renderer = ALMetalUIRenderer::create(
            *device, *scheduler, &error);
        INFO(error);
        REQUIRE(clipped_renderer);
        batch.scissor = {0, 16, 32, 16};
        REQUIRE(clipped_renderer->draw(batch, &error));
        REQUIRE(clipped_renderer->endFrame(&error));
        INFO(error);
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);
        pixels.fill(0);
        REQUIRE(clipped_renderer->outputTexture()->readback(
            *device, 0, 0, {}, pixels.data(), 32 * 4, &error));
        INFO(error);
        const std::size_t clipped_center = (24 * 32 + 16) * 4;
        CHECK(pixels[clipped_center + 0] == 16);
        CHECK(pixels[clipped_center + 1] == 32);
        CHECK(pixels[clipped_center + 2] == 255);
        CHECK(pixels[clipped_center + 3] == 255);
        const std::size_t rejected_half = (8 * 32 + 16) * 4;
        CHECK(pixels[rejected_half + 0] == 0);
        CHECK(pixels[rejected_half + 1] == 0);
        CHECK(pixels[rejected_half + 2] == 0);
        CHECK(pixels[rejected_half + 3] == 0);
        REQUIRE(buffer->write(
            position_offset, positions, sizeof(positions), &error));
        batch.scissor = {0, 0, 32, 32};

        // An explicitly unbound GL UI texture samples the engine's opaque
        // white placeholder. The native equivalent needs no sampled resource:
        // it emits the streamed vertex colour exactly, which is the common
        // property/parcel-line and untextured 3D-UI contract.
        auto vertex_color_renderer = ALMetalUIRenderer::create(
            *device, *scheduler, &error);
        INFO(error);
        REQUIRE(vertex_color_renderer);
        batch.shader = ALMetalUIShader::vertex_color;
        batch.texture = nullptr;
        REQUIRE(vertex_color_renderer->draw(batch, &error));
        REQUIRE(vertex_color_renderer->endFrame(&error));
        INFO(error);
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);
        pixels.fill(0);
        REQUIRE(vertex_color_renderer->outputTexture()->readback(
            *device, 0, 0, {}, pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(pixels[center + 0] == 16);  // BGRA target
        CHECK(pixels[center + 1] == 32);
        CHECK(pixels[center + 2] == 255);
        CHECK(pixels[center + 3] == 255);

        // interface/debugF.glsl uses the current diffuse-color uniform and
        // ignores both a sampled texture and streamed vertex colour. This is
        // the immediate-mode contract used by rotation manipulators and
        // position-only diagnostic overlays in the ordered world/UI pass.
        auto uniform_color_renderer = ALMetalUIRenderer::create(
            *device, *scheduler, &error);
        INFO(error);
        REQUIRE(uniform_color_renderer);
        ALMetalBufferDescriptor position_only_descriptor;
        position_only_descriptor.length = sizeof(positions);
        position_only_descriptor.storage = ALMetalStorageMode::shared;
        position_only_descriptor.label =
            "Alchemy production position-only debug UI test";
        auto position_only_buffer = ALMetalBuffer::create(
            *device, position_only_descriptor, &error);
        INFO(error);
        REQUIRE(position_only_buffer);
        REQUIRE(position_only_buffer->write(
            0, positions, sizeof(positions), &error));
        constexpr std::array<std::uint16_t, 3> debug_indices{0, 1, 2};
        ALMetalBufferDescriptor debug_index_descriptor;
        debug_index_descriptor.length = sizeof(debug_indices);
        debug_index_descriptor.storage = ALMetalStorageMode::shared;
        debug_index_descriptor.label =
            "Alchemy production indexed debug UI test";
        auto debug_index_buffer = ALMetalBuffer::create(
            *device, debug_index_descriptor, &error);
        INFO(error);
        REQUIRE(debug_index_buffer);
        REQUIRE(debug_index_buffer->write(
            0, debug_indices.data(), sizeof(debug_indices), &error));
        batch.shader = ALMetalUIShader::uniform_color;
        batch.vertices = position_only_buffer.get();
        batch.texcoord_offset = position_only_buffer->length();
        batch.color_offset = position_only_buffer->length();
        batch.indices = debug_index_buffer.get();
        batch.index_type = ALMetalIndexType::uint16;
        batch.index_count = static_cast<std::uint32_t>(debug_indices.size());
        batch.cull_mode = ALMetalCullMode::back;
        batch.texture = nullptr;
        batch.solid_color[0] = 1.f;
        batch.solid_color[1] = 0.5f;
        batch.solid_color[2] = 0.25f;
        batch.solid_color[3] = 1.f;
        REQUIRE(uniform_color_renderer->draw(batch, &error));
        REQUIRE(uniform_color_renderer->endFrame(&error));
        INFO(error);
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);
        pixels.fill(0);
        REQUIRE(uniform_color_renderer->outputTexture()->readback(
            *device, 0, 0, {}, pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(pixels[center + 0]) - 64) <= 1);
        CHECK(std::abs(static_cast<int>(pixels[center + 1]) - 128) <= 1);
        CHECK(pixels[center + 2] == 255);
        CHECK(pixels[center + 3] == 255);
        batch.shader = ALMetalUIShader::textured;
        batch.vertices = buffer.get();
        batch.texcoord_offset = texcoord_offset;
        batch.color_offset = color_offset;
        batch.indices = nullptr;
        batch.index_count = 0;
        batch.cull_mode = ALMetalCullMode::none;
        batch.texture = texture.get();

        const ALMetalUIRendererStats stats = renderer->stats();
        CHECK(stats.frames == 1);
        CHECK(stats.batches == 1);
        CHECK(stats.vertices == 3);
        CHECK(stats.pipeline_states == 1);
        CHECK(stats.sampler_states == 1);

        // The future world transaction must seed this same encoder with its
        // completed BGRA backing before ordinary UI draws. Prove the one-shot
        // background both without UI and under source-over UI composition.
        ALMetalTextureDescriptor background_descriptor;
        background_descriptor.format = ALMetalPixelFormat::bgra8_unorm;
        background_descriptor.width = 32;
        background_descriptor.height = 32;
        background_descriptor.storage = ALMetalStorageMode::private_gpu;
        background_descriptor.usage = ALMetalTextureUsage::shader_read;
        background_descriptor.label =
            "Alchemy native world/UI composition background";
        auto background = ALMetalTexture::create(
            *device, background_descriptor, &error);
        INFO(error);
        REQUIRE(background);
        std::array<std::uint8_t, 32 * 32 * 4> background_pixels{};
        for (std::size_t pixel = 0; pixel < 32 * 32; ++pixel)
        {
            background_pixels[pixel * 4 + 0] = 20u;
            background_pixels[pixel * 4 + 1] = 40u;
            background_pixels[pixel * 4 + 2] = 80u;
            background_pixels[pixel * 4 + 3] = 255u;
        }
        auto background_upload = device->makeCommandBuffer(
            "Alchemy native world/UI background upload", &error);
        INFO(error);
        REQUIRE(background_upload);
        REQUIRE(background->upload(
            *background_upload, 0, 0, {}, background_pixels.data(),
            32 * 4, &error));
        REQUIRE(background_upload->commitAndWait(&error));
        INFO(error);

        auto composition_renderer = ALMetalUIRenderer::create(
            *device, *scheduler, &error);
        INFO(error);
        REQUIRE(composition_renderer);
        REQUIRE(composition_renderer->setFrameBackground(
            background.get(), &error));
        REQUIRE(composition_renderer->endFrame(&error));
        INFO(error);
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);
        const ALMetalTexture* composed =
            composition_renderer->outputTexture();
        REQUIRE(composed);
        std::array<std::uint8_t, 32 * 32 * 4> composed_pixels{};
        REQUIRE(composed->readback(
            *device, 0, 0, {}, composed_pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(composed_pixels == background_pixels);
        const ALMetalUIRendererStats backing_stats =
            composition_renderer->stats();
        CHECK(backing_stats.frames == 1);
        CHECK(backing_stats.batches == 0);
        CHECK(backing_stats.vertices == 0);

        // DebugShowColor samples after ordinary HUD/interface draws but
        // before the debug-text overlay. Snapshot the center between two
        // opaque draws, then prove the retained 1x1 copy contains the first
        // draw while the resumed final target contains the second.
        REQUIRE(buffer->write(
            color_offset, colors, sizeof(colors), &error));
        batch.blend.enabled = false;
        REQUIRE(composition_renderer->setFrameBackground(
            background.get(), &error));
        REQUIRE(composition_renderer->draw(batch, &error));
        auto ordered_pixel =
            composition_renderer->copyFrameColorPixel(16, 16, &error);
        INFO(error);
        REQUIRE(ordered_pixel);
        const std::uint8_t later_colors[3][4] = {
            {8, 224, 40, 255}, {8, 224, 40, 255},
            {8, 224, 40, 255},
        };
        auto later_bytes = bytes;
        std::memcpy(
            later_bytes.data() + color_offset,
            later_colors, sizeof(later_colors));
        auto later_buffer = ALMetalBuffer::create(
            *device, buffer_descriptor, &error);
        INFO(error);
        REQUIRE(later_buffer);
        REQUIRE(later_buffer->write(
            0, later_bytes.data(), later_bytes.size(), &error));
        batch.vertices = later_buffer.get();
        REQUIRE(composition_renderer->draw(batch, &error));
        REQUIRE(composition_renderer->endFrame(&error));
        INFO(error);
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);
        std::array<std::uint8_t, 4> ordered_pixel_bytes{};
        REQUIRE(ordered_pixel->readback(
            *device, 0, 0, {}, ordered_pixel_bytes.data(), 4, &error));
        INFO(error);
        CHECK(ordered_pixel_bytes[0] == 16u);
        CHECK(ordered_pixel_bytes[1] == 32u);
        CHECK(ordered_pixel_bytes[2] == 255u);
        CHECK(ordered_pixel_bytes[3] == 255u);
        REQUIRE(composition_renderer->outputTexture()->readback(
            *device, 0, 0, {}, composed_pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(composed_pixels[center + 0] == 40u);
        CHECK(composed_pixels[center + 1] == 224u);
        CHECK(composed_pixels[center + 2] == 8u);
        CHECK(composed_pixels[center + 3] == 255u);
        batch.vertices = buffer.get();

        error.clear();
        CHECK_FALSE(composition_renderer->setFrameBackground(
            composition_renderer->outputTexture(), &error));
        CHECK(error ==
              "Metal UI frame background cannot alias its destination");
        error.clear();
        CHECK_FALSE(composition_renderer->setFrameBackground(
            texture.get(), &error));
        CHECK(error == "Metal UI frame background is incompatible");

        const std::uint8_t translucent_colors[3][4] = {
            {255, 32, 16, 128}, {255, 32, 16, 128},
            {255, 32, 16, 128},
        };
        REQUIRE(buffer->write(
            color_offset, translucent_colors,
            sizeof(translucent_colors), &error));
        batch.blend.enabled = true;
        batch.blend.source_rgb = ALMetalBlendFactor::source_alpha;
        batch.blend.destination_rgb =
            ALMetalBlendFactor::one_minus_source_alpha;
        batch.blend.source_alpha = ALMetalBlendFactor::one;
        batch.blend.destination_alpha =
            ALMetalBlendFactor::one_minus_source_alpha;
        // RLVa @setoverlay reaches this exact gUIProgram batch contract: its
        // texture uses AnisoWrap while tweened tint and alpha arrive in the
        // streamed color. Prove that sampler survives the retained-world
        // composition path rather than requiring the old unconditional GL
        // transaction rejection.
        batch.sampler.address_s = ALMetalSamplerAddressMode::repeat;
        batch.sampler.address_t = ALMetalSamplerAddressMode::repeat;
        batch.sampler.address_r = ALMetalSamplerAddressMode::repeat;
        batch.sampler.max_anisotropy = 16;
        REQUIRE(composition_renderer->setFrameBackground(
            background.get(), &error));
        REQUIRE(composition_renderer->draw(batch, &error));
        REQUIRE(composition_renderer->endFrame(&error));
        INFO(error);
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);
        composed = composition_renderer->outputTexture();
        REQUIRE(composed);
        REQUIRE(composed->readback(
            *device, 0, 0, {}, composed_pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(composed_pixels[center + 0]) - 18) <= 1);
        CHECK(std::abs(static_cast<int>(composed_pixels[center + 1]) - 36) <= 1);
        CHECK(std::abs(static_cast<int>(composed_pixels[center + 2]) - 168) <= 1);
        CHECK(composed_pixels[center + 3] == 255u);
        CHECK(composed_pixels[0] == 20u);
        CHECK(composed_pixels[1] == 40u);
        CHECK(composed_pixels[2] == 80u);
        CHECK(composed_pixels[3] == 255u);
        batch.sampler.address_s = ALMetalSamplerAddressMode::clamp_to_edge;
        batch.sampler.address_t = ALMetalSamplerAddressMode::clamp_to_edge;
        batch.sampler.address_r = ALMetalSamplerAddressMode::clamp_to_edge;
        batch.sampler.max_anisotropy = 1;

        // Background selection is consumed by one submitted frame. A later
        // UI-only frame clears outside the triangle instead of retaining a
        // stale world image, and selection cannot change after encoding starts.
        REQUIRE(buffer->write(
            color_offset, colors, sizeof(colors), &error));
        batch.blend.enabled = false;
        REQUIRE(composition_renderer->draw(batch, &error));
        error.clear();
        CHECK_FALSE(composition_renderer->setFrameBackground(nullptr, &error));
        CHECK(error ==
              "Metal UI frame background must be selected before drawing");
        REQUIRE(composition_renderer->endFrame(&error));
        INFO(error);
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        composed = composition_renderer->outputTexture();
        REQUIRE(composed);
        REQUIRE(composed->readback(
            *device, 0, 0, {}, composed_pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(composed_pixels[0] == 0u);
        CHECK(composed_pixels[1] == 0u);
        CHECK(composed_pixels[2] == 0u);
        CHECK(composed_pixels[3] == 0u);

        // Retained world depth joins the same offscreen transaction before
        // depth-tested HUD/world UI. Seed a combined depth/stencil target at
        // 0.5, then prove forward and reverse comparisons against its GPU
        // copy while the completed BGRA world backing remains underneath.
        ALMetalRenderTargetDescriptor depth_source_descriptor;
        depth_source_descriptor.width = 32;
        depth_source_descriptor.height = 32;
        depth_source_descriptor.color_attachment_count = 0;
        depth_source_descriptor.depth_stencil_format =
            ALMetalPixelFormat::depth32_float_stencil8;
        depth_source_descriptor.depth_stencil_shader_read = true;
        depth_source_descriptor.label =
            "Alchemy native world/UI retained depth source";
        auto depth_source = ALMetalRenderTarget::create(
            *device, depth_source_descriptor, &error);
        INFO(error);
        REQUIRE(depth_source);
        ALMetalRenderPassConfig depth_seed_config;
        depth_seed_config.depth_load = ALMetalLoadAction::clear;
        depth_seed_config.depth_store = ALMetalStoreAction::store;
        depth_seed_config.clear_depth = 0.5;
        depth_seed_config.stencil_load = ALMetalLoadAction::clear;
        depth_seed_config.stencil_store = ALMetalStoreAction::store;
        auto depth_seed_pass = depth_source->makeRenderPass(
            depth_seed_config, &error);
        INFO(error);
        REQUIRE(depth_seed_pass);
        auto depth_seed_command = device->makeCommandBuffer(
            "Alchemy native world/UI retained depth seed", &error);
        INFO(error);
        REQUIRE(depth_seed_command);
        auto depth_seed_encoder = ALMetalRenderEncoder::begin(
            *depth_seed_command, *depth_seed_pass,
            "Alchemy native world/UI retained depth seed", &error);
        INFO(error);
        REQUIRE(depth_seed_encoder);
        REQUIRE(depth_seed_encoder->end(&error));
        REQUIRE(depth_seed_command->commitAndWait(&error));
        INFO(error);

        auto depth_renderer = ALMetalUIRenderer::create(
            *device, *scheduler, &error);
        INFO(error);
        REQUIRE(depth_renderer);
        error.clear();
        CHECK_FALSE(depth_renderer->setFrameDepth(texture.get(), &error));
        CHECK(error == "Metal UI frame depth is incompatible");
        error.clear();

        ALMetalRenderTargetDescriptor short_depth_descriptor =
            depth_source_descriptor;
        short_depth_descriptor.width = 16;
        short_depth_descriptor.height = 16;
        short_depth_descriptor.label =
            "Alchemy mismatched native world/UI depth";
        auto short_depth = ALMetalRenderTarget::create(
            *device, short_depth_descriptor, &error);
        INFO(error);
        REQUIRE(short_depth);
        REQUIRE(depth_renderer->setFrameDepth(
            short_depth->depthStencilTexture(), &error));
        error.clear();
        CHECK_FALSE(depth_renderer->draw(batch, &error));
        CHECK(error ==
              "Metal UI frame depth dimensions do not match the target");
        error.clear();
        REQUIRE(depth_renderer->setFrameDepth(nullptr, &error));
        REQUIRE(depth_renderer->setFrameDepth(
            depth_source->depthStencilTexture(), &error));
        REQUIRE(depth_renderer->endFrame(&error));
        CHECK(depth_renderer->stats().frames == 0);
        CHECK(depth_renderer->outputTexture() == nullptr);

        auto draw_with_depth = [&](float z,
                                   ALMetalCompareFunction compare,
                                   bool reverse_z,
                                   bool expect_ui)
        {
            float depth_positions[3][4];
            std::memcpy(depth_positions, positions, sizeof(depth_positions));
            for (auto& position : depth_positions)
            {
                position[2] = z;
            }
            REQUIRE(buffer->write(
                position_offset, depth_positions,
                sizeof(depth_positions), &error));
            batch.depth.enabled = true;
            batch.depth.write_enabled = false;
            batch.depth.reverse_z = reverse_z;
            batch.depth.compare = compare;
            REQUIRE(depth_renderer->setFrameBackground(
                background.get(), &error));
            REQUIRE(depth_renderer->setFrameDepth(
                depth_source->depthStencilTexture(), &error));
            REQUIRE(depth_renderer->draw(batch, &error));
            error.clear();
            CHECK_FALSE(depth_renderer->setFrameDepth(nullptr, &error));
            CHECK(error ==
                  "Metal UI frame depth must be selected before drawing");
            REQUIRE(depth_renderer->endFrame(&error));
            INFO(error);
            REQUIRE(scheduler->waitUntilIdle(1000, &error));
            INFO(error);
            const ALMetalTexture* depth_composed =
                depth_renderer->outputTexture();
            REQUIRE(depth_composed);
            REQUIRE(depth_renderer->outputDepthTexture());
            REQUIRE(depth_composed->readback(
                *device, 0, 0, {}, composed_pixels.data(),
                32 * 4, &error));
            INFO(error);
            if (expect_ui)
            {
                CHECK(composed_pixels[center + 0] == 16u);
                CHECK(composed_pixels[center + 1] == 32u);
                CHECK(composed_pixels[center + 2] == 255u);
                CHECK(composed_pixels[center + 3] == 255u);
            }
            else
            {
                CHECK(composed_pixels[center + 0] == 20u);
                CHECK(composed_pixels[center + 1] == 40u);
                CHECK(composed_pixels[center + 2] == 80u);
                CHECK(composed_pixels[center + 3] == 255u);
            }
            CHECK(composed_pixels[0] == 20u);
            CHECK(composed_pixels[1] == 40u);
            CHECK(composed_pixels[2] == 80u);
            CHECK(composed_pixels[3] == 255u);
        };
        draw_with_depth(
            -0.5f, ALMetalCompareFunction::less_equal, false, true);
        draw_with_depth(
            0.5f, ALMetalCompareFunction::less_equal, false, false);
        draw_with_depth(
            0.75f, ALMetalCompareFunction::greater_equal, true, true);

        // HUD attachments clear only their own screen-space bounds, then the
        // following selections/beacons recover the immutable scene depth.
        // Prove both operations against physical color and depth readback.
        auto depth_region_renderer = ALMetalUIRenderer::create(
            *device, *scheduler, &error);
        INFO(error);
        REQUIRE(depth_region_renderer);
        const ALMetalScissorRect hud_region{8, 8, 16, 16};
        error.clear();
        CHECK_FALSE(depth_region_renderer->clearFrameDepthRects(
            &hud_region, 1, 1.f, &error));
        CHECK(error ==
              "Metal UI depth regions require a frame depth backing");
        error.clear();
        CHECK_FALSE(depth_region_renderer->restoreFrameDepthRects(
            &hud_region, 1, ALMetalCompareFunction::less, &error));
        CHECK(error ==
              "Metal UI depth regions require a frame depth backing");

        ALMetalRenderTargetDescriptor unreadable_depth_descriptor =
            depth_source_descriptor;
        unreadable_depth_descriptor.depth_stencil_shader_read = false;
        unreadable_depth_descriptor.label =
            "Alchemy non-sampleable retained UI depth";
        auto unreadable_depth = ALMetalRenderTarget::create(
            *device, unreadable_depth_descriptor, &error);
        INFO(error);
        REQUIRE(unreadable_depth);
        auto unreadable_depth_renderer = ALMetalUIRenderer::create(
            *device, *scheduler, &error);
        INFO(error);
        REQUIRE(unreadable_depth_renderer);
        REQUIRE(unreadable_depth_renderer->setFrameDepth(
            unreadable_depth->depthStencilTexture(), &error));
        error.clear();
        CHECK_FALSE(unreadable_depth_renderer->restoreFrameDepthRects(
            &hud_region, 1, ALMetalCompareFunction::less, &error));
        CHECK(error ==
              "Metal UI depth restore requires a shader-readable backing");
        REQUIRE(unreadable_depth_renderer->endFrame(&error));
        CHECK(unreadable_depth_renderer->stats().frames == 0);

        REQUIRE(depth_region_renderer->setFrameBackground(
            background.get(), &error));
        REQUIRE(depth_region_renderer->setFrameDepth(
            depth_source->depthStencilTexture(), &error));
        error.clear();
        CHECK_FALSE(depth_region_renderer->clearFrameDepthRects(
            nullptr, 1, 1.f, &error));
        CHECK(error == "Metal UI depth regions are missing rectangles");
        const ALMetalScissorRect invalid_hud_region{24, 24, 16, 16};
        error.clear();
        CHECK_FALSE(depth_region_renderer->clearFrameDepthRects(
            &invalid_hud_region, 1, 1.f, &error));
        CHECK(error ==
              "Metal UI depth region is outside the retained depth target");
        error.clear();
        CHECK_FALSE(depth_region_renderer->clearFrameDepthRects(
            &hud_region, 1,
            std::numeric_limits<float>::quiet_NaN(), &error));
        CHECK(error ==
              "Metal UI clear depth must be finite and normalized");

        REQUIRE(depth_region_renderer->clearFrameDepthRects(
            &hud_region, 1, 1.f, &error));
        float hud_positions[3][4];
        std::memcpy(hud_positions, positions, sizeof(hud_positions));
        for (auto& position : hud_positions)
        {
            position[2] = 0.5f;
        }
        REQUIRE(buffer->write(
            position_offset, hud_positions, sizeof(hud_positions), &error));
        REQUIRE(buffer->write(
            color_offset, colors, sizeof(colors), &error));
        batch.depth.enabled = true;
        batch.depth.write_enabled = true;
        batch.depth.reverse_z = false;
        batch.depth.compare = ALMetalCompareFunction::less_equal;
        REQUIRE(depth_region_renderer->draw(batch, &error));
        REQUIRE(depth_region_renderer->restoreFrameDepthRects(
            &hud_region, 1, ALMetalCompareFunction::less, &error));

        const std::uint8_t green_colors[3][4] = {
            {32, 255, 16, 255}, {32, 255, 16, 255},
            {32, 255, 16, 255},
        };
        auto green_bytes = bytes;
        std::memcpy(
            green_bytes.data() + position_offset,
            hud_positions, sizeof(hud_positions));
        std::memcpy(
            green_bytes.data() + color_offset,
            green_colors, sizeof(green_colors));
        ALMetalBufferDescriptor green_buffer_descriptor = buffer_descriptor;
        green_buffer_descriptor.label =
            "Alchemy post-restore UI test SoA";
        auto green_buffer = ALMetalBuffer::create(
            *device, green_buffer_descriptor, &error);
        INFO(error);
        REQUIRE(green_buffer);
        REQUIRE(green_buffer->write(
            0, green_bytes.data(), green_bytes.size(), &error));
        batch.vertices = green_buffer.get();
        batch.depth.write_enabled = false;
        REQUIRE(depth_region_renderer->draw(batch, &error));
        REQUIRE(depth_region_renderer->endFrame(&error));
        INFO(error);
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);

        const ALMetalTexture* depth_region_color =
            depth_region_renderer->outputTexture();
        const ALMetalTexture* depth_region_depth =
            depth_region_renderer->outputDepthTexture();
        REQUIRE(depth_region_color);
        REQUIRE(depth_region_depth);
        REQUIRE(depth_region_color->readback(
            *device, 0, 0, {}, composed_pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(composed_pixels[center + 0] == 16u);
        CHECK(composed_pixels[center + 1] == 32u);
        CHECK(composed_pixels[center + 2] == 255u);
        CHECK(composed_pixels[center + 3] == 255u);
        const std::size_t outside_hud = (4 * 32 + 16) * 4;
        CHECK(composed_pixels[outside_hud + 0] == 20u);
        CHECK(composed_pixels[outside_hud + 1] == 40u);
        CHECK(composed_pixels[outside_hud + 2] == 80u);
        CHECK(composed_pixels[outside_hud + 3] == 255u);
        std::array<float, 32 * 32> depth_region_values{};
        REQUIRE(depth_region_depth->readback(
            *device, 0, 0, {}, depth_region_values.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK(std::abs(depth_region_values[16 * 32 + 16] - 0.5f) <
              0.0001f);
        CHECK(std::abs(depth_region_values[4 * 32 + 16] - 0.5f) <
              0.0001f);
        const ALMetalUIRendererStats depth_region_stats =
            depth_region_renderer->stats();
        CHECK(depth_region_stats.frames == 1);
        CHECK(depth_region_stats.batches == 2);
        CHECK(depth_region_stats.vertices == 6);
        batch.vertices = buffer.get();

        // The legacy restore is conditional: a nearer HUD fragment remains
        // in depth so later world-space UI is hidden by the HUD as well as by
        // the scene. A blind retained-depth overwrite would turn this blue
        // result green and replace 0.25 with the farther scene value 0.5.
        auto preserved_hud_renderer = ALMetalUIRenderer::create(
            *device, *scheduler, &error);
        INFO(error);
        REQUIRE(preserved_hud_renderer);
        REQUIRE(preserved_hud_renderer->setFrameBackground(
            background.get(), &error));
        REQUIRE(preserved_hud_renderer->setFrameDepth(
            depth_source->depthStencilTexture(), &error));
        REQUIRE(preserved_hud_renderer->clearFrameDepthRects(
            &hud_region, 1, 1.f, &error));

        float near_hud_positions[3][4];
        std::memcpy(
            near_hud_positions, positions, sizeof(near_hud_positions));
        for (auto& position : near_hud_positions)
        {
            position[2] = -0.5f;
        }
        REQUIRE(buffer->write(
            position_offset, near_hud_positions,
            sizeof(near_hud_positions), &error));
        REQUIRE(buffer->write(
            color_offset, colors, sizeof(colors), &error));
        batch.depth.write_enabled = true;
        batch.vertices = buffer.get();
        REQUIRE(preserved_hud_renderer->draw(batch, &error));
        REQUIRE(preserved_hud_renderer->restoreFrameDepthRects(
            &hud_region, 1, ALMetalCompareFunction::less, &error));

        float behind_hud_positions[3][4];
        std::memcpy(
            behind_hud_positions, positions, sizeof(behind_hud_positions));
        for (auto& position : behind_hud_positions)
        {
            position[2] = -0.2f;
        }
        auto behind_hud_bytes = bytes;
        std::memcpy(
            behind_hud_bytes.data() + position_offset,
            behind_hud_positions, sizeof(behind_hud_positions));
        std::memcpy(
            behind_hud_bytes.data() + color_offset,
            green_colors, sizeof(green_colors));
        ALMetalBufferDescriptor behind_hud_buffer_descriptor =
            buffer_descriptor;
        behind_hud_buffer_descriptor.label =
            "Alchemy UI behind preserved HUD depth SoA";
        auto behind_hud_buffer = ALMetalBuffer::create(
            *device, behind_hud_buffer_descriptor, &error);
        INFO(error);
        REQUIRE(behind_hud_buffer);
        REQUIRE(behind_hud_buffer->write(
            0, behind_hud_bytes.data(), behind_hud_bytes.size(), &error));
        batch.vertices = behind_hud_buffer.get();
        batch.depth.write_enabled = false;
        REQUIRE(preserved_hud_renderer->draw(batch, &error));
        REQUIRE(preserved_hud_renderer->endFrame(&error));
        INFO(error);
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);

        REQUIRE(preserved_hud_renderer->outputTexture()->readback(
            *device, 0, 0, {}, composed_pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(composed_pixels[center + 0] == 16u);
        CHECK(composed_pixels[center + 1] == 32u);
        CHECK(composed_pixels[center + 2] == 255u);
        CHECK(composed_pixels[center + 3] == 255u);
        REQUIRE(preserved_hud_renderer->outputDepthTexture()->readback(
            *device, 0, 0, {}, depth_region_values.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK(std::abs(depth_region_values[16 * 32 + 16] - 0.25f) <
              0.0001f);
        batch.vertices = buffer.get();

        // Static HUD volume geometry reaches the same retained transaction as
        // an indexed draw rather than through the immediate UI bridge. Prove
        // the viewer's packed position.w texture selector, display-encoded
        // texel/tint multiply, texture-only mask and localized depth contract.
        auto hud_bytes = bytes;
        float indexed_hud_positions[3][4];
        std::memcpy(
            indexed_hud_positions, positions, sizeof(indexed_hud_positions));
        constexpr std::int32_t hud_texture_slot = 1;
        for (auto& position : indexed_hud_positions)
        {
            position[2] = -0.5f;
            std::memcpy(&position[3], &hud_texture_slot,
                        sizeof(hud_texture_slot));
        }
        const std::uint8_t hud_colors[3][4] = {
            {128, 64, 255, 10}, {128, 64, 255, 10},
            {128, 64, 255, 10},
        };
        std::memcpy(hud_bytes.data() + position_offset,
                    indexed_hud_positions, sizeof(indexed_hud_positions));
        std::memcpy(hud_bytes.data() + color_offset,
                    hud_colors, sizeof(hud_colors));
        ALMetalBufferDescriptor hud_vertex_descriptor = buffer_descriptor;
        hud_vertex_descriptor.length = hud_bytes.size();
        hud_vertex_descriptor.label = "Alchemy indexed HUD vertex test";
        auto hud_vertices = ALMetalBuffer::create(
            *device, hud_vertex_descriptor, &error);
        INFO(error);
        REQUIRE(hud_vertices);
        REQUIRE(hud_vertices->write(
            0, hud_bytes.data(), hud_bytes.size(), &error));

        const std::array<std::uint16_t, 3> hud_index_values{{0, 1, 2}};
        ALMetalBufferDescriptor hud_index_descriptor;
        hud_index_descriptor.length = sizeof(hud_index_values);
        hud_index_descriptor.storage = ALMetalStorageMode::shared;
        hud_index_descriptor.label = "Alchemy indexed HUD index test";
        auto hud_indices = ALMetalBuffer::create(
            *device, hud_index_descriptor, &error);
        INFO(error);
        REQUIRE(hud_indices);
        REQUIRE(hud_indices->write(
            0, hud_index_values.data(), sizeof(hud_index_values), &error));

        const std::array<std::uint16_t, 3> hud_reversed_index_values{{0, 2, 1}};
        ALMetalBufferDescriptor hud_reversed_index_descriptor =
            hud_index_descriptor;
        hud_reversed_index_descriptor.label =
            "Alchemy reversed indexed HUD particle test";
        auto hud_reversed_indices = ALMetalBuffer::create(
            *device, hud_reversed_index_descriptor, &error);
        INFO(error);
        REQUIRE(hud_reversed_indices);
        REQUIRE(hud_reversed_indices->write(
            0, hud_reversed_index_values.data(),
            sizeof(hud_reversed_index_values), &error));

        auto make_hud_texture = [&](const char* label,
                                    std::array<std::uint8_t, 4> texel,
                                    ALMetalPixelFormat format)
        {
            ALMetalTextureDescriptor descriptor = texture_descriptor;
            descriptor.format = format;
            descriptor.label = label;
            auto result = ALMetalTexture::create(*device, descriptor, &error);
            INFO(error);
            REQUIRE(result);
            auto command = device->makeCommandBuffer(label, &error);
            INFO(error);
            REQUIRE(command);
            REQUIRE(result->upload(
                *command, 0, 0, {}, texel.data(), 4, &error));
            REQUIRE(command->commitAndWait(&error));
            INFO(error);
            return result;
        };
        auto hud_slot_zero = make_hud_texture(
            "Alchemy indexed HUD unselected texture", {255, 0, 0, 255},
            ALMetalPixelFormat::rgba8_unorm);
        auto hud_slot_one = make_hud_texture(
            "Alchemy indexed HUD selected sRGB texture", {64, 128, 192, 200},
            ALMetalPixelFormat::rgba8_unorm_srgb);
        auto hud_mask_discard = make_hud_texture(
            "Alchemy indexed HUD discarded texture", {255, 255, 255, 100},
            ALMetalPixelFormat::rgba8_unorm);
        auto make_hud_strip_texture = [&]
            (const char* label, const std::array<std::uint8_t, 8>& texels)
        {
            ALMetalTextureDescriptor descriptor = texture_descriptor;
            descriptor.format = ALMetalPixelFormat::rgba8_unorm_srgb;
            descriptor.width = 2;
            descriptor.label = label;
            auto result = ALMetalTexture::create(*device, descriptor, &error);
            INFO(error);
            REQUIRE(result);
            auto command = device->makeCommandBuffer(label, &error);
            INFO(error);
            REQUIRE(command);
            REQUIRE(result->upload(
                *command, 0, 0, {}, texels.data(), 8, &error));
            REQUIRE(command->commitAndWait(&error));
            INFO(error);
            return result;
        };
        const std::array<std::uint8_t, 8> hud_pbr_base_texels = {
            64, 128, 192, 200, 255, 0, 255, 32};
        const std::array<std::uint8_t, 8> hud_pbr_emissive_texels = {
            0, 0, 0, 255, 255, 128, 64, 255};
        auto hud_pbr_base = make_hud_strip_texture(
            "Alchemy indexed HUD PBR base-color texture",
            hud_pbr_base_texels);
        auto hud_pbr_emissive = make_hud_strip_texture(
            "Alchemy indexed HUD PBR emissive texture",
            hud_pbr_emissive_texels);

        // Real viewer mirrors can retain BC-compressed sRGB storage. The raw
        // sampling contract must provide a compatible view for those assets
        // too, rather than decoding them merely because compression survived.
        for (ALMetalPixelFormat format : {
                 ALMetalPixelFormat::bc1_rgba_srgb,
                 ALMetalPixelFormat::bc2_rgba_srgb,
                 ALMetalPixelFormat::bc3_rgba_srgb})
        {
            ALMetalTextureDescriptor hud_bc_descriptor = texture_descriptor;
            hud_bc_descriptor.format = format;
            hud_bc_descriptor.width = 4;
            hud_bc_descriptor.height = 4;
            hud_bc_descriptor.label = "Alchemy indexed HUD BC sRGB view test";
            auto hud_bc_texture = ALMetalTexture::create(
                *device, hud_bc_descriptor, &error);
            INFO(error);
            REQUIRE(hud_bc_texture);
            CHECK(hud_bc_texture->nativeLinearHandle() != nullptr);
        }

        ALMetalHUDIndexedBatch hud_batch;
        hud_batch.vertices = hud_vertices.get();
        hud_batch.position_offset = position_offset;
        hud_batch.texcoord_offset = texcoord_offset;
        hud_batch.color_offset = color_offset;
        hud_batch.vertex_count = 3;
        hud_batch.indices = hud_indices.get();
        hud_batch.index_type = ALMetalIndexType::uint16;
        hud_batch.index_count = 3;
        hud_batch.textures[0] = hud_slot_zero.get();
        hud_batch.textures[1] = hud_slot_one.get();
        hud_batch.texture_count = 2;
        hud_batch.sampler = batch.sampler;
        hud_batch.blend.enabled = false;
        hud_batch.depth.enabled = true;
        hud_batch.depth.write_enabled = true;
        hud_batch.depth.compare = ALMetalCompareFunction::less_equal;
        hud_batch.viewport = batch.viewport;
        hud_batch.scissor = hud_region;
        hud_batch.target_width = 32;
        hud_batch.target_height = 32;
        for (int i = 0; i < 4; ++i)
        {
            hud_batch.matrices.modelview_projection[i * 4 + i] = 1.f;
            hud_batch.matrices.texture0[i * 4 + i] = 1.f;
        }

        auto hud_renderer = ALMetalUIRenderer::create(
            *device, *scheduler, &error);
        INFO(error);
        REQUIRE(hud_renderer);
        REQUIRE(hud_renderer->setFrameBackground(background.get(), &error));
        REQUIRE(hud_renderer->setFrameDepth(
            depth_source->depthStencilTexture(), &error));
        REQUIRE(hud_renderer->clearFrameDepthRects(
            &hud_region, 1, 1.f, &error));
        REQUIRE(hud_renderer->drawHUDIndexed(hud_batch, &error));
        REQUIRE(hud_renderer->restoreFrameDepthRects(
            &hud_region, 1, ALMetalCompareFunction::less, &error));
        REQUIRE(hud_renderer->endFrame(&error));
        INFO(error);
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);
        REQUIRE(hud_renderer->outputTexture()->readback(
            *device, 0, 0, {}, composed_pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(composed_pixels[center + 0]) - 192) <= 1);
        CHECK(std::abs(static_cast<int>(composed_pixels[center + 1]) - 32) <= 1);
        CHECK(std::abs(static_cast<int>(composed_pixels[center + 2]) - 32) <= 1);
        CHECK(std::abs(static_cast<int>(composed_pixels[center + 3]) - 8) <= 1);
        REQUIRE(hud_renderer->outputDepthTexture()->readback(
            *device, 0, 0, {}, depth_region_values.data(),
            32 * sizeof(float), &error));
        INFO(error);
        CHECK(std::abs(depth_region_values[16 * 32 + 16] - 0.25f) <
              0.0001f);

        // Ordinary HUD volumes retain back-face culling. Particle and HUD-
        // particle partitions disable it in the GL owner, however, because
        // their generated quads can reach this bridge with either winding.
        // Prove the explicit double-sided bit preserves that contract rather
        // than relying on the source triangle's current orientation.
        hud_batch.indices = hud_reversed_indices.get();
        REQUIRE(hud_renderer->setFrameBackground(background.get(), &error));
        REQUIRE(hud_renderer->setFrameDepth(
            depth_source->depthStencilTexture(), &error));
        REQUIRE(hud_renderer->clearFrameDepthRects(
            &hud_region, 1, 1.f, &error));
        REQUIRE(hud_renderer->drawHUDIndexed(hud_batch, &error));
        REQUIRE(hud_renderer->endFrame(&error));
        INFO(error);
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);
        REQUIRE(hud_renderer->outputTexture()->readback(
            *device, 0, 0, {}, composed_pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(composed_pixels[center + 0] == 20u);
        CHECK(composed_pixels[center + 1] == 40u);
        CHECK(composed_pixels[center + 2] == 80u);
        CHECK(composed_pixels[center + 3] == 255u);

        hud_batch.double_sided = true;
        REQUIRE(hud_renderer->setFrameBackground(background.get(), &error));
        REQUIRE(hud_renderer->setFrameDepth(
            depth_source->depthStencilTexture(), &error));
        REQUIRE(hud_renderer->clearFrameDepthRects(
            &hud_region, 1, 1.f, &error));
        REQUIRE(hud_renderer->drawHUDIndexed(hud_batch, &error));
        REQUIRE(hud_renderer->endFrame(&error));
        INFO(error);
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);
        REQUIRE(hud_renderer->outputTexture()->readback(
            *device, 0, 0, {}, composed_pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(composed_pixels[center + 0]) - 192) <= 1);
        CHECK(std::abs(static_cast<int>(composed_pixels[center + 1]) - 32) <= 1);
        CHECK(std::abs(static_cast<int>(composed_pixels[center + 2]) - 32) <= 1);
        CHECK(std::abs(static_cast<int>(composed_pixels[center + 3]) - 8) <= 1);
        hud_batch.indices = hud_indices.get();
        hud_batch.double_sided = false;

        // Vertex alpha is legacy shininess in this pool: a low value must not
        // fail the mask while the selected texture is above the authored cut.
        hud_batch.shader = ALMetalHUDShader::fullbright_alpha_mask;
        hud_batch.minimum_alpha = 0.5f;
        REQUIRE(hud_renderer->setFrameBackground(background.get(), &error));
        REQUIRE(hud_renderer->setFrameDepth(
            depth_source->depthStencilTexture(), &error));
        REQUIRE(hud_renderer->clearFrameDepthRects(
            &hud_region, 1, 1.f, &error));
        REQUIRE(hud_renderer->drawHUDIndexed(hud_batch, &error));
        REQUIRE(hud_renderer->endFrame(&error));
        INFO(error);
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);
        REQUIRE(hud_renderer->outputTexture()->readback(
            *device, 0, 0, {}, composed_pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(composed_pixels[center + 0]) - 192) <= 1);
        CHECK(std::abs(static_cast<int>(composed_pixels[center + 3]) - 8) <= 1);

        // A below-cut texture discards and leaves the retained world backing.
        hud_batch.textures[1] = hud_mask_discard.get();
        REQUIRE(hud_renderer->setFrameBackground(background.get(), &error));
        REQUIRE(hud_renderer->setFrameDepth(
            depth_source->depthStencilTexture(), &error));
        REQUIRE(hud_renderer->clearFrameDepthRects(
            &hud_region, 1, 1.f, &error));
        REQUIRE(hud_renderer->drawHUDIndexed(hud_batch, &error));
        REQUIRE(hud_renderer->endFrame(&error));
        INFO(error);
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);
        REQUIRE(hud_renderer->outputTexture()->readback(
            *device, 0, 0, {}, composed_pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(composed_pixels[center + 0] == 20u);
        CHECK(composed_pixels[center + 1] == 40u);
        CHECK(composed_pixels[center + 2] == 80u);
        CHECK(composed_pixels[center + 3] == 255u);

        // The HUD alpha pool tests texture alpha times vertex coverage with
        // no mask-pool bias, then applies the live separate RGB/alpha blend.
        // This low streamed alpha is shininess in the opaque pool above but
        // becomes coverage here.
        hud_batch.shader = ALMetalHUDShader::fullbright_alpha;
        hud_batch.textures[1] = hud_slot_one.get();
        hud_batch.minimum_alpha = 0.02f;
        hud_batch.blend.enabled = true;
        hud_batch.blend.source_rgb = ALMetalBlendFactor::source_alpha;
        hud_batch.blend.destination_rgb =
            ALMetalBlendFactor::one_minus_source_alpha;
        hud_batch.blend.source_alpha = ALMetalBlendFactor::zero;
        hud_batch.blend.destination_alpha =
            ALMetalBlendFactor::one_minus_source_alpha;
        REQUIRE(hud_renderer->setFrameBackground(background.get(), &error));
        REQUIRE(hud_renderer->setFrameDepth(
            depth_source->depthStencilTexture(), &error));
        REQUIRE(hud_renderer->clearFrameDepthRects(
            &hud_region, 1, 1.f, &error));
        REQUIRE(hud_renderer->drawHUDIndexed(hud_batch, &error));
        REQUIRE(hud_renderer->endFrame(&error));
        INFO(error);
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);
        REQUIRE(hud_renderer->outputTexture()->readback(
            *device, 0, 0, {}, composed_pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(std::abs(static_cast<int>(composed_pixels[center + 0]) - 25) <= 1);
        CHECK(std::abs(static_cast<int>(composed_pixels[center + 1]) - 40) <= 1);
        CHECK(std::abs(static_cast<int>(composed_pixels[center + 2]) - 79) <= 1);
        CHECK(std::abs(static_cast<int>(composed_pixels[center + 3]) - 247) <= 1);

        // Raising the unbiased cutoff above 200/255 * 10/255 discards.
        hud_batch.minimum_alpha = 0.04f;
        REQUIRE(hud_renderer->setFrameBackground(background.get(), &error));
        REQUIRE(hud_renderer->setFrameDepth(
            depth_source->depthStencilTexture(), &error));
        REQUIRE(hud_renderer->clearFrameDepthRects(
            &hud_region, 1, 1.f, &error));
        REQUIRE(hud_renderer->drawHUDIndexed(hud_batch, &error));
        REQUIRE(hud_renderer->endFrame(&error));
        INFO(error);
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);
        REQUIRE(hud_renderer->outputTexture()->readback(
            *device, 0, 0, {}, composed_pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(composed_pixels[center + 0] == 20u);
        CHECK(composed_pixels[center + 1] == 40u);
        CHECK(composed_pixels[center + 2] == 80u);
        CHECK(composed_pixels[center + 3] == 255u);

        // Highlight Transparent is a sampled uniform-colour HUD draw, not a
        // streamed-tint fullbright draw. Its RGB-only mask must preserve the
        // retained world alpha. Move the rigged variant to the right so a
        // static-vertex implementation cannot satisfy both controls.
        hud_batch.shader = ALMetalHUDShader::highlight;
        hud_batch.textures[0] = texture.get();
        hud_batch.texture_count = 1;
        hud_batch.emissive_texture = nullptr;
        hud_batch.minimum_alpha = 0.f;
        hud_batch.highlight_color[0] = 1.f;
        hud_batch.highlight_color[1] = 0.f;
        hud_batch.highlight_color[2] = 0.f;
        hud_batch.highlight_color[3] = 1.f;
        hud_batch.blend.enabled = true;
        hud_batch.blend.source_rgb = ALMetalBlendFactor::source_alpha;
        hud_batch.blend.destination_rgb =
            ALMetalBlendFactor::one_minus_source_alpha;
        hud_batch.blend.source_alpha = ALMetalBlendFactor::zero;
        hud_batch.blend.destination_alpha =
            ALMetalBlendFactor::one_minus_source_alpha;
        hud_batch.blend.write_mask =
            static_cast<ALMetalColorWriteMask>(
                static_cast<std::uint8_t>(ALMetalColorWriteMask::red) |
                static_cast<std::uint8_t>(ALMetalColorWriteMask::green) |
                static_cast<std::uint8_t>(ALMetalColorWriteMask::blue));
        hud_batch.depth.write_enabled = false;
        hud_batch.double_sided = false;
        REQUIRE(hud_renderer->setFrameBackground(background.get(), &error));
        REQUIRE(hud_renderer->setFrameDepth(
            depth_source->depthStencilTexture(), &error));
        REQUIRE(hud_renderer->clearFrameDepthRects(
            &hud_region, 1, 1.f, &error));
        REQUIRE(hud_renderer->drawHUDIndexed(hud_batch, &error));
        REQUIRE(hud_renderer->endFrame(&error));
        INFO(error);
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);
        REQUIRE(hud_renderer->outputTexture()->readback(
            *device, 0, 0, {}, composed_pixels.data(), 32 * 4, &error));
        INFO(error);
        const std::size_t hud_highlight_static = (16 * 32 + 12) * 4;
        CHECK(composed_pixels[hud_highlight_static + 0] == 0u);
        CHECK(composed_pixels[hud_highlight_static + 1] == 0u);
        CHECK(composed_pixels[hud_highlight_static + 2] == 255u);
        CHECK(composed_pixels[hud_highlight_static + 3] == 255u);

        constexpr std::size_t hud_highlight_weight_offset =
            (color_offset + sizeof(hud_colors) + 15u) & ~std::size_t{15u};
        const std::array<std::array<float, 4>, 3> hud_highlight_weights{{
            {{0.5f, 0.f, 0.f, 0.f}},
            {{0.5f, 0.f, 0.f, 0.f}},
            {{0.5f, 0.f, 0.f, 0.f}},
        }};
        std::array<std::uint8_t,
                   hud_highlight_weight_offset +
                       sizeof(hud_highlight_weights)>
            hud_highlight_bytes{};
        std::memcpy(hud_highlight_bytes.data(), hud_bytes.data(),
                    hud_bytes.size());
        std::memcpy(
            hud_highlight_bytes.data() + hud_highlight_weight_offset,
            hud_highlight_weights.data(), sizeof(hud_highlight_weights));
        ALMetalBufferDescriptor hud_highlight_vertex_descriptor =
            hud_vertex_descriptor;
        hud_highlight_vertex_descriptor.length =
            hud_highlight_bytes.size();
        hud_highlight_vertex_descriptor.label =
            "Alchemy rigged HUD highlight vertices";
        auto hud_highlight_vertices = ALMetalBuffer::create(
            *device, hud_highlight_vertex_descriptor, &error);
        INFO(error);
        REQUIRE(hud_highlight_vertices);
        REQUIRE(hud_highlight_vertices->write(
            0, hud_highlight_bytes.data(), hud_highlight_bytes.size(),
            &error));
        std::array<float, 16> hud_highlight_palette{{
            0.f, 0.f, 0.f, 0.f,
            1.f, 0.f, 0.f, 0.5f,
            0.f, 1.f, 0.f, 0.f,
            0.f, 0.f, 1.f, 0.f,
        }};
        hud_batch.shader = ALMetalHUDShader::highlight_skinned;
        hud_batch.vertices = hud_highlight_vertices.get();
        hud_batch.weight_offset = hud_highlight_weight_offset;
        hud_batch.skin_palette = hud_highlight_palette.data();
        hud_batch.skin_palette_float_count = hud_highlight_palette.size();
        hud_batch.skin_joint_count = 1;
        REQUIRE(hud_renderer->setFrameBackground(background.get(), &error));
        REQUIRE(hud_renderer->setFrameDepth(
            depth_source->depthStencilTexture(), &error));
        REQUIRE(hud_renderer->clearFrameDepthRects(
            &hud_region, 1, 1.f, &error));
        REQUIRE(hud_renderer->drawHUDIndexed(hud_batch, &error));
        REQUIRE(hud_renderer->endFrame(&error));
        INFO(error);
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);
        composed_pixels.fill(0xffu);
        REQUIRE(hud_renderer->outputTexture()->readback(
            *device, 0, 0, {}, composed_pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(composed_pixels[hud_highlight_static + 0] == 20u);
        CHECK(composed_pixels[hud_highlight_static + 1] == 40u);
        CHECK(composed_pixels[hud_highlight_static + 2] == 80u);
        CHECK(composed_pixels[hud_highlight_static + 3] == 255u);
        std::size_t rigged_highlight_first_x = 32;
        std::size_t rigged_highlight_last_x = 0;
        std::size_t rigged_highlight_pixel_count = 0;
        for (std::size_t x = 0; x < 32; ++x)
        {
            const std::size_t pixel = (16 * 32 + x) * 4;
            if (composed_pixels[pixel + 0] == 0u &&
                composed_pixels[pixel + 1] == 0u &&
                composed_pixels[pixel + 2] == 255u &&
                composed_pixels[pixel + 3] == 255u)
            {
                rigged_highlight_first_x = std::min(
                    rigged_highlight_first_x, x);
                rigged_highlight_last_x = std::max(
                    rigged_highlight_last_x, x);
                ++rigged_highlight_pixel_count;
            }
        }
        CHECK(rigged_highlight_pixel_count > 0);
        CHECK(rigged_highlight_first_x >= 17);
        CHECK(rigged_highlight_last_x >= 23);

        hud_batch.skin_palette_float_count = 4;
        error.clear();
        CHECK_FALSE(hud_renderer->drawHUDIndexed(hud_batch, &error));
        CHECK(error == "Metal HUD highlight skinning data is invalid");
        CHECK_FALSE(hud_renderer->hasOpenFrame());
        hud_batch.vertices = hud_vertices.get();
        hud_batch.weight_offset = 0;
        hud_batch.skin_palette = nullptr;
        hud_batch.skin_palette_float_count = 0;
        hud_batch.skin_joint_count = 0;
        hud_batch.blend.write_mask = ALMetalColorWriteMask::all;

        // Batch Size HUD attachments are untextured uniform-color indexed
        // draws. They retain the world owner's RGB-only alpha blend, no-cull
        // state, read/write depth, polygon offset and optional object skinning
        // instead of falling through the ordinary textured HUD pipeline.
        hud_batch.shader = ALMetalHUDShader::debug;
        hud_batch.vertices = hud_vertices.get();
        hud_batch.texture_count = 0;
        hud_batch.textures.fill(nullptr);
        hud_batch.highlight_color[0] = 1.f;
        hud_batch.highlight_color[1] = 64.f / 255.f;
        hud_batch.highlight_color[2] = 0.f;
        hud_batch.highlight_color[3] = 200.f / 255.f;
        hud_batch.blend.enabled = true;
        hud_batch.blend.source_rgb = ALMetalBlendFactor::source_alpha;
        hud_batch.blend.destination_rgb =
            ALMetalBlendFactor::one_minus_source_alpha;
        hud_batch.blend.source_alpha = ALMetalBlendFactor::source_alpha;
        hud_batch.blend.destination_alpha =
            ALMetalBlendFactor::one_minus_source_alpha;
        hud_batch.blend.write_mask =
            static_cast<ALMetalColorWriteMask>(
                static_cast<std::uint8_t>(ALMetalColorWriteMask::red) |
                static_cast<std::uint8_t>(ALMetalColorWriteMask::green) |
                static_cast<std::uint8_t>(ALMetalColorWriteMask::blue));
        hud_batch.depth.write_enabled = true;
        hud_batch.depth_bias_slope = -1.f;
        hud_batch.depth_bias_units = 1.f;
        hud_batch.double_sided = true;
        REQUIRE(hud_renderer->setFrameBackground(background.get(), &error));
        REQUIRE(hud_renderer->setFrameDepth(
            depth_source->depthStencilTexture(), &error));
        REQUIRE(hud_renderer->clearFrameDepthRects(
            &hud_region, 1, 1.f, &error));
        REQUIRE(hud_renderer->drawHUDIndexed(hud_batch, &error));
        REQUIRE(hud_renderer->endFrame(&error));
        INFO(error);
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);
        composed_pixels.fill(0xffu);
        REQUIRE(hud_renderer->outputTexture()->readback(
            *device, 0, 0, {}, composed_pixels.data(), 32 * 4, &error));
        REQUIRE(hud_renderer->outputDepthTexture()->readback(
            *device, 0, 0, {}, depth_region_values.data(),
            32 * sizeof(float), &error));
        INFO(error);
        const float hud_debug_alpha = 200.f / 255.f;
        const std::array<float, 3> hud_debug_source{{
            0.f, 64.f / 255.f, 1.f,
        }};
        const std::array<float, 3> hud_debug_background{{
            20.f / 255.f, 40.f / 255.f, 80.f / 255.f,
        }};
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            const float expected = hud_debug_source[channel] *
                    hud_debug_alpha +
                hud_debug_background[channel] *
                    (1.f - hud_debug_alpha);
            CHECK(std::abs(
                static_cast<float>(composed_pixels[center + channel]) /
                    255.f - expected) < 0.01f);
        }
        CHECK(composed_pixels[center + 3] == 255u);
        CHECK(depth_region_values[16 * 32 + 16] < 0.25f);

        hud_batch.indices = hud_reversed_indices.get();
        REQUIRE(hud_renderer->setFrameBackground(background.get(), &error));
        REQUIRE(hud_renderer->setFrameDepth(
            depth_source->depthStencilTexture(), &error));
        REQUIRE(hud_renderer->clearFrameDepthRects(
            &hud_region, 1, 1.f, &error));
        REQUIRE(hud_renderer->drawHUDIndexed(hud_batch, &error));
        REQUIRE(hud_renderer->endFrame(&error));
        INFO(error);
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);
        REQUIRE(hud_renderer->outputTexture()->readback(
            *device, 0, 0, {}, composed_pixels.data(), 32 * 4, &error));
        CHECK(composed_pixels[center + 2] > 180u);
        hud_batch.indices = hud_indices.get();

        hud_batch.shader = ALMetalHUDShader::debug_skinned;
        hud_batch.vertices = hud_highlight_vertices.get();
        hud_batch.weight_offset = hud_highlight_weight_offset;
        hud_batch.skin_palette = hud_highlight_palette.data();
        hud_batch.skin_palette_float_count =
            hud_highlight_palette.size();
        hud_batch.skin_joint_count = 1;
        REQUIRE(hud_renderer->setFrameBackground(background.get(), &error));
        REQUIRE(hud_renderer->setFrameDepth(
            depth_source->depthStencilTexture(), &error));
        REQUIRE(hud_renderer->clearFrameDepthRects(
            &hud_region, 1, 1.f, &error));
        REQUIRE(hud_renderer->drawHUDIndexed(hud_batch, &error));
        REQUIRE(hud_renderer->endFrame(&error));
        INFO(error);
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);
        composed_pixels.fill(0xffu);
        REQUIRE(hud_renderer->outputTexture()->readback(
            *device, 0, 0, {}, composed_pixels.data(), 32 * 4, &error));
        std::size_t rigged_debug_first_x = 32;
        std::size_t rigged_debug_last_x = 0;
        for (std::size_t x = 0; x < 32; ++x)
        {
            const std::size_t pixel = (16 * 32 + x) * 4;
            if (composed_pixels[pixel + 0] != 20u ||
                composed_pixels[pixel + 1] != 40u ||
                composed_pixels[pixel + 2] != 80u)
            {
                rigged_debug_first_x = std::min(
                    rigged_debug_first_x, x);
                rigged_debug_last_x = std::max(
                    rigged_debug_last_x, x);
            }
        }
        CHECK(rigged_debug_first_x >= 17);
        CHECK(rigged_debug_last_x >= 23);

        hud_batch.skin_palette_float_count = 4;
        error.clear();
        CHECK_FALSE(hud_renderer->drawHUDIndexed(hud_batch, &error));
        CHECK(error == "Metal HUD debug skinning data is invalid");
        CHECK_FALSE(hud_renderer->hasOpenFrame());
        hud_batch.depth_bias_units =
            std::numeric_limits<float>::quiet_NaN();
        hud_batch.skin_palette_float_count =
            hud_highlight_palette.size();
        error.clear();
        CHECK_FALSE(hud_renderer->drawHUDIndexed(hud_batch, &error));
        CHECK(error == "Metal HUD depth bias must be finite");
        CHECK_FALSE(hud_renderer->hasOpenFrame());
        hud_batch.vertices = hud_vertices.get();
        hud_batch.weight_offset = 0;
        hud_batch.skin_palette = nullptr;
        hud_batch.skin_palette_float_count = 0;
        hud_batch.skin_joint_count = 0;
        hud_batch.depth_bias_slope = 0.f;
        hud_batch.depth_bias_units = 0.f;
        hud_batch.blend.write_mask = ALMetalColorWriteMask::all;

        // PBR HUD alpha keeps the same coverage/blend contract, but its glTF
        // colour maps and streamed tint are decoded before base + emissive
        // shading and the result is encoded for the BGRA8 target. Offset only
        // the emissive transform to prove the two KHR transforms are
        // independent. Invalid material packs must fail before a frame opens.
        hud_batch.shader = ALMetalHUDShader::pbr_alpha;
        hud_batch.texture_count = 1;
        hud_batch.textures[0] = hud_pbr_base.get();
        hud_batch.emissive_texture = nullptr;
        hud_batch.minimum_alpha = 0.02f;
        hud_batch.double_sided = true;
        error.clear();
        CHECK_FALSE(hud_renderer->drawHUDIndexed(hud_batch, &error));
        CHECK(error == "Metal HUD PBR material state is invalid");
        CHECK_FALSE(hud_renderer->hasOpenFrame());
        hud_batch.emissive_texture = hud_pbr_emissive.get();
        hud_batch.pbr_base_color_transform[0] =
            std::numeric_limits<float>::quiet_NaN();
        error.clear();
        CHECK_FALSE(hud_renderer->drawHUDIndexed(hud_batch, &error));
        CHECK(error == "Metal HUD PBR material state is invalid");
        CHECK_FALSE(hud_renderer->hasOpenFrame());
        hud_batch.pbr_base_color_transform[0] = 1.f;
        hud_batch.pbr_emissive_transform[4] = 0.75f;
        hud_batch.pbr_emissive_color[0] = 0.5f;
        hud_batch.pbr_emissive_color[1] = 1.f;
        hud_batch.pbr_emissive_color[2] = 1.f;
        REQUIRE(hud_renderer->setFrameBackground(background.get(), &error));
        REQUIRE(hud_renderer->setFrameDepth(
            depth_source->depthStencilTexture(), &error));
        REQUIRE(hud_renderer->clearFrameDepthRects(
            &hud_region, 1, 1.f, &error));
        REQUIRE(hud_renderer->drawHUDIndexed(hud_batch, &error));
        REQUIRE(hud_renderer->endFrame(&error));
        INFO(error);
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);
        REQUIRE(hud_renderer->outputTexture()->readback(
            *device, 0, 0, {}, composed_pixels.data(), 32 * 4, &error));
        INFO(error);
        const auto hud_srgb_to_linear = [](float encoded)
        {
            return encoded <= 0.04045f
                ? encoded / 12.92f
                : std::pow((encoded + 0.055f) / 1.055f, 2.4f);
        };
        const auto hud_linear_to_srgb = [](float linear)
        {
            const float value = std::max(linear, 0.f);
            return value <= 0.0031308f
                ? value * 12.92f
                : 1.055f * std::pow(value, 1.f / 2.4f) - 0.055f;
        };
        const float hud_coverage =
            (hud_pbr_base_texels[3] / 255.f) * (hud_colors[0][3] / 255.f);
        const float hud_emissive_factor[3] = {0.5f, 1.f, 1.f};
        const std::uint8_t hud_background_rgb[3] = {80, 40, 20};
        for (std::size_t channel = 0; channel < 3; ++channel)
        {
            const float linear =
                hud_srgb_to_linear(hud_pbr_base_texels[channel] / 255.f) *
                    hud_srgb_to_linear(hud_colors[0][channel] / 255.f) +
                hud_srgb_to_linear(
                    hud_pbr_emissive_texels[4 + channel] / 255.f) *
                    hud_emissive_factor[channel];
            const float encoded = std::clamp(
                hud_linear_to_srgb(linear), 0.f, 1.f);
            const int expected = static_cast<int>(std::lround(
                encoded * hud_coverage * 255.f +
                hud_background_rgb[channel] * (1.f - hud_coverage)));
            const std::size_t bgra_channel = 2 - channel;
            CHECK(std::abs(static_cast<int>(
                      composed_pixels[center + bgra_channel]) - expected) <= 1);
        }
        const int expected_hud_alpha = static_cast<int>(std::lround(
            255.f * (1.f - hud_coverage)));
        CHECK(std::abs(static_cast<int>(composed_pixels[center + 3]) -
                       expected_hud_alpha) <= 1);

        // The PBR permutation uses the same unbiased base-alpha * vertex-alpha
        // cutoff as its authoritative GLSL program.
        hud_batch.minimum_alpha = 0.04f;
        REQUIRE(hud_renderer->setFrameBackground(background.get(), &error));
        REQUIRE(hud_renderer->setFrameDepth(
            depth_source->depthStencilTexture(), &error));
        REQUIRE(hud_renderer->clearFrameDepthRects(
            &hud_region, 1, 1.f, &error));
        REQUIRE(hud_renderer->drawHUDIndexed(hud_batch, &error));
        REQUIRE(hud_renderer->endFrame(&error));
        INFO(error);
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);
        REQUIRE(hud_renderer->outputTexture()->readback(
            *device, 0, 0, {}, composed_pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(composed_pixels[center + 0] == 20u);
        CHECK(composed_pixels[center + 1] == 40u);
        CHECK(composed_pixels[center + 2] == 80u);
        CHECK(composed_pixels[center + 3] == 255u);

        hud_batch.textures[1] = hud_slot_one.get();
        hud_batch.index_count = 4;
        error.clear();
        CHECK_FALSE(hud_renderer->drawHUDIndexed(hud_batch, &error));
        CHECK(error == "Metal HUD geometry range exceeds its buffers");
        hud_batch.index_count = 3;
        hud_batch.depth.enabled = false;
        hud_batch.depth.write_enabled = false;
        hud_batch.minimum_alpha = std::numeric_limits<float>::quiet_NaN();
        error.clear();
        CHECK_FALSE(hud_renderer->drawHUDIndexed(hud_batch, &error));
        CHECK(error == "Metal HUD alpha cutoff must be finite and normalized");
        hud_batch.minimum_alpha = 0.5f;

        error.clear();
        CHECK_FALSE(depth_renderer->setFrameDepth(
            depth_renderer->outputDepthTexture(), &error));
        CHECK(error == "Metal UI frame depth cannot alias its destination");
        error.clear();
        CHECK_FALSE(depth_renderer->draw(batch, &error));
        CHECK(error ==
              "Metal UI depth test requires a frame depth backing");
        batch.depth.enabled = false;
        batch.depth.write_enabled = true;
        batch.depth.reverse_z = false;
        error.clear();
        CHECK_FALSE(depth_renderer->draw(batch, &error));
        CHECK(error == "Metal UI depth writes require depth testing");
        batch.depth.write_enabled = false;
        REQUIRE(buffer->write(
            position_offset, positions, sizeof(positions), &error));
        REQUIRE(buffer->write(
            color_offset, colors, sizeof(colors), &error));

        auto rgba_renderer = ALMetalUIRenderer::createForTexture(
            *device, *scheduler, ALMetalPixelFormat::rgba8_unorm, &error);
        INFO(error);
        REQUIRE(rgba_renderer);
        REQUIRE(rgba_renderer->draw(batch, &error));
        INFO(error);
        CHECK(rgba_renderer->takeOutputTexture() == nullptr);
        REQUIRE(rgba_renderer->endFrame(&error));
        INFO(error);
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);

        auto owned_output = rgba_renderer->takeOutputTexture();
        REQUIRE(owned_output);
        CHECK(rgba_renderer->outputTexture() == nullptr);
        CHECK(owned_output->descriptor().format == ALMetalPixelFormat::rgba8_unorm);
        CHECK(alMetalHasUsage(owned_output->descriptor().usage,
                              ALMetalTextureUsage::render_target));
        CHECK(alMetalHasUsage(owned_output->descriptor().usage,
                              ALMetalTextureUsage::shader_read));
        pixels.fill(0);
        REQUIRE(owned_output->readback(*device, 0, 0, {}, pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(pixels[center + 0] == 255); // RGBA target
        CHECK(pixels[center + 1] == 32);
        CHECK(pixels[center + 2] == 16);
        CHECK(pixels[center + 3] == 255);

        // Ownership transfer must leave the reusable encoder capable of
        // allocating its next offscreen target lazily.
        REQUIRE(rgba_renderer->draw(batch, &error));
        INFO(error);
        REQUIRE(rgba_renderer->endFrame(&error));
        INFO(error);
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);
        REQUIRE(rgba_renderer->outputTexture());
        const ALMetalUIRendererStats reused_output_stats =
            rgba_renderer->stats();
        CHECK(reused_output_stats.frames == 2);
        CHECK(reused_output_stats.batches == 2);
        CHECK(reused_output_stats.vertices == 6);
        CHECK(reused_output_stats.pipeline_states == 1);
        CHECK(reused_output_stats.sampler_states == 1);

        // Appearance morph masks are exceptional synchronous consumers. The
        // checkpoint must expose the exact ordered RGBA pixel, then retain the
        // completed target as the background of a distinct resumed target.
        // A later draw clipped away from the sample proves final submission
        // loaded rather than cleared that checkpoint.
        auto reused_output = rgba_renderer->takeOutputTexture();
        REQUIRE(reused_output);
        REQUIRE(rgba_renderer->draw(batch, &error));
        std::array<std::uint8_t, 4> checkpoint_pixel{};
        REQUIRE(rgba_renderer->readFrameColorRGBA8(
            {16, 16, 1, 1}, checkpoint_pixel.data(), 4, &error));
        INFO(error);
        CHECK(checkpoint_pixel[0] == 255);
        CHECK(checkpoint_pixel[1] == 32);
        CHECK(checkpoint_pixel[2] == 16);
        CHECK(checkpoint_pixel[3] == 255);
        batch.scissor = {0, 0, 8, 8};
        REQUIRE(rgba_renderer->draw(batch, &error));
        batch.scissor = {0, 0, 32, 32};
        REQUIRE(rgba_renderer->endFrame(&error));
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);
        pixels.fill(0);
        REQUIRE(rgba_renderer->outputTexture()->readback(
            *device, 0, 0, {}, pixels.data(), 32 * 4, &error));
        CHECK(std::equal(
            checkpoint_pixel.begin(), checkpoint_pixel.end(),
            pixels.begin() + center));

        // The appearance compositor uses the same vertex layout with the
        // alpha-mask shader, including untextured clear/color rectangles.
        auto alpha_renderer = ALMetalUIRenderer::createForTexture(
            *device, *scheduler, ALMetalPixelFormat::rgba8_unorm, &error);
        INFO(error);
        REQUIRE(alpha_renderer);
        batch.shader = ALMetalUIShader::alpha_mask_textured;
        batch.minimum_alpha = 1.1f;
        REQUIRE(alpha_renderer->draw(batch, &error));
        REQUIRE(alpha_renderer->endFrame(&error));
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        const ALMetalTexture* alpha_output = alpha_renderer->outputTexture();
        REQUIRE(alpha_output);
        pixels.fill(255);
        REQUIRE(alpha_output->readback(
            *device, 0, 0, {}, pixels.data(), 32 * 4, &error));
        INFO(error);
        CHECK(pixels[center + 0] == 0);
        CHECK(pixels[center + 1] == 0);
        CHECK(pixels[center + 2] == 0);
        CHECK(pixels[center + 3] == 0);

        auto discarded_alpha_output = alpha_renderer->takeOutputTexture();
        REQUIRE(discarded_alpha_output);
        const float upper_positions[3][4] = {
            {-0.8f, 0.1f, 0.f, 1.f},
            { 0.8f, 0.1f, 0.f, 1.f},
            { 0.0f, 0.9f, 0.f, 1.f},
        };
        REQUIRE(buffer->write(position_offset, upper_positions,
                              sizeof(upper_positions), &error));
        batch.shader = ALMetalUIShader::alpha_mask_solid;
        batch.texture = nullptr;
        batch.minimum_alpha = 0.5f;
        batch.blend.enabled = false;
        REQUIRE(alpha_renderer->draw(batch, &error));

        auto faded_bytes = bytes;
        std::memcpy(faded_bytes.data() + position_offset,
                    upper_positions, sizeof(upper_positions));
        std::uint8_t faded_colors[3][4] = {
            {255, 32, 16, 128}, {255, 32, 16, 128}, {255, 32, 16, 128},
        };
        std::memcpy(faded_bytes.data() + color_offset,
                    faded_colors, sizeof(faded_colors));
        buffer_descriptor.length = faded_bytes.size();
        buffer_descriptor.label = "Alchemy alpha-mask multiply SoA";
        auto faded_buffer = ALMetalBuffer::create(
            *device, buffer_descriptor, &error);
        INFO(error);
        REQUIRE(faded_buffer);
        REQUIRE(faded_buffer->write(
            0, faded_bytes.data(), faded_bytes.size(), &error));

        batch.vertices = faded_buffer.get();
        batch.blend.enabled = true;
        batch.blend.source_rgb = ALMetalBlendFactor::destination_alpha;
        batch.blend.destination_rgb = ALMetalBlendFactor::zero;
        batch.blend.source_alpha = ALMetalBlendFactor::destination_alpha;
        batch.blend.destination_alpha = ALMetalBlendFactor::zero;
        batch.blend.write_mask = ALMetalColorWriteMask::alpha;
        REQUIRE(alpha_renderer->draw(batch, &error));
        REQUIRE(alpha_renderer->endFrame(&error));
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        alpha_output = alpha_renderer->outputTexture();
        REQUIRE(alpha_output);
        pixels.fill(0);
        REQUIRE(alpha_output->readback(
            *device, 0, 0, {}, pixels.data(), 32 * 4, &error));
        INFO(error);
        const std::size_t gl_upper_row = (26 * 32 + 16) * 4;
        const std::size_t gl_lower_row = (4 * 32 + 16) * 4;
        CHECK(pixels[gl_upper_row + 0] == 255);
        CHECK(pixels[gl_upper_row + 1] == 32);
        CHECK(pixels[gl_upper_row + 2] == 16);
        CHECK(pixels[gl_upper_row + 3] == 128);
        CHECK(pixels[gl_lower_row + 0] == 0);
        CHECK(pixels[gl_lower_row + 1] == 0);
        CHECK(pixels[gl_lower_row + 2] == 0);
        CHECK(pixels[gl_lower_row + 3] == 0);
    }
}

TEST_CASE("almetal: selection contour consumes ids and resumes the ordered UI target", "[almetal]")
{
    @autoreleasepool
    {
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);
        auto scheduler = ALMetalFrameScheduler::create(*device, 3, &error);
        INFO(error);
        REQUIRE(scheduler);
        auto renderer = ALMetalUIRenderer::create(*device, *scheduler, &error);
        INFO(error);
        REQUIRE(renderer);

        constexpr std::uint32_t width = 48;
        constexpr std::uint32_t height = 24;
        // Infinite reverse-Z perspective with near 1. The retained depth is
        // the z=-3 plane; the left and rigged triangles are at z=-2 and
        // visible, while the right triangle at z=-5 is hidden. This is the
        // production convention rather than the transitional forward path.
        constexpr float projection_a = 0.f;
        constexpr float projection_b = 1.f;
        const float projection[16] = {
            1.f, 0.f, 0.f, 0.f,
            0.f, 1.f, 0.f, 0.f,
            0.f, 0.f, projection_a, -1.f,
            0.f, 0.f, projection_b, 0.f,
        };
        const float inverse_projection[16] = {
            1.f, 0.f, 0.f, 0.f,
            0.f, 1.f, 0.f, 0.f,
            0.f, 0.f, 0.f, 1.f / projection_b,
            0.f, 0.f, -1.f, projection_a / projection_b,
        };
        const float positions[9][4] = {
            {-1.8f, -1.4f, -2.f, 1.f},
            {-0.6f, -1.4f, -2.f, 1.f},
            {-1.2f,  1.4f, -2.f, 1.f},
            {-0.4f, -1.4f, -2.f, 1.f},
            { 0.4f, -1.4f, -2.f, 1.f},
            { 0.0f,  1.4f, -2.f, 1.f},
            { 1.5f, -3.5f, -5.f, 1.f},
            { 4.5f, -3.5f, -5.f, 1.f},
            { 3.0f,  3.5f, -5.f, 1.f},
        };
        const float texcoords[9][2] = {
            {0.f, 0.f}, {0.f, 0.f}, {0.f, 0.f},
            {0.f, 0.f}, {0.f, 0.f}, {0.f, 0.f},
            {0.f, 0.f}, {0.f, 0.f}, {0.f, 0.f},
        };
        const float weights[9][4] = {
            {0.5f, 0.f, 0.f, 0.f}, {0.5f, 0.f, 0.f, 0.f},
            {0.5f, 0.f, 0.f, 0.f}, {0.5f, 0.f, 0.f, 0.f},
            {0.5f, 0.f, 0.f, 0.f}, {0.5f, 0.f, 0.f, 0.f},
            {0.5f, 0.f, 0.f, 0.f}, {0.5f, 0.f, 0.f, 0.f},
            {0.5f, 0.f, 0.f, 0.f},
        };
        const std::uint8_t colors[9][4] = {
            {100, 50, 25, 255}, {100, 50, 25, 255},
            {100, 50, 25, 255}, {100, 50, 25, 255},
            {100, 50, 25, 255}, {100, 50, 25, 255},
            {100, 50, 25, 255}, {100, 50, 25, 255},
            {100, 50, 25, 255},
        };
        constexpr std::size_t position_offset = 0;
        constexpr std::size_t texcoord_offset =
            position_offset + sizeof(positions);
        constexpr std::size_t weight_offset =
            (texcoord_offset + sizeof(texcoords) + 15u) & ~std::size_t(15u);
        constexpr std::size_t color_offset =
            weight_offset + sizeof(weights);
        std::array<std::uint8_t, color_offset + sizeof(colors)> bytes{};
        std::memcpy(bytes.data() + position_offset, positions,
                    sizeof(positions));
        std::memcpy(bytes.data() + texcoord_offset, texcoords,
                    sizeof(texcoords));
        std::memcpy(bytes.data() + weight_offset, weights,
                    sizeof(weights));
        std::memcpy(bytes.data() + color_offset, colors, sizeof(colors));

        ALMetalBufferDescriptor vertex_descriptor;
        vertex_descriptor.length = bytes.size();
        vertex_descriptor.storage = ALMetalStorageMode::shared;
        vertex_descriptor.label = "Alchemy selection id test vertices";
        auto vertices = ALMetalBuffer::create(
            *device, vertex_descriptor, &error);
        INFO(error);
        REQUIRE(vertices);
        REQUIRE(vertices->write(0, bytes.data(), bytes.size(), &error));
        const std::array<std::uint16_t, 9> index_values = {
            0, 1, 2, 3, 4, 5, 6, 7, 8};
        ALMetalBufferDescriptor index_descriptor;
        index_descriptor.length = sizeof(index_values);
        index_descriptor.storage = ALMetalStorageMode::shared;
        index_descriptor.label = "Alchemy selection id test indices";
        auto indices = ALMetalBuffer::create(
            *device, index_descriptor, &error);
        INFO(error);
        REQUIRE(indices);
        REQUIRE(indices->write(
            0, index_values.data(), sizeof(index_values), &error));

        ALMetalTextureDescriptor background_descriptor;
        background_descriptor.format = ALMetalPixelFormat::bgra8_unorm;
        background_descriptor.width = width;
        background_descriptor.height = height;
        background_descriptor.storage = ALMetalStorageMode::private_gpu;
        background_descriptor.usage = ALMetalTextureUsage::shader_read;
        background_descriptor.label = "Alchemy selection ordered background";
        auto background = ALMetalTexture::create(
            *device, background_descriptor, &error);
        INFO(error);
        REQUIRE(background);
        std::array<std::uint8_t, width * height * 4> background_pixels{};
        for (std::size_t pixel = 0; pixel < width * height; ++pixel)
        {
            background_pixels[pixel * 4 + 0] = 7;
            background_pixels[pixel * 4 + 1] = 11;
            background_pixels[pixel * 4 + 2] = 13;
            background_pixels[pixel * 4 + 3] = 255;
        }
        auto background_upload = device->makeCommandBuffer(
            "Alchemy selection ordered background upload", &error);
        INFO(error);
        REQUIRE(background_upload);
        REQUIRE(background->upload(
            *background_upload, 0, 0, {}, background_pixels.data(),
            width * 4, &error));
        REQUIRE(background_upload->commitAndWait(&error));

        ALMetalTextureDescriptor alpha_descriptor;
        alpha_descriptor.format = ALMetalPixelFormat::rgba8_unorm;
        alpha_descriptor.width = 1;
        alpha_descriptor.height = 1;
        alpha_descriptor.storage = ALMetalStorageMode::private_gpu;
        alpha_descriptor.usage = ALMetalTextureUsage::shader_read;
        alpha_descriptor.label = "Alchemy transparent selection alpha";
        auto transparent = ALMetalTexture::create(
            *device, alpha_descriptor, &error);
        INFO(error);
        REQUIRE(transparent);
        auto alpha_upload = device->makeCommandBuffer(
            "Alchemy transparent selection alpha upload", &error);
        REQUIRE(alpha_upload);
        const std::array<std::uint8_t, 4> transparent_texel = {
            255, 255, 255, 0};
        REQUIRE(transparent->upload(
            *alpha_upload, 0, 0, {}, transparent_texel.data(), 4, &error));
        REQUIRE(alpha_upload->commitAndWait(&error));

        ALMetalRenderTargetDescriptor depth_descriptor;
        depth_descriptor.width = width;
        depth_descriptor.height = height;
        depth_descriptor.color_attachment_count = 0;
        depth_descriptor.depth_stencil_format =
            ALMetalPixelFormat::depth32_float_stencil8;
        depth_descriptor.depth_stencil_shader_read = true;
        depth_descriptor.label = "Alchemy selection retained scene depth";
        auto depth = ALMetalRenderTarget::create(
            *device, depth_descriptor, &error);
        INFO(error);
        REQUIRE(depth);
        ALMetalRenderPassConfig depth_clear;
        depth_clear.depth_load = ALMetalLoadAction::clear;
        depth_clear.depth_store = ALMetalStoreAction::store;
        depth_clear.clear_depth = 1.f / 3.f;
        depth_clear.stencil_load = ALMetalLoadAction::clear;
        depth_clear.stencil_store = ALMetalStoreAction::store;
        auto depth_pass = depth->makeRenderPass(depth_clear, &error);
        INFO(error);
        REQUIRE(depth_pass);
        auto depth_command = device->makeCommandBuffer(
            "Alchemy selection retained depth seed", &error);
        REQUIRE(depth_command);
        auto depth_encoder = ALMetalRenderEncoder::begin(
            *depth_command, *depth_pass,
            "Alchemy selection retained depth seed", &error);
        REQUIRE(depth_encoder);
        REQUIRE(depth_encoder->end(&error));
        REQUIRE(depth_command->commitAndWait(&error));

        std::array<float, 16> skin_palette{};
        skin_palette[4] = 1.f;
        skin_palette[9] = 1.f;
        skin_palette[14] = 1.f;
        std::array<ALMetalSelectionIDBatch, 4> batches{};
        for (ALMetalSelectionIDBatch& batch : batches)
        {
            batch.vertices = vertices.get();
            batch.position_offset = position_offset;
            batch.texcoord_offset = texcoord_offset;
            batch.vertex_count = 9;
            batch.indices = indices.get();
            batch.index_count = 3;
            batch.sampler.min_filter = ALMetalSamplerFilter::nearest;
            batch.sampler.mag_filter = ALMetalSamplerFilter::nearest;
            batch.sampler.mip_filter = ALMetalSamplerMipFilter::none;
            batch.sampler.address_s =
                ALMetalSamplerAddressMode::clamp_to_edge;
            batch.sampler.address_t =
                ALMetalSamplerAddressMode::clamp_to_edge;
            batch.sampler.address_r =
                ALMetalSamplerAddressMode::clamp_to_edge;
            std::memcpy(batch.modelview_projection, projection,
                        sizeof(projection));
        }
        batches[0].id = 0x1234;
        batches[0].priority = 2;
        batches[1].index_offset = 3 * sizeof(std::uint16_t);
        batches[1].id = 0x00aa;
        batches[1].priority = 3;
        batches[1].weight_offset = weight_offset;
        batches[1].skin_palette = skin_palette.data();
        batches[1].skin_palette_float_count = skin_palette.size();
        batches[1].skin_joint_count = 1;
        batches[2].index_offset = 6 * sizeof(std::uint16_t);
        batches[2].id = 0x0201;
        batches[2].priority = 4;
        batches[2].show_hidden = true;
        // Draw the transparent alpha-tested face last over the rigged one. A
        // failed discard would replace id 0x00aa with this id.
        batches[3].index_offset = 3 * sizeof(std::uint16_t);
        batches[3].id = 0x00dd;
        batches[3].priority = 5;
        batches[3].texture = transparent.get();
        batches[3].alpha_cutoff = 0.5f;

        ALMetalSelectionIDScene scene;
        scene.batches = batches.data();
        scene.batch_count = batches.size();
        std::memcpy(scene.inverse_projection, inverse_projection,
                    sizeof(inverse_projection));
        scene.width = width;
        scene.height = height;
        scene.reverse_z = true;
        scene.use_scene_depth = true;

        REQUIRE(renderer->setFrameBackground(background.get(), &error));
        REQUIRE(renderer->setFrameDepth(
            depth->depthStencilTexture(), &error));
        const bool selection_encoded =
            renderer->drawSelectionIDs(scene, &error);
        INFO(error);
        REQUIRE(selection_encoded);
        REQUIRE(renderer->selectionIDTexture());
        REQUIRE(renderer->selectionDepthTexture());

        constexpr std::uint32_t palette_width = 256;
        constexpr std::uint32_t palette_height = 38;
        std::array<std::uint8_t,
                   palette_width * palette_height * 4> palette{};
        const auto set_palette = [&](std::uint32_t id, bool visible,
                                     std::array<std::uint8_t, 4> color)
        {
            const std::uint32_t row =
                (id / palette_width) * 2u + (visible ? 0u : 1u);
            const std::size_t offset =
                (static_cast<std::size_t>(row) * palette_width +
                 id % palette_width) * 4u;
            std::copy(color.begin(), color.end(), palette.begin() + offset);
        };
        set_palette(0x1234, true, {255, 0, 0, 255});
        set_palette(0x00aa, true, {0, 255, 0, 255});
        set_palette(0x0201, true, {0, 0, 255, 255});
        set_palette(0x0201, false, {0, 0, 255, 128});

        ALMetalSelectionContourScene contour;
        contour.palette_rgba8 = palette.data();
        contour.palette_bytes = palette.size();
        contour.palette_width = palette_width;
        contour.palette_height = palette_height;
        std::memcpy(contour.inverse_projection, inverse_projection,
                    sizeof(inverse_projection));
        contour.width = width;
        contour.height = height;
        contour.outline_width = 2;
        contour.inner_width = 1;
        contour.rim_width = 1;
        contour.reverse_z = true;
        ALMetalSelectionContourScene invalid_contour = contour;
        --invalid_contour.palette_bytes;
        CHECK_FALSE(renderer->drawSelectionContour(
            invalid_contour, &error));
        CHECK(error == "Metal selection contour inputs are invalid");
        invalid_contour = contour;
        invalid_contour.glow_radius = 4;
        invalid_contour.glow_brightness = 65.f;
        CHECK_FALSE(renderer->drawSelectionContour(
            invalid_contour, &error));
        CHECK(error == "Metal selection contour inputs are invalid");
        REQUIRE(renderer->drawSelectionContour(contour, &error));

        // A normal UI draw after the private pass proves the main target was
        // resumed with load rather than cleared or submitted separately.
        ALMetalUIBatch ui;
        ui.vertices = vertices.get();
        ui.position_offset = position_offset;
        ui.texcoord_offset = texcoord_offset;
        ui.color_offset = color_offset;
        ui.shader = ALMetalUIShader::vertex_color;
        ui.texture = nullptr;
        ui.sampler = batches[0].sampler;
        ui.blend.enabled = false;
        ui.vertex_count = 3;
        ui.target_width = width;
        ui.target_height = height;
        ui.viewport = {0.0, 0.0, static_cast<double>(width),
                       static_cast<double>(height), 0.0, 1.0};
        ui.scissor = {0, 0, width, height};
        std::memcpy(ui.matrices.modelview_projection, projection,
                    sizeof(projection));
        REQUIRE(renderer->draw(ui, &error));
        REQUIRE(renderer->endFrame(&error));
        INFO(error);
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);

        std::array<std::uint8_t, width * height * 4> ids{};
        REQUIRE(renderer->selectionIDTexture()->readback(
            *device, 0, 0, {}, ids.data(), width * 4, &error));
        INFO(error);
        const auto id_pixel = [&](std::uint32_t x, std::uint32_t y)
        {
            return &ids[(static_cast<std::size_t>(y) * width + x) * 4];
        };
        const std::uint8_t* visible = id_pixel(10, 12);
        CHECK(visible[0] == 0x34);
        CHECK(visible[1] == 0x12);
        CHECK(visible[2] == 255);
        CHECK(visible[3] == 2);
        const std::uint8_t* rigged = id_pixel(24, 12);
        CHECK(rigged[0] == 0xaa);
        CHECK(rigged[1] == 0x00);
        CHECK(rigged[2] == 255);
        CHECK(rigged[3] == 3);
        const std::uint8_t* hidden = id_pixel(38, 12);
        CHECK(hidden[0] == 0x01);
        CHECK(hidden[1] == 0x02);
        CHECK(hidden[2] == 128);
        CHECK(hidden[3] == 4);
        const std::uint8_t* empty = id_pixel(0, 0);
        CHECK(empty[0] == 0);
        CHECK(empty[1] == 0);
        CHECK(empty[2] == 0);
        CHECK(empty[3] == 0);

        std::array<std::uint8_t, width * height * 4> composed{};
        REQUIRE(renderer->outputTexture()->readback(
            *device, 0, 0, {}, composed.data(), width * 4, &error));
        INFO(error);
        const std::size_t ui_pixel = (12 * width + 10) * 4;
        CHECK(composed[ui_pixel + 0] == 25);
        CHECK(composed[ui_pixel + 1] == 50);
        CHECK(composed[ui_pixel + 2] == 100);
        CHECK(composed[ui_pixel + 3] == 255);
        CHECK(composed[0] == 7);
        CHECK(composed[1] == 11);
        CHECK(composed[2] == 13);
        CHECK(composed[3] == 255);

        std::size_t green_contour_pixels = 0;
        std::size_t hidden_blue_pixels = 0;
        for (std::uint32_t y = 0; y < height; ++y)
        {
            for (std::uint32_t x = 16; x < width; ++x)
            {
                const std::size_t pixel =
                    (static_cast<std::size_t>(y) * width + x) * 4u;
                CHECK(composed[pixel + 3] == 255);
                if (x < 32 && composed[pixel + 1] > 200 &&
                    composed[pixel + 1] > composed[pixel + 0] + 80 &&
                    composed[pixel + 1] > composed[pixel + 2] + 80)
                {
                    ++green_contour_pixels;
                }
                if (x >= 32 && composed[pixel + 0] > 80 &&
                    composed[pixel + 0] > composed[pixel + 1] + 40 &&
                    composed[pixel + 0] > composed[pixel + 2] + 40)
                {
                    ++hidden_blue_pixels;
                }
            }
        }
        CHECK(green_contour_pixels > 0);
        CHECK(hidden_blue_pixels > 0);

        const ALMetalUIRendererStats stats = renderer->stats();
        CHECK(stats.frames == 1);
        CHECK(stats.batches == 8);
        CHECK(stats.vertices == 24);
        CHECK(stats.pipeline_states == 6);
        CHECK(stats.sampler_states == 1);

        // A second, hover-only transaction proves both glow acceleration
        // passes and the optimized row search. The glow must surround the
        // selected surface without painting over that surface itself.
        auto first_output = renderer->takeOutputTexture();
        REQUIRE(first_output);
        batches[0].priority = 6;
        scene.batch_count = 1;
        REQUIRE(renderer->setFrameBackground(background.get(), &error));
        REQUIRE(renderer->setFrameDepth(
            depth->depthStencilTexture(), &error));
        REQUIRE(renderer->drawSelectionIDs(scene, &error));
        contour.contour_enabled = false;
        contour.rim_width = 0;
        contour.glow_radius = 4;
        contour.glow_brightness = 4.f;
        REQUIRE(renderer->drawSelectionContour(contour, &error));
        REQUIRE(renderer->endFrame(&error));
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);

        std::array<std::uint8_t, width * height * 4> glow_ids{};
        REQUIRE(renderer->selectionIDTexture()->readback(
            *device, 0, 0, {}, glow_ids.data(), width * 4, &error));
        std::array<std::uint8_t, width * height * 4> glow_output{};
        REQUIRE(renderer->outputTexture()->readback(
            *device, 0, 0, {}, glow_output.data(), width * 4, &error));
        INFO(error);
        std::size_t halo_pixels = 0;
        std::size_t own_surface_pixels = 0;
        for (std::size_t pixel = 0; pixel < width * height; ++pixel)
        {
            const std::size_t offset = pixel * 4u;
            const std::uint32_t id =
                static_cast<std::uint32_t>(glow_ids[offset + 0]) |
                (static_cast<std::uint32_t>(glow_ids[offset + 1]) << 8u);
            CHECK(glow_output[offset + 3] == 255);
            if (id != 0u)
            {
                ++own_surface_pixels;
                CHECK(glow_output[offset + 0] == 7);
                CHECK(glow_output[offset + 1] == 11);
                CHECK(glow_output[offset + 2] == 13);
            }
            else if (glow_output[offset + 2] > 32 &&
                     glow_output[offset + 2] > glow_output[offset + 0] + 16 &&
                     glow_output[offset + 2] > glow_output[offset + 1] + 16)
            {
                ++halo_pixels;
            }
        }
        CHECK(own_surface_pixels > 0);
        CHECK(halo_pixels > 0);
        CHECK(glow_output[0] == 7);
        CHECK(glow_output[1] == 11);
        CHECK(glow_output[2] == 13);

        const ALMetalUIRendererStats glow_stats = renderer->stats();
        CHECK(glow_stats.frames == 2);
        CHECK(glow_stats.batches == 14);
        CHECK(glow_stats.vertices == 42);
        CHECK(glow_stats.pipeline_states == 8);
        CHECK(glow_stats.sampler_states == 1);

        // A third transaction draws the selected surface into the current
        // ordered target before the ID pass. The half-resolution backdrop
        // must exclude that surface and shift a same-grey contour away from
        // the surrounding grey while leaving both surface and far backdrop.
        for (std::size_t pixel = 0; pixel < width * height; ++pixel)
        {
            background_pixels[pixel * 4 + 0] = 128;
            background_pixels[pixel * 4 + 1] = 128;
            background_pixels[pixel * 4 + 2] = 128;
            background_pixels[pixel * 4 + 3] = 255;
        }
        auto contrast_upload = device->makeCommandBuffer(
            "Alchemy selection contrast background upload", &error);
        REQUIRE(contrast_upload);
        REQUIRE(background->upload(
            *contrast_upload, 0, 0, {}, background_pixels.data(),
            width * 4, &error));
        REQUIRE(contrast_upload->commitAndWait(&error));
        set_palette(0x1234, true, {128, 128, 128, 255});

        REQUIRE(renderer->setFrameBackground(background.get(), &error));
        REQUIRE(renderer->setFrameDepth(
            depth->depthStencilTexture(), &error));
        ALMetalUIBatch selected_surface = ui;
        selected_surface.shader = ALMetalUIShader::solid_color;
        selected_surface.texture = background.get();
        selected_surface.solid_color[0] = 1.f;
        selected_surface.solid_color[1] = 1.f;
        selected_surface.solid_color[2] = 1.f;
        selected_surface.solid_color[3] = 1.f;
        error.clear();
        const bool selected_surface_drawn =
            renderer->draw(selected_surface, &error);
        INFO(error);
        REQUIRE(selected_surface_drawn);
        batches[0].priority = 2;
        REQUIRE(renderer->drawSelectionIDs(scene, &error));
        contour.contour_enabled = true;
        contour.contrast_shift = true;
        contour.glow_radius = 0;
        contour.glow_brightness = 0.f;
        REQUIRE(renderer->drawSelectionContour(contour, &error));
        REQUIRE(renderer->endFrame(&error));
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);

        std::array<std::uint8_t, width * height * 4> contrast_output{};
        REQUIRE(renderer->outputTexture()->readback(
            *device, 0, 0, {}, contrast_output.data(), width * 4, &error));
        INFO(error);
        std::size_t shifted_pixels = 0;
        for (std::size_t pixel = 0; pixel < width * height; ++pixel)
        {
            const std::size_t offset = pixel * 4u;
            CHECK(contrast_output[offset + 3] == 255);
            if (contrast_output[offset + 0] < 32 &&
                contrast_output[offset + 1] < 32 &&
                contrast_output[offset + 2] < 32)
            {
                ++shifted_pixels;
            }
        }
        CHECK(shifted_pixels > 0);
        CHECK(contrast_output[0] == 128);
        CHECK(contrast_output[1] == 128);
        CHECK(contrast_output[2] == 128);
        CHECK(contrast_output[ui_pixel + 0] == 255);
        CHECK(contrast_output[ui_pixel + 1] == 255);
        CHECK(contrast_output[ui_pixel + 2] == 255);

        const ALMetalUIRendererStats contrast_stats = renderer->stats();
        CHECK(contrast_stats.frames == 3);
        CHECK(contrast_stats.batches == 20);
        CHECK(contrast_stats.vertices == 60);
        CHECK(contrast_stats.pipeline_states == 10);
        CHECK(contrast_stats.sampler_states == 1);

        // A fourth transaction exercises the native indexed wire expansion:
        // static and skinned visible lines, a hidden line through the reverse
        // depth pass, and an alpha-tested batch that must leave the prior
        // green line untouched. No jump/tile/contour work is encoded for this
        // wire-only frame.
        set_palette(0x1234, true, {255, 0, 0, 255});
        set_palette(0x00aa, true, {0, 255, 0, 255});
        set_palette(0x00dd, true, {255, 0, 255, 255});
        scene.batch_count = batches.size();
        REQUIRE(renderer->setFrameBackground(background.get(), &error));
        REQUIRE(renderer->setFrameDepth(
            depth->depthStencilTexture(), &error));
        REQUIRE(renderer->drawSelectionIDs(scene, &error));
        contour.contour_enabled = false;
        contour.contrast_shift = false;
        contour.wire_batches = batches.data();
        contour.wire_batch_count = batches.size();
        contour.wire_width = 2;
        contour.wire_depth_slope = 2.f;
        contour.wire_depth_units = 4.f;
        contour.wire_hud = false;
        ALMetalSelectionContourScene invalid_wire = contour;
        invalid_wire.wire_width = 0;
        CHECK_FALSE(renderer->drawSelectionContour(invalid_wire, &error));
        CHECK(error == "Metal selection contour inputs are invalid");
        error.clear();
        REQUIRE(renderer->drawSelectionContour(contour, &error));
        REQUIRE(renderer->endFrame(&error));
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);

        std::array<std::uint8_t, width * height * 4> wire_output{};
        REQUIRE(renderer->outputTexture()->readback(
            *device, 0, 0, {}, wire_output.data(), width * 4, &error));
        INFO(error);
        std::size_t red_wire_pixels = 0;
        std::size_t green_wire_pixels = 0;
        std::size_t hidden_blue_wire_pixels = 0;
        std::size_t magenta_wire_pixels = 0;
        for (std::uint32_t y = 0; y < height; ++y)
        {
            for (std::uint32_t x = 0; x < width; ++x)
            {
                const std::size_t pixel =
                    (static_cast<std::size_t>(y) * width + x) * 4u;
                CHECK(wire_output[pixel + 3] == 255);
                if (x < 16 && wire_output[pixel + 2] > 200 &&
                    wire_output[pixel + 2] > wire_output[pixel + 1] + 80 &&
                    wire_output[pixel + 2] > wire_output[pixel + 0] + 80)
                {
                    ++red_wire_pixels;
                }
                if (x >= 16 && x < 32 && wire_output[pixel + 1] > 200 &&
                    wire_output[pixel + 1] > wire_output[pixel + 2] + 80 &&
                    wire_output[pixel + 1] > wire_output[pixel + 0] + 80)
                {
                    ++green_wire_pixels;
                }
                if (x >= 32 && wire_output[pixel + 0] > 150 &&
                    wire_output[pixel + 0] > wire_output[pixel + 1] + 40 &&
                    wire_output[pixel + 0] > wire_output[pixel + 2] + 40)
                {
                    ++hidden_blue_wire_pixels;
                }
                if (wire_output[pixel + 0] > 180 &&
                    wire_output[pixel + 2] > 180 &&
                    wire_output[pixel + 1] < 100)
                {
                    ++magenta_wire_pixels;
                }
            }
        }
        CHECK(red_wire_pixels > 0);
        CHECK(green_wire_pixels > 0);
        CHECK(hidden_blue_wire_pixels > 0);
        CHECK(magenta_wire_pixels == 0);
        CHECK(wire_output[0] == 128);
        CHECK(wire_output[1] == 128);
        CHECK(wire_output[2] == 128);

        const ALMetalUIRendererStats wire_stats = renderer->stats();
        CHECK(wire_stats.frames == 4);
        CHECK(wire_stats.batches == 29);
        CHECK(wire_stats.vertices == 102);
        CHECK(wire_stats.pipeline_states == 14);
        CHECK(wire_stats.sampler_states == 1);

        // Finally force the skinned U32 path through a triangle whose top
        // corner is behind the near plane. Its clipped polygon is a quad, but
        // the centre of the new near-plane edge must stay background: only
        // the source triangle's three edges are lines.
        const float clipped_z = -0.5f;
        REQUIRE(vertices->write(
            position_offset + 5u * sizeof(positions[0]) +
                2u * sizeof(float),
            &clipped_z, sizeof(clipped_z), &error));
        const std::array<std::uint32_t, 3> u32_indices = {3u, 4u, 5u};
        ALMetalBufferDescriptor u32_index_descriptor;
        u32_index_descriptor.length = sizeof(u32_indices);
        u32_index_descriptor.storage = ALMetalStorageMode::shared;
        u32_index_descriptor.label =
            "Alchemy clipped selection wire U32 indices";
        auto u32_index_buffer = ALMetalBuffer::create(
            *device, u32_index_descriptor, &error);
        REQUIRE(u32_index_buffer);
        REQUIRE(u32_index_buffer->write(
            0, u32_indices.data(), sizeof(u32_indices), &error));
        ALMetalSelectionIDBatch clipped_batch = batches[1];
        clipped_batch.indices = u32_index_buffer.get();
        clipped_batch.index_offset = 0;
        clipped_batch.index_type = ALMetalIndexType::uint32;
        scene.batches = &clipped_batch;
        scene.batch_count = 1;
        REQUIRE(renderer->setFrameBackground(background.get(), &error));
        REQUIRE(renderer->setFrameDepth(
            depth->depthStencilTexture(), &error));
        REQUIRE(renderer->drawSelectionIDs(scene, &error));
        contour.wire_batches = &clipped_batch;
        contour.wire_batch_count = 1;
        REQUIRE(renderer->drawSelectionContour(contour, &error));
        REQUIRE(renderer->endFrame(&error));
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);

        std::array<std::uint8_t, width * height * 4> clipped_output{};
        REQUIRE(renderer->outputTexture()->readback(
            *device, 0, 0, {}, clipped_output.data(), width * 4, &error));
        INFO(error);
        std::size_t clipped_green_pixels = 0;
        for (std::size_t pixel = 0; pixel < width * height; ++pixel)
        {
            const std::size_t offset = pixel * 4u;
            if (clipped_output[offset + 1] > 200 &&
                clipped_output[offset + 1] > clipped_output[offset + 0] + 80 &&
                clipped_output[offset + 1] > clipped_output[offset + 2] + 80)
            {
                ++clipped_green_pixels;
            }
        }
        CHECK(clipped_green_pixels > 0);
        const std::size_t false_cap_pixel = (6u * width + 24u) * 4u;
        CHECK(clipped_output[false_cap_pixel + 0] == 128);
        CHECK(clipped_output[false_cap_pixel + 1] == 128);
        CHECK(clipped_output[false_cap_pixel + 2] == 128);
        CHECK(clipped_output[false_cap_pixel + 3] == 255);

        const ALMetalUIRendererStats clipped_stats = renderer->stats();
        CHECK(clipped_stats.frames == 5);
        CHECK(clipped_stats.batches == 31);
        CHECK(clipped_stats.vertices == 111);
        CHECK(clipped_stats.pipeline_states == 14);
        CHECK(clipped_stats.sampler_states == 1);

        // HUD wireframes cannot read the window depth. Prove that a farther
        // copy of the same projected triangle selects its hidden palette row
        // against the private nearest-selected depth instead.
        set_palette(0x1234, false, {255, 255, 0, 255});
        ALMetalSelectionIDBatch hud_near = batches[0];
        ALMetalSelectionIDBatch hud_far = batches[0];
        hud_far.modelview_projection[0] *= 2.5f;
        hud_far.modelview_projection[5] *= 2.5f;
        hud_far.modelview_projection[11] *= 2.5f;
        scene.batches = &hud_near;
        scene.batch_count = 1;
        scene.use_scene_depth = false;
        REQUIRE(renderer->setFrameBackground(background.get(), &error));
        REQUIRE(renderer->setFrameDepth(
            depth->depthStencilTexture(), &error));
        REQUIRE(renderer->drawSelectionIDs(scene, &error));
        contour.wire_batches = &hud_far;
        contour.wire_batch_count = 1;
        contour.wire_hud = true;
        REQUIRE(renderer->drawSelectionContour(contour, &error));
        REQUIRE(renderer->endFrame(&error));
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);

        std::array<std::uint8_t, width * height * 4> hud_wire_output{};
        REQUIRE(renderer->outputTexture()->readback(
            *device, 0, 0, {}, hud_wire_output.data(), width * 4, &error));
        INFO(error);
        std::size_t hidden_yellow_pixels = 0;
        for (std::size_t pixel = 0; pixel < width * height; ++pixel)
        {
            const std::size_t offset = pixel * 4u;
            if (hud_wire_output[offset + 0] < 40 &&
                hud_wire_output[offset + 1] > 200 &&
                hud_wire_output[offset + 2] > 200)
            {
                ++hidden_yellow_pixels;
            }
        }
        CHECK(hidden_yellow_pixels > 0);

        const ALMetalUIRendererStats hud_wire_stats = renderer->stats();
        CHECK(hud_wire_stats.frames == 6);
        CHECK(hud_wire_stats.batches == 33);
        CHECK(hud_wire_stats.vertices == 120);
        CHECK(hud_wire_stats.pipeline_states == 14);
        CHECK(hud_wire_stats.sampler_states == 1);
    }
}

TEST_CASE("almetal: a CAMetalLayer overlay coexists with an SDL OpenGL window", "[almetal]")
{
    @autoreleasepool
    {
        SDLVideoScope video;
        std::string error;
        auto device = ALMetalDevice::create(&error);
        INFO(error);
        REQUIRE(device);

        SDL_PropertiesID properties = SDL_CreateProperties();
        REQUIRE(properties != 0);
        SDL_SetStringProperty(properties, SDL_PROP_WINDOW_CREATE_TITLE_STRING, "Alchemy Metal surface test");
        SDL_SetNumberProperty(properties, SDL_PROP_WINDOW_CREATE_WIDTH_NUMBER, 64);
        SDL_SetNumberProperty(properties, SDL_PROP_WINDOW_CREATE_HEIGHT_NUMBER, 48);
        SDL_SetBooleanProperty(properties, SDL_PROP_WINDOW_CREATE_OPENGL_BOOLEAN, true);
        SDL_SetBooleanProperty(properties, SDL_PROP_WINDOW_CREATE_HIDDEN_BOOLEAN, true);
        std::unique_ptr<SDL_Window, SDLWindowDeleter> window(SDL_CreateWindowWithProperties(properties));
        SDL_DestroyProperties(properties);
        INFO(SDL_GetError());
        REQUIRE(window);
        CHECK((SDL_GetWindowFlags(window.get()) & SDL_WINDOW_OPENGL) != 0);
        CHECK((SDL_GetWindowFlags(window.get()) & SDL_WINDOW_METAL) == 0);

        auto surface = ALMetalSurface::create(window.get(), *device, {}, &error);
        INFO(error);
        REQUIRE(surface);
        CHECK((SDL_GetWindowFlags(window.get()) & SDL_WINDOW_OPENGL) != 0);
        CHECK((SDL_GetWindowFlags(window.get()) & SDL_WINDOW_METAL) == 0);
        CHECK(surface->nativeLayer() != nullptr);
        CHECK(surface->info().width >= 64);
        CHECK(surface->info().height >= 48);
        CHECK(surface->info().maximum_drawable_count == 3);
        CHECK(surface->info().opaque);
        REQUIRE(surface->setOpaque(false, &error));
        CHECK_FALSE(surface->info().opaque);
        REQUIRE(surface->setOpaque(true, &error));
        CHECK(surface->info().opaque);
        const std::uint64_t original_generation = surface->info().generation;
        REQUIRE(surface->resize(80, 52, &error));
        CHECK(surface->info().width == 80);
        CHECK(surface->info().height == 52);
        CHECK(surface->info().generation == original_generation + 1);

        auto drawable = surface->nextDrawable(&error);
        if (!drawable)
        {
            // Some WindowServer versions withhold drawable allocation from a
            // hidden view. Briefly showing the tiny test window is still the
            // real SDL/CAMetalLayer path and avoids treating that policy as a
            // backend failure.
            REQUIRE(SDL_ShowWindow(window.get()));
            REQUIRE(SDL_SyncWindow(window.get()));
            drawable = surface->nextDrawable(&error);
        }
        INFO(error);
        REQUIRE(drawable);
        CHECK(drawable->width() == 80);
        CHECK(drawable->height() == 52);
        CHECK(drawable->generation() == surface->info().generation);

        auto command = device->makeCommandBuffer("Alchemy Metal drawable test", &error);
        INFO(error);
        REQUIRE(command);
        ALMetalRenderPassColorConfig pass_config;
        pass_config.clear = {0.02, 0.04, 0.08, 1.0};
        auto pass = ALMetalRenderPass::createForColorAttachment(
            *device, drawable->nativeTexture(), ALMetalPixelFormat::bgra8_unorm,
            pass_config, &error);
        INFO(error);
        REQUIRE(pass);
        auto encoder = ALMetalRenderEncoder::begin(
            *command, *pass, "Alchemy Metal drawable clear", &error);
        INFO(error);
        REQUIRE(encoder);
        REQUIRE(encoder->end(&error));

        REQUIRE(surface->present(*command, *drawable, &error));
        CHECK(drawable->wasPresented());
        REQUIRE(command->commit(&error));
        REQUIRE(command->waitUntilCompleted(&error));
        INFO(error);

        // A viewer frame without UI batches must still replace the previous
        // overlay with a transparent drawable; otherwise hiding all UI would
        // leave the last presented controls frozen above the GL world.
        auto scheduler = ALMetalFrameScheduler::create(*device, 3, &error);
        INFO(error);
        REQUIRE(scheduler);
        auto renderer = ALMetalUIRenderer::createForSurface(
            *device, *scheduler, *surface, &error);
        INFO(error);
        REQUIRE(renderer);
        REQUIRE(renderer->endFrame(&error));
        INFO(error);
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);
        const ALMetalUIRendererStats empty_stats = renderer->stats();
        CHECK(empty_stats.frames == 1);
        CHECK(empty_stats.batches == 0);
        CHECK(empty_stats.vertices == 0);
        CHECK(renderer->outputTexture() == nullptr);

        // The integrated world route hands its completed BGRA8 texture to
        // this same surface-backed renderer. Exercise the exact no-additional-
        // UI path and prove that it submits one more drawable frame without
        // requiring an offscreen output texture.
        ALMetalTextureDescriptor world_descriptor;
        world_descriptor.format = ALMetalPixelFormat::bgra8_unorm;
        world_descriptor.width = surface->info().width;
        world_descriptor.height = surface->info().height;
        world_descriptor.storage = ALMetalStorageMode::private_gpu;
        world_descriptor.usage = ALMetalTextureUsage::shader_read;
        world_descriptor.label =
            "Alchemy retained world/UI surface publication source";
        auto world = ALMetalTexture::create(
            *device, world_descriptor, &error);
        INFO(error);
        REQUIRE(world);
        std::vector<std::uint8_t> world_pixels(
            static_cast<std::size_t>(world_descriptor.width) *
            world_descriptor.height * 4u, 0u);
        for (std::size_t pixel = 0; pixel < world_pixels.size() / 4u; ++pixel)
        {
            world_pixels[pixel * 4u + 0u] = 24u;
            world_pixels[pixel * 4u + 1u] = 48u;
            world_pixels[pixel * 4u + 2u] = 96u;
            world_pixels[pixel * 4u + 3u] = 255u;
        }
        auto world_upload = device->makeCommandBuffer(
            "Alchemy retained world/UI surface publication upload", &error);
        INFO(error);
        REQUIRE(world_upload);
        REQUIRE(world->upload(
            *world_upload, 0, 0, {}, world_pixels.data(),
            static_cast<std::size_t>(world_descriptor.width) * 4u, &error));
        REQUIRE(world_upload->commitAndWait(&error));
        INFO(error);
        REQUIRE(renderer->setFrameBackground(world.get(), &error));
        REQUIRE(renderer->endFrame(&error));
        INFO(error);
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);
        const ALMetalUIRendererStats world_stats = renderer->stats();
        CHECK(world_stats.frames == 2);
        CHECK(world_stats.batches == 0);
        CHECK(world_stats.vertices == 0);
        CHECK(renderer->outputTexture() == nullptr);
        renderer.reset();

        // The exact world/UI path is produced offscreen. Finish that retained
        // texture and append its drawable presentation to the same command
        // buffer: both the texture handoff and surface submission must cost
        // exactly one native commit rather than the former pair.
        auto fused_renderer = ALMetalUIRenderer::createForTexture(
            *device, *scheduler, ALMetalPixelFormat::bgra8_unorm, &error);
        INFO(error);
        REQUIRE(fused_renderer);
        REQUIRE(fused_renderer->setFrameBackground(world.get(), &error));
        const std::uint64_t submissions_before_fused =
            ALMetalDevice::committedCommandBufferCount();
        REQUIRE(fused_renderer->endFrameAndPresent(*surface, &error));
        INFO(error);
        CHECK(ALMetalDevice::committedCommandBufferCount() ==
              submissions_before_fused + 1);
        auto fused_output = fused_renderer->takeOutputTexture();
        REQUIRE(fused_output);
        REQUIRE(scheduler->waitUntilIdle(1000, &error));
        INFO(error);
        std::vector<std::uint8_t> fused_pixels(world_pixels.size(), 0u);
        REQUIRE(fused_output->readback(
            *device, 0, 0, {}, fused_pixels.data(),
            static_cast<std::size_t>(world_descriptor.width) * 4u, &error));
        INFO(error);
        CHECK(fused_pixels == world_pixels);
        const ALMetalUIRendererStats fused_stats = fused_renderer->stats();
        CHECK(fused_stats.frames == 1);
        CHECK(fused_stats.batches == 0);
        CHECK(fused_stats.vertices == 0);

        // The Metal view must go away before its SDL window.
        surface.reset();
    }
}
